(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("strabo-geography-1-e", [{"sp": "HDR", "t": "Γεωγραφικά (Αʹ–Γʹ)"}, {"sp": "HDR", "t": "Βιβλίον Αʹ", "st": "1"}, {"sp": "N", "t": "τῆς τοῦ φιλοσόφου πραγματείας εἶναι νομίζομεν, εἴπερ ἄλλην τινά, καὶ τὴν γεωγραφικήν, ἣν νῦν προῃρήμεθα ἐπισκοπεῖν. ὅτι δ’ οὐ φαύλως νομίζομεν ἐκ πολλῶν δῆλον· οἵ τε γὰρ πρῶτοι θαρρήσαντες αὐτῆς ἅψασθαι τοιοῦτοί τινες ὑπῆρξαν, Ὅμηρός τε καὶ Ἀναξίμανδρος ὁ Μιλήσιος καὶ Ἑκαταῖος, ὁ πολίτης αὐτοῦ, καθὼς καὶ Ἐρατοσθένης φησί· καὶ Δημόκριτος δὲ καὶ Εὔδοξος καὶ Δικαίαρχος καὶ Ἔφορος καὶ ἄλλοι πλείους· ἔτι δὲ οἱ μετὰ τούτους, Ἐρατοσθένης τε καὶ Πολύβιος καὶ Ποσειδώνιος, ἄνδρες φιλόσοφοι. ἥ τε πολυμάθεια, δι’ ἧς μόνης ἐφικέσθαι τοῦδε τοῦ ἔργου δυνατόν, οὐκ ἄλλου τινός ἐστιν ἢ τοῦ τὰ θεῖα καὶ τὰ ἀνθρώπεια ἐπιβλέποντος, ὧνπερ τὴν φιλοσοφίαν ἐπιστήμην φασίν. ὡς δ’ αὕτως καὶ ἡ ὠφέλεια ποικίλη τις οὖσα, ἡ μὲν πρὸς τὰ πολιτικὰ καὶ τὰς ἡγεμονικὰς πράξεις, ἡ δὲ πρὸς ἐπιστήμην τῶν τε οὐρανίων καὶ τῶν ἐπὶ γῆς καὶ θαλάττης ζῴων καὶ φυτῶν καὶ καρπῶν καὶ τῶν ἄλλων ὅσα ἰδεῖν παρ’ ἑκάστοις ἔστι, τὸν αὐτὸν ὑπογράφει ἄνδρα, τὸν φροντίζοντα τῆς περὶ τὸν βίον τέχνης καὶ εὐδαιμονίας.", "st": "1.1.1"}, {"sp": "N", "t": "Ἀναλαβόντες δὲ καθ’ ἕκαστον ἐπισκοπῶμεν τῶν εἰρημένων ἔτι μᾶλλον. καὶ πρῶτον ὅτι ὀρθῶς ὑπειλήφαμεν καὶ ἡμεῖς καὶ οἱ πρὸ ἡμῶν, ὧν ἐστι καὶ Ἵππαρχος, ἀρχηγέτην εἶναι τῆς γεωγραφικῆς ἐμπειρίας Ὅμηρον, ὃς οὐ μόνον ἐν τῇ κατὰ τὴν ποίησιν ἀρετῇ πάντας ὑπερβέβληται τοὺς πάλαι καὶ τοὺς ὕστερον, ἀλλὰ σχεδόν τι καὶ τῇ κατὰ τὸν βίον ἐμπειρίᾳ τὸν πολιτικόν, ἀφ’ ἧς οὐ μόνον περὶ τὰς πράξεις ἐσπούδασεν ἐκεῖνος, ὅπως ὅτι πλείστας γνοίη καὶ παραδώσει τοῖς ὕστερον ἐσομένοις, ἀλλὰ καὶ τὰ περὶ τοὺς τόπους τούς τε καθ’ ἕκαστα καὶ τοὺς κατὰ σύμπασαν τὴν οἰκουμένην γῆν τε καὶ θάλατταν· οὐ γὰρ ἂν μέχρι τῶν ἐσχάτων αὐτῆς περάτων ἀφίκετο τῇ μνήμῃ κύκλῳ περιιών.", "st": "1.1.2"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τῷ ὠκεανῷ περίκλυστον, ὥσπερ ἔστιν, ἀπέφαινεν αὐτήν· ἔπειτα δὲ τῶν χωρίων τὰ μὲν ὠνόμαζε τὰ δὲ ὑπῃνίττετο τεκμηρίοις τισί, Λιβύην μὲν καὶ Αἰθιοπίαν καὶ Σιδονίους καὶ Ἐρεμβούς, οὓς εἰκὸς λέγειν Τρωγλοδύτας Ἄραβας, ῥητῶς λέγων, τοὺς δὲ πρὸς ταῖς ἀνατολαῖς καὶ δύσεσιν αἰνιττόμενος ἐκ τοῦ τῷ ὠκεανῷ κλύζεσθαι· ἐντεῦθεν γὰρ ἀνίσχοντα ποιεῖ τὸν ἥλιον καὶ δυόμενον εἰς τοῦτον, ὡς δ’ αὕτως καὶ τὰ ἄστρα καὶ τοὺς ἀστέρας λελουμένους ἐξ ὠκεανοῦ λέγει.", "st": "1.1.3"}, {"sp": "N", "t": "τῶν δ’ ἑσπερίων ἀνδρῶν καὶ τὴν εὐδαιμονίαν ἐμφανίζει καὶ τὴν εὐκρασίαν τοῦ περιέχοντος, πεπυσμένος, ὡς ἔοικε, τὸν Ἰβηρικὸν πλοῦτον, ἐφ’ ὃν καὶ Ἡρακλῆς ἐστράτευσε καὶ οἱ Φοίνικες ὕστερον, οἵπερ καὶ κατέσχον τὴν πλείστην ἀρχήν, μετὰ δὲ ταῦτα Ῥωμαῖοι· ἐνταῦθα γὰρ αἱ τοῦ ζεφύρου πνοαί, ἐνταῦθα δὲ καὶ τὸ Ἠλύσιον ποιεῖ πεδίον ὁ ποιητής, εἰς ὃ πεμφθήσεσθαί φησι τὸν Μενέλαον ὑπὸ τῶν θεῶν “ἀλλά σ’ ἐς Ἠλύσιον πεδίον καὶ πείρατα γαίης ἀθάνατοι πέμψουσιν, ὅθι ξανθὸς Ῥαδάμανθυς, τῇ περ ῥηίστη βιοτὴ πέλει· οὐ νιφετός, οὔτ’ ἂρ χειμὼν πολύς, ἀλλ’ αἰεὶ ζεφύροιο λιγὺ πνείοντας ἀήτας ὠκεανὸς ἀνίησι.”", "st": "1.1.4"}, {"sp": "N", "t": "καὶ αἱ τῶν μακάρων δὲ νῆσοι πρὸ τῆς Μαυρουσίας εἰσὶ τῆς ἐσχάτης πρὸς δύσιν, καθ’ ὃ μέρος συντρέχει καὶ τῆς Ἰβηρίας τὸ ταύτῃ πέρας· ἐκ δὲ τοῦ ὀνόματος δῆλον ὅτι καὶ ταύτας ἐνόμιζον εὐδαίμονας διὰ τὸ πλησιάζειν τοιούτοις χωρίοις.", "st": "1.1.5"}, {"sp": "N", "t": "Ἀλλὰ μὴν ὅτι γε καὶ οἱ Αἰθίοπες ἐπὶ τῷ ὠκεανῷ ἔσχατοι, δηλοῖ· ὅτι μὲν ἔσχατοι “Αἰθίοπες, τοὶ διχθὰ δεδαίαται, ἔσχατοι ἀνδρῶν.” οὐδὲ τοῦ “διχθὰ δεδαίαται” φαύλως λεγομένου, ὡς δειχθήσεται ὕστερον· ὅτι δ’ ἐπὶ τῷ ὠκεανῷ “Ζεὺς γὰρ ἐς ὠκεανὸν μετ’ ἀμύμονας Αἰθιοπῆας χθιζὸς ἔβη μετὰ δαῖτα.” ὅτι δὲ καὶ ἡ πρὸς ταῖς ἄρκτοις ἐσχατιὰ παρωκεανῖτίς ἐστιν, οὕτως ᾐνίξατο εἰπὼν περὶ τῆς ἄρκτου “οἴη δ’ ἄμμορός ἐστι λοετρῶν ὠκεανοῖο.” διὰ μὲν γὰρ τῆς ἄρκτου καὶ τῆς ἁμάξης τὸν ἀρκτικὸν δηλοῖ· οὐ γὰρ ἂν τοσούτων ἀστέρων ἐν τῷ αὐτῷ χωρίῳ περιφερομένων τῷ ἀεὶ φανερῷ οἴην ἄμμορον εἶπε λοετρῶν ὠκεανοῖο. ὥστ’ οὐκ εὖ ἀπειρίαν αὐτοῦ καταγινώσκουσιν, ὡς μίαν ἄρκτον ἀντὶ δυεῖν εἰδότος· οὐδὲ γὰρ εἰκὸς ἦν πω τὴν ἑτέραν ἠστροθετῆσθαι, ἀλλ’ ἀφ’ οὗ οἱ Φοίνικες ἐσημειώσαντο καὶ ἐχρῶντο πρὸς τὸν πλοῦν παρελθεῖν καὶ εἰς τοὺς Ἕλληνας τὴν διάταξιν ταύτην, ὥσπερ καὶ τὸν Βερενίκης πλόκαμον καὶ τὸν Κάνωβον ἐχθὲς καὶ πρώην κατωνομασμένον, πολλοὺς δ’ ἔτι νῦν ἀνωνύμους ὄντας, καθάπερ καὶ Ἄρατός φησιν. οὐδὲ Κράτης οὖν ὀρθῶς γράφει “οἶος δ’ ἄμμορός ἐστι λοετρῶν,” φεύγων τὰ μὴ φευκτά. βελτίων δ’ Ἡράκλειτος καὶ ὁμηρικώτερος, ὁμοίως ἀντὶ τοῦ ἀρκτικοῦ τὴν ἄρκτον ὀνομάζων “ἠοῦς καὶ ἑσπέρης τέρματα ἡ ἄρκτος, καὶ ἀντίον τῆς ἄρκτου οὖρος αἰθρίου Διός.” ὁ γὰρ ἀρκτικός ἐστι δύσεως καὶ ἀνατολῆς ὅρος, οὐχ ἡ ἄρκτος. διὰ μὲν δὴ τῆς ἄρκτου, ἣν καὶ ἅμαξαν καλεῖ καὶ τὸν Ὠρίωνα δοκεύειν φησί, τὸν ἀρκτικὸν δηλοῖ, διὰ δὲ τοῦ ὠκεανοῦ τὸν ὁρίζοντα, εἰς ὃν καὶ ἐξ οὗ τὰς δύσεις καὶ τὰς ἀνατολὰς ποιεῖται. εἰπὼν δὲ αὐτοῦ στρέφεσθαι καὶ ἀμοιρεῖν τοῦ ὠκεανοῦ οἶδεν ὅτι κατὰ σημεῖον τὸ ἀρκτικώτατον τοῦ ὁρίζοντος γίνεται ὁ ἀρκτικός. ἀκολούθως δὴ τούτῳ τὸ ποιητικὸν ἁρμόσαντες τὸν μὲν ὁρίζοντα ὀφείλομεν δέχεσθαι τὸν ἐπὶ τῆς γῆς οἰκείως τῷ ὠκεανῷ, τὸν δ’ ἀρκτικὸν τῆς γῆς ἁπτόμενον ὡς ἂν πρὸς αἴσθησιν κατὰ τὸ ἀρκτικώτατον τῆς οἰκήσεως σημεῖον· ὥστε καὶ τοῦτο τὸ μέρος τῆς γῆς κλύζοιτ’ ἂν τῷ ὠκεανῷ κατ’ αὐτόν. καὶ τοὺς ἀνθρώπους δὲ οἶδε τοὺς προσβόρρους μάλιστα, οὓς ὀνομαστὶ μὲν οὐ δηλοῖ (οὐδὲ γὰρ νῦν που κοινὸν αὐτοῖς ὄνομα κεῖται πᾶσι), τῇ διαίτῃ δὲ φράζει, νομάδας αὐτοὺς ὑπογράφων καὶ ἀγαυοὺς ἱππημολγοὺς γαλακτοφάγους ἀβίους τε.", "st": "1.1.6"}, {"sp": "N", "t": "καὶ ἄλλως δ’ ἐμφαίνει τὸ κύκλῳ περικεῖσθαι τῇ γῇ τὸν ὠκεανόν, ὅταν οὕτω φῇ ἡ Ἥρα “εἶμι γὰρ ὀψομένη πολυφόρβου πείρατα γαίης Ὠκεανόν τε θεῶν γένεσιν.” τοῖς γὰρ πέρασι πᾶσι συνήθη λέγει τὸν ὠκεανόν, τὰ δὲ πέρατα κύκλῳ περίκειται. ἔν τε τῇ ὁπλοποιίᾳ τῆς Ἀχιλλέως ἀσπίδος κύκλῳ περιτίθησι τὸν ὠκεανὸν ἐπὶ τῆς ἴτυος. ἔχεται δὲ τῆς αὐτῆς φιλοπραγμοσύνης καὶ τὸ μὴ ἀγνοεῖν τὰ περὶ τὰς πλημμυρίδας τοῦ ὠκεανοῦ καὶ τὰς ἀμπώτεις ἀψορρόου ὠκεανοῖο, λέγοντα καί “τρὶς μὲν γάρ τ’ ἀνίησιν ἐπ’ ἤματι, τρὶς δ’ ἀναροιβδεῖ.” καὶ γὰρ εἰ μὴ τρὶς ἀλλὰ δίς, τάχα τῆς ἱστορίας παραπεσόντος ἢ τῆς γραφῆς διημαρτημένης, ἀλλ’ ἥ γε προαίρεσις τοιαύτη. καὶ τὸ “ἐξ ἀκαλαρρείταο” δὲ ἔχει τινὰ ἔμφασιν τῆς πλημμυρίδος, ἐχούσης τὴν ἐπίβασιν πραεῖαν καὶ οὐ τελέως ῥοώδη. Ποσειδώνιος δὲ καὶ ἐκ τοῦ σκοπέλους λέγειν τοτὲ μὲν καλυπτομένους τοτὲ δὲ γυμνουμένους καὶ ἐκ τοῦ ποταμὸν φάναι τὸν ὠκεανὸν εἰκάζει τὸ ῥοῶδες αὐτοῦ τὸ περὶ τὰς πλημμυρίδας ἐμφανίζεσθαι. τὸ μὲν οὖν πρῶτον εὖ, τὸ δὲ δεύτερον οὐκ ἔχει λόγον· οὔτε γὰρ ποταμίῳ ῥεύματι ἔοικεν ἡ τῆς πλημμυρίδος ἐπίβασις, πολὺ δὲ μᾶλλον ἡ ἀναχώρησις οὐ τοιαύτη, ὅ τε τοῦ Κράτητος λόγος διδάσκει τι πιθανώτερον. βαθύρρουν μὲν γὰρ καὶ ἄψορρον λέγει, ὁμοίως δὲ καὶ ποταμὸν τὸν ὅλον ὠκεανόν· λέγει δὲ καὶ μέρος τοῦ ὠκεανοῦ τι ποταμὸν καὶ ποταμοῖο ῥόον, οὐ τοῦ ὅλου ἀλλὰ τοῦ μέρους, ὅταν οὕτω φῇ “αὐτὰρ ἐπεὶ ποταμοῖο λίπεν ῥόον ὠκεανοῖο νηῦς, ἀπὸ δ’ ἵκετο κῦμα θαλάσσης εὐρυπόροιο.” οὐ γὰρ τὸν ὅλον, ἀλλὰ τὸν ἐν τῷ ὠκεανῷ τοῦ ποταμοῦ ῥόον μέρος ὄντα τοῦ ὠκεανοῦ, ὅν φησιν ὁ Κράτης ἀνάχυσίν τινα καὶ κόλπον ἐπὶ τὸν νότιον πόλον ἀπὸ τοῦ χειμερινοῦ τροπικοῦ διήκοντα. τοῦτον γὰρ δύναιτ’ ἄν τις ἐκλιπὼν ἔτι εἶναι ἐν τῷ ὠκεανῷ, τὸν δὲ ὅλον ἐκλιπόντα ἔτι εἶναι ἐν τῷ ὅλῳ οὐχ οἷόν τε. Ὅμηρος δέ γε οὕτω φησί “ποταμοῖο λίπεν ῥόον, ἀπὸ δ’ ἵκετο κῦμα θαλάσσης,” ἥτις οὐκ ἄλλη τίς ἐστιν ἀλλὰ ὠκεανός. γίνεται οὖν, ἐὰν ἄλλως δέχῃ, ἐκβὰς ἐκ τοῦ ὠκεανοῦ ἦλθεν εἰς τὸν ὠκεανόν. ἀλλὰ ταῦτα μὲν μακροτέρας ἐστὶ διαίτης.", "st": "1.1.7"}, {"sp": "N", "t": "̔́οτι δὲ ἡ οἰκουμένη νῆσός ἐστι πρῶτον μὲν ἐκ τῆς αἰσθήσεως καὶ τῆς πείρας ληπτέον. πανταχῆ γάρ, ὁπουποτοῦν ἐφικτὸν γέγονεν ἀνθρώποις ἐπὶ τὰ ἔσχατα τῆς γῆς προελθεῖν, εὑρίσκεται θάλαττα, ἣν δὴ καλοῦμεν ὠκεανόν. καὶ ὅπου δὲ τῇ αἰσθήσει λαβεῖν οὐχ ὑπῆρξεν, ὁ λόγος δείκνυσι. τὸ μὲν γὰρ ἑωθινὸν πλευρόν, τὸ κατὰ τοὺς Ἰνδούς, καὶ τὸ ἑσπέριον, τὸ κατὰ τοὺς Ἴβηρας καὶ τοὺς Μαυρουσίους, περιπλεῖται πᾶν ἐπὶ πολὺ τοῦ τε νοτίου μέρους καὶ τοῦ βορείου· τὸ δὲ λειπόμενον ἄπλουν ἡμῖν μέχρι νῦν τῷ μὴ συμμῖξαι μηδένας ἀλλήλοις τῶν ἀντιπεριπλεόντων οὐ πολύ, εἴ τις συντίθησιν ἐκ τῶν παραλλήλων διαστημάτων τῶν ἐφικτῶν ἡμῖν. οὐκ εἰκὸς δὲ διθάλαττον εἶναι τὸ πέλαγος τὸ Ἀτλαντικόν, ἰσθμοῖς διειργόμενον οὕτω στενοῖς τοῖς κωλύουσι τὸν περίπλουν, ἀλλὰ μᾶλλον σύρρουν καὶ συνεχές· οἵ τε γὰρ περιπλεῖν ἐγχειρήσαντες, εἶτα ἀναστρέψαντες, οὐχ ὑπὸ ἠπείρου τινὸς ἀντιπιπτούσης καὶ κωλυούσης τὸν ἐπέκεινα πλοῦν ἀνακρουσθῆναι φασίν, ἀλλὰ ὑπὸ ἀπορίας καὶ ἐρημίας, οὐδὲν ἧττον τῆς θαλάττης ἐχούσης τὸν πόρον. τοῖς τε πάθεσι τοῦ ὠκεανοῦ τοῖς περὶ τὰς ἀμπώτεις καὶ τὰς πλημμυρίδας ὁμολογεῖ τοῦτο μᾶλλον· πάντη γοῦν ὁ αὐτὸς τρόπος τῶν τε μεταβολῶν ὑπάρχει καὶ τῶν αὐξήσεων καὶ μειώσεων, ἣ οὐ πολὺ παραλλάττων, ὡς ἂν ἐπὶ ἑνὸς πελάγους τῆς κινήσεως ἀποδιδομένης καὶ ἀπὸ μιᾶς αἰτίας.", "st": "1.1.8"}, {"sp": "N", "t": "̔́ιππαρχος δ’ οὐ πιθανός ἐστιν ἀντιλέγων τῇ δόξῃ ταύτῃ, ὡς οὔθ’ ὁμοιοπαθοῦντος τοῦ ὠκεανοῦ παντελῶς οὔτ’, εἰ δοθείη τοῦτο, ἀκολουθοῦντος αὐτῷ τοῦ σύρρουν εἶναι πᾶν τὸ κύκλῳ πέλαγος τὸ Ἀτλαντικόν, πρὸς τὸ μὴ ὁμοιοπαθεῖν μάρτυρι χρώμενος Σελεύκῳ τῷ Βαβυλωνίῳ. ἡμεῖς δὲ τὸν μὲν πλείω λόγον περὶ τοῦ ὠκεανοῦ καὶ τῶν πλημμυρίδων εἰς Ποσειδώνιον ἀναβαλλόμεθα καὶ Ἀθηνόδωρον, ἱκανῶς * διακρατήσαντας τὸν περὶ τούτων λόγον· πρὸς δὲ τὰ νῦν ἐπὶ τοσοῦτον λέγομεν, ὅτι πρός τε τὴν ὁμοιοπάθειαν οὕτω βέλτιον νομίσαι, τά τε οὐράνια συνέχοιτ’ ἂν κρεῖττον ταῖς ἐντεῦθεν ἀναθυμιάσεσιν, εἰ πλεῖον εἴη τὸ ὑγρὸν περικεχυμένον.", "st": "1.1.9"}, {"sp": "N", "t": "ὥσπερ οὖν τὰ ἔσχατα καὶ τὰ κύκλῳ τῆς οἰκουμένης οἶδε καὶ φράζει σαφῶς ὁ ποιητής, οὕτω καὶ τὰ τῆς θαλάττης τῆς ἐντός. περιέχει γὰρ ταύτην ἀπὸ στηλῶν ἀρξαμένοις Λιβύη τε καὶ Αἴγυπτος καὶ Φοινίκη, ἑξῆς δὲ ἡ πέριξ τῆς Κύπρου, εἶτα Σόλυμοι καὶ Λύκιοι καὶ Κᾶρες, μετὰ δὲ τούτους ἡ μεταξὺ Μυκάλης καὶ τῆς Τρῳάδος ᾐὼν καὶ αἱ προκείμεναι νῆσοι· ὧν ἁπάντων μέμνηται, καὶ ἐφεξῆς τῶν περὶ τὴν Προποντίδα καὶ τοῦ Εὐξείνου μέχρι Κολχίδος καὶ τῆς Ἰάσονος στρατείας. καὶ μὴν καὶ τὸν Κιμμερικὸν Βόσπορον οἶδε τοὺς Κιμμερίους εἰδώς, οὐ δήπου τὸ μὲν ὄνομα τῶν Κιμμερίων εἰδὼς αὐτοὺς δὲ ἀγνοῶν, οἳ κατ’ αὐτὸν ἢ μικρὸν πρὸ αὐτοῦ μέχρι Ἰωνίας ἐπέδραμον τὴν γῆν τὴν ἐκ Βοσπόρου πᾶσαν. αἰνίττεται γοῦν καὶ τὸ κλίμα τῆς χώρας αὐτῶν ζοφῶδες ὄν, καὶ ὡς φησίν “ἠέρι καὶ νεφέλῃ κεκαλυμμένοι· οὐδέ ποτ’ αὐτοὺς ἠέλιος φαέθων ἐπιλάμπεται, ἀλλ’ ἐπὶ νὺξ ὀλοὴ τέταται.” γνωρίζει δὲ καὶ τὸν Ἴστρον, μεμνημένος γε Μυσῶν, ἔθνους Θρᾳκίου παροικοῦντος τὸν Ἴστρον. καὶ μὴν καὶ τὴν ἑξῆς παραλίαν οἶδε, Θρᾳκίαν οὖσαν μέχρι Πηνειοῦ, Παίονάς τε ὀνομάζων καὶ Ἄθω καὶ Ἀξιὸν καὶ τὰς προκειμένας τούτων νήσους. ἑξῆς δέ ἐστιν ἡ τῶν Ἑλλήνων παραλία μέχρι Θεσπρωτῶν, ἧς ἁπάσης μέμνηται. καὶ μὴν καὶ τὰ τῆς Ἰταλίας ἄκρα οἶδε, Τεμέσην καλῶν καὶ Σικελούς, καὶ τὰ τῆς Ἰβηρίας ἄκρα καὶ τὴν εὐδαιμονίαν αὐτῶν, ἣν ἀρτίως ἔφαμεν. εἰ δέ τινα ἐν τοῖς μεταξὺ διαλείμματα φαίνεται, συγγνοίη τις ἄν· καὶ γὰρ ὁ γεωγραφῶν ὄντως πολλὰ παρίησι τῶν ἐν μέρει. συγγνοίη δ’ ἂν καὶ εἰ μυθώδη τινὰ προσπέπλεκται τοῖς λεγομένοις ἱστορικῶς καὶ διδασκαλικῶς, καὶ οὐ δεῖ μέμφεσθαι. οὐδὲ γὰρ ἀληθές ἐστιν, ὅ φησιν Ἐρατοσθένης, ὅτι ποιητὴς πᾶς στοχάζεται ψυχαγωγίας, οὐ διδασκαλίας· τἀναντία γὰρ οἱ φρονιμώτατοι τῶν περὶ ποιητικῆς τι φθεγξαμένων πρώτην τινὰ λέγουσι φιλοσοφίαν τὴν ποιητικήν. ἀλλὰ πρὸς Ἐρατοσθένη μὲν αὖθις ἐροῦμεν διὰ πλειόνων, ἐν οἷς καὶ περὶ τοῦ ποιητοῦ πάλιν ἔσται λόγος.", "st": "1.1.10"}, {"sp": "N", "t": "νυνὶ δὲ ὅτι μὲν Ὅμηρος τῆς γεωγραφίας ἦρξεν, ἀρκείτω τὰ λεχθέντα. φανεροὶ δὲ καὶ οἱ ἐπακολουθήσαντες αὐτῷ ἄνδρες ἀξιόλογοι καὶ οἰκεῖοι φιλοσοφίας, ὧν τοὺς πρώτους μεθ’ Ὅμηρον δύο φησὶν Ἐρατοσθένης, Ἀναξίμανδρόν τε Θαλοῦ γεγονότα γνώριμον καὶ πολίτην καὶ Ἑκαταῖον τὸν Μιλήσιον· τὸν μὲν οὖν ἐκδοῦναι πρῶτον γεωγραφικὸν πίνακα, τὸν δὲ Ἑκαταῖον καταλιπεῖν γράμμα, πιστούμενον ἐκείνου εἶναι ἐκ τῆς ἄλλης αὐτοῦ γραφῆς.", "st": "1.1.11"}, {"sp": "N", "t": "Ἀλλὰ μὴν ὅτι γε δεῖ πρὸς ταῦτα πολυμαθείας, εἰρήκασι συχνοί. εὖ δὲ καὶ Ἵππαρχος ἐν τοῖς πρὸς Ἐρατοσθένην διδάσκει, ὅτι παντὶ καὶ ἰδιώτῃ καὶ τῷ φιλομαθοῦντι τῆς γεωγραφικῆς ἱστορίας προσηκούσης, ἀδύνατον [αὐτὴν] λαβεῖν ἄνευ τῆς τῶν οὐρανίων καὶ τῆς τῶν ἐκλειπτικῶν τηρήσεων ἐπικρίσεως· οἷον Ἀλεξάνδρειαν τὴν πρὸς Αἰγύπτῳ, πότερον ἀρκτικωτέρα Βαβυλῶνος ἢ νοτιωτέρα, λαβεῖν οὐχ οἷόν τε, οὐδ’ ἐφ’ ὁπόσον διάστημα, χωρὶς τῆς διὰ τῶν κλιμάτων ἐπισκέψεως. ὁμοίως τὰς πρὸς ἕω παρακεχωρηκυίας ἢ πρὸς δύσιν μᾶλλον καὶ ἧττον οὐκ ἂν γνοίη τις ἀκριβῶς πλὴν εἰ διὰ τῶν ἐκλειπτικῶν ἡλίου καὶ σελήνης συγκρίσεων.", "st": "1.1.12"}, {"sp": "N", "t": "οὗτός τε δὴ ταῦτά φησι, καὶ πάντες, ὅσοι τόπων ἰδιότητας λέγειν ἐπιχειροῦσιν, οἰκείως προσάπτονται καὶ τῶν οὐρανίων καὶ γεωμετρίας, σχήματα καὶ μεγέθη καὶ ἀποστήματα καὶ κλίματα δηλοῦντες καὶ θάλπη καὶ ψύχη καὶ ἁπλῶς τὴν τοῦ περιέχοντος φύσιν. ἐπεὶ καὶ οἶκον κατασκευάζων οἰκοδόμος ταῦτα ἂν προορῷτο καὶ πόλιν κτίζων ἀρχιτέκτων, μή τί γε ὅλην ἐπισκοπῶν τὴν οἰκουμένην ἀνήρ· πολὺ γὰρ τούτῳ προσήκει μᾶλλον. ἐν μὲν γὰρ τοῖς μικροῖς χωρίοις τὸ πρὸς ἄρκτους ἢ πρὸς νότον κεκλίσθαι παραλλαγὴν οὐ πολλὴν ἔχει, ἐν δὲ τῷ παντὶ κύκλῳ τῆς οἰκουμένης πρὸς ἄρκτον μὲν τὸ μέχρι τῶν ὑστάτων ἐστὶ τῆς Σκυθίας ἢ τῆς Κελτικῆς, μέχρι δὲ τῶν ὑστάτων Αἰθιόπων τὰ πρὸς νότον· τοῦτο δὲ παμπόλλην ἔχει διαφοράν. ὁμοίως δὲ καὶ τὸ παρ’ Ἰνδοῖς οἰκεῖν ἢ παρ’ Ἴβηρσιν· ὧν τοὺς μὲν ἑῴους μάλιστα τοὺς δὲ ἑσπερίους, τρόπον δέ τινα καὶ ἀντίποδας ἀλλήλοις ἴσμεν.", "st": "1.1.13"}, {"sp": "N", "t": "πᾶν δὲ τὸ τοιοῦτον ἐκ τῆς τοῦ ἡλίου καὶ τῶν ἄλλων ἄστρων κινήσεως τὴν ἀρχὴν ἔχον καὶ ἔτι τῆς ἐπὶ τὸ μέσον φορᾶς ἀναβλέπειν ἀναγκάζει πρὸς τὸν οὐρανὸν καὶ πρὸς τὰ φαινόμενα παρ’ ἑκάστοις ἡμῶν τῶν οὐρανίων· ἐν δὲ τούτοις ἐξαλλάξεις ὁρῶνται παμμεγέθεις τῶν οἰκήσεων. τίς ἂν οὖν διαφορὰς τόπων ἐκτιθέμενος καλῶς καὶ ἱκανῶς διδάσκοι, μὴ φροντίσας τούτων μηδενὸς μηδ’ ἐπὶ μικρόν; καὶ γὰρ εἰ μὴ δυνατὸν κατὰ τὴν ὑπόθεσιν τὴν τοιαύτην ἅπαντα ἀκριβοῦν διὰ τὸ εἶναι πολιτικωτέραν, τό γε ἐπὶ τοσοῦτον, ἐφ’ ὅσον καὶ τῷ πολιτικῷ παρακολουθεῖν δυνατόν, προσήκοι ἂν εἰκότως.", "st": "1.1.14"}, {"sp": "N", "t": "̔ο δ’ οὕτω μετεωρίσας ἤδη τὴν διάνοιαν οὐδὲ τῆς ὅλης ἀπέχεται γῆς· φαίνεται γὰρ γελοῖον, εἰ τὴν οἰκουμένην γλιχόμενος σαφῶς ἐξειπεῖν τῶν μὲν οὐρανίων ἐτόλμησεν ἅψασθαι καὶ χρήσασθαι πρὸς τὴν διδασκαλίαν, τὴν δ’ ὅλην γῆν, ἧς μέρος ἡ οἰκουμένη, μήθ’ ὁπόση μήθ’ ὁποία τις μήθ’ ὅπου κειμένη τοῦ σύμπαντος κόσμου, μηδὲν ἐφρόντισε, μηδ’ εἰ καθ’ ἓν μέρος οἰκεῖται μόνον τὸ καθ’ ἡμᾶς ἢ κατὰ πλείω καὶ πόσα· ὡς δ’ αὕτως καὶ τὸ ἀοίκητον αὐτῆς πόσον καὶ ποῖόν τι καὶ διὰ τί. ἔοικεν οὖν μετεωρολογικῇ τινι πραγματείᾳ καὶ γεωμετρικῇ συνῆφθαι τὸ τῆς γεωγραφίας εἶδος τὰ ἐπίγεια τοῖς οὐρανίοις συνάπτον εἰς ἕν, ὡς ἐγγυτάτω ὄντα ἀλλὰ μὴ διεστῶτα τοσοῦτον “ὅσον οὐρανός ἐστ’ ἀπὸ γαίης.” φέρε δὴ τῇ τοσαύτῃ πολυμαθείᾳ προσθῶμεν τὴν ἐπίγειον ἱστορίαν, οἷον ζῴων καὶ φυτῶν καὶ τῶν ἄλλων, ὅσα χρήσιμα ἢ δύσχρηστα φέρει γῆ τε καὶ θάλασσα· οἶμαι γὰρ ἐναργὲς ἂν γενέσθαι μᾶλλον ὃ λέγω.", "st": "1.1.15"}, {"sp": "N", "t": "̔́οτι δὲ καὶ τὸ ὄφελος μέγα παντὶ τῷ παραλαβόντι τὴν τοιαύτην ἱστορίαν ἔκ τε τῆς παλαιᾶς μνήμης δῆλον καὶ ἐκ τοῦ λόγου. οἱ γοῦν ποιηταὶ φρονιμωτάτους τῶν ἡρώων ἀποφαίνουσι τοὺς ἀποδημήσαντας πολλαχοῦ καὶ πλανηθέντας· ἐν μεγάλῳ γὰρ τίθενται τὸ πολλῶν ἀνθρώπων ἰδεῖν ἄστεα καὶ νόον γνῶναι. καὶ ὁ Νέστωρ σεμνύνεται διότι τοῖς Λαπίθαις ὡμίλησεν, ἐλθὼν μετάπεμπτος “τηλόθεν ἐξ ἀπίης γαίης· καλέσαντο γὰρ αὐτοί.” καὶ ὁ Μενέλαος ὡσαύτως “Κύπρον Φοινίκην τε καὶ Αἰγυπτίους ἐπαληθεὶς Αἰθίοπας θ’ ἱκόμην καὶ Σιδονίους καὶ Ἐρεμβοὺς καὶ Λιβύην, ἵνα τ’ ἄρνες ἄφαρ κεραοὶ τελέθουσι,” προσθεὶς καὶ τὸ ἰδίωμα τῆς χώρας “τρὶς γὰρ τίκτει μῆλα τελεσφόρον εἰς ἐνιαυτόν.” πάντα γὰρ τὰ τοιαῦτα παρασκευαί τινες εἰς φρόνησιν μεγάλαι τῷ μαθεῖν τῆς χώρας τὴν φύσιν καὶ ζῴων καὶ φυτῶν ἰδέας. προσθεῖναι δὲ καὶ τὰ τῆς θαλάττης· ἀμφίβιοι γὰρ τρόπον τινά ἐσμεν καὶ οὐ μᾶλλον χερσαῖοι ἢ θαλάττιοι. καὶ τὸν Ἡρακλέα εἰκὸς ἀπὸ τῆς πολλῆς ἐμπειρίας τε καὶ ἱστορίας λεχθῆναι “μεγάλων ἐπιίστορα ἔργων.” ἔκ τε δὴ τῆς παλαιᾶς μνήμης καὶ ἐκ τοῦ λόγου μαρτυρεῖται τὰ λεχθέντα ἐν ἀρχαῖς ὑφ’ ἡμῶν, διαφερόντως δ’ ἐπάγεσθαι δοκεῖ μοι πρὸς τὰ νῦν ἐκεῖνος ὁ λόγος, διότι τῆς γεωγραφίας τὸ πλέον ἐστὶ πρὸς τὰς χρείας τὰς πολιτικάς. χώρα γὰρ τῶν πράξεων ἐστὶ γῆ καὶ θάλαττα, ἣν οἰκοῦμεν, τῶν μὲν μικρῶν μικρὰ τῶν δὲ μεγάλων μεγάλη, μεγίστη δ’ ἡ σύμπασα, ἥνπερ ἰδίως καλοῦμεν οἰκουμένην, ὥστε τῶν μεγίστων πράξεων αὕτη ἂν εἴη χώρα, μέγιστοι δὲ τῶν στρατηλατῶν, ὅσοι δύνανται γῆς καὶ θαλάττης ἄρχειν, ἔθνη καὶ πόλεις συνάγοντες εἰς μίαν ἐξουσίαν καὶ διοίκησιν πολιτικήν. δῆλον οὖν ὅτι ἡ γεωγραφικὴ πᾶσα ἐπὶ τὰς πράξεις ἀνάγεται τὰς ἡγεμονικάς, διατιθεῖσα ἠπείρους καὶ πελάγη τὰ μὲν ἐντὸς τὰ δὲ ἐκτὸς τῆς συμπάσης οἰκουμένης. πρὸς τούτους δὲ ἡ διάθεσις, οἷς διαφέρει ταῦτα ἔχειν οὕτως ἢ ἑτέρως καὶ γνώριμα εἶναι ἢ μὴ γνώριμα. βέλτιον γὰρ ἂν διαχειρίζοιεν ἕκαστα εἰδότες τὴν χώραν ὁπόση τις καὶ πῶς κειμένη τυγχάνει καὶ τίνας διαφορὰς ἴσχουσα τάς τ’ ἐν τῷ περιέχοντι καὶ τὰς ἐν αὐτῇ. ἄλλων δὲ κατ’ ἄλλα μέρη δυναστευόντων καὶ ἀπ’ ἄλλης ἑστίας καὶ ἀρχῆς τὰς πράξεις προχειριζομένων καὶ ἐπεκτεινόντων τὸ τῆς ἡγεμονίας μέγεθος, οὐκ ἐπ’ ἴσης δυνατὸν οὔτ’ ἐκείνοις ἅπαντα γνωρίζειν οὔτε τοῖς γεωγραφοῦσιν, ἀλλὰ τὸ μᾶλλον καὶ ἧττον πολὺ ἐν ἀμφοτέροις καθορᾶται τούτοις. μόλις γὰρ [ἂν] τὸ ἐπ’ ἴσης πάντ’ εἶναι φανερὰ συμβαίη τῆς συμπάσης οἰκουμένης ὑπὸ μίαν ἀρχὴν καὶ πολιτείαν ὑπηγμένης· ἀλλ’ οὐδ’ οὕτως, ἀλλὰ τὰ ἐγγυτέρω μᾶλλον ἂν γνωρίζοιτο. κἂν προσήκοι ταῦτα διὰ πλειόνων ἐμφανίζειν, ἵν’ εἴη γνώριμα· ταῦτα γὰρ καὶ τῆς χρείας ἐγγυτέρω ἐστίν. ὥστ’ οὐκ ἂν εἴη θαυμαστὸν οὐδ’ εἰ ἄλλος μὲν Ἰνδοῖς προσήκοι χωρογράφος, ἄλλος δὲ Αἰθίοψιν, ἄλλος δὲ Ἕλλησι καὶ Ῥωμαίοις. τί γὰρ ἂν προσήκοι τῷ παρ’ Ἰνδοῖς γεωγράφῳ καὶ τὰ κατὰ Βοιωτοὺς οὕτω φράζειν ὡς Ὅμηρος “οἵθ’ Ὑρίην ἐνέμοντο καὶ Αὐλίδα πετρήεσσαν Σχοῖνόν τε Σκῶλόν τε;” ἡμῖν δὲ προσήκει, τὰ δὲ παρ’ Ἰνδοῖς οὕτω καὶ τὰ καθ’ ἕκαστα οὐκέτι· οὐδὲ γὰρ ἡ χρεία ἐπάγεται· μέτρον δ’ αὕτη μάλιστα τῆς τοιαύτης ἐμπειρίας.", "st": "1.1.16"}, {"sp": "N", "t": "καὶ τοῦτο καὶ ἐν μικροῖς μὲν δῆλόν ἐστιν, οἷον ἐν τοῖς κυνηγεσίοις· ἄμεινον γὰρ ἂν θηρεύσειέ τις εἰδὼς τὴν ὕλην ὁποία τις καὶ πόση, καὶ στρατοπεδεῦσαι δὲ καλῶς ἐν χωρίῳ τοῦ εἰδότος ἐστὶ καὶ ἐνεδρεῦσαι καὶ ὁδεῦσαι· ἀλλ’ ἐν τοῖς μεγάλοις ἐστὶ τηλαυγέστερον, ὅσῳπερ καὶ τὰ ἆθλα μείζω τὰ τῆς ἐμπειρίας καὶ τὰ σφάλματα τὰ ἐκ τῆς ἀπειρίας. ὁ μέντοι Ἀγαμέμνονος στόλος τὴν Μυσίαν ὡς τὴν Τρῳάδα πορθῶν ἐπαλινδρόμησεν αἰσχρῶς. Πέρσαι δὲ καὶ Λίβυες τοὺς πορθμοὺς ὑπονοήσαντες εἶναι τυφλοὺς στενωπούς, ἐγγὺς μὲν ἦλθον κινδύνων μεγάλων, τρόπαια δὲ τῆς ἀγνοίας κατέλιπον, οἱ μὲν τὸν τοῦ Σαλγανέως τάφον πρὸς τῷ εὐρίπῳ τῷ Χαλκιδικῷ τοῦ σφαγέντος ὑπὸ τῶν Περσῶν ὡς καθοδηγήσαντος φαύλως ἀπὸ Μαλιέων ἐπὶ τὸν εὔριπον τὸν στόλον, οἱ δὲ τὸ τοῦ Πελώρου μνῆμα καὶ τούτου διαφθαρέντος κατὰ τὴν ὁμοίαν αἰτίαν· πλήρης τε ναυαγίων ἡ Ἑλλὰς ὑπῆρξε κατὰ τὴν Ξέρξου στρατείαν. καὶ ἡ τῶν Αἰολέων δὲ καὶ ἡ τῶν Ἰώνων ἀποικία πολλὰ τοιαῦτα πταίσματα παραδέδωκεν. ὁμοίως δὲ καὶ κατορθώματα, ὅπου τι κατορθωθῆναι συνέβη παρὰ τὴν ἐμπειρίαν τῶν τόπων· καθάπερ ἐν τοῖς περὶ Θερμοπύλας στενοῖς ὁ Ἐφιάλτης λέγεται δείξας τὴν διὰ τῶν ὀρῶν ἀτραπὸν τοῖς Πέρσαις ὑποχειρίους αὐτοῖς ποιῆσαι τοὺς περὶ Λεωνίδαν καὶ δέξασθαι τοὺς βαρβάρους εἴσω Πυλῶν. ἐάσας δὲ τὰ παλαιὰ τὴν νῦν Ῥωμαίων στρατείαν ἐπὶ Παρθυαίους ἱκανὸν ἡγοῦμαι τούτων τεκμήριον· ὡς δ’ αὕτως τὴν ἐπὶ Γερμανοὺς καὶ Κελτούς, ἐν ἕλεσι καὶ δρυμοῖς ἀβάτοις ἐρημίαις τε τοπομαχούντων τῶν βαρβάρων καὶ τὰ ἐγγὺς πόρρω ποιούντων τοῖς ἀγνοοῦσι καὶ τὰς ὁδοὺς ἐπικρυπτομένων καὶ τὰς εὐπορίας τροφῆς τε καὶ τῶν ἄλλων.", "st": "1.1.17"}, {"sp": "N", "t": "τὸ μὲν δὴ πλέον, ὥσπερ εἴρηται, πρὸς τοὺς ἡγεμονικοὺς βίους καὶ τὰς χρείας ἐστίν. ἔστι δὲ καὶ τῆς ἠθικῆς φιλοσοφίας καὶ πολιτικῆς τὸ πλέον περὶ τοὺς ἡγεμονικοὺς βίους. σημεῖον δέ· τὰς γὰρ τῶν πολιτειῶν διαφορὰς ἀπὸ τῶν ἡγεμονιῶν διακρίνομεν, ἄλλην μὲν ἡγεμονίαν τιθέντες τὴν μοναρχίαν, ἣν καὶ βασιλείαν καλοῦμεν, ἄλλην δὲ τὴν ἀριστοκρατίαν, τρίτην δὲ τὴν δημοκρατίαν. τοσαύτας δὲ καὶ τὰς πολιτείας νομίζομεν, ὁμωνύμως καλοῦντες ὡς ἂν ἀπ’ ἐκείνων τὴν ἀρχὴν ἐχούσας τῆς εἰδοποιίας· ἄλλος γὰρ νόμος τὸ τοῦ βασιλέως πρόσταγμα, ἄλλος δὲ τὸ τῶν ἀρίστων καὶ τὸ τοῦ δήμου. τύπος δὲ καὶ σχῆμα πολιτείας ὁ νόμος. διὰ τοῦτο δὲ καὶ τὸ δίκαιον εἶπόν τινες τὸ τοῦ κρείττονος συμφέρον. εἴπερ οὖν ἡ πολιτικὴ φιλοσοφία περὶ τοὺς ἡγεμόνας τὸ πλέον ἐστίν, ἔστι δὲ καὶ ἡ γεωγραφία περὶ τὰς ἡγεμονικὰς χρείας, ἔχοι ἄν τι πλεονέκτημα καὶ αὕτη παρὰ τοῦτο.", "st": "1.1.18"}, {"sp": "N", "t": "Ἀλλὰ τοῦτο μὲν τὸ πλεονέκτημα πρὸς τὰς πράξεις· ἔχει δέ τινα καὶ θεωρίαν οὐ φαύλην ἡ πραγματεία, τὴν μὲν τεχνικήν τε καὶ μαθηματικὴν καὶ φυσικήν, τὴν δὲ ἐν ἱστορίᾳ καὶ μύθοις κειμένην οὐδὲν οὖσι πρὸς τὰς πράξεις· οἷον εἴ τις λέγοι τὰ περὶ τὴν Ὀδυσσέως πλάνην καὶ Μενελάου καὶ Ἰάσονος, εἰς φρόνησιν μὲν οὐδὲν ἂν συλλαμβάνειν δόξειεν, ἣν ὁ πράττων ζητεῖ, πλὴν εἰ καταμίσγοι καὶ τῶν γενομένων ἀναγκαίων τὰ παραδείγματα χρήσιμα· διαγωγὴν δ’ ὅμως πορίζοι ἂν οὐκ ἀνελεύθερον τῷ ἐπιβάλλοντι ἐπὶ τοὺς τόπους τοὺς παρασχόντας τὴν μυθοποιίαν. καὶ γὰρ τοῦτο ζητοῦσιν οἱ πράττοντες διὰ τὸ ἔνδοξον καὶ τὸ ἡδύ, ἀλλ’ οὐκ ἐπὶ πολύ· μᾶλλον γὰρ σπουδάζουσιν, ὡς εἰκός, περὶ τὰ χρήσιμα. διόπερ καὶ τῷ γεωγράφῳ τούτων μᾶλλον ἢ ἐκείνων ἐπιμελητέον. ὡς δ’ αὕτως ἔχει καὶ περὶ τῆς ἱστορίας καὶ περὶ τῶν μαθημάτων· καὶ γὰρ τούτων τὸ χρήσιμον ἀεὶ μᾶλλον ληπτέον καὶ τὸ πιστότερον.", "st": "1.1.19"}, {"sp": "N", "t": "μάλιστα δὲ δοκεῖ, καθάπερ εἴρηται, γεωμετρίας τε καὶ ἀστρονομίας δεῖν τῇ τοιαύτῃ ὑποθέσει. καὶ δεῖ μὲν ὡς ἀληθῶς· σχήματα γὰρ καὶ κλίματα καὶ μεγέθη καὶ τὰ ἄλλα τὰ τούτοις οἰκεῖα οὐχ οἷόν τε λαβεῖν καλῶς ἄνευ τῆς τοιαύτης μεθόδου. ἀλλ’ ὥσπερ τὰ περὶ τὴν ἀναμέτρησιν τῆς ὅλης γῆς ἐν ἄλλοις δεικνύουσιν, ἐνταῦθα δὲ ὑποθέσθαι δεῖ καὶ πιστεῦσαι τοῖς ἐκεῖ δειχθεῖσιν … ὑποθέσθαι δὲ καὶ σφαιροειδῆ μὲν τὸν κόσμον, σφαιροειδῆ δὲ καὶ τὴν ἐπιφάνειαν τῆς γῆς, ἔτι δὲ τούτων πρότερον τὴν ἐπὶ τὸ μέσον τῶν σωμάτων φοράν. ταῦτα μὲν οὖν ἐπεὶ τῆς αἰσθήσεως ἢ τῶν κοινῶν ἐννοιῶν ἐγγύς ἐστιν … εἰ ἄρα, ἐπισημηνάμενοι ἐπὶ κεφαλαίῳ μικρά· οἷον ὅτι ἡ γῆ σφαιροειδής, ἐκ μὲν τῆς ἐπὶ τὸ μέσον φορᾶς πόρρωθεν ἡ ὑπόμνησις καὶ τοῦ ἕκαστον σῶμα ἐπὶ τὸ αὑτοῦ ἄρτημα νεύειν, ἐκ δὲ τῶν κατὰ πελάγη καὶ τὸν οὐρανὸν φαινομένων ἐγγύθεν· καὶ γὰρ ἡ αἴσθησις ἐπιμαρτυρεῖν δύναται καὶ ἡ κοινὴ ἔννοια. φανερῶς γὰρ ἐπιπροσθεῖ τοῖς πλέουσιν ἡ κυρτότης τῆς θαλάττης, ὥστε μὴ προσβάλλειν τοῖς πόρρω φέγγεσι τοῖς ἐπ’ ἴσον ἐξῃρμένοις τῇ ὄψει. ἐξαρθέντα γοῦν πλέον τῆς ὄψεως ἐφάνη, καίτοι πλέον ἀποσχόντα αὐτῆς· ὁμοίως δὲ καὶ αὐτὴ μετεωρισθεῖσα εἶδε τὰ κεκρυμμένα πρότερον. ὅπερ δηλοῖ καὶ ὁ ποιητής· τοιοῦτον γάρ ἐστι καὶ τό “ὀξὺ μάλα προϊδών, μεγάλου ὑπὸ κύματος ἀρθείς.” καὶ τοῖς προσπλέουσι δὲ ἀεὶ καὶ μᾶλλον ἀπογυμνοῦται τὰ πρόσγεια μέρη καὶ τὰ φανέντα ἐν ἀρχαῖς ταπεινὰ ἐξαίρεται μᾶλλον. τῶν τε οὐρανίων ἡ περιφορὰ ἐναργής ἐστι καὶ ἄλλως καὶ ἐκ τῶν γνωμονικῶν· ἐκ δὲ τούτων εὐθὺς ὑποτείνει καὶ ἡ ἔννοια, ὅτι ἐρριζωμένης ἐπ’ ἄπειρον τῆς γῆς οὐκ ἂν ἡ τοιαύτη περιφορὰ συνέβαινε. καὶ τὰ περὶ τῶν κλιμάτων δὲ ἐν τοῖς περὶ τῶν οἰκήσεων δείκνυται.", "st": "1.1.20"}, {"sp": "N", "t": "νυνὶ δὲ ἐξ ἑτοίμου δεῖ λαβεῖν ἔνια, καὶ ταῦθ’ ὅσα τῷ πολιτικῷ καὶ τῷ στρατηλάτῃ χρήσιμα. οὔτε γὰρ οὕτω δεῖ ἀγνοεῖν τὰ περὶ τὸν οὐρανὸν καὶ τὴν θέσιν τῆς γῆς, ὥστ’ ἐπειδὰν γένηται κατὰ τόπους, καθ’ οὓς ἐξήλλακταί τινα τῶν φαινομένων τοῖς πολλοῖς ἐν τῷ οὐρανῷ, ταράττεσθαι καὶ τοιαῦτα λέγειν· “ὦ φίλοι, οὐ γάρ τ’ ἴδμεν ὅπη ζόφος, οὐδ’ ὅπη ἠώς, οὐδ’ ὅπη ἠέλιος φαεσίμβροτος εἶσ’ ὑπὸ γαῖαν, οὐδ’ ὅπη ἀννεῖται·” οὔθ’ οὕτως ἀκριβοῦν, ὥστε τὰς πανταχοῦ συνανατολάς τε καὶ συγκαταδύσεις καὶ συμμεσουρανήσεις καὶ ἐξάρματα πόλων καὶ τὰ κατὰ κορυφὴν σημεῖα καὶ ὅσα ἄλλα τοιαῦτα κατὰ τὰς μεταπτώσεις τῶν ὁριζόντων ἅμα καὶ τῶν ἀρκτικῶν διαφέροντα ἀπαντᾷ, τὰ μὲν πρὸς τὴν ὄψιν τὰ δὲ καὶ τῇ φύσει, γνωρίζειν ἅπαντα· ἀλλὰ τὰ μὲν μηδ’ ὅλως φροντίζειν, πλὴν εἰ θέας φιλοσόφου χάριν, τοῖς δὲ πιστεύειν, κἂν μὴ βλέπῃ τὸ διὰ τί. καὶ γὰρ τοῦτο τοῦ φιλοσοφοῦντος μόνου, τῷ δὲ πολιτικῷ σχολῆς οὐ τοσαύτης μέτεστιν ἢ οὐκ ἀεί. οὐ μὴν οὐδ’ οὕτως ὑπάρχειν ἁπλοῦν δεῖ τὸν ἐντυγχάνοντα τῇ γραφῇ ταύτῃ καὶ ἀργόν, ὥστε μηδὲ σφαῖραν ἰδεῖν, μηδὲ κύκλους ἐν αὐτῇ τοὺς μὲν παραλλήλους τοὺς δ’ ὀρθίους πρὸς τούτους τοὺς δὲ λοξούς, μηδὲ τροπικῶν τε καὶ ἰσημερινοῦ καὶ ζωδιακοῦ θέσιν, δι’ οὗ φερόμενος ὁ ἥλιος τρέπεται καὶ διδάσκει διαφορὰς κλιμάτων τε καὶ ἀνέμων. ταῦτα γὰρ καὶ τὰ περὶ τοὺς ὁρίζοντας καὶ τοὺς ἀρκτικοὺς καὶ ὅσα ἄλλα κατὰ τὴν πρώτην ἀγωγὴν τὴν εἰς τὰ μαθήματα παραδίδοται κατανοήσας τις ἄλλως πως δύναται παρακολουθεῖν τοῖς λεγομένοις ἐνταῦθα. ὁ δὲ μηδ’ εὐθεῖαν γραμμὴν ἢ περιφερῆ μηδὲ κύκλον εἰδώς, μηδὲ σφαιρικὴν ἐπιφάνειαν ἢ ἐπίπεδον, μηδ’ ἐν τῷ οὐρανῷ μηδὲ τοὺς ἑπτὰ τῆς μεγάλης ἄρκτου ἀστέρας καταμαθὼν μηδ’ ἄλλο τι τῶν τοιούτων μηδέν, ἢ οὐκ ἂν δέοιτο τῆς πραγματείας ταύτης ἢ οὐχὶ νῦν, ἀλλ’ ἐκείνοις ἐντυχὼν πρότερον, ὧν χωρὶς οὐκ ἂν εἴη γεωγραφίας οἰκεῖος. οὕτως δὲ καὶ οἱ τοὺς λιμένας καὶ τοὺς περίπλους καλουμένους πραγματευθέντες ἀτελῆ τὴν ἐπίσκεψιν ποιοῦνται, μὴ προστιθέντες ὅσα ἐκ τῶν μαθημάτων καὶ ἐκ τῶν οὐρανίων συνάπτειν προσῆκεν.", "st": "1.1.21"}, {"sp": "N", "t": "̔απλῶς δὲ κοινὸν εἶναι τὸ σύγγραμμα τοῦτο δεῖ καὶ πολιτικὸν καὶ δημωφελὲς ὁμοίως ὥσπερ τὴν τῆς ἱστορίας γραφήν. κἀκεῖ δὲ πολιτικὸν λέγομεν οὐχὶ τὸν παντάπασιν ἀπαίδευτον, ἀλλὰ τὸν μετασχόντα τῆς τε ἐγκυκλίου καὶ συνήθους ἀγωγῆς τοῖς ἐλευθέροις καὶ τοῖς φιλοσοφοῦσιν· οὐδὲ γὰρ ἂν οὔτε ψέγειν δύναιτο καλῶς οὔτ’ ἐπαινεῖν, οὐδὲ κρίνειν ὅσα μνήμης ἄξια τῶν γεγονότων, ὅτῳ μηδὲν ἐμέλησεν ἀρετῆς καὶ φρονήσεως καὶ τῶν εἰς ταῦτα λόγων.", "st": "1.1.22"}, {"sp": "N", "t": "διόπερ ἡμεῖς πεποιηκότες ὑπομνήματα ἱστορικὰ χρήσιμα, ὡς ὑπολαμβάνομεν, εἰς τὴν ἠθικὴν καὶ πολιτικὴν φιλοσοφίαν, ἔγνωμεν προσθεῖναι καὶ τήνδε τὴν σύνταξιν· ὁμοειδὴς γὰρ καὶ αὕτη, καὶ πρὸς τοὺς αὐτοὺς ἄνδρας, καὶ μάλιστα τοὺς ἐν ταῖς ὑπεροχαῖς. ἔτι δὲ τὸν αὐτὸν τρόπον, ὅνπερ ἐκεῖ τὰ περὶ τοὺς ἐπιφανεῖς ἄνδρας καὶ βίους τυγχάνει μνήμης, τὰ δὲ μικρὰ καὶ ἄδοξα παραλείπεται, κἀνταῦθα δεῖ τὰ μικρὰ καὶ τὰ ἀφανῆ παραπέμπειν, ἐν δὲ τοῖς ἐνδόξοις καὶ μεγάλοις καὶ ἐν οἷς τὸ πραγματικὸν καὶ εὐμνημόνευτον καὶ ἡδὺ διατρίβειν. καθάπερ τε καὶ ἐν τοῖς κολοσσικοῖς ἔργοις οὐ τὸ καθ’ ἕκαστον ἀκριβὲς ζητοῦμεν, ἀλλὰ τοῖς καθόλου προσέχομεν μᾶλλον εἰ καλῶς τὸ ὅλον, οὕτως κἀν τούτοις δεῖ ποιεῖσθαι τὴν κρίσιν. κολοσσουργία γάρ τις καὶ αὕτη, τὰ μεγάλα φράζουσα πῶς ἔχει καὶ τὰ ὅλα, πλὴν εἴ τι κινεῖν δύναται καὶ τῶν μικρῶν τὸν φιλειδήμονα καὶ τὸν πραγματικόν. ὅτι μὲν οὖν σπουδαῖον τὸ προκείμενον ἔργον καὶ φιλοσόφῳ πρέπον, ταῦτα εἰρήσθω.", "st": "1.1.23"}, {"sp": "N", "t": "εἰ δὲ πολλῶν προειπόντων ἐπιχειροῦμεν καὶ αὐτοὶ λέγειν περὶ τῶν αὐτῶν, οὔπω μεμπτέον, ἂν μὴ καὶ τὸν αὐτὸν τρόπον διελεγχθῶμεν ἐκείνοις ἅπαντα λέγοντες. ὑπολαμβάνομεν δ’ ἄλλων ἄλλο τι κατορθωσάντων ἄλλο πολὺ μέρος ἔτι τοῦ ἔργου λείπεσθαι· πρὸς οἷς ἂν καὶ μικρὸν προσλαβεῖν δυνηθῶμεν, ἱκανὴν δεῖ τίθεσθαι πρόφασιν τῆς ἐπιχειρήσεως. καὶ γὰρ δὴ πολύ τι τοῖς νῦν ἡ τῶν Ῥωμαίων ἐπικράτεια καὶ τῶν Παρθυαίων τῆς τοιαύτης ἐμπειρίας προσδέδωκε, καθάπερ τοῖς μετὰ τὴν Ἀλεξάνδρου στρατείαν, ὥς φησιν Ἐρατοσθένης· ὁ μὲν γὰρ τῆς Ἀσίας πολλὴν ἀνεκάλυψεν ἡμῖν καὶ τῶν βορείων τῆς Εὐρώπης ἅπαντα μέχρι τοῦ Ἴστρου· οἱ δὲ Ῥωμαῖοι τὰ ἑσπέρια τῆς Εὐρώπης ἅπαντα μέχρι Ἄλβιος ποταμοῦ τοῦ τὴν Γερμανίαν δίχα διαιροῦντος τά τε πέραν Ἴστρου τὰ μέχρι Τύρα ποταμοῦ· τὰ δὲ ἐπέκεινα μέχρι Μαιωτῶν καὶ τῆς εἰς Κόλχους τελευτώσης παραλίας Μιθριδάτης ὁ κληθεὶς Εὐπάτωρ ἐποίησε γνώριμα καὶ οἱ ἐκείνου στρατηγοί· οἱ δὲ Παρθυαῖοι τὰ περὶ τὴν Ὑρκανίαν καὶ τὴν Βακτριανὴν καὶ τοὺς ὑπὲρ τούτων Σκύθας γνωριμωτέρους ἡμῖν ἐποίησαν, ἧττον γνωριζομένους ὑπὸ τῶν πρότερον· ὥστε ἔχοιμεν ἄν τι λέγειν πλέον τῶν πρὸ ἡμῶν. ὁρᾶν δ’ ἔσται τοῦτο μάλιστα ἐν τοῖς λόγοις τοῖς πρὸς τοὺς πρὸ ἡμῶν, ἧττον μὲν τοὺς πάλαι, μᾶλλον δὲ τοὺς μετ’ Ἐρατοσθένη καὶ αὐτὸν ἐκεῖνον· οὓς εἰκὸς ὅσῳπερ πολυμαθέστεροι τῶν πολλῶν γεγόνασι, τοσούτῳ δυσελεγκτοτέρους εἶναι τοῖς ὕστερον, ἄν τι πλημμελῶς λέγωσιν. εἰ δ’ ἀναγκασθησόμεθά που τοῖς αὐτοῖς ἀντιλέγειν, οἷς μάλιστα ἐπακολουθοῦμεν κατ’ ἄλλα, δεῖ συγγνώμην ἔχειν· οὐ γὰρ πρόκειται πρὸς ἅπαντας ἀντιλέγειν, ἀλλὰ τοὺς μὲν πολλοὺς ἐᾶν, οἷς μηδὲ ἀκολουθεῖν ἄξιον, ἐκείνους δὲ διαιτᾶν, οὓς ἐν τοῖς πλείστοις κατωρθωκότας ἴσμεν, ἐπεὶ οὐδὲ πρὸς ἅπαντας φιλοσοφεῖν ἄξιον, πρὸς Ἐρατοσθένη δὲ καὶ Ἵππαρχον καὶ Ποσειδώνιον καὶ Πολύβιον καὶ ἄλλους τοιούτους καλόν.", "st": "1.2.1"}, {"sp": "N", "t": "πρῶτον δ’ ἐπισκεπτέον Ἐρατοσθένη παρατιθέντας ἅμα καὶ τὴν Ἱππάρχου πρὸς αὐτὸν ἀντιλογίαν ἔστι δ’ ὁ Ἐρατοσθένης οὔθ’ οὕτως εὐκατατρόχαστος ὥστε μηδ’ Ἀθήνας αὐτὸν ἰδεῖν φάσκειν, ὅπερ Πολέμων ἐπιχειρεῖ δεικνύναι, οὔτ’ ἐπὶ τοσοῦτον πιστὸς ἐφ’ ὅσον παρεδέξαντό τινες, καίπερ πλείστοις ἐντυχών, ὡς εἴρηκεν αὐτός, ἀγαθοῖς ἀνδράσιν. “ἐγένοντο γάρ” φησίν “ὡς οὐδέποτε, κατὰ τοῦτον τὸν καιρὸν ὑφ’ ἕνα περίβολον καὶ μίαν πόλιν οἱ κατ’ Ἀρίστωνα καὶ Ἀρκεσίλαον ἀνθήσαντες φιλόσοφοι.” οὐχ ἱκανὸν δ’ οἶμαι τοῦτο, ἀλλὰ τὸ κρίνειν καλῶς οἷς μᾶλλον προσιτέον. ὁ δὲ Ἀρκεσίλαον καὶ Ἀρίστωνα τῶν καθ’ αὑτὸν ἀνθησάντων κορυφαίους τίθησιν· Ἀπελλῆς τε αὐτῷ πολύς ἐστι καὶ Βίων, ὅν φησι πρῶτον ἀνθινὰ περιβαλεῖν φιλοσοφίαν· ἀλλ’ ὅμως πολλάκις εἰπεῖν ἄν τινα ἐπ’ αὐτοῦ τοῦτο “οἵην ἐκ ῥακέων ὁ Βίων.” ἐν αὐταῖς γὰρ ταῖς ἀποφάσεσι ταύταις ἱκανὴν ἀσθένειαν ἐμφαίνει τῆς ἑαυτοῦ γνώμης· ᾗ τοῦ Ζήνωνος τοῦ Κιτιέως γνώριμος γενόμενος Ἀθήνησι τῶν μὲν ἐκεῖνον διαδεξαμένων οὐδενὸς μέμνηται, τοὺς δ’ ἐκείνῳ διενεχθέντας καὶ ὧν διαδοχὴ οὐδεμία σώζεται, τούτους ἀνθῆσαί φησι κατὰ τὸν καιρὸν ἐκεῖνον. δηλοῖ δὲ καὶ ἡ περὶ τῶν ἀγαθῶν ἐκδοθεῖσα ὑπ’ αὐτοῦ πραγματεία καὶ μελέται καὶ εἴ τι ἄλλο τοιοῦτο τὴν ἀγωγὴν αὐτοῦ, διότι μέσος ἦν τοῦ τε βουλομένου φιλοσοφεῖν καὶ τοῦ μὴ θαρροῦντος ἐγχειρίζειν ἑαυτὸν εἰς τὴν ὑπόσχεσιν ταύτην, ἀλλὰ μόνον μέχρι τοῦ δοκεῖν προϊόντος, ἢ καὶ παράβασίν τινα ταύτην ἀπὸ τῶν ἄλλων τῶν ἐγκυκλίων πεπορισμένου πρὸς διαγωγὴν ἢ καὶ παιδιάν· τρόπον δέ τινα καὶ ἐν τοῖς ἄλλοις ἐστὶ τοιοῦτος. ἀλλ’ ἐκεῖνα ἐάσθω, πρὸς δὲ τὰ νῦν ἐπιχειρητέον ὅσα δύναιτ’ ἂν ἐπανορθοῦν τὴν γεωγραφίαν, καὶ πρῶτον ὅπερ ἀρτίως ὑπερεθέμεθα.", "st": "1.2.2"}, {"sp": "N", "t": "ποιητὴν γὰρ ἔφη πάντα στοχάζεσθαι ψυχαγωγίας, οὐ διδασκαλίας. τοὐναντίον δ’ οἱ παλαιοὶ φιλοσοφίαν τινὰ λέγουσι πρώτην τὴν ποιητικήν, εἰσάγουσαν εἰς τὸν βίον ἡμᾶς ἐκ νέων καὶ διδάσκουσαν ἤθη καὶ πάθη καὶ πράξεις μεθ’ ἡδονῆς· οἱ δ’ ἡμέτεροι καὶ μόνον ποιητὴν ἔφασαν εἶναι τὸν σοφόν. διὰ τοῦτο καὶ τοὺς παῖδας αἱ τῶν Ἑλλήνων πόλεις πρώτιστα διὰ τῆς ποιητικῆς παιδεύουσιν, οὐ ψυχαγωγίας χάριν δήπουθεν ψιλῆς, ἀλλὰ σωφρονισμοῦ· ὅπου γε καὶ οἱ μουσικοὶ ψάλλειν καὶ λυρίζειν καὶ αὐλεῖν διδάσκοντες μεταποιοῦνται τῆς ἀρετῆς ταύτης· παιδευτικοὶ γὰρ εἶναί φασι καὶ ἐπανορθωτικοὶ τῶν ἠθῶν. ταῦτα δ’ οὐ μόνον παρὰ τῶν Πυθαγορείων ἀκούειν ἐστὶ λεγόντων, ἀλλὰ καὶ Ἀριστόξενος οὕτως ἀποφαίνεται. καὶ Ὅμηρος δὲ τοὺς ἀοιδοὺς σωφρονιστὰς εἴρηκε, καθάπερ τὸν τῆς Κλυταιμνήστρας φύλακα “ᾧ πόλλ’ ἐπέτελλεν Ἀτρείδης Τροίηνδε κιὼν εἴρυσθαι ἄκοιτιν,” τόν τε Αἴγισθον οὐ πρότερον αὐτῆς περιγενέσθαι πρὶν ἢ “τὸν μὲν ἀοιδὸν ἄγων ἐς νῆσον ἐρήμην κάλλιπεν· τὴν δ’ ἐθέλων ἐθέλουσαν ἀνήγαγεν ὅνδε δόμονδε.” χωρὶς δὲ τούτων ὁ Ἐρατοσθένης ἑαυτῷ μάχεται· μικρὸν γὰρ πρὸ τῆς λεχθείσης ἀποφάσεως ἐναρχόμενος τοῦ περὶ τῆς γεωγραφίας λόγου φησὶν ἅπαντας κατ’ ἀρχὰς φιλοτίμως ἔχειν εἰς τὸ μέσον φέρειν τὴν ὑπὲρ τῶν τοιούτων ἱστορίαν. Ὅμηρον γοῦν ὑπέρ τε τῶν Αἰθιόπων ὅσα ἐπύθετο καταχωρίσαι εἰς τὴν ποίησιν καὶ περὶ τῶν κατ’ Αἴγυπτον καὶ Λιβύην, τὰ δὲ δὴ κατὰ τὴν Ἑλλάδα καὶ τοὺς σύνεγγυς τόπους καὶ λίαν περιέργως ἐξενηνοχέναι, πολυτρήρωνα μὲν τὴν Θίσβην λέγοντα, Ἁλίαρτον δὲ ποιήεντα, ἐσχατόωσαν δὲ Ἀνθηδόνα, Λίλαιαν δὲ πηγῇς ἔπι Κηφισσοῖο, καὶ οὐδεμίαν προσθήκην κενῶς ἀπορρίπτειν. πότερον οὖν ὁ ποιῶν ταῦτα ψυχαγωγοῦντι ἔοικεν ἢ διδάσκοντι; νὴ Δία, ἀλλὰ ταῦτα μὲν οὕτως εἴρηκε, τὰ δ’ ἔξω τῆς αἰσθήσεως καὶ οὗτος καὶ ἄλλοι τερατολογίας μυθικῆς πεπληρώκασιν. οὐκοῦν ἐχρῆν οὕτως εἰπεῖν, ὅτι ποιητὴς πᾶς τὰ μὲν ψυχαγωγίας χάριν μόνον ἐκφέρει τὰ δὲ διδασκαλίας· ὁ δ’ ἐπήνεγκεν ὅτι ψυχαγωγίας μόνον, διδασκαλίας δ’ οὔ. καὶ προσεξεργάζεταί γε, πυνθανόμενος τί συμβάλλεται πρὸς ἀρετὴν ποιητοῦ πολλῶν ὑπάρξαι τόπων ἔμπειρον ἢ στρατηγίας ἢ γεωργίας ἢ ῥητορικῆς ἢ οἷα δὴ περιποιεῖν αὐτῷ τινες ἐβουλήθησαν; τὸ μὲν οὖν ἅπαντα ζητεῖν περιποιεῖν αὐτῷ προεκπίπτοντος ἄν τις θείη τῇ φιλοτιμίᾳ, ὡς ἂν εἴ τις, φησὶν ὁ Ἵππαρχος, Ἀττικῆς εἰρεσιώνης κατηγοροίη καὶ ἃ μὴ δύναται φέρειν μῆλα καὶ ὄγχνας, οὕτως ἐκείνου πᾶν μάθημα καὶ πᾶσαν τέχνην. τοῦτο μὲν δὴ ὀρθῶς ἂν λέγοις, ὦ Ἐρατόσθενες· ἐκεῖνα δ’ οὐκ ὀρθῶς, ἀφαιρούμενος αὐτὸν τὴν τοσαύτην πολυμάθειαν καὶ τὴν ποιητικὴν γραώδη μυθολογίαν ἀποφαίνων, ᾗ δέδοται πλάττειν, φησίν, ὃ ἂν αὐτῇ φαίνηται ψυχαγωγίας οἰκεῖον. ἆρα γὰρ οὐδὲ τοῖς ἀκροωμένοις τῶν ποιητῶν οὐδὲν συμβάλλεται πρὸς ἀρετήν; λέγω δὲ τὸ πολλῶν ὑπάρξαι τόπων ἔμπειρον ἢ στρατηγίας ἢ γεωργίας ἢ ῥητορικῆς, ἅπερ ἡ ἀκρόασις, ὡς εἰκός, περιποιεῖ.", "st": "1.2.3"}, {"sp": "N", "t": "Ἀλλὰ μὴν ταῦτά γε πάντα ὁ ποιητὴς Ὀδυσσεῖ προσῆψεν, ὃν τῶν πάντων μάλιστα ἀρετῇ πάσῃ κοσμεῖ· οὗτος γὰρ αὐτῷ “πολλῶν ἀνθρώπων ἴδεν ἄστεα καὶ νόον ἔγνω,” οὗτος δ’ ὁ πτολίπορθος ἀεὶ λεγόμενος καὶ τὸ Ἴλιον ἑλὼν “βουλῇ καὶ μύθοισι καὶ ἠπεροπηίδι τέχνῃ·” “τούτου γ’ ἑσπομένοιο καὶ ἐκ πυρὸς αἰθομένοιο ἄμφω νοστήσαιμεν,” φησὶν ὁ Διομήδης. καὶ μὴν ἐπί γε τῇ γεωργίᾳ σεμνύνεται· καὶ γὰρ ἐν ἀμητῷ “ἐν ποίῃ δρέπανον μὲν ἐγὼν εὐκαμπὲς ἔχοιμι, καὶ δὲ σὺ τοῖον ἔχοις” καὶ ἐν ἀρότῳ, “τῷ κέ μ’ ἴδοις, εἰ ὦλκα διηνεκέα προταμοίμην.” καὶ οὐχ Ὅμηρος μὲν οὕτω φρονεῖ περὶ τούτων οὐχὶ δὲ πάντες οἱ πεπαιδευμένοι μάρτυρι χρῶνται τῷ ποιητῇ ὡς ὀρθῶς λέγοντι περὶ τοῦ τὴν τοιαύτην ἐμπειρίαν εἰς φρόνησιν συντείνειν μάλιστα.", "st": "1.2.4"}, {"sp": "N", "t": "̔η δὲ ῥητορικὴ φρόνησίς ἐστι δήπου περὶ λόγους, ἣν ἐπιδείκνυται παρ’ ὅλην τὴν ποίησιν Ὀδυσσεὺς ἐν τῇ διαπείρᾳ, ἐν ταῖς λιταῖς, ἐν τῇ πρεσβείᾳ, ἐν ᾗ φησίν “ἀλλ’ ὅτε δὴ ὄπα τε μεγάλην ἐκ στήθεος εἵη καὶ ἔπεα νιφάδεσσιν ἐοικότα χειμερίῃσιν, οὐκ ἂν ἔπειτ’ Ὀδυσῆί γ’ ἐρίσσειε βροτὸς ἄλλος.” τίς ἂν οὖν ὑπολάβοι τὸν δυνάμενον ποιητὴν εἰσάγειν ῥητορεύοντας ἑτέρους καὶ στρατηγοῦντας καὶ τὰ ἄλλα ἐπιδεικνυμένους τὰ τῆς ἀρετῆς ἔργα αὐτὸν εἶναι τῶν φλυάρων ἕνα καὶ τῶν θαυματοποιῶν, γοητεύειν μόνον καὶ κολακεύειν τὸν ἀκροατὴν δυνάμενον, ὠφελεῖν δὲ μηδέν; προτέραν δ’ οὐδ’ ἀρετὴν ποιητοῦ λέγοιμεν ἂν ἡντινοῦν ἄλλην ἢ τὴν μιμητικὴν τοῦ βίου διὰ λόγων. πῶς ἂν οὖν μιμοῖτο ἄπειρος ὢν τοῦ βίου καὶ ἄφρων; οὐ γὰρ οὕτω φαμὲν τὴν τῶν ποιητῶν ἀρετὴν ὡσεὶ τεκτόνων ἢ χαλκέων· ἀλλ’ ἐκείνη μὲν οὐδενὸς ἔχεται καλοῦ καὶ σεμνοῦ, ἡ δὲ ποιητοῦ συνέζευκται τῇ τοῦ ἀνθρώπου, καὶ οὐχ οἷόν τε ἀγαθὸν γενέσθαι ποιητὴν μὴ πρότερον γενηθέντα ἄνδρα ἀγαθόν.", "st": "1.2.5"}, {"sp": "N", "t": "τὸ δὲ δὴ καὶ τὴν ῥητορικὴν ἀφαιρεῖσθαι τὸν ποιητὴν τελέως ἀφειδοῦντος ἡμῶν ἐστι. τί γὰρ οὕτω ῥητορικὸν ὡς φράσις; τί δ’ οὕτω ποιητικόν; τίς δ’ ἀμείνων Ὁμήρου φράσαι; νὴ Δία, ἀλλ’ ἑτέρα φράσις ἡ ποιητική. τῷ γε εἴδει, ὡς καὶ ἐν αὐτῇ τῇ ποιητικῇ ἡ τραγικὴ καὶ ἡ κωμική, καὶ ἐν τῇ πεζῇ ἡ ἱστορικὴ καὶ ἡ δικανική. ἆρα γὰρ οὐδ’ ὁ λόγος ἐστὶ γενικός, οὗ εἴδη ὁ ἔμμετρος καὶ ὁ πεζός; ἢ λόγος μέν, ῥητορικὸς δὲ λόγος οὐκ ἔστι γενικὸς καὶ φράσις καὶ ἀρετὴ λόγου; ὡς δ’ εἰπεῖν, ὁ πεζὸς λόγος, ὅ γε κατεσκευασμένος, μίμημα τοῦ ποιητικοῦ ἐστι. πρώτιστα γὰρ ἡ ποιητικὴ κατασκευὴ παρῆλθεν εἰς τὸ μέσον καὶ εὐδοκίμησεν· εἶτα ἐκείνην μιμούμενοι, λύσαντες τὸ μέτρον, τἆλλα δὲ φυλάξαντες τὰ ποιητικά, συνέγραψαν οἱ περὶ Κάδμον καὶ Φερεκύδη καὶ Ἑκαταῖον· εἶτα οἱ ὕστερον ἀφαιροῦντες ἀεί τι τῶν τοιούτων εἰς τὸ νῦν εἶδος κατήγαγον ὡς ἂν ἀπὸ ὕψους τινός· καθάπερ ἄν τις καὶ τὴν κωμῳδίαν φαίη λαβεῖν τὴν σύστασιν ἀπὸ τῆς τραγῳδίας καὶ τοῦ κατ’ αὐτὴν ὕψους καταβιβασθεῖσαν εἰς τὸ λογοειδὲς νυνὶ καλούμενον. καὶ τὸ ἀείδειν δὲ ἀντὶ τοῦ φράζειν τιθέμενον παρὰ τοῖς πάλαι ταὐτὸ τοῦτο ἐκμαρτυρεῖ, διότι πηγὴ καὶ ἀρχὴ φράσεως κατεσκευασμένης καὶ ῥητορικῆς ὑπῆρξεν ἡ ποιητική. αὕτη γὰρ προσεχρήσατο τῷ μέλει κατὰ τὰς ἐπιδείξεις· τοῦτο δ’ ἦν ᾠδὴ ἢ λόγος μεμελισμένος, ἀφ’ οὗ δὴ ῥαψῳδίαν τ’ ἔλεγον καὶ τραγῳδίαν καὶ κωμῳδίαν. ὥστ’ ἐπειδὴ τὸ φράζειν πρώτιστα ἐπὶ τῆς ποιητικῆς ἐλέγετο φράσεως, αὕτη δὲ μετ’ ᾠδῆς * τὸ ἀείδειν αὐτοῖς τὸ αὐτὸ τῷ φράζειν ὑπῆρξε παρ’ ἐκείνοις. καταχρησαμένων δ’ αὐτῶν θατέρῳ καὶ ἐπὶ τοῦ πεζοῦ λόγου, καὶ ἐπὶ θάτερον ἡ κατάχρησις διέβη. καὶ αὐτὸ δὲ τὸ πεζὸν λεχθῆναι τὸν ἄνευ τοῦ μέτρου λόγον ἐμφαίνει τὸν ἀπὸ ὕψους τινὸς καταβάντα καὶ ὀχήματος εἰς τοὔδαφος.", "st": "1.2.6"}, {"sp": "N", "t": "Ἀλλ’ οὐδὲ τὰ σύνεγγυς μόνον, ὥσπερ Ἐρατοσθένης εἴρηκε, καὶ τὰ ἐν τοῖς Ἕλλησιν, ἀλλὰ καὶ τῶν πόρρω πολλὰ λέγει καὶ δι’ ἀκριβείας Ὅμηρος καὶ μᾶλλόν γε τῶν ὕστερον μυθολογεῖται, οὐ πάντα τερατευόμενος, ἀλλὰ καὶ πρὸς ἐπιστήμην ἀλληγορῶν ἢ διασκευάζων ἢ δημαγωγῶν ἄλλα τε καὶ τὰ περὶ τὴν Ὀδυσσέως πλάνην, περὶ ἧς πολλὰ διαμαρτάνει τούς τ’ ἐξηγητὰς φλυάρους ἀποφαίνων καὶ αὐτὸν τὸν ποιητήν· περὶ ὧν ἄξιον εἰπεῖν διὰ πλειόνων.", "st": "1.2.7"}, {"sp": "N", "t": "καὶ πρῶτον ὅτι τοὺς μύθους ἀπεδέξαντο οὐχ οἱ ποιηταὶ μόνον, ἀλλὰ καὶ αἱ πόλεις πολὺ πρότερον καὶ οἱ νομοθέται τοῦ χρησίμου χάριν, βλέψαντες εἰς τὸ φυσικὸν πάθος τοῦ λογικοῦ ζῴου· φιλειδήμων γὰρ ἅνθρωπος, προοίμιον δὲ τούτου τὸ φιλόμυθον. ἐντεῦθεν οὖν ἄρχεται τὰ παιδία ἀκροᾶσθαι καὶ κοινωνεῖν λόγων ἐπὶ πλεῖον. αἴτιον δ’, ὅτι καινολογία τίς ἐστιν ὁ μῦθος, οὐ τὰ καθεστηκότα φράζων ἀλλ’ ἕτερα παρὰ ταῦτα· ἡδὺ δὲ τὸ καινὸν καὶ ὃ μὴ πρότερον ἔγνω τις· τοῦτο δ’ αὐτό ἐστι καὶ τὸ ποιοῦν φιλειδήμονα. ὅταν δὲ προσῇ καὶ τὸ θαυμαστὸν καὶ τὸ τερατῶδες, ἐπιτείνει τὴν ἡδονήν, ἥπερ ἐστὶ τοῦ μανθάνειν φίλτρον. κατ’ ἀρχὰς μὲν οὖν ἀνάγκη τοιούτοις δελέασι χρῆσθαι, προϊούσης δὲ τῆς ἡλικίας ἐπὶ τὴν τῶν ὄντων μάθησιν ἄγειν, ἤδη τῆς διανοίας ἐρρωμένης καὶ μηκέτι δεομένης κολάκων. καὶ ἰδιώτης δὲ πᾶς καὶ ἀπαίδευτος τρόπον τινὰ παῖς ἐστι φιλομυθεῖ τε ὡσαύτως· ὁμοίως δὲ καὶ ὁ πεπαιδευμένος μετρίως· οὐδὲ γὰρ οὗτος ἰσχύει τῷ λογισμῷ, πρόσεστι δὲ καὶ τὸ ἐκ παιδὸς ἔθος. ἐπεὶ δ’ οὐ μόνον ἡδὺ ἀλλὰ καὶ φοβερὸν τὸ τερατῶδες, ἀμφοτέρων ἐστὶ τῶν εἰδῶν χρεία πρός τε τοὺς παῖδας καὶ τοὺς ἐν ἡλικίᾳ· τοῖς τε γὰρ παισὶ προσφέρομεν τοὺς ἡδεῖς μύθους εἰς προτροπήν, εἰς ἀποτροπὴν δὲ τοὺς φοβερούς· ἥ τε γὰρ Λάμια μῦθός ἐστι καὶ ἡ Γοργὼ καὶ ὁ Ἐφιάλτης καὶ ἡ Μορμολύκη. οἵ τε πολλοὶ τῶν τὰς πόλεις οἰκούντων εἰς μὲν προτροπὴν ἄγονται τοῖς ἡδέσι τῶν μύθων, ὅταν ἀκούωσι τῶν ποιητῶν ἀνδραγαθήματα μυθώδη διηγουμένων, οἷον Ἡρακλέους ἄθλους ἢ Θησέως, ἢ τιμὰς παρὰ θεῶν νεμομένας, ἢ νὴ Δία ὁρῶσι γραφὰς ἢ ξόανα ἢ πλάσματα τοιαύτην τινὰ περιπέτειαν ὑποσημαίνοντα μυθώδη· εἰς ἀποτροπὴν δέ, ὅταν κολάσεις παρὰ θεῶν καὶ φόβους καὶ ἀπειλὰς ἢ διὰ λόγων ἢ διὰ τύπων ἀοράτων τινῶν προσδέχωνται, ἢ καὶ πιστεύωσι περιπεσεῖν τινας. οὐ γὰρ ὄχλον γε γυναικῶν καὶ παντὸς χυδαίου πλήθους ἐπαγαγεῖν λόγῳ δυνατὸν φιλοσόφῳ καὶ προσκαλέσασθαι πρὸς εὐσέβειαν καὶ ὁσιότητα καὶ πίστιν, ἀλλὰ δεῖ καὶ διὰ δεισιδαιμονίας· τοῦτο δ’ οὐκ ἄνευ μυθοποιίας καὶ τερατείας. κεραυνὸς γὰρ καὶ αἰγὶς καὶ τρίαινα καὶ λαμπάδες καὶ δράκοντες καὶ θυρσόλογχα τῶν θεῶν ὅπλα μῦθοι καὶ πᾶσα θεολογία ἀρχαϊκή· ταῦτα δ’ ἀπεδέξαντο οἱ τὰς πολιτείας καταστησάμενοι μορμολύκας τινὰς πρὸς τοὺς νηπιόφρονας. τοιαύτης δὲ τῆς μυθοποιίας οὔσης καὶ καταστρεφούσης εἰς τὸ κοινωνικὸν καὶ τὸ πολιτικὸν τοῦ βίου σχῆμα καὶ τὴν τῶν ὄντων ἱστορίαν, οἱ μὲν ἀρχαῖοι τὴν παιδικὴν ἀγωγὴν ἐφύλαξαν μέχρι τῶν τελείων ἡλικιῶν, καὶ διὰ ποιητικῆς ἱκανῶς σωφρονίζεσθαι πᾶσαν ἡλικίαν ὑπέλαβον· χρόνοις δ’ ὕστερον ἡ τῆς ἱστορίας γραφὴ καὶ ἡ νῦν φιλοσοφία παρελήλυθεν εἰς μέσον. αὕτη μὲν οὖν πρὸς ὀλίγους, ἡ δὲ ποιητικὴ δημωφελεστέρα καὶ θέατρα πληροῦν δυναμένη, ἡ δὲ δὴ τοῦ Ὁμήρου ὑπερβαλλόντως· καὶ οἱ πρῶτοι δὲ ἱστορικοὶ καὶ φυσικοὶ μυθογράφοι.", "st": "1.2.8"}, {"sp": "N", "t": "̔́ατε δὴ πρὸς τὸ παιδευτικὸν εἶδος τοὺς μύθους ἀναφέρων ὁ ποιητὴς ἐφρόντισε πολὺ μέρος τἀληθοῦς, ἐν δ’ ἐτίθει καὶ ψεῦδος, τὸ μὲν ἀποδεχόμενος τῷ δὲ δημαγωγῶν καὶ στρατηγῶν τὰ πλήθη. “ὡς δ’ ὅτε τις χρυσὸν περιχεύεται ἀργύρῳ ἀνήρ,” οὕτως ἐκεῖνος ταῖς ἀληθέσι περιπετείαις προσεπετίθει μῦθον, ἡδύνων καὶ κοσμῶν τὴν φράσιν, πρὸς δὲ τὸ αὐτὸ τέλος τοῦ ἱστορικοῦ καὶ τοῦ τὰ ὄντα λέγοντος βλέπων. οὕτω δὴ τόν τε Ἰλιακὸν πόλεμον γεγονότα παραλαβὼν ἐκόσμησε ταῖς μυθοποιίαις, καὶ τὴν Ὀδυσσέως πλάνην ὡσαύτως· ἐκ μηδενὸς δὲ ἀληθοῦς ἀνάπτειν κενὴν τερατολογίαν οὐχ Ὁμηρικόν. προσπίπτει γάρ, ὡς εἰκός, ὡς πιθανώτερον ἂν οὕτω τις ψεύδοιτο, εἰ καταμίσγοι τι καὶ αὐτῶν τῶν ἀληθινῶν· ὅπερ καὶ Πολύβιός φησι περὶ τῆς Ὀδυσσέως πλάνης ἐπιχειρῶν· τοιοῦτο δ’ ἐστὶ καὶ τό “ἴσκε ψεύδεα πολλὰ λέγων ἐτύμοισιν ὁμοῖα.” οὐ γὰρ πάντα ἀλλὰ πολλά, ἐπεὶ οὐδ’ ἂν ἦν ἐτύμοισιν ὁμοῖα. ἔλαβεν οὖν παρὰ τῆς ἱστορίας τὰς ἀρχάς. καὶ γὰρ τὸν Αἰόλον δυναστεῦσαί φασι τῶν περὶ τὴν Λιπάραν νήσων καὶ τῶν περὶ τὴν Αἴτνην καὶ Λεοντίνην Κύκλωπας καὶ Λαιστρυγόνας ἀξένους τινάς· διὸ καὶ τὰ περὶ τὸν πορθμὸν ἀπροσπέλαστα εἶναι τοῖς τότε καὶ τὴν Χάρυβδιν καὶ τὸ Σκύλλαιον ὑπὸ λῃστῶν κατέχεσθαι. οὕτω δὲ καὶ τοὺς ἄλλους τῶν ὑπὸ Ὁμήρου λεγομένων ἐν ἄλλοις τόποις ἱστοροῦμεν· οὕτω δὲ καὶ τοὺς Κιμμερίους εἰδὼς οἰκοῦντας τὸν Κιμμερικὸν Βόσπορον πρὸς βορρᾶν καὶ ζοφώδη μετήγαγεν οἰκείως εἰς σκοτεινόν τινα τόπον τὸν καθ’ ᾄδην, χρήσιμον ὄντα πρὸς τὴν μυθοποιίαν τὴν ἐν τῇ πλάνῃ. ὅτι δ’ οἶδεν αὐτούς, οἱ χρονογράφοι δηλοῦσιν ἢ μικρὸν πρὸ αὐτοῦ τὴν τῶν Κιμμερίων ἔφοδον ἢ κατ’ αὐτὸν ἀναγράφοντες.", "st": "1.2.9"}, {"sp": "N", "t": "̔ωσαύτως καὶ τοὺς Κόλχους εἰδὼς καὶ τὸν Ἰάσονος πλοῦν τὸν εἰς Αἶαν καὶ τὰ περὶ Κίρκης καὶ Μηδείας μυθευόμενα καὶ ἱστορούμενα περὶ τῆς φαρμακείας καὶ τῆς ἄλλης ὁμοιοτροπίας συγγενείας τε ἔπλασε τῶν οὕτω διῳκισμένων, τῆς μὲν ἐν τῷ μυχῷ τοῦ Πόντου τῆς δ’ ἐν τῇ Ἰταλίᾳ, καὶ ἐξωκεανισμὸν ἀμφοῖν, τάχα καὶ τοῦ Ἰάσονος μέχρι τῆς Ἰταλίας πλανηθέντος· δείκνυται γάρ τινα καὶ περὶ τὰ Κεραύνια ὄρη καὶ περὶ τὸν Ἀδρίαν καὶ ἐν τῷ Ποσειδωνιάτῃ κόλπῳ καὶ ταῖς πρὸ τῆς Τυρρηνίας νήσοις τῆς τῶν Ἀργοναυτῶν πλάνης σημεῖα. προσέδοσαν δέ τι καὶ αἱ Κυάνεαι, ἅσπερ Συμπληγάδας καλοῦσι πέτρας τινές, τραχὺν ποιοῦσαι τὸν διέκπλουν τὸν διὰ τοῦ Βυζαντιακοῦ στόματος· ὥστε παρὰ μὲν τὴν Αἶαν ἡ Αἰαίη, παρὰ δὲ τὰς Συμπληγάδας αἱ Πλαγκταὶ καὶ ὁ δι’ αὐτῶν πλοῦς τοῦ Ἰάσονος πιθανὸς ἐφάνη, παρὰ δὲ τὴν Σκύλλαν καὶ τὴν Χάρυβδιν ὁ διὰ τῶν σκοπέλων πλοῦς. ἁπλῶς δ’ οἱ τότε τὸ πέλαγος τὸ Ποντικὸν ὥσπερ ἄλλον τινὰ ὠκεανὸν ὑπελάμβανον, καὶ τοὺς πλέοντας ἐκεῖσε ὁμοίως ἐκτοπίζειν ἐδόκουν ὥσπερ τοὺς ἔξω στηλῶν ἐπὶ πολὺ προϊόντας· καὶ γὰρ μέγιστον τῶν καθ’ ἡμᾶς ἐνομίζετο, καὶ διὰ τοῦτο κατ’ ἐξοχὴν ἰδίως πόντον προσηγόρευον, ὡς ποιητὴν Ὅμηρον. ἴσως οὖν καὶ διὰ τοῦτο μετήνεγκε τὰ ἐκ τοῦ Πόντου πρὸς τὸν ὠκεανὸν ὡς εὐπαράδεκτα διὰ τὴν κατέχουσαν δόξαν. οἶμαι δὲ καὶ τῶν Σολύμων τὰ ἄκρα τοῦ Ταύρου τὰ περὶ τὴν Λυκίαν ἕως Πισιδίας κατεχόντων τὰ ὑψηλότατα καὶ τὰς ἀπὸ τῆς μεσημβρίας ὑπερβολὰς ἐπιφανεστάτας παρεχόντων τοῖς ἐντὸς τοῦ Ταύρου καὶ μάλιστα τοῖς περὶ τὸν Πόντον, καθ’ ὁμοιότητά τινα καὶ τούτους ἐξωκεανισθῆναι· φησὶ γὰρ ἐπὶ τοῦ πλέοντος ἐν τῇ σχεδίᾳ “τὸν δ’ ἐξ Αἰθιόπων ἀνιὼν κρείων Ἐνοσίχθων τηλόθεν ἐκ Σολύμων ὀρέων ἴδεν.” τάχα δὲ καὶ τοὺς μονομμάτους Κύκλωπας ἐκ τῆς Σκυθικῆς ἱστορίας μετενήνοχε· τοιούτους γάρ τινας τοὺς Ἀριμασπούς φασιν, οὓς ἐν τοῖς Ἀριμασπείοις ἔπεσιν ἐνδέδωκεν Ἀριστέας ὁ Προκοννήσιος.", "st": "1.2.10"}, {"sp": "N", "t": "δεῖ δὲ ταῦτα προϋποθέμενον σκοπεῖν τί λέγουσιν οἱ φήσαντες περὶ Σικελίαν ἢ Ἰταλίαν γενέσθαι τῷ Ὀδυσσεῖ τὴν πλάνην καθ’ Ὅμηρον· ἔστι γὰρ ἀμφοτέρως τοῦτο δέξασθαι, καὶ βέλτιον καὶ χεῖρον· βέλτιον μέν, ἂν οὕτω [τις] δέχηται ὅτι πεισθεὶς ἐκεῖ τὴν πλάνην τῷ Ὀδυσσεῖ γενέσθαι, λαβὼν ἀληθῆ ταύτην τὴν ὑπόθεσιν ποιητικῶς διεσκεύασε· τοῦτο γὰρ οἰκείως ἂν λέγοιτο περὶ αὐτοῦ· καὶ οὐ μόνον γε περὶ Ἰταλίαν, ἀλλὰ καὶ μέχρι τῶν ἐσχάτων τῆς Ἰβηρίας ἐστὶν εὑρεῖν ἴχνη τῆς ἐκείνου πλάνης καὶ ἄλλων πλειόνων. χεῖρον δέ, ἐάν τις καὶ τὴν διασκευὴν ὡς ἱστορίαν δέχηται, ἐκείνου ὠκεανὸν καὶ ᾄδην καὶ Ἡλίου βόας καὶ παρὰ θεαῖς ξενίας καὶ μεταμορφώσεις καὶ μεγέθη Κυκλώπων καὶ Λαιστρυγόνων καὶ μορφὴν Σκύλλης καὶ διαστήματα πλοῦ καὶ ἄλλα πλείω τοιαῦτα τερατογραφοῦντος φανερῶς. οὔτε δὲ πρὸς τοῦτον ἄξιον ἀντιλέγειν οὕτω φανερῶς καταψευδόμενον τοῦ ποιητοῦ, καθάπερ οὐδ’ εἰ φαίη τοῦτον τὸν τρόπον γενέσθαι τὸν εἰς τὴν Ἰθάκην κατάπλουν τοῦ Ὀδυσσέως καὶ τὴν μνηστηροφονίαν καὶ τὴν ἐπὶ τοῦ ἀγροῦ συστᾶσαν μάχην τοῖς Ἰθακησίοις πρὸς αὐτόν, οὔτε πρὸς τὸν δεξάμενον οἰκείως προσπλέκεσθαι δίκαιον.", "st": "1.2.11"}, {"sp": "N", "t": "̔ο Ἐρατοσθένης δὲ πρὸς ἀμφοτέρας τὰς ἀποφάσεις ἀπήντηκεν οὐκ εὖ· πρὸς μὲν τὴν δευτέραν, ὅτι πειρᾶται διαβάλλειν φανερῶς ψευδῆ καὶ οὐκ ἄξια λόγου διὰ μακρῶν, πρὸς δὲ τὴν προτέραν, ποιητήν τε ἅπαντα ἀποφήνας φλύαρον καὶ μήτε τόπων ἐμπειρίαν μήτε τεχνῶν πρὸς ἀρετὴν συντείνειν νομίσας· τῶν τε μύθων τῶν μὲν ἐν τόποις οὐ πεπλασμένοις πεφημισμένων, οἷον ἐν Ἰλίῳ καὶ Ἴδῃ καὶ Πηλίῳ, τῶν δὲ ἐν πεπλασμένοις, καθάπερ ἐν οἷς αἱ Γοργόνες ἢ ὁ Γηρυόνης, ταύτης φησὶ τῆς ἰδέας εἶναι καὶ τοὺς κατὰ τὴν Ὀδυσσέως πλάνην λεγομένους, τοὺς δὲ μὴ πεπλάσθαι λέγοντας ἀλλ’ ὑποκεῖσθαι ἐξ αὐτοῦ τοῦ μὴ συμφωνεῖν ἐλέγχεσθαι ψευδομένους· τὰς γοῦν Σειρῆνας τοὺς μὲν ἐπὶ τῆς Πελωριάδος καθιδρύειν, τοὺς δὲ ἐπὶ τῶν Σειρηνουσσῶν πλείους ἢ δισχιλίους διεχουσῶν σταδίους· εἶναι δ’ αὐτὰς σκόπελον τρικόρυφον διείργοντα τὸν Κυμαῖον καὶ Ποσειδωνιάτην κόλπον. ἀλλ’ οὔθ’ ὁ σκόπελος οὗτος ἐστὶ τρικόρυφος οὔθ’ ὅλως κορυφοῦται πρὸς ὕψος, ἀλλ’ ἀγκών τις ἔκκειται μακρὸς καὶ στενὸς ἀπὸ τῶν κατὰ Συρρεντὸν χωρίων ἐπὶ τὸν κατὰ Καπρίας πορθμόν, ἐπὶ θάτερα μὲν τῆς ὀρεινῆς τὸ τῶν Σειρήνων ἱερὸν ἔχων, ἐπὶ θάτερα δὲ πρὸς τῷ Ποσειδωνιάτῃ κόλπῳ νησίδια τρία προκείμενα ἔρημα πετρώδη, ἃ καλοῦσι Σειρῆνας, ἐπ’ αὐτῷ δὲ τῷ πορθμῷ τὸ Ἀθήναιον, ᾧπερ ὁμωνυμεῖ καὶ ὁ ἀγκὼν αὐτός.", "st": "1.2.12"}, {"sp": "N", "t": "Ἀλλ’ οὐδ’ εἰ μὴ συμφωνοῦσιν οἱ τὴν ἱστορίαν τῶν τόπων παραδιδόντες, εὐθὺς ἐκβάλλειν δεῖ τὴν σύμπασαν ἱστορίαν· ἀλλ’ ἔσθ’ ὅτε καὶ πιστοῦσθαι τὸ καθόλου μᾶλλόν ἐστιν. οἷόν τι λέγω, ζητουμένου εἰ κατὰ Σικελίαν καὶ Ἰταλίαν ἡ πλάνη γέγονε καὶ εἰ αἱ Σειρῆνες ἐνταῦθά που λέγονται· ὁ μὲν φήσας ἐν τῇ Πελωριάδι πρὸς τὸν ἐν ταῖς Σειρηνούσσαις διαφωνεῖ, ἀμφότεροι δὲ πρὸς τὸν περὶ Σικελίαν καὶ Ἰταλίαν λέγοντα οὐ διαφωνοῦσιν, ἀλλὰ καὶ μείζω πίστιν παρέχουσιν, ὅτι καίπερ μὴ τὸ αὐτὸ χωρίον φράζοντες ὅμως οὐκ ἐκβεβήκεσάν γε τοῦ κατὰ τὴν Ἰταλίαν ἢ Σικελίαν. ἐὰν δὲ προσθῇ τις ὅτι ἐν Νεαπόλει Παρθενόπης δείκνυται μνῆμα μιᾶς τῶν Σειρήνων, ἔτι πλείων προσεγένετο πίστις, καίτοι τρίτου τινὸς λεχθέντος τούτου τοῦ τόπου. ἀλλ’ ὅτι ἐν τούτῳ τῷ κόλπῳ τῷ ὑπὸ Ἐρατοσθένους λεχθέντι Κυμαίῳ, ὃν ποιοῦσιν αἱ Σειρηνοῦσσαι, καὶ ἡ Νεάπολις ἵδρυται, βεβαιοτέρως πιστεύομεν τὸ περὶ τούτους τοὺς τόπους γεγονέναι τὰς Σειρῆνας· οὔτε γὰρ τὸν ποιητὴν ἀκριβῶς ἕκαστα πυθέσθαι, οὔθ’ ἡμεῖς παρ’ ἐκείνου ζητοῦμεν τὸ ἀκριβές· οὐ μὴν οὐδ’ οὕτως ἔχομεν ὡς ὑπολαμβάνειν καὶ μηδὲν πεπυσμένον περὶ τῆς πλάνης, μήθ’ ὅπου μήθ’ ὅπως γεγένηται, ῥαψῳδεῖν.", "st": "1.2.13"}, {"sp": "N", "t": "Ἐρατοσθένης δὲ Ἡσίοδον μὲν εἰκάζει πεπυσμένον περὶ τῆς Ὀδυσσέως πλάνης ὅτι κατὰ Σικελίαν καὶ Ἰταλίαν γεγένηται, πιστεύσαντα τῇ δόξῃ μὴ μόνον τῶν ὑφ’ Ὁμήρου λεγομένων μεμνῆσθαι, ἀλλὰ καὶ Αἴτνης καὶ Ὀρτυγίας τοῦ πρὸς Συρακούσαις νησίου καὶ Τυρρηνῶν· Ὅμηρον δὲ μήτε εἰδέναι ταῦτα μήτε βούλεσθαι ἐν γνωρίμοις τόποις ποιεῖν τὴν πλάνην. πότερον οὖν Αἴτνη μὲν καὶ Τυρρηνία γνώριμα, Σκύλλαιον δὲ καὶ Χάρυβδις καὶ Κίρκαιον καὶ Σειρηνοῦσσαι οὐ πάνυ; ἢ καὶ Ἡσιόδῳ μὲν ἔπρεπε μὴ φλυαρεῖν, ἀλλὰ ταῖς κατεχούσαις δόξαις ἀκολουθεῖν, Ὁμήρῳ δὲ πᾶν ὅ τι ἂν ἐπ’ ἀκαιρίμαν γλῶσσαν ἴῃ κελαδεῖν; χωρὶς γὰρ τῶν λεχθέντων περὶ τοῦ τρόπου τῆς πρεπούσης Ὁμήρῳ μυθοποιίας καὶ τὸ πλῆθος τῶν συγγραφέων τῶν ταὐτὰ θρυλούντων κἀκ τῆς κατὰ τοὺς τόπους ἐπιχωριαζούσης φήμης διδάσκειν δύναται, διότι ταῦτα οὐ ποιητῶν πλάσματά ἐστιν οὐδὲ συγγραφέων, ἀλλὰ γεγενημένων ἴχνη καὶ προσώπων καὶ πράξεων.", "st": "1.2.14"}, {"sp": "N", "t": "καὶ Πολύβιος δ’ ὀρθῶς ὑπονοεῖ τὰ περὶ τῆς πλάνης· τὸν γὰρ Αἰόλον τὸν προσημαίνοντα τοὺς ἔκπλους ἐν τοῖς κατὰ τὸν πορθμὸν τόποις ἀμφιδρόμοις οὖσι καὶ δυσέκπλοις διὰ τὰς παλιρροίας ταμίαν τε εἰρῆσθαι τῶν ἀνέμων καὶ βασιλέα νενομίσθαι φησί, καθάπερ Δαναὸν μὲν τὰ ὑδρεῖα τὰ ἐν Ἄργει παραδείξαντα, Ἀτρέα δὲ τοῦ ἡλίου τὸν ὑπεναντίον τῷ οὐρανῷ δρόμον, μάντεις τε καὶ ἱεροσκοπουμένους ἀποδείκνυσθαι βασιλέας, τούς θ’ ἱερέας τῶν Αἰγυπτίων καὶ Χαλδαίους καὶ Μάγους σοφίᾳ τινὶ διαφέροντας τῶν ἄλλων ἡγεμονίας καὶ τιμῆς τυγχάνειν παρὰ τοῖς πρὸ ἡμῶν, οὕτω δὲ καὶ τῶν θεῶν ἕνα ἕκαστον τῶν χρησίμων τινὸς εὑρετὴν γενόμενον τιμᾶσθαι. ταῦτα δὲ προοικονομησάμενος οὐκ ἐᾷ τὸν Αἰόλον ἐν μύθου σχήματι ἀκούεσθαι οὐδ’ ὅλην τὴν Ὀδυσσέως πλάνην, ἀλλὰ μικρὰ μὲν προσμεμυθεῦσθαι καθάπερ καὶ τῷ Ἰλιακῷ πολέμῳ, τὸ δ’ ὅλον περὶ Σικελίαν καὶ τῷ ποιητῇ πεποιῆσθαι καὶ τοῖς ἄλλοις συγγραφεῦσιν, ὅσοι τὰ περιχώρια λέγουσι τὰ περὶ τὴν Ἰταλίαν καὶ Σικελίαν. οὐκ ἐπαινεῖ δὲ οὐδὲ τὴν τοιαύτην τοῦ Ἐρατοσθένους ἀπόφασιν, διότι φησὶ τότ’ ἂν εὑρεῖν τινα ποῦ Ὀδυσσεὺς πεπλάνηται, ὅταν εὕρῃ τὸν σκυτέα τὸν συρράψαντα τὸν τῶν ἀνέμων ἀσκόν. καὶ τοῦτο δ’ οἰκείως εἰρῆσθαι τοῖς συμβαίνουσι περὶ τὸ Σκύλλαιον καὶ τὴν θήραν τῶν γαλεωτῶν τὸ ἐπὶ τῆς Σκύλλης “αὐτοῦ δ’ ἰχθυάᾳ σκόπελον περιμαιμώωσα δελφῖνάς τε κύνας τε, καὶ εἴ ποθι μεῖζον ἕλῃσι κῆτος.” τοὺς γὰρ θύννους ἀγεληδὸν φερομένους παρὰ τὴν Ἰταλίαν, ἐπειδὰν ἐμπέσωσι καὶ κωλυθῶσι τῆς Σικελίας ἅψασθαι, περιπίπτειν τοῖς μείζοσι τῶν ζῴων, οἷον δελφίνων καὶ κυνῶν καὶ ἄλλων κητωδῶν, ἐκ δὲ τῆς θήρας αὐτῶν πιαίνεσθαι τοὺς γαλεώτας, οὓς καὶ ξιφίας λέγεσθαι καὶ κύνας φησί· συμβαίνειν γὰρ ταὐτὸν ἐνθάδε καὶ κατὰ τὰς ἀναβάσεις τοῦ Νείλου καὶ τῶν ἄλλων ὑδάτων, ὅπερ ἐπὶ πυρὸς καὶ ὕλης ἐμπιπραμένης· ἀθροιζόμενα γὰρ τὰ θηρία φεύγειν τὸ πῦρ ἢ τὸ ὕδωρ καὶ βορὰν γίνεσθαι τοῖς κρείττοσι.", "st": "1.2.15"}, {"sp": "N", "t": "ταῦτα δ’ εἰπὼν διηγεῖται τῶν γαλεωτῶν θήραν, ἣ συνίσταται περὶ τὸ Σκύλλαιον· σκοπὸς γὰρ ἐφέστηκε κοινὸς ὑφορμοῦσιν ἐν δικώποις σκαφιδίοις πολλοῖς, δύο καθ’ ἕκαστον σκαφίδιον· καὶ ὁ μὲν ἐλαύνει, ὁ δ’ ἐπὶ τῆς πρώρας ἕστηκε δόρυ ἔχων, σημήναντος τοῦ σκοποῦ τὴν ἐπιφάνειαν τοῦ γαλεώτου· φέρεται δὲ τὸ τρίτον μέρος ἔξαλον τὸ ζῷον. συνάψαντος δὲ τοῦ σκάφους, ὁ μὲν ἔπληξεν ἐκ χειρός, εἶτ’ ἐξέσπασεν ἐκ τοῦ σώματος τὸ δόρυ χωρὶς τῆς ἐπιδορατίδος· ἀγκιστρώδης τε γάρ ἐστι καὶ χαλαρῶς ἐνήρμοσται τῷ δόρατι ἐπίτηδες, καλώδιον δ’ ἔχει μακρὸν ἐξημμένον· τοῦτ’ ἐπιχαλῶσι τῷ τρωθέντι τέως ἕως ἂν κάμῃ σφαδάζον καὶ ὑποφεῦγον· τότε δ’ ἕλκουσιν ἐπὶ τὴν γῆν, ἢ εἰς τὸ σκάφος ἀναλαμβάνουσιν, ἐὰν μὴ μέγα ᾖ τελέως τὸ σῶμα. κἂν ἐκπέσῃ δὲ εἰς τὴν θάλατταν τὸ δόρυ, οὐκ ἀπόλωλεν· ἔστι γὰρ πηκτὸν ἔκ τε δρυὸς καὶ ἐλάτης, ὥστε βαπτιζομένου τοῦ δρυΐνου βάρει μετέωρον εἶναι τὸ λοιπὸν καὶ εὐανάληπτον. συμβαίνειν δέ ποτε καὶ τιτρώσκεσθαι διὰ τοῦ σκαφιδίου τὸν κωπηλάτην διὰ τὸ μέγεθος τοῦ ξίφους τῶν γαλεωτῶν καὶ τὸ τὴν ἀκμὴν τοῦ ζῴου συαγρώδη εἶναι καὶ τὴν θήραν. ἔκ τε δὴ τῶν τοιούτων εἰκάζοι τις ἄν, φησί, περὶ Σικελίαν γενέσθαι τὴν πλάνην κατὰ τὸν Ὅμηρον, ὅτι τῇ Σκύλλῃ προσῆψε τὴν τοιαύτην θήραν ἣ μάλιστ’ ἐπιχώριός ἐστι τῷ Σκυλλαίῳ, καὶ ἐκ τῶν περὶ τῆς Χαρύβδεως λεγομένων ὁμοίων τοῖς τοῦ πορθμοῦ πάθεσι. τὸ δέ “τρὶς μὲν γάρ τ’ ἀνίησιν” ἀντὶ τοῦ δίς, γραφικὸν εἶναι ἁμάρτημα ἢ ἱστορικόν.", "st": "1.2.16"}, {"sp": "N", "t": "καὶ τὰ ἐν τῇ Μήνιγγι δὲ τοῖς περὶ τῶν Λωτοφάγων εἰρημένοις συμφωνεῖν. εἰ δέ τινα μὴ συμφωνεῖ, μεταβολὰς αἰτιᾶσθαι δεῖν ἢ ἄγνοιαν ἢ καὶ ποιητικὴν ἐξουσίαν, ἣ συνέστηκεν ἐξ ἱστορίας καὶ διαθέσεως καὶ μύθου. τῆς μὲν οὖν ἱστορίας ἀλήθειαν εἶναι τέλος, ὡς ἐν νεῶν καταλόγῳ τὰ ἑκάστοις τόποις συμβεβηκότα λέγοντος τοῦ ποιητοῦ, τὴν μὲν πετρήεσσαν τὴν δὲ ἐσχατόωσαν πόλιν, ἄλλην δὲ πολυτρήρωνα, τὴν δ’ ἀγχίαλον· τῆς δὲ διαθέσεως ἐνέργειαν εἶναι τὸ τέλος, ὡς ὅταν μαχομένους εἰσάγῃ, μύθου δὲ ἡδονὴν καὶ ἔκπληξιν. τὸ δὲ πάντα πλάττειν οὐ πιθανόν, οὐδ’ Ὁμηρικόν· τὴν γὰρ ἐκείνου ποίησιν φιλοσόφημα πάντας νομίζειν, οὐχ ὡς Ἐρατοσθένης φησί, κελεύων μὴ κρίνειν πρὸς τὴν διάνοιαν τὰ ποιήματα, μηδ’ ἱστορίαν ἀπ’ αὐτῶν ζητεῖν. πιθανώτερόν τε τό “ἔνθεν δ’ ἐννῆμαρ φερόμην ὀλοοῖς ἀνέμοισιν” ἐν βραχεῖ διαστήματι δέχεσθαι (οἱ γὰρ ὀλοοὶ οὐκ εὐθύδρομοι) ἢ ἐξωκεανίζειν, ὡς ἂν οὐρίων πνεόντων συνεχῶς. συνθεὶς δὲ τὸ διάστημα τὸ ἐκ Μαλεῶν ἐπὶ στήλας σταδίων δισμυρίων καὶ δισχιλίων πεντακοσίων, εἰ, φησί, τοῦτο θείημεν ἐν ταῖς ἐννέα ἡμέραις διηνύσθαι ἰσοταχῶς, ἑκάστης ἂν ἡμέρας ὁ πλοῦς συμβαίνοι σταδίων δισχιλίων πεντακοσίων. τίς οὖν ἱστόρηκεν ἐκ Λυκίας ἢ Ῥόδου δευτεραῖόν τινα ἀφιγμένον εἰς Ἀλεξάνδρειαν, ὄντος τοῦ διαστήματος σταδίων τετρακισχιλίων; πρὸς δὲ τοὺς ἐπιζητοῦντας πῶς τρὶς εἰς Σικελίαν ἐλθὼν οὐδ’ ἅπαξ διὰ τοῦ πορθμοῦ πέπλευκεν Ὀδυσσεύς, ἀπολογεῖται διότι καὶ οἱ ὕστερον ἔφευγον ἅπαντες τὸν πλοῦν τοῦτον.", "st": "1.2.17"}, {"sp": "N", "t": "τοιαῦτα μὲν εἴρηκεν. ἔστι δὲ τἆλλα μὲν εὖ λεγόμενα· ὅταν δ’ ἀνασκευάζῃ τὸν ἐξωκεανιζόμενον καὶ πρὸς ἀκριβῆ μέτρα τὸν τῶν ἡμερῶν πλοῦν ἀνάγῃ καὶ διαστήματα, ὑπερβολὴν οὐκ ἀπολείπει τῆς ἀνομολογίας. ἅμα μὲν γὰρ παρατίθησι τὰ τοῦ ποιητοῦ ἔπη “ἔνθεν δ’ ἐννῆμαρ φερόμην ὀλοοῖς ἀνέμοισιν,” ἅμα δ’ ἐπικρύπτεται· καὶ γὰρ ταῦτα τοῦ ποιητοῦ “αὐτὰρ ἐπεὶ ποταμοῖο λίπεν ῥόον ὠκεανοῖο νηῦς,” καὶ τὸ “νήσῳ ἐν Ὠγυγίῃ, ὅθι τ’ ὀμφαλός ἐστι θαλάσσης,” καὶ ὅτι ἐνταῦθα οἰκεῖ Ἄτλαντος θυγάτηρ, καὶ τὸ περὶ τῶν Φαιάκων “οἰκέομεν δ’ ἀπάνευθε πολυκλύστῳ ἐνὶ πόντῳ ἔσχατοι· οὐ δέ τις ἄμμι βροτῶν ἐπιμίσγεται ἄλλος.” ταῦτα γὰρ πάντα φανερῶς ἐν τῷ Ἀτλαντικῷ πελάγει πλαττόμενα δηλοῦται. ὁ δὲ ταῦτ’ ἐπικρυπτόμενος τὰ φανερῶς λεγόμενα ἀναιρεῖ. τοῦτο μὲν οὖν οὐκ εὖ· τὸ δὲ περὶ Σικελίαν καὶ Ἰταλίαν γεγονέναι τὴν πλάνην ὀρθῶς, ἐπεὶ τίς ἔπεισε ποιητὴς ἢ συγγραφεὺς Νεαπολίτας μὲν λέγειν μνῆμα Παρθενόπης τῆς Σειρῆνος, τοὺς δὲ ἐν Κύμῃ καὶ Δικαιαρχείᾳ καὶ Βεσβίῳ Πυριφλεγέθοντα καὶ Ἀχερουσίαν λίμνην καὶ νεκυομαντεῖον τὸ ἐν τῷ Ἀόρνῳ καὶ Βάιον καὶ Μισηνὸν τῶν Ὀδυσσέως ἑταίρων τινάς; οὕτω δὲ καὶ τὰ περὶ Σειρηνούσσας καὶ τὰ περὶ τὸν πορθμὸν καὶ Σκύλλαν καὶ Χάρυβδιν καὶ Αἰόλον· ἅπερ οὔτ’ ἀκριβῶς ἐξετάζειν δεῖ οὔτ’ ἄρριζα καὶ ἀνέστια ἐᾶν, ἀληθείας μηδὲν προσαπτόμενα μηδ’ ὠφελείας ἱστορικῆς.", "st": "1.2.18"}, {"sp": "N", "t": "καὶ αὐτὸς δὲ ὑπονοήσας τοῦτο ὁ Ἐρατοσθένης, ὑπολάβοι τις ἄν, φησί, τὸν ποιητὴν βούλεσθαι μὲν ἐν τοῖς προσεσπερίοις τόποις τὴν πλάνην τῷ Ὀδυσσεῖ ποιεῖν, ἀποστῆναι δ’ ἀπὸ τῶν ὑποκειμένων, τὰ μὲν οὐκ ἀκριβῶς πεπυσμένον, τὰ δὲ οὐδὲ προελόμενον οὕτως, ἀλλ’ ἐπὶ τὸ δεινότερον καὶ τὸ τερατωδέστερον ἕκαστα ἐξάγειν. τοῦτο μὲν αὐτὸ εὖ, τὸ δ’ οὗ χάριν τοῦτ’ ἐποίει κακῶς δεξάμενος· οὐ γὰρ φλυαρίας, ἀλλ’ ὠφελείας χάριν. ὥστε δίκαιός ἐστιν ὑπέχειν λόγον καὶ περὶ τούτου καὶ διότι φησὶ τὰ πόρρω τερατολογεῖσθαι μᾶλλον διὰ τὸ εὐκατάψευστον. πολλοστὸν γὰρ μέρος ἐστὶ τὰ πόρρω τερατολογούμενα τῶν ἐν τῇ Ἑλλάδι καὶ ἐγγὺς τῆς Ἑλλάδος· οἷα δὴ τὰ κατὰ τοὺς Ἡρακλέους ἄθλους καὶ Θησέως καὶ τὰ ἐν Κρήτῃ καὶ Σικελίᾳ μυθευόμενα καὶ ταῖς ἄλλαις νήσοις, καὶ τὰ περὶ τὸν Κιθαιρῶνα καὶ Ἑλικῶνα καὶ Παρνασσὸν καὶ Πήλιον καὶ τὴν Ἀττικὴν ὅλην καὶ Πελοπόννησον· οὐδείς τε ἐκ τῶν μύθων ἄγνοιαν αἰτιᾶται τῶν μυθοποιῶν. ἔτι δὲ ἐπεὶ οὐ πάντα μυθεύουσιν, ἀλλὰ πλείω προσμυθεύουσι, καὶ μάλιστα Ὅμηρος, ὁ ζητῶν τί οἱ παλαιοὶ προσμυθεύουσιν οὐ ζητεῖ, εἰ τὰ προσμυθευόμενα ὑπῆρξεν ἢ ἐστίν, ἀλλὰ καὶ μᾶλλον οἷς προσμυθεύεται τόποις ἢ προσώποις, περὶ ἐκείνων ζητεῖ τἀληθές, οἷον τὴν Ὀδυσσέως πλάνην, εἰ γέγονε καὶ ποῦ.", "st": "1.2.19"}, {"sp": "N", "t": "τὸ δ’ ὅλον οὐκ εὖ τὸ τὴν Ὁμήρου ποίησιν εἰς ἓν συνάγειν τῇ τῶν ἄλλων ποιητῶν εἴς τε τἆλλα καὶ εἰς αὐτὰ τὰ νῦν προκείμενα τὰ τῆς γεωγραφίας καὶ μηδὲν αὐτῷ πρεσβεῖον ἀπονέμειν. καὶ γὰρ εἰ μηδὲν ἄλλο, τόν γε Τριπτόλεμον τὸν Σοφοκλέους ἢ τὸν ἐν ταῖς Βάκχαις ταῖς Εὐριπίδου πρόλογον ἐπελθόντα καὶ παραβαλόντα τὴν Ὁμήρου περὶ τὰ τοιαῦτα ἐπιμέλειαν, ῥᾷον ἦν αἰσθέσθαι τὴν ὑπερβολὴν ἢ τὴν διαφοράν· ὅπου γὰρ χρεία τάξεως ὧν μέμνηται τόπων, φυλάττει τὴν τάξιν ὁμοίως μὲν τῶν Ἑλληνικῶν, ὁμοίως δὲ τῶν ἄπωθεν· “Ὄσσαν ἐπ’ Οὐλύμπῳ μέμασαν θέμεν, αὐτὰρ ἐπ’ Ὄσσῃ Πήλιον εἰνοσίφυλλον.” “Ἥρη δ’ ἀίξασα λίπεν ῥίον Οὐλύμποιο, Πιερίην δ’ ἐπιβᾶσα καὶ Ἠμαθίην ἐρατεινὴν σεύατ’ ἐφ’ ἱπποπόλων Θρῃκῶν ὄρεα νιφόεντα· ἐξ Ἀθόω δ’ ἐπὶ πόντον.” καὶ ἐν τῷ καταλόγῳ τὰς μὲν πόλεις οὐκ ἐφεξῆς λέγει· οὐ γὰρ ἀναγκαῖον· τὰ δὲ ἔθνη ἐφεξῆς. ὁμοίως δὲ καὶ περὶ τῶν ἄπωθεν· “Κύπρον Φοινίκην τε καὶ Αἰγυπτίους ἐπαληθεὶς Αἰθίοπάς θ’ ἱκόμην καὶ Σιδονίους καὶ Ἐρεμβοὺς καὶ Λιβύην.” ὅπερ καὶ Ἵππαρχος ἐπισημαίνεται. οἱ δ’ ἐφ’ ὧν τάξεως χρεία, ὁ μὲν τὸν Διόνυσον ἐπιόντα τὰ ἔθνη φράζων, ὁ δὲ τὸν Τριπτόλεμον τὴν κατασπειρομένην γῆν, τὰ μὲν πολὺ διεστῶτα συνάπτουσιν ἐγγύς, τὰ δὲ συνεχῆ διασπῶσι· “λιπὼν δὲ Λυδῶν τὰς πολυχρύσους γύας Φρυγῶν τε Περσῶν θ’ ἡλιοβλήτους πλάκας Βάκτριά τε τείχη, τήν τε δύσχειμον χθόνα Μήδων ἐπελθὼν Ἀραβίαν τ’ εὐδαίμονα.” τοιαῦτα δὲ καὶ ὁ Τριπτόλεμος ποιεῖ. κἀν τοῖς κλίμασι δὲ κἀν τοῖς ἀνέμοις διαφαίνει τὸ πολυμαθὲς τὸ περὶ τὴν γεωγραφίαν Ὅμηρος, ἐν ταῖς τοποθεσίαις λέγων ἅμα καὶ ταῦτα πολλαχοῦ· “αὐτὴ δὲ χθαμαλὴ πανυπερτάτη εἰν ἁλὶ κεῖται πρὸς ζόφον· αἱ δέ τ’ ἄνευθε πρὸς ἠῶ τ’ ἠέλιόν τε.” “δύω δέ τέ οἱ θύραι εἰσίν, αἱ μὲν πρὸς βορέαν, αἱ δ’ αὖ πρὸς νότον.” “εἴτ’ ἐπὶ δεξί’ ἴωσι πρὸς ἠῶ τ’ ἠέλιόν τε, εἴτ’ ἐπ’ ἀριστερά τοί γε ποτὶ ζόφον.” καὶ μὴν τὴν ἄγνοιάν γε τῶν τοιούτων τελείαν ἡγεῖται σύγχυσιν τῶν ἁπάντων· “ὦ φίλοι, οὐ γάρ τ’ ἴδμεν, ὅπῃ ζόφος οὐδ’ ὅπῃ ἠώς, οὐδ’ ὅπῃ ἠέλιος.” κἀνταῦθα δ’ εἰπόντος εὖ τοῦ ποιητοῦ “βορέης καὶ ζέφυρος, τώ τε Θρῄκηθεν ἄητον,” οὐκ εὖ δεξάμενος ὁ αὐτὸς συκοφαντεῖ ὡς καθόλου λέγοντος, ὅτι ὁ ζέφυρος ἐκ Θρᾴκης πνεῖ, ἐκείνου λέγοντος οὐ καθόλου, ἀλλ’ ὅταν κατὰ τὴν Θρᾳκίαν θάλατταν συμπέσωσι περὶ τὸν Μέλανα κόλπον αὐτοῦ τοῦ Αἰγαίου μέρος οὖσαν. ἐπιστροφὴν γὰρ λαμβάνει πρὸς νότον ἀκρωτηριάζουσα ἡ Θρᾴκη καθ’ ἃ συνάπτει τῇ Μακεδονίᾳ, καὶ προπίπτουσα εἰς τὸ πέλαγος τοὺς ζεφύρους ἐντεῦθεν πνέοντας ἀποφαίνει τοῖς ἐν Θάσῳ καὶ Λήμνῳ καὶ Ἴμβρῳ καὶ Σαμοθρᾴκῃ καὶ τῇ περὶ αὐτὰς θαλάττῃ, καθάπερ καὶ τῇ Ἀττικῇ ἀπὸ τῶν Σκειρωνίδων πετρῶν, ἀφ’ ὧν καὶ Σκείρωνες καλοῦνται οἱ ζέφυροι, καὶ μάλιστα οἱ ἀργέσται. οὐκ ἐνόησε δὲ τοῦτο Ἐρατοσθένης, ὑπενόησε δ’ ὅμως. αὐτὸς γοῦν ἐξηγεῖται τὴν ἐπιστροφὴν ἣν λέγω τῆς χώρας· ὡς καθόλου οὖν δέχεται, εἶτ’ ἀπειρίαν αἰτιᾶται τοῦ ποιητοῦ, ὡς τοῦ ζεφύρου μὲν ἀπὸ τῆς ἑσπέρας πνέοντος καὶ τῆς Ἰβηρίας, τῆς δὲ Θρᾴκης ἐκεῖσε μὴ διατεινούσης. πότερον οὖν τὸν ζέφυρον ἀγνοεῖ ἀπὸ ἑσπέρας πνέοντα; ἀλλ’ ὅταν οὕτω φῇ, φυλάττει τὴν οἰκείαν αὐτοῦ τάξιν “σὺν δ’ εὖρός τε νότος τε πέσον ζέφυρός τε δυσαὴς καὶ βορέης·” ἢ τὴν Θρᾴκην οὐκ οἶδε μὴ προπίπτουσαν πέραν τῶν Παιονικῶν καὶ Θετταλικῶν ὀρῶν; ἀλλὰ καὶ ταύτην τὴν ἐφεξῆς κατὰ τοὺς Θρᾷκας εἰδὼς καὶ κατονομάζων τήν τε παραλίαν καὶ τὴν μεσόγαιαν Μάγνητας μέν τινας καὶ Μαλιεῖς καὶ τοὺς ἐφεξῆς Ἕλληνας καταλέγει μέχρι Θεσπρωτῶν, ὁμοίως δὲ καὶ τοῖς Παίοσι τοὺς ὁμόρους Δόλοπας καὶ Σελλοὺς περὶ Δωδώνην μέχρις Ἀχελώου· Θρᾳκῶν δ’ οὐ μέμνηται περαιτέρω. εὐεπιφόρως δὲ ἔχει πρὸς τὴν ἐγγυτάτην καὶ γνωριμωτάτην ἑαυτῷ θάλατταν, ὡς καὶ ὅταν φῇ “κινήθη δ’ ἀγορὴ ὡς κύματα μακρὰ θαλάσσης πόντου Ἰκαρίοιο.”", "st": "1.2.20"}, {"sp": "N", "t": "εἰσὶ δέ τινες οἵ φασιν εἶναι δύο τοὺς κυριωτάτους ἀνέμους βορέαν καὶ νότον, τοὺς δὲ ἄλλους κατὰ μικρὰν ἔγκλισιν διαφέρειν, τὸν μὲν ἀπὸ θερινῶν ἀνατολῶν εὖρον χειμερινῶν δὲ ἀπηλιώτην, δύσεων δὲ θερινῶν μὲν ζέφυρον χειμερινῶν δὲ ἀργέστην. τοῦ δὲ δύο εἶναι τοὺς ἀνέμους ποιοῦνται μάρτυρας Θρασυάλκην τε καὶ τὸν ποιητὴν αὐτὸν τῷ τὸν μὲν ἀργέστην τῷ νότῳ προσνέμειν “ἀργεστᾶο Νότοιο,” τὸν δὲ ζέφυρον τῷ βορέᾳ “βορέης καὶ ζέφυρος, τώ τε Θρῄκηθεν ἄητον.” φησὶ δὲ Ποσειδώνιος μηδένα οὕτως παραδεδωκέναι τοὺς ἀνέμους τῶν γνωρίμων περὶ ταῦτα, οἷον Ἀριστοτέλη Τιμοσθένη Βίωνα τὸν ἀστρολόγον· ἀλλὰ τὸν μὲν ἀπὸ θερινῶν ἀνατολῶν καικίαν, τὸν δὲ τούτῳ κατὰ διάμετρον ἐναντίον λίβα ἀπὸ δύσεως ὄντα χειμερινῆς· πάλιν δὲ τὸν μὲν ἀπὸ χειμερινῆς ἀνατολῆς εὖρον, τὸν δ’ ἐναντίον ἀργέστην· τοὺς δὲ μέσους ἀπηλιώτην καὶ ζέφυρον. τὸν δὲ ποιητὴν δυσαῆ μὲν ζέφυρον λέγειν τὸν ὑφ’ ἡμῶν καλούμενον ἀργέστην, λίγα δὲ πνέοντα ζέφυρον τὸν ὑφ’ ἡμῶν ζέφυρον, ἀργέστην δὲ νότον τὸν λευκόνοτον· οὗτος γὰρ ὀλίγα τὰ νέφη ποιεῖ, τοῦ λοιποῦ νότου ὀλεροῦ πως ὄντος. “ὡς ὁπότε ζέφυρος νέφεα στυφελίξῃ, ἀργεστᾶο νότοιο βαθείῃ λαίλαπι τύπτων.” τὸν γὰρ δυσαῆ ζέφυρον νῦν λέγει, ὃς εἴωθε διασκιδνάναι τὰ ὑπὸ τοῦ λευκονότου συναγόμενα ἀσθενῆ ὄντα, ἐπιθέτως τοῦ νότου νῦν ἀργέστου λεγομένου. ταῦτα μὲν δὴ ἐν ἀρχῇ τοῦ πρώτου τῶν γεωγραφικῶν εἰρημένα τοιαύτην τινὰ τὴν ἐπανόρθωσιν ἔχει.", "st": "1.2.21"}, {"sp": "N", "t": "Ἐπιμένων δὲ τοῖς περὶ Ὁμήρου ψευδῶς ὑποληφθεῖσι καὶ ταῦτά φησιν, ὅτι οὐδὲ τὰ τοῦ Νείλου στόματα οἶδε πλείω ὄντα οὐδ’ αὐτὸ τοὔνομα, Ἡσίοδος δὲ οἶδε· μέμνηται γάρ. τὸ μὲν οὖν ὄνομα εἰκὸς μήπω λέγεσθαι κατ’ αὐτόν· τὰ δὲ στόματα εἰ μὲν ἦν ἀφανῆ καὶ ὀλίγοις γνώριμα ὅτι πλείω καὶ οὐχ ἕν, δοίη τις ἂν μὴ πεπύσθαι αὐτόν· εἰ δὲ τῶν κατ’ Αἴγυπτον τὸ γνωριμώτατον καὶ παραδοξότατον καὶ μάλιστα πάντων μνήμης ἄξιον καὶ ἱστορίας ὁ ποταμὸς καὶ ἦν καὶ ἐστίν, ὡς δ’ αὕτως αἱ ἀναβάσεις αὐτοῦ καὶ τὰ στόματα, τίς ἂν ἢ τοὺς ἀγγέλλοντας αὐτῷ ποταμὸν Αἴγυπτον καὶ χώραν καὶ Θήβας Αἰγυπτίας καὶ Φάρον ὑπολάβοι μὴ γνωρίζειν ταῦτα, ἢ γνωρίζοντας μὴ λέγειν, πλὴν εἰ μὴ διὰ τὸ γνώριμον; ἔτι δ’ ἀπιθανώτερον, εἰ τὴν μὲν Αἰθιοπίαν ἔλεγε καὶ Σιδονίους καὶ Ἐρεμβοὺς καὶ τὴν ἔξω θάλατταν καὶ τὸ διχθὰ δεδάσθαι τοὺς Αἰθίοπας, τὰ δ’ ἐγγὺς καὶ γνώριμα μή. εἰ δὲ μὴ ἐμνήσθη τούτων, οὐ τοῦτο σημεῖον τοῦ ἀγνοεῖν· οὐδὲ γὰρ τῆς αὐτοῦ πατρίδος ἐμνήσθη οὐδὲ πολλῶν ἄλλων, ἀλλὰ μᾶλλον τὰ λίαν γνώριμα ὄντα φαίη τις ἂν δόξαι μὴ ἄξια μνήμης εἶναι πρὸς τοὺς εἰδότας.", "st": "1.2.22"}, {"sp": "N", "t": "οὐκ εὖ δὲ οὐδὲ τοῦτο προφέρουσιν αὐτῷ τὸ περὶ τῆς νήσου τῆς Φαρίας, ὅτι φησὶ πελαγίαν, ὡς κατ’ ἄγνοιαν λέγοντι· τοὐναντίον γὰρ κἂν μαρτυρίῳ χρήσαιτό τις τούτῳ πρὸς τὸ μὴ ἀγνοεῖσθαι μηδὲν ὑπὸ τοῦ ποιητοῦ τῶν εἰρημένων ἀρτίως περὶ τὴν Αἴγυπτον. γνοίης δ’ ἂν οὕτως· ἀλαζὼν δὴ πᾶς ὁ πλάνην αὑτοῦ διηγούμενος· τούτων δ’ ἦν καὶ ὁ Μενέλαος, ὃς ἀναβεβηκὼς μέχρις Αἰθιόπων ἐπέπυστο τὰς ἀναβάσεις τοῦ Νείλου καὶ τὴν χοῦν ὅσην ἐπιφέρει τῇ χώρᾳ, καὶ τὸν πρὸ τῶν στομάτων πόρον ὅσον ἤδη προσχώσας τῇ ἠπείρῳ προστέθεικεν, ὥστε εἰκότως ὑπὸ τοῦ Ἡροδότου καὶ τὴν ὅλην Αἴγυπτον τοῦ ποταμοῦ δῶρον λέγεσθαι· κἂν εἰ μὴ τὴν ὅλην, τήν γε ὑπὸ τῷ Δέλτα τὴν κάτω χώραν προσαγορευομένην. ἱστόρησε δὲ καὶ τὴν Φάρον πελαγίαν οὖσαν τὸ παλαιόν· προσεψεύσατο δὴ καὶ τὸ πελαγίαν εἶναι, καίπερ μηκέτι πελαγίαν οὖσαν. ὁ δὲ ταῦτα διασκευάζων ὁ ποιητὴς ἦν· ὥστ’ ἐκ τούτων εἰκάζειν ὅτι καὶ τὰς ἀναβάσεις ᾔδει καὶ τὰ στόματα τοῦ Νείλου.", "st": "1.2.23"}, {"sp": "N", "t": "̔η δ’ αὐτὴ ἁμαρτία καὶ περὶ τοῦ ἀγνοεῖν τὸν ἰσθμὸν τὸν μεταξὺ τοῦ Αἰγυπτίου πελάγους καὶ τοῦ Ἀραβίου κόλπου καὶ περὶ τοῦ ψευδῶς λέγεσθαι “Αἰθίοπες, τοὶ διχθὰ δεδαίαται ἔσχατοι ἀνδρῶν.” καὶ γὰρ τοῦτο ἐκείνου λέγοντος καλῶς ἐπιτιμῶσιν οἱ ὕστερον οὐκ εὖ. τοσούτου γὰρ δεῖ τοῦτ’ ἀληθὲς εἶναι τὸ ἀγνοεῖν Ὅμηρον τὸν ἰσθμὸν τοῦτον, ὥστε ἐκεῖνον μέν φημι μὴ εἰδέναι μόνον, ἀλλὰ καὶ ἀποφαίνεσθαι ἄντικρυς, τοὺς δὲ γραμματικοὺς μηδὲ λέγοντος ἐκείνου αἰσθάνεσθαι ἀπὸ Ἀριστάρχου καὶ Κράτητος τῶν κορυφαίων ἐν τῇ ἐπιστήμῃ ταύτῃ. εἰπόντος γὰρ τοῦ ποιητοῦ “Αἰθίοπας, τοὶ διχθὰ δεδαίαται, ἔσχατοι ἀνδρῶν,” περὶ τοῦ ἐπιφερομένου ἔπους διαφέρονται, ὁ μὲν Ἀρίσταρχος γράφων “οἱ μὲν δυσομένου Ὑπερίονος, οἱ δ’ ἀνιόντος,” ὁ δὲ Κράτης “ἠμὲν δυσομένου Ὑπερίονος, ἠδ’ ἀνιόντος,” οὐδὲν διαφέρον πρὸς τὴν ἑκατέρου ὑπόθεσιν οὕτως ἢ ἐκείνως γράφειν. ὁ μὲν γὰρ ἀκολουθῶν τοῖς μαθηματικῶς λέγεσθαι δοκοῦσι τὴν διακεκαυμένην ζώνην κατέχεσθαί φησιν ὑπὸ τοῦ ὠκεανοῦ· παρ’ ἑκάτερον δὲ ταύτης εἶναι τὴν εὔκρατον, τήν τε καθ’ ἡμᾶς καὶ τὴν ἐπὶ θάτερον μέρος. ὥσπερ οὖν οἱ παρ’ ἡμῖν Αἰθίοπες οὗτοι λέγονται οἱ πρὸς μεσημβρίαν κεκλιμένοι παρ’ ὅλην τὴν οἰκουμένην ἔσχατοι τῶν ἄλλων παροικοῦντες τὸν ὠκεανόν, οὕτως οἴεται δεῖν καὶ πέραν τοῦ ὠκεανοῦ νοεῖσθαί τινας Αἰθίοπας ἐσχάτους τῶν ἄλλων τῶν ἐν τῇ ἑτέρᾳ εὐκράτῳ, παροικοῦντας τὸν αὐτὸν τοῦτον ὠκεανόν· διττοὺς δὲ εἶναι καὶ διχθὰ δεδάσθαι ὑπὸ τοῦ ὠκεανοῦ. προσκεῖσθαι δὲ τὸ “ἠμὲν δυσομένου Ὑπερίονος, ἠδ’ ἀνιόντος,” ὅτι τοῦ ζωδιακοῦ κατὰ κορυφὴν ὄντος ἀεὶ τῷ ἐν τῇ γῇ ζωδιακῷ, τούτου δ’ οὐκ ἐκβαίνοντος ἔξω τῆς Αἰθιόπων ἀμφοῖν τῇ λοξώσει, ἀνάγκη καὶ τὴν πάροδον τοῦ ἡλίου πᾶσαν ἐν τῷ πλάτει τούτῳ νοεῖσθαι, καὶ τὰς ἀνατολὰς καὶ τὰς δύσεις συμβαίνειν ἐνταῦθα ἄλλας ἄλλοις καὶ κατ’ ἄλλα ἢ ἄλλα σημεῖα. εἴρηκε μὲν οὕτως ἀστρονομικώτερον νομίσας· ἦν δὲ καὶ ἁπλούστερον εἰπεῖν αὐτὸ σώζοντα τὸ οὕτω διῃρῆσθαι δίχα τοὺς Αἰθίοπας, ὡς εἴρηται, ὅτι ἀφ’ ἡλίου ἀνιόντος μέχρι δύσεως ἐφ’ ἑκάτερα παροικοῦσι τῷ ὠκεανῷ Αἰθίοπες. τί οὖν διαφέρει πρὸς τὸν νοῦν τοῦτον ἢ οὕτως εἰπεῖν ὥσπερ αὐτὸς γράφει, ἢ ὡς Ἀρίσταρχος “οἱ μὲν δυσομένου Ὑπερίονος, οἱ δ’ ἀνιόντος;” καὶ γὰρ τοῦτ’ ἐστὶ καὶ πρὸς δύσιν καὶ πρὸς ἀνατολὴν ἐφ’ ἑκάτερα τοῦ ὠκεανοῦ οἰκεῖν. ὁ δ’ Ἀρίσταρχος ταύτην μὲν ἐκβάλλει τὴν ὑπόθεσιν, δίχα δὲ μεμερισμένους οἴεται λέγεσθαι τοὺς καθ’ ἡμᾶς Αἰθίοπας τοὺς τοῖς Ἕλλησι πρὸς μεσημβρίαν ἐσχάτους. τούτους δὲ μὴ μεμερίσθαι δίχα ὥστε εἶναι δύο Αἰθιοπίας, τὴν μὲν πρὸς ἀνατολὴν τὴν δὲ πρὸς δύσιν, ἀλλὰ μίαν μόνην τὴν πρὸς μεσημβρίαν κειμένην τοῖς Ἕλλησιν, ἱδρυμένην δὲ κατ’ Αἴγυπτον. τοῦτο δὲ ἀγνοοῦντα τὸν ποιητήν, ὥσπερ καὶ τὰ ἄλλα, ὅσα εἴρηκεν Ἀπολλόδωρος ἐν τῷ περὶ νεῶν καταλόγου δευτέρῳ, καταψεύσασθαι τῶν τόπων τὰ μὴ ὄντα.", "st": "1.2.24"}, {"sp": "N", "t": "πρὸς μὲν οὖν Κράτητα μακροῦ λόγου δεῖ καὶ ἴσως οὐδὲν ὄντος πρὸς τὰ νῦν. Ἀριστάρχου δὲ τοῦτο μὲν ἐπαινῶμεν, διότι τὴν Κρατήτειον ἀφεὶς ὑπόθεσιν δεχομένην πολλὰς ἐνστάσεις περὶ τῆς καθ’ ἡμᾶς Αἰθιοπίας ὑπονοεῖ γεγονέναι τὸν λόγον· τὰ δ’ ἄλλα ἐπισκοπῶμεν. καὶ πρῶτον ὅτι καὶ αὐτὸς μικρολογεῖται μάτην περὶ τῆς γραφῆς. καὶ γὰρ ἂν ἑκατέρως γράφηται, δύναται ἐφαρμόττειν τοῖς νοήμασιν αὐτοῦ. τί γὰρ διαφέρει λέγειν ἢ οὕτως “δύο εἰσὶ καθ’ ἡμᾶς Αἰθίοπες, οἱ μὲν πρὸς ἀνατολὰς οἱ δὲ πρὸς δύσεις,” ἢ οὕτως “καὶ γὰρ πρὸς ἀνατολὰς καὶ πρὸς δύσεις;” ἔπειθ’ ὅτι ψευδοῦς προΐσταται δόγματος. φέρε γὰρ τὸν ποιητὴν ἀγνοεῖν μὲν τὸν ἰσθμόν, τῆς δὲ κατ’ Αἴγυπτον Αἰθιοπίας μεμνῆσθαι ὅταν φῇ “Αἰθίοπας, τοὶ διχθὰ δεδαίαται.” πῶς οὖν; οὐ διχθὰ δεδαίαται οὕτως, ἀλλ’ ἀγνοῶν οὕτως εἴρηκεν ὁ ποιητής; πότερ’ οὐδ’ ἡ Αἴγυπτος, οὐδ’ οἱ Αἰγύπτιοι ἀπὸ τοῦ Δέλτα ἀρξάμενοι μέχρι πρὸς Συήνην ὑπὸ τοῦ Νείλου δίχα διῄρηνται “οἱ μὲν δυσομένου Ὑπερίονος, οἱ δ’ ἀνιόντος;” τί δ’ ἄλλο ἡ Αἴγυπτός ἐστι πλὴν ἡ ποταμία, ἣν ἐπικλύζει τὸ ὕδωρ; αὕτη δ’ ἐφ’ ἑκάτερα τοῦ ποταμοῦ κεῖται πρὸς ἀνατολὴν καὶ δύσιν. ἀλλὰ μὴν ἡ Αἰθιοπία ἐπ’ εὐθείας ἐστὶ τῇ Αἰγύπτῳ καὶ παραπλησίως ἔχει πρός τε τὸν Νεῖλον καὶ τὴν ἄλλην φύσιν τῶν τόπων. καὶ γὰρ αὕτη στενή τέ ἐστι καὶ μακρὰ καὶ ἐπίκλυστος. τὰ δ’ ἔξω τῆς ἐπικλύστου ἔρημά τε καὶ ἄνυδρα καὶ σπανίως οἰκεῖσθαι δυνάμενα, τὰ μὲν πρὸς ἕω τὰ δὲ πρὸς δύσιν κεκλιμένα. πῶς οὖν οὐχὶ καὶ δίχα διῄρηται; ἢ τοῖς μὲν τὴν Ἀσίαν ἀπὸ τῆς Λιβύης διαιροῦσιν ἀξιόλογον τοῦθ’ ὅριον ἐφάνη ὁ Νεῖλος, μῆκος μὲν ἀνατείνων ἐπὶ τὴν μεσημβρίαν πλειόνων ἢ μυρίων σταδίων, πλάτος δέ, ὥστε καὶ νήσους ἀπολαμβάνειν μυριάνδρους, ὧν μεγίστη ἡ Μερόη τὸ βασίλειον καὶ μητρόπολις τῶν Αἰθιόπων, αὐτὴν δὲ τὴν Αἰθιοπίαν οὐχ ἱκανὸς ἦν διαιρεῖν δίχα; καὶ μὴν οἵ γε ἐπιτιμῶντες τοῖς τὰς ἠπείρους τῷ ποταμῷ διαιροῦσι τῶν ἐγκλημάτων τοῦτο μέγιστον προφέρουσιν αὐτοῖς, ὅτι τὴν Αἴγυπτον καὶ τὴν Αἰθιοπίαν διασπῶσι καὶ ποιοῦσι τὸ μέν τι μέρος ἑκατέρας αὐτῶν Λιβυκόν, τὸ δ’ Ἀσιατικόν· ἢ εἰ μὴ βούλονται τοῦτο, ἢ οὐ διαιροῦσι τὰς ἠπείρους ἢ οὐ τῷ ποταμῷ.", "st": "1.2.25"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἐστὶ καὶ ἄλλως διαιρεῖν τὴν Αἰθιοπίαν. πάντες γὰρ οἱ παραπλεύσαντες τῷ ὠκεανῷ τὴν Λιβύην, οἵ τε ἀπὸ τῆς Ἐρυθρᾶς καὶ οἱ ἀπὸ τῶν στηλῶν, μέχρι ποσοῦ προελθόντες εἶτα ἀνέστρεψαν ὑπὸ πολλῶν ἀποριῶν κωλυόμενοι, ὥστε καὶ πίστιν κατέλιπον τοῖς πολλοῖς, ὡς τὸ μεταξὺ διείργοιτο ἰσθμῷ· καὶ μὴν σύρρους ἡ πᾶσα Ἀτλαντικὴ θάλαττα, καὶ μάλιστα ἡ κατὰ μεσημβρίαν. ἅπαντες δὲ οὗτοι τὰ τελευταῖα χωρία, ἐφ’ ἃ πλέοντες ἦλθον, Αἰθιοπικὰ προσηγόρευσαν καὶ ἀπήγγειλαν οὕτως. τί οὖν ἄλογον, εἰ καὶ Ὅμηρος ὑπὸ τοιαύτης ἀκοῆς ἀχθεὶς δίχα διῄρει, τοὺς μὲν πρὸς ἀνατολὴν λέγων, τοὺς δὲ πρὸς δύσιν, τῶν μεταξὺ οὐ γινωσκομένων εἴτε εἰσὶν εἴτε μὴ εἰσίν; ἀλλὰ μὴν καὶ ἄλλην τινὰ ἱστορίαν εἴρηκεν παλαιὰν Ἔφορος, ᾗ οὐκ ἄλογον ἐντυχεῖν καὶ Ὅμηρον. λέγεσθαι γάρ φησιν ὑπὸ τῶν Ταρτησσίων Αἰθίοπας τὴν Λιβύην ἐπελθόντας μέχρι αὐάσεως τοὺς μὲν αὐτοῦ μεῖναι, τοὺς δὲ καὶ τῆς παραλίας κατασχεῖν πολλήν· τεκμαίρεται δ’ ἐκ τούτου καὶ Ὅμηρον εἰπεῖν οὕτως “Αἰθίοπες, τοὶ διχθὰ δεδαίαται, ἔσχατοι ἀνδρῶν.”", "st": "1.2.26"}, {"sp": "N", "t": "ταῦτά τε δὴ πρὸς τὸν Ἀρίσταρχον λέγοι ἄν τις καὶ πρὸς τοὺς ἀκολουθοῦντας αὐτῷ καὶ ἄλλα τούτων ἐπιεικέστερα, ἀφ’ ὧν τὴν πολλὴν ἄγνοιαν ἀφαιρήσεται τοῦ ποιητοῦ. φημὶ γὰρ κατὰ τὴν τῶν ἀρχαίων Ἑλλήνων δόξαν, ὥσπερ τὰ πρὸς βορρᾶν μέρη τὰ γνώριμα ἑνὶ ὀνόματι Σκύθας ἐκάλουν ἢ νομάδας, ὡς Ὅμηρος, ὕστερον δὲ καὶ τῶν πρὸς ἑσπέραν γνωσθέντων Κελτοὶ καὶ Ἴβηρες ἢ μικτῶς Κελτίβηρες καὶ Κελτοσκύθαι προσηγορεύοντο, ὑφ’ ἓν ὄνομα τῶν καθ’ ἕκαστα ἐθνῶν ταττομένων διὰ τὴν ἄγνοιαν, οὕτω τὰ μεσημβρινὰ πάντα Αἰθιοπίαν καλεῖσθαι τὰ πρὸς ὠκεανῷ. μαρτυρεῖ δὲ τὰ τοιαῦτα. ὅ τε γὰρ Αἰσχύλος ἐν Προμηθεῖ τῷ λυομένῳ φησὶν οὕτω “φοινικόπεδόν τ’ ἐρυθρᾶς ἱερὸν χεῦμα θαλάσσης, χαλκοκέραυνόν τε παρ’ ὠκεανῷ λίμναν παντοτρόφον Αἰθιόπων, ἵν’ ὁ παντόπτας Ἥλιος αἰεὶ χρῶτ’ ἀθάνατον κάματόν θ’ ἵππων θερμαῖς ὕδατος μαλακοῦ προχοαῖς ἀναπαύει.” παρ’ ὅλον γὰρ τὸ μεσημβρινὸν κλίμα τοῦ ὠκεανοῦ ταύτην πρὸς τὸν ἥλιον ἴσχοντος τὴν χρείαν καὶ τὴν σχέσιν, παρ’ ὅλον καὶ τοὺς Αἰθίοπας τάττων φαίνεται. ὅ τ’ Εὐριπίδης ἐν τῷ Φαέθοντι τὴν Κλυμένην δοθῆναί φησι “Μέροπι τῆσδ’ ἄνακτι γῆς, ἣν ἐκ τεθρίππων ἁρμάτων πρώτην χθόνα Ἥλιος ἀνίσχων χρυσέᾳ βάλλει φλογί· καλοῦσι δ’ αὐτὴν γείτονες μελάμβροτοι Ἕω φαεννὰς Ἡλίου θ’ ἱπποστάσεις.” νῦν μὲν δὴ κοινὰς ποιεῖται τὰς ἱπποστάσεις τῇ τε Ἠοῖ καὶ τῷ Ἡλίῳ, ἐν δὲ τοῖς ἑξῆς πλησίον αὐτάς φησιν εἶναι τῇ οἰκήσει τοῦ Μέροπος· καὶ ὅλῃ γε τῇ δραματουργίᾳ τοῦτο παραπέπλεκται, οὐ δή που τῆς κατ’ Αἴγυπτον ἴδιον ὄν, μᾶλλον δὲ τῆς παρ’ ὅλον τὸ μεσημβρινὸν κλίμα διηκούσης παραλίας.", "st": "1.2.27"}, {"sp": "N", "t": "μηνύει δὲ καὶ Ἔφορος τὴν παλαιὰν περὶ τῆς Αἰθιοπίας δόξαν, ὅς φησιν ἐν τῷ περὶ τῆς Εὐρώπης λόγῳ, τῶν περὶ τὸν οὐρανὸν καὶ τὴν γῆν τόπων εἰς τέτταρα μέρη διῃρημένων, τὸ πρὸς τὸν ἀπηλιώτην Ἰνδοὺς ἔχειν, πρὸς νότον δὲ Αἰθίοπας, πρὸς δύσιν δὲ Κελτούς, πρὸς δὲ βορρᾶν ἄνεμον Σκύθας. προστίθησι δ’ ὅτι μείζων ἡ Αἰθιοπία καὶ ἡ Σκυθία· δοκεῖ γάρ, φησί, τὸ τῶν Αἰθιόπων ἔθνος παρατείνειν ἀπ’ ἀνατολῶν χειμερινῶν μέχρι δυσμῶν, ἡ Σκυθία δ’ ἀντίκειται τούτῳ. ὅτι δ’ ὁ ποιητὴς ὁμόλογος τούτοις, καὶ ἐκ τῶνδε δῆλον ὅτι ἡ μὲν Ἰθάκη κεῖται “πρὸς ζόφον” (ὅπερ ἐστὶ πρὸς ἄρκτον), “αἱ δέ τ’ ἄνευθε πρὸς ἠῶ τ’ ἠέλιόν τε.” ὅλον τὸ νότιον πλευρὸν οὕτω λέγων. καὶ ἔτι, ὅταν φῇ· “εἴτ’ ἐπὶ δέξι’ ἴωσι πρὸς ἠῶ τ’ ἠέλιόν τε, εἴτ’ ἐπ’ ἀριστερὰ τοί γε ποτὶ ζόφον ἠερόεντα.” καὶ πάλιν “ὦ φίλοι, οὐ γάρ τ’ ἴδμεν, ὅπῃ ζόφος, οὐδ’ ὅπῃ ἠώς, οὐδ’ ὅπῃ ἠέλιος φαεσίμβροτος εἶσ’ ὑπὸ γαῖαν, οὐδ’ ὅπῃ ἀννεῖται.” περὶ ὧν λέγεται καὶ ἐν τοῖς περὶ τῆς Ἰθάκης λόγοις σαφέστερον. ὅταν οὖν φῇ “Ζεὺς γὰρ ἐς ὠκεανὸν μετ’ ἀμύμονας Αἰθιοπῆας χθιζὸς ἔβη,” κοινότερον δεκτέον καὶ τὸν ὠκεανὸν τὸν καθ’ ὅλον τὸ μεσημβρινὸν κλίμα τεταμένον καὶ τοὺς Αἰθίοπας· ᾧ γὰρ ἂν τόπῳ τοῦδε τοῦ κλίματος προσβάλῃς τὴν διάνοιαν, καὶ ἐπὶ τῷ ὠκεανῷ ἔσῃ καὶ ἐπὶ τῇ Αἰθιοπίᾳ. οὕτω δὲ λέγει καὶ τὸ “τὸν δ’ ἐξ Αἰθιόπων ἀνιὼν τηλόθεν ἐκ Σολύμων ὀρέων ἴδεν,” ἴσον τῷ ἀπὸ μεσημβρινῶν τόπων, Σολύμους λέγων οὐ τοὺς ἐν τῇ Πισιδίᾳ, ἀλλ’ ὡς ἔφην πρότερον πλάσαι τινὰς ὁμωνύμους, τοὺς ἀναλόγως ἔχοντας πρός τε τὸν πλέοντα ἐν τῇ σχεδίᾳ καὶ τοὺς ἐκεῖ μεσημβρινούς, ὡς ἂν Αἰθίοπας, ὡς οἱ Πισιδικοὶ πρός τε τὸν Πόντον καὶ τοὺς ὑπὲρ τῆς Αἰγύπτου Αἰθίοπας. οὕτω δὲ καὶ τὸν περὶ τῶν γεράνων λόγον κοινὸν ποιούμενός φησιν “αἵ τ’ ἐπεὶ οὖν χειμῶνα φύγον καὶ ἀθέσφατον ὄμβρον, κλαγγῇ ταί γε πέτονται ἐπ’ ὠκεανοῖο ῥοάων, ἀνδράσι Πυγμαίοισι φόνον καὶ κῆρα φέρουσαι.” οὐ γὰρ ἐν μὲν τοῖς κατὰ τὴν Ἑλλάδα τόποις ὁρᾶται φερομένη ἡ γέρανος ἐπὶ τὴν μεσημβρίαν, ἐν δὲ τοῖς κατὰ τὴν Ἰταλίαν ἢ Ἰβηρίαν οὐδαμῶς ἢ τοῖς κατὰ τὴν Κασπίαν καὶ Βακτριανήν. κατὰ πᾶσαν οὖν τὴν μεσημβρινὴν παραλίαν τοῦ ὠκεανοῦ παρατείνοντος, ἐφ’ ἅπασαν δὲ καὶ χειμοφυγούντων, δέχεσθαι δεῖ καὶ τοὺς Πυγμαίους μεμυθευμένους κατὰ πᾶσαν. εἰ δ’ οἱ ὕστερον τοὺς Αἰθίοπας ἐπὶ τοὺς κατ’ Αἴγυπτον μόνους μετήγαγον καὶ τὸν περὶ τῶν Πυγμαίων λόγον, οὐδὲν ἂν εἴη πρὸς τὰ πάλαι. καὶ γὰρ Ἀχαιοὺς καὶ Ἀργείους οὐ πάντας μὲν νῦν φαμεν τοὺς στρατεύσαντας ἐπὶ Ἴλιον, Ὅμηρος δὲ καλεῖ πάντας. παραπλήσιον δέ ἐστιν ὃ λέγω καὶ περὶ τῶν δίχα διῃρημένων Αἰθιόπων, ὅτι δεῖ δέχεσθαι τοὺς παρ’ ὅλην διατείνοντας τὴν ὠκεανῖτιν ἀφ’ ἡλίου ἀνιόντος μέχρι ἡλίου δυομένου. οἱ γὰρ οὕτω λεγόμενοι Αἰθίοπες δίχα διῄρηνται φυσικῶς τῷ Ἀραβίῳ κόλπῳ, ὡς ἂν μεσημβρινοῦ κύκλου τμήματι ἀξιολόγῳ, ποταμοῦ δίκην ἐν μήκει σχεδόν τι καὶ πεντακισχιλίων σταδίων ἐπὶ τοῖς μυρίοις, πλάτει δ’ οὐ πολὺ τῶν χιλίων μείζονι τῷ μεγίστῳ· πρόσεστι δὲ τῷ μήκει καὶ τὸ τὸν μυχὸν τοῦδε τοῦ κόλπου διέχειν τῆς κατὰ Πηλούσιον θαλάττης τριῶν ἢ τεττάρων ἡμερῶν [ὁδόν], ἣν ἐπέχει ὁ ἰσθμός. καθάπερ οὖν οἱ χαριέστεροι τῶν διαιρούντων τὴν Ἀσίαν ἀπὸ τῆς Λιβύης ὅρον εὐφυέστερον ἡγοῦνται τοῦτον τῶν ἠπείρων ἀμφοῖν τὸν κόλπον ἢ τὸν Νεῖλον· τὸν μὲν γὰρ διήκειν παρ’ ὀλίγον παντελῶς ἀπὸ θαλάττης ἐπὶ θάλατταν, τὸν δὲ Νεῖλον πολλαπλάσιον ἀπὸ τοῦ ὠκεανοῦ διέχειν, ὥστε μὴ διαιρεῖν τὴν Ἀσίαν πᾶσαν ἀπὸ τῆς Λιβύης· τοῦτον ὑπολαμβάνω τὸν τρόπον κἀγὼ τὰ μεσημβρινὰ μέρη πάντα καθ’ ὅλην τὴν οἰκουμένην δίχα διῃρῆσθαι νομίσαι τὸν ποιητὴν τῷ κόλπῳ τούτῳ. πῶς οὖν ἠγνόει τὸν ἰσθμόν, ὃν οὗτος ποιεῖ πρὸς τὸ Αἰγύπτιον πέλαγος;", "st": "1.2.28"}, {"sp": "N", "t": "καὶ γὰρ δὴ καὶ τελέως ἄλογον, εἰ τὰς μὲν Αἰγυπτίους Θήβας ᾔδει σαφῶς, αἳ διέχουσι τῆς καθ’ ἡμᾶς θαλάττης σταδίους μικρὸν ἀπολείποντας ἀπὸ τῶν πεντακισχιλίων, τὸν δὲ μυχὸν τοῦ Ἀραβίου κόλπου μὴ ᾔδει, μηδὲ τὸν ἰσθμὸν τὸν κατ’ αὐτόν, πλάτος ἔχοντα οὐ πλειόνων ἢ χιλίων σταδίων· πολὺ δ’ ἂν ἀλογώτερον δόξειεν, εἰ τὸν μὲν Νεῖλον ᾔδει ὁμωνύμως τῇ τοσαύτῃ χώρᾳ λεγόμενον, τὴν δ’ αἰτίαν μὴ ἑώρα τούτου· μάλιστα γὰρ ἂν προσπίπτοι τὸ ῥηθὲν ὑφ’ Ἡροδότου διότι δῶρον ἦν ἡ χώρα τοῦ ποταμοῦ καὶ διὰ τοῦτο ἠξιοῦτο τοῦ αὐτοῦ ὀνόματος. ἄλλως τε τῶν παρ’ ἑκάστοις ἰδίων ταῦτ’ ἐστὶ γνωριμώτατα, ἃ καὶ παραδοξίαν ἔχει τινά, καὶ ἐν τῷ φανερῷ πᾶσίν ἐστι· τοιοῦτον δ’ ἐστὶ καὶ ἡ τοῦ Νείλου ἀνάβασις καὶ ἡ πρόσχωσις τοῦ πελάγους. καὶ καθάπερ οἱ προσαχθέντες πρὸς τὴν Αἴγυπτον οὐδὲν πρότερον ἱστοροῦσι περὶ τῆς χώρας, ἢ τὴν τοῦ Νείλου φύσιν διὰ τὸ τοὺς ἐπιχωρίους μήτε καινότερα τούτων λέγειν ἔχειν πρὸς ἄνδρας ξένους, μήτ’ ἐπιφανέστερα περὶ τῶν παρ’ αὐτοῖς· τῷ γὰρ ἱστορήσαντι περὶ τοῦ ποταμοῦ κατάδηλος καὶ ἡ χώρα γίνεται πᾶσα ὁποία τίς ἐστιν· οὕτω καὶ οἱ πόρρωθεν ἀκούοντες οὐδὲν πρότερον ἱστοροῦσι τούτου. προστίθει οὖν τούτῳ καὶ τὸ φιλείδημον τοῦ ποιητοῦ καὶ τὸ φιλέκδημον, ὅπερ αὐτῷ μαρτυροῦσιν ὅσοι τὸν βίον ἀναγράφουσι, καὶ ἐξ αὐτῶν δὲ λαμβάνεται τῶν ποιημάτων πολλὰ παραδείγματα τοῦ τοιούτου. οὗτος μὲν οὖν ἐκ πλεόνων ἐλέγχεται καὶ εἰδὼς καὶ λέγων ῥητῶς τὰ ῥητὰ καὶ σιγῶν τὰ λίαν ἐκφανῆ ἢ ἐπιθέτως λέγων.", "st": "1.2.29"}, {"sp": "N", "t": "θαυμάζειν δὲ δεῖ τῶν Αἰγυπτίων καὶ Σύρων, πρὸς οὓς νῦν ἡμῖν ὁ λόγος, εἰ μηδ’ ἐκείνου λέγοντος τὰ παρ’ αὐτοῖς ἐπιχώρια συνιᾶσιν, ἀλλὰ καὶ ἄγνοιαν αἰτιῶνται, ᾗ αὐτοὺς ἐνόχους δείκνυσιν ὁ λόγος. ἁπλῶς δὲ τὸ μὴ λέγειν οὐ τοῦ μὴ εἰδέναι σημεῖόν ἐστιν· οὐδὲ γὰρ τὰς τροπὰς τοῦ εὐρίπου λέγει οὐδὲ τὰς Θερμοπύλας οὐδ’ ἄλλα πλείω τῶν γνωρίμων παρὰ τοῖς Ἕλλησιν, οὐ μὴν ἠγνόει γε. ἀλλὰ καὶ λέγει, οὐ δοκεῖ δὲ τοῖς ἐθελοκωφοῦσιν, ὥστε ἐκείνους αἰτιατέον. ὁ ποιητὴς τοίνυν διιπετέας καλεῖ τοὺς ποταμούς, οὐ τοὺς χειμάρρους μόνους, ἀλλὰ καὶ πάντας κοινῶς, ὅτι πληροῦνται πάντες ἀπὸ τῶν ὀμβρίων ὑδάτων· ἀλλὰ τὸ κοινὸν ἐπὶ τῶν κατ’ ἐξοχὴν ἴδιον γίνεται. ἄλλως γὰρ ἂν τὸν χειμάρρουν ἀκούοι τις διιπετῆ καὶ ἄλλως τὸν ἀέναον· ἐνταῦθα δὲ διπλασιάζει πως ἡ ἐξοχή. καὶ καθάπερ εἰσί τινες ὑπερβολαὶ ἐπὶ ὑπερβολαῖς, ὡς τὸ κουφότερον εἶναι φελλοῦ σκιᾶς, δειλότερον δὲ λαγὼ Φρυγός, ἐλάττω δ’ ἔχειν γῆν τὸν ἀγρὸν ἐπιστολῆς Λακωνικῆς· οὕτως ἐξοχὴ ἐπὶ ἐξοχῇ συντρέχει ἐπὶ τοῦ διιπετῆ τὸν Νεῖλον λέγεσθαι. ὁ μὲν γὰρ χειμάρρους ὑπερβέβληται τοὺς ἄλλους ποταμοὺς τῷ διιπετὴς εἶναι· ὁ δὲ Νεῖλος καὶ τοὺς χειμάρρους ἐπὶ τοσοῦτον πληρούμενος καὶ πλήθους καὶ χρόνου. ὥστ’ ἐπεὶ καὶ γνώριμον ἦν τὸ πάθος τοῦ ποταμοῦ τῷ ποιητῇ, ὡς παραμεμυθήμεθα, καὶ κέχρηται τῷ ἐπιθέτῳ τούτῳ κατ’ αὐτοῦ, οὐκ ἄλλως δεκτέον ἢ ὡς εἰρήκαμεν. τὸ δὲ πλείοσι στόμασιν ἐκδιδόναι κοινὸν καὶ πλειόνων, ὥστ’ οὐκ ἄξιον μνήμης ὑπέλαβε, καὶ ταῦτα πρὸς εἰδότας· καθάπερ οὐδ’ Ἀλκαῖος, καίτοι φήσας ἀφῖχθαι καὶ αὐτὸς εἰς Αἴγυπτον. αἱ δὲ προσχώσεις καὶ ἐκ τῶν ἀναβάσεων μὲν δύνανται ὑπονοεῖσθαι καὶ ἐξ ὧν δὲ εἶπε περὶ τῆς Φάρου. ὁ γὰρ ἱστορῶν αὐτῷ περὶ τῆς Φάρου, μᾶλλον δὲ ἡ κοινὴ φήμη, διότι μὲν τότε τοσοῦτον ἀπεῖχεν ἀπὸ τῆς ἠπείρου ὅσον φησί, δρόμον νεὼς ἡμερήσιον, οὐκ ἂν εἴη διατεθρυλημένη ἐπὶ τοσοῦτον ἐψευσμένως. ὅτι δ’ ἡ ἀνάβασις καὶ αἱ προσχώσεις τοιαῦταί τινες, κοινότερον πεπύσθαι εἰκὸς ἦν· ἐξ ὧν συνθεὶς ὁ ποιητὴς ὅτι πλέον ἢ τότε ἀφειστήκει τῆς γῆς ἡ νῆσος κατὰ τὴν Μενελάου παρουσίαν, προσέθηκε παρ’ ἑαυτοῦ πολλαπλάσιον διάστημα τοῦ μυθώδους χάριν. αἱ δὲ μυθοποιίαι οὐκ ἀγνοίας σημεῖον δήπου· οὐδὲ τὰ περὶ τοῦ Πρωτέως καὶ τῶν Πυγμαίων, οὐδ’ αἱ τῶν φαρμάκων δυνάμεις, οὐδ’ εἴ τι ἄλλο τοιοῦτον οἱ ποιηταὶ πλάττουσιν· οὐ γὰρ κατ’ ἄγνοιαν τῶν τοπικῶν λέγεται, ἀλλ’ ἡδονῆς καὶ τέρψεως χάριν. πῶς οὖν καὶ ἄνυδρον οὖσαν φησὶν ὕδωρ ἔχειν; “ἐν δὲ λιμὴν εὔορμος, ὅθεν τ’ ἀπὸ νῆας ἐίσας ἐς πόντον βάλλουσιν ἀφυσσάμενοι μέλαν ὕδωρ.” ἀλλ’ οὔτε τὸ ὑδρεῖον ἐκλιπεῖν ἀδύνατον οὔτε τὴν ὑδρείαν ἐκ τῆς νήσου γενέσθαι φησίν, ἀλλὰ τὴν ἀναγωγὴν μόνην διὰ τὴν τοῦ λιμένος ἀρετήν, τὸ δ’ ὕδωρ ἐκ τῆς περαίας ἀρύσασθαι παρῆν, ἐξομολογουμένου πως τοῦ ποιητοῦ δι’ ἐμφάσεως, ὅτι πελαγίαν εἶπεν οὐ πρὸς ἀλήθειαν ἀλλὰ πρὸς ὑπερβολὴν καὶ μυθοποιίαν.", "st": "1.2.30"}, {"sp": "N", "t": "Ἐπεὶ δὲ καὶ τὰ περὶ τῆς πλάνης τῆς Μενελάου λεχθέντα συνηγορεῖν δοκεῖ τῇ ἀγνοίᾳ τῇ περὶ τοὺς τόπους ἐκείνους, βέλτιον ἴσως ἐστὶ τὰ ἐν τοῖς ἔπεσι τούτοις ζητούμενα προεκθεμένους ἅμα ταῦτά τε διαστεῖλαι καὶ περὶ τοῦ ποιητοῦ ἀπολογήσασθαι καθαρώτερον. φησὶ δὴ πρὸς Τηλέμαχον ὁ Μενέλαος θαυμάσαντα τὸν τῶν βασιλείων κόσμον “ἦ γὰρ πολλὰ παθὼν καὶ πόλλ’ ἐπαληθεὶς ἠγαγόμην ἐν νηυσί, καὶ ὀγδοάτῳ ἔτει ἦλθον Κύπρον Φοινίκην τε καὶ Αἰγυπτίους ἐπαληθείς, Αἰθίοπάς θ’ ἱκόμην καὶ Σιδονίους καὶ Ἐρεμβοὺς καὶ Λιβύην.” ζητοῦσι δὲ πρὸς τίνας ἦλθεν Αἰθίοπας πλέων ἐξ Αἰγύπτου· οὔτε γὰρ ἐν τῇ καθ’ ἡμᾶς θαλάττῃ οἰκοῦσί τινες Αἰθίοπες, οὔτε τοῦ Νείλου τοὺς καταράκτας ἦν διελθεῖν ναυσί· τίνες τε οἱ Σιδόνιοι· οὐ γὰρ οἵ γε ἐν Φοινίκῃ· οὐ γὰρ ἂν τὸ γένος προθεὶς τὸ εἶδος ἐπήνεγκε· τίνες τε οἱ Ἐρεμβοί· καινὸν γὰρ τὸ ὄνομα. Ἀριστόνικος μὲν οὖν ὁ καθ’ ἡμᾶς γραμματικὸς ἐν τοῖς περὶ τῆς Μενελάου πλάνης πολλῶν ἀναγέγραφεν ἀνδρῶν ἀποφάσεις περὶ ἑκάστου τῶν ἐκκειμένων κεφαλαίων· ἡμῖν δ’ ἀρκέσει κἂν ἐπιτέμνοντες λέγωμεν. οἱ μὲν δὴ πλεῦσαι φήσαντες εἰς τὴν Αἰθιοπίαν οἱ μὲν περίπλουν τῶν διὰ Γαδείρων μέχρι τῆς Ἰνδικῆς εἰσάγουσιν, ἅμα καὶ τὸν χρόνον τῇ πλάνῃ συνοικειοῦντες, ὅν φησιν ὅτι ὀγδοάτῳ ἔτει ἦλθον, οἱ δὲ διὰ τοῦ ἰσθμοῦ τοῦ κατὰ τὸν Ἀράβιον κόλπον, οἱ δὲ διὰ τῶν διωρύγων τινός. οὔτε δ’ ὁ περίπλους ἀναγκαῖος, ὃν Κράτης εἰσάγει, οὐχ ὡς ἀδύνατος εἶναι (καὶ γὰρ [οὐδ’] ἡ Ὀδυσσέως πλάνη ἀδύνατος), ἀλλ’ ὅτι οὔτε πρὸς τὰς ὑποθέσεις τὰς μαθηματικὰς χρήσιμος οὔτε πρὸς τὸν χρόνον τῆς πλάνης. καὶ γὰρ ἀκούσιοι διατριβαὶ κατέσχον αὐτὸν ὑπὸ δυσπλοίας, φήσαντος ὅτι ἀπὸ ἑξήκοντα νεῶν πέντε ἐλείφθησαν αὐτῷ, καὶ ἑκούσιοι χρηματισμοῦ χάριν· φησὶ γὰρ ὁ Νέστωρ “ὣς ὁ μὲν ἔνθα πολὺν βίοτον καὶ χρυσὸν ἀγείρων, ἠλᾶτο ξὺν νηυσί· Κύπρον Φοινίκην τε καὶ Αἰγυπτίους ἐπαληθείς.” ὅ τε διὰ τοῦ ἰσθμοῦ πλοῦς ἢ τῶν διωρύγων λεγόμενος μὲν ἠκούετο ἂν ἐν μύθου σχήματι, μὴ λεγόμενος δὲ περιττῶς καὶ ἀπιθάνως εἰσάγοιτο ἄν. ἀπιθάνως δὲ λέγω, ὅτι πρὸ τῶν Τρωικῶν οὐδεμία ἦν διῶρυξ· τὸν δὲ ἐπιχειρήσαντα ποιῆσαι Σέσωστριν ἀποστῆναί φασι, μετεωροτέραν ὑπολαβόντα τὴν τῆς θαλάττης ἐπιφάνειαν. ἀλλὰ μὴν οὐδ’ ὁ ἰσθμὸς ἦν πλόιμος· ἀλλ’ εἰκάζει ὁ Ἐρατοσθένης οὐκ εὖ. μὴ γάρ πω τὸ ἔκρηγμα τὸ κατὰ τὰς στήλας γεγονέναι νομίζει· ὥστε ἐνταῦθα μὴ συνάπτειν τὴν εἴσω θάλατταν τῇ ἐκτὸς καὶ καλύπτειν τὸν ἰσθμὸν μετεωροτέραν οὖσαν, τοῦ δ’ ἐκρήγματος γενομένου ταπεινωθῆναι καὶ ἀνακαλύψαι τὴν γῆν τὴν κατὰ τὸ Κάσιον καὶ τὸ Πηλούσιον μέχρι τῆς Ἐρυθρᾶς. τίνα οὖν ἔχομεν ἱστορίαν περὶ τοῦ ἐκρήγματος τούτου διότι πρὸ τῶν Τρωικῶν οὔπω ὑπῆρχεν, ἴσως δ’ ὁ ποιητὴς ἅμα μὲν τὸν Ὀδυσσέα ταύτῃ διεκπλέοντα εἰς τὸν ὠκεανὸν πεποίηκεν ὡς ἤδη ἐκρήγματος γεγονότος, ἅμα δὲ εἰς τὴν Ἐρυθρὰν τὸν Μενέλαον ἐκ τῆς Αἰγύπτου ναυστολεῖ ὡς οὔπω γεγονότος. ἀλλὰ καὶ τὸν Πρωτέα εἰσάγει λέγοντα αὐτῷ “ἀλλά σ’ ἐς Ἠλύσιον πεδίον καὶ πείρατα γαίης ἀθάνατοι πέμψουσι.” ποῖα οὖν; καὶ ὅτι ἑσπέριόν τινα λέγει τόπον τοῦτον ἔσχατον ὁ ζέφυρος παρατεθεὶς δηλοῖ “ἀλλ’ αἰεὶ ζεφύροιο λιγὺ πνείοντας ἀήτας ὠκεανὸς ἀνίησι.” ταῦτα γὰρ αἰνίγματος πλήρη.", "st": "1.2.31"}, {"sp": "N", "t": "εἰ δ’ οὖν καὶ σύρρουν ποτὲ ὑπάρξαντα τὸν ἰσθμὸν τοῦτον ὁ ποιητὴς ἱστορήκει, πόσῳ μείζονα ἂν ἔχοιμεν πίστιν τοῦ τοὺς Αἰθίοπας διχθὰ διῃρῆσθαι, πορθμῷ τηλικούτῳ διειργομένους; τίς δὲ καὶ χρηματισμὸς παρὰ τῶν ἔξω καὶ κατὰ τὸν ὠκεανὸν Αἰθιόπων; ἅμα μὲν γὰρ θαυμάζουσι τοῦ κόσμου τῶν βασιλείων οἱ περὶ Τηλέμαχον τὸ πλῆθος ὅ ἐστι “χρυσοῦ τ’ ἠλέκτρου τε καὶ ἀργύρου ἠδ’ ἐλέφαντος.” τούτων δ’ οὐδενὸς πλὴν ἐλέφαντος εὐπορία παρ’ ἐκείνοις ἐστίν, ἀπορωτάτοις τῶν ἁπάντων οὖσι τοῖς πλείστοις καὶ νομάσι. νὴ Δία, ἀλλ’ ἡ Ἀραβία προσῆν καὶ τὰ μέχρι τῆς Ἰνδικῆς· τούτων δ’ ἡ μὲν εὐδαίμων κέκληται μόνη τῶν ἁπασῶν, τὴν δέ, εἰ καὶ μὴ ὀνομαστὶ καλοῦσιν, οὕτως ὑπολαμβάνουσί γε καὶ ἱστοροῦσιν ὡς εὐδαιμονεστάτην. τὴν μὲν οὖν Ἰνδικὴν οὐκ οἶδεν Ὅμηρος (εἰδὼς δὲ ἐμέμνητο ἄν), τὴν δ’ Ἀραβίαν, ἣν εὐδαίμονα προσαγορεύουσιν οἱ νῦν, τότε δ’ οὐκ ἦν πλουσία, ἀλλὰ καὶ αὐτὴ ἄπορος καὶ ἡ πολλὴ αὐτῆς σκηνιτῶν ἀνδρῶν· ὀλίγη δ’ ἡ ἀρωματοφόρος, δι’ ἣν καὶ τοῦτο τοὔνομα εὕρετο ἡ χώρα διὰ τὸ καὶ τὸν φόρτον εἶναι τὸν τοιοῦτον ἐν τοῖς παρ’ ἡμῖν σπάνιον καὶ τίμιον. νυνὶ μὲν οὖν εὐποροῦσι καὶ πλουτοῦσι διὰ τὸ καὶ τὴν ἐμπορίαν εἶναι πυκνὴν καὶ δαψιλῆ, τότε δ’ οὐκ εἰκός. αὐτῶν δὲ χάριν τῶν ἀρωμάτων ἐμπόρῳ μὲν καὶ καμηλίτῃ γένοιτ’ ἄν τις ἐκ τῶν τοιούτων φορτίων εὐπορία· Μενελάῳ δὲ λαφύρων ἢ δωρεῶν ἔδει παρὰ βασιλέων καὶ δυναστῶν, ἐχόντων τε ἃ δώσουσι καὶ βουλομένων [διδόναι] διὰ τὴν ἐπιφάνειαν αὐτοῦ καὶ εὔκλειαν. οἱ μὲν οὖν Αἰγύπτιοι καὶ οἱ πλησίον Αἰθίοπες καὶ Ἄραβες οὔθ’ οὕτω τελέως ἄβιοι οὔτ’ ἀνήκοοι τῆς τῶν Ἀτρειδῶν δόξης, καὶ μάλιστα διὰ τὴν κατόρθωσιν τοῦ Ἰλιακοῦ πολέμου, ὥστ’ ἐλπὶς ἦν τῆς ἐξ αὐτῶν ὠφελείας· καθάπερ ἐπὶ τοῦ θώρακος τοῦ Ἀγαμέμνονος λέγεται “τόν ποτέ οἱ Κινύρης δῶκε ξεινήιον εἶναι· πεύθετο γὰρ Κύπρονδε μέγα κλέος.” καὶ δὴ καὶ τὸν πλείω χρόνον τῆς πλάνης λεκτέον μὲν ἐν τοῖς κατὰ Φοινίκην καὶ Συρίαν καὶ Αἴγυπτον καὶ Λιβύην γενέσθαι καὶ τὰ περὶ Κύπρον χωρία καὶ ὅλως τὴν καθ’ ἡμᾶς παραλίαν καὶ τὰς νήσους· καὶ γὰρ ξένια παρὰ τούτοις καὶ τὸ βίᾳ καὶ τὸ ἐκ λεηλασίας πορίσασθαι, καὶ μάλιστα παρὰ τῶν συμμαχησάντων τοῖς Τρωσίν, ἐντεῦθεν ἦν. οἱ δ’ ἐκτὸς καὶ πόρρω βάρβαροι οὐδεμίαν τοιαύτην ὑπηγόρευον ἐλπίδα. εἰς οὖν τὴν Αἰθιοπίαν ἀφῖχθαι λέγεται ὁ Μενέλαος, οὐχ ὅτι … μέχρι τῶν ὅρων τῶν πρὸς Αἰγύπτῳ. τάχα μὲν γὰρ καὶ πλησιαίτεροι ἦσαν ταῖς Θήβαις οἱ τότε ὅροι, ἀλλὰ καὶ οἱ νῦν πλησίον εἰσίν, οἱ κατὰ Συήνην καὶ τὰς Φίλας· ὧν ἡ μὲν τῆς Αἰγύπτου ἐστίν, αἱ δὲ Φίλαι κοινὴ κατοικία τῶν Αἰθιόπων καὶ τῶν Αἰγυπτίων. ὁ οὖν εἰς Θήβας ἀφιγμένος εἰ καὶ μέχρι τῶν ὅρων ἀφῖκτο ἢ καὶ περαιτέρω τῶν Αἰθιόπων, καὶ ταῦτα τῇ βασιλικῇ ξενίᾳ χρώμενος, οὐδὲν ἄλογον. οὕτω δὲ καὶ Κυκλώπων εἰς γαῖαν ἀφῖχθαί φησιν ὁ Ὀδυσσεύς, μέχρι τοῦ σπηλαίου προεληλυθὼς ἀπὸ θαλάττης· ἐπ’ ἐσχατιᾶς γὰρ ἱδρῦσθαί που λέγει. καὶ εἰς Αἰολίαν δὲ καὶ Λαιστρυγόνας καὶ τοὺς ἄλλους, ὅπου ποτὲ καὶ καθωρμίσατο, ἐκεῖσέ φησιν ἀφῖχθαι. καὶ ὁ Μενέλαος οὖν οὕτως εἰς Αἰθιοπίαν ἧκεν, οὕτω δὲ καὶ εἰς Λιβύην, ὅτι προσέσχε τόποις τισίν· ἀφ’ οὗ καὶ ὁ κατὰ τὴν Ἀρδανίαν λιμὴν τὴν ὑπὲρ Παραιτονίου Μενέλαος καλεῖται.", "st": "1.2.32"}, {"sp": "N", "t": "εἰ δὲ Φοίνικας εἰπὼν ὀνομάζει καὶ Σιδωνίους τὴν μητρόπολιν αὐτῶν σχήματι συνήθει χρῆται, ὡς “Τρῶάς τε καὶ Ἕκτορα νηυσὶ πέλασσε,” καί “οὐ γὰρ ἔτ’ Οἰνῆος μεγαλήτορος υἱέες ἦσαν, οὐδ’ ἄρ’ ἔτ’ αὐτὸς ἔην, θάνε δὲ ξανθὸς Μελέαγρος,” καί “Ἴδην δ’ ἵκανεν καὶ Γάργαρον,” καί “οἳ δ’ Εὔβοιαν ἔχον καὶ Χαλκίδα τ’ Εἰρέτριάν τε.” καὶ Σαπφώ “ἤ σε Κύπρος ἢ Πάφος ἢ Πάνορμος.” καίτοι καὶ ἄλλο τι ἦν τὸ ποιῆσαν καίπερ ἤδη μνησθέντα τῆς Φοινίκης ἰδίως πάλιν καὶ τὴν Σιδῶνα συγκαταλέξαι. πρὸς μὲν γὰρ τὸ τὰ ἐφεξῆς ἔθνη καταλέξαι ἱκανῶς εἶχεν οὕτως εἰπεῖν “Κύπρον Φοινίκην τε καὶ Αἰγυπτίους ἐπαληθεὶς Αἰθίοπάς θ’ ἱκόμην·” ἵνα δ’ ἐμφήνῃ καὶ τὴν παρὰ τοῖς Σιδωνίοις ἀποδημίαν τὴν ἐπὶ πλέον γενομένην, καλῶς εἶχεν εἴτ’ ἀναλαβεῖν εἴτε καὶ παραλαβεῖν· ἐμφαίνει [δὲ] διὰ τῶν ἐπαίνων τῆς παρ’ αὐτοῖς εὐτεχνίας καὶ τοῦ τὴν Ἑλένην προεξενῶσθαι τοῖς ἀνθρώποις μετὰ Ἀλεξάνδρου· διόπερ παρὰ τῷ Ἀλεξάνδρῳ πολλὰ τοιαῦτα ἀποκείμενα λέγει “ἔνθ’ ἔσαν οἱ πέπλοι παμποίκιλοι, ἔργα γυναικῶν Σιδονίων, ἃς αὐτὸς Ἀλέξανδρος θεοειδὴς ἤγαγε Σιδονίηθεν τὴν ὁδόν, ἣν Ἑλένην περ ἀνήγαγε·” καὶ παρὰ τῷ Μενελάῳ· λέγει γὰρ πρὸς Τηλέμαχον “δώσω τοι κρητῆρα τετυγμένον· ἀργύρεος δὲ ἐστὶν ἅπας, χρυσῷ δ’ ἐπὶ χείλεα κεκράανται. ἄργον δ’ Ἡφαίστοιο· πόρεν δέ ἑ φαίδιμος ἥρως Σιδονίων βασιλεύς, ὅθ’ ἑὸς δόμος ἀμφεκάλυψε κεῖσέ με νοστήσαντα.” δεῖ δὲ δέξασθαι πρὸς ὑπερβολὴν εἰρημένον τὸ Ἡφαίστου ἔργον, ὡς λέγεται Ἀθηνᾶς ἔργα τὰ καλὰ καὶ Χαρίτων καὶ Μουσῶν. ἐπεὶ ὅτι γε οἱ ἄνδρες ἦσαν καλλίτεχνοι, δηλοῖ τὸν κρατῆρα ἐπαινῶν, ὃν ὁ Εὔνεως ἔδωκεν ἀντὶ Λυκάονος· φησὶ γάρ “κάλλει ἐνίκα πᾶσαν ἐπ’ αἶαν πολλόν· ἐπεὶ Σιδόνες πολυδαίδαλοι εὖ ἤσκησαν, Φοίνικες δ’ ἄγον ἄνδρες.”", "st": "1.2.33"}, {"sp": "N", "t": "περὶ δὲ τῶν Ἐρεμβῶν πολλὰ μὲν εἴρηται, πιθανώτατοι δ’ εἰσὶν οἱ νομίζοντες τοὺς Ἄραβας λέγεσθαι. Ζήνων δ’ ὁ ἡμέτερος καὶ γράφει οὕτως “Αἰθίοπάς θ’ ἱκόμην καὶ Σιδονίους Ἄραβάς τε.” τὴν μὲν οὖν γραφὴν οὐκ ἀνάγκη κινεῖν παλαιὰν οὖσαν· αἰτιᾶσθαι δὲ βέλτιον τὴν τοῦ ὀνόματος μετάπτωσιν πολλὴν καὶ ἐπιπολαίαν οὖσαν ἐν πᾶσι τοῖς ἔθνεσιν. ἀμέλει δὲ καὶ ποιοῦσί τινες παραγραμματίζοντες. ἄριστα δ’ ἂν δόξειεν εἰπεῖν ὁ Ποσειδώνιος κἀνταῦθα ἀπὸ τῆς τῶν ἐθνῶν συγγενείας καὶ κοινότητος ἐτυμολογῶν. τὸ γὰρ τῶν Ἀρμενίων ἔθνος καὶ τὸ τῶν Σύρων καὶ Ἀράβων πολλὴν ὁμοφυλίαν ἐμφαίνει κατά τε τὴν διάλεκτον καὶ τοὺς βίους καὶ τοὺς τῶν σωμάτων χαρακτῆρας, καὶ μάλιστα καθὸ πλησιόχωροί εἰσι. δηλοῖ δ’ ἡ Μεσοποταμία ἐκ τῶν τριῶν συνεστῶσα τούτων ἐθνῶν· μάλιστα γὰρ ἐν τούτοις ἡ ὁμοιότης διαφαίνεται. εἰ δέ τις παρὰ τὰ κλίματα γίνεται διαφορὰ τοῖς προσβόρροις ἐπὶ πλέον πρὸς τοὺς μεσημβρινοὺς καὶ τούτοις πρὸς μέσους τοὺς ὅρους, ἀλλ’ ἐπικρατεῖ γε τὸ κοινόν. καὶ οἱ Ἀσσύριοι δὲ καὶ οἱ Ἀριανοὶ παραπλησίως πως ἔχουσι καὶ πρὸς τούτους καὶ πρὸς ἀλλήλους. εἰκάζει γε δὴ καὶ τὰς τῶν ἐθνῶν τούτων κατονομασίας ἐμφερεῖς ἀλλήλαις εἶναι. τοὺς γὰρ ὑφ’ ἡμῶν Σύρους καλουμένους ὑπ’ αὐτῶν τῶν Σύρων Ἀραμμαίους καλεῖσθαι· τούτῳ δ’ ἐοικέναι τοὺς Ἀρμενίους καὶ τοὺς Ἄραβας καὶ Ἐρεμβούς, τάχα τῶν πάλαι Ἑλλήνων οὕτω καλούντων τοὺς Ἄραβας, ἅμα καὶ τοῦ ἐτύμου συνεργοῦντος πρὸς τοῦτο. ἀπὸ γὰρ τοῦ εἰς τὴν ἔραν ἐμβαίνειν τοὺς Ἐρεμβοὺς ἐτυμολογοῦσιν οὕτως οἱ πολλοί, οὓς μεταλαβόντες οἱ ὕστερον ἐπὶ τὸ σαφέστερον Τρωγλοδύτας ἐκάλεσαν· οὗτοι δέ εἰσιν Ἀράβων οἱ ἐπὶ θάτερον μέρος τοῦ Ἀραβίου κόλπου κεκλιμένοι, τὸ πρὸς Αἰγύπτῳ καὶ Αἰθιοπίᾳ. τούτων δ’ εἰκὸς μεμνῆσθαι τὸν ποιητὴν καὶ πρὸς τούτους ἀφῖχθαι λέγειν τὸν Μενέλαον, καθ’ ὃν τρόπον εἴρηται καὶ πρὸς τοὺς Αἰθίοπας· τῇ γὰρ Θηβαΐδι καὶ οὗτοι πλησιάζουσιν· ὁμοίως οὐκ ἐργασίας οὐδὲ χρηματισμοῦ χάριν τούτων ὀνομαζομένων (οὐ πολὺ γὰρ ἦν τοῦτο), ἀλλὰ τοῦ μήκους τῆς ἀποδημίας καὶ τοῦ ἐνδόξου· ἔνδοξον γὰρ τοσοῦτον ἐκτοπίσαι. τοιοῦτον δὲ καὶ τὸ “πολλῶν ἀνθρώπων ἴδεν ἄστεα καὶ νόον ἔγνω,” καὶ τὸ “ἦ γὰρ πολλὰ παθὼν καὶ πόλλ’ ἐπαληθεὶς ἠγαγόμην.” Ἡσίοδος δ’ ἐν Καταλόγῳ φησί “καὶ κούρην Ἀράβοιο, τὸν Ἑρμάων ἀκάκητα γείνατο καὶ Θρονίη, κούρη Βήλοιο ἄνακτος.” οὕτω δὲ καὶ Στησίχορος λέγει. εἰκάζειν οὖν ἐστιν ὅτι ἀπὸ τούτου καὶ ἡ χώρα Ἀραβία ἤδη τότε ὠνομάζετο, κατὰ δὲ τοὺς ἥρωας τυχὸν ἴσως οὔπω.", "st": "1.2.34"}, {"sp": "N", "t": "οἱ δὲ πλάττοντες Ἐρεμβοὺς ἴδιόν τι ἔθνος Αἰθιοπικὸν καὶ ἄλλο Κηφήνων καὶ τρίτον Πυγμαίων καὶ ἄλλα μυρία ἧττον ἂν πιστεύοιντο, πρὸς τῷ μὴ ἀξιοπίστῳ καὶ σύγχυσίν τινα ἐμφαίνοντες τοῦ μυθικοῦ καὶ ἱστορικοῦ σχήματος. ὅμοιοι δ’ εἰσὶ τούτοις καὶ οἱ Σιδονίους ἐν τῇ κατὰ Πέρσας θαλάττῃ διηγούμενοι ἢ ἄλλοθί που τοῦ ὠκεανοῦ, καὶ τὴν τοῦ Μενελάου πλάνην ἐξωκεανίζοντες· ὁμοίως δὲ καὶ τοὺς Φοίνικας. τῆς δ’ ἀπιστίας αἴτιον οὐκ ἐλάχιστόν ἐστι τὸ ἐναντιοῦσθαι ἀλλήλοις τοὺς λέγοντας. οἱ μὲν γὰρ καὶ τοὺς Σιδονίους τοὺς καθ’ ἡμᾶς ἀποίκους εἶναι τῶν ἐν τῷ ὠκεανῷ φασί, προστιθέντες καὶ διὰ τί Φοίνικες ἐκαλοῦντο, ὅτι καὶ ἡ θάλαττα ἐρυθρά· οἱ δ’ ἐκείνους τούτων. εἰσὶ δ’ οἳ καὶ τὴν Αἰθιοπίαν εἰς τὴν καθ’ ἡμᾶς Φοινίκην μετάγουσι καὶ τὰ περὶ τὴν Ἀνδρομέδαν ἐν Ἰόπῃ συμβῆναί φασιν· οὐ δήπου κατ’ ἄγνοιαν τοπικὴν καὶ τούτων λεγομένων, ἀλλ’ ἐν μύθου μᾶλλον σχήματι· καθάπερ καὶ τῶν παρ’ Ἡσιόδῳ καὶ τοῖς ἄλλοις, ἃ προφέρει ὁ Ἀπολλόδωρος, οὐδ’ ὃν τρόπον παρατίθησι τοῖς Ὁμήρου ταῦτα εἰδώς. τὰ μὲν γὰρ Ὁμήρου τὰ περὶ τὸν Πόντον καὶ τὴν Αἴγυπτον παρατίθησιν ἄγνοιαν αἰτιώμενος, ὡς λέγειν μὲν τὰ ὄντα βουλομένου, μὴ λέγοντος δὲ τὰ ὄντα, ἀλλὰ τὰ μὴ ὄντα ὡς ὄντα κατ’ ἄγνοιαν. Ἡσιόδου δ’ οὐκ ἄν τις αἰτιάσαιτο ἄγνοιαν, ἡμίκυνας λέγοντος καὶ μακροκεφάλους καὶ πυγμαίους· οὐδὲ γὰρ αὐτοῦ Ὁμήρου ταῦτα μυθεύοντος, ὧν εἰσι καὶ οὗτοι οἱ πυγμαῖοι, οὐδ’ Ἀλκμᾶνος στεγανόποδας ἱστοροῦντος, οὐδ’ Αἰσχύλου κυνοκεφάλους καὶ στερνοφθάλμους καὶ μονομμάτους, ὅπου γε οὐδὲ τοῖς πεζῇ συγγράφουσιν ἐν ἱστορίας σχήματι προσέχομεν περὶ πολλῶν, κἂν μὴ ἐξομολογῶνται τὴν μυθογραφίαν. φαίνεται γὰρ εὐθὺς ὅτι μύθους παραπλέκουσιν ἑκόντες οὐκ ἀγνοίᾳ τῶν ὄντων, ἀλλὰ πλάσει τῶν ἀδυνάτων τερατείας καὶ τέρψεως χάριν. δοκοῦσι δὲ κατ’ ἄγνοιαν, ὅτι μάλιστα καὶ πιθανῶς τὰ τοιαῦτα μυθεύουσι περὶ τῶν ἀδήλων καὶ τῶν ἀγνοουμένων. Θεόπομπος δὲ ἐξομολογεῖται φήσας ὅτι καὶ μύθους ἐν ταῖς ἱστορίαις ἐρεῖ, κρεῖττον ἢ ὡς Ἡρόδοτος καὶ Κτησίας καὶ Ἑλλάνικος καὶ οἱ τὰ Ἰνδικὰ συγγράψαντες.", "st": "1.2.35"}, {"sp": "N", "t": "περὶ δὲ τῶν τοῦ ὠκεανοῦ παθῶν εἴρηται μὲν ἐν μύθου σχήματι· καὶ γὰρ τούτου στοχάζεσθαι δεῖ τὸν ποιητήν. ἀπὸ γὰρ τῶν ἀμπώτεων καὶ τῶν πλημμυρίδων ἡ Χάρυβδις αὐτῷ μεμύθευται, οὐδ’ αὐτὴ παντάπασιν Ὁμήρου πλάσμα οὖσα, ἀλλ’ ἀπὸ τῶν ἱστορουμένων περὶ τὸν Σικελικὸν πορθμὸν διεσκευασμένη. εἰ δὲ δὶς τῆς παλιρροίας γινομένης καθ’ ἑκάστην ἡμέραν καὶ νύκτα ἐκεῖνος τρὶς εἴρηκε “τρὶς μὲν γάρ τ’ ἀνίησιν ἐπ’ ἤματι, τρὶς δ’ ἀναροιβδεῖ,” λέγοιτ’ ἂν καὶ οὕτως· οὐ γὰρ κατ’ ἄγνοιαν τῆς ἱστορίας ὑποληπτέον λέγεσθαι τοῦτο, ἀλλὰ τραγῳδίας χάριν καὶ φόβου, ὃν ἡ Κίρκη πολὺν τοῖς λόγοις προστίθησιν ἀποτροπῆς χάριν, ὥστε καὶ τὸ ψεῦδος παραμίγνυσθαι. ἐν αὐτοῖς γοῦν τοῖς ἔπεσι τούτοις εἴρηκε μὲν οὕτως ἡ Κίρκη “τρὶς μὲν γάρ τ’ ἀνίησιν ἐπ’ ἤματι, τρὶς δ’ ἀναροιβδεῖ δεινόν· μὴ σύ γε κεῖθι τύχοις, ὅτε ῥοιβδήσειε· οὐ γάρ κεν ῥύσαιτό σ’ ὑπὲκ κακοῦ οὐδ’ Ἐνοσίχθων.” καὶ μὴν παρέτυχέ τε τῇ ἀναρροιβδήσει ὁ Ὀδυσσεὺς καὶ οὐκ ἀπώλετο, ὥς φησιν αὐτός “ἡ μὲν ἀνερροίβδησε θαλάσσης ἁλμυρὸν ὕδωρ· αὐτὰρ ἐγὼ ποτὶ μακρὸν ἐρινεὸν ὑψόσ’ ἀερθείς, τῷ προσφὺς ἐχόμην, ὡς νυκτερίς.” εἶτα περιμείνας τὰ ναυάγια καὶ λαβόμενος πάλιν αὐτῶν σώζεται, ὥστ’ ἐψεύσατο ἡ Κίρκη. ὡς οὖν τοῦτο, κἀκεῖνο τὸ “τρὶς μὲν γάρ τ’ ἀνίησιν ἐπ’ ἤματι” ἀντὶ τοῦ δίς, ἅμα καὶ τῆς ὑπερβολῆς τῆς τοιαύτης συνήθους πᾶσιν οὔσης, τρισμακαρίους καὶ τρισαθλίους λεγόντων· καὶ ὁ ποιητής “τρισμάκαρες Δαναοί,” καί “ἀσπασίη τρίλλιστος,” “τριχθά τε καὶ τετραχθά.” ἴσως δ’ ἄν τις καὶ ἀπὸ τῆς ὥρας τεκμήραιτο, ὅτι ὑπαινίττεταί πως τὸ ἀληθές· μᾶλλον γὰρ ἂν ἐφαρμόττοι τῷ δὶς γενέσθαι τὴν παλίρροιαν κατὰ τὸν συνάμφω χρόνον, τὸν ἐξ ἡμέρας καὶ νυκτός, ἢ τῷ τρὶς τοσοῦτον χρόνον μεῖναι τὰ ναυάγια ὑποβρύχια, ὀψὲ δὲ ἀναβληθῆναι ποθοῦντι. καὶ συνεχῶς προσισχομένῳ τοῖς κλάδοις “νωλεμέως δ’ ἐχόμην, ὄφρ’ ἐξεμέσειεν ὀπίσσω ἱστὸν καὶ τρόπιν αὖτις, ἐελδομένῳ δέ μοι ἦλθεν ὄψ’· ἦμός τ’ ἐπὶ δόρπον ἀνὴρ ἀγορῆθεν ἀνέστη, κρίνων νείκεα πολλὰ δικαζομένων αἰζηῶν, καὶ τότε δήμοι δοῦρα Χαρύβδιος ἐξεφαάνθη.” πάντα γὰρ ταῦτα χρόνου τινὸς ἔμφασιν ἀξιολόγου δίδωσι, καὶ μάλιστα τὸ τὴν ἑσπέραν ἐπιτεῖναι, μὴ κοινῶς εἰπόντα, ἡνίκα ὁ δικαστὴς ἀνίσταται, ἀλλ’ ἡνίκα κρίνων νείκεα πολλά, ὥστε βραδῦναι πλέον τι καὶ ἄλλως δὲ οὐ πιθανὴν ἂν ὑπέτεινε τῷ ναυαγῷ τὴν ἀπαλλαγήν, εἰ πρὶν ἀποσπασθῆναι πολὺ καὶ αὐτίκα εἰς τοὐπίσω παλίρρους μετέπιπτεν.", "st": "1.2.36"}, {"sp": "N", "t": "Ἀπολλόδωρος δὲ ἐπιτιμᾷ Καλλιμάχῳ, συνηγορῶν τοῖς περὶ τὸν Ἐρατοσθένη, διότι καίπερ γραμματικὸς ὢν παρὰ τὴν Ὁμηρικὴν ὑπόθεσιν καὶ τὸν ἐξωκεανισμὸν τῶν τόπων, περὶ οὓς τὴν πλάνην φράζει, Γαῦδον καὶ Κόρκυραν ὀνομάζει. ἀλλ’ εἰ μὲν μηδαμοῦ γέγονεν ἡ πλάνη, ἀλλ’ ὅλον πλάσμα ἐστὶν Ὁμήρου τοῦτο, ὀρθὴ ἡ ἐπιτίμησις· ἢ εἰ γέγονε μέν, περὶ ἄλλους δὲ τόπους, δεῖ λέγειν εὐθὺς καὶ περὶ τίνας, ἐπανορθούμενον ἅμα τὴν ἄγνοιαν. μήτε δὲ ὅλου πλάσματος εἶναι πιθανῶς λεγομένου, καθάπερ ἐπεδείκνυμεν, μήτ’ ἄλλων τόπων κατὰ πίστιν μείζω δεικνυμένων, ἀπολύοιτ’ ἂν τῆς αἰτίας ὁ Καλλίμαχος.", "st": "1.2.37"}, {"sp": "N", "t": "οὐδ’ ὁ Σκήψιος δὲ Δημήτριος εὖ, ἀλλὰ καὶ τῷ Ἀπολλοδώρῳ τῶν ἁμαρτιῶν ἐνίων αἴτιος ἐκεῖνος κατέστη. πρὸς γὰρ Νεάνθη τὸν Κυζικηνὸν φιλοτιμοτέρως ἀντιλέγων εἰπόντα ὅτι οἱ Ἀργοναῦται πλέοντες εἰς Φᾶσιν τὸν ὑφ’ Ὁμήρου καὶ τῶν ἄλλων ὁμολογούμενον πλοῦν ἱδρύσαντο τὰ τῆς Ἰδαίας μητρὸς ἱερὰ περὶ Κύζικον, ἀρχὴν φησὶ μηδ’ εἰδέναι τὴν εἰς Φᾶσιν ἀποδημίαν τοῦ Ἰάσονος Ὅμηρον. τοῦτο δ’ οὐ μόνον τοῖς ὑφ’ Ὁμήρου λεγομένοις μάχεται, ἀλλὰ καὶ τοῖς ὑπ’ αὐτοῦ. φησὶ γὰρ τὸν Ἀχιλλέα Λέσβον μὲν πορθῆσαι καὶ ἄλλα χωρία, Λήμνου δ’ ἀποσχέσθαι καὶ τῶν πλησίον νήσων διὰ τὴν πρὸς Ἰάσονα καὶ τὸν υἱὸν Εὔνεων συγγένειαν τότε τὴν νῆσον κατέχοντα. πῶς οὖν ὁ ποιητὴς τοῦτο μὲν ᾔδει, διότι συγγενεῖς ἢ ὁμοεθνεῖς ἢ γείτονες ἢ ὁπωσοῦν οἰκεῖοι ὑπῆρχον ὅ τε Ἀχιλλεὺς καὶ ὁ Ἰάσων (ὅπερ οὐδαμόθεν ἄλλοθεν ἀλλ’ ἐκ τοῦ Θετταλοὺς ἀμφοτέρους εἶναι συνέβαινε, καὶ τὸν μὲν Ἰώλκιον τὸν δ’ ἐκ τῆς Φθιώτιδος Ἀχαιίδος ὑπάρχειν), τοῦτο δ’ ἠγνόει, πόθεν ἦλθε τῷ Ἰάσονι, Θετταλῷ καὶ Ἰωλκίῳ ὑπάρχοντι, ἐν μὲν τῇ πατρίδι μηδεμίαν καταλιπεῖν διαδοχήν, Λήμνου δὲ καταστῆσαι κύριον τὸν υἱόν; καὶ Πελίαν μὲν ᾔδει καὶ τὰς Πελιάδας καὶ τὴν ἀρίστην αὐτῶν καὶ τὸν υἱὸν αὐτῆς “Εὔμηλον, τὸν ὑπ’ Ἀδμήτῳ τέκε δῖα γυναικῶν Ἄλκηστις, Πελίαο θυγατρῶν εἶδος ἀρίστη,” τῶν δὲ περὶ τὸν Ἰάσονα συμβάντων καὶ τὴν Ἀργὼ καὶ τοὺς Ἀργοναύτας, τῶν ὁμολογουμένων παρὰ πᾶσιν, ἀνήκοος ἦν, ἐν δὲ τῷ ὠκεανῷ τὸν παρ’ Αἰήτου πλοῦν ἔπλαττεν, ἀρχὴν μηδεμίαν ἐξ ἱστορίας λαβών;", "st": "1.2.38"}, {"sp": "N", "t": "ὡς μὲν γὰρ ἅπαντες λέγουσιν, ὅτι ἐξ ἀρχῆς ὁ πλοῦς ἐπὶ Φᾶσιν ἔχει πιθανόν τι τοῦ Πελίου στείλαντος, καὶ ἡ ἐπάνοδος καὶ ἡ ἐν τῷ παράπλῳ νήσων ὁσηδὴ ἐπικράτεια καὶ νὴ Δία ἡ ἐπὶ πλέον γενηθεῖσα πλάνη, καθάπερ καὶ τῷ Ὀδυσσεῖ καὶ τῷ Μενελάῳ, ἐκ τῶν ἔτι νῦν δεικνυμένων καὶ πεπιστευμένων ἐστὶν ἐκ τῆς Ὁμήρου φωνῆς. ἥ τε γὰρ Αἶα δείκνυται περὶ Φᾶσιν πόλις, καὶ ὁ Αἰήτης πεπίστευται βασιλεῦσαι τῆς Κολχίδος, καὶ ἔστι τοῖς ἐκεῖ τοῦτ’ ἐπιχώριον τοὔνομα. ἥ τε Μήδεια φαρμακὶς ἱστορεῖται, καὶ ὁ πλοῦτος τῆς ἐκεῖ χώρας ἐκ τῶν χρυσείων καὶ ἀργυρείων καὶ σιδηρείων δικαίαν τινὰ ὑπαγορεύει πρόφασιν τῆς στρατείας, καθ’ ἣν καὶ Φρίξος πρότερον ἔστειλε τὸν πλοῦν τοῦτον· καὶ ἔστιν ὑπομνήματα τῆς ἀμφοῖν στρατείας τό τε Φρίξειον τὸ ἐν τοῖς μεθορίοις τῆς τε Κολχίδος καὶ τῆς Ἰβηρίας, καὶ τὰ Ἰασόνεια, ἃ πολλαχοῦ καὶ τῆς Ἀρμενίας καὶ τῆς Μηδίας καὶ τῶν πλησιοχώρων αὐταῖς τόπων δείκνυται. καὶ μὴν καὶ περὶ Σινώπην καὶ τὴν ταύτης παραλίαν καὶ τὴν Προποντίδα καὶ τὸν Ἑλλήσποντον μέχρι τῶν κατὰ τὴν Λῆμνον τόπων λέγεται πολλὰ τεκμήρια τῆς τε Ἰάσονος στρατείας καὶ τῆς Φρίξου· τῆς δ’ Ἰάσονος καὶ τῶν ἐπιδιωξάντων Κόλχων καὶ μέχρι τῆς Κρήτης καὶ τῆς Ἰταλίας καὶ τοῦ Ἀδρίου, ὧν ἔνια καὶ ὁ Καλλίμαχος ἐπισημαίνεται, τοτὲ μὲν “Αἰγλήτην Ἀνάφην τε Λακωνίδι γείτονα Θήρῃ” λέγων “ἄρχμενος, ὡς ἥρωες ἀπ’ Αἰήταο Κυταίου αὖτις ἐς ἀρχαίην ἔπλεον Αἱμονίην,” τοτὲ δὲ περὶ τῶν Κόλχων οἳ μὲν ἐπ’ Ἰλλυριοῖο πόρου σχάσσαντες ἐρετμὰ λᾶα πάρα ξανθῆς Ἁρμονίης τάφιον ἄστυρον ἐκτίσσαντο, τό κεν φυγάδων τις ἐνίσποι Γραικός, ἀτὰρ κείνων γλῶσσ’ ὀνόμηνε Πόλας. τινὲς δὲ καὶ τὸν Ἴστρον ἀναπλεῦσαί φασι μέχρι πολλοῦ τοὺς περὶ τὸν Ἰάσονα, οἱ δὲ καὶ μέχρι τοῦ Ἀδρίου· οἱ μὲν κατὰ ἄγνοιαν τῶν τόπων, οἱ δὲ καὶ ποταμὸν Ἴστρον ἐκ τοῦ μεγάλου Ἴστρου τὴν ἀρχὴν ἔχοντα ἐκβάλλειν εἰς τὸν Ἀδρίαν φασί· τάδε οὐκ * ἀπιθάνως οὐδ’ ἀπίστως λέγοντες.", "st": "1.2.39"}, {"sp": "N", "t": "τοιαύταις δή τισιν ἀφορμαῖς ὁ ποιητὴς χρησάμενος τὰ μὲν ὁμολογεῖ τοῖς ἱστορουμένοις, προσμυθεύει δὲ τούτοις, ἔθος τι φυλάττων καὶ κοινὸν καὶ ἴδιον. ὁμολογεῖ μέν, ὅταν Αἰήτην ὀνομάζῃ, καὶ τὸν Ἰάσονα καὶ τὴν Ἀργὼ λέγῃ, καὶ παρὰ [τὴν Αἶαν] τὴν Αἰαίην πλάττῃ, καὶ τὸν Εὔνεων ἐν Λήμνῳ καθιδρύῃ, καὶ ποιῇ τῷ Ἀχιλλεῖ φίλην τὴν νῆσον, καὶ παρὰ τὴν Μήδειαν τὴν Κίρκην φαρμακίδα ποιῇ “αὐτοκασιγνήτην ὀλοόφρονος Αἰήταο·” προσμυθοποιεῖ δὲ τὸν ἐξωκεανισμὸν τὸν κατὰ τὴν πλάνην συμβάντα τὴν ἀπ’ ἐκείνου τοῦ πλοῦ. ἐπεὶ κἀκεῖνο ὑποκειμένων μὲν τούτων εὖ λέγεται “Ἀργὼ πασιμέλουσα,” ὡς ἐν γνωρίμοις τόποις καὶ εὐανδροῦσι τῆς ναυστολίας γενομένης· εἰ δ’, ὥσπερ ὁ Σκήψιός φησι παραλαβὼν μάρτυρα Μίμνερμον, ὃς ἐν τῷ ὠκεανῷ ποιήσας τὴν οἴκησιν τοῦ Αἰήτου πρὸς ταῖς ἀνατολαῖς ἐκτὸς πεμφθῆναί φησιν ὑπὸ τοῦ Πελίου τὸν Ἰάσονα καὶ κομίσαι τὸ δέρος, οὔτ’ ἂν ἡ ἐπὶ τὸ δέρος ἐκεῖσε πομπὴ πιθανῶς λέγοιτο εἰς ἀγνῶτας καὶ ἀφανεῖς τόπους, οὔθ’ ὁ δι’ ἐρήμων καὶ ἀοίκων καὶ καθ’ ἡμᾶς τοσοῦτον ἐκτετοπισμένων πλοῦς οὔτ’ ἔνδοξος οὔτε πασιμέλων.", "st": "1.2.40"}, {"sp": "N", "t": "οὐδὲ τοῦτ’ εὖ Ἐρατοσθένης, ὅτι ἀνδρῶν οὐκ ἐξίων μνήμης ἐπὶ πλέον μέμνηται, τὰ μὲν ἐλέγχων τὰ δὲ πιστεύων καὶ μάρτυσι χρώμενος αὐτοῖς, οἷον Δαμάστῃ καὶ τοιούτοις ἄλλοις. καὶ γὰρ εἴ τι λέγουσιν ἀληθές, οὐ μάρτυσί γε ἐκείνοις χρηστέον περὶ αὐτοῦ, οὐδὲ πιστευτέον διὰ τοῦτο· ἀλλ’ ἐπὶ τῶν ἀξιολόγων ἀνδρῶν μόνων τῷ τοιούτῳ τρόπῳ χρηστέον, οἳ πολλὰ μὲν εἰρήκασιν εὖ, πολλὰ δὲ καὶ παραλελοίπασιν ἢ οὐχ ἱκανῶς ἐξεῖπον, οὐδὲν δ’ ἐψευσμένως. ὁ δὲ Δαμάστῃ χρώμενος μάρτυρι οὐδὲν διαφέρει τοῦ καλοῦντος μάρτυρα τὸν Βεργαῖον Εὐήμερον καὶ τοὺς ἄλλους, οὓς αὐτὸς εἴρηκε διαβάλλων τὴν φλυαρίαν. καὶ τούτου δ’ ἕνα τῶν λήρων αὐτὸς λέγει, τὸν μὲν Ἀράβιον κόλπον λίμνην ὑπολαμβάνοντος εἶναι, Διότιμον δὲ τὸν Στρομβίχου πρεσβείας Ἀθηναίων ἀφηγούμενον διὰ τοῦ Κύδνου ἀναπλεῦσαι ἐκ τῆς Κιλικίας ἐπὶ τὸν Χοάσπην ποταμόν, ὃς παρὰ τὰ Σοῦσα ῥεῖ, καὶ ἀφικέσθαι τετταρακοσταῖον εἰς Σοῦσα· ταῦτα δ’ αὐτῷ διηγήσασθαι αὐτὸν τὸν Διότιμον. εἶτα θαυμάζειν εἰ τὸν Εὐφράτην καὶ τὸν Τίγριν ἦν δυνατὸν διακόψαντα τὸν Κύδνον εἰς τὸν Χοάσπην ἐκβαλεῖν.", "st": "1.3.1"}, {"sp": "N", "t": "οὐ μόνον δὲ ταῦτ’ ἄν τις ἐπισημήναιτο, ἀλλ’ ὅτι καὶ περὶ τῶν τόπων οὐδὲ καθ’ ἑαυτόν πω γνώριμα εἶναί φησι τὰ καθ’ ἕκαστα ἀκριβολογούμενα, καὶ κελεύσας ἡμῖν μὴ ῥᾳδίως τοῖς τυχοῦσι πιστεύειν, καὶ τὰς αἰτίας διὰ μακρῶν ἀποδοὺς δι’ ἃς οὐδὲ πιστευτέον, οἷον περὶ τῶν κατὰ τὸν Πόντον καὶ τὸν Ἀδρίαν, αὐτὸς ἐπίστευσε τοῖς τυχοῦσι. τοιγάρτοι τὸν μὲν Ἰσσικὸν κόλπον ἐπίστευσεν ἑωθινώτατον τῆς καθ’ ἡμᾶς θαλάττης σημεῖον, τοῦ κατὰ Διοσκουριάδα τὴν ἐν τῷ τοῦ Πόντου μυχῷ σχεδόν τι καὶ τρισχιλίοις σταδίοις ἑωθινωτέρου ὄντος καὶ κατ’ αὐτὸν ἐκ τοῦ σταδιασμοῦ οὗ φησί· τοῦ τε Ἀδρίου καὶ τὰ ἀρκτικὰ καὶ τὰ ἔσχατα διεξιὼν οὐδενὸς ἀπέχεται μυθώδους. πεπίστευκε δὲ καὶ περὶ τῶν ἔξω στηλῶν Ἡρακλείων πολλοῖς μυθώδεσι, Κέρνην τε νῆσον καὶ ἄλλους τόπους ὀνομάζων τοὺς μηδαμοῦ νυνὶ δεικνυμένους, περὶ ὧν μνησθησόμεθα καὶ ὕστερον. εἰπών τε τοὺς ἀρχαιοτάτους πλεῖν καὶ κατὰ λῃστείαν ἢ ἐμπορίαν, μὴ πελαγίζειν δέ, ἀλλὰ παρὰ γῆν, καθάπερ τὸν Ἰάσονα, ὅνπερ καὶ μέχρι τῆς Ἀρμενίας καὶ Μηδίας ἐκ τῶν Κόλχων στρατεῦσαι ἀφέντα τὰς ναῦς, ὕστερόν φησι τὸ παλαιὸν οὔτε τὸν Εὔξεινον θαρρεῖν τινα πλεῖν οὔτε παρὰ Λιβύην καὶ Συρίαν καὶ Κιλικίαν. εἰ μὲν οὖν τοὺς πάλαι τοὺς πρὸ τῆς ἡμετέρας λέγει μνήμης, οὐδὲν ἐμοὶ μέλει περὶ ἐκείνων λέγειν, οὔτ’ εἰ ἔπλεον οὔτ’ εἰ μή· εἰ δὲ περὶ τῶν μνημονευομένων, οὐκ ἂν ὀκνήσαι τις εἰπεῖν ὡς οἱ παλαιοὶ μακροτέρας ὁδοὺς φανοῦνται καὶ κατὰ γῆν καὶ κατὰ θάλατταν τελέσαντες τῶν ὕστερον, εἰ χρὴ προσέχειν τοῖς λεγομένοις· οἷον Διόνυσος καὶ Ἡρακλῆς καὶ αὐτὸς ὁ Ἰάσων, ἔτι δ’ οἱ ὑπὸ τοῦ ποιητοῦ λεγόμενοι Ὀδυσσεὺς καὶ Μενέλαος. καὶ Θησέα δὲ καὶ Πειρίθουν μακρὰς εἰκός ἐστι στρατείας ὑπομείναντας καταλιπεῖν δόξαν περὶ ἑαυτῶν ὡς εἰς Ἅιδου καταβάντας, τοὺς δὲ Διοσκούρους ἐπιμελητὰς τῆς θαλάττης λεχθῆναι καὶ σωτῆρας τῶν πλεόντων. ἥ τε Μίνω θαλαττοκρατία θρυλεῖται καὶ ἡ Φοινίκων ναυτιλία, οἳ καὶ τὰ ἔξω τῶν Ἡρακλείων στηλῶν ἐπῆλθον καὶ πόλεις ἔκτισαν κἀκεῖ καὶ περὶ τὰ μέσα τῆς Λιβύης παραλίας μικρὸν τῶν Τρωικῶν ὕστερον. Αἰνείαν δὲ καὶ Ἀντήνορα καὶ Ἐνετοὺς καὶ ἁπλῶς τοὺς ἐκ τοῦ Τρωικοῦ πολέμου πλανηθέντας εἰς πᾶσαν τὴν οἰκουμένην ἄξιον μὴ τῶν παλαιῶν ἀνθρώπων νομίσαι; συνέβη γὰρ δὴ τοῖς τότε Ἕλλησιν ὁμοίως καὶ τοῖς βαρβάροις διὰ τὸν τῆς στρατείας χρόνον ἀποβαλεῖν τά τε ἐν οἴκῳ καὶ τῇ στρατείᾳ πορισθέντα· ὥστε μετὰ τὴν τοῦ Ἰλίου καταστροφὴν τούς τε νικήσαντας ἐπὶ λῃστείαν τραπέσθαι διὰ τὰς ἀπορίας καὶ πολὺ μᾶλλον τοὺς ἡττηθέντας καὶ περιγενομένους ἐκ τοῦ πολέμου. καὶ δὴ καὶ πόλεις ὑπὸ τούτων πλεῖσται κτισθῆναι λέγονται κατὰ πᾶσαν τὴν ἔξω τῆς Ἑλλάδος παραλίαν, ἔστι δ’ ὅπου καὶ τὴν μεσόγαιαν.", "st": "1.3.2"}, {"sp": "N", "t": "εἰπὼν δὲ καὶ αὐτὸς ὁπόσον προὔβη τὰ τῆς οἰκουμένης εἰς γνῶσιν τοῖς μετ’ Ἀλέξανδρον καὶ κατ’ αὐτὸν ἤδη, μεταβέβηκεν ἐπὶ τὸν περὶ τοῦ σχήματος λόγον, οὐχὶ περὶ τοῦ τῆς οἰκουμένης, ὅπερ ἦν οἰκειότερον τῷ περὶ αὐτῆς λόγῳ, ἀλλὰ τοῦ τῆς συμπάσης γῆς· δεῖ μὲν γὰρ καὶ τούτου μνησθῆναι, μὴ ἀτάκτως δέ. εἰπὼν οὖν ὅτι σφαιροειδὴς ἡ σύμπασα, οὐχ ὡς ἐκ τόρνου δέ, ἀλλ’ ἔχει τινὰς ἀνωμαλίας, ἐπιφέρει τὸ πλῆθος τῶν ἐν μέρει μετασχηματισμῶν αὐτῆς, οἳ συμβαίνουσιν ἔκ τε ὕδατος καὶ πυρὸς καὶ σεισμῶν καὶ ἀναφυσημάτων καὶ ἄλλων τοιούτων, οὐδ’ ἐνταῦθα τὴν τάξιν φυλάττων. τὸ μὲν γὰρ σφαιροειδὲς περὶ ὅλην τὴν γῆν ἀπὸ τῆς τοῦ ὅλου ἕξεως συμβαίνει, οἱ δὲ τοιοῦτοι μετασχηματισμοὶ τὴν μὲν ὅλην γῆν οὐδὲν ἐξαλλάττουσιν· ἐν γὰρ τοῖς μεγάλοις ἐναφανίζεται τὰ οὕτω μικρά· τῆς δὲ οἰκουμένης διαθέσεις ἑτέρας καὶ ἑτέρας τινὰς ἀπεργάζονται καὶ τὰς προσεχεῖς αἰτίας ἄλλας καὶ ἄλλας ἔχουσι.", "st": "1.3.3"}, {"sp": "N", "t": "μάλιστα δέ φησι ζήτησιν παρασχεῖν πῶς ἐν δισχιλίοις καὶ τρισχιλίοις ἀπὸ θαλάττης σταδίοις κατὰ τὴν μεσόγαιαν ὁρᾶται πολλαχοῦ κόγχων καὶ ὀστρέων καὶ χηραμύδων πλῆθος καὶ λιμνοθάλατται, καθάπερ φησὶ περὶ τὸ ἱερὸν τοῦ Ἄμμωνος καὶ τὴν ἐπ’ αὐτῷ ὁδὸν τρισχιλίων σταδίων οὖσαν· πολλὴν γὰρ εἶναι χύσιν ὀστρέων, ἅλας τε καὶ νῦν ἔτι εὑρίσκεσθαι πολλούς, ἀναφυσήματά τε θαλάττης εἰς ὕψος ἀναβάλλειν· πρὸς ᾧ καὶ ναυάγια θαλαττίων πλοίων δείκνυσθαι, ἃ ἔφασαν διὰ τοῦ χάσματος ἐκβεβράσθαι, καὶ ἐπὶ στυλιδίων ἀνακεῖσθαι δελφῖνας ἐπιγραφὴν ἔχοντας Κυρηναίων θεωρῶν. ταῦτα δ’ εἰπὼν τὴν Στράτωνος ἐπαινεῖ δόξαν τοῦ φυσικοῦ, καὶ ἔτι Ξάνθου τοῦ Λυδοῦ· τοῦ μὲν Ξάνθου λέγοντος ἐπὶ Ἀρταξέρξου γενέσθαι μέγαν αὐχμὸν ὥστ’ ἐκλιπεῖν ποταμοὺς καὶ λίμνας καὶ φρέατα· αὐτόν τε εἰδέναι πολλαχῆ πρόσω ἀπὸ τῆς θαλάττης λίθον τε κογχυλιώδη καὶ τὰ κτενώδεα καὶ χηραμύδων τυπώματα καὶ λιμνοθάλατταν ἐν Ἀρμενίοις καὶ Ματιηνοῖς καὶ ἐν Φρυγίᾳ τῇ κάτω, ὧν ἕνεκα πείθεσθαι τὰ πεδία ποτὲ θάλατταν γενέσθαι. τοῦ δὲ Στράτωνος ἔτι μᾶλλον ἁπτομένου τῆς αἰτιολογίας, ὅτι φησὶν οἴεσθαι τὸν Εὔξεινον μὴ ἔχειν πρότερον τὸ κατὰ Βυζάντιον στόμα, τοὺς δὲ ποταμοὺς βιάσασθαι καὶ ἀνοῖξαι τοὺς εἰς αὐτὸν ἐμβάλλοντας, εἶτ’ ἐκπεσεῖν τὸ ὕδωρ εἰς τὴν Προποντίδα καὶ τὸν Ἑλλήσποντον. τὸ δ’ αὐτὸ συμβῆναι καὶ περὶ τὴν καθ’ ἡμᾶς θάλατταν· καὶ γὰρ ἐνταῦθα τὸν κατὰ στήλας ἐκραγῆναι πόρον, πληρωθείσης ὑπὸ τῶν ποταμῶν τῆς θαλάττης, κατὰ δὲ τὴν ἔκρυσιν ἀνακαλυφθῆναι τὰ τεναγώδη πρότερον. φέρει δ’ αἰτίαν πρῶτον μὲν ὅτι τῆς ἔξω θαλάττης καὶ τῆς ἐντὸς τοὔδαφος ἕτερόν ἐστιν, ἔπειθ’ ὅτι καὶ νῦν ἔτι ταινία τις ὕφαλος διατέτακεν ἀπὸ τῆς Εὐρώπης ἐπὶ τὴν Λιβύην, ὡς ἂν [μὴ] μιᾶς οὔσης πρότερον τῆς τε ἐντὸς καὶ τῆς ἐκτός. καὶ βραχύτατα μὲν εἶναι τὰ περὶ τὸν Πόντον, τὸ δὲ Κρητικὸν καὶ Σικελικὸν καὶ Σαρδῷον πέλαγος σφόδρα βαθέα· τῶν γὰρ ποταμῶν πλείστων καὶ μεγίστων ῥεόντων ἀπὸ τῆς ἄρκτου καὶ τῆς ἀνατολῆς, ἐκεῖνα μὲν ἰλύος πληροῦσθαι, τὰ ἄλλα δὲ μένειν βαθέα. διὸ καὶ γλυκυτάτην εἶναι τὴν Ποντικὴν θάλατταν τάς τ’ ἐκρύσεις γίνεσθαι εἰς οὓς ἐγκέκλιται τόπους τὰ ἐδάφη. δοκεῖν δὲ κἂν χωσθῆναι τὸν Πόντον ὅλον εἰς ὕστερον, ἂν μένωσιν αἱ ἐπιρρύσεις τοιαῦται· καὶ γὰρ νῦν ἤδη τεναγίζειν τὰ ἐν ἀριστερᾷ τοῦ Πόντου, τόν τε Σαλμυδησσὸν καὶ τὰ καλούμενα στήθη ὑπὸ τῶν ναυτικῶν τὰ περὶ τὸν Ἴστρον καὶ τὴν Σκυθῶν ἐρημίαν. τάχα δὴ καὶ τὸ τοῦ Ἄμμωνος ἱερὸν πρότερον ἐπὶ τῆς θαλάττης ὂν ἐκρύσεως γενομένης νῦν ἐν τῇ μεσογαίᾳ κεῖσθαι. εἰκάζει τε τὸ μαντεῖον εὐλόγως ἐπὶ τοσοῦτον γενέσθαι ἐπιφανές τε καὶ γνώριμον ἐπὶ θαλάττῃ ὄν, τόν τε ἐπὶ πολὺ οὕτως ἐκτοπισμὸν ἀπὸ τῆς θαλάττης οὐκ εὔλογον ποιεῖν τὴν νῦν οὖσαν ἐπιφάνειαν καὶ δόξαν· τήν τε Αἴγυπτον τὸ παλαιὸν θαλάττῃ κλύζεσθαι μέχρι τῶν ἑλῶν τῶν περὶ τὸ Πηλούσιον καὶ τὸ Κάσιον ὄρος καὶ τὴν Σιρβωνίδα λίμνην· ἔτι γοῦν καὶ νῦν κατὰ τὴν Αἴγυπτον τῆς ἁλμυρίδος ὀρυττομένης ὑφάμμους καὶ κογχυλιώδεις εὑρίσκεσθαι τοὺς βόθρους, ὡς ἂν τεθαλαττωμένης τῆς χώρας καὶ τοῦ τόπου παντὸς τοῦ περὶ τὸ Κάσιον καὶ τὰ Γέρρα καλούμενα τεναγίζοντος, ὥστε συνάπτειν τῷ τῆς Ἐρυθρᾶς κόλπῳ· ἐνδούσης δὲ τῆς θαλάττης ἀνακαλυφθῆναι, μεῖναι δὲ τὴν Σιρβωνίδα λίμνην, εἶτ’ ἐκραγῆναι καὶ ταύτην ὥστε ἑλώδη γενέσθαι. ὡς δ’ αὕτως καὶ τῆς Μοίριδος λίμνης τοὺς αἰγιαλοὺς [αἰγιαλοῖς] θαλάττης μᾶλλον ἢ ποταμοῦ προσεοικέναι. τὸ μὲν οὖν ἐπικλύζεσθαί ποτε πολὺ μέρος τῶν ἠπείρων ἐπὶ καιρούς τινας καὶ πάλιν ἀνακαλύπτεσθαι δοίη τις ἄν· ὡς δ’ αὕτως καὶ τὸ τοῖς ἐδάφεσιν ἀνώμαλον εἶναι τὴν γῆν ἅπασαν τὴν νῦν ὕφαλον, καθάπερ γε νὴ Δία καὶ τὴν ἔξαλον, ἐν ᾗ οἰκοῦμεν, τοσαύτας δεχομένην ὅσας αὐτὸς Ἐρατοσθένης εἴρηκε μεταβολάς· ὥστε πρός γε τὸν Ξάνθου λόγον οὐδὲν ἂν ἔχοι τις προσφέρειν ἄτοπον.", "st": "1.3.4"}, {"sp": "N", "t": "πρὸς δὲ τὸν Στράτωνα λέγοιτ’ ἄν, ὅτι πολλῶν αἰτίων ὄντων ἀφεὶς ταῦτα τὰ μὴ ὄντα αἰτιᾶται. πρώτην γὰρ αἰτίαν φησίν, ὅτι τῆς ἐντὸς θαλάττης καὶ τῆς ἐκτὸς οὐ ταὐτὸν τὸ ἔδαφος καὶ ὁ βυθός. πρὸς γὰρ τὸ μετεωρίζεσθαι ταύτην καὶ ταπεινοῦσθαι καὶ ἐπικλύζειν τόπους τινὰς καὶ ἀναχωρεῖν ἀπ’ αὐτῶν οὐ τοῦτό ἐστιν αἴτιον [τὸ] ἄλλα καὶ ἄλλα ἐδάφη τὰ μὲν ταπεινότερα εἶναι τὰ δὲ ὑψηλότερα, ἀλλὰ τὸ τὰ αὐτὰ ἐδάφη ποτὲ μὲν μετεωρίζεσθαι ποτὲ δ’ αὖ ταπεινοῦσθαι καὶ συνεξαίρειν ἢ συνενδιδόναι τὸ πέλαγος· ἐξαρθὲν μὲν γὰρ ἐπικλύσαι ἄν, ταπεινωθὲν δὲ ἀναδράμοι ἂν εἰς τὴν ἀρχαίαν κατάστασιν. εἰ γὰρ [οὐχ] οὕτω, δεήσει πλεονασμῷ τῆς θαλάττης αἰφνιδίῳ γενομένῳ τὴν ἐπίκλυσιν συμβαίνειν, καθάπερ ἐν ταῖς ἀναβάσεσι τῶν ποταμῶν, τοτὲ μὲν ἐπενεχθέντος ἑτέρωθεν τοτὲ δ’ αὐξηθέντος τοῦ ὕδατος. ἀλλ’ οὔθ’ αἱ αὐξήσεις ἀθρόαι καὶ αἰφνίδιοι γίνονται, οὔθ’ αἱ πλημμυρίδες τοσοῦτον ἐπιμένουσι χρόνον οὐδ’ ἄτακτοί εἰσιν, οὔτε κατὰ τὴν ἡμετέραν ἐπικλύζουσι θάλατταν οὐδ’ ὅπου ἔτυχε. λοιπὸν οὖν αἰτιᾶσθαι τὸ ἔδαφος ἢ τὸ τῇ θαλάττῃ ὑποκείμενον ἢ τὸ ἐπικλυζόμενον, μᾶλλον δὲ τὸ ὕφαλον. πολὺ γὰρ εὐκινητότερον καὶ μεταβολὰς θάττους δέξασθαι δυνάμενον τὸ ἔνυγρον· καὶ γὰρ τὸ πνευματικὸν τὸ πάντων τῶν τοιούτων αἴτιον πλέον ἐνταῦθα. ἀλλ’, ὡς ἔφην, τῶν τοιούτων ἀπεργαστικόν ἐστι παθῶν τὸ τὰ αὐτὰ ἐδάφη ποτὲ μὲν ἐξαίρεσθαι ποτὲ δὲ ὑφίζησιν λαμβάνειν, οὐ τὸ τὰ μὲν εἶναι ὑψηλὰ τὰ δὲ ἧττον· ὁ δὲ τοῦτο λαμβάνει, νομίζων ὅπερ ἐπὶ τῶν ποταμῶν συμβαίνει τοῦτο καὶ ἐπὶ τῆς θαλάττης ἀπαντᾶν, τὸ ἀπὸ τῶν μετεώρων τόπων εἶναι τὴν ῥύσιν. οὐδὲ γὰρ ἂν τοῦ κατὰ Βυζάντιον ῥοῦ τὸ ἔδαφος ᾐτιᾶτο, λέγων ὑψηλότερον τὸ τοῦ Εὐξείνου ἢ τὸ τῆς Προποντίδος καὶ τοῦ ἑξῆς πελάγους, ἅμα καὶ αἰτίαν προστιθείς· ἀπὸ γὰρ τῆς ἰλύος τῆς ἀπὸ τῶν ποταμῶν καταφερομένης πληροῦσθαι τὸν βυθὸν καὶ βραχὺν γίνεσθαι, διὰ τοῦτο δὲ καὶ ῥεῖν εἰς τὰ ἐκτός. τὸν δ’ αὐτὸν λόγον καὶ ἐπὶ τὴν ἡμετέραν θάλατταν σύμπασαν μεταφέρει πρὸς τὴν ἐκτός, ὡς καὶ ταύτης μετεωρότερον τοὔδαφος ποιούσης τοῦ ὑποκειμένου τῷ Ἀτλαντικῷ πελάγει· καὶ γὰρ αὕτη ἐκ πολλῶν ποταμῶν πληροῦται καὶ τὴν ὑποστάθμην τῆς ἰλύος δέχεται τὴν ἀνάλογον. ἐχρῆν οὖν καὶ τὸν εἴσρουν ὅμοιον γίνεσθαι τῷ κατὰ Βυζάντιον τὸν κατὰ στήλας καὶ τὴν Κάλπην. ἀλλὰ τοῦτο μὲν ἐῶ· ἐροῦσι γὰρ κἀκεῖ τοῦτο συμβαίνειν, περισπᾶσθαι δὲ ὑπὸ τῶν ἀμπώτεων καὶ τῶν πλημμυρίδων καὶ ἐπικρύπτεσθαι.", "st": "1.3.5"}, {"sp": "N", "t": "Ἐκεῖνο δὲ πυνθάνομαι τί ἐκώλυε, πρὶν ἀνεῳγέναι τὸ στόμα τὸ κατὰ Βυζάντιον, ταπεινότερον ὂν τὸ τοῦ Εὐξείνου ἔδαφος τοῦ τῆς Προποντίδος καὶ τῆς ἑξῆς θαλάττης πληρωθῆναι ὑπὸ τῶν ποταμῶν, εἴτε θάλατταν οὖσαν καὶ πρότερον εἴτε λίμνην μείζω τῆς Μαιώτιδος; εἰ γὰρ τοῦτο συγχωροῖτο, προσερήσομαι καὶ τοῦτο· ἆρά γε ἡ ἐπιφάνεια τοῦ ὕδατος ἐκείνου καὶ τοῦ τῆς Προποντίδος οὐχ οὕτως εἶχεν ὥστε, μέχρι μὲν ἡ αὐτὴ ἦν, μὴ βιάζεσθαι πρὸς ἔκρυσιν διὰ τὴν ἐξ ἴσης ἀντέρεισιν καὶ θλῖψιν, ἐπειδὴ δὲ ὑπερεπόλασεν ἡ ἐντός, βιάσασθαι καὶ ἀπερᾶσαι τὸ πλεονάζον, ἐκ δὲ τούτου γενέσθαι σύρρουν τὸ ἔξω πέλαγος τῷ ἐντὸς καὶ τὴν αὐτὴν ἐπιφάνειαν ἐκείνῳ λαβεῖν, εἴτε θαλαττίῳ εἴτε λιμναίῳ μὲν πρότερον ὄντι, θαλαττίῳ δὲ ὕστερον, διὰ τὴν μῖξιν καὶ τὴν ἐπικράτειαν; εἰ γὰρ καὶ τοῦτο δώσουσιν, ἡ μὲν ἔκρυσις οὐκ ἂν κωλύοιτο ἡ νῦν, οὐκ ἀπὸ ὑπερτέρου δὲ ἐδάφους οὐδὲ ἐπικλινοῦς, ὅπερ ἠξίου Στράτων.", "st": "1.3.6"}, {"sp": "N", "t": "ταῦτα δὲ [δεῖ] μεταφέρειν καὶ ἐπὶ τὴν ὅλην τὴν καθ’ ἡμᾶς θάλατταν καὶ τὴν ἐκτός, μὴ ἐν τοῖς ἐδάφεσι καὶ ταῖς ἐπικλίσεσιν αὐτῶν τὴν αἰτίαν τοῦ ἔκρου τιθεμένους, ἀλλ’ ἐν τοῖς ποταμοῖς· ἐπεὶ οὐκ ἀπίθανον κατ’ αὐτούς, οὐδ’ εἰ τὴν ὅλην θάλατταν τὴν ἡμετέραν λίμνην πρότερον εἶναι συνέβαινε πληρουμένην ὑπὸ τῶν ποταμῶν, ἐπιπολάσασαν ἐκπεσεῖν ἔξω διὰ τῶν κατὰ στήλας στενῶν ὡς ἐκ καταράκτου, ἐπαυξομένην δ’ ἀεὶ καὶ μᾶλλον τὴν θάλατταν σύρρουν γενέσθαι ὑπ’ αὐτῆς τῷ χρόνῳ καὶ συνδραμεῖν εἰς μίαν ἐπιφάνειαν, ἐκθαλαττωθῆναι δὲ διὰ τὴν ἐπικράτειαν. οὐ φυσικὸν δ’ ὅλως τὸ τοῖς ποταμοῖς εἰκάζειν τὴν θάλατταν· οἱ μὲν γὰρ φέρονται κατὰ ἐπικλινὲς ῥεῖθρον, ἡ δὲ ἀκλινὴς ἕστηκεν. οἱ δὲ πορθμοὶ ῥευματίζονται κατ’ ἄλλον τρόπον, οὐ διὰ τὸ τὴν ἰλὺν τὴν ἐκ τῶν ποταμῶν προσχοῦν τὸν τοῦ πελάγους βυθόν· ἡ γὰρ πρόσχωσις περὶ αὐτὰ συνίσταται τὰ στόματα τῶν ποταμῶν, οἷον περὶ μὲν τὰ τοῦ Ἴστρου τὰ λεγόμενα στήθη καὶ ἡ Σκυθῶν ἐρημία καὶ ὁ Σαλμυδησσός, καὶ ἄλλων χειμάρρων συνεργούντων πρὸς τοῦτο, περὶ δὲ τὰ τοῦ Φάσιδος ἡ Κολχικὴ παραλία δίαμμος καὶ ταπεινὴ καὶ μαλακὴ οὖσα, περὶ δὲ τὸν Θερμώδοντα καὶ τὸν Ἶριν ὅλη Θεμίσκυρα, τὸ τῶν Ἀμαζόνων πεδίον, καὶ τῆς Σιδηνῆς τὸ πλέον· οὕτω δὲ καὶ ἐπὶ τῶν ἄλλων. ἅπαντες γὰρ μιμοῦνται τὸν Νεῖλον ἐξηπειροῦντες τὸν πρὸ αὐτῶν πόρον, οἱ μὲν μᾶλλον οἱ δὲ ἧττον· ἧττον μὲν οἱ μὴ πολλὴν καταφέροντες τὴν ἰλύν, μᾶλλον δὲ οἱ πολλήν τε καὶ μαλακόγειον χώραν ἐπιόντες καὶ χειμάρρους δεχόμενοι πολλούς, ὧν ἐστι καὶ ὁ Πύραμος ὁ τῇ Κιλικίᾳ πολὺ μέρος προσθείς, ἐφ’ οὗ καὶ λόγιον ἐκπέπτωκέ τι τοιοῦτον “ἔσσεται ἐσσομένοις, ὅτε Πύραμος ἀργυροδίνης ἠιόνα προχέων ἱερὴν ἐς Κύπρον ἵκηται.” ἐκ μέσων γὰρ τῶν τῆς Καταονίας πεδίων ἐνεχθεὶς πλωτὸς καὶ διεκπαισάμενος διὰ τῶν τοῦ Ταύρου στενῶν εἰς τὴν Κιλικίαν ἐκδίδωσιν εἰς τὸν πρὸ ταύτης τε καὶ τῆς Κύπρου πόρον.", "st": "1.3.7"}, {"sp": "N", "t": "αἴτιον δὲ τοῦ μὴ φθάνειν τὴν χοῦν εἰς τὸ πέλαγος προϊοῦσαν τὴν ὑπὸ τῶν ποταμῶν καταφερομένην τὸ τὴν θάλατταν ἀνακόπτειν αὐτὴν εἰς τοὐπίσω, παλιρροοῦσαν φύσει· ἔοικε γὰρ τοῖς ζῴοις, καὶ καθάπερ ἐκεῖνα συνεχῶς ἀναπνεῖ τε καὶ ἐκπνεῖ, τὸν αὐτὸν τρόπον καὶ αὐτὴ ἐξ αὑτῆς τε καὶ εἰς ἑαυτὴν συνεχῶς παλινδρομικήν τινα κινουμένη κίνησιν. δῆλον δὲ τῷ ἐπὶ τοῦ αἰγιαλοῦ ἑστῶτι κατὰ τὴν κυμάτωσιν· ἅμα γὰρ κλύζονται οἱ πόδες καὶ γυμνοῦνται καὶ πάλιν κλύζονται, καὶ τοῦτο συνεχῶς· τῷ δὲ κλύδωνι καὶ κῦμα ἐπιτρέχει, [ὃ] κἂν γαληνότατον ᾖ ἐπιφερόμενον ἔχει τινὰ βίαν πλείω καὶ ἀπορρίπτει πᾶν τὸ ἀλλότριον εἰς τὴν γῆν “πολλὸν δὲ παρὲξ ἅλα φῦκος ἔχευε.” μᾶλλον μὲν οὖν ἐν ἀνέμῳ συμβαίνει τοῦτο, ἀλλὰ καὶ ἐν νηνεμίᾳ καὶ ἐν ἀπογαίοις πνεύμασιν· οὐδὲν γὰρ ἧττον ἐπὶ γῆν φέρεται τὸ κῦμα ὑπεναντίως τῷ ἀνέμῳ, ὡς ἂν ἰδίαν τινὰ τῆς θαλάττης κίνησιν συγκινούμενον αὐτῇ.", "st": "1.3.8"}, {"sp": "N", "t": "̔η μὲν οὖν ἔφοδος τοῦ κύματος ἔχει τινὰ βίαν ὥστ’ ἀπωθεῖσθαι τὸ ἀλλότριον. καὶ δὴ καὶ κάθαρσίν τινα τῆς θαλάττης ταύτην φασί, καθ’ ἣν καὶ τὰ νεκρὰ σώματα καὶ τὰ ναυάγια εἰς γῆν ἐκκυμαίνεται. ἡ δ’ ἀναχώρησις οὐκ ἔχει τοσαύτην βίαν ὥστε νεκρὸν ἢ ξύλον ἢ τὸ κουφότατον, φελλόν, ὑπὸ τοῦ κύματος εἰς γῆν ἀναβληθῆναι, οὕτω δὲ καὶ τῶν πλησίον αὐτῆς τόπων εἰς τὸ πέλαγος προπεσεῖν ὑποληφθέντων ὑπὸ τοῦ κύματος. οὕτω δὴ καὶ τὴν χοῦν καὶ τὸ σὺν αὐτῇ τεθολωμένον ὕδωρ ἐκκυμαίνεσθαι συμβαίνει, καὶ τοῦ βάρους ἅμα συνεργοῦντος ὥστε θᾶττον κατενεχθῆναι πρὸς τὴν γῆν κάτω, πρὶν εἰς τὸ πρόσω πελαγίσαι. καὶ γὰρ ἡ τοῦ ποταμοῦ βία παύεται μικρὸν προελθοῦσα τοῦ στόματος. οὕτω μὲν οὖν ἐνδέχεται προσχωσθῆναι τὸ πέλαγος πᾶν, ἀπὸ τῶν αἰγιαλῶν ἀρξάμενον, ἂν συνεχεῖς ἔχῃ τὰς ἐκ τῶν ποταμῶν ἐπιρρύσεις. τοῦτο δ’ ἂν συμβαίη, κἂν τοῦ Σαρδονίου πελάγους βαθύτερον ὑποθώμεθα τὸν Πόντον, ὅπερ λέγεται τῶν ἀναμετρηθέντων βαθύτατον χιλίων που ὀργυιῶν, ὡς Ποσειδώνιός φησι.", "st": "1.3.9"}, {"sp": "N", "t": "τὴν μὲν οὖν τοιαύτην αἰτιολογίαν ἧττον ἄν τις ἀποδέξαιτο· μᾶλλον δ’ ἀπὸ τῶν φανερωτέρων καὶ τῶν καθ’ ἡμέραν τρόπον τινὰ ὁρωμένων ἀναπτέον τὸν λόγον· καὶ γὰρ κατακλυσμοὶ καὶ σεισμοὶ καὶ ἀναφυσήματα καὶ ἀνοιδήσεις τῆς ὑφάλου γῆς μετεωρίζουσι καὶ τὴν θάλατταν, αἱ δὲ συνιζήσεις ταπεινοῦσιν αὐτήν· οὐ γὰρ μύδροι μὲν ἀνενεχθῆναι δύνανται καὶ μικραὶ νῆσοι, μεγάλαι δ’ οὔ· οὐδὲ νῆσοι μέν, ἤπειροι δ’ οὔ. ὁμοίως δὲ καὶ συνιζήσεις καὶ μικραὶ καὶ μεγάλαι γένοιντ’ ἄν, εἴπερ καὶ χάσματα καὶ καταπόσεις χωρίων καὶ κατοικιῶν, ὡς ἐπὶ Βούρας τε καὶ Βιζώνης καὶ ἄλλων πλειόνων, ὑπὸ σεισμοῦ γενέσθαι φασί· καὶ τὴν Σικελίαν οὐδέν τι μᾶλλον ἀπορρῶγα τῆς Ἰταλίας εἰκάζοι τίς ἂν ἢ ἀναβληθεῖσαν ὑπὸ τοῦ Αἰτναίου πυρὸς ἐκ βυθοῦ συμμεῖναι· ὡσαύτως δὲ καὶ τὰς Λιπαραίων νήσους καὶ Πιθηκούσσας.", "st": "1.3.10"}, {"sp": "N", "t": "̔ο δ’ οὕτως ἡδύς ἐστιν ὥστε καὶ μαθηματικὸς ὢν οὐδὲ τὴν Ἀρχιμήδους βεβαιοῖ δόξαν, ὅτι φησὶν ἐκεῖνος ἐν τοῖς περὶ τῶν ὀχουμένων, παντὸς ὑγροῦ καθεστηκότος καὶ μένοντος τὴν ἐπιφάνειαν σφαιρικὴν εἶναι, σφαίρας ταὐτὸ κέντρον ἐχούσης τῇ γῇ· ταύτην γὰρ τὴν δόξαν ἀποδέχονται πάντες οἱ μαθημάτων πως ἁψάμενοι. ἐκεῖνος δὲ τὴν ἐντὸς θάλατταν, καίπερ μίαν οὖσαν, ὥς φησιν, οὐ νομίζει ὑπὸ μίαν ἐπιφάνειαν τετάχθαι, ἀλλ’ οὐδὲ τοῖς σύνεγγυς τόποις. καὶ μάρτυράς γε τῆς τοιαύτης ἀμαθίας ἀρχιτέκτονας ἄνδρας ποιεῖται, καὶ τῶν μαθηματικῶν καὶ τὴν ἀρχιτεκτονικὴν μέρος τῆς μαθηματικῆς ἀποφηναμένων. φησὶ γὰρ καὶ Δημήτριον διακόπτειν ἐπιχειρῆσαι τὸν τῶν Πελοποννησίων ἰσθμὸν πρὸς τὸ παρασχεῖν διάπλουν τοῖς στόλοις, κωλυθῆναι δ’ ὑπὸ τῶν ἀρχιτεκτόνων ἀναμετρησάντων καὶ ἀπαγγειλάντων μετεωροτέραν τὴν ἐν τῷ Κορινθιακῷ κόλπῳ θάλατταν τῆς κατὰ Κεγχρεὰς εἶναι, ὥστε, εἰ διακόψειε τὸ μεταξὺ χωρίον, ἐπικλυσθῆναι ἂν ἅπαντα τὸν περὶ Αἴγιναν πόρον καὶ αὐτὴν Αἴγιναν καὶ τὰς πλησίον νήσους, καὶ μηδὲ τὸν διάπλουν ἂν γενέσθαι χρήσιμον. διὰ δὲ τοῦτο καὶ τοὺς εὐρίπους ῥοώδεις εἶναι, μάλιστα δὲ τὸν κατὰ Σικελίαν πορθμόν, ὅν φησιν ὁμοιοπαθεῖν ταῖς κατὰ τὸν ὠκεανὸν πλημμυρίσι τε καὶ ἀμπώτεσι· δὶς γὰρ μεταβάλλειν τὸν ῥοῦν ἑκάστης ἡμέρας καὶ νυκτός, καθάπερ τὸν ὠκεανὸν δὶς μὲν πλημμυρεῖν δὶς δὲ ἀναχωρεῖν. τῇ μὲν οὖν πλημμυρίδι ὁμολογεῖν τὸν ἐκ τοῦ Τυρρηνικοῦ πελάγους εἰς τὸ Σικελικὸν καταφερόμενον ὡς ἂν ἐκ μετεωροτέρας ἐπιφανείας, ὃν δὴ καὶ κατιόντα ὀνομάζεσθαι, ὁμολογεῖν δ’ ὅτι καὶ κατὰ τὸν αὐτὸν καιρὸν ἄρχεταί τε καὶ παύεται καθ’ ὃν αἱ πλημμυρίδες· ἄρχεται μὲν γὰρ περὶ τὴν ἀνατολὴν τῆς σελήνης καὶ τὴν δύσιν, λήγει δ’ ὅταν συνάπτῃ τῇ μεσουρανήσει ἑκατέρᾳ, τῇ τε ὑπὲρ γῆς καὶ τῇ ὑπὸ γῆς· τῇ δὲ ἀμπώτει τὸν ἐναντίον, ὃν ἐξιόντα καλεῖσθαι, ταῖς μεσουρανήσεσι τῆς σελήνης ἀμφοτέραις ἐναρχόμενον, καθάπερ αἱ ἀμπώτεις, ταῖς δὲ συνάψεσι ταῖς πρὸς τὰς ἀνατολὰς καὶ δύσεις παυόμενον.", "st": "1.3.11"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν πλημμυρίδων καὶ τῶν ἀμπώτεων εἰρήκασιν ἱκανῶς Ποσειδώνιός τε καὶ Ἀθηνόδωρος· περὶ δὲ τῆς τῶν πορθμῶν παλιρροίας, ἐχόντων καὶ αὐτῶν φυσικώτερον λόγον ἢ κατὰ τὴν νῦν ὑπόθεσιν, τοσοῦτον εἰπεῖν ἀπόχρη, ὅτι οὔτε εἷς τρόπος τοῦ ῥοώδεις εἶναι τοὺς πορθμούς, ὅ γε κατ’ εἶδος (οὐ γὰρ ἂν ὁ μὲν Σικελικὸς δὶς ἑκάστης ἡμέρας μετέβαλλεν, ὡς οὗτός φησιν, ὁ δὲ Χαλκιδικὸς ἑπτάκις, ὁ δὲ κατὰ Βυζάντιον οὐδὲ μετέβαλλεν, ἀλλὰ διετέλει τὸν ἔκρουν μόνον ἔχων τὸν ἐκ τοῦ Ποντικοῦ πελάγους εἰς τὴν Προποντίδα, ὡς δὲ Ἵππαρχος ἱστορεῖ, καὶ μονάς ποτε ἐποιεῖτο), οὔτ’ εἰ τρόπος εἷς εἴη, ταύτην ἂν ἔχοι τὴν αἰτίαν, ἥν φησιν ὁ Ἐρατοσθένης, ὅτι ἡ ἐφ’ ἑκάτερα θάλαττα ἄλλην καὶ ἄλλην ἐπιφάνειαν ἔχει· οὐδὲ γὰρ ἐπὶ τῶν ποταμῶν τοῦτο γένοιτ’ ἄν, εἰ μὴ καταράκτας ἔχοιεν· ἔχοντες δὲ οὐ παλιρροοῦσιν, ἀλλ’ ἐπὶ τὸ ταπεινότερον ἀεὶ φέρονται. καὶ τοῦτο δὲ συμβαίνει διὰ τὸ κεκλιμένον εἶναι τὸ ῥεῦμα καὶ τὴν ἐπιφάνειαν αὐτοῦ· ὥστ’ οὐχ ὅτι παλιρροοῦντας, ἀλλ’ οὐδὲ καθεστῶτας καὶ μένοντας, συρροίας μὲν ἐν αὐτοῖς οὔσης, μὴ μιᾶς δὲ ἐπιφανείας, ἀλλὰ τῆς μὲν ὑψηλοτέρας τῆς δὲ ταπεινοτέρας. πελάγους δὲ τίς ἂν φαίη κεκλιμένην ἐπιφάνειαν; καὶ μάλιστα κατὰ τὰς σφαιροποιούσας ὑποθέσεις τὰ τέτταρα σώματα, ἃ δὴ καὶ στοιχεῖα φαμέν· οὐ γὰρ ὥσπερ ἡ γῆ κατὰ ἕξιν ἐσχημάτισται στερεὰ οὖσα, ὥστε καὶ κοιλάδας ἔχειν συμμενούσας καὶ ἀναστήματα, οὕτω καὶ τὸ ὕδωρ, ἀλλ’ αὐτῇ τῇ κατὰ τὸ βάρος ῥοπῇ τὴν ὄχησιν ἐπὶ τῆς γῆς ποιεῖται καὶ τοιαύτην λαμβάνει τὴν ἐπιφάνειαν οἵαν ὁ Ἀρχιμήδης φησιν.", "st": "1.3.12"}, {"sp": "N", "t": "Ἐπιφέρει δὲ τοῖς περὶ τοῦ Ἄμμωνος καὶ τῆς Αἰγύπτου ῥηθεῖσιν, ὅτι δοκοίη καὶ τὸ Κάσιον ὄρος περικλύζεσθαι θαλάττῃ καὶ πάντα τὸν τόπον, ὅπου νῦν τὰ καλούμενα Γέρρα, καθ’ ἕκαστα τεναγίζειν συνάπτοντα τῷ τῆς Ἐρυθρᾶς κόλπῳ, συνελθούσης δὲ τῆς θαλάττης ἀποκαλυφθῆναι. τὸ δὴ τεναγίζειν τὸν λεχθέντα τόπον συνάπτοντα τῷ τῆς Ἐρυθρᾶς κόλπῳ, ἀμφίβολόν ἐστιν, ἐπειδὴ τὸ συνάπτειν σημαίνει καὶ τὸ συνεγγίζειν καὶ τὸ ψαύειν, ὥστε, εἰ ὕδατα εἴη, σύρρουν εἶναι θάτερον θατέρῳ. ἐγὼ μὲν οὖν δέχομαι καὶ τὸ συνεγγίζειν τὰ τενάγη τῇ Ἐρυθρᾷ θαλάττῃ, ἕως ἀκμὴν ἐκέκλειστο τὰ κατὰ τὰς στήλας στενά, ἐκραγέντων δὲ τὴν ἀναχώρησιν γενέσθαι, ταπεινωθείσης τῆς ἡμετέρας θαλάττης διὰ τὴν κατὰ τὰς στήλας ἔκρυσιν. Ἵππαρχος δὲ ἐκδεξάμενος τὸ συνάπτειν ταὐτὸν τῷ σύρρουν γενέσθαι τὴν ἡμετέραν θάλατταν τῇ Ἐρυθρᾷ διὰ τὴν πλήρωσιν, αἰτιᾶται τί δή ποτε οὐχὶ τῇ κατὰ τὰς στήλας ἐκρύσει μεθισταμένη ἐκεῖσε ἡ καθ’ ἡμᾶς θάλαττα συμμεθίστα καὶ τὴν σύρρουν αὐτῇ γενομένην τὴν Ἐρυθράν, καὶ ἐν τῇ αὐτῇ διέμεινεν ἐπιφανείᾳ, μὴ ταπεινουμένη· καὶ γὰρ κατ’ αὐτὸν Ἐρατοσθένη τὴν ἐκτὸς θάλατταν ἅπασαν σύρρουν εἶναι, ὥστε καὶ τὴν ἑσπέριον καὶ τὴν Ἐρυθρὰν θάλατταν μίαν εἶναι. τοῦτο δ’ εἰπὼν ἐπιφέρει τὸ ἀκόλουθον, τὸ τὸ αὐτὸ ὕψος ἔχειν τήν τε ἔξω στηλῶν θάλατταν καὶ τὴν Ἐρυθρὰν καὶ ἔτι τὴν ταύτῃ γεγονυῖαν σύρρουν.", "st": "1.3.13"}, {"sp": "N", "t": "Ἀλλ’ οὔτ’ εἰρηκέναι τοῦτό φησιν Ἐρατοσθένης, τὸ σύρρουν γεγονέναι κατὰ τὴν πλήρωσιν τῇ Ἐρυθρᾷ, ἀλλὰ συνεγγίσαι μόνον, οὔτ’ ἀκολουθεῖν τῇ μιᾷ καὶ συνεχεῖ θαλάττῃ τὸ αὐτὸ ὕψος ἔχειν καὶ τὴν αὐτὴν ἐπιφάνειαν, ὥσπερ οὐδὲ τὴν καθ’ ἡμᾶς, καὶ νὴ Δία τὴν κατὰ τὸ Λέχαιον καὶ τὴν περὶ Κεγχρεάς. ὅπερ καὶ αὐτὸς ὁ Ἵππαρχος ἐπισημαίνεται ἐν τῷ πρὸς αὐτὸν λόγῳ· εἰδὼς οὖν τὴν δόξαν αὐτοῦ τοιαύτην ἰδίᾳ τι πρὸς αὐτὸν λεγέτω, καὶ μὴ ἐξ ἑτοίμου λαμβανέτω, ὡς ἄρα ὁ φήσας μίαν εἶναι τὴν ἔξω θάλατταν σύμφησι καὶ ὅτι μία ἐστὶν αὐτῆς ἡ ἐπιφάνεια.", "st": "1.3.14"}, {"sp": "N", "t": "ψευδῆ δ’ εἶναι φήσας τὴν ἐπὶ τοῖς δελφῖσιν ἐπιγραφὴν Κυρηναίων θεωρῶν αἰτίαν ἀποδίδωσιν οὐ πιθανήν, ὅτι ἡ μὲν τῆς Κυρήνης κτίσις ἐν χρόνοις φέρεται μνημονευομένοις, τὸ δὲ μαντεῖον οὐδεὶς μέμνηται ἐπὶ θαλάττῃ ποτὲ ὑπάρξαν. τί γάρ, εἰ μηδεὶς μὲν ἱστορεῖ, ἐκ δὲ τῶν τεκμηρίων, ἐξ ὧν εἰκάζομεν παράλιόν ποτε τὸν τόπον γενέσθαι, οἵ τε δελφῖνες ἀνετέθησαν καὶ ἡ ἐπιγραφὴ ἐγένετο ὑπὸ Κυρηναίων θεωρῶν; συγχωρήσας δὲ τῷ μετεωρισμῷ τοῦ ἐδάφους συμμετεωρισθεῖσαν καὶ τὴν θάλατταν ἐπικλύσαι τοὺς μέχρι τοῦ μαντείου τόπους, πλέον ἀπὸ θαλάττης διέχοντας τῶν τρισχιλίων σταδίων, οὐ συγχωρεῖ τὸν μέχρι τοσούτου μετεωρισμὸν ὥστε καὶ τὴν Φάρον ὅλην καλυφθῆναι καὶ τὰ πολλὰ τῆς Αἰγύπτου, ὥσπερ οὐχ ἱκανοῦ ὄντος τοῦ τοσούτου ὕψους καὶ ταῦτα ἐπικλύσαι. φήσας δέ, εἴπερ ἐπεπλήρωτο ἐπὶ τοσοῦτον ἡ καθ’ ἡμᾶς θάλαττα πρὶν τὸ ἔκρηγμα τὸ κατὰ στήλας γενέσθαι, ἐφ’ ὅσον εἴρηκεν ὁ Ἐρατοσθένης, χρῆναι καὶ τὴν Λιβύην πᾶσαν καὶ τῆς Εὐρώπης τὰ πολλὰ καὶ τῆς Ἀσίας κεκαλύφθαι πρότερον, τούτοις ἐπιφέρει διότι καὶ ὁ Πόντος τῷ Ἀδρίᾳ σύρρους ἂν ὑπῆρξε κατά τινας τόπους, ἅτε δὴ τοῦ Ἴστρου ἀπὸ τῶν κατὰ τὸν Πόντον τόπων σχιζομένου καὶ ῥέοντος εἰς ἑκατέραν τὴν θάλατταν διὰ τὴν θέσιν τῆς χώρας. ἀλλ’ οὔτ’ ἀπὸ τῶν κατὰ τὸν Πόντον μερῶν ὁ Ἴστρος τὰς ἀρχὰς ἔχει, ἀλλὰ τἀναντία ἀπὸ τῶν ὑπὲρ τοῦ Ἀδρίου ὀρῶν· οὔτ’ εἰς ἑκατέραν τὴν θάλατταν ῥεῖ, ἀλλ’ εἰς τὸν Πόντον μόνον, σχίζεταί τε πρὸς αὐτοῖς μόνον τοῖς στόμασι. κοινὴν δέ τινα τῶν πρὸ αὐτοῦ τισιν ἄγνοιαν ταύτην ἠγνόηκεν, ὑπολαβοῦσιν εἶναί τινα ὁμώνυμον τῷ Ἴστρῳ ποταμὸν ἐκβάλλοντα εἰς τὸν Ἀδρίαν ἀπεσχισμένον αὐτοῦ, ἀφ’ οὗ καὶ τὸ γένος Ἴστρων, δι’ οὗ φέρεται, λαβεῖν τὴν προσηγορίαν, καὶ τὸν Ἰάσονα ταύτῃ ποιήσασθαι τὸν ἐκ τῶν Κόλχων ἀνάπλουν.", "st": "1.3.15"}, {"sp": "N", "t": "πρὸς δὲ τὴν ἀθαυμαστίαν τῶν τοιούτων μεταβολῶν, οἵας ἔφαμεν αἰτίας εἶναι τῶν ἐπικλύσεων καὶ τῶν τοιούτων παθῶν, οἷα εἴρηται τὰ κατὰ τὴν Σικελίαν καὶ τὰς Αἰόλου νήσους καὶ Πιθηκούσσας, ἄξιον παραθεῖναι καὶ ἄλλα πλείω τῶν ἐν ἑτέροις τόποις ὄντων ἢ γενομένων ὁμοίων τούτοις. ἀθρόα γὰρ τὰ τοιαῦτα παραδείγματα πρὸ ὀφθαλμῶν τεθέντα παύσει τὴν ἔκπληξιν. νυνὶ δὲ τὸ ἄηθες ταράττει τὴν αἴσθησιν καὶ δείκνυσιν ἀπειρίαν τῶν φύσει συμβαινόντων καὶ τοῦ βίου παντός, οἷον εἴ τις λέγοι τὰ περὶ Θήραν καὶ Θηρασίαν νήσους ἱδρυμένας ἐν τῷ μεταξὺ πόρῳ Κρήτης καὶ τῆς Κυρηναίας, ὧν ἡ Θήρα μητρόπολίς ἐστι τῆς Κυρήνης, καὶ τὴν Αἴγυπτον καὶ πολλὰ μέρη τοιαῦτα τῆς Ἑλλάδος. ἀνὰ μέσον γὰρ Θήρας καὶ Θηρασίας ἐκπεσοῦσαι φλόγες ἐκ τοῦ πελάγους ἐφ’ ἡμέρας τέτταρας, ὥστε πᾶσαν ζεῖν καὶ φλέγεσθαι τὴν θάλατταν, ἀνεφύσησαν κατ’ ὀλίγον ἐξαιρομένην ὡς ἂν ὀργανικῶς συντιθεμένην ἐκ μύδρων νῆσον ἐπέχουσαν δώδεκα σταδίων τὴν περίμετρον. μετὰ δὲ τὴν παῦλαν τοῦ πάθους ἐθάρρησαν πρῶτοι Ῥόδιοι θαλαττοκρατοῦντες ἐπιπροσπλεῦσαι τῷ τόπῳ καὶ Ποσειδῶνος Ἀσφαλίου ἱερὸν ἱδρύσασθαι κατὰ τὴν νῆσον. ἐν δὲ τῇ Φοινίκῃ φησὶ Ποσειδώνιος γενομένου σεισμοῦ καταποθῆναι πόλιν ἱδρυμένην ὑπὲρ Σιδῶνος, καὶ αὐτῆς δὲ Σιδῶνος σχεδόν τι τὰ δύο μέρη πεσεῖν, ἀλλ’ οὐκ ἀθρόως, ὥστε μὴ πολὺν φθόρον ἀνθρώπων γενέσθαι. τὸ δ’ αὐτὸ πάθος καὶ ἐπὶ τὴν Συρίαν ὅλην διέτεινε, μετρίως δέ πως. διέβη δὲ καὶ ἐπί τινας νήσους τάς τε Κυκλάδας καὶ τὴν Εὔβοιαν, ὥστε τῆς Ἀρεθούσης (ἔστι δ’ ἐν Χαλκίδι κρήνη) τὰς πηγὰς ἀποτυφλωθῆναι, συχναῖς δ’ ἡμέραις ὕστερον ἀναβλύσαι κατ’ ἄλλο στόμιον, μὴ παύεσθαι δὲ σειομένην τὴν νῆσον κατὰ μέρη πρὶν ἢ χάσμα γῆς ἀνοιχθὲν ἐν τῷ Ληλάντῳ πεδίῳ πηλοῦ διαπύρου ποταμὸν ἐξήμεσε.", "st": "1.3.16"}, {"sp": "N", "t": "πολλῶν δὲ συναγωγὰς ποιησαμένων τοιαύτας, ἀρκέσει τὰ ὑπὸ τοῦ Σκηψίου Δημητρίου συνηγμένα οἰκείως παρατεθέντα. μνησθεὶς γὰρ τῶν ἐπῶν τούτων<br>κρουνὼ δ’ ἵκανον καλλιρρόω, ἔνθα τε πηγαὶ<br>δοιαὶ ἀναΐσσουσι Σκαμάνδρου δινήεντος.<br>ἡ μὲν γάρ θ’ ὕδατι λιαρῷ, …<br>ἡ δ’ ἑτέρη θέρεϊ προρέει εἰκυῖα χαλάζῃ,<br>οὐκ ἐᾷ θαυμάζειν, εἰ νῦν ἡ μὲν τοῦ ψυχροῦ ὕδατος μένει πηγή, ἡ δὲ τοῦ θερμοῦ οὐχ ὁρᾶται. δεῖν γάρ φησιν αἰτιᾶσθαι τὴν ἔκλειψιν τοῦ θερμοῦ ὕδατος. μιμνήσκεται δὲ πρὸς ταῦτα τῶν ὑπὸ Δημοκλέους λεγομένων, σεισμούς τινας μεγάλους τοὺς μὲν πάλαι περὶ Λυδίαν γενομένους καὶ Ἰωνίαν μέχρι τῆς Τρωάδος ἱστοροῦντος, ὑφ’ ὧν καὶ κῶμαι κατεπόθησαν καὶ Σίπυλος κατεστράφη κατὰ τὴν Ταντάλου βασιλείαν … καὶ ἐξ ἑλῶν λίμναι ἐγένοντο, τὴν δὲ Τροίαν ἐπέκλυσε κῦμα. ἡ δὲ Φάρος ἡ κατ’ Αἴγυπτον ἦν ποτε πελαγία, νῦν δὲ τρόπον τινὰ χερρόνησος γέγονεν· ὡς δ’ αὕτως καὶ Τύρος καὶ Κλαζομεναί. ἡμῶν δ’ ἐπιδημούντων ἐν Ἀλεξανδρείᾳ τῇ πρὸς Αἰγύπτῳ, περὶ Πηλούσιον καὶ τὸ Κάσιον ὄρος μετεωρισθὲν τὸ πέλαγος ἐπέκλυσε τὴν γῆν καὶ νῆσον ἐποίησε τὸ ὄρος, ὥστε πλωτὴν γενέσθαι τὴν παρὰ τὸ Κάσιον ὁδὸν τὴν ἐς Φοινίκην. οὐδὲν οὖν θαυμαστὸν οὐδ’ εἴ ποτε διαστὰς ὁ ἰσθμὸς ἢ ἵζημα λαβὼν ὁ διείργων τὸ Αἰγύπτιον πέλαγος ἀπὸ τῆς Ἐρυθρᾶς θαλάττης ἀποφανεῖ πορθμὸν καὶ σύρρουν ποιήσει τὴν ἐκτὸς θάλατταν τῇ ἐντός, καθάπερ ἐπὶ τοῦ κατὰ τὰς Ἡρακλέους στήλας πορθμοῦ συνέβη. εἴρηται δὲ περὶ τῶν τοιούτων τινὰ καὶ ἐν ἀρχαῖς τῆς πραγματείας, ἃ δεῖ συμφέρειν εἰς ἓν καὶ τὴν πίστιν ἰσχυρὰν κατασκευάζειν τῶν τε τῆς φύσεως ἔργων καὶ τῶν ἄλλως γινομένων μεταβολῶν.", "st": "1.3.17"}, {"sp": "N", "t": "τόν τε Πειραιᾶ νησιάζοντα πρότερον καὶ πέραν τῆς ἀκτῆς κείμενον οὕτως φασὶν ὀνομασθῆναι· ὑπεναντίως δ’ ἡ Λευκὰς Κορινθίων τὸν ἰσθμὸν διακοψάντων νῆσος γέγονεν, ἀκτὴ πρότερον οὖσα· περὶ ταύτης γάρ φασι λέγειν τὸν Λαέρτην “οἷος Νήριτον εἷλον ἐυκτίμενον πτολίεθρον, ἀκτὴν ἠπείροιο·” ἐνταῦθα μὲν δὴ διακοπαὶ χειρότμητοι γεγόνασιν, ἀλλαχόθι δὲ προσχώσεις ἢ γεφυρώσεις, καθάπερ ἐπὶ τῆς πρὸς Συρακούσαις νήσου νῦν μὲν γέφυρά ἐστιν ἡ συνάπτουσα αὐτὴν πρὸς τὴν ἤπειρον, πρότερον δὲ χῶμα, ὥς φησιν Ἴβυκος, λογαίου λίθου, ὃν καλεῖ ἐκλεκτόν. Βοῦρα δὲ καὶ Ἑλίκη ἡ μὲν ὑπὸ χάσματος ἡ δ’ ὑπὸ κύματος ἠφανίσθη. περὶ Μεθώνην δὲ τὴν ἐν τῷ Ἑρμιονικῷ κόλπῳ ὄρος ἑπταστάδιον τὸ ὕψος ἀνεβλήθη γενηθέντος ἀναφυσήματος φλογώδους, μεθ’ ἡμέραν μὲν ἀπρόσιτον ὑπὸ τοῦ θερμοῦ καὶ τῆς θειώδους ὀδμῆς, νύκτωρ δ’ ἐκλάμπον πόρρω καὶ θερμαῖνον ὥστε ζεῖν τὴν θάλατταν ἐπὶ σταδίους πέντε, θολερὰν δ’ εἶναι καὶ ἐπὶ εἴκοσι σταδίους, προσχωσθῆναι δὲ πέτραις ἀπορρῶξι πύργων οὐκ ἐλάττοσιν. ὑπὸ δὲ τῆς Κωπαΐδος λίμνης ἥ τε Ἄρνη κατεπόθη καὶ Μίδεια, ἃς ὠνόμακεν ὁ ποιητὴς ἐν τῷ καταλόγῳ “οἵ τε πολυστάφυλον Ἄρνην ἔχον, οἵ τε Μίδειαν.” καὶ ὑπὸ τῆς Βιστονίδος δὲ καὶ τῆς νῦν Ἀφνίτιδος λίμνης ἐοίκασι κατακεκλύσθαι πόλεις τινὲς Θρᾳκῶν, οἱ δὲ καὶ Τρηρῶν, ὡς συνοίκων τοῖς Θρᾳξὶν ὄντων. καὶ ἡ πρότερον δὲ Ἀρτεμίτα λεγομένη μία τῶν Ἐχινάδων νήσων ἤπειρος γέγονε· καὶ ἄλλας δὲ τῶν περὶ τὸν Ἀχελῶον νησίδων τὸ αὐτὸ πάθος φασὶ παθεῖν ἐκ τῆς ὑπὸ τοῦ ποταμοῦ προχώσεως τοῦ πελάγους, συγχοῦνται δὲ καὶ αἱ λοιπαί, ὡς Ἡρόδοτός φησι. καὶ Αἰτωλικαὶ δέ τινες ἄκραι εἰσὶ νησίζουσαι πρότερον· καὶ ἡ Ἀστερία ἤλλακται, ἣν Ἀστερίδα φησὶν ὁ ποιητής ἔστι δέ τις νῆσος μέσσῃ ἁλὶ πετρήεσσα, Ἀστερίς, οὐ μεγάλη, λιμένες δ’ ἐνὶ ναύλοχοι αὐτῇ ἀμφίδυμοι· νυνὶ δὲ οὐδ’ ἀγκυροβόλιον εὐφυὲς ἔχει. ἔν τε τῇ Ἰθάκῃ οὐδέν ἐστιν ἄντρον τοιοῦτον οὐδὲ νυμφαῖον, οἷόν φησιν Ὅμηρος· βέλτιον δὲ αἰτιᾶσθαι μεταβολὴν ἢ ἄγνοιαν ἢ κατάψευσιν τῶν τόπων κατὰ τὸ μυθῶδες. τοῦτο μὲν δὴ ἀσαφὲς ὃν [ἐῶ] ἐν κοινῷ σκοπεῖν.", "st": "1.3.18"}, {"sp": "N", "t": "̔η δὲ Ἄντισσα νῆσος ἦν πρότερον, ὡς Μυρσίλος φησί· τῆς δὲ Λέσβου καλουμένης πρότερον Ἴσσης, καὶ τὴν νῆσον Ἄντισσαν καλεῖσθαι συνέβη· νῦν δὲ τῆς Λέσβου πόλις ἐστίν. οἱ δὲ καὶ τὴν Λέσβον τῆς Ἴδης ἀπερρωγέναι πεπιστεύκασι, καθάπερ τὴν Προχύτην καὶ τὴν Πιθηκοῦσσαν τοῦ Μισηνοῦ, τὰς δὲ Καπρέας τοῦ Ἀθηναίου, τὴν Σικελίαν δὲ τῆς Ῥηγίνης, τὴν Ὄσσαν δὲ τοῦ Ὀλύμπου. γεγόνασι δὲ καὶ περὶ ταῦτα τοιαῦται μεταβολαί. καὶ ὁ Λάδων δὲ ὁ ἐν Ἀρκαδίᾳ ἐπέσχε ποτὲ τὸ ῥεῦμα. Δοῦρις δὲ τὰς Ῥάγας τὰς κατὰ Μηδίαν ὠνομάσθαι φησὶν ὑπὸ σεισμῶν ῥαγείσης τῆς περὶ τὰς Κασπίους πύλας γῆς, ὥστε ἀνατραπῆναι πόλεις συχνὰς καὶ κώμας καὶ ποταμοὺς ποικίλας μεταβολὰς δέξασθαι. Ἴων δὲ περὶ τῆς Εὐβοίας φησὶν ἐν Ὀμφάλῃ Σατύροις Εὐβοΐδα μὲν γῆν λεπτὸς εὐρίπου κλύδων Βοιωτίας ἐχώρισ’, ἀκτὴν ἐκτεμὼν προβλῆτα πορθμῷ.", "st": "1.3.19"}, {"sp": "N", "t": "δημήτριος δ’ ὁ Καλλατιανὸς τοὺς καθ’ ὅλην τὴν Ἑλλάδα γενομένους ποτὲ σεισμοὺς διηγούμενος τῶν τε Λιχάδων νήσων καὶ τοῦ Κηναίου τὰ πολλὰ καταδῦναί φησι, τά τε θερμὰ τὰ ἐν Αἰδηψῷ καὶ Θερμοπύλαις ἐπὶ τρεῖς ἡμέρας ἐπισχεθέντα πάλιν ῥυῆναι, τὰ δ’ ἐν Αἰδηψῷ καὶ καθ’ ἑτέρας ἀναρραγῆναι πηγάς· Ὠρεοῦ δὲ τὸ πρὸς θαλάττῃ τεῖχος καὶ τῶν οἰκιῶν περὶ ἑπτακοσίας συμπεσεῖν, Ἐχίνου τε καὶ Φαλάρων καὶ Ἡρακλείας τῆς Τραχῖνος, τῶν μὲν πολὺ μέρος πεσεῖν, Φαλάρων δὲ καὶ ἐξ ἐδάφους ἀνατραπῆναι τὸ κτίσμα. παραπλήσια δὲ συμβῆναι καὶ Λαμιεῦσι καὶ Λαρισαίοις· καὶ Σκάρφειαν δ’ ἐκ θεμελίων ἀναρριφῆναι, καὶ καταδῦναι σώματα χιλίων καὶ ἑπτακοσίων οὐκ ἐλάττω, Θρονίους δ’ ὑπὲρ ἥμισυ τούτων· κῦμά τε ἐξαρθὲν τριχῆ τὸ μὲν πρὸς Τάρφην ἐνεχθῆναι καὶ Θρόνιον, τὸ δὲ πρὸς Θερμοπύλας, ἄλλο δὲ εἰς τὸ πεδίον ἕως τοῦ Φωκικοῦ Δαφνοῦντος, πηγάς τε ποταμῶν ξηρανθῆναι πρὸς ἡμέρας τινάς· τὸν δὲ Σπερχειὸν ἀλλάξαι τὸ ῥεῖθρον καὶ ποιῆσαι πλωτὰς τὰς ὁδούς, τὸν δὲ Βοάγριον κατ’ ἄλλης ἐνεχθῆναι φάραγγος, καὶ Ἀλόπης δὲ καὶ Κύνου καὶ Ὀποῦντος πολλὰ καταβλαβῆναι μέρη, Οἶον δὲ τὸ ὑπερκείμενον φρούριον πᾶν ἀνατραπῆναι, Ἐλατείας δὲ τοῦ τείχους καταρραγῆναι μέρος, περὶ δὲ Ἄλπωνον θεσμοφορίων ὄντων πέντε καὶ εἴκοσι παρθένους ἀναδραμούσας εἰς πύργον τῶν ἐλλιμενίων κατὰ θέαν, πεσόντος τοῦ πύργου, πεσεῖν καὶ αὐτὰς εἰς τὴν θάλατταν. λέγουσι δὲ καὶ τῆς Ἀταλάντης τῆς πρὸς Εὐβοίᾳ τὰ μέσα ῥήγματος γενομένου διάπλουν δέξασθαι, μεταξὺ καὶ τῶν πεδίων ἔνια καὶ μέχρι εἴκοσι σταδίων ἐπικλυσθῆναι, καὶ τριήρη τινὰ ἐκ τῶν νεωρίων ἐξαιρεθεῖσαν ὑπερπεσεῖν τοῦ τείχους.", "st": "1.3.20"}, {"sp": "N", "t": "προστιθέασι δὲ καὶ τὰς ἐκ τῶν μεταστάσεων μεταβολὰς ἐπὶ πλέον τὴν ἀθαυμαστίαν ἡμῖν κατασκευάζειν ἐθέλοντες, ἣν ὑμνεῖ Δημόκριτος καὶ οἱ ἄλλοι φιλόσοφοι πάντες· παράκειται γὰρ τῷ ἀθαμβεῖ καὶ ἀταράχῳ καὶ ἀνεκπλήκτῳ. οἷον Ἰβήρων μὲν τῶν ἑσπερίων εἰς τοὺς ὑπὲρ τοῦ Πόντου καὶ τῆς Κολχίδος τόπους μετῳκισμένων (οὓς ὁ Ἀράξης, ὥς φησιν Ἀπολλόδωρος, ἀπὸ τῆς Ἀρμενίας ὁρίζει, Κῦρος δὲ μᾶλλον καὶ τὰ ὄρη τὰ Μοσχικά), Αἰγυπτίων δ’ εἴς τε Αἰθίοπας καὶ Κόλχους, Ἑνετῶν δ’ ἐκ Παφλαγονίας ἐπὶ τὸν Ἀδρίαν. ἅπερ καὶ ἐπὶ τῶν Ἑλληνικῶν ἐθνῶν συνέβη, Ἰώνων καὶ Δωριέων καὶ Ἀχαιῶν καὶ Αἰολέων· καὶ Αἰνιᾶνες οἱ νῦν Αἰτωλοῖς ὅμοροι περὶ τὸ Δώτιον ᾤκουν καὶ τὴν Ὄσσαν μετὰ Περραιβῶν· καὶ αὐτοὶ δὲ Περραιβοὶ μετανάσται τινές. πλήρης δέ ἐστι τῶν τοιούτων παραδειγμάτων ἡ νῦν ἐνεστῶσα πραγματεία. τινὰ μὲν οὖν καὶ πρόχειρα τοῖς πολλοῖς ἐστιν· αἱ δὲ τῶν Καρῶν καὶ Τρηρῶν καὶ Τεύκρων μεταναστάσεις καὶ Γαλατῶν, ὁμοῦ δὲ καὶ τῶν ἡγεμόνων οἱ ἐπὶ πολὺ ἐκτοπισμοί, Μάδυός τε τοῦ Σκυθικοῦ καὶ Τεαρκὼ τοῦ Αἰθίοπος καὶ Κώβου τοῦ Τρηρὸς καὶ Σεσώστριος καὶ Ψαμμιτίχου τῶν Αἰγυπτίων καὶ Περσῶν τῶν ἀπὸ Κύρου μέχρι Ξέρξου οὐχ ὁμοίως ἐν ἑτοίμῳ πᾶσίν εἰσιν. οἵ τε Κιμμέριοι, οὓς καὶ Τρῆρας ὀνομάζουσιν, ἢ ἐκείνων τι ἔθνος, πολλάκις ἐπέδραμον τὰ δεξιὰ μέρη τοῦ Πόντου καὶ τὰ συνεχῆ αὐτοῖς, τοτὲ μὲν ἐπὶ Παφλαγόνας τοτὲ δὲ καὶ Φρύγας ἐμβαλόντες, ἡνίκα Μίδαν αἷμα ταύρου πιόντα φασὶν ἀπελθεῖν εἰς τὸ χρεών. Λύγδαμις δὲ τοὺς αὑτοῦ ἄγων μέχρι Λυδίας καὶ Ἰωνίας ἤλασε καὶ Σάρδεις εἷλεν, ἐν Κιλικίᾳ δὲ διεφθάρη. πολλάκις δὲ καὶ οἱ Κιμμέριοι καὶ οἱ Τρῆρες ἐποιήσαντο τὰς τοιαύτας ἐφόδους· τοὺς δὲ Τρῆρας καὶ Κῶβον ὑπὸ Μάδυος τὸ τελευταῖον ἐξελαθῆναί φασι τοῦ τῶν Σκυθῶν βασιλέως. ταῦτα μὲν εἰρήσθω πρὸς ἅπασαν κοινῇ τὴν περίοδον τῆς γῆς ἔχοντα οἰκείαν ἱστορίαν.", "st": "1.3.21"}, {"sp": "N", "t": "Ἐπάνιμεν δ’ ἐπὶ τὰ ἑξῆς ἀφ’ ὧν παρέβημεν. τοῦ γὰρ Ἡροδότου μηδένας ὑπερβορείους εἶναι φήσαντος, μηδὲ γὰρ ὑπερνοτίους, γελοίαν φησὶν εἶναι τὴν ἀπόδειξιν καὶ ὁμοίαν ὁ Ἐρατοσθένης τῷ σοφίσματι τούτῳ, εἴ τις λέγοι μηδένας εἶναι ἐπιχαιρεκάκους, μηδὲ γὰρ ἐπιχαιραγάθους. κατὰ τύχην τε εἶναι καὶ ὑπερνοτίους· κατὰ γοῦν τὴν Αἰθιοπίαν μὴ πνεῖν νότον, ἀλλὰ κατωτέρω. θαυμαστὸν δ’ εἰ καθ’ ἕκαστον κλίμα πνέοντος ἀνέμου καὶ πανταχοῦ τοῦ ἀπὸ μεσημβρίας νότου προσαγορευομένου, ἔστι τις οἴκησις ἐν ᾗ τοῦτο μὴ συμβαίνει. τοὐναντίον γὰρ οὐ μόνον Αἰθιοπία ἔχοι ἂν τὸν καθ’ ἡμᾶς νότον, ἀλλὰ καὶ ἡ ἀνωτέρω πᾶσα μέχρι τοῦ ἰσημερινοῦ. εἰ δ’ ἄρα, τοῦ Ἡροδότου τοῦτ’ ἐχρῆν αἰτιᾶσθαι, ὅτι τοὺς ὑπερβορείους τούτους ὑπέλαβε λέγεσθαι, παρ’ οἷς ὁ βορέας οὐ πνεῖ. καὶ γὰρ εἰ οἱ ποιηταὶ μυθικώτερον οὕτω φασίν, οἵ γ’ ἐξηγούμενοι τὸ ὑγιὲς ἂν ἀκούσαιεν, ὑπερβορείους τοὺς βορειοτάτους λέγεσθαι. ὅρος δὲ τῶν μὲν βορείων ὁ πόλος, τῶν δὲ νοτίων ὁ ἰσημερινός· καὶ τῶν ἀνέμων δ’ ὁ αὐτὸς ὅρος.", "st": "1.3.22"}, {"sp": "N", "t": "̔εξῆς δὲ λέγει πρὸς τοὺς φανερῶς πεπλασμένα καὶ ἀδύνατα λέγοντας, τὰ μὲν ἐν μύθου σχήματι τὰ δ’ ἱστορίας, περὶ ὧν οὐκ ἄξιον μεμνῆσθαι· οὐδ’ ἐκεῖνον ἐχρῆν ἐν ὑποθέσει τοιαύτῃ φλυάρους ἐπισκοπεῖν.", "st": "1.3.23"}, {"sp": "N", "t": "̔η μὲν οὖν πρώτη διέξοδος αὐτῷ τῶν ὑπομνημάτων τοιαύτη. ἐν δὲ τῇ δευτέρᾳ πειρᾶται διόρθωσίν τινα ποιεῖσθαι τῆς γεωγραφίας καὶ τὰς ἑαυτοῦ λέγει ὑπολήψεις, πρὸς ἃς πάλιν εἰ ἔστι τις ἐπανόρθωσις, πειρατέον προσφέρειν. τὸ μὲν οὖν τὰς μαθηματικὰς ὑποθέσεις εἰσάγειν καὶ φυσικὰς εὖ λέγεται, καὶ ὅτι εἰ σφαιροειδὴς ἡ γῆ καθάπερ καὶ ὁ κόσμος, περιοικεῖται, καὶ τὰ ἄλλα τὰ τοιαῦτα. εἰ δὲ τηλικαύτη ἡλίκην αὐτὸς εἴρηκεν, οὐχ ὁμολογοῦσιν οἱ ὕστερον, οὐδ’ ἐπαινοῦσι τὴν ἀναμέτρησιν· ὅμως δὲ πρὸς τὴν σημείωσιν τῶν κατὰ τὰς οἰκήσεις ἑκάστας φαινομένων προσχρῆται τοῖς διαστήμασιν ἐκείνοις Ἵππαρχος ἐπὶ τοῦ διὰ Μερόης καὶ Ἀλεξανδρείας καὶ Βορυσθένους μεσημβρινοῦ, μικρὸν παραλλάττειν φήσας παρὰ τὴν ἀλήθειαν. καὶ περὶ τοῦ σχήματος δ’ ἐν τοῖς ἑξῆς διὰ πλειόνων [λέγων] καὶ δεικνύς, ὅτι σφαιροειδὴς καὶ ἡ γῆ σὺν τῇ ὑγρᾷ φύσει καὶ ὁ οὐρανός, ἀλλοτριολογεῖν ἂν δόξειεν· ἀρκεῖ γὰρ τὸ ἐπὶ μικρόν.", "st": "1.4.1"}, {"sp": "N", "t": "̔εξῆς δὲ τὸ πλάτος τῆς οἰκουμένης ἀφορίζων φησὶν ἀπὸ μὲν Μερόης ἐπὶ τοῦ δι’ αὐτῆς μεσημβρινοῦ μέχρι Ἀλεξανδρείας εἶναι μυρίους, ἐνθένδε εἰς τὸν Ἑλλήσποντον περὶ ὀκτακισχιλίους ἑκατόν, εἶτ’ εἰς Βορυσθένη πεντακισχιλίους, εἶτ’ ἐπὶ τὸν κύκλον τὸν διὰ Θούλης (ἥν φησι Πυθέας ἀπὸ μὲν τῆς Βρεττανικῆς ἓξ ἡμερῶν πλοῦν ἀπέχειν πρὸς ἄρκτον, ἐγγὺς δ’ εἶναι τῆς πεπηγυίας θαλάττης) ἄλλους ὡς μυρίους χιλίους πεντακοσίους. ἐὰν οὖν ἔτι προσθῶμεν ὑπὲρ τὴν Μερόην ἄλλους τρισχιλίους τετρακοσίους, ἵνα τὴν τῶν Αἰγυπτίων νῆσον ἔχωμεν καὶ τὴν Κινναμωμοφόρον καὶ τὴν Ταπροβάνην, ἔσεσθαι σταδίους τρισμυρίους ὀκτακισχιλίους.", "st": "1.4.2"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα διαστήματα δεδόσθω αὐτῷ· ὡμολόγηται γὰρ ἱκανῶς· τὸ δ’ ἀπὸ τοῦ Βορυσθένους ἐπὶ τὸν διὰ Θούλης κύκλον τίς ἂν δοίη νοῦν ἔχων; ὅ τε γὰρ ἱστορῶν τὴν Θούλην Πυθέας ἀνὴρ ψευδίστατος ἐξήτασται, καὶ οἱ τὴν Βρεττανικὴν [καὶ] Ἰέρνην ἰδόντες οὐδὲν περὶ τῆς Θούλης λέγουσιν, ἄλλας νήσους λέγοντες μικρὰς περὶ τὴν Βρεττανικήν· αὐτή τε ἡ Βρεττανικὴ τὸ μῆκος ἴσως πώς ἐστι τῇ Κελτικῇ παρεκτεταμένη, τῶν πεντακισχιλίων σταδίων οὐ μείζων καὶ τοῖς ἄκροις τοῖς ἀντικειμένοις ἀφοριζομένη. ἀντίκειται γὰρ ἀλλήλοις τά τε ἑῷα ἄκρα τοῖς ἑῴοις καὶ τὰ ἑσπέρια τοῖς ἑσπερίοις, καὶ τά γε ἑῷα ἐγγὺς ἀλλήλων ἐστὶ μέχρις ἐπόψεως, τό τε Κάντιον καὶ αἱ τοῦ Ῥήνου ἐκβολαί. ὁ δὲ πλειόνων ἢ δισμυρίων τὸ μῆκος ἀποφαίνει τῆς νήσου, καὶ τὸ Κάντιον ἡμερῶν τινων πλοῦν ἀπέχειν τῆς Κελτικῆς φησι· καὶ τὰ περὶ τοὺς Ὠστιμίους δὲ καὶ τὰ πέραν τοῦ Ῥήνου τὰ μέχρι Σκυθῶν πάντα κατέψευσται τῶν τόπων. ὅστις οὖν περὶ τῶν γνωριζομένων τόπων τοσαῦτα ἔψευσται, σχολῇ γ’ ἂν περὶ τῶν ἀγνοουμένων παρὰ πᾶσιν ἀληθεύειν δύναιτο.", "st": "1.4.3"}, {"sp": "N", "t": "τὸν δὲ διὰ τοῦ Βορυσθένους παράλληλον τὸν αὐτὸν εἶναι τῷ διὰ τῆς Βρεττανικῆς εἰκάζουσιν Ἵππαρχός τε καὶ ἄλλοι ἐκ τοῦ τὸν αὐτὸν εἶναι καὶ τὸν διὰ Βυζαντίου τῷ διὰ Μασσαλίας· ὃν γὰρ λόγον εἴρηκε [Πυθέας] τοῦ ἐν Μασσαλίᾳ γνώμονος πρὸς τὴν σκιάν, τὸν αὐτὸν καὶ Ἵππαρχος κατὰ τὸν ὁμώνυμον καιρὸν εὑρεῖν ἐν τῷ Βυζαντίῳ φησίν. ἐκ Μασσαλίας δὲ εἰς μέσην τὴν Βρεττανικὴν οὐ πλέον τῶν πεντακισχιλίων ἐστὶ σταδίων. ἀλλὰ μὴν ἐκ μέσης τῆς Βρεττανικῆς οὐ πλέον τῶν τετρακισχιλίων προελθὼν εὕροις ἂν οἰκήσιμον ἄλλως πως (τοῦτο δ’ ἂν εἴη τὸ περὶ τὴν Ἰέρνην), ὥστε τὰ ἐπέκεινα, εἰς ἃ ἐκτοπίζει τὴν Θούλην, οὐκέτ’ οἰκήσιμα. τίνι δ’ ἂν καὶ στοχασμῷ λέγοι τὸ ἀπὸ τοῦ διὰ Θούλης ἕως τοῦ διὰ Βορυσθένους μυρίων καὶ χιλίων πεντακοσίων, οὐχ ὁρῶ.", "st": "1.4.4"}, {"sp": "N", "t": "διαμαρτὼν δὲ τοῦ πλάτους ἠνάγκασται καὶ τοῦ μήκους ἀστοχεῖν. ὅτι μὲν γὰρ πλέον ἢ διπλάσιον τὸ γνώριμον μῆκός ἐστι τοῦ γνωρίμου πλάτους, ὁμολογοῦσι καὶ οἱ ὕστερον καὶ τῶν παλαιῶν οἱ χαριέστατοι· λέγω δὲ τὸ ἀπὸ τῶν ἄκρων τῆς Ἰνδικῆς ἐπὶ τὰ ἄκρα τῆς Ἰβηρίας, τοῦ ἀπ’ Αἰθιόπων ἕως τοῦ κατὰ Ἰέρνην κύκλου. ὁρίσας δὲ τὸ λεχθὲν πλάτος, τὸ ἀπὸ τῶν ἐσχάτων Αἰθιόπων μέχρι τοῦ διὰ Θούλης ἐκτείνει πλέον ἢ δεῖ τὸ μῆκος, ἵνα ποιήσῃ πλέον ἢ διπλάσιον τοῦ λεχθέντος πλάτους. φησὶ δ’ οὖν τὸ μὲν τῆς Ἰνδικῆς μέχρι τοῦ Ἰνδοῦ ποταμοῦ τὸ στενώτατον σταδίων μυρίων ἑξακισχιλίων (τὸ γὰρ ἐπὶ τὰ ἀκρωτήρια τεῖνον τρισχιλίοις εἶναι μεῖζον), τὸ δὲ ἔνθεν ἐπὶ Κασπίους πύλας μυρίων τετρακισχιλίων, εἶτ’ ἐπὶ τὸν Εὐφράτην μυρίων, ἐπὶ δὲ τὸν Νεῖλον ἀπὸ τοῦ Εὐφράτου πεντακισχιλίων, ἄλλους δὲ χιλίους καὶ τριακοσίους μέχρι Κανωβικοῦ στόματος, εἶτα μέχρι τῆς Καρχηδόνος μυρίους τρισχιλίους πεντακοσίους, εἶτα μέχρι στηλῶν ὀκτακισχιλίους τοὐλάχιστον· ὑπεραίρειν δὴ τῶν ἑπτὰ μυριάδων ὀκτακοσίους. δεῖν δὲ ἔτι προσθεῖναι τὸ ἐκτὸς Ἡρακλείων στηλῶν κύρτωμα τῆς Εὐρώπης, ἀντικείμενον μὲν τοῖς Ἴβηρσι προπεπτωκὸς δὲ πρὸς τὴν ἑσπέραν, οὐκ ἔλαττον σταδίων τρισχιλίων, καὶ τὰ ἀκρωτήρια τά τε ἄλλα καὶ τὸ τῶν Ὠστιμίων, ὃ καλεῖται Κάβαιον, καὶ τὰς κατὰ τοῦτο νήσους, ὧν τὴν ἐσχάτην Οὐξισάμην φησὶ Πυθέας ἀπέχειν ἡμερῶν τριῶν πλοῦν. ταῦτα δ’ εἰπὼν τὰ τελευταῖα οὐδὲν πρὸς τὸ μῆκος συντείνοντα προσέθηκε τὰ περὶ τῶν ἀκρωτηρίων καὶ τῶν Ὠστιμίων καὶ τῆς Οὐξισάμης καὶ ὧν φησι νήσων· ταῦτα γὰρ πάντα προσάρκτιά ἐστι καὶ Κελτικά, οὐκ Ἰβηρικά, μᾶλλον δὲ Πυθέου πλάσματα. προστίθησί τε τοῖς εἰρημένοις τοῦ μήκους διαστήμασιν ἄλλους σταδίους δισχιλίους μὲν πρὸς τῇ δύσει, δισχιλίους δὲ πρὸς τῇ ἀνατολῇ, ἵνα σώσῃ τὸ πλέον ἢ διπλάσιον τὸ μῆκος τοῦ πλάτους εἶναι.", "st": "1.4.5"}, {"sp": "N", "t": "παραμυθούμενος δ’ ἐπὶ πλέον, ὅτι κατὰ φύσιν ἐστὶ τὸ ἀπὸ ἀνατολῆς ἐπὶ δύσιν διάστημα μεῖζον λέγειν, κατὰ φύσιν φησὶν εἶναι ἀπὸ τῆς ἕω πρὸς τὴν ἑσπέραν μακροτέραν εἶναι τὴν οἰκουμένην, καθάπερ εἰρήκαμεν· … ὡς οἱ μαθηματικοί φασι, κύκλον συνάπτειν, συμβάλλουσαν αὐτὴν ἑαυτῇ, ὥστ’ εἰ μὴ τὸ μέγεθος τοῦ Ἀτλαντικοῦ πελάγους ἐκώλυε, κἂν πλεῖν ἡμᾶς ἐκ τῆς Ἰβηρίας εἰς τὴν Ἰνδικὴν διὰ τοῦ αὐτοῦ παραλλήλου, τὸ λοιπὸν μέρος παρὰ τὸ λεχθὲν διάστημα ὑπὲρ τὸ τρίτον μέρος ὂν τοῦ ὅλου κύκλου· εἴπερ ὁ δι’ Ἀθηνῶν ἐλάττων ἐστὶν εἴκοσι μυριάδων, ὅπου πεποιήμεθα τὸν εἰρημένον σταδιασμὸν ἀπὸ τῆς Ἰνδικῆς εἰς τὴν Ἰβηρίαν. οὐδὲ ταῦτα οὖν εὖ λέγει· οὗτος γὰρ ὁ λόγος περὶ μὲν τῆς εὐκράτου καὶ καθ’ ἡμᾶς ζώνης λέγοιτ’ ἂν κατὰ τοὺς μαθηματικούς, ἧς μέρος ἡ οἰκουμένη ἐστί, περὶ δὲ τῆς οἰκουμένης … καλοῦμεν γὰρ οἰκουμένην ἣν οἰκοῦμεν καὶ γνωρίζομεν· ἐνδέχεται δὲ ἐν τῇ αὐτῇ εὐκράτῳ ζώνῃ καὶ δύο οἰκουμένας εἶναι ἢ καὶ πλείους, καὶ μάλιστα ἐγγὺς τοῦ δι’ Ἀθηνῶν κύκλου τοῦ διὰ τοῦ Ἀτλαντικοῦ πελάγους γραφομένου. πάλιν δὲ ἐπιμένων τῇ περὶ τοῦ σφαιροειδῆ τὴν γῆν εἶναι ἀποδείξει τῆς αὐτῆς ἐπιτιμήσεως ἂν τυγχάνοι. ὡς δ’ αὕτως καὶ πρὸς τὸν Ὅμηρον οὐ παύεται περὶ τῶν αὐτῶν διαφερόμενος.", "st": "1.4.6"}, {"sp": "N", "t": "̔εξῆς δὲ περὶ τῶν ἠπείρων εἰπὼν γεγονέναι πολὺν λόγον, καὶ τοὺς μὲν τοῖς ποταμοῖς διαιρεῖν αὐτὰς τῷ τε Νείλῳ καὶ τῷ Τανάιδι νήσους ἀποφαίνοντας, τοὺς δὲ τοῖς ἰσθμοῖς τῷ τε μεταξὺ τῆς Κασπίας καὶ τῆς Ποντικῆς θαλάσσης καὶ τῷ μεταξὺ τῆς Ἐρυθρᾶς καὶ τοῦ Ἐκρήγματος, τούτους δὲ χερρονήσους αὐτὰς λέγειν, οὐχ ὁρᾶν φησι πῶς ἂν εἰς πράγματα καταστρέφοι ἡ ζήτησις αὕτη, ἀλλὰ μόνον ἔριν διαιτώντων κατὰ Δημόκριτον εἶναι. μὴ ὄντων γὰρ ἀκριβῶν ὅρων, καθάπερ Κολυττοῦ καὶ Μελίτης, οἷον στηλῶν ἢ περιβόλων, τοῦτο μὲν ἔχειν φάναι ἡμᾶς ὅτι τουτὶ μέν ἐστι Κολυττὸς τουτὶ δὲ Μελίτη, τοὺς ὅρους δὲ μὴ ἔχειν εἰπεῖν. διὸ καὶ συμβαίνειν κρίσεις πολλάκις περὶ χωρίων τινῶν, καθάπερ Ἀργείοις μὲν καὶ Λακεδαιμονίοις περὶ Θυρέας, Ἀθηναίοις δὲ καὶ Βοιωτοῖς περὶ Ὠρωποῦ. ἄλλως τε τοὺς Ἕλληνας τὰς τρεῖς ἠπείρους ὀνομάσαι οὐκ εἰς τὴν οἰκουμένην ἀποβλέψαντας, ἀλλ’ εἴς τε τὴν σφετέραν καὶ τὴν ἀπαντικρὺ τὴν Καρικήν, ἐφ’ ᾗ νῦν Ἴωνες καὶ οἱ ἑξῆς· χρόνῳ δὲ ἐπὶ πλέον προϊόντας ἀεὶ καὶ πλειόνων γνωριζομένων χωρῶν εἰς τοῦτο καταστρέψαι τὴν διαίρεσιν. πότερον οὖν οἱ πρῶτοι διορίσαντες τὰς τρεῖς, ἵνα ἀπὸ τῶν ἐσχάτων ἄρξωμαι διαιτῶν τὴν ἔριν, μὴ κατὰ Δημόκριτον ἀλλὰ κατ’ αὐτόν, οὗτοι ἦσαν οἱ πρῶτοι τὴν σφετέραν ἀπὸ τῆς ἀντικειμένης τῆς τῶν Καρῶν διορίσαι ζητοῦντες; ἢ οὗτοι μὲν τὴν Ἑλλάδα ἐπενόουν μόνην καὶ τὴν Καρίαν καὶ ὀλίγην τὴν συνεχῆ, οὔτε δ’ Εὐρώπην οὔτε Ἀσίαν ὡσαύτως οὔτε Λιβύην, οἱ δὲ λοιποὶ ἐπιόντες ὅση ἦν ἱκανὴ ὑπογράψαι τὴν τῆς οἰκουμένης ἐπίνοιαν, οὗτοί εἰσιν οἱ εἰς τρία διαιροῦντες; πῶς οὖν οὐ τῆς οἰκουμένης ἐποιοῦντο διαίρεσιν; τίς δὲ τρία μέρη λέγων καὶ καλῶν ἤπειρον ἕκαστον τῶν μερῶν οὐ προσεπινοεῖ τὸ ὅλον, οὗ τὸν μερισμὸν ποιεῖται; εἰ δ’ ἐπινοοῖ μὲν μὴ τὴν οἰκουμένην, μέρους δέ τινος αὐτῆς τὸν μερισμὸν ποιοῖτο, τίνος ἄν τις μέρους τῆς οἰκουμένης μέρος εἶπε τὴν Ἀσίαν ἢ τὴν Εὐρώπην ἢ ὅλως ἤπειρον; ταῦτα γὰρ εἴρηται παχυμερῶς.", "st": "1.4.7"}, {"sp": "N", "t": "ἔτι δὲ παχυμερέστερον τὸ φήσαντα μὴ ὁρᾶν εἰς τί πραγματικὸν καταστρέφει τὸ τοὺς ὅρους ζητεῖν, παραθεῖναι τὸν Κολυττὸν καὶ τὴν Μελίτην, εἶτ’ εἰς τἀναντία περιτρέπεσθαι. εἰ γὰρ οἱ περὶ Θυρεῶν καὶ Ὠρωποῦ πόλεμοι διὰ τὰς τῶν ὅρων ἀγνοίας ἀπέβησαν, εἰς πραγματικόν τι καταστρέφον τὸ διαχωρίζειν τὰς χώρας· ἢ τοῦτο λέγει, ὡς ἐπὶ μὲν τῶν χωρίων καὶ νὴ Δία τῶν καθ’ ἕκαστα ἐθνῶν πραγματικὸν τὸ διορίζειν ἀκριβῶς, ἐπὶ δὲ τῶν ἠπείρων περιττόν; καίτοι οὐδὲ ἐνταῦθα ἧττον οὐδέν· γένοιτο γὰρ ἂν καὶ ἐπὶ τούτων ἡγεμόσι μεγάλοις ἀμφισβήτησις, τῷ μὲν ἔχοντι τὴν Ἀσίαν, τῷ δὲ τὴν Λιβύην, ὁποτέρου δή ἐστιν ἡ Αἴγυπτος, δηλονότι ἡ κάτω λεγομένη τῆς Αἰγύπτου χώρα. κἂν ἐάσῃ δέ τις τοῦτο διὰ τὸ σπάνιον, ἄλλως φατέον διαιρεῖσθαι τὰς ἠπείρους κατὰ μέγαν διορισμὸν καὶ πρὸς τὴν οἰκουμένην ὅλην ἀναφερόμενον· καθ’ ὃν οὐδὲ τούτου φροντιστέον, εἰ οἱ τοῖς ποταμοῖς διορίσαντες ἀπολείπουσί τινα χωρία ἀδιόριστα, τῶν ποταμῶν μὴ μέχρι τοῦ ὠκεανοῦ διηκόντων μηδὲ νήσους ὡς ἀληθῶς ἀπολειπόντων τὰς ἠπείρους.", "st": "1.4.8"}, {"sp": "N", "t": "Ἐπὶ τέλει δὲ τοῦ ὑπομνήματος οὐκ ἐπαινέσας τοὺς δίχα διαιροῦντας ἅπαν τὸ τῶν ἀνθρώπων πλῆθος εἴς τε Ἕλληνας καὶ βαρβάρους, καὶ τοὺς Ἀλεξάνδρῳ παραινοῦντας τοῖς μὲν Ἕλλησιν ὡς φίλοις χρῆσθαι τοῖς δὲ βαρβάροις ὡς πολεμίοις, βέλτιον εἶναί φησιν ἀρετῇ καὶ κακίᾳ διαιρεῖν ταῦτα. πολλοὺς γὰρ καὶ τῶν Ἑλλήνων εἶναι κακοὺς καὶ τῶν βαρβάρων ἀστείους, καθάπερ Ἰνδοὺς καὶ Ἀριανούς, ἔτι δὲ Ῥωμαίους καὶ Καρχηδονίους οὕτω θαυμαστῶς πολιτευομένους. διόπερ τὸν Ἀλέξανδρον ἀμελήσαντα τῶν παραινούντων, ὅσους οἷόν τ’ ἦν ἀποδέχεσθαι τῶν εὐδοκίμων ἀνδρῶν καὶ εὐεργετεῖν· ὥσπερ δι’ ἄλλο τι τῶν οὕτω διελόντων τοὺς μὲν ἐν ψόγῳ τοὺς δ’ ἐν ἐπαίνῳ τιθεμένων, ἢ διότι τοῖς μὲν ἐπικρατεῖ τὸ νόμιμον καὶ τὸ παιδείας καὶ λόγων οἰκεῖον, τοῖς δὲ τἀναντία. καὶ ὁ Ἀλέξανδρος οὖν οὐκ ἀμελήσας τῶν παραινούντων, ἀλλ’ ἀποδεξάμενος τὴν γνώμην τὰ ἀκόλουθα, οὐ τὰ ἐναντία ἐποίει, πρὸς τὴν διάνοιαν σκοπῶν τὴν τῶν ἐπεσταλκότων.", "st": "1.4.9"}, {"sp": "HDR", "t": "Βιβλίον Βʹ", "st": "2"}, {"sp": "N", "t": "Ἐν δὲ τῷ τρίτῳ τῶν γεωγραφικῶν καθιστάμενος τὸν τῆς οἰκουμένης πίνακα γραμμῇ τινι διαιρεῖ δίχα ἀπὸ δύσεως ἐπ’ ἀνατολὴν παραλλήλῳ τῇ ἰσημερινῇ γραμμῇ, πέρατα δ’ αὐτῆς τίθησι πρὸς δύσει μὲν τὰς Ἡρακλείους στήλας, ἐπ’ ἀνατολῇ δὲ τὰ ἄκρα καὶ ἔσχατα ὄρη τῶν ἀφοριζόντων ὀρῶν τὴν πρὸς ἄρκτον τῆς Ἰνδικῆς πλευράν. γράφει δὲ τὴν γραμμὴν ἀπὸ στηλῶν διά τε τοῦ Σικελικοῦ πορθμοῦ καὶ τῶν μεσημβρινῶν ἄκρων τῆς τε Πελοποννήσου καὶ τῆς Ἀττικῆς μέχρι τῆς Ῥοδίας καὶ τοῦ Ἰσσικοῦ κόλπου. μέχρι μὲν δὴ δεῦρο διὰ τῆς θαλάττης φησὶν εἶναι τὴν λεχθεῖσαν γραμμὴν καὶ τῶν παρακειμένων ἠπείρων (καὶ γὰρ αὐτὴν ὅλην τὴν καθ’ ἡμᾶς θάλατταν οὕτως ἐπὶ μῆκος τετάσθαι μέχρι τῆς Κιλικίας), εἶτα ἐπ’ εὐθείας πως ἐκβάλλεσθαι παρ’ ὅλην τὴν ὀρεινὴν τοῦ Ταύρου μέχρι τῆς Ἰνδικῆς· τὸν γὰρ Ταῦρον ἐπ’ εὐθείας τῇ ἀπὸ στηλῶν θαλάττῃ τεταμένον δίχα τὴν Ἀσίαν διαιρεῖν ὅλην ἐπὶ μῆκος, τὸ μὲν αὐτῆς μέρος βόρειον ποιοῦντα τὸ δὲ νότιον, ὥσθ’ ὁμοίως καὶ αὐτὸν ἐπὶ τοῦ δι’ Ἀθηνῶν ἱδρῦσθαι παραλλήλου καὶ τὴν ἀπὸ στηλῶν μέχρι δεῦρο θάλατταν.", "st": "2.1.1"}, {"sp": "N", "t": "ταῦτα δ’ εἰπὼν οἴεται δεῖν διορθῶσαι τὸν ἀρχαῖον γεωγραφικὸν πίνακα· πολὺ γὰρ ἐπὶ τὰς ἄρκτους παραλλάττειν τὰ ἑωθινὰ μέρη τῶν ὀρῶν κατ’ αὐτόν, συνεπισπᾶσθαι δὲ καὶ τὴν Ἰνδικὴν ἀρκτικωτέραν ἢ δεῖ γινομένην. πίστιν δὲ τούτου φέρει μίαν μὲν ταύτην, ὅτι τὰ τῆς Ἰνδικῆς ἄκρα τὰ μεσημβρινώτατα ὁμολογοῦσι πολλοὶ τοῖς κατὰ Μερόην ἀνταίρειν τόποις, ἀπό τε τῶν ἀέρων καὶ τῶν οὐρανίων τεκμαιρόμενοι, ἐντεῦθεν δ’ ἐπὶ τὰ βορειότατα τῆς Ἰνδικῆς τὰ πρὸς τοῖς Καυκασίοις ὄρεσι Πατροκλῆς, ὁ μάλιστα πιστεύεσθαι δίκαιος διά τε τὸ ἀξίωμα καὶ διὰ τὸ μὴ ἰδιώτης εἶναι τῶν γεωγραφικῶν, φησὶ σταδίους μυρίους καὶ πεντακισχιλίους· ἀλλὰ μὴν καὶ τὸ ἀπὸ Μερόης ἐπὶ τὸν δι’ Ἀθηνῶν παράλληλον τοσοῦτόν πώς ἐστιν ὥστε τῆς Ἰνδικῆς τὰ προσάρκτια μέρη συνάπτοντα τοῖς Καυκασίοις ὄρεσιν εἰς τοῦτον τελευτᾶν τὸν κύκλον.", "st": "2.1.2"}, {"sp": "N", "t": "ἄλλην δὲ πίστιν φέρει τοιαύτην, ὅτι τὸ ἀπὸ τοῦ Ἰσσικοῦ κόλπου διάστημα ἐπὶ τὴν θάλατταν τὴν Ποντικὴν τρισχιλίων πώς ἐστι σταδίων πρὸς ἄρκτον ἰόντι καὶ τοὺς περὶ Ἀμισὸν ἢ Σινώπην τόπους, ὅσον καὶ τὸ πλάτος τῶν ὀρῶν λέγεται· ἐκ δὲ Ἀμισοῦ πρὸς τὴν ἰσημερινὴν ἀνατολὴν φερομένῳ πρῶτον μὲν ἡ Κολχίς ἐστιν, ἔπειτα ἡ ἐπὶ τὴν Ὑρκανίαν θάλατταν ὑπέρθεσις καὶ ἡ ἐφεξῆς ἡ ἐπὶ Βάκτρα καὶ τοὺς ἐπέκεινα Σκύθας ὁδὸς δεξιὰ ἔχοντι τὰ ὄρη· αὕτη δ’ ἡ γραμμὴ διὰ Ἀμισοῦ πρὸς δύσιν ἐκβαλλομένη διὰ τῆς Προποντίδος ἐστὶ καὶ τοῦ Ἑλλησπόντου. ἀπὸ δὲ Μερόης ἐπὶ τὸν Ἑλλήσποντον οὐ πλείους εἰσὶ τῶν μυρίων καὶ ὀκτακισχιλίων σταδίων, ὅσοι καὶ ἀπὸ τοῦ μεσημβρινοῦ πλευροῦ τῆς Ἰνδικῆς πρὸς τὰ περὶ τοὺς Βακτρίους μέρη, προστεθέντων τρισχιλίων τοῖς μυρίοις καὶ πεντακισχιλίοις, ὧν οἱ μὲν τοῦ πλάτους ἦσαν τῶν ὀρῶν οἱ δὲ τῆς Ἰνδικῆς.", "st": "2.1.3"}, {"sp": "N", "t": "πρὸς δὲ τὴν ἀπόφασιν ταύτην ὁ Ἵππαρχος ἀντιλέγει διαβάλλων τὰς πίστεις· οὐδὲ γὰρ Πατροκλέα πιστὸν εἶναι, δυεῖν ἀντιμαρτυρούντων αὐτῷ Δηιμάχου τε καὶ Μεγασθένους, οἳ καθ’ οὓς μὲν τόπους δισμυρίων εἶναι σταδίων τὸ διάστημά φασι τὸ ἀπὸ τῆς κατὰ μεσημβρίαν θαλάττης, καθ’ οὓς δὲ καὶ τρισμυρίων· τούτους τε δὴ τοιαῦτα λέγειν καὶ τοὺς ἀρχαίους πίνακας τούτοις ὁμολογεῖν. ἀπίθανον δή που νομίζει τὸ μόνῳ δεῖν πιστεύειν Πατροκλεῖ, παρέντας τοὺς τοσοῦτον ἀντιμαρτυροῦντας αὐτῷ, καὶ διορθοῦσθαι παρ’ αὐτὸ τοῦτο τοὺς ἀρχαίους πίνακας, ἀλλὰ μὴ ἐᾶν οὕτως, ἕως ἄν τι πιστότερον περὶ αὐτῶν γνῶμεν.", "st": "2.1.4"}, {"sp": "N", "t": "οἶμαι δὴ πολλὰς ἔχειν εὐθύνας τοῦτον τὸν λόγον. πρῶτον μὲν ὅτι πολλαῖς μαρτυρίαις ἐκείνου χρησαμένου μιᾷ φησι τῇ Πατροκλέους αὐτὸν χρῆσθαι. τίνες οὖν ἦσαν οἱ φάσκοντες τὰ μεσημβρινὰ ἄκρα τῆς Ἰνδικῆς ἀνταίρειν τοῖς κατὰ Μερόην; τίνες δ’ οἱ τὸ ἀπὸ Μερόης διάστημα μέχρι τοῦ δι’ Ἀθηνῶν παραλλήλου [τοσοῦτον] λέγοντες; τίνες δὲ πάλιν οἱ τὸ τῶν ὀρῶν πλάτος τοσοῦτον, ἢ οἱ τὸ ἀπὸ τῆς Κιλικίας ἐπὶ τὴν Ἀμισὸν τὸ αὐτὸ τούτῳ λέγοντες; τίνες δὲ οἱ [τὸ] ἀπὸ Ἀμισοῦ διὰ Κόλχων καὶ τῆς Ὑρκανίας μέχρι Βακτρίων καὶ τῶν ἐπέκεινα εἰς τὴν ἑῴαν θάλατταν καθηκόντων ἐπ’ εὐθείας τε εἶναι λέγοντες καὶ ἐπ’ ἰσημερινὰς ἀνατολὰς καὶ παρὰ τὰ ὄρη ἐν δεξιᾷ ἔχοντι αὐτά; ἢ πάλιν τὸ ἐπὶ τὴν δύσιν ἐπ’ εὐθείας ταύτῃ τῇ γραμμῇ, διότι ἐπὶ τὴν Προποντίδα ἐστὶ καὶ τὸν Ἑλλήσποντον; ταῦτα γὰρ ὁ Ἐρατοσθένης λαμβάνει πάντα ὡς καὶ ἐκμαρτυρούμενα ὑπὸ τῶν ἐν τοῖς τόποις γενομένων, ἐντετυχηκὼς ὑπομνήμασι πολλοῖς, ὧν εὐπόρει βιβλιοθήκην ἔχων τηλικαύτην ἡλίκην αὐτὸς Ἵππαρχός φησι.", "st": "2.1.5"}, {"sp": "N", "t": "καὶ αὐτὴ δὲ ἡ τοῦ Πατροκλέους πίστις ἐκ πολλῶν μαρτυριῶν σύγκειται, τῶν βασιλέων τῶν πεπιστευκότων αὐτῷ τηλικαύτην ἀρχήν, τῶν ἐπακολουθησάντων αὐτῷ, τῶν ἀντιδοξούντων, ὧν αὐτὸς ὁ Ἵππαρχος κατονομάζει· οἱ γὰρ κατ’ ἐκείνων ἔλεγχοι πίστεις τῶν ὑπὸ τούτου λεγομένων εἰσίν. οὐδὲ τοῦτο δὲ ἀπίθανον τοῦ Πατροκλέους, ὅτι φησὶ τοὺς Ἀλεξάνδρῳ συστρατεύσαντας ἐπιδρομάδην ἱστορῆσαι ἕκαστα, αὐτὸν δὲ Ἀλέξανδρον ἀκριβῶσαι, ἀναγραψάντων τὴν ὅλην χώραν τῶν ἐμπειροτάτων αὐτῷ· τὴν δ’ ἀναγραφὴν αὐτῷ δοθῆναί φησιν ὕστερον ὑπὸ Ξενοκλέους τοῦ γαζοφύλακος.", "st": "2.1.6"}, {"sp": "N", "t": "ἔτι φησὶν ὁ Ἵππαρχος ἐν τῷ δευτέρῳ ὑπομνήματι αὐτὸν τὸν Ἐρατοσθένη διαβάλλειν τὴν τοῦ Πατροκλέους πίστιν ἐκ τῆς πρὸς Μεγασθένη διαφωνίας περὶ τοῦ μήκους τῆς Ἰνδικῆς τοῦ κατὰ τὸ βόρειον πλευρόν, τοῦ μὲν Μεγασθένους λέγοντος σταδίων μυρίων ἑξακισχιλίων, τοῦ δὲ Πατροκλέους χιλίοις λείπειν φαμένου· ἀπὸ γάρ τινος ἀναγραφῆς σταθμῶν ὁρμηθέντα τοῖς μὲν ἀπιστεῖν διὰ τὴν διαφωνίαν, ἐκείνῃ δὲ προσέχειν. εἰ οὖν διὰ τὴν διαφωνίαν ἐνταῦθα ἄπιστος ὁ Πατροκλῆς, καίτοι παρὰ χιλίους σταδίους τῆς διαφορᾶς οὔσης, πόσῳ χρὴ μᾶλλον ἀπιστεῖν ἐν οἷς παρὰ ὀκτακισχιλίους ἡ διαφορά ἐστι, πρὸς δύο καὶ ταῦτα ἄνδρας συμφωνοῦντας ἀλλήλοις, τῶν μὲν λεγόντων τὸ τῆς Ἰνδικῆς πλάτος δισμυρίων σταδίων, τοῦ δὲ μυρίων καὶ δισχιλίων;", "st": "2.1.7"}, {"sp": "N", "t": "Ἐροῦμεν δ’ ὅτι οὐ ψιλὴν τὴν διαφωνίαν ᾐτιάσατο, ἀλλὰ συγκρίνων πρὸς τὴν ὁμολογίαν καὶ τὴν ἀξιοπιστίαν τῆς ἀναγραφῆς τῶν σταθμῶν. οὐ θαυμαστὸν δὲ εἰ πιστοῦ γίνεταί τι πιστότερον, καὶ εἰ τῷ αὐτῷ ἐν ἑτέροις μὲν πιστεύομεν ἐν ἑτέροις δ’ ἀπιστοῦμεν, ὅταν παρά τινος τεθῇ τι βεβαιότερον. γελοῖόν τε τὸ τὴν παρὰ πολὺ διαφωνίαν ἀπιστοτέρους ποιεῖν νομίσαι τοὺς διαφωνοῦντας· τοὐναντίον γὰρ ἐν τῷ παρὰ μικρὸν συμβαίνειν τοῦτο μᾶλλον ἔοικε. παρὰ μικρὸν γὰρ ἡ πλάνη συμβαίνει μᾶλλον οὐ τοῖς τυχοῦσι μόνον, ἀλλὰ καὶ τοῖς πλέον τι τῶν ἑτέρων φρονοῦσιν· ἐν δὲ τοῖς παρὰ πολὺ ὁ μὲν τυχὼν ἁμάρτοι ἄν, ὁ δ’ ἐπιστημονικώτερος ἧττον ἂν τοῦτο πάθοι· διὸ καὶ πιστεύεται θᾶττον.", "st": "2.1.8"}, {"sp": "N", "t": "̔́απαντες μὲν τοίνυν οἱ περὶ τῆς Ἰνδικῆς γράψαντες ὡς ἐπὶ τὸ πολὺ ψευδολόγοι γεγόνασι, καθ’ ὑπερβολὴν δὲ Δηίμαχος, τὰ δὲ δεύτερα λέγει Μεγασθένης, Ὀνησίκριτος δὲ καὶ Νέαρχος καὶ ἄλλοι τοιοῦτοι παραψελλίζοντες ἤδη. καὶ ἡμῖν δ’ ὑπῆρξεν ἐπὶ πλέον κατιδεῖν ταῦτα ὑπομνηματιζομένοις τὰς Ἀλεξάνδρου πράξεις· διαφερόντως δ’ ἀπιστεῖν ἄξιον Δηιμάχῳ τε καὶ Μεγασθένει. οὗτοι γάρ εἰσιν οἱ τοὺς ἐνωτοκοίτας καὶ τοὺς ἀστόμους καὶ ἄρρινας ἱστοροῦντες μονοφθάλμους τε καὶ μακροσκελεῖς καὶ ὀπισθοδακτύλους· ἀνεκαίνισαν δὲ καὶ τὴν Ὁμηρικὴν τῶν Πυγμαίων γερανομαχίαν, τρισπιθάμους εἰπόντες. οὗτοι δὲ καὶ τοὺς χρυσωρύχους μύρμηκας καὶ Πᾶνας σφηνοκεφάλους ὄφεις τε καὶ βοῦς καὶ ἐλάφους σὺν κέρασι καταπίνοντας· περὶ ὧν ἕτερος τὸν ἕτερον ἐλέγχει, ὅπερ καὶ Ἐρατοσθένης φησίν. ἐπέμφθησαν μὲν γὰρ εἰς τὰ Παλίμβοθρα, ὁ μὲν Μεγασθένης πρὸς Σανδρόκοττον ὁ δὲ Δηίμαχος πρὸς Ἀλλιτροχάδην τὸν ἐκείνου υἱὸν κατὰ πρεσβείαν· ὑπομνήματα δὲ τῆς ἀποδημίας κατέλιπον τοιαῦτα, ὑφ’ ἧς δή ποτε αἰτίας προαχθέντες. Πατροκλῆς δὲ ἥκιστα τοιοῦτος· καὶ οἱ ἄλλοι δὲ μάρτυρες οὐκ ἀπίθανοι, οἷς κέχρηται ὁ Ἐρατοσθένης …", "st": "2.1.9"}, {"sp": "N", "t": "… εἰ γὰρ ὁ διὰ Ῥόδου καὶ Βυζαντίου μεσημβρινὸς ὀρθῶς εἴληπται, καὶ ὁ διὰ τῆς Κιλικίας καὶ Ἀμισοῦ ὀρθῶς ἂν εἴη εἰλημμένος· φαίνεται γὰρ τὸ παράλληλον ἐκ πολλῶν, ὅταν μηδετέρως ἡ σύμπτωσις ἀπελέγχηται.", "st": "2.1.10"}, {"sp": "N", "t": "̔́ο τε ἐξ Ἀμισοῦ πλοῦς ἐπὶ τὴν Κολχίδα ὅτι ἐστὶν ἐπὶ ἰσημερινὴν ἀνατολήν, καὶ τοῖς ἀνέμοις ἐλέγχεται καὶ ὥραις καὶ καρποῖς καὶ ταῖς ἀνατολαῖς αὐταῖς· ὡς δ’ αὕτως καὶ ἡ ἐπὶ τὴν Κασπίαν ὑπέρβασις καὶ ἡ ἐφεξῆς ὁδὸς μέχρι Βάκτρων. πολλαχοῦ γὰρ ἡ ἐνάργεια καὶ τὸ ἐκ πάντων συμφωνούμενον ὀργάνου πιστότερόν ἐστιν, ἐπεὶ καὶ αὐτὸς ὁ Ἵππαρχος τὴν ἀπὸ στηλῶν μέχρι τῆς Κιλικίας γραμμήν, ὅτι ἐστὶν ἐπ’ εὐθείας καὶ ὅτι ἐπὶ ἰσημερινὴν ἀνατολήν, οὐ πᾶσαν ὀργανικῶς καὶ γεωμετρικῶς ἔλαβεν, ἀλλ’ ὅλην τὴν ἀπὸ στηλῶν μέχρι πορθμοῦ τοῖς πλέουσιν ἐπίστευσεν. ὥστ’ οὐδ’ ἐκεῖνο εὖ λέγει τό “ἐπειδὴ οὐκ ἔχομεν λέγειν οὔθ’ ἡμέρας μεγίστης πρὸς τὴν βραχυτάτην λόγον οὔτε γνώμονος πρὸς σκιὰν ἐπὶ τῇ παρωρείᾳ τῇ ἀπὸ Κιλικίας μέχρι Ἰνδῶν, οὐδ’ εἰ ἐπὶ παραλλήλου γραμμῆς ἐστιν ἡ λόξωσις ἔχομεν εἰπεῖν, ἀλλ’ ἐᾶν ἀδιόρθωτον, λοξὴν φυλάξαντες, ὡς οἱ ἀρχαῖοι πίνακες παρέχουσι.” πρῶτον μὲν γὰρ τὸ μὴ ἔχειν εἰπεῖν ταὐτόν ἐστι τῷ ἐπέχειν, ὁ δ’ ἐπέχων οὐδετέρωσε ῥέπει, ἐᾶν δὲ κελεύων, ὡς οἱ ἀρχαῖοι, ἐκεῖσε ῥέπει. μᾶλλον δ’ ἂν τἀκόλουθον ἐφύλαττεν, εἰ συνεβούλευε μηδὲ γεωγραφεῖν ὅλως· οὐδὲ γὰρ τῶν ἄλλων ὀρῶν τὰς θέσεις, οἷον Ἄλπεων καὶ τῶν Πυρηναίων καὶ τῶν Θρᾳκίων καὶ Ἰλλυρικῶν καὶ Γερμανικῶν, οὕτως ἔχομεν εἰπεῖν. τίς δ’ ἂν ἡγήσαιτο πιστοτέρους τῶν ὑστέρων τοὺς παλαιοὺς τοσαῦτα πλημμελήσαντας περὶ τὴν πινακογραφίαν, ὅσα εὖ διαβέβληκεν Ἐρατοσθένης, ὧν οὐδενὶ ἀντείρηκεν Ἵππαρχος;", "st": "2.1.11"}, {"sp": "N", "t": "καὶ τὰ ἑξῆς δὲ πλήρη μεγάλων ἀποριῶν ἐστιν. ὅρα γάρ, εἰ τοῦτο μὲν μὴ κινοίη τις τὸ τὰ ἄκρα τῆς Ἰνδικῆς τὰ μεσημβρινὰ ἀνταίρειν τοῖς κατὰ Μερόην, μηδὲ τὸ διάστημα τὸ ἀπὸ Μερόης ἐπὶ τὸ στόμα τὸ κατὰ τὸ Βυζάντιον, ὅτι ἐστὶ περὶ μυρίους σταδίους καὶ ὀκτακισχιλίους, ποιοίη δὲ τρισμυρίων τὸ ἀπὸ τῶν μεσημβρινῶν Ἰνδῶν μέχρι τῶν ὀρῶν, ὅσα ἂν συμβαίη ἄτοπα. τὸ πρῶτον μὲν γὰρ εἴπερ ὁ αὐτός ἐστι παράλληλος ὁ διὰ Βυζαντίου τῷ διὰ Μασσαλίας, καθάπερ εἴρηκεν Ἵππαρχος πιστεύσας Πυθέᾳ, ὁ δ’ αὐτὸς καὶ μεσημβρινός ἐστιν ὁ διὰ Βυζαντίου τῷ διὰ Βορυσθένους, ὅπερ καὶ αὐτὸ δοκιμάζει ὁ Ἵππαρχος, δοκιμάζει δὲ καὶ τὸ ἀπὸ Βυζαντίου διάστημα ἐπὶ τὸν Βορυσθένη σταδίους εἶναι τρισχιλίους ἑπτακοσίους, τοσοῦτοι ἂν εἶεν καὶ οἱ ἀπὸ Μασσαλίας ἐπὶ τὸν διὰ Βορυσθένους παράλληλον, ὅς γε διὰ τῆς Κελτικῆς παρωκεανίτιδος ἂν εἴη· τοσούτους γάρ πως διελθόντες συνάπτουσι τῷ ὠκεανῷ.", "st": "2.1.12"}, {"sp": "N", "t": "πάλιν δ’ ἐπεὶ τὴν Κινναμωμοφόρον ἐσχάτην ἴσμεν οἰκουμένην πρὸς μεσημβρίαν, καὶ καθ’ Ἵππαρχον αὐτὸν ὁ δι’ αὐτῆς παράλληλος ἀρχὴ τῆς εὐκράτου καὶ τῆς οἰκουμένης ἐστί, καὶ διέχει τοῦ ἰσημερινοῦ περὶ ὀκτακισχιλίους καὶ ὀκτακοσίους σταδίους· ἐπεὶ οὖν φησὶν ἀπὸ τοῦ ἰσημερινοῦ τὸν διὰ Βορυσθένους διέχειν τρισμυρίους καὶ τετρακισχιλίους σταδίους, εἶεν ἂν λοιποὶ οἱ ἀπὸ τοῦ ὁρίζοντος τὴν διακεκαυμένην καὶ τὴν εὔκρατον εἰς τὸν διὰ Βορυσθένους καὶ τῆς Κελτικῆς παρωκεανίτιδος στάδιοι δισμύριοι πεντακισχίλιοι διακόσιοι. ὁ δέ γε ἀπὸ τῆς Κελτικῆς πρὸς ἄρκτον πλοῦς ἔσχατος λέγεται παρὰ τοῖς νῦν ὁ ἐπὶ τὴν Ἰέρνην, ἐπέκεινα μὲν οὖσαν τῆς Βρεττανικῆς, ἀθλίως δὲ διὰ ψῦχος οἰκουμένην, ὥστε τὰ ἐπέκεινα νομίζειν ἀοίκητα. οὐ πλέον δὲ τῆς Κελτικῆς τὴν Ἰέρνην διέχειν φασὶ τῶν πεντακισχιλίων, ὥστε περὶ τρισμυρίους εἶεν ἂν ἢ μικρῷ πλείους οἱ πάντες οἱ τὸ πλάτος τῆς οἰκουμένης ἀφορίζοντες.", "st": "2.1.13"}, {"sp": "N", "t": "φέρε δὴ ἐπὶ τὴν ἀνταίρουσαν τῇ Κινναμωμοφόρῳ καὶ ἐπὶ τοῦ αὐτοῦ παραλλήλου πρὸς ἕω κειμένην ὑποβῶμεν. αὕτη δ’ ἐστὶν ἡ περὶ τὴν Ταπροβάνην· ἡ δὲ Ταπροβάνη πεπίστευται σφόδρα ὅτι τῆς Ἰνδικῆς πρόκειται πελαγία μεγάλη νῆσος πρὸς νότον, μηκύνεται δὲ ἐπὶ τὴν Αἰθιοπίαν πλέον ἢ πεντακισχιλίους σταδίους, ὥς φασιν, ἐξ ἧς καὶ ἐλέφαντα κομίζεσθαι πολὺν εἰς τὰ τῶν Ἰνδῶν ἐμπόρια καὶ χελώνεια καὶ ἄλλον φόρτον. ταύτῃ δὴ τῇ νήσῳ πλάτος προστεθὲν τὸ ἀνάλογον τῷ μήκει καὶ δίαρμα τὸ ἐπ’ αὐτὴν ἐκ τῆς Ἰνδικῆς τῶν μὲν τρισχιλίων σταδίων οὐκ ἂν ἔλαττον ποιήσειε διάστημα, ὅσον ἦν τὸ ἀπὸ τοῦ ὅρου τῆς οἰκουμένης εἰς Μερόην, εἴπερ μέλλει τὰ ἄκρα τῆς Ἰνδικῆς ἀνταίρειν τῇ Μερόῃ· πιθανώτερον δ’ ἐστὶ καὶ πλείους τῶν τρισχιλίων τιθέναι. εἰ δὴ τοῦτο προσθείη τις τοῖς τρισμυρίοις, οἷς φησιν ὁ Δηίμαχος μέχρι τῆς εἰς Βακτρίους καὶ Σογδιανοὺς ὑπερθέσεως, ἐκπέσοι ἂν πάντα ταῦτα τὰ ἔθνη τῆς οἰκουμένης καὶ τῆς εὐκράτου. τίς ἂν οὖν θαρρήσειε ταῦτα λέγειν, ἀκούων καὶ τῶν πάλαι καὶ τῶν νῦν τὴν εὐκρασίαν καὶ τὴν εὐκαρπίαν λεγόντων πρῶτον μὲν τὴν τῶν προσβόρρων Ἰνδῶν, ἔπειτα δὲ καὶ τὴν ἐν τῇ Ὑρκανίᾳ καὶ τῇ Ἀρίᾳ καὶ ἐφεξῆς τῇ τε Μαργιανῇ καὶ τῇ Βακτριανῇ; ἅπασαι γὰρ αὗται προσεχεῖς μέν εἰσι τῇ βορείῳ πλευρᾷ τοῦ Ταύρου, καὶ ἥ γε Βακτριανὴ καὶ πλησιάζει τῇ εἰς Ἰνδοὺς ὑπερθέσει, τοσαύτῃ δ’ εὐδαιμονίᾳ κέχρηνται ὥστε πάμπολύ τι ἀπέχειν τῆς ἀοικήτου. ἐν μέν γε τῇ Ὑρκανίᾳ τὴν ἄμπελον μετρητὴν οἴνου φέρειν φασί, τὴν δὲ συκῆν μεδίμνους ἑξήκοντα, τὸν δὲ σῖτον ἐκ τοῦ ἐκπεσόντος καρποῦ τῆς καλάμης πάλιν φύεσθαι, ἐν δὲ τοῖς δένδρεσι σμηνουργεῖσθαι καὶ τῶν φύλλων ἀπορρεῖν μέλι, ὅπερ γίνεσθαι μὲν καὶ τῆς Μηδίας ἐν τῇ Ματιανῇ καὶ τῆς Ἀρμενίας ἐν τῇ Σακασηνῇ καὶ τῇ Ἀραξηνῇ· ἀλλ’ ἐνταῦθα μὲν οὐκ ἐπ’ ἴσης θαυμαστόν, εἴπερ εἰσὶ νοτιώτεραι τῆς Ὑρκανίας καὶ εὐκρασίᾳ διαφέρουσαι τῆς ἄλλης χώρας· ἐκεῖ δὲ μᾶλλον. ἐν δὲ τῇ Μαργιανῇ τὸν πυθμένα φασὶν εὑρίσκεσθαι τῆς ἀμπέλου πολλάκις δυεῖν ἀνδρῶν ὀργυιαῖς περιληπτόν, τὸν δὲ βότρυν δίπηχυν. παραπλησίαν δὲ λέγουσι καὶ τὴν Ἀρίαν, εὐοινίᾳ δὲ καὶ ὑπερβάλλειν, ἐν ᾗ γε καὶ εἰς τριγένειαν παραμένειν ἐν ἀπιττώτοις ἄγγεσι τὸν οἶνον· πάμφορον δ’ εἶναι καὶ τὴν Βακτριανὴν πλὴν ἐλαίου, πλησίον τῇ Ἀρίᾳ παρακειμένην.", "st": "2.1.14"}, {"sp": "N", "t": "εἰ δὲ καὶ ψυχρὰ μέρη τῶν τόπων τούτων ἐστίν, ὅσα ὑψηλὰ καὶ ὀρεινά, οὐδὲν δεῖ θαυμάζειν· καὶ γὰρ ἐν τοῖς μεσημβρινοῖς κλίμασι τὰ ὄρη ψυχρά ἐστι, καὶ καθόλου τὰ μετέωρα ἐδάφη, κἂν πεδία ᾖ. τῆς γοῦν Καππαδοκίας τὰ πρὸς τῷ Εὐξείνῳ πολὺ βορειότερά ἐστι τῶν πρὸς τῷ Ταύρῳ· ἀλλ’ ἡ μὲν Βαγαδανία, πεδίον ἐξαίσιον μεταξὺ πῖπτον τοῦ τε Ἀργαίου ὄρους καὶ τοῦ Ταύρου, σπάνιον εἴ πού τι τῶν καρπίμων δένδρων φύοι, καίπερ νοτιώτερον τῆς Ποντικῆς θαλάττης σταδίοις τρισχιλίοις, τὰ δὲ τῆς Σινώπης προάστεια καὶ τῆς Ἀμισοῦ καὶ τῆς Φαναροίας τὸ πλέον ἐλαιόφυτά ἐστι. καὶ τὸν Ὦξον δὲ τὸν ὁρίζοντα τὴν Βακτριανὴν ἀπὸ τῆς Σογδιανῆς οὕτω φασὶν εὔπλουν εἶναι ὥστε τὸν Ἰνδικὸν φόρτον ὑπερκομισθέντα εἰς αὐτὸν ῥᾳδίως εἰς τὴν Ὑρκανίαν κατάγεσθαι καὶ τοὺς ἐφεξῆς τόπους μέχρι τοῦ Πόντου διὰ τῶν ποταμῶν.", "st": "2.1.15"}, {"sp": "N", "t": "τίν’ [ἂν] οὖν τοιαύτην εὕροις εὐδαιμονίαν περὶ Βορυσθένη καὶ τὴν Κελτικὴν τὴν παρωκεανῖτιν; ὅπου μηδὲ φύεται ἄμπελος ἢ μὴ τελεσφορεῖ· ἐν δὲ τοῖς νοτιωτέροις τούτων καὶ ἐπιθαλαττιδίοις καὶ τοῖς κατὰ Βόσπορον τελεσφορεῖ, ἐν μικροκαρπίᾳ δέ, καὶ τοῦ χειμῶνος κατορύττεται. οἱ δὲ πάγοι παρ’ αὐτοῖς τοιοῦτοί τινές εἰσιν ἐπὶ τῷ στόματι τῆς λίμνης τῆς Μαιώτιδος, ὥστ’ ἐν χωρίῳ, ἐν ᾧ χειμῶνος ὁ τοῦ Μιθριδάτου στρατηγὸς ἐνίκησε τοὺς βαρβάρους ἱππομαχῶν ἐπὶ τῷ πάγῳ, τοὺς αὐτοὺς καταναυμαχῆσαι θέρους, λυθέντος τοῦ πάγου. ὁ δ’ Ἐρατοσθένης καὶ τοὐπίγραμμα προφέρεται τὸ ἐν τῷ Ἀσκληπιείῳ τῷ Παντικαπαιέων ἐπὶ τῇ ῥαγείσῃ χαλκῇ ὑδρίᾳ διὰ τὸν πάγον “εἴ τις ἄρ’ ἀνθρώπων μὴ πείθεται οἷα παρ’ ἡμῖν γίγνεται, εἰς τήνδε γνώτω ἰδὼν ὑδρίαν· ἣν οὐχ ὡς ἀνάθημα θεοῦ καλόν, ἀλλ’ ἐπίδειγμα χειμῶνος μεγάλου θῆχ’ ἱερεὺς Στρατίος.” ὅπου οὖν οὐδὲ τοῖς ἐν Βοσπόρῳ συγκριτέον τὰ ἐν τοῖς διαριθμηθεῖσι τόποις, ἀλλ’ οὐδὲ τοῖς ἐν Ἀμισῷ καὶ Σινώπῃ (καὶ γὰρ ἐκείνων εὐκρατοτέρους ἂν εἴποι τις), σχολῇ γ’ ἂν παραβάλλοιντο τοῖς κατὰ Βορυσθένη καὶ τοῖς ἐσχάτοις Κελτοῖς. μόλις γὰρ ἂν ταυτοκλινεῖς εἶεν τοῖς κατ’ Ἀμισὸν καὶ Σινώπην καὶ Βυζάντιον καὶ Μασσαλίαν, οἳ τοῦ Βορυσθένους καὶ τῶν Κελτῶν ὡμολόγηνται νοτιώτεροι σταδίοις τρισχιλίοις καὶ ἑπτακοσίοις.", "st": "2.1.16"}, {"sp": "N", "t": "οἱ δέ γε περὶ Δηίμαχον τοῖς τρισμυρίοις ἐὰν προσλάβωσι τὸ ἐπὶ τὴν Ταπροβάνην καὶ τοὺς ὅρους τῆς διακεκαυμένης, οὓς οὐκ ἐλάττους τῶν τετρακισχιλίων θετέον, ἐκτοπιοῦσι τά τε Βάκτρα καὶ τὴν Ἀρίαν εἰς τοὺς ἀπέχοντας τόπους τῆς διακεκαυμένης σταδίους τρισμυρίους καὶ τετρακισχιλίους, ὅσους ἀπὸ τοῦ ἰσημερινοῦ ἐπὶ Βορυσθένη φησὶν εἶναι ὁ Ἵππαρχος. ἐκπεσοῦνται ἄρα εἰς τοὺς βορειοτέρους τοῦ Βορυσθένους καὶ τῆς Κελτικῆς σταδίοις ὀκτακισχιλίοις καὶ ὀκτακοσίοις, ὅσοις νοτιώτερός ἐστιν ὁ ἰσημερινὸς τοῦ ὁρίζοντος κύκλου τὴν διακεκαυμένην καὶ τὴν εὔκρατον, ὅν φαμεν διὰ τῆς Κινναμωμοφόρου μάλιστα γράφεσθαι. ἡμεῖς δέ γε ἐπεδείκνυμεν μέχρι τῆς Ἰέρνης μόλις οἰκήσιμα ὄντα τὰ ὑπὲρ τὴν Κελτικήν, ἅπερ οὐ πλείω τῶν πεντακισχιλίων ἐστίν. οὗτος δ’ ἀποφαίνει ὁ λόγος τῆς Ἰέρνης ἔτι βορειότερον εἶναί τινα κύκλον οἰκήσιμον σταδίοις τρισχιλίοις ὀκτακοσίοις. ἔσται δὲ Βάκτρα καὶ τοῦ στόματος τῆς Κασπίας θαλάττης εἴτε Ὑρκανίας πάμπολύ τι ἀρκτικώτερα, ὅπερ τοῦ μυχοῦ τῆς Κασπίας καὶ τῶν Ἀρμενιακῶν καὶ Μηδικῶν ὀρῶν διέχει περὶ ἑξακισχιλίους σταδίους, καὶ δοκεῖ αὐτῆς τῆς παραλίας μέχρι τῆς Ἰνδικῆς ἀρκτικώτερον εἶναι σημεῖον καὶ περίπλουν ἔχειν ἀπὸ τῆς Ἰνδικῆς δυνατόν, ὥς φησιν ὁ τῶν τόπων ἡγησάμενος τούτων Πατροκλῆς. ἔτι τοίνυν ἡ Βακτριανὴ χίλια στάδια ἐπὶ τὴν ἄρκτον ἐκτείνεται· τὰ δὲ τῶν Σκυθῶν [ἔθνη] πολὺ μείζω ταύτης ἐπέκεινα χώραν νέμεται, καὶ τελευτᾷ πρὸς τὴν βόρειον θάλατταν, νομαδικῶς μὲν ζῶντα δ’ ὅμως. πῶς οὖν, εἴπερ καὶ αὐτὰ τὰ Βάκτρα ἤδη τῆς οἰκουμένης ἐκπίπτει; εἴη ἂν τὸ διάστημα τοῦτο ἀπὸ τοῦ Καυκάσου μέχρι τῆς βορείας θαλάττης τῇ διὰ Βάκτρων ὀλίγῳ πλειόνων ἢ τετρακισχιλίων. ταῦτα δὴ προστεθέντα τῷ ἀπὸ τῆς Ἰέρνης ἐπὶ τὰ βόρεια σταδιασμῷ ποιεῖ τὸ πᾶν διὰ τῆς ἀοικήτου διάστημα ἐπὶ τοῦ διὰ τῆς Ἰέρνης σταδιασμοῦ σταδίων ἑπτακισχιλίων καὶ ὀκτακοσίων· εἰ δὲ ἐάσειέ τις τοὺς τετρακισχιλίους σταδίους, αὐτά γε τὰ πρὸς τῷ Καυκάσῳ μέρη τῆς Βακτριανῆς ἔσται βορειότερα τῆς Ἰέρνης σταδίοις τρισχιλίοις καὶ ὀκτακοσίοις, τῆς δὲ Κελτικῆς καὶ τοῦ Βορυσθένους ὀκτακισχιλίοις καὶ ὀκτακοσίοις.", "st": "2.1.17"}, {"sp": "N", "t": "φησὶ δὲ ὁ Ἵππαρχος κατὰ τὸν Βορυσθένη καὶ τὴν Κελτικὴν ἐν ὅλαις ταῖς θεριναῖς νυξὶ παραυγάζεσθαι τὸ φῶς τοῦ ἡλίου περιιστάμενον ἀπὸ τῆς δύσεως ἐπὶ τὴν ἀνατολήν, ταῖς δὲ χειμεριναῖς τροπαῖς [τὸ] πλεῖστον μετεωρίζεσθαι τὸν ἥλιον ἐπὶ πήχεις ἐννέα, ἐν δὲ τοῖς ἀπέχουσι τῆς Μασσαλίας ἑξακισχιλίοις καὶ τριακοσίοις (οὓς ἐκεῖνος μὲν ἔτι Κελτοὺς ὑπολαμβάνει, ἐγὼ δ’ οἶμαι Βρεττανοὺς εἶναι, βορειοτέρους τῆς Κελτικῆς σταδίοις δισχιλίοις πεντακοσίοις) πολὺ μᾶλλον τοῦτο συμβαίνειν. ἐν δὲ ταῖς χειμεριναῖς ἡμέραις ὁ ἥλιος μετεωρίζεται πήχεις ἕξ, τέτταρας δ’ ἐν τοῖς ἀπέχουσι Μασσαλίας ἐνακισχιλίους σταδίους καὶ ἑκατόν, ἐλάττους δὲ τῶν τριῶν ἐν τοῖς ἐπέκεινα, οἳ κατὰ τὸν ἡμέτερον λόγον πολὺ ἂν εἶεν ἀρκτικώτεροι τῆς Ἰέρνης. οὗτος δὲ Πυθέᾳ πιστεύων κατὰ τὰ ἀρκτικώτερα τῆς Βρεττανικῆς τὴν οἴκησιν ταύτην τίθησι, καί φησιν εἶναι τὴν μακροτάτην ἐνταῦθα ἡμέραν ὡρῶν ἰσημερινῶν δέκα ἐννέα, ὀκτωκαίδεκα δὲ ὅπου τέτταρας ὁ ἥλιος μετεωρίζεται πήχεις· οὕς φησιν ἀπέχειν τῆς Μασσαλίας ἐνακισχιλίους καὶ ἑκατὸν σταδίους, ὥσθ’ οἱ νοτιώτατοι τῶν Βρεττανῶν βορειότεροι τούτων εἰσίν. ἤτοι οὖν ἐπὶ τοῦ αὐτοῦ παραλλήλου εἰσὶ τοῖς πρὸς τῷ Καυκάσῳ Βακτρίοις ἢ ἐπί τινος πλησιάζοντος· εἴρηται γὰρ ὅτι κατὰ τοὺς περὶ Δηίμαχον συμβήσεται βορειοτέρους εἶναι τῆς Ἰέρνης τοὺς πρὸς τῷ Καυκάσῳ Βακτρίους σταδίοις τρισχιλίοις ὀκτακοσίοις· προστεθέντων δὲ τούτων τοῖς ἀπὸ Μασσαλίας εἰς Ἰέρνην, γίνονται μύριοι δισχίλιοι πεντακόσιοι. τίς οὖν ἱστόρηκεν ἐν τοῖς ἐκεῖ τόποις (λέγω δὲ τοῖς περὶ Βάκτρα) τοῦτο τὸ μῆκος τῶν μεγίστων ἡμερῶν ἢ τὸ ἔξαρμα τοῦ ἡλίου τὸ κατὰ τὰς μεσουρανήσεις ἐν ταῖς χειμεριναῖς τροπαῖς; ὀφθαλμοφανῆ γὰρ πάντα ταῦτα [καὶ] ἰδιώτῃ καὶ οὐ δεόμενα μαθηματικῆς σημειώσεως, ὥστε συνέγραψαν ἂν πολλοὶ καὶ τῶν παλαιῶν τῶν τὰ Περσικὰ ἱστορούντων καὶ τῶν ὕστερον μέχρι καὶ εἰς ἡμᾶς. πῶς δ’ ἂν ἡ λεχθεῖσα εὐδαιμονία τῶν τόπων ὡμολόγητο τοῖς τοιούτοις ἐν τῷ οὐρανῷ φαινομένοις; ἐκ δὲ τῶν εἰρημένων δῆλον ὡς καὶ σοφῶς ἀντιλέγει πρὸς τὴν ἀπόδειξιν, ὡς ἰσοδυναμούντων τῶν ζητουμένων λαμβάνοντος πρὸς τὸ ἀποδεῖξαι τὸ ζητούμενον.", "st": "2.1.18"}, {"sp": "N", "t": "πάλιν δ’ ἐκείνου τὸν Δηίμαχον ἰδιώτην ἐνδείξασθαι βουλομένου καὶ ἄπειρον τῶν τοιούτων· οἴεσθαι γὰρ τὴν Ἰνδικὴν μεταξὺ κεῖσθαι τῆς τε φθινοπωρινῆς ἰσημερίας καὶ τῶν τροπῶν τῶν χειμερινῶν, Μεγασθένει τε ἀντιλέγειν φήσαντι ἐν τοῖς νοτίοις μέρεσι τῆς Ἰνδικῆς τάς τε ἄρκτους ἀποκρύπτεσθαι καὶ τὰς σκιὰς ἀντιπίπτειν· μηδέτερον γὰρ τούτων μηδαμοῦ τῆς Ἰνδικῆς συμβαίνειν· ταῦτα δὴ φάσκοντος ἀμαθῶς λέγεσθαι· τό τε γὰρ τὴν φθινοπωρινὴν τῆς ἐαρινῆς διαφέρειν οἴεσθαι κατὰ τὴν διάστασιν τὴν πρὸς τὰς τροπὰς ἀμαθές, τοῦ τε κύκλου τοῦ αὐτοῦ ὄντος καὶ τῆς ἀνατολῆς· τοῦ τε διαστήματος τοῦ ἐπὶ τῆς γῆς τροπικοῦ ἀπὸ τοῦ ἰσημερινοῦ, ὧν μεταξὺ τίθησι τὴν Ἰνδικὴν ἐκεῖνος, δειχθέντος ἐν τῇ ἀναμετρήσει πολὺ ἐλάττονος τῶν δισμυρίων σταδίων, συμβῆναι ἂν καὶ κατ’ αὐτὸν ἐκεῖνον, ὅπερ αὐτὸς νομίζει, οὐχ ὃ ἐκεῖνος· δυεῖν μὲν γὰρ ἢ καὶ τριῶν μυριάδων οὖσαν τὴν Ἰνδικὴν οὐδὲ πεσεῖν μεταξὺ τοσούτου διαστήματος, ὅσων δ’ αὐτὸς εἴρηκε, πεσεῖν ἄν· τῆς δ’ αὐτῆς ἀγνοίας εἶναι καὶ τὸ μηδαμοῦ τῆς Ἰνδικῆς ἀποκρύπτεσθαι φάσκειν τὰς ἄρκτους μηδὲ τὰς σκιὰς ἀντιπίπτειν, ὅτε γε καὶ πεντακισχιλίους προελθόντι ἀπ’ Ἀλεξανδρείας εὐθὺς συμβαίνειν ἄρχεται· ταῦτα δὴ εἰπόντος, εὐθύνει πάλιν οὐκ εὖ ὁ Ἵππαρχος, πρῶτον ἀντὶ τοῦ χειμερινοῦ τροπικοῦ τὸν θερινὸν δεξάμενος, εἶτ’ οὐκ οἰόμενος δεῖν μάρτυρι χρῆσθαι τῶν μαθηματικῶν ἀναστρολογήτῳ ἀνθρώπῳ, ὥσπερ τοῦ Ἐρατοσθένους προηγουμένως τὴν ἐκείνου μαρτυρίαν ἐγκρίνοντος, ἀλλ’ οὐ κοινῷ τινι ἔθει χρωμένου πρὸς τοὺς ματαιολογοῦντας. εἷς γάρ τις τῶν πρὸς τοὺς ματαίως ἀντιλέγοντας ἐλέγχων ἐστίν, ὅταν αὐτὴν τὴν ἐκείνων ἀπόφασιν, ὁποία ποτέ ἐστι, δείξωμεν ἡμῖν συνηγοροῦσαν.", "st": "2.1.19"}, {"sp": "N", "t": "νυνὶ μὲν οὖν ὑποθέμενοι τὰ νοτιώτατα τῆς Ἰνδικῆς ἀνταίρειν τοῖς κατὰ Μερόην, ὅπερ εἰρήκασι πολλοὶ καὶ πεπιστεύκασιν, ἐπεδείξαμεν τὰ συμβαίνοντα ἄτοπα. ἐπεὶ δὲ ὁ Ἵππαρχος οὐδὲν ἀντειπὼν τῇ ὑποθέσει ταύτῃ νυνὶ μετὰ ταῦτα ἐν τῷ δευτέρῳ ὑπομνήματι οὐ συγχωρεῖ, σκεπτέον καὶ τοῦτον τὸν λόγον. φησὶ τοίνυν ἀνταιρόντων ἀλλήλοις [τῶν] ἐπὶ τοῦ αὐτοῦ παραλλήλου κειμένων, ἐπειδὰν τὸ μεταξὺ ᾖ μέγα διάστημα, μὴ δύνασθαι γνωσθῆναι αὐτὸ τοῦτο ὅτι εἰσὶν ἐπὶ τοῦ αὐτοῦ παραλλήλου οἱ τόποι, ἄνευ τῆς τῶν κλιμάτων συγκρίσεως τῆς κατὰ θάτερον τὸν τόπον. τὸ μὲν οὖν κατὰ Μερόην κλίμα Φίλωνά τε τὸν συγγράψαντα τὸν εἰς Αἰθιοπίαν πλοῦν ἱστορεῖν, ὅτι πρὸ πέντε καὶ τετταράκοντα ἡμερῶν τῆς θερινῆς τροπῆς κατὰ κορυφὴν γίνεται ὁ ἥλιος, λέγειν δὲ καὶ τοὺς λόγους τοῦ γνώμονος πρός τε τὰς τροπικὰς σκιὰς καὶ τὰς ἰσημερινάς, αὐτόν τε Ἐρατοσθένη συμφωνεῖν ἔγγιστα τῷ Φίλωνι, τὸ δ’ ἐν τῇ Ἰνδικῇ κλίμα μηδένα ἱστορεῖν, μηδ’ αὐτὸν Ἐρατοσθένη. εἰ δὲ δὴ καὶ αἱ ἄρκτοι ἐκεῖ ἀμφότεραι, ὡς οἴεται, ἀποκρύπτονται, πιστεύων τοῖς περὶ Νέαρχον, μὴ δυνατὸν εἶναι ἐπὶ ταὐτοῦ παραλλήλου κεῖσθαι τήν τε Μερόην καὶ τὰ ἄκρα τῆς Ἰνδικῆς. εἰ μὲν τοίνυν περὶ τῶν ἄρκτων ἀμφοτέρων ὅτι ἀποκρύπτονται συναποφαίνεται τοῖς εἰποῦσιν Ἐρατοσθένης, πῶς περὶ τοῦ ἐν τῇ Ἰνδικῇ κλίματος οὐδεὶς ἀποφαίνεται, οὐδ’ αὐτὸς Ἐρατοσθένης; οὗτος γὰρ ὁ λόγος περὶ τοῦ κλίματός ἐστιν. εἰ δ’ οὐ συναποφαίνεται, ἀπηλλάχθω τῆς αἰτίας. οὐ συναποφαίνεται δέ γε, ἀλλὰ τοῦ Δηιμάχου φήσαντος μηδαμοῦ τῆς Ἰνδικῆς μήτ’ ἀποκρύπτεσθαι τὰς ἄρκτους μήτ’ ἀντιπίπτειν τὰς σκιάς, ἅπερ ὑπείληφεν ὁ Μεγασθένης, ἀπειρίαν αὐτοῦ καταγιγνώσκει, τὸ συμπεπλεγμένον νομίζων ψεῦδος, ἐν ᾧ ὁμολογουμένως καὶ κατ’ αὐτὸν τὸν Ἵππαρχον τό γε μὴ ἀντιπίπτειν τὰς σκιὰς ψεῦδος ἐμπέπλεκται. καὶ γὰρ εἰ μὴ τῇ Μερόῃ ἀνταίρει, τῆς γε Συήνης νοτιώτερα εἶναι τὰ ἄκρα τῆς Ἰνδικῆς συγχωρῶν φαίνεται.", "st": "2.1.20"}, {"sp": "N", "t": "καὶ ἐν τοῖς ἑξῆς δὲ περὶ τῶν αὐτῶν ἐπιχειρῶν ἢ ταὐτὰ λέγει τοῖς ἐξελεγχθεῖσιν ὑφ’ ἡμῶν, ἢ λήμμασι προσχρῆται ψευδέσιν, ἢ ἐπιφέρει τὸ μὴ ἀκολουθοῦν. οὔτε γὰρ τῷ ἀπὸ Βαβυλῶνος εἰς Θάψακον εἶναι σταδίους τετρακισχιλίους ὀκτακοσίους, ἐντεῦθεν δὲ πρὸς τὴν ἄρκτον ἐπὶ τὰ Ἀρμένια ὄρη [δις]χιλίους ἑκατόν, ἀκολουθεῖ τὸ ἀπὸ Βαβυλῶνος ἐπὶ τοῦ δι’ αὐτῆς μεσημβρινοῦ ἐπὶ τὰ ἀρκτικὰ ὄρη πλείους εἶναι τῶν ἑξακισχιλίων· οὔτε τὸ ἀπὸ Θαψάκου ἐπὶ τὰ ὄρη [δις]χιλίων καὶ ἑκατόν φησιν Ἐρατοσθένης, ἀλλ’ εἶναί τι λοιπὸν ἀκαταμέτρητον, ὥσθ’ ἡ ἑξῆς ἔφοδος ἐκ μὴ διδομένου λήμματος οὐκ ἂν ἐπεραίνετο· οὔτ’ ἀπεφήνατο οὐδαμοῦ Ἐρατοσθένης τὴν Θάψακον τῆς Βαβυλῶνος πρὸς ἄρκτους κεῖσθαι πλείοσιν ἢ τετρακισχιλίοις καὶ πεντακοσίοις σταδίοις.", "st": "2.1.21"}, {"sp": "N", "t": "̔εξῆς δὲ συνηγορῶν ἔτι τοῖς ἀρχαίοις πίναξιν οὐ τὰ λεγόμενα ὑπὸ τοῦ Ἐρατοσθένους προφέρεται περὶ τῆς τρίτης σφραγῖδος, ἀλλ’ ἑαυτῷ κεχαρισμένως πλάττει τὴν ἀπόφασιν πρὸς ἀνατροπὴν εὐφυῆ. ὁ μὲν γὰρ ἀκολουθῶν τῇ θέσει τῇ προειρημένῃ τοῦ τε Ταύρου καὶ τῆς ἀπὸ στηλῶν θαλάττης, διελὼν τῇ γραμμῇ ταύτῃ τὴν οἰκουμένην δίχα καὶ καλέσας τὸ μὲν βόρειον μέρος τὸ δὲ νότιον, πειρᾶται τούτων ἑκάτερον τέμνειν πάλιν εἰς τὰ δυνατὰ μέρη· καλεῖ δὲ ταῦτα σφραγῖδας. καὶ δὴ τοῦ νοτίου μέρους πρώτην εἰπὼν σφραγῖδα τὴν Ἰνδικήν, δευτέραν δὲ τὴν Ἀριανήν, ἐχούσας τι εὐπερίγραφον, ἴσχυσεν ἀμφοτέρων ἀποδοῦναι καὶ μῆκος καὶ πλάτος, τρόπον δέ τινα καὶ σχῆμα, ὡς ἂν γεωμετρικός. τὴν μὲν γὰρ Ἰνδικὴν ῥομβοειδῆ φησι διὰ τὸ τῶν πλευρῶν τὰς μὲν θαλάττῃ κλύζεσθαι τῇ τε νοτίῳ καὶ τῇ ἑῴᾳ, μὴ πάνυ κολπώδεις ᾐόνας ποιούσαις, τὰς δὲ λοιπὰς τὴν μὲν τῷ ὄρει τὴν δὲ τῷ ποταμῷ, κἀνταῦθα τοῦ εὐθυγράμμου σχήματος ὑπό τι σωζομένου· τὴν δ’ Ἀριανὴν ὁρῶν τάς γε τρεῖς πλευρὰς ἔχουσαν εὐφυεῖς πρὸς τὸ ἀποτελέσαι παραλληλόγραμμον σχῆμα, τὴν δ’ ἑσπέριον οὐκ ἔχων σημείοις ἀφορίσαι διὰ τὸ ἐπαλλάττειν ἀλλήλοις τὰ ἔθνη, γραμμῇ τινι ὅμως δηλοῖ τῇ ἀπὸ Κασπίων πυλῶν ἐπὶ τὰ ἄκρα τῆς Καρμανίας τελευτώσῃ τὰ συνάπτοντα πρὸς τὸν Περσικὸν κόλπον. ἑσπέριον μὲν οὖν καλεῖ τοῦτο τὸ πλευρόν, ἑῷον δὲ τὸ παρὰ τὸν Ἰνδόν, παράλληλα δ’ οὐ λέγει· οὐδὲ τὰ λοιπά, τό τε τῷ ὄρει γραφόμενον καὶ τὸ τῇ θαλάττῃ, ἀλλὰ μόνον τὸ μὲν βόρειον τὸ δὲ νότιον.", "st": "2.1.22"}, {"sp": "N", "t": "οὕτω δ’ ὁλοσχερεῖ τινι τύπῳ τὴν δευτέραν ἀποδιδοὺς σφραγῖδα πολὺ ταύτης ὁλοσχερέστερον ἀποδίδωσι τὴν τρίτην σφραγῖδα κατὰ πλείους αἰτίας. πρώτην μὲν τὴν λεχθεῖσαν, ὅτι οὐκ εὐκρινῶς ἀφώρισται ἡ ἀπὸ Κασπίων πυλῶν ἐπὶ Καρμανίαν, ἥτις κοινή ἐστι τῇ τρίτῃ πρὸς τὴν δευτέραν σφραγῖδα πλευρά· ἔπειθ’ ὅτι εἰς τὴν νότιον πλευρὰν ὁ Περσικὸς ἐμπίπτει κόλπος, ὅπερ καὶ αὐτός φησιν, ὥστ’ ἠνάγκασται τὴν ἐκ Βαβυλῶνος λαβεῖν γραμμὴν ὡς ἂν εὐθεῖάν τινα διὰ Σούσων καὶ Περσεπόλεως μέχρι τῶν ὅρων τῆς Καρμανίας καὶ τῆς Περσίδος, ᾗ δυνατὸς ἦν εὑρεῖν μεμετρημένην ὁδόν, σταδίων οὖσαν τὴν ὅλην μικρῷ πλειόνων ἢ ἐνακισχιλίων· ἣν νότιον μὲν καλεῖ πλευράν, παράλληλον δ’ οὐ λέγει τῇ βορείῳ. δῆλον δ’ ὅτι οὐδ’ ὁ Εὐφράτης, ᾧ τὸ ἑσπέριον ἀφορίζει πλευρόν, σύνεγγύς ἐστιν εὐθείᾳ γραμμῇ, ἀλλ’ ἀπὸ τῶν ὀρῶν ἐπὶ τὴν μεσημβρίαν ῥυεὶς εἶτ’ ἐπιστρέφει πρὸς ἕω καὶ πάλιν πρὸς νότον μέχρι τῆς εἰς θάλατταν ἐκβολῆς. δηλοῖ δὲ τὸ μὴ εὐθύπορον τοῦ ποταμοῦ, φράζων τὸ σχῆμα τῆς Μεσοποταμίας, ὃ ποιοῦσι συμπίπτοντες εἰς ἓν ὅ τε Τίγρις καὶ ὁ Εὐφράτης, ὑπηρεσίῳ παραπλήσιον, ὥς φησι. καὶ μὴν οὐδὲ πᾶν μεμετρημένον ἔχει τὸ ἑσπέριον πλευρὸν τὸ ἀφοριζόμενον ὑπὸ τοῦ Εὐφράτου, ἀλλὰ φησὶ τὸ πρὸς τῇ Ἀρμενίᾳ μέρος καὶ τοῖς ἀρκτικοῖς ὄρεσι μὴ ἔχειν [εἰπεῖν] πόσον ἐστὶ διὰ τὸ ἀμέτρητον εἶναι. διὰ δὴ ταῦτα πάντα τυπωδῶς φησιν ἀποδιδόναι τὴν τρίτην μερίδα· καὶ γὰρ καὶ τὰ διαστήματά φησιν ἐκ πολλῶν συναγαγεῖν τῶν τοὺς σταθμοὺς πραγματευσαμένων, [ὧν] τινὰς καὶ ἀνεπιγράφους καλεῖ. ἀγνωμονεῖν δὴ δόξειεν ἂν ὁ Ἵππαρχος πρὸς τὴν τοιαύτην ὁλοσχέρειαν γεωμετρικῶς ἀντιλέγων, ἐν ᾗ χάριν εἰδέναι δεῖ τοῖς καὶ ὁπωσοῦν ἀπαγγείλασιν ἡμῖν τὴν τῶν τόπων φύσιν. ὅταν δὲ δὴ μηδ’ ἐξ ὧν ἐκεῖνος λέγει λαμβάνῃ τὰς γεωμετρικὰς ὑποθέσεις ἀλλ’ ἑαυτῷ πλάσας, ἐκφανέστερον ἂν τὸ φιλότιμον καταμηνύοιτο.", "st": "2.1.23"}, {"sp": "N", "t": "̔ο μὲν δὴ οὕτως φησὶ τὴν τρίτην μερίδα τυπωδῶς ἀποδίδοσθαι μυρίων σταδίων ἀπὸ Κασπίων πυλῶν ἐπὶ τὸν Εὐφράτην, κατὰ μέρος δὲ διαιρῶν, ὡς ἀναγεγραμμένην εὗρε τὴν μέτρησιν οὕτω τίθησιν, ἔμπαλιν τὴν ἀρχὴν ἀπὸ τοῦ Εὐφράτου ποιησάμενος καὶ τῆς κατὰ Θάψακον διαβάσεως αὐτοῦ. μέχρι μὲν δὴ τοῦ Τίγριδος, ὅπου Ἀλέξανδρος διέβη, σταδίους [δις]χιλίους καὶ τετρακοσίους γράφει· ἐντεῦθεν δ’ ἐπὶ τοὺς ἑξῆς τύπους διὰ Γαυγαμήλων καὶ τοῦ Λύκου καὶ Ἀρβήλων καὶ Ἐκβατάνων, ᾗ Δαρεῖος ἐκ τῶν Γαυγαμήλων ἔφυγε μέχρι Κασπίων πυλῶν, τοὺς μυρίους ἐκπληροῖ, τριακοσίοις μόνον πλεονάσας. τὸ μὲν δὴ βόρειον πλευρὸν οὕτω καταμετρεῖ, οὐ παράλληλον τοῖς ὄρεσι θεὶς οὐδὲ τῇ διὰ στηλῶν καὶ Ἀθηνῶν καὶ Ῥόδου γραμμῇ· ἡ γὰρ Θάψακος πολὺ τῶν ὀρῶν ἀφέστηκε, συμπίπτει δὲ καὶ τὸ ὄρος καὶ ἡ ἀπὸ Θαψάκου ὁδὸς ἐπὶ τὰς Κασπίους πύλας. καὶ τά γε προσάρκτια μέρη τοῦ ὅρου ταῦτ’ ἐστίν.", "st": "2.1.24"}, {"sp": "N", "t": "Ἀποδοὺς δὲ τὸ βόρειον οὕτω πλευρόν “τὸ δὲ νότιον” φησί “παρὰ μὲν τὴν θάλατταν οὐκ ἔστι λαβεῖν διὰ τὸ τὸν Περσικὸν ἐμπίπτειν κόλπον, ἀπὸ Βαβυλῶνος δὲ διὰ Σούσων καὶ Περσεπόλεως μέχρι τῶν ὁρίων τῆς τε Περσίδος καὶ τῆς Καρμανίας σταδίους εἶναι ἐνακισχιλίους καὶ διακοσίους,” νότιον μὲν λέγων, παράλληλον δ’ οὐ λέγων τῷ βορείῳ τὸ νότιον. τὴν δὲ διαφωνίαν τοῦ μήκους φησὶ συμβαίνειν, τοῦ τε βορείου τεθέντος πλευροῦ καὶ τοῦ νοτίου, διὰ τὸ τὸν Εὐφράτην μέχρι τινὸς πρὸς μεσημβρίαν ῥυέντα πρὸς τὴν ἕω πολὺ ἐγκλίνειν.", "st": "2.1.25"}, {"sp": "N", "t": "τῶν δὲ πλαγίων πλευρῶν τὴν ἑσπερίαν λέγει πρῶτον, ἣν ὁποία τίς ἐστιν, εἴτε μία εἴτε δύο, ἐν μέσῳ πάρεστι σκοπεῖν. ἀπὸ γὰρ τῆς κατὰ Θάψακόν φησι διαβάσεως παρὰ τὸν Εὐφράτην εἰς μὲν Βαβυλῶνα σταδίους εἶναι τετρακισχιλίους ὀκτακοσίους, ἐντεῦθεν δ’ ἐπὶ τὰς ἐκβολὰς τοῦ Εὐφράτου καὶ πόλιν Τερηδόνα τρισχιλίους· τὰ δ’ ἀπὸ Θαψάκου πρὸς τὰς ἄρκτους μέχρι μὲν τῶν Ἀρμενίων πυλῶν καταμεμετρῆσθαι καὶ εἶναι ὡς χιλίους ἑκατόν, τοὺς δὲ διὰ Γορδυαίων καὶ Ἀρμενίων μηκέτι· διὸ δὴ παραλείπειν αὐτούς. τοῦ δὲ πρὸς ἕω πλευροῦ τὸ μὲν διὰ τῆς Περσικῆς κατὰ μῆκος ἀπὸ τῆς Ἐρυθρᾶς ὡς ἐπὶ Μηδίαν καὶ τὰς ἄρκτους οὐκ ἔλαττον εἶναι δοκεῖ τῶν ὀκτακισχιλίων, ἀπὸ δέ τινων ἀκρωτηρίων καὶ ὑπὲρ τοὺς ἐνακισχιλίους, τὸ δὲ λοιπὸν διὰ τῆς Παραιτακηνῆς καὶ Μηδίας ἐπὶ Κασπίους πύλας ὡς τρισχιλίων· τὸν δὲ Τίγριν ποταμὸν καὶ τὸν Εὐφράτην ῥέοντας ἐκ τῆς Ἀρμενίας πρὸς μεσημβρίαν, ἐπειδὰν παραμείψωνται τὰ τῶν Γορδυαίων ὄρη, κύκλον μέγαν περιβαλομένους καὶ ἐμπεριλαβόντας χώραν πολλὴν τὴν Μεσοποταμίαν ἐπιστρέφειν πρὸς χειμερινὴν ἀνατολὴν καὶ τὴν μεσημβρίαν, πλέον δὲ τὸν Εὐφράτην· γενόμενον δὲ τοῦτον ἔγγιον ἀεὶ τοῦ Τίγριδος κατὰ τὸ Σεμιράμιδος διατείχισμα καὶ κώμην καλουμένην Ὦπιν, διασχόντα ταύτης ὅσον διακοσίους σταδίους καὶ ῥυέντα διὰ Βαβυλῶνος ἐκπίπτειν εἰς τὸν Περσικὸν κόλπον. “γίνεται δή” φησί “τὸ σχῆμα τῆς Μεσοποταμίας καὶ Βαβυλωνίας ὑπηρεσίῳ παραπλήσιον.” ὁ μὲν δὴ Ἐρατοσθένης τοιαῦτ’ εἴρηκε.", "st": "2.1.26"}, {"sp": "N", "t": "περὶ δὲ τῆς τρίτης σφραγῖδος καὶ ἄλλα μέν τινα ἁμαρτήματα ποιεῖ, περὶ ὧν ἐπισκεψόμεθα, ἃ δὲ Ἵππαρχος προφέρει αὐτῷ, οὐ πάνυ. σκοπῶμεν δ’ ἃ λέγει. βουλόμενος γὰρ βεβαιοῦν τὸ ἐξ ἀρχῆς, ὅτι οὐ μεταθετέον τὴν Ἰνδικὴν ἐπὶ τὰ νοτιώτερα, ὥσπερ Ἐρατοσθένης ἀξιοῖ, σαφὲς ἂν γενέσθαι τοῦτο μάλιστά φησιν ἐξ ὧν αὐτὸς ἐκεῖνος προφέρεται· τὴν γὰρ τρίτην μερίδα κατὰ τὴν βόρειον πλευρὰν εἰπόντα ἀφορίζεσθαι ὑπὸ τῆς ἀπὸ Κασπίων πυλῶν ἐπὶ τὸν Εὐφράτην γραμμῆς σταδίων μυρίων οὔσης, μετὰ ταῦτα ἐπιφέρειν ὅτι τὸ νότιον πλευρὸν τὸ ἀπὸ Βαβυλῶνος εἰς τοὺς ὅρους τῆς Καρμανίας μικρῷ πλειόνων ἐστὶν ἢ ἐνακισχιλίων, τὸ δὲ πρὸς δύσει πλευρὸν ἀπὸ Θαψάκου παρὰ τὸν Εὐφράτην ἐστὶν εἰς Βαβυλῶνα τετρακισχίλιοι ὀκτακόσιοι στάδιοι, καὶ ἑξῆς ἐπὶ τὰς ἐκβολὰς τρισχίλιοι, τὰ δὲ πρὸς ἄρκτον ἀπὸ Θαψάκου τὸ μὲν ἀπομεμέτρηται μέχρι χιλίων ἑκατόν, τὸ λοιπὸν δ’ οὐκέτι. “ἐπεὶ τοίνυν” φησί “τὸ μὲν βόρειόν ἐστι πλευρὸν τῆς τρίτης μερίδος ὡς μυρίων, ἡ δὲ τούτῳ παράλληλος ἀπὸ Βαβυλῶνος εὐθεῖα μέχρι ἀνατολικοῦ πλευροῦ συνελογίσθη μικρῷ πλειόνων ἢ ἐνακισχιλίων, δῆλον ὅτι ἡ Βαβυλὼν οὐ πολλῷ πλείοσιν ἢ χιλίοις σταδίοις ἐστὶν ἀνατολικωτέρα τῆς κατὰ Θάψακον διαβάσεως.”", "st": "2.1.27"}, {"sp": "N", "t": "Ἐροῦμεν δ’ ὅτι, εἰ μὲν ἐπὶ τῆς αὐτῆς μεσημβρινῆς εὐθείας ἐπ’ ἀκριβὲς ἐλαμβάνοντο αἵ τε Κάσπιοι πύλαι καὶ οἱ ὅροι τῶν Καρμανίων καὶ Περσῶν, πρὸς ὀρθάς τε ἤγοντο ἀπὸ τῆς λεχθείσης μεσημβρινῆς εὐθείας ἥ τε ἐπὶ Θάψακον καὶ ἡ ἐπὶ Βαβυλῶνα, συνέβαινεν ἂν τοῦτο. ἡ γὰρ προσεκβαλλομένη τῇ διὰ Βαβυλῶνος μέχρι τῆς διὰ Θαψάκου εὐθείας μεσημβρινῆς ἴση ἂν ἦν πρὸς αἴσθησιν ἢ πάρισός γε τῇ ἀπὸ Κασπίων πυλῶν εἰς Θάψακον, ὥστε τῇ ὑπεροχῇ ἐγίνετ’ ἂν ἀνατολικωτέρα ἡ Βαβυλὼν τῆς Θαψάκου, ᾗ ὑπερέχει ἡ ἐκ Κασπίων πυλῶν εἰς Θάψακον τῆς ἐκ τῶν Καρμανίων ὅρων εἰς Βαβυλῶνα. ἀλλ’ οὔτε τὴν διορίζουσαν γραμμὴν ἑσπέριον πλευρὸν τῆς Ἀριανῆς ἐπὶ μεσημβρινοῦ κειμένην εἴρηκεν Ἐρατοσθένης, οὔτε τὴν ἀπὸ Κασπίων πυλῶν ἐπὶ Θάψακον πρὸς ὀρθὰς τῇ διὰ τῶν Κασπίων πυλῶν μεσημβρινῇ, ἀλλὰ μᾶλλον τὴν τῷ ὄρει γραφομένην, πρὸς ἣν ἡ ἐπὶ Θάψακον γωνίαν ποιεῖ ἀπὸ τοῦ αὐτοῦ σημείου κατηγμένη ἀφ’ οὗ καὶ ἡ τοῦ ὄρους γραμμή· οὔθ’ ἡ ἐπὶ Βαβυλῶνα ἠγμένη ἀπὸ τῆς Καρμανίας παράλληλος εἴρηται τῇ ἐπὶ Θάψακον ἠγμένῃ· οὐδ’ εἰ παράλληλος ἦν, μὴ [πρὸς] ὀρθὰς δὲ τῇ διὰ Κασπίων πυλῶν μεσημβρινῇ, οὐδὲν ἂν ἐγίνετο πλέον πρὸς τὸν συλλογισμόν.", "st": "2.1.28"}, {"sp": "N", "t": "ὁ δὲ ταῦτα λαβὼν ἐξ ἑτοίμου καὶ δείξας, ὡς οἴεται, διότι ἡ Βαβυλὼν κατὰ Ἐρατοσθένη Θαψάκου ἀνατολικωτέρα ἐστὶ μικρῷ πλείοσιν ἢ χιλίοις σταδίοις, πάλιν ἄλλως πλάττει λῆμμα ἑαυτῷ πρὸς τὴν ἑξῆς ἀπόδειξιν καί φησιν, ἐὰν ἐννοηθῇ ἀπὸ Θαψάκου ἐπὶ μεσημβρίαν εὐθεῖα ἀγομένη καὶ ἀπὸ Βαβυλῶνος ἐπὶ ταύτην κάθετος, τρίγωνον ὀρθογώνιον ἔσεσθαι, συνεστηκὸς ἔκ τε τῆς ἀπὸ Θαψάκου ἐπὶ Βαβυλῶνα τεινούσης πλευρᾶς καὶ τῆς ἀπὸ Βαβυλῶνος καθέτου ἐπὶ τὴν διὰ Θαψάκου μεσημβρινὴν γραμμὴν ἠγμένης καὶ αὐτῆς τῆς διὰ Θαψάκου μεσημβρινῆς. τούτου δὲ τοῦ τριγώνου τὴν μὲν ὑποτείνουσαν τῇ ὀρθῇ τὴν ἀπὸ Θαψάκου εἰς Βαβυλῶνα τίθησιν, ἥν φησι τετρακισχιλίων ὀκτακοσίων εἶναι, τὴν δ’ ἐκ Βαβυλῶνος εἰς τὴν διὰ Θαψάκου μεσημβρινὴν γραμμὴν κάθετον μικρῷ πλειόνων ἢ χιλίων, ὅσων ἦν ἡ ὑπεροχὴ τῆς ἐπὶ Θάψακον πρὸς τὴν μέχρι Βαβυλῶνος· ἐκ δὲ τούτων καὶ τὴν λοιπὴν τῶν περὶ τὴν ὀρθὴν συλλογίζεται πολλαπλάσιον οὖσαν τῆς λεχθείσης καθέτου· προστίθησι δὲ ταύτῃ τὴν ἀπὸ Θαψάκου πρὸς ἄρκτον ἐκβαλλομένην μέχρι τῶν Ἀρμενίων ὀρῶν, ἧς τὸ μὲν ἔφη μεμετρῆσθαι Ἐρατοσθένης καὶ εἶναι χιλίων ἑκατόν, τὸ δ’ ἀμέτρητον ἐᾷ. οὗτος δ’ ἐπὶ τοὐλάχιστον ὑποτίθεται χιλίων, ὥστε τὸ συνάμφω δισχιλίων καὶ ἑκατὸν γίγνεσθαι, ὃ προσθεὶς τῇ ἐπ’ εὐθείας πλευρᾷ τοῦ τριγώνου μέχρι τῆς καθέτου τῆς ἐκ Βαβυλῶνος πολλῶν χιλιάδων λογίζεται διάστημα τὸ ἀπὸ τῶν Ἀρμενίων ὀρῶν καὶ τοῦ δι’ Ἀθηνῶν παραλλήλου μέχρι τῆς ἐκ Βαβυλῶνος καθέτου, ἥτις ἐπὶ τοῦ διὰ Βαβυλῶνος παραλλήλου ἵδρυται. τὸ δέ γε ἀπὸ τοῦ δι’ Ἀθηνῶν παραλλήλου ἐπὶ τὸν διὰ Βαβυλῶνος δείκνυσιν οὐ μεῖζον ὂν σταδίων δισχιλίων τετρακοσίων, ὑποτεθέντος τοῦ μεσημβρινοῦ παντὸς τοσούτων σταδίων, ὅσων Ἐρατοσθένης φησίν. εἰ δὲ τοῦτο, οὐκ ἂν ἦν τὰ ὄρη τὰ Ἀρμένια καὶ τὰ τοῦ Ταύρου ἐπὶ τοῦ δι’ Ἀθηνῶν παραλλήλου, ὡς Ἐρατοσθένης, ἀλλὰ πολλαῖς χιλιάσι σταδίων ἀρκτικώτερα κατ’ αὐτὸν ἐκεῖνον. ἐνταῦθα δὴ πρὸς τῷ τοῖς ἀνεσκευασμένοις λήμμασι προσχρῆσθαι πρὸς τὴν τοῦ ὀρθογωνίου τριγώνου τάξιν καὶ τοῦτο λαμβάνει τὸ μὴ διδόμενον, τὸ τὴν ὑποτείνουσαν τῇ ὀρθῇ γωνίᾳ τὴν ἀπὸ Θαψάκου γραμμὴν εὐθεῖαν εἶναι μέχρι Βαβυλῶνος ἐν σταδίοις τετρακισχιλίοις ὀκτακοσίοις. παρά τε γὰρ τὸν Εὐφράτην φησὶν εἶναι τὴν ὁδὸν ταύτην ὁ Ἐρατοσθένης, καὶ τὴν Μεσοποταμίαν σὺν τῇ Βαβυλωνίᾳ μεγάλῳ κύκλῳ περιέχεσθαι λέγων ὑπό τε τοῦ Εὐφράτου καὶ τοῦ Τίγριδος, τὸ πλέον δὲ τῆς περιοχῆς ὑπὸ τοῦ Εὐφράτου συμβαίνειν φησίν· ὥσθ’ ἡ ἀπὸ Θαψάκου εἰς Βαβυλῶνα εὐθεῖα οὔτ’ ἂν παρὰ τὸν Εὐφράτην εἴη οὔτ’ ἂν τοσούτων σταδίων οὐδ’ ἐγγύς. ἀνατέτραπται οὖν ὁ συλλογισμός· καὶ μὴν εἴρηταί γε, ὅτι οὐχ οἷόν τε δυεῖν δεδομένων γραμμῶν ἀπὸ τῶν Κασπίων πυλῶν κατάγεσθαι τὴν μὲν ἐπὶ Θάψακον τὴν δ’ ἐπὶ τὰ τῶν Ἀρμενίων ὄρη τὰ κατάλληλα τῇ Θαψάκῳ, ἀπέχοντα τῆς Θαψάκου τοὐλάχιστον κατ’ αὐτὸν τὸν Ἵππαρχον δισχιλίους καὶ ἑκατὸν σταδίους, ἀμφοτέρας παραλλήλους εἶναι καὶ ἀλλήλαις καὶ τῇ διὰ Βαβυλῶνος, ἣν νότιον πλευρὰν Ἐρατοσθένης ἐκάλεσεν. ἐκεῖνος μὲν οὖν οὐκ ἔχων καταμεμετρημένην εἰπεῖν τὴν παρὰ τὰ ὄρη ὁδόν, τὴν δ’ ἀπὸ Θαψάκου ἐπὶ Κασπίους πύλας, ταύτην εἶπε καὶ προσέθηκε τὸ ὡς τυπωδῶς εἰπεῖν· ἄλλως τε τῷ βουλομένῳ τὸ μῆκος εἰπεῖν τῆς μετὰ τὴν Ἀριανὴν μέχρι Εὐφράτου χώρας οὐ πολὺ διέφερε ταύτην ἢ ἐκείνην καταμετρεῖν. ὁ δ’ ὡς παραλλήλους ὑπακούων λέγεσθαι τελέως ἂν δόξειε καταγινώσκειν παιδικὴν ἀμαθίαν τἀνθρώπου.", "st": "2.1.29"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἐᾶν δεῖ ὡς παιδικά. ἃ δ’ ἄν τις αἰτιάσαιτο τοῦ Ἐρατοσθένους τοιαῦτά ἐστι. καθάπερ γὰρ ἡ κατὰ μέλος τομὴ τῆς ἄλλως κατὰ μέρος διαφέρει (διότι ἡ μὲν καὶ τὰ μέρη λαμβάνει περιγραφὴν ἔχοντα φυσικήν, ἀρθρώσει τινὶ καὶ τύπῳ σημειώδη, ἡ δ’ οὐδὲν ἔχει τοιοῦτον), χρώμεθα δ’ οἰκείως ἑκατέρᾳ τὸν καιρὸν καὶ τὴν χρείαν σκοποῦντες, οὕτως ἐπὶ τῶν γεωγραφικῶν δεῖ μὲν τομὰς ποιεῖσθαι τῶν μερῶν τὰ καθ’ ἕκαστα ἐπιόντας, μιμεῖσθαι δὲ τὰς κατὰ μέλος τομὰς μᾶλλον ἢ τὰς ὡς ἔτυχε. τὸ γὰρ σημειῶδες καὶ τὸ εὐπεριόριστον ἐκεῖθεν λαβεῖν ἔστιν, οὗ χρείαν ἔχει ὁ γεωγράφος· εὐπεριόριστον δέ, ὅταν ἢ ποταμοῖς ἢ ὄρεσιν ἢ θαλάττῃ δυνατὸν ᾖ, καὶ ἔθνει δὲ ἢ ἔθνεσι καὶ μεγέθει ποσῷ καὶ σχήματι, ὅπου τοῦτο δυνατόν. πανταχοῦ δὲ ἀντὶ τοῦ γεωμετρικῶς τὸ ἁπλῶς καὶ ὁλοσχερῶς ἱκανόν. μέγεθος μὲν οὖν ἱκανόν ἐστιν, ἂν τὸ μέγιστον εἴπῃς μῆκος καὶ πλάτος, ὡς τῆς οἰκουμένης ἑπτὰ μυριάδων εἰ τύχοι μῆκος, πλάτος δ’ ἔλαττον ἢ ἥμισυ μικρῷ τοῦ μήκους· σχῆμα δ’, ἂν τῶν γεωμετρικῶν τινὶ σχημάτων εἰκάσῃς, ὡς τὴν Σικελίαν τριγώνῳ, ἢ τῶν ἄλλων γνωρίμων τινὶ σχημάτων, οἷον τὴν Ἰβηρίαν βύρσῃ, τὴν Πελοπόννησον πλατάνου φύλλῳ· ὅσῳ δ’ ἂν μεῖζον ᾖ τὸ τεμνόμενον, τοσῷδε καὶ ὁλοσχερεστέρας πρέποι ἂν ποιεῖσθαι τὰς τομάς.", "st": "2.1.30"}, {"sp": "N", "t": "̔η μὲν οὖν οἰκουμένη δίχα διῄρηται τῷ τε Ταύρῳ καὶ τῇ ἐπὶ στήλας θαλάττῃ καλῶς. καὶ τοῦ νοτίου μέρους ἡ μὲν Ἰνδικὴ περιώρισται πολλοῖς· καὶ γὰρ ὄρει καὶ ποταμῷ καὶ θαλάττῃ καὶ ἑνὶ ὀνόματι ὡς ἑνὸς ἔθνους· ὥστε καὶ τετράπλευρος ὀρθῶς λέγεται καὶ ῥομβοειδής. ἡ δ’ Ἀριανὴ ἧττον μὲν τὸ εὐπερίγραφον ἔχει διὰ τὸ τὴν ἑσπερίαν πλευρὰν συγκεχύσθαι, διώρισται δ’ ὅμως ταῖς τε τρισὶ πλευραῖς ὡς ἂν εὐθείαις, καὶ τῷ ὀνόματι ὡς ἂν ἑνὸς ἔθνους. ἡ δὲ τρίτη σφραγὶς τελέως ἀπερίγραφός ἐστιν, οὕτω γε ἀφορισθεῖσα· ἥ τε γὰρ κοινὴ πλευρὰ αὐτῇ τε καὶ τῇ Ἀριανῇ συγκέχυται, ὡς προείρηται, καὶ ἡ νότιος πλευρὰ ἀργότατα εἴληπται· οὔτε γὰρ περιγράφει τὴν σφραγῖδα, διὰ μέσης τε αὐτῆς βαδίζουσα καὶ πολλὰ μέρη ἀπολείπουσα πρὸς νότον, οὔτε μῆκος ὑπογράφει τὸ μέγιστον (τὸ γὰρ προσάρκτιον πλευρὸν μεῖζον), οὔθ’ ὁ Εὐφράτης ἑσπέριόν ἐστι πλευρὸν οὐδ’ εἰ ἐπ’ εὐθείας ῥέοι, τῶν ἄκρων αὐτοῦ μὴ ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ κειμένων. τί γὰρ μᾶλλον ἑσπέριον ἢ νότιον; χωρὶς δὲ τούτων, ὀλίγης οὔσης τῆς ἐπὶ θάλατταν λοιπῆς τὴν Κιλίκιον καὶ τὴν Συριακήν, τὸ μὴ μέχρι δεῦρο προάγειν δεῖν τὴν σφραγῖδα οὐ πιθανόν, τῆς τε Σεμιράμιδος καὶ τοῦ Νίνου Σύρων λεγομένων, ὧν τῆς μὲν ἡ Βαβυλὼν κτίσμα καὶ βασίλειον, τοῦ δὲ Νίνος ὡς ἂν μητρόπολις τῆς Συρίας. καὶ τῆς διαλέκτου δὲ μέχρι νῦν διαμενούσης τῆς αὐτῆς τοῖς τε ἐκτὸς τοῦ Εὐφράτου καὶ τοῖς ἐντός, τὸ ἐνταῦθα μέντοι τοιούτῳ μερισμῷ διασπᾶν ἔθνος γνωριμώτατον καὶ τὰ μέρη συνάπτειν τοῖς ἀλλοεθνέσιν ἥκιστα ἂν πρέποι. οὐδὲ γὰρ ὑπὸ μεγέθους ἀπηναγκάσθαι λέγοι ἄν· καὶ γὰρ τὸ μέχρι θαλάττης οὐ μήν πω ἂν ἐξισάζοιτο τῇ Ἰνδικῇ, ἀλλ’ οὐδὲ τῇ Ἀριανῇ, προσλαβὸν καὶ τὸ μέχρι τῶν ὅρων τῆς εὐδαίμονος Ἀραβίας καὶ τῆς Αἰγύπτου· ὥστε πολὺ κρεῖττον ἦν μέχρι δεῦρο προελθεῖν, τῆς τρίτης εἰπόντα σφραγῖδος τοσαύτῃ προσθήκῃ τῇ μέχρι τῆς Συριακῆς θαλάττης τὸ μὲν νότιον πλευρὸν οὐχ ὥσπερ ἐκεῖνος εἶπεν ἔχον, οὐδ’ ἐπ’ εὐθείας, ἀλλ’ ἀπὸ τῆς Καρμανίας εὐθὺς τὴν δεξιὰν παραλίαν εἰσπλέοντι τὸν Περσικὸν κόλπον μέχρι τῆς ἐκβολῆς τοῦ Εὐφράτου, καὶ μετὰ ταῦτα τοῖς ὁρίοις τῆς Μεσήνης καὶ τῆς Βαβυλωνίας συνάπτον, ἥπερ ἐστὶν ἀρχὴ τοῦ διορίζοντος τὴν εὐδαίμονα Ἀραβίαν ἀπὸ τῆς ἄλλης ἠπείρου, εἶτ’ ἐφεξῆς αὐτὸν τοῦτον διεξιόν, διῆκόν τε μέχρι τοῦ μυχοῦ τοῦ Ἀραβίου κόλπου καὶ Πηλουσίου, καὶ ἔτι τοῦ Κανωβικοῦ στόματος τοῦ Νείλου· τοῦτο μὲν τὸ νότιον πλευρόν, τὸ δὲ λοιπὸν ἑσπέριον τὴν ἀπὸ τοῦ Κανωβικοῦ στόματος μέχρι τῆς Κιλικίας παραλίαν.", "st": "2.1.31"}, {"sp": "N", "t": "τετάρτη δ’ ἂν εἴη σφραγὶς ἡ συνεστῶσα ἔκ τε τῆς εὐδαίμονος Ἀραβίας καὶ τοῦ Ἀραβίου κόλπου καὶ τῆς Αἰγύπτου πάσης καὶ τῆς Αἰθιοπίας. ταύτης δὲ τῆς μερίδος μῆκος μὲν ἔσται τὸ ἀφοριζόμενον ὑπὸ δυεῖν μεσημβρινῶν· ὁ μὲν γὰρ γράφεται διὰ τοῦ δυσμικωτάτου σημείου τοῦ ἐπ’ αὐτῆς, ὁ δὲ διὰ τοῦ ἑωθινωτάτου· πλάτος δὲ τὸ μεταξὺ δυεῖν παραλλήλων, ὧν ὁ μὲν γράφεται διὰ τοῦ βορειοτάτου σημείου, ὁ δὲ διὰ τοῦ νοτιωτάτου· ἐπὶ γὰρ τῶν ἀνωμάλων σχημάτων, ἐφ’ ὧν πλευραῖς οὐ δυνατὸν ἀφορίσαι πλάτος καὶ μῆκος, οὕτω τὸ μέγεθος ἀφοριστέον. καθόλου δὲ νοητέον, ὅτι οὐχ ὡσαύτως λέγεται μῆκος καὶ πλάτος ἐπὶ ὅλου καὶ μέρους· ἀλλ’ ἐφ’ ὅλου μὲν τὸ μεῖζον διάστημα καλεῖται μῆκος, τὸ δ’ ἔλαττον πλάτος, ἐπὶ μέρους δὲ μῆκος μὲν τὸ παράλληλον τῷ τοῦ ὅλου μήκει τμῆμα ἐκείνου, ὁπότερον ἂν ᾖ μεῖζον, κἂν τὸ ληφθὲν διάστημα ἐν τῷ πλάτει μεῖζον ᾖ τοῦ ληφθέντος ἐν τῷ μήκει διαστήματος. διὸ καὶ τῆς οἰκουμένης ἀπ’ ἀνατολῆς ἐπὶ δύσιν μηκυνομένης, ἀπὸ δὲ ἄρκτων ἐπὶ νότον πλατυνομένης, καὶ τοῦ μὲν μήκους ἐπὶ παραλλήλου τινὸς τῷ ἰσημερινῷ γραφομένου, τοῦ δὲ πλάτους ἐπὶ μεσημβρινοῦ, δεῖ καὶ τῶν μερῶν λαμβάνεσθαι μήκη μὲν τὰ παράλληλα τῷ μήκει τμήματα αὐτῆς, πλάτη δὲ τὰ τῷ πλάτει. οὕτω γὰρ ἂν ἄμεινον ὑπογράφοιτο πρῶτον μὲν τὸ μέγεθος τῆς οἰκουμένης ὅλης, ἔπειτα καὶ ἡ διάθεσις καὶ τὸ σχῆμα τῶν μερῶν, καθ’ ἃ μὲν ἀπολείπειν καθ’ ἃ δὲ πλεονάζειν φαινομένων τῇ τοιαύτῃ παραθέσει.", "st": "2.1.32"}, {"sp": "N", "t": "Ἐρατοσθένης δὲ τὸ μὲν τῆς οἰκουμένης λαμβάνει μῆκος ἐπὶ τῆς διὰ στηλῶν καὶ Κασπίων πυλῶν καὶ Καυκάσου γραμμῆς, ὡς ἂν εὐθείας, τὸ δὲ τῆς τρίτης μερίδος ἐπὶ τῆς διὰ Κασπίων πυλῶν καὶ Θαψάκου, τὸ δὲ τῆς τετάρτης ἐπὶ τῆς διὰ Θαψάκου καὶ Ἡρώων πόλεως μέχρι τῆς μεταξὺ τῶν στομάτων τοῦ Νείλου, [ἣν] ἀνάγκη καταστρέφειν εἰς τοὺς περὶ Κάνωβον καὶ Ἀλεξάνδρειαν τόπους· ἐνταῦθα γάρ ἐστι τὸ ἔσχατον στόμα τὸ καλούμενον Κανωβικόν τε καὶ Ἡρακλεωτικόν. εἴτ’ οὖν ἐπ’ εὐθείας ἀλλήλοις τὰ μήκη τίθησιν, εἴθ’ ὡς ἂν γωνίαν ποιοῦντα κατὰ Θάψακον, ἀλλ’ ὅτι γε οὐ παράλληλον οὐδέτερον τῷ τῆς οἰκουμένης μήκει, φανερόν ἐστιν ἐξ αὐτῶν ὧν εἴρηκεν αὐτός. τὸ μὲν γὰρ τῆς οἰκουμένης μῆκος διὰ τοῦ Ταύρου γράφει καὶ τῆς ἐπ’ εὐθείας μέχρι στηλῶν θαλάττης κατὰ γραμμὴν τὴν διὰ τοῦ Καυκάσου καὶ Ῥόδου καὶ Ἀθηνῶν, ἀπὸ δὲ Ῥόδου εἰς Ἀλεξάνδρειαν κατὰ τὸν δι’ αὐτῶν μεσημβρινὸν οὐ πολὺ ἐλάττους τῶν τετρακισχιλίων φησὶν εἶναι σταδίων, ὥστε τοσοῦτον καὶ οἱ παράλληλοι διέχοιεν ἂν ἀλλήλων ὅ τε διὰ Ῥόδου καὶ ὁ δι’ Ἀλεξανδρείας. ὁ δ’ αὐτός πώς ἐστι τούτῳ ὁ διὰ τῆς Ἡρώων πόλεως, ἢ νοτιώτερός γε τούτου, ὥσθ’ ἡ συμπίπτουσα γραμμὴ τούτῳ τε τῷ παραλλήλῳ καὶ τῷ διὰ Ῥόδου καὶ Κασπίων πυλῶν, εἴτ’ εὐθεῖα εἴτε κεκλασμένη, οὐκ ἂν εἴη παράλληλος οὐδετέρᾳ. οὐκ εὖ γοῦν λαμβάνεται τὰ μήκη, οὐκ εὖ δὲ οὐδὲ αἱ βόρειοι λαμβάνονται μερίδες.", "st": "2.1.33"}, {"sp": "N", "t": "Ἀλλ’ ἐπὶ τὸν Ἵππαρχον πρότερον ἐπανιόντες τὰ ἑξῆς ἴδωμεν. πάλιν γὰρ πλάσας ἑαυτῷ λήμματα γεωμετρικῶς ἀνασκευάζει τὰ ὑπ’ ἐκείνου τυπωδῶς λεγόμενα. φησὶ γὰρ αὐτὸν λέγειν τὸ ἐκ Βαβυλῶνος εἰς μὲν Κασπίους πύλας διάστημα σταδίων ἑξακισχιλίων ἑπτακοσίων, εἰς δὲ τοὺς ὅρους τῆς Καρμανίας καὶ Περσίδος πλειόνων ἢ ἐνακισχιλίων, ὅπερ ἐπὶ γραμμῆς κεῖται πρὸς ἰσημερινὰς ἀνατολὰς εὐθείας ἀγομένης· γίνεσθαι δὲ ταύτην κάθετον ἐπὶ τὴν κοινὴν πλευρὰν τῆς τε δευτέρας καὶ τῆς τρίτης σφραγῖδος, ὥστε κατ’ αὐτὸν συνίστασθαι τρίγωνον ὀρθογώνιον ὀρθὴν ἔχον τὴν πρὸς τοῖς ὅροις τῆς Καρμανίας, καὶ τὴν ὑποτείνουσαν εἶναι ἐλάττω μιᾶς τῶν περὶ τὴν ὀρθὴν ἐχουσῶν· δεῖν οὖν τὴν Περσίδα τῆς δευτέρας ποιεῖν σφραγῖδος. πρὸς ταῦτα δ’ εἴρηται ὅτι οὔθ’ ἡ ἐκ Βαβυλῶνος εἰς τὴν Καρμανίαν ἐπὶ παραλλήλου λαμβάνεται, οὔθ’ ἡ διορίζουσα εὐθεῖα τὰς σφραγῖδας μεσημβρινὴ εἴρηται· ὥστ’ οὐδὲν εἴρηται πρὸς αὐτόν. οὐδὲ τὸ ἐπιφερόμενον [εὖ]· εἰρηκότος γὰρ ἀπὸ Κασπίων πυλῶν εἰς μὲν Βαβυλῶνα τοὺς λεχθέντας, εἰς δὲ Σοῦσα σταδίους εἶναι τετρακισχιλίους ἐνακοσίους, ἀπὸ δὲ Βαβυλῶνος τρισχιλίους τετρακοσίους, πάλιν ἀπὸ τῶν αὐτῶν ὁρμηθεὶς ὑποθέσεων ἀμβλυγώνιον τρίγωνον συνίστασθαί φησι πρός τε ταῖς Κασπίοις πύλαις καὶ Σούσοις καὶ Βαβυλῶνι, τὴν ἀμβλεῖαν γωνίαν ἔχον πρὸς Σούσοις, τὰ δὲ τῶν πλευρῶν μήκη τὰ ἐκκείμενα· εἶτ’ ἐπιλογίζεται, διότι συμβήσεται κατὰ τὰς ὑποθέσεις ταύτας τὴν διὰ Κασπίων πυλῶν μεσημβρινὴν γραμμὴν ἐπὶ τοῦ διὰ Βαβυλῶνος καὶ Σούσων παραλλήλου δυσμικωτέραν ἔχειν τὴν κοινὴν τομὴν τῆς κοινῆς τομῆς τοῦ αὐτοῦ παραλλήλου καὶ τῆς ἀπὸ Κασπίων πυλῶν καθηκούσης εὐθείας ἐπὶ τοὺς ὅρους τοὺς τῆς Καρμανίας καὶ τῆς Περσίδος πλείοσι τῶν τετρακισχιλίων καὶ τετρακοσίων· σχεδὸν δή τι πρὸς τὴν διὰ Κασπίων πυλῶν μεσημβρινὴν γραμμὴν ἡμίσειαν ὀρθῆς ποιεῖν γωνίαν τὴν διὰ Κασπίων πυλῶν καὶ τῶν ὅρων τῆς τε Καρμανίας καὶ τῆς Περσίδος, καὶ νεύειν αὐτὴν ἐπὶ τὰ μέσα τῆς τε μεσημβρίας καὶ τῆς ἰσημερινῆς ἀνατολῆς· ταύτῃ δ’ εἶναι παράλληλον τὸν Ἰνδὸν ποταμόν, ὥστε καὶ τοῦτον ἀπὸ τῶν ὀρῶν οὐκ ἐπὶ μεσημβρίαν ῥεῖν, ὥς φησιν Ἐρατοσθένης, ἀλλὰ μεταξὺ ταύτης καὶ τῆς ἰσημερινῆς ἀνατολῆς, καθάπερ ἐν τοῖς ἀρχαίοις πίναξι καταγέγραπται. τίς οὖν συγχωρήσει τὸ νῦν συσταθὲν τρίγωνον ἀμβλυγώνιον εἶναι, μὴ συγχωρῶν ὀρθογώνιον εἶναι τὸ περιέχον αὐτό; τίς δ’ ἐπὶ παραλλήλου κειμένην τὴν ἀπὸ Βαβυλῶνος εἰς Σοῦσα μίαν τῶν τὴν ἀμβλεῖαν περιεχουσῶν, τὴν ὅλην μὴ συγχωρῶν τὴν μέχρι Καρμανίας; τίς δὲ τῷ Ἰνδῷ παράλληλον τὴν ἀπὸ Κασπίων πυλῶν ἐπὶ τοὺς ὅρους τῆς Καρμανίας; ὧν χωρὶς κενὸς ἂν εἴη ὁ συλλογισμός. χωρὶς δὲ τούτων κἀκεῖνος εἴρηκεν, ὅτι ῥομβοειδές ἐστι τὸ σχῆμα τῆς Ἰνδικῆς· καὶ καθάπερ ἡ ἑωθινὴ πλευρὰ παρέσπασται πολὺ πρὸς ἕω, καὶ μάλιστα τῷ ἐσχάτῳ ἀκρωτηρίῳ, ὃ καὶ πρὸς μεσημβρίαν προπίπτει πλέον παρὰ τὴν ἄλλην ᾐόνα, οὕτω καὶ ἡ παρὰ τὸν Ἰνδὸν πλευρά. πάντα δὲ ταῦτα λέγει γεωμετρικῶς ἐλέγχων, οὐ πιθανῶς.", "st": "2.1.34"}, {"sp": "N", "t": "ταῦτα δὲ καὶ αὐτὸς ἑαυτῷ ἐπενέγκας ἀπολύεται φήσας, εἰ μὲν παρὰ μικρὰ διαστήματα ὑπῆρχεν ὁ ἔλεγχος, συγγνῶναι ἂν ἦν· ἐπειδὴ δὲ παρὰ χιλιάδας σταδίων φαίνεται διαπίπτων, οὐκ εἶναι συγγνωστά· καίτοι ἐκεῖνόν γε καὶ παρὰ τετρακοσίους σταδίους αἰσθητὰ ἀποφαίνεσθαι τὰ παραλλάγματα, ὡς ἐπὶ τοῦ δι’ Ἀθηνῶν παραλλήλου καὶ τοῦ διὰ Ῥόδου. ἔστι δὲ τὸ πρὸς αἴσθησιν οὐχ ἁπλοῦν, ἀλλὰ τὸ μὲν ἐν πλάτει μείζονι τὸ δ’ ἐν ἐλάττονι· μείζονι μέν, ἂν αὐτῷ τῷ ὀφθαλμῷ πιστεύωμεν ἢ καρποῖς ἢ κράσεσιν ἀέρων πρὸς τὴν τῶν κλιμάτων κρίσιν, ἐλάττονι δ’, ἂν δι’ ὀργάνων γνωμονικῶν ἢ διοπτρικῶν. ὁ μὲν οὖν δι’ Ἀθηνῶν παράλληλος γνωμονικῶς ληφθεὶς καὶ ὁ διὰ Ῥόδου καὶ Καρίας, εἰκότως ἐν σταδίοις τοσούτοις αἰσθητὴν ἐποίησε τὴν διαφοράν. ὁ δ’ ἐν πλάτει μὲν τρισχιλίων σταδίων, μήκει δὲ καὶ τετρακισμυρίων ὄρους, πελάγους δὲ τρισμυρίων λαμβάνων τὴν ἀπὸ δύσεως ἐπ’ ἰσημερινὰς ἀνατολὰς γραμμήν, καὶ τὰ ἐφ’ ἑκάτερον τὸ μέρος τὰ μὲν νότια ὀνομάζων τὰ δὲ βόρεια, καὶ ταῦτα πλινθία καλῶν καὶ σφραγῖδας, νοείσθω πῶς καὶ ταῦτα λέγει καὶ πλευρὰ τὰ μὲν ἀρκτικὰ τὰ δὲ νότια, καὶ πῶς τὰ μὲν ἑσπέρια τὰ δὲ ἑωθινά· καὶ τὸ μὲν παρὰ πολὺ διαμαρτανόμενον παρορῶν ὑπεχέτω λόγον (δίκαιον γάρ), τὸ δὲ παρὰ μικρὸν οὐδὲ παριδὼν ἐλεγκτέος ἐστίν. ἐνταῦθα δ’ οὐδετέρως αὐτῷ προσάγεταί τις ἔλεγχος· οὔτε γὰρ τῶν ἐν τοσούτῳ πλάτει γεωμετρική τις δύναιτ’ ἂν [εἶναι] ἀπόδειξις, οὔτ’ ἐν οἷς ἐπιχειρεῖ γεωμετρεῖν ὁμολογουμένοις χρῆται λήμμασιν, ἀλλ’ ἑαυτῷ πλάσας.", "st": "2.1.35"}, {"sp": "N", "t": "βέλτιον δὲ περὶ τῆς τετάρτης λέγει μερίδος, προστίθησι δὲ καὶ [τὸ] τοῦ φιλαιτίου καὶ τοῦ μένοντος ἐπὶ τῶν αὐτῶν ὑποθέσεων ἢ τῶν παραπλησίων. τοῦτο μὲν γὰρ ὀρθῶς ἐπιτιμᾷ διότι μῆκος ὀνομάζει τῆς μερίδος ταύτης τὴν ἀπὸ Θαψάκου μέχρι Αἰγύπτου γραμμήν, ὥσπερ εἴ τις παραλληλογράμμου τὴν διάμετρον μῆκος αὐτοῦ φαίη· οὐ γὰρ ἐπὶ τοῦ αὐτοῦ παραλλήλου κεῖται ἥ τε Θάψακος καὶ ἡ τῆς Αἰγύπτου παραλία, ἀλλ’ ἐπὶ διεστώτων πολὺ ἀλλήλων, ἐν δὲ τῷ μεταξὺ διαγώνιός πως ἄγεται καὶ λοξὴ ἡ ἀπὸ Θαψάκου εἰς Αἴγυπτον. τὸ δὲ θαυμάζειν, πῶς ἐθάρρησεν εἰπεῖν ἑξακισχιλίων σταδίων τὸ ἀπὸ Πηλουσίου εἰς Θάψακον, πλειόνων ὄντων ἢ ὀκτακισχιλίων, οὐκ ὀρθῶς. λαβὼν γὰρ δι’ ἀποδείξεως μέν, ὅτι ὁ διὰ Πηλουσίου παράλληλος τοῦ διὰ Βαβυλῶνος πλείοσιν ἢ δισχιλίοις καὶ πεντακοσίοις σταδίοις νοτιώτερός ἐστι, κατ’ Ἐρατοσθένη δὲ (ὡς οἴεται), διότι τοῦ διὰ Βαβυλῶνος ὁ διὰ τῆς Θαψάκου ἀρκτικώτερος τετρακισχιλίοις ὀκτακοσίοις, συμπίπτειν φησὶ πλείους τῶν ὀκτακισχιλίων. πῶς οὖν κατ’ Ἐρατοσθένη δείκνυται ἡ τοσαύτη ἀπόστασις τοῦ διὰ Βαβυλῶνος παραλλήλου ἀπὸ τοῦ διὰ Θαψάκου, ζητῶ. ὅτι μὲν γὰρ ἀπὸ Θαψάκου ἐπὶ Βαβυλῶνα τοσοῦτόν ἐστιν, εἴρηκεν ἐκεῖνος· ὅτι δὲ καὶ ἀπὸ τοῦ δι’ ἑκατέρου παραλλήλου ἐπὶ τὸν διὰ θατέρου, οὐκ εἴρηκεν· οὐδὲ γάρ, ὅτι ἐπὶ ταὐτοῦ μεσημβρινοῦ ἐστιν ἡ Θάψακος καὶ ἡ Βαβυλών. τἀναντία γὰρ αὐτὸς ὁ Ἵππαρχος ἔδειξε κατ’ Ἐρατοσθένη πλείοσιν ἢ χιλίοις σταδίοις συμβαίνειν ἀνατολικωτέραν εἶναι τὴν Βαβυλῶνα τῆς Θαψάκου. ἡμεῖς τε παρετίθεμεν τὰς Ἐρατοσθένους ἀποφάσεις, ἐν αἷς τὸν Τίγριν καὶ τὸν Εὐφράτην ἐγκυκλοῦσθαι τήν τε Μεσοποταμίαν καὶ τὴν Βαβυλωνίαν, καὶ τὸ πλέον γε τῆς ἐγκυκλώσεως τὸν Εὐφράτην ποιεῖν· ἀπὸ γὰρ τῶν ἄρκτων ἐπὶ μεσημβρίαν ῥυέντα ἐπιστρέφειν πρὸς τὰς ἀνατολάς, ἐκπίπτειν δὲ ἐπὶ μεσημβρίαν. ἡ μὲν οὖν ἐπὶ μεσημβρίαν ἀπὸ τῶν ἄρκτων ὁδὸς ὡς ἂν μεσημβρινοῦ τινός ἐστιν, ἡ δ’ ἐπὶ τὰς ἀνατολὰς ἐπιστροφὴ καὶ ἐπὶ τὴν Βαβυλῶνα ἔκνευσίς τέ ἐστιν ἀπὸ τοῦ μεσημβρινοῦ καὶ οὐκ ἐπ’ εὐθείας διὰ τὴν ῥηθεῖσαν ἐγκύκλωσιν. τὴν δέ γε ὁδὸν εἴρηκε τετρακισχιλίων καὶ ὀκτακοσίων σταδίων τὴν ἐπὶ Βαβυλῶνα ἀπὸ Θαψάκου παρὰ τὸν Εὐφράτην προσθείς, καθάπερ ἐπίτηδες, τοῦ μή τινα εὐθεῖαν αὐτὴν δέξασθαι καὶ μέτρον τοῦ μεταξὺ δυεῖν παραλλήλων διαστήματος. μὴ διδομένου δὲ τούτου, κενόν ἐστι καὶ τὸ ἐφεξῆς δείκνυσθαι δοκοῦν, ὅτι συνισταμένου ὀρθογωνίου τριγώνου πρός τε Πηλουσίῳ καὶ Θαψάκῳ καὶ τῇ τομῇ τοῦ τε διὰ Πηλουσίου παραλλήλου καὶ τοῦ διὰ Θαψάκου μεσημβρινοῦ, μία τῶν περὶ τὴν ὀρθήν, ἡ ἐπὶ τοῦ μεσημβρινοῦ, μείζων ἔσται τῆς ὑπὸ τὴν ὀρθήν, τῆς ἀπὸ Θαψάκου εἰς Πηλούσιον. κενὸν δὲ καὶ τὸ συνάπτον τούτῳ, ἀπὸ μὴ συγχωρουμένου λήμματος κατασκευαζόμενον. οὐ γὰρ δὴ δίδοται τὸ ἀπὸ Βαβυλῶνος ἐπὶ τὸν διὰ Κασπίων πυλῶν μεσημβρινὸν εἶναι διάστημα τετρακισχιλίων ὀκτακοσίων. ἐλήλεγκται γὰρ ὑφ’ ἡμῶν ἐκ τῶν μὴ συγχωρουμένων ὑπ’ Ἐρατοσθένους κατεσκευακότα τοῦτο τὸν Ἵππαρχον· ἵνα δ’ ἀνίσχυρον ᾖ τὸ ὑπὸ ἐκείνου διδόμενον, λαβὼν τὸ εἶναι πλείους ἢ ἐννακισχιλίους ἐκ Βαβυλῶνος ἐπὶ τὴν ἐκ Κασπίων πυλῶν οὕτως ἀγομένην γραμμήν, ὡς ἐκεῖνος εἴρηκεν, ἐπὶ τοὺς ὅρους τῆς Καρμανίας, ἐδείκνυε τὸ αὐτό.", "st": "2.1.36"}, {"sp": "N", "t": "οὐ τοῦτο οὖν λεκτέον πρὸς τὸν Ἐρατοσθένη, ἀλλ’ ὅτι τῶν ἐν πλάτει λεγομένων καὶ μεγεθῶν καὶ σχημάτων εἶναί τι δεῖ μέτρον καὶ ὅπου μὲν μᾶλλον ὅπου δὲ ἔλαττον, συγχωρητέον. ληφθέντος γὰρ τοῦ τῶν ὀρῶν πλάτους τῶν ἐπὶ τὰς ἰσημερινὰς ἀνατολὰς ἐκτεινομένων τρισχιλίων σταδίων, ὁμοίως δὲ καὶ τοῦ τῆς θαλάττης τῆς μέχρι στηλῶν, μᾶλλον ἄν τις συγχωρήσειεν ὡς ἐπὶ μιᾶς γραμμῆς ἐξετάζεσθαι τὰς παραλλήλους ἐκείνης ἐν τῷ αὐτῷ πλάτει ἀγομένας ἢ τὰς συμπιπτούσας, καὶ τῶν συμπιπτουσῶν τὰς ἐν αὐτῷ ἐκείνῳ τῷ πλάτει τὴν σύμπτωσιν ἐχούσας ἢ τὰς ἐκτός· ὡσαύτως καὶ τὰς διισταμένας μέχρι τοῦ μὴ ἐκβαίνειν τοῦ πλάτους ἢ τὰς ἐκβαινούσας, καὶ τὰς ἐν μείζονι μήκει μᾶλλον ἢ τὰς ἐν ἐλάττονι. καὶ γὰρ ἡ ἀνισότης τῶν μηκῶν συγκρύπτοιτ’ ἂν μᾶλλον καὶ ἡ ἀνομοιότης τῶν σχημάτων· οἷον ἐν τῷ πλάτει τοῦ Ταύρου παντὸς καὶ τῆς μέχρι στηλῶν θαλάττης, ὑποκειμένων τρισχιλίων σταδίων, νοεῖται ἕν τι παραλληλόγραμμον χωρίον, τὸ περιγράφον τό τε ὄρος ἅπαν καὶ τὴν λεχθεῖσαν θάλατταν. ἐὰν οὖν διέλῃς εἰς πλείω παραλληλόγραμμα τὸ μῆκος, καὶ τὴν διάμετρον ὅλου τε τούτου λάβῃς καὶ τῶν μερῶν, ῥᾷον ἂν ἡ τοῦ ὅλου διάμετρος ἡ αὐτὴ λογισθείη τῇ κατὰ τὸ μῆκος πλευρᾷ ἤπερ ἡ ἐν τοῖς μέρεσι· καὶ ὅσῳ γ’ ἂν ἔλαττον ᾖ τὸ παραλληλόγραμμον τὸ ληφθὲν ἐν μέρει, τοσῷδε μᾶλλον τοῦτ’ ἂν συμβαίνοι. ἥ τε γὰρ λοξότης τῆς διαμέτρου ἧττον ἀπελέγχεται καὶ ἡ ἀνισότης τοῦ μήκους ἐν τοῖς μεγάλοις, ὥστ’ οὐδ’ ἂν ὀκνήσειας ἐπ’ αὐτῶν τὴν διάμετρον εἰπεῖν μῆκος τοῦ σχήματος. ἐὰν οὖν τὴν διάμετρον λοξώσῃς μᾶλλον, ὥστε ἐκπεσεῖν ἔξω τῶν πλευρῶν ἑκατέρας ἢ τῆς γε ἑτέρας, οὐκ ἂν ὁμοίως ἔτι ταῦτα συμβαίνοι· τοιοῦτον δή τι λέγω τὸ μέτρον τῶν ἐν πλάτει λεγομένων. ὁ δ’ ἀπὸ τῶν Κασπίων πυλῶν τὴν μὲν δι’ αὐτῶν τῶν ὀρῶν λαμβάνων ὡς ἂν ἐπὶ ταὐτοῦ παραλλήλου μέχρι στηλῶν ἀγομένην, τὴν δ’ ἀπονεύουσαν εἰς Θάψακον εὐθὺς ἔξω πολὺ τῶν ὀρῶν, καὶ πάλιν ἐκ Θαψάκου προσεκβάλλων ἄλλην μέχρι Αἰγύπτου τοσοῦτον ἐπιλαμβάνουσαν πλάτος, εἶτα τῷ μήκει τῷ ταύτης καταμετρῶν τὸ τοῦ χωρίου μῆκος, διαμέτρῳ τετραγώνου καταμετρεῖν ἂν δόξειε τὸ τοῦ τετραγώνου μῆκος. ὅταν δὲ μηδὲ διάμετρος ᾖ ἀλλὰ κεκλασμένη ἡ γραμμή, πολὺ μᾶλλον ἂν δόξειε πλημμελεῖν· κεκλασμένη γάρ ἐστιν ἡ ἀπὸ Κασπίων πυλῶν διὰ Θαψάκου πρὸς τὸν Νεῖλον ἀγομένη. πρὸς μὲν Ἐρατοσθένη ταῦτα.", "st": "2.1.37"}, {"sp": "N", "t": "πρὸς δὲ τὸν Ἵππαρχον κἀκεῖνο, ὅτι ἐχρῆν, ὡς κατηγορίαν πεποίηται τῶν ὑπ’ ἐκείνου λεχθέντων, οὕτω καὶ ἐπανόρθωσίν τινα ποιήσασθαι τῶν ἡμαρτημένων· ὅπερ ἡμεῖς ποιοῦμεν. ἐκεῖνος δ’ εἰ καί που τούτου πεφρόντικε, κελεύει ἡμᾶς τοῖς ἀρχαίοις πίναξι προσέχειν, δεομένοις παμπόλλῳ τινὶ μείζονος ἐπανορθώσεως ἢ ὁ Ἐρατοσθένους πίναξ προσδεῖται. καὶ τὸ ἐπιφερόμενον δ’ ἐπιχείρημα τῆς αὐτῆς ἔχεται μοχθηρίας. λαμβάνει γὰρ ἐν λήμματι τὸ ἐκ τῶν μὴ διδομένων κατασκευασθέν, ὡς ἠλέγξαμεν ἡμεῖς, ὅτι Θαψάκου Βαβυλὼν ἀνατολικωτέρα ἐστὶν οὐ πλείοσιν ἢ χιλίοις σταδίοις· ὥστ’ εἰ καὶ πάνυ συνάγεται τὸ πλείοσιν ἢ δισχιλίοις καὶ τετρακοσίοις σταδίοις ἀνατολικωτέραν αὐτὴν εἶναι ἐκ τῶν λεγομένων ὑπὸ τοῦ Ἐρατοσθένους, ὅτι ἐπὶ τὴν τοῦ Τίγριδος διάβασιν, ᾗ Ἀλέξανδρος διέβη, ἀπὸ Θαψάκου ἐστὶ σύντομος σταδίων δισχιλίων τετρακοσίων, ὁ δὲ Τίγρις καὶ ὁ Εὐφράτης ἐγκυκλωσάμενοι τὴν Μεσοποταμίαν, τέως μὲν ἐπ’ ἀνατολὰς φέρονται, εἶτ’ ἐπιστρέφουσι πρὸς νότον καὶ πλησιάζουσι τότε ἀλλήλοις τε ἅμα καὶ Βαβυλῶνι, οὐδὲν ἄτοπον συμβαίνει τῷ λόγῳ.", "st": "2.1.38"}, {"sp": "N", "t": "πλημμελεῖ δὲ καὶ ἐν τῷ ἑξῆς ἐπιχειρήματι, ἐν ᾧ συνάγειν βούλεται, ὅτι τὴν ἀπὸ Θαψάκου ἐπὶ Κασπίους πύλας ὁδόν, ἣν μυρίων σταδίων Ἐρατοσθένης εἴρηκεν, οὐκ ἐπ’ εὐθείας ἀναμεμετρημένην ὡς ἐπ’ εὐθείας παραδίδωσι, τῆς εὐθείας πολὺ ἐλάττονος οὔσης. ἡ δ’ ἔφοδός ἐστιν αὐτῷ τοιαύτη. φησὶν εἶναι κατ’ Ἐρατοσθένη τὸν αὐτὸν μεσημβρινὸν τόν τε διὰ τοῦ Κανωβικοῦ στόματος καὶ τὸν διὰ Κυανέων, διέχειν δὲ τοῦτον τοῦ διὰ Θαψάκου ἑξακισχιλίους τριακοσίους σταδίους, τὰς δὲ Κυανέας τοῦ Κασπίου ὄρους ἑξακισχιλίους ἑξακοσίους, ὃ κεῖται κατὰ τὴν ὑπέρθεσιν τὴν ἐπὶ τὸ Κάσπιον πέλαγος ἐκ Κολχίδος, ὥστε παρὰ τριακοσίους σταδίους τὸ ἴσον εἶναι διάστημα ἀπὸ τοῦ διὰ Κυανέων μεσημβρινοῦ ἐπί τε Θάψακον καὶ ἐπὶ τὸ Κάσπιον· τρόπον δή τινα ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ κεῖσθαι τήν τε Θάψακον καὶ τὸ Κάσπιον· τούτῳ δ’ ἀκολουθεῖν τὸ ἀφεστάναι ἴσον τὰς Κασπίους πύλας Θαψάκου τε καὶ τοῦ Κασπίου, [τοῦ δὲ Κασπίου] πολὺ ἐλάττους ἀφεστάναι τῶν μυρίων, ὅσους φησὶν ἀφεστάναι Ἐρατοσθένης τῆς Θαψάκου, [τῆς Θαψάκου] ἄρα πολὺ ἐλάττους ἢ μυρίους ἀφεστάναι τοὺς ἐπ’ εὐθείας. κυκλοπορίαν ἄρα εἶναι τοὺς μυρίους, [οὓς] λογίζεται ἐκεῖνος ἐπ’ εὐθείας ἀπὸ Κασπίων πυλῶν εἰς Θάψακον. ἐροῦμεν δὲ πρὸς αὐτόν, ὅτι τοῦ Ἐρατοσθένους ἐν πλάτει λαμβάνοντος [τὰς] εὐθείας, ὅπερ οἰκεῖόν ἐστι γεωγραφίας, ἐν πλάτει δὲ καὶ τὰς μεσημβρινὰς καὶ τὰς ἐπὶ ἰσημερινὴν ἀνατολήν, ἐκεῖνος γεωμετρικῶς αὐτὸν εὐθύνει καὶ ὡς ἂν δι’ ὀργάνων λάβοι τις τούτων ἕκαστον, οὐδὲ αὐτὸς δι’ ὀργάνων ἀλλὰ μᾶλλον στοχασμῷ λαμβάνων καὶ τὸ πρὸς ὀρθὰς καὶ τὸ παραλλήλους. ἓν μὲν δὴ τοῦθ’ ἁμάρτημα· ἕτερον δὲ τὸ μηδὲ τὰ κείμενα παρ’ ἐκείνῳ διαστήματα τίθεσθαι ὑπ’ αὐτοῦ, μηδὲ πρὸς ἐκεῖνα τὸν ἔλεγχον προσάγεσθαι, ἀλλὰ πρὸς τὰ ὑπ’ αὐτοῦ πλαττόμενα. διόπερ πρῶτον μὲν ἐκείνου τὸ ἀπὸ τοῦ στόματος ἐπὶ Φᾶσιν εἰπόντος σταδίων ὀκτακισχιλίων, καὶ προσθέντος τοὺς εἰς Διοσκουριάδα ἐνθένδε ἑξακοσίους, τὴν δ’ ἀπὸ Διοσκουριάδος εἰς τὸ Κάσπιον ὑπέρθεσιν ἡμερῶν πέντε, ἥτις κατ’ αὐτὸν Ἵππαρχον εἰκάζεται λέγεσθαι ὅσον χιλίων σταδίων, ὥστε τὴν σύμπασαν κατ’ Ἐρατοσθένη κεφαλαιοῦσθαι ἐννακισχιλίων ἑξακοσίων· αὐτὸς συντέτμηκε καὶ φησὶν ἐκ μὲν Κυανέων εἰς Φᾶσιν πεντακισχιλίους ἑξακοσίους, εἰς δὲ Κάσπιον ἐνθένδε ἄλλους χιλίους· ὥστ’ οὐ κατ’ Ἐρατοσθένη συμβαίνοι ἂν ἐπὶ τοῦ αὐτοῦ πως μεσημβρινοῦ τό τε Κάσπιον εἶναι καὶ τὴν Θάψακον, ἀλλὰ κατ’ αὐτόν. φέρε δ’ οὖν κατ’ Ἐρατοσθένη· πῶς οὖν τούτῳ ἕπεται τὸ τὴν ἀπὸ τοῦ Κασπίου ἐπὶ Κασπίους πύλας ἴσην εἶναι τῇ ἀπὸ Θαψάκου ἐπὶ τὸ αὐτὸ σημεῖον;", "st": "2.1.39"}, {"sp": "N", "t": "Ἐν δὲ τῷ δευτέρῳ ὑπομνήματι ἀναλαβὼν πάλιν τὴν αὐτὴν ζήτησιν τὴν περὶ τῶν ὅρων τῶν κατὰ τὸν Ταῦρον, περὶ ὧν ἱκανῶς εἰρήκαμεν, μεταβαίνει πρὸς τὰ βόρεια μέρη τῆς οἰκουμένης· εἶτ’ ἐκτίθεται τὰ λεχθέντα ὑπὸ τοῦ Ἐρατοσθένους περὶ τῶν μετὰ τὸν Πόντον τόπων, ὅτι φησὶ τρεῖς ἄκρας ἀπὸ τῶν ἄρκτων καθήκειν· μίαν μὲν ἐφ’ ἧς ἡ Πελοπόννησος, δευτέραν δὲ τὴν Ἰταλικήν, τρίτην δὲ τὴν Λιγυστικήν, ὑφ’ ὧν κόλπους ἀπολαμβάνεσθαι τόν τε Ἀδριατικὸν καὶ τὸν Τυρρηνικόν. ταῦτα δ’ ἐκθέμενος καθόλου πειρᾶται τὰ καθ’ ἕκαστα περὶ αὐτῶν λεγόμενα ἐλέγχειν γεωμετρικῶς μᾶλλον ἢ γεωγραφικῶς. ἔστι δὲ τοσοῦτον τῶν ἁμαρτανομένων ἐν αὐτοῖς ὑπὸ τοῦ Ἐρατοσθένους τὸ πλῆθος, καὶ ὑπὸ Τιμοσθένους τοῦ τοὺς λιμένας συγγράψαντος (ὃν ἐπαινεῖ μὲν ἐκεῖνος μάλιστα τῶν ἄλλων, διαφωνῶν δ’ ἐλέγχεται πρὸς αὐτὸν πλεῖστα), ὥστ’ οὐκ ἄξιον ἡγοῦμαι διαιτᾶν οὔτ’ ἐκείνους ἐπὶ τοσοῦτον διαμαρτάνοντας τῶν ὄντων, οὔτε τὸν Ἵππαρχον. καὶ γὰρ οὗτος τὰ μὲν παραλείπει τῶν ἡμαρτημένων τὰ δ’ οὐκ ἐπανορθοῖ, ἀλλ’ ἐλέγχει μόνον ὅτι ψευδῶς ἢ μαχομένως εἴρηται. αἰτιάσαιτο μὲν γὰρ καὶ τοῦτ’ ἂν ἴσως τις, ὅτι φησὶν ἄκρας τρεῖς τῆς Εὐρώπης, μίαν μὲν τιθεὶς τὴν ἐφ’ ἧς ἡ Πελοπόννησος· ἔχει γάρ τι πολυσχιδές· καὶ γὰρ τὸ Σούνιον ἀκρωτηριάζει ὁμοίως τῇ Λακωνικῇ, οὐ πολὺ ἧττον μεσημβρινώτερον ὂν τῶν Μαλεῶν καὶ κόλπον ἀπολαμβάνον ἀξιόλογον. καὶ ἡ Θρᾳκία Χερρόνησος ἀπολαμβάνει πρὸς τὸ Σούνιον τόν τε Μέλανα κόλπον καὶ τοὺς ἐφεξῆς τοὺς Μακεδονικούς. εἰ δ’ οὖν παρείημεν τοῦτο, καὶ τῶν διαστημάτων τὰ πλεῖστα φανερῶς ψευδογραφούμενα ἐλέγχει τὴν ἀπειρίαν τῶν τόπων ὑπερβάλλουσαν καὶ οὐ δεομένην γεωμετρικῶν ἐλέγχων, ἀλλὰ φανερῶν καὶ αὐτόθεν ἐκμαρτυρεῖσθαι δυναμένων· οἷον ὅτι ἐξ Ἐπιδάμνου πρὸς τὸν Θερμαῖον κόλπον ἡ ὑπέρβασίς ἐστι πλειόνων ἢ δισχιλίων σταδίων· ὁ δ’ ἐνακοσίων φησίν· ἐκ δὲ Ἀλεξανδρείας εἰς Καρχηδόνα ὑπὲρ μυρίους καὶ τρισχιλίους, οὐ πλείους ὄντας τῶν ἐννακισχιλίων, εἴπερ ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ ἐστι κατὰ τοῦτον τῇ μὲν Ἀλεξανδρείᾳ Καρία καὶ Ῥόδος, τῇ δὲ Καρχηδόνι ὁ πορθμός. πάντες γὰρ ὁμολογοῦσι μὴ πλειόνων εἶναι τὸν ἐκ Καρίας ἐπὶ πορθμὸν πλοῦν σταδίων ἢ ἐνακισχιλίων· ὅ τε μεσημβρινὸς ἐν μεγάλῳ μέν τινι διαστήματι λαμβανόμενος δοθείη ἂν ὁ αὐτὸς εἶναι τοσοῦτον δυσμικώτερος πρὸς τὸν ἑωθινώτερον ὅσον ἡ Καρχηδών ἐστι τοῦ πορθμοῦ πρὸς δύσει μᾶλλον, ἐν δὲ τετρακισχιλίοις σταδίοις ἔχει καταφανῆ τὸν ἔλεγχον. ὁ δὲ καὶ τὴν Ῥώμην τιθεὶς ἐπὶ ταὐτοῦ μεσημβρινοῦ τὴν τοσοῦτον καὶ Καρχηδόνος δυσμικωτέραν, ὑπερβολὴν οὐκ ἀπολείπει τῆς τῶν τόπων ἀπειρίας καὶ τούτων καὶ τῶν ἐφεξῆς πρὸς δύσιν μέχρι στηλῶν.", "st": "2.1.40"}, {"sp": "N", "t": "̔ιππάρχῳ μὲν οὖν μὴ γεωγραφοῦντι ἀλλ’ ἐξετάζοντι τὰ λεχθέντα ἐν τῇ γεωγραφίᾳ τῇ Ἐρατοσθένους οἰκεῖον ἦν ἐπὶ πλέον τὰ καθ’ ἕκαστα εὐθύνειν. ἡμεῖς δ’ ἐν οἷς μὲν κατορθοῖ, τὸ πλέον δ’ ἔτι ὅπου καὶ πλημμελεῖ, τὸν καθ’ ἕκαστα οἰκεῖον λόγον ᾠήθημεν δεῖν προσάγειν, τὰ μὲν ἐπανορθοῦντες, ὑπὲρ ὧν δ’ ἀπολυόμενοι τὰς ἐπιφερομένας αἰτίας ὑπὸ τοῦ Ἱππάρχου, καὶ αὐτὸν τὸν Ἵππαρχον συνεξετάζομεν, ὅπου τι φιλαιτίως εἴρηκεν. ἐν δὲ τούτοις ὁρῶντες ἤδη τὸν μὲν τελέως παραπαίοντα, τὸν δὲ δικαίως ἐπικαλοῦντα, ἀρκεῖν ὑπολαμβάνομεν, ἂν ἐν αὐτῇ τῇ γεωγραφίᾳ τὰ ὄντα λέγοντες ἐπανορθῶμεν αὐτόν. ἐφ’ ὧν γὰρ συνεχῆ καὶ ἐπιπολάζοντά ἐστι τὰ ἁμαρτανόμενα, κρεῖττον μηδὲ μεμνῆσθαι πλὴν εἰ σπάνιόν τι καὶ καθόλου, ὅπερ πειρασόμεθα ποιεῖν ἐν τοῖς καθ’ ἕκαστα. καὶ νῦν δ’ εἰρήσθω ὅτι καὶ Τιμοσθένης καὶ Ἐρατοσθένης καὶ οἱ ἔτι τούτων πρότεροι τελέως ἠγνόουν τά τε Ἰβηρικὰ καὶ τὰ Κελτικά, μυρίῳ δὲ μᾶλλον τὰ Γερμανικὰ καὶ τὰ Βρεττανικά, ὡς δ’ αὕτως τὰ τῶν Γετῶν καὶ Βασταρνῶν. ἐπὶ πολὺ δ’ ἀγνοίας ἐτύγχανον ἀφιγμένοι καὶ τῶν κατ’ Ἰταλίαν καὶ τὸν Ἀδρίαν καὶ τὸν Πόντον καὶ τῶν ἐφεξῆς προσαρκτίων μερῶν· εἰ καὶ τὰ τοιαῦτα ἴσως φιλαίτια. τοῦ γὰρ Ἐρατοσθένους ἐπὶ τῶν πόρρω διεστηκότων τὰ παραδεδομένα φάσκοντος ἐρεῖν διαστήματα, μὴ διισχυριζομένου δὲ καὶ λέγοντος ὡς παρέλαβε, προστιθέντος δ’ ἔστιν ὅπου τὰ ἐπ’ εὐθείας μᾶλλον καὶ ἧττον, οὐ δεῖ προσάγειν τὸν ἀκριβῆ ἔλεγχον τοῖς μὴ ὁμολογουμένοις πρὸς ἄλληλα διαστήμασιν· ὅπερ ποιεῖν πειρᾶται ὁ Ἵππαρχος ἔν τε τοῖς πρότερον λεχθεῖσι καὶ ἐν οἷς τὰ περὶ τὴν Ὑρκανίαν μέχρι Βακτρίων καὶ τῶν ἐπέκεινα ἐθνῶν ἐκτίθεται διαστήματα, καὶ ἔτι τὰ ἀπὸ Κολχίδος ἐπὶ τὴν Ὑρκανίαν θάλατταν. οὐ γὰρ ὁμοίως ἐπί τε τούτων ἐξεταστέον αὐτὸν καὶ ἐπὶ τῶν κατὰ τὴν ἠπειρῶτιν παραλίαν καὶ τοὺς ἄλλους τοὺς οὕτω γνωρίμους τόπους· ἀλλ’ οὐδ’ ἐπὶ τούτων γεωμετρικῶς, ὅπερ ἔφην, ἀλλὰ γεωγραφικῶς μᾶλλον. αἰτιασάμενος δ’ οὖν τινα τῶν Αἰθιοπικῶν ἐπὶ τέλει τοῦ δευτέρου ὑπομνήματος τῶν πρὸς τὴν Ἐρατοσθένους γεωγραφίαν πεποιημένων, ἐν τῷ τρίτῳ φησὶ τὴν μὲν πλείω θεωρίαν ἔσεσθαι μαθηματικήν, ἐπὶ ποσὸν δὲ καὶ γεωγραφικήν· οὐδ’ ἐπὶ ποσὸν μέντοι δοκεῖ μοι ποιήσασθαι γεωγραφικήν, ἀλλὰ πᾶσαν μαθηματικήν, διδόντος καὶ τοῦ Ἐρατοσθένους τὴν τοιαύτην πρόφασιν. πολλαχοῦ γὰρ ἐκπίπτει πρὸς τὸ ἐπιστημονικώτερον τῆς προκειμένης ἱστορίας, ἐκπεσὼν δὲ οὐκ ἀκριβεῖς ἀλλ’ ὁλοσχερεῖς ποιεῖται τὰς ἀποφάσεις, τρόπον τινὰ ἐν μὲν τοῖς γεωγραφικοῖς μαθηματικὸς ἐν δὲ τοῖς μαθηματικοῖς γεωγραφικὸς ὤν, ὥστε πρὸς ἄμφω δίδωσιν ἀφορμὰς τοῖς ἀντιλέγουσιν, ἐν δὲ τούτῳ τῷ ὑπομνήματι καὶ δικαίας καὶ οὗτος καὶ ὁ Τιμοσθένης, ὥστ’ οὐδ’ ἡμῖν καταλείπεται συνεπισκοπεῖν, ἀλλ’ ἀρκεῖσθαι τοῖς ὑπὸ τοῦ Ἱππάρχου λεχθεῖσιν.", "st": "2.1.41"}, {"sp": "N", "t": "ἴδωμεν δὲ καὶ Ποσειδώνιον ἅ φησιν ἐν τοῖς περὶ ὠκεανοῦ· δοκεῖ γὰρ ἐν αὐτοῖς τὰ πολλὰ γεωγραφεῖν, τὰ μὲν οἰκείως τὰ δὲ μαθηματικώτερον. οὐκ ἄτοπον οὖν ἔνια καὶ τῶν ὑπὸ τούτου λεγομένων διαιτῆσαι, τὰ μὲν νῦν τὰ δ’ ἐν τοῖς καθ’ ἕκαστα ὡς ἂν ὑποπίπτῃ, μέτρου τινὸς ἐχομένους. ἔστιν οὖν τι τῶν πρὸς γεωγραφίαν οἰκείων τὸ τὴν γῆν ὅλην ὑποθέσθαι σφαιροειδῆ καθάπερ καὶ τὸν κόσμον, καὶ τὰ ἄλλα παραδέξασθαι τὰ ἀκόλουθα τῇ ὑποθέσει ταύτῃ· τούτων δ’ ἐστὶ καὶ τὸ πεντάζωνον αὐτὴν εἶναι.", "st": "2.2.1"}, {"sp": "N", "t": "φησὶ δὴ ὁ Ποσειδώνιος τῆς εἰς πέντε ζώνας διαιρέσεως ἀρχηγὸν γενέσθαι Παρμενίδην· ἀλλ’ ἐκεῖνον μὲν σχεδόν τι διπλασίαν ἀποφαίνειν τὸ πλάτος τὴν διακεκαυμένην ὑπερπίπτουσαν ἑκατέρων τῶν τροπικῶν εἰς τὸ ἐκτὸς καὶ πρὸς ταῖς εὐκράτοις· Ἀριστοτέλη δὲ αὐτὴν καλεῖν τὴν μεταξὺ τῶν τροπικῶν, τὰς δὲ μεταξὺ τῶν τροπικῶν καὶ τῶν ἀρκτικῶν εὐκράτους. ἀμφοτέροις δ’ ἐπιτιμᾷ δικαίως· διακεκαυμένην γὰρ λέγεσθαι τὸ ἀοίκητον διὰ καῦμα· τῆς δὲ μεταξὺ τῶν τροπικῶν πλέον ἢ τὸ ἥμισυ τοῦ πλάτους οὐκ οἰκήσιμόν ἐστιν ἐκ τῶν ὑπὲρ Αἰγύπτου στοχαζομένοις Αἰθιόπων, εἴπερ τὸ μὲν ἥμισυ τοῦ παντὸς πλάτους ἐστὶν ὃ διαιρεῖ ἐφ’ ἑκάτερα ὁ ἰσημερινός, τούτου δὲ τὸ μὲν ἀπὸ τῆς Συήνης, ἥπερ ἐστὶν ὅριον τοῦ θερινοῦ τροπικοῦ, εἰς Μερόην εἰσὶ πεντακισχίλιοι, τὸ δ’ ἐνθένδε ἕως [τοῦ] τῆς Κινναμωμοφόρου παραλλήλου, ὅσπερ ἐστὶν ἀρχὴ τῆς διακεκαυμένης, τρισχίλιοι. τοῦτο μὲν οὖν τὸ διάστημα πᾶν ἐστι μετρητόν, πλεῖταί τε γὰρ καὶ ὁδεύεται· τὸ δ’ ἑξῆς μέχρι τοῦ ἰσημερινοῦ λόγῳ δείκνυται κατὰ τὴν ὑπ’ Ἐρατοσθένους γενομένην ἀναμέτρησιν τῆς γῆς ὅτι ἐστὶ σταδίων ὀκτακισχιλίων ὀκτακοσίων· ὃν δὴ λόγον ἔχει τὰ μύρια ἑξακισχίλια ὀκτακόσια πρὸς τὰ ὀκτακισχίλια [ὀκτακόσια], τοῦτον ἂν ἔχοι τὸ μεταξὺ τῶν τροπικῶν διάστημα πρὸς τὸ τῆς διακεκαυμένης πλάτος. κἂν τῶν νεωτέρων δὲ ἀναμετρήσεων εἰσάγηται ἡ ἐλαχίστην ποιοῦσα τὴν γῆν, οἵαν ὁ Ποσειδώνιος ἐγκρίνει περὶ ὀκτωκαίδεκα μυριάδας οὖσαν, περὶ ἥμισύ που ἀποφαίνει τὴν διακεκαυμένην τῆς μεταξὺ τῶν τροπικῶν ἢ μικρῷ τοῦ ἡμίσους μείζονα, ἴσην δὲ καὶ τὴν αὐτὴν οὐδαμῶς. τοῖς τε ἀρκτικοῖς οὔτε παρὰ πᾶσιν οὖσιν οὔτε τοῖς αὐτοῖς πανταχοῦ τίς ἂν διορίζοι τὰς εὐκράτους, αἵπερ εἰσὶν ἀμετάπτωτοι; τὸ μὲν οὖν μὴ παρὰ πᾶσιν εἶναι τοὺς ἀρκτικούς, οὐδὲν ἂν εἴη πρὸς τὸν ἔλεγχον· δεῖ γὰρ παρὰ τοῖς τὴν εὔκρατον οἰκοῦσιν εἶναι πᾶσι, πρὸς οὕσπερ καὶ λέγεται μόνους εὔκρατος. τὸ δὲ μὴ πανταχοῦ τὸν αὐτὸν τρόπον, ἀλλὰ μεταπίπτειν, καλῶς εἴληπται.", "st": "2.2.2"}, {"sp": "N", "t": "αὐτὸς δὲ διαιρῶν εἰς τὰς ζώνας πέντε μέν φησιν εἶναι χρησίμους πρὸς τὰ οὐράνια, τούτων δὲ περισκίους δύο τὰς ὑπὸ τοῖς πόλοις μέχρι τῶν ἐχόντων τοὺς τροπικοὺς ἀρκτικούς, ἑτεροσκίους δὲ τὰς ἐφεξῆς ταύταις δύο μέχρι τῶν ὑπὸ τοῖς τροπικοῖς οἰκούντων, ἀμφίσκιον δὲ τὴν μεταξὺ τῶν τροπικῶν· πρὸς δὲ τὰ ἀνθρώπεια ταύτας τε καὶ δύο ἄλλας στενὰς τὰς ὑπὸ τοῖς τροπικοῖς, καθ’ ἃς ἥμισύ πως μηνὸς κατὰ κορυφήν ἐστιν ὁ ἥλιος, δίχα διαιρουμένας ὑπὸ τῶν τροπικῶν. ἔχειν γάρ τι ἴδιον τὰς ζώνας ταύτας, αὐχμηράς τε ἰδίως καὶ ἀμμώδεις ὑπαρχούσας καὶ ἀφόρους πλὴν σιλφίου καὶ πυρωδῶν τινων καρπῶν συγκεκαυμένων· ὄρη γὰρ μὴ εἶναι πλησίον ὥστε τὰ νέφη προσπίπτοντα ὄμβρους ποιεῖν, μηδὲ δὴ ποταμοῖς διαρρεῖσθαι· διόπερ οὐλότριχας καὶ οὐλόκερως καὶ προχείλους καὶ πλατύρρινας γεννᾶσθαι· τὰ γὰρ ἄκρα αὐτῶν συστρέφεσθαι· καὶ τοὺς ἰχθυοφάγους δὲ κατὰ ταύτας τὰς ζώνας οἰκεῖν. ὅτι δὲ ταῦτ’ ἴδια τῶν ζωνῶν τούτων, δηλοῦν φησὶ τὸ τοὺς νοτιωτέρους αὐτῶν ἔχειν τὸ περιέχον εὐκρατότερον καὶ τὴν γῆν καρπιμωτέραν καὶ εὐυδροτέραν.", "st": "2.2.3"}, {"sp": "N", "t": "πολύβιος δὲ ποιεῖ ζώνας ἕξ, δύο μὲν τὰς τοῖς ἀρκτικοῖς ὑποπιπτούσας, δύο δὲ τὰς μεταξὺ τούτων τε καὶ τῶν τροπικῶν, [καὶ δύο τὰς μεταξὺ τούτων] καὶ τοῦ ἰσημερινοῦ. ἡ μὲν οὖν εἰς πέντε διαίρεσις δοκεῖ μοι καὶ φυσικῶς ἅμα καὶ γεωγραφικῶς εἰρῆσθαι· φυσικῶς μέν, ὅτι καὶ πρὸς τὰ οὐράνια καὶ πρὸς τὴν τοῦ περιέχοντος κρᾶσιν· πρὸς μὲν τὰ οὐράνια, ὅτι τοῖς περισκίοις [καὶ τοῖς ἑτεροσκίοις] καὶ τοῖς ἀμφισκίοις οὕτως ἂν ἄριστα διοριζομένοις συνδιορίζεται καὶ τὰ περὶ τὴν θέαν τῶν ἄστρων, ὁλοσχερεῖ τινι μερισμῷ λαμβάνοντα τὴν ἐξάλλαξιν· πρὸς δὲ τὴν τοῦ περιέχοντος κρᾶσιν, ὅτι τῆς τούτου κράσεως πρὸς τὸν ἥλιον κρινομένης διαφοραὶ τρεῖς εἰσιν αἱ γενικώταται καὶ συντείνουσαι πρός τε τὰς τῶν ζῴων καὶ φυτῶν συστάσεις καὶ τῶν ἄλλων * ἡμισυσταλεῖς τῶν ὑπὸ τῷ ἀέρι καὶ ἐν αὐτῷ ἐκείνῳ, ὑπερβολὴ θάλπους καὶ ἔλλειψις καὶ μεσότης. αὕτη δὲ τῷ εἰς τὰς ζώνας μερισμῷ λαμβάνει τὴν οἰκείαν διάκρισιν· αἵ τε γὰρ κατεψυγμέναι δύο τὴν ἔλλειψιν τοῦ θάλπους ὑπαγορεύουσιν εἰς μίαν τοῦ περιέχοντος φύσιν συναγόμεναι, αἵ τε εὔκρατοι παραπλησίως εἰς μίαν τὴν μεσότητα ἄγονται, εἰς δὲ τὴν λοιπὴν ἡ λοιπὴ μία καὶ διακεκαυμένη. ὅτι δὲ καὶ γεωγραφικός ἐστιν ὁ μερισμός, δῆλον· ζητεῖ γὰρ ἡ γεωγραφία τῆς ἑτέρας τῶν εὐκράτων ἀφορίσαι τὸ οἰκούμενον ὑφ’ ἡμῶν τμῆμα· πρὸς δύσει μὲν οὖν καὶ ἀνατολῇ θάλαττά ἐστιν ἡ περατοῦσα, πρὸς δὲ τὰ νότια καὶ τὰ βόρεια ὁ ἀήρ, ὁ μὲν μέσος εὔκρατος ὢν καὶ φυτοῖς καὶ ζῴοις, ὁ δ’ ἐφ’ ἑκάτερα δύσκρατος ὑπερβολῇ καὶ ἐλλείψει τοῦ θάλπους. εἰς δὲ τὰς τρεῖς διαφορὰς ταύτας ἐδέησε τῆς εἰς πέντε ζώνας διαιρέσεως· τῷ γὰρ ἰσημερινῷ τμηθεῖσα δίχα ἡ σφαῖρα τῆς γῆς εἴς τε τὸ βόρειον ἡμισφαίριον, ἐν ᾧ ἡμεῖς ἐσμεν, καὶ τὸ νότιον ὑπέγραψε τὰς τρεῖς διαφοράς· τὰ μὲν γὰρ πρὸς τῷ ἰσημερινῷ καὶ τῇ διακεκαυμένῃ ζώνῃ διὰ καῦμα ἀοίκητά ἐστι, τὰ δὲ πρὸς τῷ πόλῳ διὰ ψῦχος, τὰ δὲ μέσα τὰ εὔκρατα καὶ τὰ οἰκήσιμα. ὁ δὲ τὰς ὑπὸ τοῖς τροπικοῖς προστιθεὶς οὐκ ἀνὰ λόγον ταῖς πέντε ταύτας προστίθησιν οὐδ’ ὁμοίᾳ κεχρημένας διαφορᾷ, ἀλλ’ ὡς ἂν εἰ καὶ ταῖς ἐθνικαῖς διαφοραῖς ἀπέφαινε ζώνας, ἄλλην μὲν τὴν Αἰθιοπικήν, ἄλλην δὲ τὴν Σκυθικὴν καὶ Κελτικήν, τρίτην δὲ τὴν ἀνὰ μέσον.", "st": "2.3.1"}, {"sp": "N", "t": "̔ο δὲ Πολύβιος τοῦτο μὲν οὐκ εὖ τὸ ποιεῖν τινας ζώνας τοῖς ἀρκτικοῖς διοριζομένας, δύο μὲν τὰς ὑποπιπτούσας αὐτοῖς δύο δὲ τὰς μεταξὺ τούτων καὶ τῶν τροπικῶν· εἴρηται γὰρ ὅτι τοῖς μεταπίπτουσι σημείοις οὐχ ὁριστέον τὰ ἀμετάπτωτα. οὐδὲ τοῖς τροπικοῖς δὲ τῆς διακεκαυμένης ὅροις χρηστέον· καὶ [γὰρ] τοῦτ’ εἴρηται. τὴν διακεκαυμένην μέντοι δίχα διαιρῶν πρὸς οὐ φαύλην ἐπίνοιαν φαίνεται κεκινημένος, πρὸς ἣν καὶ ὅλην δίχα διαιροῦμεν εὐφυῶς τὴν γῆν εἴς τε τὸ βόρειον ἡμισφαίριον καὶ τὸ νότιον τῷ ἰσημερινῷ· δῆλον γὰρ ὅτι διαιρεῖται κατὰ ταύτην τὴν τομὴν καὶ ἡ διακεκαυμένη, [καὶ] ποιεῖ τινα ἐπιτηδειότητα, ὥστε καὶ τὸ ἡμισφαίριον ἑκάτερον ἐξ ὅλων συντετάχθαι τριῶν ζωνῶν ὁμοιοειδῶν τῶν ἐν θατέρῳ. ἡ μὲν οὖν τοιαύτη τομὴ δέχεται τὴν εἰς ἓξ ζώνας διαίρεσιν, ἡ δ’ ἑτέρα οὐ πάνυ. εἰ γοῦν τῷ διὰ τῶν πόλων δίχα τέμνοις τὴν γῆν, οὐκ ἂν εἰκότως ἑκάτερον τῶν ἡμισφαιρίων, τό τε ἑσπέριον καὶ τὸ ἀνατολικόν, τέμνοις εἰς ζώνας ἕξ, ἀλλὰ ἡ εἰς πέντε ἀρκοῦσα ἂν εἴη· τὸ γὰρ ὁμοιοπαθὲς τῶν τμημάτων ἀμφοτέρων τῆς διακεκαυμένης, ἃ ποιεῖ ὁ ἰσημερινός, καὶ τὸ συγκεῖσθαι περιττὴν καὶ περίεργον ἀποφαίνει τὴν τομήν, ὁμοιοειδῶν μὲν οὐσῶν καὶ τῶν εὐκράτων καὶ τῶν κατεψυγμένων, ἀλλ’ οὐ συγκειμένων· οὕτως οὖν καὶ τὴν ὅλην γῆν ἐκ τῶν τοιούτων ἡμισφαιρίων ἐπινοουμένην ἀρκούντως ἂν εἰς πέντε διαιροίης. εἰ δ’, ὥσπερ Ἐρατοσθένης φησίν, ἡ ὑποπίπτουσα τῷ ἰσημερινῷ ἐστὶν εὔκρατος, καθάπερ καὶ Πολύβιος ὁμοδοξεῖ (προστίθησι δ’ οὗτος καὶ διότι ὑψηλοτάτη ἐστί· διόπερ καὶ κατομβρεῖται, τῶν βορείων νεφῶν κατὰ τοὺς ἐτησίας ἐκεῖ τοῖς ἀναστήμασι προσπιπτόντων πλείστων), πολὺ κρεῖττον τρίτην εὔκρατον ταύτην ποιεῖν στενήν τινα, ἢ τὰς ὑπὸ τοῖς τροπικοῖς εἰσάγειν. συνηγορεῖ δὲ τούτοις καὶ τὰ τοιαῦτα, ὧν μέμνηται καὶ Ποσειδώνιος, τὸ ἐκεῖ τὰς μεταστάσεις ὀξυτέρας εἶναι τὰς εἰς τὰ πλάγια, ὡς δ’ αὕτως καὶ τὰς ἀπ’ ἀνατολῆς ἐπὶ δύσιν τοῦ ἡλίου· ὀξύτεραι γὰρ αἱ κατὰ μεγίστου κύκλου τῶν ὁμοταχῶν κινήσεων.", "st": "2.3.2"}, {"sp": "N", "t": "Ἐνίσταται δ’ ὁ Ποσειδώνιος τῷ Πολυβίῳ, διότι φησὶ τὴν ὑπὸ τῷ ἰσημερινῷ οἴκησιν ὑψηλοτάτην· οὐδὲν γὰρ εἶναι κατὰ τὴν σφαιρικὴν ἐπιφάνειαν ὕψος διὰ τὴν ὁμαλότητα, οὐδὲ δὴ ὀρεινὴν εἶναι τὴν ὑπὸ τῷ ἰσημερινῷ, ἀλλὰ μᾶλλον πεδιάδα ἰσόπεδόν πως τῇ ἐπιφανείᾳ τῆς θαλάττης· τοὺς δὲ πληροῦντας τὸν Νεῖλον ὄμβρους ἐκ τῶν Αἰθιοπικῶν ὀρῶν συμβαίνειν. ταῦτα δ’ εἰπὼν ἐνταῦθα ἐν ἄλλοις συγχωρεῖ, φήσας ὑπονοεῖν ὄρη εἶναι τὰ ὑπὸ τῷ ἰσημερινῷ, πρὸς ἃ ἑκατέρωθεν ἀπὸ τῶν εὐκράτων ἀμφοῖν προσπίπτοντα τὰ νέφη ποιεῖν τοὺς ὄμβρους. αὕτη μὲν οὖν ἡ ἀνομολογία φανερά· ἀλλὰ καὶ δοθέντος τοῦ ὀρεινὴν εἶναι τὴν ὑπὸ τῷ ἰσημερινῷ, ἄλλη τις ἀνακύπτειν ἂν δόξειεν· οἱ γὰρ αὐτοὶ σύρρουν φασὶν εἶναι τὸν ὠκεανόν. πῶς οὖν ὄρη κατὰ μέσον ἱδρύουσιν αὐτόν; πλὴν εἰ νήσους τινὰς βούλονται λέγειν. ὅπως δὲ [δή] ποτε τοῦτ’ ἔχει, τῆς γεωγραφικῆς μερίδος ἔξω πίπτει· δοτέον δ’ ἴσως τῷ προθεμένῳ τὴν περὶ ὠκεανοῦ πραγματείαν ταῦτ’ ἐξετάζειν.", "st": "2.3.3"}, {"sp": "N", "t": "μνησθεὶς δὲ τῶν περιπλεῦσαι λεγομένων τὴν Λιβύην, Ἡρόδοτον μὲν οἴεσθαί φησιν ὑπὸ Δαρείου πεμφθέντας τινὰς τελέσαι τὸν περίπλουν· Ἡρακλείδην δὲ τὸν Ποντικὸν ἐν διαλόγῳ ποιεῖν ἀφιγμένον παρὰ Γέλωνι μάγον τινὰ περιπλεῦσαι φάσκοντα. ἀμάρτυρα δὲ ταῦτ’ εἶναι φήσας καὶ Εὔδοξόν τινα Κυζικηνὸν θεωρὸν καὶ σπονδοφόρον τοῦ τῶν Κορείων ἀγῶνος ἐλθεῖν εἰς Αἴγυπτον ἱστορεῖ κατὰ τὸν δεύτερον Εὐεργέτην· συσταθῆναι δὲ καὶ τῷ βασιλεῖ καὶ τοῖς περὶ αὐτόν … καὶ μάλιστα κατὰ τοὺς ἀνάπλους τοῦ Νείλου, θαυμαστικὸν ὄντα τῶν τοπικῶν ἰδιωμάτων ἅμα καὶ οὐκ ἀπαίδευτον. τυχεῖν δή τινα Ἰνδὸν κομισθέντα ὡς τὸν βασιλέα ὑπὸ τῶν φυλάκων τοῦ Ἀραβίου μυχοῦ, λεγόντων εὑρεῖν ἡμιθανῆ καταχθέντα μόνον ἐν νηί, τίς δ’ εἴη καὶ πόθεν ἀγνοεῖν μὴ συνιέντας τὴν διάλεκτον· τὸν δὲ παραδοῦναι τοῖς διδάξουσιν ἑλληνίζειν. ἐκμαθόντα δὲ διηγήσασθαι διότι ἐκ τῆς Ἰνδικῆς πλέων περιπέσοι πλάνῃ καὶ σωθείη δεῦρο τοὺς σύμπλους ἀποβαλὼν λιμῷ· ὑποληφθέντα δὲ ὑποσχέσθαι τὸν εἰς Ἰνδοὺς πλοῦν ἡγήσασθαι τοῖς ὑπὸ τοῦ βασιλέως προχειρισθεῖσι· τούτων δὲ γενέσθαι τὸν Εὔδοξον. πλεύσαντα δὴ μετὰ δώρων ἐπανελθεῖν ἀντιφορτισάμενον ἀρώματα καὶ λίθους πολυτελεῖς, ὧν τοὺς μὲν καταφέρουσιν οἱ ποταμοὶ μετὰ τῶν ψήφων, τοὺς δ’ ὀρυκτοὺς εὑρίσκουσι πεπηγότας ἐξ ὑγροῦ, καθάπερ τὰ κρυστάλλινα παρ’ ἡμῖν· διαψευσθῆναι δὲ τῶν ἐλπίδων· ἀφελέσθαι γὰρ αὐτὸν ἅπαντα τὸν φόρτον τὸν Εὐεργέτην. τελευτήσαντος δ’ ἐκείνου τὸν βίον, Κλεοπάτραν τὴν γυναῖκα διαδέξασθαι τὴν ἀρχήν· πάλιν οὖν καὶ ὑπὸ ταύτης πεμφθῆναι τὸν Εὔδοξον μετὰ μείζονος παρασκευῆς. ἐπανιόντα δ’ ἀνέμοις παρενεχθῆναι ὑπὲρ τὴν Αἰθιοπίαν· προσφερόμενον δέ τισι τόποις ἐξοικειοῦσθαι τοὺς ἀνθρώπους μεταδόσει σιτίων τε καὶ οἴνου καὶ παλαθίδων, ὧν ἐκείνοις οὐ μετῆν, ἀντὶ δὲ τούτων ὑδρείας τε τυγχάνειν καὶ καθοδηγίας, ἀπογράφεσθαί τε τῶν ῥημάτων ἔνια. εὑρόντα δ’ ἀκρόπρῳρον ξύλινον ἐκ ναυαγίου ἵππον ἔχον ἐγγεγλυμμένον, πυθόμενον ὡς ἀπὸ τῆς ἑσπέρας πλεόντων τινῶν εἴη τὸ ναυάγιον τοῦτο, κομίζειν αὐτὸ ἀναστρέψαντα πρὸς τὸν οἰκεῖον πλοῦν. σωθέντα δ’ εἰς Αἴγυπτον, οὐκέτι τῆς Κλεοπάτρας ἡγουμένης ἀλλὰ τοῦ παιδός, ἀφαιρεθῆναι πάλιν πάντα· φωραθῆναι γὰρ νενοσφισμένον πολλά. τὸ δ’ ἀκρόπρῳρον προφέροντα εἰς τὸ ἐμπόριον δεικνύναι τοῖς ναυκλήροις, γνῶναι δὲ Γαδειριτῶν ὄν· τούτων γὰρ τοὺς μὲν ἐμπόρους μεγάλα στέλλειν πλοῖα, τοὺς δὲ πένητας μικρά, ἃ καλεῖν ἵππους ἀπὸ τῶν ἐν ταῖς πρῴραις ἐπισήμων· τούτοις δὲ πλεῖν μέχρι τοῦ Λίξου ποταμοῦ περὶ τὴν Μαυρουσίαν ἁλιευομένους. ἀλλὰ τῶν δὴ ναυκλήρων τινὰς γνωρίσαι τὸ ἀκρόπρῳρον ἑνὸς τῶν ἀπὸ τοῦ Λίξου ποταμοῦ πορρώτερον πλευσάντων καὶ μὴ σωθέντων ὑπάρξαν. ἐκ δὲ τούτου συμβαλόντα τὸν Εὔδοξον ὡς δυνατὸς εἴη ὁ περίπλους ὁ Λιβυκός, πορευθέντα οἴκαδε τὴν οὐσίαν ἐνθέμενον πᾶσαν ἐξορμῆσαι. καὶ πρῶτον μὲν εἰς Δικαιάρχειαν, εἶτ’ εἰς Μασσαλίαν ἐλθεῖν καὶ τὴν ἑξῆς παραλίαν μέχρι Γαδείρων, πανταχοῦ δὲ διακωδωνίζοντα ταῦτα καὶ χρηματιζόμενον κατασκευάσασθαι πλοῖον μέγα καὶ ἐφόλκια δύο λέμβοις λῃστρικοῖς ὅμοια, ἐμβιβάσαι τε μουσικὰ παιδισκάρια καὶ ἰατροὺς καὶ ἄλλους τεχνίτας, ἔπειτα πλεῖν ἐπὶ τὴν Ἰνδικὴν μετέωρον ζεφύροις συνεχέσι. καμνόντων δὲ τῷ πλῷ τῶν συνόντων, ἄκοντα ἐπουρίσαι πρὸς γῆν δεδοικότα τὰς πλημμυρίδας καὶ τὰς ἀμπώτεις. καὶ δὴ καὶ συμβῆναι ὅπερ ἐδεδίει· καθίσαι γὰρ τὸ πλοῖον, ἡσυχῆ δέ, ὥστε μηδ’ ἀθροῦν διαλυθῆναι, ἀλλὰ φθῆναι τὰ φορτία σωθέντα εἰς γῆν καὶ τῶν ξύλων τὰ πλεῖστα· ἐξ ὧν τρίτον λέμβον συμπηξάμενον πεντηκοντόρῳ πάρισον πλεῖν, ἕως ἀνθρώποις συνέμιξε τὰ αὐτὰ ῥήματα φθεγγομένοις, ἅπερ πρότερον ἀπεγέγραπτο· ἅμα δὲ τοῦτό τε γνῶναι ὅτι οἱ ἐνταῦθα ἄνθρωποι ὁμοεθνεῖς εἶεν τοῖς Αἰθίοψιν ἐκείνοις, καὶ ὅτι ὁμοροῖεν τῇ Βόγου βασιλείᾳ. ἀφέντα δὴ τὸν ἐπὶ Ἰνδοὺς πλοῦν ἀναστρέφειν· ἐν δὲ τῷ παράπλῳ νῆσον εὔυδρον καὶ εὔδενδρον ἐρήμην ἰδόντα σημειώσασθαι· σωθέντα δὲ εἰς τὴν Μαυρουσίαν, διαθέμενον τοὺς λέμβους πεζῇ κομισθῆναι πρὸς τὸν Βόγον καὶ συμβουλεύειν αὐτῷ τὴν ναυστολίαν ἐπανελέσθαι ταύτην, ἰσχῦσαι δ’ εἰς τἀναντία τοὺς φίλους ὑποτείνοντας φόβον μὴ συμβῇ τὴν χώραν εὐεπιβούλευτον γενέσθαι, δειχθείσης παρόδου τοῖς ἔξωθεν ἐπιστρατεύειν ἐθέλουσιν. ὡς δ’ ἐπύθετο λόγῳ μὲν πεμπόμενον ἑαυτὸν ἐπὶ τὴν ἀναδειχθεῖσαν ναυστολίαν, ἔργῳ δ’ ἐκτεθησόμενον εἰς ἐρήμην τινὰ νῆσον, φυγεῖν εἰς τὴν Ῥωμαίων ἐπικράτειαν κἀκεῖθεν εἰς τὴν Ἰβηρίαν διᾶραι. πάλιν δὲ κατασκευασάμενον στρογγύλον πλοῖον καὶ μακρὸν πεντηκόντορον, ὥστε τῷ μὲν πελαγίζειν τῷ δὲ πειρᾶσθαι τῆς γῆς, ἐνθέμενον γεωργικὰ ἐργαλεῖα καὶ σπέρματα καὶ οἰκοδόμους ὁρμῆσαι πρὸς τὸν αὐτὸν περίπλουν, διανοούμενον, εἰ βραδύνοιτο ὁ πλοῦς, ἐνδιαχειμάσαι τῇ προεσκεμμένῃ νήσῳ, καὶ σπείραντα καὶ ἀνελόμενον τοὺς καρποὺς τελέσαι τὸν ἐγνωσμένον ἐξ ἀρχῆς πλοῦν.", "st": "2.3.4"}, {"sp": "N", "t": "“Ἐγὼ μὲν οὖν” φησί “μέχρι [δεῦρο] τῆς περὶ τὸν Εὔδοξον ἱστορίας ἥκω· τί δ’ ὕστερον συνέβη τοὺς ἐκ Γαδείρων καὶ τῆς Ἰβηρίας εἰκὸς εἰδέναι.” ἐκ πάντων δὴ τούτων φησὶ δείκνυσθαι διότι ἡ οἰκουμένη κύκλῳ περιρρεῖται τῷ ὠκεανῷ· “οὐ γάρ μιν δεσμὸς περιβάλλεται ἠπείροιο, ἀλλ’ ἐς ἀπειρεσίην κέχυται· τό μιν οὔτι μιαίνει.” θαυμαστὸς δὴ κατὰ πάντα ἐστὶν ὁ Ποσειδώνιος, τὸν μὲν τοῦ μάγου περίπλουν, ὃν Ἡρακλείδης εἶπεν, ἀμάρτυρον νομίσας, καὶ αὐτῶν τῶν ὑπὸ Δαρείου πεμφθέντων, ὃν Ἡρόδοτος ἱστορεῖ, τὸ δὲ Βεργαῖον διήγημα τοῦτο ἐν πίστεως μέρει τιθείς, εἴθ’ ὑπ’ αὐτοῦ πεπλασμένον εἴτ’ ἄλλων πλασάντων πιστευθέν. τίς γὰρ ἡ πιθανότης πρῶτον μὲν τῆς κατὰ τὸν Ἰνδὸν περιπετείας; ὁ γὰρ Ἀράβιος κόλπος ποταμοῦ δίκην στενός ἐστι καὶ μακρὸς [πεντακισχιλίους] ἐπὶ μυρίοις που σταδίους μέχρι τοῦ στόματος, καὶ τούτου στενοῦ παντάπασιν ὄντος· οὐκ εἰκὸς δ’ οὔτ’ ἔξω που τὸν πλοῦν ἔχοντας εἰς τὸν κόλπον παρωσθῆναι τοὺς Ἰνδοὺς κατὰ πλάνην (τὰ γὰρ στενὰ ἀπὸ τοῦ στόματος δηλώσειν ἔμελλε τὴν πλάνην), οὔτ’ εἰς τὸν κόλπον ἐπίτηδες καταχθεῖσιν ἔτι πλάνης ἦν πρόφασις καὶ ἀνέμων ἀστάτων. λιμῷ τε πῶς περιεῖδον ἅπαντας ἀπολλυμένους σφᾶς πλὴν ἑνός; περιγενόμενός τε πῶς ἱκανὸς ἦν μόνος κατευθύνειν τὸ πλοῖον οὐ μικρὸν ὂν τά γε τηλικαῦτα πελάγη διαίρειν δυνάμενον; τίς δ’ ἡ ὀξυμάθεια τῆς διαλέκτου, ἀφ’ ἧς ἱκανὸς ἦν πεῖσαι τὸν βασιλέα, ὡς δυνάμενος τοῦ πλοῦ καθηγήσασθαι; τίς δ’ ἡ σπάνις τῷ Εὐεργέτῃ τῶν τοιούτων καθηγεμόνων, ἤδη γνωριζομένης ὑπὸ πολλῶν τῆς ταύτῃ θαλάττης; ὁ δὲ δὴ σπονδοφόρος καὶ θεωρὸς τῶν Κυζικηνῶν πῶς ἀφεὶς τὴν πόλιν εἰς Ἰνδοὺς ἔπλει; πῶς δὲ ἐπιστεύθη τηλικαύτην χρείαν; πῶς δ’ ἐπανιὼν ἀφαιρεθεὶς πάντα παρὰ τὴν ἐλπίδα καὶ ἀτιμωθεὶς ἔτι μείζονα ἐπιστεύθη παρασκευὴν δώρων; ἐπανιὼν δὲ καὶ παρενεχθεὶς εἰς τὴν Αἰθιοπίαν τίνος χάριν ἢ τὰς διαλέκτους ἀπεγράφετο, ἢ τὸ ἀκρόπρῳρον ἐπυνθάνετο τῆς ἁλιάδος πόθεν ἐκπέσοι; τὸ γὰρ μαθεῖν ὅτι ἀπὸ δύσεως πλεόντων ἦν ναυάγιον οὐδενὸς ἔμελλεν ὑπάρξειν σημεῖον, ἐπεὶ καὶ αὐτὸς ἔμελλεν ἀπὸ δύσεως πλεῖν κατὰ τὴν ἐπάνοδον. ἐλθὼν δ’ οὖν εἰς Ἀλεξάνδρειαν, φωραθεὶς ὡς νενοσφισμένος πολλά, πῶς οὐκ ἐκολάσθη, ἀλλὰ καὶ περιῄει τοὺς ναυκλήρους διαπυνθανόμενος, δεικνὺς ἅμα τὸ ἀκρόπρῳρον; ὁ δὲ γνωρίσας οὐχὶ θαυμαστός; ὁ δὲ πιστεύσας οὐ θαυμασιώτερος καὶ κατ’ ἐλπίδα τοιαύτην ἐπανιὼν εἰς τὴν οἰκείαν καὶ μετοικισμὸν ἐκεῖθεν ποιησάμενος εἰς τὰ ἔξω στηλῶν; ἀλλ’ οὐδ’ ἐξὸν ἦν ἄνευ προστάγματος ἐξ Ἀλεξανδρείας ἀνάγεσθαι, καὶ ταῦτα νενοσφισμένῳ βασιλικὰ χρήματα. οὐδέ γε λαθεῖν ἐκπλεύσαντα ἐνεδέχετο τοσαύτῃ φρουρᾷ κεκλεισμένου τοῦ λιμένος καὶ τῶν ἄλλων ἐξόδων, ὅσην καὶ νῦν ἔτι διαμένουσαν ἔγνωμεν ἡμεῖς ἐπιδημοῦντες τῇ Ἀλεξανδρείᾳ πολὺν χρόνον, καίτοι τὰ νῦν πολὺ ἀνεῖται, Ῥωμαίων ἐχόντων· αἱ βασιλικαὶ δὲ φρουραὶ πολὺ ἦσαν πικρότεραι. ἐπειδὴ δὲ καὶ ἀπῆρεν εἰς τὰ Γάδειρα καὶ ναυπηγησάμενος ἔπλει βασιλικῶς, διαλυθέντος αὐτῷ τοῦ πλοίου, πῶς μὲν ἐναυπηγήσατο τρίτον λέμβον ἐν τῇ ἐρήμῳ; πῶς δὲ πλέων πάλιν καὶ εὑρὼν τοὺς ἑσπερίους Αἰθίοπας τοῖς ἑῴοις ὁμογλώττους οὐκ ὠρέχθη διανύσαι τὸν ἑξῆς πλοῦν, οὕτω χαῦνος ὢν πρὸς τὸ φιλέκδημον, μικρὸν ἔχειν ἐλπίσας λοιπὸν τὸ ἄγνωστον, ἀλλ’ ἀφεὶς ταῦτα τῆς διὰ Βόγου ναυστολίας ἐπεθύμησε; πῶς δ’ ἔγνω τὴν λάθρᾳ κατ’ αὐτοῦ συνισταμένην ἐπιβουλήν; τί δὲ τοῦτ’ ἦν τῷ Βόγῳ πλεονέκτημα ὁ τἀνθρώπου ἀφανισμός, ἐξὸν ἄλλως ἀποπέμψασθαι; γνοὺς δὲ τὴν ἐπιβουλὴν πῶς ἔφθη φυγὼν εἰς ἀσφαλεῖς τόπους; ἕκαστον γὰρ τῶν τοιούτων οὐκ ἀδύνατον μέν, ἀλλὰ χαλεπὸν καὶ σπανίως γινόμενον μετὰ τύχης τινός· τῷ δ’ εὐτυχεῖν ἀεὶ συνέβαινεν εἰς κινδύνους καθισταμένῳ συνεχεῖς. πῶς δ’ οὐκ ἔδεισεν ἀποδρὰς τὸν Βόγον πλεῖν πάλιν παρὰ τὴν Λιβύην σὺν παρασκευῇ δυναμένῃ συνοικίσαι νῆσον; οὐ πολὺ οὖν ἀπολείπεται ταῦτα τῶν Πυθέου καὶ Εὐημέρου καὶ Ἀντιφάνους ψευσμάτων. ἀλλ’ ἐκείνοις μὲν συγγνώμη τοῦτ’ αὐτὸ ἐπιτηδεύουσιν, ὥσπερ τοῖς θαυματοποιοῖς· τῷ δ’ ἀποδεικτικῷ καὶ φιλοσόφῳ, σχεδὸν δέ τι καὶ περὶ πρωτείων ἀγωνιζομένῳ, τίς ἂν συγγνοίη; ταῦτα μὲν οὖν οὐκ εὖ.", "st": "2.3.5"}, {"sp": "N", "t": "τὸ δὲ ἐξαίρεσθαι τὴν γῆν ποτε καὶ ἱζήματα λαμβάνειν καὶ μεταβολὰς τὰς ἐκ τῶν σεισμῶν καὶ τῶν ἄλλων τῶν παραπλησίων, ὅσα διηριθμησάμεθα καὶ ἡμεῖς, ὀρθῶς κεῖται παρ’ αὐτῷ· πρὸς ὃ καὶ τὸ τοῦ Πλάτωνος εὖ παρατίθησιν, ὅτι ἐνδέχεται καὶ μὴ πλάσμα εἶναι τὸ περὶ τῆς νήσου τῆς Ἀτλαντίδος, περὶ ἧς ἐκεῖνος ἱστορῆσαι Σόλωνά φησι πεπυσμένον παρὰ τῶν Αἰγυπτίων ἱερέων, ὡς ὑπάρχουσά ποτε ἀφανισθείη, τὸ μέγεθος οὐκ ἐλάττων ἠπείρου· καὶ τοῦτο οἴεται βέλτιον εἶναι λέγειν ἢ διότι ὁ πλάσας αὐτὴν ἠφάνισεν, ὡς ὁ ποιητὴς τὸ τῶν Ἀχαιῶν τεῖχος. εἰκάζει δὲ καὶ τὴν τῶν Κίμβρων καὶ τῶν συγγενῶν ἐξανάστασιν ἐκ τῆς οἰκείας [κατὰ λῃστείαν] γενέσθαι, οὐ κατὰ θαλάττης ἔφοδον ἀθρόαν συμβᾶσαν. ὑπονοεῖ δὲ τὸ τῆς οἰκουμένης μῆκος ἑπτά που μυριάδων σταδίων ὑπάρχον ἥμισυ εἶναι τοῦ ὅλον κύκλου καθ’ ὃν εἴληπται, ὥστε (φησίν) ἀπὸ τῆς δύσεως εὔρῳ πλέων ἐν τοσαύταις μυριάσιν ἔλθοι ἂν εἰς Ἰνδούς.", "st": "2.3.6"}, {"sp": "N", "t": "Ἐπιχειρήσας δὲ αἰτιᾶσθαι τοὺς οὕτω τὰς ἠπείρους διορίσαντας, ἀλλὰ μὴ παραλλήλοις τισὶ τῷ ἰσημερινῷ, δι’ ὧν ἔμελλον ἐξαλλάξεις δείκνυσθαι ζῴων τε καὶ φυτῶν καὶ ἀέρων, τῶν μὲν τῇ κατεψυγμένῃ συναπτόντων τῶν δὲ τῇ διακεκαυμένῃ, ὥστε οἱονεὶ ζώνας εἶναι τὰς ἠπείρους, ἀνασκευάζει πάλιν καὶ ἐν ἀναλύσει δίκης γίνεται, ἐπαινῶν πάλιν τὴν οὖσαν διαίρεσιν, θετικὴν ποιούμενος τὴν ζήτησιν πρὸς οὐδὲν χρησίμως. αἱ γὰρ τοιαῦται διατάξεις οὐκ ἐκ προνοίας γίνονται, καθάπερ οὐδὲ αἱ κατὰ τὰ ἔθνη διαφοραί, οὐδ’ αἱ διάλεκτοι, ἀλλὰ κατὰ περίπτωσιν καὶ συντυχίαν· καὶ τέχναι δὲ καὶ δυνάμεις καὶ ἐπιτηδεύσεις ἀρξάντων τινῶν κρατοῦσιν αἱ πλείους ἐν ὁποιῳοῦν κλίματι. ἔστι δέ τι καὶ παρὰ τὰ κλίματα, ὥστε τὰ μὲν φύσει ἐστὶν ἐπιχώριά τισι τὰ δ’ ἔθει καὶ ἀσκήσει. οὐ γὰρ φύσει Ἀθηναῖοι μὲν φιλόλογοι, Λακεδαιμόνιοι δ’ οὒ καὶ οἱ ἔτι ἐγγυτέρω Θηβαῖοι, ἀλλὰ μᾶλλον ἔθει· οὕτως οὐδὲ Βαβυλώνιοι φιλόσοφοι φύσει καὶ Αἰγύπτιοι, ἀλλ’ ἀσκήσει καὶ ἔθει· καὶ ἵππων δὲ καὶ βοῶν ἀρετὰς καὶ ἄλλων ζῴων οὐ τόποι μόνον, ἀλλὰ καὶ ἀσκήσεις ποιοῦσιν. ὁ δὲ συγχεῖ ταῦτα· ἐπαινῶν δὲ τὴν τοιαύτην διαίρεσιν τῶν ἠπείρων, οἵα νῦν ἐστι, παραδείγματι χρῆται τῷ τοὺς Ἰνδοὺς τῶν Αἰθιόπων διαφέρειν τῶν ἐν τῇ Λιβύῃ· εὐερνεστέρους γὰρ εἶναι καὶ ἧττον ἕψεσθαι τῇ ξηρασίᾳ τοῦ περιέχοντος· διὸ καὶ Ὅμηρον πάντας λέγοντα Αἰθίοπας δίχα διελεῖν “οἱ μὲν δυσομένου Ὑπερίονος, οἱ δ’ ἀνιόντος,” Κράτητα δ’ εἰσάγοντα τὴν ἑτέραν οἰκουμένην, ἣν οὐκ οἶδεν Ὅμηρος, δουλεύειν ὑποθέσει· καὶ ἔδει (φησί) μεταγράφειν οὕτως “ἠμὲν ἀπερχομένου Ὑπερίονος,” οἷον ἀπὸ τοῦ μεσημβρινοῦ περικλίνοντος.", "st": "2.3.7"}, {"sp": "N", "t": "πρῶτον μὲν οὖν οἱ πρὸς Αἰγύπτῳ Αἰθίοπες καὶ αὐτοὶ δίχα διαιροῦνται· οἱ μὲν γὰρ ἐν τῇ Ἀσίᾳ εἰσὶν οἱ δ’ ἐν τῇ Λιβύῃ, οὐδὲν διαφέροντες ἀλλήλων. ἔπειθ’ Ὅμηρος οὐ διὰ τοῦτο διαιρεῖ τοὺς Αἰθίοπας, ὅτι τοὺς Ἰνδοὺς ᾔδει τοιούτους τινὰς τοῖς σώμασιν (οὐδὲ γὰρ ἀρχὴν εἰδέναι τοὺς Ἰνδοὺς εἰκὸς Ὅμηρον, ὅπου γε οὐδ’ ὁ Εὐεργέτης κατὰ τὸν Εὐδόξειον μῦθον ᾔδει τὰ κατὰ τὴν Ἰνδικήν, οὐδὲ τὸν πλοῦν τὸν ἐπ’ αὐτήν), ἀλλὰ μᾶλλον κατὰ τὴν λεχθεῖσαν ὑφ’ ἡμῶν πρότερον διαίρεσιν. ἐκεῖ δὲ καὶ περὶ τῆς γραφῆς τῆς Κρατητείου διῃτήσαμεν ὅτι οὐδὲν διαφέρει οὕτως ἢ ἐκείνως γράφειν· ὁ δὲ τοῦτο μὲν διαφέρειν φησί, κρεῖττον δ’ οὕτως εἶναι μεταθεῖναι “ἠμὲν ἀπερχομένου.” τί οὖν διαφέρει τοῦτο τοῦ “ἠμὲν δυσομένου;” πᾶν γὰρ τὸ τμῆμα τὸ ἀπὸ τοῦ μεσημβρινοῦ ἐπὶ δύσιν δύσις καλεῖται, καθάπερ καὶ τὸ τοῦ ὁρίζοντος ἡμικύκλιον· ὅπερ καὶ Ἄρατος ἐπισημαίνεται “ἧχί περ ἄκραι μίσγονται δύσιές τε καὶ ἀντολαὶ ἀλλήλῃσιν.” εἰ δ’ ἐπὶ τῆς Κρατητείου γραφῆς οὕτω βέλτιον, φήσει τις καὶ ἐπὶ τῆς Ἀρισταρχείου δεῖν. τοσαῦτα καὶ πρὸς Ποσειδώνιον· πολλὰ γὰρ καὶ ἐν τοῖς καθ’ ἕκαστα τυγχάνει τῆς προσηκούσης διαίτης, ὅσα γεωγραφικά· ὅσα δὲ φυσικώτερα, ἐπισκεπτέον ἐν ἄλλοις ἢ οὐδὲ φροντιστέον· πολὺ γάρ ἐστι τὸ αἰτιολογικὸν παρ’ αὐτῷ καὶ τὸ Ἀριστοτελίζον, ὅπερ ἐκκλίνουσιν οἱ ἡμέτεροι διὰ τὴν ἐπίκρυψιν τῶν αἰτιῶν.", "st": "2.3.8"}, {"sp": "N", "t": "πολύβιος δὲ τὴν Εὐρώπην χωρογραφῶν τοὺς μὲν ἀρχαίους ἐᾶν φησι, τοὺς δ’ ἐκείνους ἐλέγχοντας ἐξετάζειν Δικαίαρχόν τε καὶ Ἐρατοσθένη τὸν τελευταῖον πραγματευσάμενον περὶ γεωγραφίας, καὶ Πυθέαν, ὑφ’ οὗ παρακρουσθῆναι πολλούς, ὅλην μὲν τὴν Βρεττανικὴν ἐμβαδὸν ἐπελθεῖν φάσκοντος, τὴν δὲ περίμετρον πλειόνων ἢ τεττάρων μυριάδων ἀποδόντος τῆς νήσου, προσιστορήσαντος δὲ καὶ τὰ περὶ τῆς Θούλης καὶ τῶν τόπων ἐκείνων, ἐν οἷς οὔτε γῆ καθ’ αὑτὴν ὑπῆρχεν ἔτι οὔτε θάλαττα οὔτ’ ἀήρ, ἀλλὰ σύγκριμά τι ἐκ τούτων πλεύμονι θαλαττίῳ ἐοικός, ἐν ᾧ φησι τὴν γῆν καὶ τὴν θάλατταν αἰωρεῖσθαι καὶ τὰ σύμπαντα, καὶ τοῦτον ὡς ἂν δεσμὸν εἶναι τῶν ὅλων, μήτε πορευτὸν μήτε πλωτὸν ὑπάρχοντα· τὸ μὲν οὖν τῷ πλεύμονι ἐοικὸς αὐτὸς ἑωρακέναι, τἆλλα δὲ λέγειν ἐξ ἀκοῆς. ταῦτα μὲν τὰ τοῦ Πυθέου, καὶ διότι ἐπανελθὼν ἐνθένδε πᾶσαν ἐπέλθοι τὴν παρωκεανῖτιν τῆς Εὐρώπης ἀπὸ Γαδείρων ἕως Τανάιδος.", "st": "2.4.1"}, {"sp": "N", "t": "φησὶ δ’ οὖν ὁ Πολύβιος ἄπιστον καὶ αὐτὸ τοῦτο, πῶς ἰδιώτῃ ἀνθρώπῳ καὶ πένητι τὰ τοσαῦτα διαστήματα πλωτὰ καὶ πορευτὰ γένοιτο; τὸν δ’ Ἐρατοσθένη διαπορήσαντα εἰ χρὴ πιστεύειν τούτοις, ὅμως περί τε τῆς Βρεττανικῆς πεπιστευκέναι καὶ τῶν κατὰ Γάδειρα καὶ τὴν Ἰβηρίαν· πολὺ δέ φησι βέλτιον τῷ Μεσσηνίῳ πιστεύειν ἢ τούτῳ. ὁ μέντοι γε εἰς μίαν χώραν τὴν Παγχαΐαν λέγει πλεῦσαι, ὁ δὲ καὶ μέχρι τῶν τοῦ κόσμου περάτων κατωπτευκέναι τὴν προσάρκτιον τῆς Εὐρώπης πᾶσαν, ἣν οὐδ’ ἂν τῷ Ἑρμῇ πιστεύσαι τις λέγοντι. Ἐρατοσθένη δὲ τὸν μὲν Εὐήμερον Βεργαῖον καλεῖν, Πυθέᾳ δὲ πιστεύειν, καὶ ταῦτα μηδὲ Δικαιάρχου πιστεύσαντος. τὸ μὲν οὖν μηδὲ Δικαιάρχου πιστεύσαντος γελοῖον, ὥσπερ ἐκείνῳ κανόνι χρήσασθαι προσῆκον, καθ’ οὗ τοσούτους ἐλέγχους αὐτὸς προφέρεται. Ἐρατοσθένους δὲ εἴρηται ἡ περὶ τὰ ἑσπέρια καὶ τὰ ἀρκτικὰ τῆς Εὐρώπης ἄγνοια. ἀλλ’ ἐκείνῳ μὲν καὶ Δικαιάρχῳ συγγνώμη, τοῖς μὴ κατιδοῦσι τοὺς τόπους ἐκείνους· Πολυβίῳ δὲ καὶ Ποσειδωνίῳ τίς ἂν συγγνοίη; ἀλλὰ μὴν Πολύβιός γέ ἐστιν ὁ λαοδογματικὰς καλῶν ἀποφάσεις, ἃς ποιοῦνται περὶ τῶν ἐν τούτοις τοῖς τόποις διαστημάτων καὶ ἐν ἄλλοις πολλοῖς, ἀλλ’ οὐδ’ ἐν οἷς ἐκείνους ἐλέγχει καθαρεύων. τοῦ γοῦν Δικαιάρχου μυρίους μὲν εἰπόντος τοὺς ἐπὶ στήλας ἀπὸ τῆς Πελοποννήσου σταδίους, πλείους δὲ τούτων τοὺς ἐπὶ τὸν Ἀδρίαν μέχρι τοῦ μυχοῦ, τοῦ δ’ ἐπὶ στήλας τὸ μέχρι τοῦ πορθμοῦ τρισχιλίους ἀποδόντος, ὡς γίνεσθαι τὸ λοιπὸν ἑπτακισχιλίους τὸ ἀπὸ πορθμοῦ μέχρι στηλῶν· τοὺς μὲν τρισχιλίους ἐᾶν φησιν εἴτ’ εὖ λαμβάνονται εἴτε μή, τοὺς δ’ ἑπτακισχιλίους οὐδετέρως, οὔτε τὴν παραλίαν ἐκμετροῦντι οὔτε τὴν διὰ μέσου τοῦ πελάγους. τὴν μὲν γὰρ παραλίαν ἐοικέναι μάλιστ’ ἀμβλείᾳ γωνίᾳ, βεβηκυίᾳ ἐπί τε τοῦ πορθμοῦ καὶ τῶν στηλῶν, κορυφὴν δ’ ἐχούσῃ Νάρβωνα, ὥστε συνίστασθαι τρίγωνον βάσιν ἔχον τὴν διὰ τοῦ πελάγους εὐθεῖαν, πλευρὰς δὲ τὰς τὴν γωνίαν ποιούσας τὴν λεχθεῖσαν, ὧν ἡ μὲν ἀπὸ τοῦ πορθμοῦ μέχρι Νάρβωνος μυρίων ἐστὶ καὶ πλειόνων ἢ διακοσίων ἐπὶ τοῖς χιλίοις, ἡ δὲ λοιπὴ μικρῷ ἐλαττόνων ἢ ὀκτακισχιλίων· καὶ μὴν πλεῖστον μὲν διάστημα ἀπὸ τῆς Εὐρώπης ἐπὶ τὴν Λιβύην ὁμολογεῖσθαι κατὰ τὸ Τυρρηνικὸν πέλαγος σταδίων οὐ πλειόνων ἢ τρισχιλίων, κατὰ τὸ Σαρδόνιον δὲ λαμβάνειν συναγωγήν. ἀλλ’ ἔστω, φησί, καὶ ἐκεῖνο τρισχιλίων, προειλήφθω δ’ ἐπὶ τούτοις δισχιλίων σταδίων τὸ τοῦ κόλπου βάθος τοῦ κατὰ Νάρβωνα, ὡς ἂν κάθετος ἀπὸ τῆς κορυφῆς ἐπὶ τὴν βάσιν τοῦ ἀμβλυγωνίου· δῆλον οὖν, φησίν, ἐκ τῆς παιδικῆς μετρήσεως, ὅτι ἡ σύμπασα παραλία ἡ ἀπὸ τοῦ πορθμοῦ ἐπὶ στήλας ἔγγιστα ὑπερέχει τῆς διὰ τοῦ πελάγους εὐθείας πεντακοσίοις σταδίοις. προστεθέντων δὲ τῶν ἀπὸ τῆς Πελοποννήσου ἐπὶ τὸν πορθμὸν τρισχιλίων, οἱ σύμπαντες ἔσονται στάδιοι, αὐτοὶ οἱ ἐπ’ εὐθείας, πλείους ἢ διπλάσιοι ὧν Δικαίαρχος εἶπε· πλείους δὲ τούτων τοὺς ἐπὶ τὸν μυχὸν τὸν Ἀδριατικὸν δεήσει, φησί, τιθέναι κατ’ ἐκεῖνον.", "st": "2.4.2"}, {"sp": "N", "t": "Ἀλλ’ ὦ φίλε Πολύβιε, φαίη τις ἄν, ὥσπερ τούτου τοῦ ψεύσματος ἐναργῆ παρίστησι τὸν ἔλεγχον ἡ πεῖρα ἐξ αὐτῶν ὧν εἴρηκας αὐτός, εἰς μὲν Λευκάδα ἐκ Πελοποννήσου ἑπτακοσίους, ἐντεῦθεν δὲ τοὺς ἴσους εἰς Κόρκυραν, καὶ πάλιν ἐντεῦθεν εἰς τὰ Κεραύνια τοὺς ἴσους, καὶ ἐν δεξιᾷ εἰς τὴν Ἰαπυγίαν, ἀπὸ δὲ τῶν Κεραυνίων τὴν Ἰλλυρικὴν παραλίαν σταδίων ἑξακισχιλίων ἑκατὸν πεντήκοντα· οὕτως κἀκεῖνα ψεύσματά ἐστιν ἀμφότερα, καὶ ὃ Δικαίαρχος εἶπε, τὸ ἀπὸ πορθμοῦ ἐπὶ στήλας εἶναι σταδίων ἑπτακισχιλίων, καὶ ὃ σὺ δοκεῖς ἀποδεῖξαι· ὁμολογοῦσι γὰρ οἱ πλεῖστοι λέγοντες τὸ διὰ πελάγους μυρίων εἶναι καὶ δισχιλίων, συμφωνεῖ δὲ τοῦτο καὶ τῇ ἀποφάσει τῇ περὶ τοῦ μήκους τῆς οἰκουμένης. μάλιστα γὰρ εἶναί φασι μυριάδων ἑπτά· τούτου δὲ τὸ ἑσπέριον τμῆμα τὸ ἀπὸ τοῦ Ἰσσικοῦ κόλπου μέχρι τῶν ἄκρων τῆς Ἰβηρίας, ἅπερ δυσμικώτατά ἐστι, μικρὸν ἀπολείπειν τῶν τρισμυρίων. συντιθέασι δ’ οὕτως· ἀπὸ μὲν τοῦ Ἰσσικοῦ κόλπου μέχρι τῆς Ῥοδίας πεντακισχιλίους, ἐνθένδ’ ἐπὶ Σαλμώνιον τῆς Κρήτης, ὅπερ ἐστὶ τὸ ἑῷον ἄκρον, χιλίους, αὐτῆς δὲ τῆς Κρήτης μῆκος πλείους ἢ δισχιλίους ἐπὶ Κριοῦ μέτωπον, ἐντεῦθεν δ’ ἐπὶ Πάχυνον τῆς Σικελίας τετρακισχιλίους καὶ πεντακοσίους, καὶ ἀπὸ Παχύνου δὲ ἐπὶ πορθμὸν πλείους ἢ χιλίους, εἶτα τὸ δίαρμα τὸ ἐπὶ στήλας ἀπὸ πορθμοῦ μυρίους δισχιλίους, ἀπὸ στηλῶν δὲ ἐπὶ τὰ τελευταῖα τοῦ Ἱεροῦ ἀκρωτηρίου τῆς Ἰβηρίας περὶ τρισχιλίους. καὶ ἡ κάθετος δὲ οὐ καλῶς εἴληπται, εἴπερ ἡ μὲν Νάρβων ἐπὶ τοῦ αὐτοῦ παραλλήλου σχεδόν τι ἵδρυται τῷ διὰ Μασσαλίας, αὕτη τε τῷ διὰ Βυζαντίου, καθάπερ καὶ Ἵππαρχος πείθεται, ἡ δὲ διὰ τοῦ πελάγους ἐπὶ τοῦ αὐτοῦ ἐστι τῷ διὰ πορθμοῦ καὶ τῆς Ῥοδίας, ἀπὸ δὲ τῆς Ῥοδίας εἰς Βυζάντιον ὡς ἂν ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ κειμένων ἀμφοῖν περὶ πεντακισχιλίους, ὡς εἰρήκασι, σταδίους· τοσοῦτοι γὰρ ἂν εἶεν καὶ οἱ τῆς εἰρημένης καθέτου. ἐπεὶ δὲ καὶ τὸ μέγιστον δίαρμα τοῦ πελάγους τούτου τὸ ἀπὸ τῆς Εὐρώπης ἐπὶ τὴν Λιβύην πεντακισχιλίων που σταδίων λέγουσιν ἀπὸ τοῦ μυχοῦ τοῦ Γαλατικοῦ κόλπου, δοκεῖ μοι πεπλανημένως λέγεσθαι τοῦτο, ἢ πολὺ τὴν Λιβύην κατὰ τοῦτο τὸ μέρος προσνεύειν ἐπὶ τὴν ἄρκτον καὶ συνάπτειν τῷ διὰ τῶν στηλῶν παραλλήλῳ. καὶ τοῦτο οὐκ εὖ λέγεται τὸ πλησίον τῆς Σαρδόνος τὴν λεχθεῖσαν κάθετον τελευτᾶν· οὐ γὰρ παραπλήσιον, ἀλλὰ πολὺ δυσμικώτερον εἶναι τὸ δίαρμα τοῦτο τῆς Σαρδόνος, ὅλον σχεδόν τι ἀπολαμβάνον ἐν τῷ μεταξὺ πρὸς τῷ Σαρδονίῳ τὸ Λιγυστικὸν πέλαγος· καὶ τῆς παραλίας δὲ τὰ μήκη πεπλεόνασται, πλὴν οὐκ ἐπὶ τοσοῦτόν γε.", "st": "2.4.3"}, {"sp": "N", "t": "̔εξῆς δὲ τὰ τοῦ Ἐρατοσθένους ἐπανορθοῖ, τὰ μὲν εὖ τὰ δὲ χεῖρον λέγων ἢ ἐκεῖνος. ἐξ Ἰθάκης μὲν γὰρ εἰς Κόρκυραν τριακοσίους εἰπόντος, πλείους φησὶν εἶναι τῶν ἐνακοσίων, ἐξ Ἐπιδάμνου δὲ εἰς Θεσσαλονίκειαν ἐνακοσίους ἀποδόντος, πλείους τῶν δισχιλίων φησί· ταῦτα μὲν εὖ. ἀπὸ δὲ Μασσαλίας ἐπὶ στήλας λέγοντος ἑπτακισχιλίους, ἀπὸ δὲ Πυρήνης ἑξακισχιλίους, αὐτὸς λέγει χεῖρον πλείους ἢ ἐνακισχιλίους τοὺς ἀπὸ Μασσαλίας, ἀπὸ δὲ Πυρήνης μικρὸν ἐλάττους ἢ ὀκτακισχιλίους· ἐγγυτέρω γὰρ τῆς ἀληθείας ἐκεῖνος εἴρηκεν. οἱ γὰρ νῦν ὁμολογοῦσιν, εἴ τις τὰς τῶν ὁδῶν ἀνωμαλίας ὑποτέμνοιτο, μὴ μείζω τῶν ἑξακισχιλίων σταδίων εἶναι τὸ μῆκος τὴν σύμπασαν Ἰβηρίαν ἀπὸ Πυρήνης ἕως τῆς ἑσπερίου πλευρᾶς. ὁ δ’ αὐτὸν τὸν Τάγον ποταμὸν ὀκτακισχιλίων τίθησι τὸ μῆκος ἀπὸ τῆς πηγῆς μέχρι τῶν ἐκβολῶν, οὐ δή που τὸ σὺν τοῖς σκολιώμασιν (οὐ γὰρ γεωγραφικὸν τοῦτο), ἀλλ’ ἐπ’ εὐθείας λέγων, καίτοι γε ἀπὸ Πυρήνης αἱ τοῦ Τάγου πηγαὶ πλέον διέχουσιν ἢ χιλίους σταδίους. πάλιν δὲ τοῦτο μὲν ὀρθῶς ἀποφαίνεται, ὅτι ἀγνοεῖ τὰ Ἰβηρικὰ ὁ Ἐρατοσθένης, καὶ διότι περὶ αὐτῆς ἔσθ’ ὅπου τὰ μαχόμενα ἀποφαίνεται· ὅς γε μέχρι Γαδείρων ὑπὸ Γαλατῶν περιοικεῖσθαι φήσας [τὰ] ἔξωθεν αὐτῆς, εἴ γε τὰ πρὸς δύσιν τῆς Εὐρώπης μέχρι Γαδείρων ἔχουσιν ἐκεῖνοι, τούτων ἐκλαθόμενος κατὰ τὴν τῆς Ἰβηρίας περίοδον τῶν Γαλατῶν οὐδαμοῦ μέμνηται.", "st": "2.4.4"}, {"sp": "N", "t": "τό [τε] μῆκος τῆς Εὐρώπης ὅτι ἔλαττόν ἐστι τοῦ συνάμφω τῆς τε Λιβύης καὶ τῆς Ἀσίας ἐκθείς, οὐκ ὀρθῶς τὴν σύγκρισιν ποιεῖται· τὸ μὲν γὰρ στόμα τὸ κατὰ στήλας φησὶν ὅτι κατὰ τὴν ἰσημερινὴν δύσιν ἐστίν, ὁ δὲ Τάναϊς ῥεῖ ἀπὸ θερινῆς ἀνατολῆς· ἐλαττοῦται δὴ τοῦ συνάμφω μήκους τῷ μεταξὺ τῆς θερινῆς ἀνατολῆς καὶ τῆς ἰσημερινῆς· τοῦτο γὰρ ἡ Ἀσία προλαμβάνει πρὸς τὴν ἰσημερινὴν ἀνατολὴν τοῦ πρὸς τὰς ἄρκτους ἡμικυκλίου. χωρὶς γὰρ τοῦ περισκελοῦς ἐν πράγμασιν εὐαποδότοις καὶ ψεῦδός ἐστι τὸ ἀπὸ θερινῆς ἀνατολῆς τὸν Τάναϊν ῥεῖν· ἅπαντες γὰρ οἱ ἔμπειροι τῶν τόπων ἀπὸ τῶν ἄρκτων ῥεῖν φασιν εἰς τὴν Μαιῶτιν, ὥστε τὰ στόματα τοῦ ποταμοῦ καὶ τὸ τῆς Μαιώτιδος καὶ αὐτὸν τὸν ποταμόν, ἐφ’ ὅσον γνώριμός ἐστιν, ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ κεῖσθαι.", "st": "2.4.5"}, {"sp": "N", "t": "οὐκ ἄξιοι δὲ λόγου τινὲς οἱ μὲν εἶπον ἀπὸ τῶν κατὰ τὸν Ἴστρον τόπων αὐτὸν τὰς ἀρχὰς ἔχειν καὶ ἀπὸ τῆς ἑσπέρας, οὐκ ἐνθυμηθέντες ὡς μεταξὺ ὁ Τύρας καὶ Βορυσθένης καὶ Ὕπανις μεγάλοι ποταμοὶ ῥέουσιν εἰς τὸν Πόντον, ὁ μὲν τῷ Ἴστρῳ παράλληλος οἱ δὲ τῷ Τανάιδι· οὔτε δὲ τοῦ Τύρα τῶν πηγῶν κατωπτευμένων οὔτε τοῦ Βορυσθένους οὔτε τοῦ Ὑπάνιος, πολὺ ἂν εἴη ἀγνωστότερα τὰ ἐκείνων ἀρκτικώτερα· ὥσθ’ ὁ δι’ ἐκείνων ἄγων ἐπὶ τὴν Μαιῶτιν τὸν Τάναϊν, εἶτ’ ἐπιστρέφων ἐπ’ αὐτήν (αἱ γὰρ ἐκβολαὶ φανερῶς ἐν τοῖς προσαρκτίοις μέρεσι τῆς λίμνης δείκνυνται καὶ τούτοις τοῖς ἑωθινωτάτοις), πλαστὸς ἄν τις εἴη καὶ ἀπέραντος λόγος. ὡς δ’ αὕτως ἀπέραντος καὶ ὁ διὰ τοῦ Καυκάσου πρὸς ἄρκτον φήσας ῥεῖν, εἶτ’ ἐπιστρέφειν εἰς τὴν Μαιῶτιν· εἴρηται γὰρ καὶ τοῦτο. ἀπὸ μέντοι τῆς ἀνατολῆς οὐδεὶς εἴρηκε τὴν ῥύσιν· καὶ γὰρ εἰ ἔρρει οὕτως, οὐκ ἂν ὑπεναντίως τῷ Νείλῳ καὶ τρόπον τινὰ κατὰ διάμετρον ῥεῖν αὐτὸν ἀπεφαίνοντο οἱ χαριέστεροι, ὡς ἂν ἐπὶ ταὐτοῦ μεσημβρινοῦ ἢ παρακειμένου τινὸς τῆς ῥύσεως οὔσης ἑκατέρῳ ποταμῷ.", "st": "2.4.6"}, {"sp": "N", "t": "̔́η τε τοῦ μήκους τῆς οἰκουμένης μέτρησις κατὰ παραλλήλου τῷ ἰσημερινῷ ἐστιν, ἐπειδὴ καὶ αὐτὴ ἐπὶ μῆκος οὕτως ἐκτέταται ὥστε καὶ τῶν ἠπείρων ἑκάστης οὕτω δεῖ λαμβάνειν τὸ μῆκος μεταξὺ μεσημβρινῶν δυεῖν κείμενον. τά τε μέτρα τῶν μηκῶν σταδιασμοί εἰσιν, οὓς θηρεύομεν, ἢ δι’ αὐτῶν ἐκείνων ἰόντες ἢ τῶν παραλλήλων ὁδῶν ἢ πόρων. ὁ δὲ τοῦτον ἀφεὶς τὸν τρόπον καινὸν εἰσάγει τὸ μεταξὺ τῆς τε θερινῆς ἀνατολῆς καὶ τῆς ἰσημερινῆς τμῆμά τι τοῦ ἀρκτικοῦ ἡμικυκλίου. πρὸς δὲ τὰ ἀμετάπτωτα οὐδεὶς κανόσι καὶ μέτροις χρῆται τοῖς μεταπτώτοις οὐδὲ τοῖς κατ’ ἄλλην καὶ ἄλλην σχέσιν λεγομένοις πρὸς τὰ καθ’ αὑτὰ καὶ * διαφοράν. τὸ μὲν οὖν μῆκος ἀμετάπτωτον καὶ καθ’ αὑτὸ λέγεται, ἀνατολὴ δ’ ἰσημερινὴ καὶ δύσις, ὡς δ’ αὕτως θερινή τε καὶ χειμερινή, οὐ καθ’ αὑτὴν ἀλλὰ πρὸς ἡμᾶς· ἡμῶν δ’ ἄλλοτ’ ἄλλῃ μεταχωρούντων, ἄλλοτ’ ἄλλοι τόποι καὶ δύσεών εἰσι καὶ ἀνατολῶν ἰσημερινῶν τε καὶ τροπικῶν, τὸ δὲ μῆκος μένει ταὐτὸν τῆς ἠπείρου. Τάναϊν μὲν οὖν καὶ Νεῖλον οὐκ ἄτοπον πέρας ποιεῖσθαι, θερινὴν δ’ ἀνατολὴν ἢ ἰσημερινὴν καινόν.", "st": "2.4.7"}, {"sp": "N", "t": "προπεπτωκυίας δὲ τῆς Εὐρώπης ἄκραις πλείοσι, βέλτιον μὲν οὗτος εἴρηκεν περὶ αὐτῶν Ἐρατοσθένους, οὔπω δὲ ἱκανῶς· ἐκεῖνος μὲν γὰρ τρεῖς ἔφη, τὴν ἐπὶ τὰς στήλας καθήκουσαν, ἐφ’ ἧς ἡ Ἰβηρία, καὶ τὴν ἐπὶ τὸν πορθμόν, ἐφ’ ἧς ἡ Ἰταλία, καὶ τρίτην τὴν κατὰ Μαλέας, ἐφ’ ἧς τὰ μεταξὺ τοῦ Ἀδρίου καὶ τοῦ Εὐξείνου πάντ’ ἔθνη καὶ τοῦ Τανάιδος. οὗτος δὲ τὰς μὲν δύο τὰς πρώτας ὁμοίως ἐκτίθεται, τρίτην δὲ τὴν κατὰ Μαλέας καὶ Σούνιον, ἐφ’ ἧς ἡ Ἑλλὰς πᾶσα καὶ ἡ Ἰλλυρὶς καὶ τῆς Θρᾴκης τινά, τετάρτην δὲ τὴν κατὰ τὴν Θρᾳκίαν χερρόνησον, ἐφ’ ἧς τὰ κατὰ Σηστὸν καὶ Ἄβυδον στενά (ἔχουσι δ’ αὐτὴν Θρᾷκες), πέμπτην δὲ τὴν κατὰ τὸν Κιμμερικὸν Βόσπορον καὶ τὸ στόμα τῆς Μαιώτιδος. τὰς μὲν οὖν δύο τὰς πρώτας δοτέον· ἁπλοῖς γάρ τισι περιλαμβάνονται κόλποις, ἡ μὲν τῷ μεταξὺ τῆς Κάλπης καὶ τοῦ ἱεροῦ ἀκρωτηρίου, ἐν ᾧ τὰ Γάδειρα, καὶ τῷ μεταξὺ στηλῶν καὶ τῆς Σικελίας πελάγει· ἡ δὲ τούτῳ τε καὶ τῷ Ἀδρίᾳ, καίτοι ἥ γε τῶν Ἰαπύγων ἄκρα παρεμπίπτουσα καὶ τὴν Ἰταλίαν δικόρυφον ποιοῦσα ἔχει τινὰ ἀντέμφασιν· αἱ λοιπαὶ δ’ ἔτι ἐναργέστερον ποικίλαι καὶ πολυμερεῖς οὖσαι ζητοῦσιν ἄλλην διαίρεσιν. ὡς δ’ αὕτως ἔχει καὶ ἡ εἰς ἓξ διαίρεσις τὴν ὁμοίαν ἔνστασιν ἀκολούθως ταῖς ἄκραις διειλημμένη. ποιησόμεθα δ’ ἡμεῖς ἐν τοῖς καθ’ ἕκαστα τὴν προσήκουσαν ἐπανόρθωσιν καὶ τούτων καὶ τῶν ἄλλων, ὅσα ἔν τε τῇ Εὐρώπῃ διημάρτηται καὶ ἐν τῇ τῆς Λιβύης περιοδείᾳ. νῦν δ’ ἀρκέσει ταῦτα λεχθέντα πρὸς τοὺς πρὸ ἡμῶν, ὅσους ᾠήθημεν ἱκανοὺς εἶναι παρατεθέντας ἐκμαρτυρεῖν ἡμῖν, ὅτι δικαίως προειλόμεθα καὶ αὐτοὶ τὸ αὐτὸ τοῦτο ἔργον τοσαύτης ἐπανορθώσεως καὶ προσθήκης δεόμενον.", "st": "2.4.8"}, {"sp": "N", "t": "Ἐπεὶ δὲ τοῖς πρὸς ἐκείνους λόγοις συνεχής ἐστιν ἡ ἐγχείρησις τῆς ἡμετέρας ὑποσχέσεως, λαβόντες ἀρχὴν ἑτέραν λέγωμεν, ὅτι δεῖ τὸν χωρογραφεῖν ἐπιχειροῦντα πολλὰ τῶν φυσικῶς τε καὶ μαθηματικῶς λεγομένων ὑποθέσθαι, καὶ πρὸς τὴν ἐκείνων ὑπόνοιάν τε καὶ πίστιν τὰ ἑξῆς πραγματεύεσθαι. εἴρηται γάρ, ὅτι οὐδ’ οἰκοδόμος, οὐδ’ ἀρχιτέκτων οἰκίαν ἢ πόλιν ἱδρῦσαι καλῶς οἷός τε γένοιτ’ ἂν ἀπρονοήτως ἔχων κλιμάτων τε τῶν κατὰ τὸν οὐρανὸν καὶ σχημάτων τε καὶ μεγεθῶν καὶ θάλπους καὶ ψύχους καὶ ἄλλων τοιούτων, μή τί γε τὴν ὅλην οἰκουμένην τοποθετῶν. αὐτὸ γὰρ τὸ εἰς ἐπίπεδον γράφειν ἐπιφάνειαν μίαν καὶ τὴν αὐτὴν τά τε Ἰβηρικὰ καὶ τὰ Ἰνδικὰ καὶ τὰ μέσα τούτων, καὶ μηδὲν ἧττον δύσεις καὶ ἀνατολὰς ἀφορίζειν καὶ μεσουρανήσεις ὡς ἂν κοινὰς πᾶσι, τῷ μὲν προεπινοήσαντι τὴν τοῦ οὐρανοῦ διάθεσίν τε καὶ κίνησιν καὶ λαβόντι, ὅτι σφαιρικὴ μέν ἐστιν ἡ κατ’ ἀλήθειαν τῆς γῆς ἐπιφάνεια, πλάττεται δὲ νῦν ἐπίπεδος πρὸς τὴν ὄψιν, γεωγραφικὴν ἔχει τὴν παράδοσιν, τῷ δ’ ἄλλως, οὐ γεωγραφικήν. οὐ γὰρ ὥσπερ διὰ πεδίων ἰοῦσι μεγάλων, οἷον τῶν Βαβυλωνίων, ἢ διὰ πελάγους παρίσταται τὰ πρόσω πάντα καὶ τὰ κατόπιν καὶ ἐκ πλαγίων ἐπίπεδα, καὶ οὐδεμίαν ἀντέμφασιν παρέχει πρὸς τὰ οὐράνια καὶ τὰς τοῦ ἡλίου κινήσεις καὶ σχέσεις πρὸς ἡμᾶς καὶ τῶν ἄλλων ἄστρων, οὕτω καὶ γεωγραφοῦσιν παρίστασθαι ἀεὶ δεῖ τὰ ὅμοια. ὁ μὲν γὰρ πελαγίζων ἢ ὁδεύων διὰ χώρας πεδιάδος κοιναῖς τισι φαντασίαις ἄγεται, καθ’ ἃς καὶ ὁ ἀπαίδευτος καὶ ὁ πολιτικὸς ἐνεργεῖ ταὐτά, ἄπειρος ὢν τῶν οὐρανίων καὶ τὰς πρὸς ταῦτα ἀντεμφάσεις ἀγνοῶν. ἀνατέλλοντα μὲν γὰρ ὁρᾷ ἥλιον καὶ δύνοντα καὶ μεσουρανοῦντα, τίνα δὲ τρόπον, οὐκ ἐπισκοπεῖ· οὐδὲ γὰρ χρήσιμον αὐτῷ πρὸς τὸ προκείμενον, ὥσπερ οὐδὲ τὸ παράλληλον ἑστάναι τῷ παρεστῶτι ἢ μή· τάχα δ’ ἐπισκοποῖ μὲν ἄν τι, δόξει δ’ ἐν τοῖς μαθηματικῶς λεγομένοις, καθάπερ οἱ ἐπιχώριοι· ἔχει γὰρ ὁ τόπος τοιαῦτα διαπτώματα. ὁ δὲ γεωγραφικὸς οὐκ ἐπιχωρίῳ γεωγραφεῖ, οὐδὲ πολιτικῷ τοιούτῳ, ὅστις μηδὲν ἐφρόντισε τῶν λεγομένων ἰδίως μαθημάτων· οὐδὲ γὰρ θεριστῇ καὶ σκαπανεῖ, ἀλλὰ τῷ πεισθῆναι δυναμένῳ τὴν γῆν ἔχειν οὕτω τὴν ὅλην, ὡς οἱ μαθηματικοί φασι, καὶ τὰ ἄλλα τὰ πρὸς τὴν ὑπόθεσιν τὴν τοιαύτην. κελεύει τε τοῖς προσιοῦσιν ἐκεῖνα προενθυμηθεῖσι τὰ ἑξῆς ἐφορᾶν· ἐκείνοις γὰρ τὰ ἀκόλουθα ἐρεῖν, ὥστε μᾶλλον ποιήσασθαι τῶν παραδιδομένων ἀσφαλῆ τὴν χρῆσιν τοὺς ἐντυγχάνοντας, ἂν ἀκούωσι μαθηματικῶς, τοῖς δ’ ἄλλως ἔχουσιν οὔ φησι γεωγραφεῖν.", "st": "2.5.1"}, {"sp": "N", "t": "τὸν μὲν δὴ γεωγραφοῦντα πιστεῦσαι δεῖ περὶ τῶν ἐχόντων αὐτῷ τάξιν ἀρχῆς τοῖς ἀναμετρήσασι τὴν ὅλην γῆν γεωμέτραις, τούτους δὲ τοῖς ἀστρονομικοῖς, ἐκείνους δὲ τοῖς φυσικοῖς. ἡ δὲ φυσικὴ ἀρετή τις· τὰς δ’ ἀρετὰς ἀνυποθέτους φασὶν ἐξ αὑτῶν ἠρτημένας, καὶ ἐν αὑταῖς ἐχούσας τάς τε ἀρχὰς καὶ τὰς περὶ τούτων πίστεις. τὰ μὲν οὖν παρὰ τῶν φυσικῶν δεικνύμενα τοιαῦτά ἐστι· σφαιροειδὴς μὲν ὁ κόσμος καὶ ὁ οὐρανός, ἡ ῥοπὴ δ’ ἐπὶ τὸ μέσον τῶν βαρέων· περὶ τοῦτό τε συνεστῶσα ἡ γῆ σφαιροειδῶς ὁμόκεντρος τῷ μὲν οὐρανῷ μένει καὶ αὐτὴ καὶ ὁ δι’ αὐτῆς ἄξων καὶ τοῦ οὐρανοῦ μέσου τεταμένος, ὁ δ’ οὐρανὸς περιφέρεται περί τε αὐτὴν καὶ περὶ τὸν ἄξονα ἀπ’ ἀνατολῆς ἐπὶ δύσιν, σὺν αὐτῷ δὲ οἱ ἀπλανεῖς ἀστέρες ὁμοταχεῖς τῷ πόλῳ. οἱ μὲν οὖν ἀπλανεῖς ἀστέρες κατὰ παραλλήλων φέρονται κύκλων· παράλληλοι δ’ εἰσὶ γνωριμώτατοι ὅ τε ἰσημερινὸς καὶ οἱ τροπικοὶ δύο καὶ οἱ ἀρκτικοί· οἱ δὲ πλάνητες ἀστέρες καὶ ἥλιος καὶ σελήνη κατὰ λοξῶν τινων τῶν τεταγμένων ἐν τῷ ζωδιακῷ. τούτοις δὲ πιστεύσαντες ἢ πᾶσιν ἢ τισὶν οἱ ἀστρονομικοὶ τὰ ἑξῆς πραγματεύονται, κινήσεις καὶ περιόδους καὶ ἐκλείψεις καὶ μεγέθη καὶ ἀποστάσεις καὶ ἄλλα μυρία· ὡς δ’ αὕτως οἱ τὴν γῆν ὅλην ἀναμετροῦντες γεωμέτραι προστίθενται ταῖς τῶν φυσικῶν καὶ τῶν ἀστρονομικῶν δόξαις, ταῖς δὲ τῶν γεωμετρῶν πάλιν οἱ γεωγράφοι.", "st": "2.5.2"}, {"sp": "N", "t": "πεντάζωνον μὲν γὰρ ὑποθέσθαι δεῖ τὸν οὐρανόν, πεντάζωνον δὲ καὶ τὴν γῆν, ὁμωνύμους δὲ καὶ τὰς ζώνας τὰς κάτω ταῖς ἄνω· τὰς δ’ αἰτίας εἰρήκαμεν τῆς εἰς τὰς ζώνας διαιρέσεως. διορίζοιντο δ’ ἂν αἱ ζῶναι κύκλοις παραλλήλοις τῷ ἰσημερινῷ γραφομένοις ἑκατέρωθεν αὐτοῦ, δυσὶ μὲν τοῖς ἀπολαμβάνουσι τὴν διακεκαυμένην, δυσὶ δὲ τοῖς μετὰ τούτους, οἳ πρὸς μὲν τῇ διακεκαυμένῃ τὰς εὐκράτους δύο ποιοῦσι, πρὸς δὲ ταῖς εὐκράτοις τὰς κατεψυγμένας. ὑποπίπτει δ’ ἑκάστῳ τῶν οὐρανίων κύκλων ὁ ἐπὶ γῆς ὁμώνυμος αὐτῷ, καὶ ἡ ζώνη δὲ ὡσαύτως τῇ ζώνῃ. εὐκράτους μὲν οὖν φασι τὰς οἰκεῖσθαι δυναμένας, ἀοικήτους δὲ τὰς ἄλλας, τὴν μὲν διὰ καῦμα τὰς δὲ διὰ ψῦχος. τὸν δ’ αὐτὸν τρόπον καὶ περὶ τῶν τροπικῶν καὶ τῶν ἀρκτικῶν, παρ’ οἷς εἰσιν ἀρκτικοί, διορίζουσιν ὁμωνύμως τοῖς ἄνω τοὺς ἐπὶ γῆς ποιοῦντες, καὶ τοὺς ἑκάστοις ὑποπίπτοντας. τοῦ δ’ ἰσημερινοῦ δίχα τέμνοντος τὸν ὅλον οὐρανόν, καὶ τὴν γῆν ἀνάγκη διαιρεῖσθαι ὑπὸ τοῦ ἐν αὐτῇ ἰσημερινοῦ. καλεῖται δὲ τῶν ἡμισφαιρίων ἑκάτερον τῶν τε οὐρανίων καὶ τῶν ἐπὶ γῆς τὸ μὲν βόρειον τὸ δὲ νότιον· οὕτως δὲ καὶ τῆς διακεκαυμένης ὑπὸ τοῦ αὐτοῦ κύκλου δίχα διαιρουμένης τὸ μὲν ἔσται βόρειον αὐτῆς μέρος τὸ δὲ νότιον· δῆλον δ’ ὅτι καὶ τῶν εὐκράτων ζωνῶν ἡ μὲν ἔσται βόρειος ἡ δὲ νότιος ὁμωνύμως τῷ ἡμισφαιρίῳ ἐν ᾧ ἐστι. καλεῖται δὲ βόρειον μὲν ἡμισφαίριον τὸ τὴν εὔκρατον ἐκείνην περιέχον, ἐν ᾗ ἀπὸ τῆς ἀνατολῆς βλέποντι ἐπὶ τὴν δύσιν ἐν δεξιᾷ μέν ἐστιν ὁ πόλος, ἐν ἀριστερᾷ δ’ ὁ ἰσημερινός, ἢ ἐν ᾧ πρὸς μεσημβρίαν βλέπουσιν ἐν δεξιᾷ μέν ἐστι δύσις ἐν ἀριστερᾷ δ’ ἀνατολή, νότιον δὲ τὸ ἐναντίως ἔχον· ὥστε δῆλον ὅτι ἡμεῖς ἐσμεν ἐν θατέρῳ τῶν ἡμισφαιρίων, καὶ τῷ βορείῳ γε, ἐν ἀμφοτέροις δ’ οὐχ οἷόν τε· “μέσσῳ γὰρ μεγάλοι ποταμοί, ὠκεανὸς μὲν πρῶτα,” ἔπειτα ἡ διακεκαυμένη. οὔτε δὲ ὠκεανὸς ἐν μέσῳ τῆς καθ’ ἡμᾶς οἰκουμένης ἐστὶ τέμνων ὅλην, οὔτ’ οὖν διακεκαυμένον χωρίον· οὐδὲ δὴ μέρος αὐτῆς εὑρίσκεται τοῖς κλίμασιν ὑπεναντίως ἔχον τοῖς λεχθεῖσιν ἐν τῇ βορείῳ εὐκράτῳ.", "st": "2.5.3"}, {"sp": "N", "t": "λαβὼν οὖν ταῦθ’ ὁ γεωμέτρης, προσχρησάμενος τοῖς ὑπὸ τοῦ ἀστρονομικοῦ δεικνυμένοις, ἐν οἷς οἵ τε παράλληλοι τῷ ἰσημερινῷ εὑρίσκονται οἱ καθ’ ἑκάστην τὴν οἴκησιν καὶ οἱ πρὸς ὀρθὰς τέμνοντες τούτους, γραφόμενοι δὲ διὰ τῶν πόλων, καταμετρεῖ τὴν μὲν οἰκήσιμον ἐμβατεύων, τὴν δ’ ἄλλην ἐκ τοῦ λόγου τῶν ἀποστάσεων. οὕτω δ’ ἂν εὑρίσκοι πόσον ἂν εἴη τὸ ἀπὸ τοῦ ἰσημερινοῦ μέχρι πόλου, ὅπερ ἐστὶ τεταρτημόριον τοῦ μεγίστου κύκλου τῆς γῆς· ἔχων δὲ τοῦτο ἔχει καὶ τὸ τετραπλάσιον αὐτοῦ, τοῦτο δ’ ἐστὶν ἡ περίμετρος τῆς γῆς. ὥσπερ οὖν ὁ μὲν τὴν γῆν ἀναμετρῶν παρὰ τοῦ ἀστρονομοῦντος ἔλαβε τὰς ἀρχάς, ὁ δὲ ἀστρονόμος παρὰ τοῦ φυσικοῦ, τὸν αὐτὸν τρόπον χρὴ καὶ τὸν γεωγράφον παρὰ τοῦ ἀναμεμετρηκότος ὅλην τὴν γῆν ὁρμηθέντα, πιστεύσαντα τούτῳ καὶ οἷς ἐπίστευσεν οὗτος, πρῶτον μὲν ἐκθέσθαι τὴν οἰκουμένην καθ’ ἡμᾶς πόση τις καὶ ποία τὸ σχῆμα καὶ τὴν φύσιν οἵα ἐστὶ καὶ πῶς ἔχουσα πρὸς τὴν ὅλην γῆν (ἴδιον γὰρ τοῦ γεωγράφου τοῦτο), ἔπειτα περὶ τῶν καθ’ ἕκαστα τῶν τε κατὰ γῆν καὶ τῶν κατὰ θάλατταν ποιήσασθαι τὸν προσήκοντα λόγον, παρασημαινόμενον ὅσα μὴ ἱκανῶς εἴρηται τοῖς πρὸ ἡμῶν τοῖς μάλιστα πεπιστευμένοις ἀρίστοις γεγονέναι περὶ ταῦτα.", "st": "2.5.4"}, {"sp": "N", "t": "̔υποκείσθω δὴ σφαιροειδὴς ἡ γῆ σὺν τῇ θαλάττῃ, μίαν καὶ τὴν αὐτὴν ἐπιφάνειαν ἴσχουσα τοῖς πελάγεσι. συγκρύπτοιτο γὰρ ἂν τὸ ἐξέχον τῆς γῆς ἐν τῷ τοσούτῳ μεγέθει μικρὸν ὂν καὶ λανθάνειν δυνάμενον, ὥστε τὸ σφαιροειδὲς ἐπὶ τούτων οὐχ ὡς ἂν ἐκ τόρνου φαμέν, οὐδ’ ὡς ὁ γεωμέτρης πρὸς λόγον, ἀλλὰ πρὸς αἴσθησιν καὶ ταύτην παχυτέραν. νοείσθω δὴ πεντάζωνος καὶ ὁ ἰσημερινὸς τεταγμένος ἐν αὐτῇ κύκλος, καὶ ἄλλος τούτῳ παράλληλος, ὁρίζων τὴν κατεψυγμένην ἐν τῷ βορείῳ ἡμισφαιρίῳ, καὶ διὰ τῶν πόλων τις τέμνων τούτους πρὸς ὀρθάς. τοῦ δὴ βορείου ἡμισφαιρίου δύο περιέχοντος τεταρτημόρια τῆς γῆς, ἃ ποιεῖ ὁ ἰσημερινὸς πρὸς τὸν διὰ τῶν πόλων, ἐν ἑκατέρῳ τούτων ἀπολαμβάνεται τετράπλευρον χωρίον, οὗ ἡ μὲν βόρειος πλευρὰ ἥμισυ τοῦ πρὸς τῷ πόλῳ παραλλήλου ἐστίν, ἡ δὲ νότιος τοῦ ἰσημερινοῦ ἥμισυ, αἱ δὲ λοιπαὶ πλευραὶ τμήματά εἰσι τοῦ διὰ τῶν πόλων ἀντικείμενα ἀλλήλοις, ἴσα τὸ μῆκος. ἐν θατέρῳ δὴ τῶν τετραπλεύρων τούτων (ὁποτέρῳ δ’ οὐδὲν ἂν διαφέρειν δόξειεν) ἱδρῦσθαί φαμεν τὴν καθ’ ἡμᾶς οἰκουμένην περίκλυστον θαλάττῃ καὶ ἐοικυῖαν νήσῳ· εἴρηται γὰρ ὅτι καὶ τῇ αἰσθήσει καὶ τῷ λόγῳ δείκνυται τοῦτο. εἰ δ’ ἀπιστεῖ τις τῷ λόγῳ τούτῳ, διαφέροι ἂν πρὸς τὴν γεωγραφίαν οὐδὲν νῆσον ποιεῖν, ἢ ὅπερ ἐκ τῆς πείρας ἐλάβομεν τούτῳ συγχωρεῖν, ὅτι καὶ ἀπὸ τῆς ἠοῦς ἑκατέρωθεν περίπλους ἐστὶ καὶ ἀπὸ τῆς ἑσπέρας πλὴν ὀλίγων τῶν μέσων χωρίων. ταῦτα δ’ οὐ διαφέρει θαλάττῃ περατοῦσθαι ἢ γῇ ἀοικήτῳ· ὁ γὰρ γεωγραφῶν ζητεῖ τὰ γνώριμα μέρη τῆς οἰκουμένης εἰπεῖν, τὰ δ’ ἄγνωστα ἐᾷ καθάπερ καὶ τὰ ἔξω αὐτῆς. ἀρκέσει δ’ ἐπιζεύξασιν εὐθεῖαν γραμμὴν ἐπὶ τὰ ὕστατα σημεῖα τοῦ ἑκατέρωθεν παράπλου τὸ πᾶν ἐκπληρῶσαι σχῆμα τῆς λεγομένης νήσου.", "st": "2.5.5"}, {"sp": "N", "t": "προκείσθω δὴ ἡ μὲν νῆσος ἐν τῷ λεχθέντι τετραπλεύρῳ. δεῖ δὲ λαβεῖν τὸ μέγεθος αὐτῆς τὸ φαινόμενον, ἀφελόντας ἀπὸ μὲν τοῦ ὅλου μεγέθους τῆς γῆς τὸ ἡμισφαίριον τὸ καθ’ ἡμᾶς, ἀπὸ δὲ τούτου τὸ ἥμισυ, ἀπὸ δ’ αὖ τούτου πάλιν τὸ τετράπλευρον, ἐν ᾧ δὴ τὴν οἰκουμένην κεῖσθαί φαμεν. ἀνάλογον δὲ καὶ περὶ τοῦ σχήματος ὑπολαβεῖν δεῖ τὸ φαινόμενον τοῖς ὑποκειμένοις ἐφαρμόττοντας. ἀλλ’ ἐπειδὴ τὸ μεταξὺ τοῦ ἰσημερινοῦ καὶ τοῦ ληφθέντος παραλλήλου τούτῳ πρὸς τῷ πόλῳ τμῆμα τοῦ βορείου ἡμισφαιρίου σπόνδυλός ἐστι τὸ σχῆμα, ὁ δὲ διὰ τοῦ πόλου δίχα τέμνων τὸ ἡμισφαίριον δίχα τέμνει καὶ τὸν σπόνδυλον καὶ ποιεῖ τὸ τετράπλευρον, ἔσται δῆλον ὅτι σπονδύλου ἐπιφανείας ἥμισυ τὸ τετράπλευρον, ᾧ ἐπίκειται τὸ Ἀτλαντικὸν πέλαγος, ἡ δ’ οἰκουμένη χλαμυδοειδὴς ἐν τούτῳ νῆσος, ἔλαττον ἢ ἥμισυ τοῦ τετραπλεύρου μέρος οὖσα. φανερὸν δὲ τοῦτο ἔκ τε γεωμετρίας καὶ τοῦ πλήθους τῆς περικεχυμένης θαλάττης, καλυπτούσης τὰ ἄκρα τῶν ἠπείρων ἑκατέρωθεν καὶ συναγούσης εἰς μύουρον σχῆμα, καὶ τρίτου τοῦ μήκους καὶ πλάτους τοῦ μεγίστου, ὧν τὸ μὲν ἑπτὰ μυριάδων σταδίων ἐστίν, ὡς ἐπὶ τὸ πολὺ περατούμενον θαλάττῃ μηκέτι πλεῖσθαι δυναμένῃ διὰ τὸ μέγεθος καὶ τὴν ἐρημίαν, τὸ * δ’ ἔλαττον τριῶν μυριάδων ὁριζόμενον τῷ ἀοικήτῳ διὰ θάλπος ἢ ψῦχος. αὐτὸ γὰρ τὸ διὰ θάλπος ἀοίκητον τοῦ τετραπλεύρου, πλάτος μὲν ἔχον ὀκτακισχιλίων καὶ ὀκτακοσίων σταδίων, μῆκος δὲ τὸ μέγιστον μυριάδων δώδεκα καὶ ἑξακισχιλίων, ὅσον ἐστὶν ἥμισυ τοῦ ἰσημερινοῦ … πλέον ἂν εἴη τὸ λοιπόν.", "st": "2.5.6"}, {"sp": "N", "t": "τούτοις δὲ συνῳδά πώς ἐστι καὶ τὰ ὑπὸ Ἱππάρχου λεγόμενα· φησὶ γὰρ ἐκεῖνος, ὑποθέμενος τὸ μέγεθος τῆς γῆς ὅπερ εἶπεν Ἐρατοσθένης, ἐντεῦθεν δεῖν ποιεῖσθαι τὴν τῆς οἰκουμένης ἀφαίρεσιν· οὐ γὰρ πολὺ διοίσειν πρὸς τὰ φαινόμενα τῶν οὐρανίων καθ’ ἑκάστην τὴν οἴκησιν οὕτως ἔχειν τὴν ἀναμέτρησιν, ἢ ὡς οἱ ὕστερον ἀποδεδώκασιν. ὄντος δὴ κατ’ Ἐρατοσθένη τοῦ ἰσημερινοῦ κύκλου σταδίων μυριάδων πέντε καὶ εἴκοσι καὶ δισχιλίων, τὸ τεταρτημόριον εἴη ἂν ἓξ μυριάδες καὶ τρισχίλιοι· τοῦτο δέ ἐστι τὸ ἀπὸ τοῦ ἰσημερινοῦ ἐπὶ τὸν πόλον πεντεκαίδεκα ἑξηκοντάδων, οἵων ἐστὶν ὁ ἰσημερινὸς ἑξήκοντα, τὸ δ’ ἀπὸ τοῦ ἰσημερινοῦ ἐπὶ τὸν θερινὸν τροπικὸν τεττάρων· οὗτος δ’ ἐστὶν ὁ διὰ Συήνης γραφόμενος παράλληλος. συλλογίζεται δὴ τὰ καθ’ ἕκαστα διαστήματα ἐκ τῶν φαινομένων μέτρων· τὸν μὲν γὰρ τροπικὸν κατὰ Συήνην κεῖσθαι συμβαίνει, διότι ἐνταῦθα κατὰ τὰς θερινὰς τροπὰς ἄσκιός ἐστιν ὁ γνώμων μέσης ἡμέρας· ὁ δὲ διὰ τῆς Συήνης μεσημβρινὸς γράφεται μάλιστα διὰ τῆς τοῦ Νείλου ῥύσεως ἀπὸ Μερόης ἕως Ἀλεξανδρείας· στάδιοι δ’ εἰσὶν οὗτοι περὶ μυρίους· κατὰ μέσον δὲ τὸ διάστημα τὴν Συήνην ἱδρῦσθαι συμβαίνει, ὥστ’ ἐντεῦθεν ἐπὶ Μερόην πεντακισχίλιοι. προϊόντι δ’ ἐπ’ εὐθείας ὅσον τρισχιλίους σταδίους ἐπὶ μεσημβρίαν οὐκέτ’ οἰκήσιμα τἆλλά ἐστι διὰ καῦμα, ὥστε τὸν διὰ τούτων τῶν τόπων παράλληλον, τὸν αὐτὸν ὄντα τῷ διὰ τῆς Κινναμωμοφόρου, πέρας καὶ ἀρχὴν δεῖ τίθεσθαι τῆς καθ’ ἡμᾶς οἰκουμένης πρὸς μεσημβρίαν. ἐπεὶ οὖν πεντακισχίλιοι μέν εἰσιν οἱ ἀπὸ Συήνης εἰς Μερόην, ἄλλοι δὲ προσγεγόνασι τρισχίλιοι, εἶεν ἂν οἱ πάντες ἐπὶ τοὺς ὅρους τῆς οἰκουμένης ὀκτακισχίλιοι. ἐπὶ δέ γε τὸν ἰσημερινὸν ἀπὸ Συήνης μύριοι ἑξακισχίλιοι ὀκτακόσιοι (τοσοῦτοι γάρ εἰσιν οἱ τῶν τεττάρων ἑξηκοντάδων, τεθείσης ἑκάστης τετρακισχιλίων καὶ διακοσίων), ὥστε λοιποὶ εἶεν ἂν ἀπὸ τῶν ὅρων τῆς οἰκουμένης ἐπὶ τὸν ἰσημερινὸν ὀκτακισχίλιοι ὀκτακόσιοι, ἀπὸ δὲ Ἀλεξανδρείας δισμύριοι χίλιοι ὀκτακόσιοι. πάλιν δ’ ἀπὸ τῆς Ἀλεξανδρείας ἐπ’ εὐθείας τῇ ῥύσει τοῦ Νείλου πάντες ὁμολογοῦσι τὸν ἐπὶ Ῥόδον πλοῦν κἀντεῦθεν δὲ τὸν τῆς Καρίας παράπλουν καὶ Ἰωνίας μέχρι τῆς Τρῳάδος καὶ Βυζαντίου καὶ Βορυσθένους. λαβόντες οὖν τὰ διαστήματα γνώριμα καὶ πλεόμενα σκοποῦσι τὰ ὑπὲρ τοῦ Βορυσθένους ἐπ’ εὐθείας ταύτῃ τῇ γραμμῇ μέχρι τίνος οἰκήσιμά ἐστι, καὶ περατοῖ τὰ προσάρκτια μέρη τῆς οἰκουμένης. οἰκοῦσι δ’ ὑπὲρ τοῦ Βορυσθένους ὕστατοι τῶν γνωρίμων Σκυθῶν Ῥωξολανοί, νοτιώτεροι ὄντες τῶν ὑπὲρ τῆς Βρεττανικῆς ἐσχάτων γνωριζομένων· ἤδη δὲ τἀπέκεινα διὰ ψῦχος ἀοίκητά ἐστι· νοτιώτεροι δὲ τούτων καὶ οἱ ὑπὲρ τῆς Μαιώτιδος Σαυρομάται καὶ Σκύθαι μέχρι τῶν ἑῴων Σκυθῶν.", "st": "2.5.7"}, {"sp": "N", "t": "̔ο μὲν οὖν Μασσαλιώτης Πυθέας τὰ περὶ Θούλην τὴν βορειοτάτην τῶν Βρεττανίδων ὕστατα λέγει, παρ’ οἷς ὁ αὐτός ἐστι τῷ ἀρκτικῷ ὁ θερινὸς τροπικὸς κύκλος· παρὰ δὲ τῶν ἄλλων οὐδὲν ἱστορῶ, οὔθ’ ὅτι Θούλη νῆσός ἐστί τις οὔτ’ εἰ τὰ μέχρι δεῦρο οἰκήσιμά ἐστιν, ὅπου ὁ θερινὸς τροπικὸς ἀρκτικὸς γίνεται. νομίζω δὲ πολὺ εἶναι νοτιώτερον τοῦτο τὸ τῆς οἰκουμένης πέρας τὸ προσάρκτιον· οἱ γὰρ νῦν ἱστοροῦντες περαιτέρω τῆς Ἰέρνης οὐδὲν ἔχουσι λέγειν, ἣ πρὸς ἄρκτον πρόκειται τῆς Βρεττανικῆς πλησίον, ἀγρίων τελέως ἀνθρώπων καὶ κακῶς οἰκούντων διὰ ψῦχος, ὥστ’ ἐνταῦθα νομίζω τὸ πέρας εἶναι θετέον. τοῦ δὲ παραλλήλου τοῦ διὰ Βυζαντίου διὰ Μασσαλίας πως ἰόντος, ὥς φησιν Ἵππαρχος πιστεύσας Πυθέᾳ (φησὶ γὰρ ἐν Βυζαντίῳ τὸν αὐτὸν εἶναι λόγον τοῦ γνώμονος πρὸς τὴν σκιάν, ὃν εἶπεν ὁ Πυθέας ἐν Μασσαλίᾳ), τοῦ δὲ διὰ Βορυσθένους ἀπὸ τούτου διέχοντος περὶ τρισχιλίους καὶ ὀκτακοσίους, εἴη ἂν ἐκ τοῦ διαστήματος τοῦ ἀπὸ Μασσαλίας ἐπὶ τὴν Βρεττανικὴν ἐνταῦθά που πίπτων ὁ διὰ τοῦ Βορυσθένους κύκλος. πανταχοῦ δὲ παρακρουόμενος τοὺς ἀνθρώπους ὁ Πυθέας κἀνταῦθά που διέψευσται· τὸ μὲν γὰρ τὴν ἀπὸ στηλῶν γραμμὴν ἐπὶ τοὺς περὶ τὸν πορθμὸν καὶ Ἀθήνας καὶ Ῥόδον τόπους ἐπὶ τοῦ αὐτοῦ παραλλήλου κεῖσθαι ὡμολόγηται παρὰ πολλῶν· ὁμολογεῖται δὲ ὅτι καὶ διὰ μέσου πως τοῦ πελάγους ἐστὶν ἡ ἀπὸ στηλῶν ἐπὶ τὸν πορθμόν. οἱ δὲ πλέοντες τὸ μέγιστον δίαρμα ἀπὸ τῆς Κελτικῆς ἐπὶ τὴν Λιβύην εἶναι τὸ ἀπὸ τοῦ Γαλατικοῦ κόλπου σταδίων πεντακισχιλίων, τοῦτο δ’ εἶναι καὶ τὸ μέγιστον πλάτος τοῦ πελάγους, ὥστ’ εἴη ἂν τὸ ἀπὸ τῆς λεχθείσης γραμμῆς ἐπὶ τὸν μυχὸν τοῦ κόλπου σταδίων δισχιλίων πεντακοσίων, ἐπὶ δὲ Μασσαλίαν ἐλαττόνων· νοτιωτέρα γάρ ἐστιν ἡ Μασσαλία τοῦ μυχοῦ τοῦ κόλπου. τὸ δέ γε ἀπὸ τῆς Ῥοδίας ἐπὶ τὸ Βυζάντιον ἐστὶ τετρακισχιλίων που καὶ ἐνακοσίων σταδίων, ὥστε πολὺ ἀρκτικώτερος ἂν εἴη ὁ διὰ Βυζαντίου τοῦ διὰ Μασσαλίας. τὸ δ’ ἐκεῖθεν ἐπὶ τὴν Βρεττανικὴν δύναται συμφωνεῖν τῷ ἀπὸ Βυζαντίου ἐπὶ Βορυσθένη· τὸ δ’ ἐκεῖθεν ἐπὶ τὴν Ἰέρνην οὐκέτι γνώριμον πόσον ἄν τις θείη, οὐδ’ εἰ περαιτέρω ἔτι οἰκήσιμά ἐστιν, οὐδὲ δεῖ φροντίζειν τοῖς ἐπάνω λεχθεῖσι [προσέχοντας]· πρός τε γὰρ ἐπιστήμην ἀρκεῖ τὸ λαβεῖν, καθάπερ ἐπὶ τῶν νοτίων μερῶν, ὅτι ὑπὲρ Μερόης μέχρι τρισχιλίων σταδίων προελθόντι τῆς οἰκησίμου τίθεσθαι [πέρας] προσῆκεν (οὐχ ὡς ἂν τούτου ἀκριβεστάτου πέρατος ὄντος, ἀλλ’ ἐγγύς γε τἀκριβοῦς), οὕτω κἀκεῖ τοὺς ὑπὲρ τῆς Βρεττανικῆς οὐ πλείους τούτων θετέον ἢ μικρῷ πλείους, οἷον τετρακισχιλίους. πρός τε τὰς ἡγεμονικὰς χρείας οὐδὲν ἂν εἴη πλεονέκτημα τὰς τοιαύτας γνωρίζειν χώρας καὶ τοὺς ἐνοικοῦντας, καὶ μάλιστα εἰ νήσους οἰκοῖεν τοιαύτας, αἳ μήτε λυπεῖν μήτ’ ὠφελεῖν ἡμᾶς δύνανται μηδὲν διὰ τὸ ἀνεπίπλεκτον· καὶ γὰρ τὴν Βρεττανικὴν ἔχειν δυνάμενοι Ῥωμαῖοι κατεφρόνησαν, ὁρῶντες ὅτι οὔτε φόβος ἐξ αὐτῶν οὐδὲ εἷς ἐστιν (οὐ γὰρ ἰσχύουσι τοσοῦτον ὥστ’ ἐπιδιαβαίνειν ἡμῖν) οὔτ’ ὠφέλεια τοσαύτη τις, εἰ κατάσχοιεν. πλέον γὰρ ἐκ τῶν τελῶν δοκεῖ προσφέρεσθαι νῦν ἢ ὁ φόρος δύναται συντελεῖν, ἀφαιρουμένης τῆς εἰς τὸ στρατιωτικὸν δαπάνης τὸ φρουρῆσον καὶ φορολογῆσον τὴν νῆσον· πολὺ δ’ ἂν ἐπιγένοιτο τὸ ἄχρηστον ἐπὶ τῶν ἄλλων τῶν περὶ ταύτην νήσων.", "st": "2.5.8"}, {"sp": "N", "t": "εἰ δὲ προστεθείη τῷ ἀπὸ τῆς Ῥοδίας μέχρι Βορυσθένους διαστήματι τὸ ἀπὸ Βορυσθένους ἐπὶ τὰς ἄρκτους τῶν τετρακισχιλίων σταδίων διάστημα, γίνεται τὸ πᾶν μύριοι δισχίλιοι ἑπτακόσιοι στάδιοι, τὸ δ’ ἀπὸ τῆς Ῥοδίας ἐπὶ τὸ νότιον πέρας ἐστὶ τῆς οἰκουμένης μύριοι ἑξακισχίλιοι ἑξακόσιοι, ὥστε τὸ σύμπαν πλάτος τῆς οἰκουμένης εἴη ἂν ἔλαττον τῶν τρισμυρίων ἀπὸ νότου πρὸς ἄρκτον· τὸ δέ γε μῆκος περὶ ἑπτὰ μυριάδας λέγεται, τοῦτο δ’ ἐστὶν ἀπὸ δύσεως ἐπὶ τὰς ἀνατολὰς τὸ ἀπὸ τῶν ἄκρων τῆς Ἰβηρίας ἐπὶ τὰ ἄκρα τῆς Ἰνδικῆς, τὸ μὲν ὁδοῖς τὸ δὲ ταῖς ναυτιλίαις ἀναμεμετρημένον. ὅτι δ’ ἐντὸς τοῦ λεχθέντος τετραπλεύρου τὸ μῆκός ἐστι τοῦτο, ἐκ τοῦ λόγου τῶν παραλλήλων πρὸς τὸν ἰσημερινὸν δῆλον, ὥστε πλέον ἢ διπλάσιόν ἐστι τοῦ πλάτους τὸ μῆκος. λέγεται δὲ καὶ χλαμυδοειδές πως τὸ σχῆμα· πολλὴ γὰρ συναγωγὴ τοῦ πλάτους πρὸς τοῖς ἄκροις εὑρίσκεται καὶ μάλιστα τοῖς ἑσπερίοις, τὰ καθ’ ἕκαστα ἐπιόντων ἡμῶν.", "st": "2.5.9"}, {"sp": "N", "t": "νυνὶ μὲν οὖν ἐπιγεγράφαμεν ἐπὶ σφαιρικῆς ἐπιφανείας τὸ χωρίον, ἐν ᾧ φαμεν ἱδρῦσθαι τὴν οἰκουμένην· καὶ δεῖ τὸν ἐγγυτάτω διὰ τῶν χειροκμήτων σχημάτων μιμούμενον τὴν ἀλήθειαν ποιήσαντα σφαῖραν τὴν γῆν, καθάπερ τὴν Κρατήτειον, ἐπὶ ταύτης ἀπολαβόντα τὸ τετράπλευρον ἐντὸς τούτου τιθέναι τὸν πίνακα τῆς γεωγραφίας. ἀλλ’ ἐπειδὴ μεγάλης δεῖ σφαίρας, ὥστε πολλοστημόριον αὐτῆς ὑπάρχον τὸ λεχθὲν τμῆμα ἱκανὸν γενέσθαι δέξασθαι σαφῶς τὰ προσήκοντα μέρη τῆς οἰκουμένης, καὶ τὴν οἰκείαν παρασχεῖν ὄψιν τοῖς ἐπιβλέπουσι, τῷ μὲν δυναμένῳ κατασκευάσασθαι τηλικαύτην οὕτω ποιεῖν βέλτιον· ἔστω δὲ μὴ μείω δέκα ποδῶν ἔχουσα τὴν διάμετρον· τῷ δὲ μὴ δυναμένῳ τηλικαύτην ἢ μὴ πολλῷ ταύτης ἐνδεεστέραν ἐν ἐπιπέδῳ καταγραπτέον πίνακι τοὐλάχιστον ἑπτὰ ποδῶν. διοίσει γὰρ μικρόν, ἐὰν ἀντὶ τῶν κύκλων τῶν τε παραλλήλων καὶ τῶν μεσημβρινῶν, οἷς τά τε κλίματα καὶ τοὺς ἀνέμους διασαφοῦμεν καὶ τὰς ἄλλας διαφορὰς καὶ τὰς σχέσεις τῶν τῆς γῆς μερῶν πρὸς ἄλληλά τε καὶ τὰ οὐράνια, εὐθείας γράφωμεν, τῶν μὲν παραλλήλων παραλλήλους, τῶν δὲ ὀρθῶν πρὸς ἐκείνους ὀρθάς, τῆς διανοίας ῥᾳδίως μεταφέρειν δυναμένης τὸ ὑπὸ τῆς ὄψεως ἐν ἐπιπέδῳ θεωρούμενον ἐπιφανείᾳ σχῆμα καὶ μέγεθος ἐπὶ τὴν περιφερῆ τε καὶ σφαιρικήν. ἀνάλογον δὲ καὶ περὶ τῶν λοξῶν κύκλων καὶ εὐθειῶν φαμεν. εἰ δ’ οἱ μεσημβρινοὶ οἱ παρ’ ἑκάστοις [διὰ] τοῦ πόλου γραφόμενοι πάντες συννεύουσιν ἐν τῇ σφαίρᾳ πρὸς ἓν σημεῖον, ἀλλ’ ἐν τῷ ἐπιπέδῳ γε οὐ διοίσει πίνακι τὰς εὐθείας μικρὰς συννευούσας ποιεῖν μόνον τὰς μεσημβρινάς· οὐδὲ γὰρ πολλαχοῦ τοῦτ’ ἀναγκαῖον, οὐδ’ ἐκφανής ἐστιν ὥσπερ ἡ περιφέρεια οὕτω καὶ ἡ σύννευσις, μεταφερομένων τῶν γραμμῶν εἰς τὸν πίνακα τὸν ἐπίπεδον καὶ γραφομένων εὐθειῶν.", "st": "2.5.10"}, {"sp": "N", "t": "καὶ δὴ καὶ τὸν ἑξῆς λόγον ὡς ἐν ἐπιπέδῳ πίνακι τῆς γραφῆς γινομένης ἐκθήσομεν. ἐροῦμεν δὴ τὴν μὲν ἐπελθόντες αὐτοὶ τῆς γῆς καὶ θαλάττης, περὶ ἧς δὲ πιστεύσαντες τοῖς εἰποῦσιν ἢ γράψασιν. ἐπήλθομεν δὲ ἐπὶ δύσιν μὲν ἀπὸ τῆς Ἀρμενίας μέχρι τῶν κατὰ Σαρδόνα τόπων τῆς Τυρρηνίας, ἐπὶ μεσημβρίαν δὲ ἀπὸ τοῦ Εὐξείνου μέχρι τῶν τῆς Αἰθιοπίας ὅρων· οὐδὲ τῶν ἄλλων δὲ οὐδὲ εἷς ἂν εὑρεθείη τῶν γεωγραφησάντων πολύ τι ἡμῶν μᾶλλον ἐπεληλυθὼς τῶν λεχθέντων διαστημάτων, ἀλλ’ οἱ πλεονάσαντες περὶ τὰ δυσμικὰ μέρη τῶν πρὸς ταῖς ἀνατολαῖς οὐ τοσοῦτον ἥψαντο, οἱ δὲ περὶ τἀναντία τῶν ἑσπερίων ὑστέρησαν· ὁμοίως δ’ ἔχει καὶ περὶ τῶν πρὸς νότον καὶ τὰς ἄρκτους. τὸ μέντοι πλέον κἀκεῖνοι καὶ ἡμεῖς ἀκοῇ παραλαβόντες συντίθεμεν καὶ τὸ σχῆμα καὶ τὸ μέγεθος καὶ τὴν ἄλλην φύσιν ὁποία καὶ ὁπόση, τὸν αὐτὸν τρόπον ὅνπερ ἡ διάνοια ἐκ τῶν αἰσθητῶν συντίθησι τὰ νοητά· σχῆμα γὰρ καὶ χρόαν καὶ μέγεθος μήλου καὶ ὀδμὴν καὶ ἁφὴν καὶ χυμὸν ἀπαγγέλλουσιν αἱ αἰσθήσεις, ἐκ δὲ τούτων συντίθησιν ἡ διάνοια τὴν τοῦ μήλου νόησιν· καὶ αὐτῶν δὲ τῶν μεγάλων σχημάτων τὰ μέρη μὲν αἴσθησις ὁρᾷ, τὸ δ’ ὅλον ἐκ τῶν ὁραθέντων ἡ διάνοια συντίθησιν. οὕτω δὲ καὶ οἱ φιλομαθεῖς ἄνδρες ὥσπερ αἰσθητηρίοις πιστεύσαντες τοῖς ἰδοῦσι καὶ πλανηθεῖσιν οὓς ἔτυχε τόπους ἄλλοις κατ’ ἄλλα μέρη τῆς γῆς, συντιθέασιν εἰς ἓν διάγραμμα τὴν τῆς ὅλης οἰκουμένης ὄψιν· ἐπεὶ καὶ οἱ στρατηγοὶ πάντα μὲν αὐτοὶ πράττουσιν, οὐ πανταχοῦ δὲ πάρεισιν, ἀλλὰ πλεῖστα κατορθοῦσι δι’ ἑτέρων, ἀγγέλοις πιστεύοντες καὶ πρὸς τὴν ἀκοὴν διαπέμποντες οἰκείως τὰ προστάγματα. ὁ δ’ ἀξιῶν μόνους εἰδέναι τοὺς ἰδόντας ἀναιρεῖ τὸ τῆς ἀκοῆς κριτήριον, ἥτις πρὸς ἐπιστήμην ὀφθαλμοῦ πολὺ κρείττων ἐστί.", "st": "2.5.11"}, {"sp": "N", "t": "μάλιστα δ’ οἱ νῦν ἄμεινον ἔχοιεν ἄν τι λέγειν περὶ τῶν κατὰ Βρεττανοὺς καὶ Γερμανοὺς καὶ τοὺς περὶ τὸν Ἴστρον τούς τε ἐντὸς καὶ τοὺς ἐκτὸς Γέτας τε καὶ Τυρεγέτας καὶ Βαστάρνας, ἔτι δὲ τοὺς περὶ τὸν Καύκασον, οἷον Ἀλβανοὺς καὶ Ἴβηρας. ἀπήγγελται δ’ ἡμῖν καὶ ὑπὸ τῶν τὰ Παρθικὰ συγγραψάντων, τῶν περὶ Ἀπολλόδωρον τὸν Ἀρτεμιτηνόν, ἃ πολλῶν ἐκεῖνοι μᾶλλον ἀφώρισαν, τὰ περὶ τὴν Ὑρκανίαν καὶ τὴν Βακτριανήν· τῶν τε Ῥωμαίων καὶ εἰς τὴν εὐδαίμονα Ἀραβίαν ἐμβαλόντων μετὰ στρατιᾶς νεωστί, ἧς ἡγεῖτο ἀνὴρ φίλος ἡμῖν καὶ ἑταῖρος Αἴλιος Γάλλος, καὶ τῶν ἐκ τῆς Ἀλεξανδρείας ἐμπόρων στόλοις ἤδη πλεόντων διὰ τοῦ Νείλου καὶ τοῦ Ἀραβίου κόλπου μέχρι τῆς Ἰνδικῆς, πολὺ μᾶλλον καὶ ταῦτα ἔγνωσται τοῖς νῦν ἢ τοῖς πρὸ ἡμῶν. ὅτε γοῦν Γάλλος ἐπῆρχε τῆς Αἰγύπτου, συνόντες αὐτῷ καὶ συναναβάντες μέχρι Συήνης καὶ τῶν Αἰθιοπικῶν ὅρων ἱστοροῦμεν, ὅτι καὶ ἑκατὸν καὶ εἴκοσι νῆες πλέοιεν ἐκ Μυὸς ὅρμου πρὸς τὴν Ἰνδικήν, πρότερον ἐπὶ τῶν Πτολεμαϊκῶν βασιλέων ὀλίγων παντάπασι θαρρούντων πλεῖν καὶ τὸν Ἰνδικὸν ἐμπορεύεσθαι φόρτον.", "st": "2.5.12"}, {"sp": "N", "t": "τὰ μὲν οὖν πρῶτα καὶ κυριώτατα καὶ πρὸς ἐπιστήμην καὶ πρὸς τὰς χρείας τὰς πολιτικὰς ταῦτα, σχῆμα καὶ μέγεθος εἰπεῖν ὡς ἁπλούστατα ἐγχειρεῖν τὸ πῖπτον εἰς τὸν γεωγραφικὸν πίνακα, συμπαραδηλοῦντα καὶ τὸ ποῖόν τι καὶ πόστον μέρος τῆς ὅλης γῆς ἐστι· τοῦτο μὲν γὰρ οἰκεῖον τῷ γεωγράφῳ, τὸ δὲ καὶ περὶ ὅλης ἀκριβολογεῖσθαι τῆς γῆς καὶ περὶ τοῦ σπονδύλου παντὸς ἧς λέγομεν ζώνης ἄλλης τινὸς ἐπιστήμης ἐστίν, οἷον εἰ περιοικεῖται καὶ κατὰ θάτερον τεταρτημόριον ὁ σπόνδυλος· καὶ γὰρ εἰ οὕτως ἔχει, οὐχ ὑπὸ τούτων γε οἰκεῖται τῶν παρ’ ἡμῖν, ἀλλ’ ἐκείνην ἄλλην οἰκουμένην θετέον, ὅπερ ἐστὶ πιθανόν. ἡμῖν δὲ τὰ ἐν αὐτῇ ταύτῃ λεκτέον.", "st": "2.5.13"}, {"sp": "N", "t": "ἔστι δή τι χλαμυδοειδὲς σχῆμα τῆς γῆς τῆς οἰκουμένης, οὗ τὸ μὲν πλάτος ὑπογράφει τὸ μέγιστον ἡ διὰ τοῦ Νείλου γραμμή, λαβοῦσα τὴν ἀρχὴν ἀπὸ τοῦ διὰ τῆς Κινναμωμοφόρου παραλλήλου καὶ τῆς τῶν Αἰγυπτίων τῶν φυγάδων νήσου μέχρι τοῦ διὰ τῆς Ἰέρνης παραλλήλου, τὸ δὲ μῆκος ἡ ταύτῃ πρὸς ὀρθὰς ἀπὸ τῆς ἑσπέρας διὰ στηλῶν καὶ τοῦ Σικελικοῦ πορθμοῦ μέχρι τῆς Ῥοδίας καὶ τοῦ Ἰσσικοῦ κόλπου, παρὰ τὸν Ταῦρον ἰοῦσα τὸν διεζωκότα τὴν Ἀσίαν καὶ καταστρέφοντα ἐπὶ τὴν ἑῴαν θάλατταν μεταξὺ Ἰνδῶν καὶ τῶν ὑπὲρ τῆς Βακτριανῆς Σκυθῶν. δεῖ δὴ νοῆσαι παραλληλόγραμμόν τι, ἐν ᾧ τὸ χλαμυδοειδὲς σχῆμα ἐγγέγραπται οὕτως ὥστε τὸ μῆκος τῷ μήκει ὁμολογεῖν καὶ ἴσον εἶναι τὸ μέγιστον καὶ τὸ πλάτος τῷ πλάτει. τὸ μὲν δὴ χλαμυδοειδὲς σχῆμα οἰκουμένη ἐστί· τὸ δὲ πλάτος ὁρίζεσθαι ἔφαμεν αὐτῆς ταῖς ἐσχάταις παραλλήλοις πλευραῖς, ταῖς διοριζούσαις τὸ οἰκήσιμον αὐτῆς καὶ τὸ ἀοίκητον ἐφ’ ἑκάτερα. αὗται δ’ ἦσαν πρὸς ἄρκτοις μὲν ἡ διὰ τῆς Ἰέρνης, πρὸς δὲ τῇ διακεκαυμένῃ ἡ διὰ τῆς Κινναμωμοφόρου· αὗται δὴ προσεκβαλλόμεναι ἐπί τε τὰς ἀνατολὰς καὶ ἐπὶ τὰς δύσεις μέχρι τῶν ἀνταιρόντων μερῶν τῆς οἰκουμένης ποιήσουσί τι παραλληλόγραμμον πρὸς τὰς ἐπιζευγνυούσας διὰ τῶν ἄκρων αὐτάς. ὅτι μὲν οὖν ἐν τούτῳ ἐστὶν ἡ οἰκουμένη, φανερὸν ἐκ τοῦ μήτε τὸ πλάτος αὐτῆς τὸ μέγιστον ἔξω πίπτειν αὐτοῦ μήτε τὸ μῆκος· ὅτι δ’ αὐτῆς χλαμυδοειδὲς τὸ σχῆμά ἐστιν, ἐκ τοῦ τὰ ἄκρα μυουρίζειν τὰ τοῦ μήκους ἑκατέρωθεν, κλυζόμενα ὑπὸ τῆς θαλάττης, καὶ ἀφαιρεῖν τοῦ πλάτους· τοῦτο δὲ δῆλον ἐκ τῶν περιπλευσάντων τά τε ἑῷα μέρη καὶ τὰ δυσμικὰ ἑκατέρωθεν. τῆς τε γὰρ Ἰνδικῆς νοτιωτέραν πολὺ τὴν Ταπροβάνην καλουμένην νῆσον ἀποφαίνουσιν, οἰκουμένην ἔτι καὶ ἀνταίρουσαν τῇ τῶν Αἰγυπτίων νήσῳ καὶ τῇ τὸ κιννάμωμον φερούσῃ γῇ· τὴν γὰρ κρᾶσιν τῶν ἀέρων παραπλησίαν εἶναι· τῆς τε μετὰ τοὺς Ἰνδοὺς Σκυθίας τῆς ὑστάτης ἀρκτικώτερά ἐστι τὰ κατὰ τὸ στόμα τῆς Ὑρκανίας θαλάττης καὶ ἔτι μᾶλλον τὰ κατὰ τὴν Ἰέρνην. ὁμοίως δὲ καὶ περὶ τῆς ἔξω στηλῶν λέγεται· δυσμικώτατον μὲν γὰρ σημεῖον τῆς οἰκουμένης τὸ τῶν Ἰβήρων ἀκρωτήριον ὃ καλοῦσιν ἱερόν· κεῖται δὲ κατὰ τὴν γραμμήν πως τὴν διὰ Γαδείρων τε καὶ στηλῶν καὶ τοῦ Σικελικοῦ πορθμοῦ καὶ τῆς Ῥοδίας. συμφωνεῖν γὰρ καὶ τὰ ὡροσκοπεῖα καὶ τοὺς ἀνέμους φασὶ τοὺς ἑκατέρωσε φοροὺς καὶ τὰ μήκη τῶν μεγίστων ἡμερῶν τε καὶ νυκτῶν· ἔστι γὰρ τετταρεσκαίδεκα ὡρῶν ἰσημερινῶν [καὶ ἡμίσους ἡ μεγίστη τῶν ἡμερῶν] τε καὶ νυκτῶν. ἔν τε τῇ παραλίᾳ τῇ κατὰ Γάδειρα καὶ * Ἴβηράς ποτε ὁρᾶσθαι. Ποσειδώνιος δ’ ἔκ τινος ὑψηλῆς οἰκίας ἐν πόλει διεχούσῃ τῶν τόπων τούτων ὅσον τετρακοσίους σταδίους φησὶν ἰδεῖν ἀστέρα, ὃν τεκμαίρεσθαι τὸν Κάνωβον αὐτὸν ἐκ τοῦ τε μικρὸν ἐκ τῆς Ἰβηρίας προελθόντας ἐπὶ τὴν μεσημβρίαν ὁμολογεῖν ἀφορᾶν αὐτὸν καὶ ἐκ τῆς ἱστορίας τῆς ἐν Κνίδῳ· τὴν γὰρ Εὐδόξου σκοπὴν οὐ πολὺ τῶν οἰκήσεων ὑψηλοτέραν εἶναι, λέγεσθαι δ’ ὅτι ἐντεῦθεν ἐκεῖνος ἀφεώρα τὸν Κάνωβον ἀστέρα, εἶναι δ’ ἐπὶ τοῦ Ῥοδιακοῦ κλίματος τὴν Κνίδον, ἐφ’ οὗ καὶ τὰ Γάδειρα καὶ ἡ ταύτῃ παραλία.", "st": "2.5.14"}, {"sp": "N", "t": "Ἐντεῦθεν δὲ πρὸς μὲν τὰ νότια μέρη πλέουσιν ἡ Λιβύη κεῖται· ταύτης δὲ τὰ δυσμικώτατα μικρῷ τῶν Γαδείρων πρόκειται μᾶλλον, εἶτ’ ἄκραν ποιήσαντα στενὴν ἀναχωρεῖ πρὸς ἕω καὶ νότον, καὶ πλατύνεται κατ’ ὀλίγον ἕως ἂν τοῖς ἑσπερίοις Αἰθίοψι συνάψῃ. οὗτοι δ’ ὑπόκεινται τῶν περὶ Καρχηδόνα τόπων ὕστατοι, συνάπτοντες τῇ διὰ τῆς Κινναμωμοφόρου γραμμῇ. εἰς δὲ τἀναντία πλέουσιν ἀπὸ τοῦ ἱεροῦ ἀκρωτηρίου μέχρι τῶν Ἀρτάβρων καλουμένων ὁ πλοῦς ἐστι πρὸς ἄρκτον ἐν δεξιᾷ ἔχουσι τὴν Λυσιτανίαν· εἶθ’ ὁ λοιπὸς πρὸς ἕω πᾶς ἀμβλεῖαν γωνίαν ποιῶν μέχρι τῶν τῆς Πυρήνης ἄκρων τῶν τελευτώντων εἰς τὸν ὠκεανόν. τούτοις δὲ τὰ ἑσπέρια τῆς Βρεττανικῆς ἀντίκειται πρὸς ἄρκτον, ὁμοίως δὲ καὶ τοῖς Ἀρτάβροις ἀντίκεινται πρὸς ἄρκτον αἱ Καττιτερίδες καλούμεναι νῆσοι πελάγιαι κατὰ τὸ Βρεττανικόν πως κλίμα ἱδρυμέναι· ὥστε δῆλον ἐφ’ ὅσον συνάγεται τὰ ἄκρα τῆς οἰκουμένης κατὰ μῆκος ὑπὸ τοῦ περικεχυμένου πελάγους εἰς στενόν.", "st": "2.5.15"}, {"sp": "N", "t": "τοιούτου δὲ ὄντος τοῦ καθόλου σχήματος, χρήσιμον φαίνεται δύο λαβεῖν εὐθείας, αἳ τέμνουσαι πρὸς ὀρθὰς ἀλλήλας, ἡ μὲν διὰ τοῦ μήκους ἥξει τοῦ μεγίστου παντὸς ἡ δὲ διὰ τοῦ πλάτους, καὶ ἡ μὲν τῶν παραλλήλων ἔσται μία ἡ δὲ τῶν μεσημβρινῶν· ἔπειτα ταύταις παραλλήλους ἐπινοοῦντας ἐφ’ ἑκάτερα διαιρεῖν κατὰ ταύτας τὴν γῆν καὶ τὴν θάλατταν, ᾗ χρώμενοι τυγχάνομεν. καὶ γὰρ τὸ σχῆμα μᾶλλον ἂν καταφανὲς γένοιτο ὁποῖον εἰρήκαμεν, κατὰ τὸ μέγεθος τῶν γραμμῶν ἄλλα καὶ ἄλλα μέτρα ἐχουσῶν τῶν τε τοῦ μήκους καὶ τοῦ πλάτους, καὶ τὰ κλίματα ἀποδηλωθήσεται βέλτιον τά τε ἑωθινὰ καὶ τὰ ἑσπέρια, ὡς δ’ αὕτως τὰ νότια καὶ τὰ βόρεια. ἐπεὶ δὲ διὰ γνωρίμων τόπων λαμβάνεσθαι δεῖ τὰς εὐθείας ταύτας, αἱ μὲν ἐλήφθησαν ἤδη, λέγω δὲ τὰς μέσας δύο τήν τε τοῦ μήκους καὶ τοῦ πλάτους, τὰς λεχθείσας πρότερον, αἱ δ’ ἄλλαι ῥᾳδίως γνωρίζοιντ’ ἂν διὰ τούτων· τρόπον γάρ τινα στοιχείοις χρώμενοι τούτοις τὰ παράλληλα μέρη στοχαζόμεθα καὶ τὰς ἄλλας σχέσεις τῶν οἰκήσεων τάς τ’ ἐπὶ γῆς καὶ πρὸς τὰ οὐράνια.", "st": "2.5.16"}, {"sp": "N", "t": "πλεῖστον δ’ ἡ θάλαττα γεωγραφεῖ καὶ σχηματίζει τὴν γῆν, κόλπους ἀπεργαζομένη καὶ πελάγη καὶ πορθμούς, ὁμοίως δὲ ἰσθμοὺς καὶ χερρονήσους καὶ ἄκρας· προσλαμβάνουσι δὲ ταύτῃ καὶ οἱ ποταμοὶ καὶ τὰ ὄρη. διὰ γὰρ τῶν τοιούτων ἤπειροί τε καὶ ἔθνη καὶ πόλεων θέσεις εὐφυεῖς ἐνενοήθησαν καὶ τἆλλα ποικίλματα, ὅσων μεστός ἐστιν ὁ χωρογραφικὸς πίναξ. ἐν δὲ τούτοις καὶ τὸ τῶν νήσων πλῆθός ἐστι κατεσπαρμένον ἔν τε τοῖς πελάγεσι καὶ κατὰ τὴν παραλίαν πᾶσαν. ἄλλων δ’ ἄλλας ἀρετάς τε καὶ κακίας καὶ τὰς ἀπ’ αὐτῶν χρείας ἐπιδεικνυμένων ἢ δυσχρηστίας, τὰς μὲν φύσει τὰς δὲ ἐκ κατασκευῆς, τὰς φύσει δεῖ λέγειν· διαμένουσι γάρ, αἱ δ’ ἐπίθετοι δέχονται μεταβολάς. καὶ τούτων δὲ τὰς πλείω χρόνον συμμένειν δυναμένας ἐμφανιστέον, … μὴ πολὺ μέν, ἄλλως δ’ ἐπιφάνειαν ἐχούσας τινὰ καὶ δόξαν, ἣ πρὸς τὸν ὕστερον χρόνον παραμένουσα τρόπον τινὰ συμφυῆ τοῖς τόποις ποιεῖ καὶ μηκέτι οὖσαν κατασκευήν, ὥστε δῆλον ὅτι δεῖ καὶ τούτων μεμνῆσθαι. περὶ πολλῶν γάρ ἐστι πόλεων τοῦτ’ εἰπεῖν, ὅπερ εἶπε Δημοσθένης ἐπὶ τῶν περὶ Ὄλυνθον, ἃς οὕτως ἠφανίσθαι φησὶν ὥστε μηδ’ εἰ πώποτε ᾠκίσθησαν γνῶναι ἄν τινα ἐπελθόντα. ἀλλ’ ὅμως καὶ εἰς τούτους τοὺς τόπους καὶ εἰς ἄλλους ἀφικνοῦνται ἄσμενοι, τά γ’ ἴχνη ποθοῦντες ἰδεῖν τῶν οὕτω διωνομασμένων ἔργων, καθάπερ καὶ τοὺς τάφους τῶν ἐνδόξων ἀνδρῶν. οὕτω δὲ καὶ νομίμων καὶ πολιτειῶν μεμνήμεθα τῶν μηκέτι οὐσῶν, ἐνταῦθα καὶ τῆς ὠφελείας προκαλουμένης τὸν αὐτὸν τρόπον ὅνπερ καὶ ἐπὶ τῶν πράξεων· ἢ γὰρ ζήλου χάριν ἢ ἀποτροπῆς τῶν τοιούτων.", "st": "2.5.17"}, {"sp": "N", "t": "λέγομεν δ’ ἀναλαβόντες ἀπὸ τῆς πρώτης ὑποτυπώσεως ὅτι ἡ καθ’ ἡμᾶς οἰκουμένη γῆ περίρρυτος οὖσα δέχεται κόλπους εἰς ἑαυτὴν ἀπὸ τῆς ἔξω θαλάττης κατὰ τὸν ὠκεανὸν πολλούς, μεγίστους δὲ τέτταρας· ὧν ὁ μὲν βόρειος Κασπία καλεῖται θάλαττα (οἱ δ’ Ὑρκανίαν προσαγορεύουσιν), ὁ δὲ Περσικὸς καὶ Ἀράβιος ἀπὸ τῆς νοτίας ἀναχέονται θαλάττης, ὁ μὲν τῆς Κασπίας κατ’ ἀντικρὺ μάλιστα ὁ δὲ τῆς Ποντικῆς, τὸν δὲ τέταρτον, ὅσπερ πολὺ τούτους ὑπερβέβληται κατὰ τὸ μέγεθος, ἡ ἐντὸς καὶ καθ’ ἡμᾶς λεγομένη θάλαττα ἀπεργάζεται, τὴν μὲν ἀρχὴν ἀπὸ τῆς ἑσπέρας λαμβάνουσα καὶ τοῦ κατὰ τὰς Ἡρακλείους στήλας πορθμοῦ, μηκυνομένη δ’ εἰς τὸ πρὸς ἕω μέρος ἐν ἄλλῳ [καὶ ἄλλῳ] πλάτει, μετὰ δὲ ταῦτα σχιζομένη καὶ τελευτῶσα εἰς δύο κόλπους πελαγίους, τὸν μὲν ἐν ἀριστερᾷ, ὅνπερ Εὔξεινον πόντον προσαγορεύομεν, τὸν δ’ ἕτερον τὸν συγκείμενον ἔκ τε τοῦ Αἰγυπτίου πελάγους καὶ τοῦ Παμφυλίου καὶ τοῦ Ἰσσικοῦ. ἅπαντες δ’ οἱ λεχθέντες κόλποι ἀπὸ τῆς ἔξω θαλάττης στενὸν ἔχουσι τὸν εἴσπλουν, μᾶλλον μὲν ὅ τε Ἀράβιος καὶ ὁ κατὰ στήλας, ἧττον δ’ οἱ λοιποί. ἡ δὲ περικλείουσα αὐτοὺς γῆ τριχῆ νενέμηται, καθάπερ εἴρηται. ἡ μὲν οὖν Εὐρώπη πολυσχημονεστάτη πασῶν ἐστιν, ἡ δὲ Λιβύη τἀναντία πέπονθεν, ἡ δὲ Ἀσία μέσην πως ἀμφοῖν ἔχει τὴν διάθεσιν. ἅπασαι δ’ ἐκ τῆς ἐντὸς παραλίας ἔχουσι τὴν αἰτίαν τοῦ τε πολυσχήμονος καὶ τοῦ μή, ἡ δ’ ἐκτὸς πλὴν τῶν λεχθέντων κόλπων ἁπλῆ καὶ χλαμυδοειδής ἐστιν, ὡς εἶπον, τὰς δ’ ἄλλας ἐν μικρῷ διαφορὰς ἐατέον· οὐδὲν γὰρ ἐν τοῖς μεγάλοις τὸ μικρόν. ἔτι δ’ ἐπεὶ κατὰ τὴν γεωγραφικὴν ἱστορίαν οὐ σχήματα μόνον ζητοῦμεν καὶ μεγέθη τόπων, ἀλλὰ καὶ σχέσεις πρὸς ἄλληλα αὐτῶν, ὥσπερ ἔφαμεν, καὶ ἐνταῦθα τὸ ποικίλον ἡ ἐντὸς παραλία παρέχεται μᾶλλον ἢ ἡ ἐκτός. πολὺ δ’ ἐστὶ καὶ τὸ γνώριμον καὶ τὸ εὔκρατον καὶ τὸ πόλεσι καὶ ἔθνεσιν εὐνομουμένοις συνοικούμενον μᾶλλον ἐνταῦθα ἢ ἐκεῖ. ποθοῦμεν δὲ εἰδέναι ταῦτα, ἐν οἷς πλείους παραδίδονται πράξεις καὶ πολιτεῖαι καὶ τέχναι καὶ τἆλλα ὅσα εἰς φρόνησιν συνεργεῖ, αἵ τε χρεῖαι συνάγουσιν ἡμᾶς πρὸς ἐκεῖνα ὧν ἐν ἐφικτῷ αἱ ἐπιπλοκαὶ καὶ κοινωνίαι· ταῦτα δ’ ἐστὶν ὅσα οἰκεῖται, μᾶλλον δ’ οἰκεῖται καλῶς. πρὸς ἅπαντα δὲ τὰ τοιαῦτα, ὡς ἔφην, ἡ παρ’ ἡμῖν θάλαττα πλεονέκτημα ἔχει μέγα· καὶ δὴ καὶ ἔνθεν ἀρκτέον τῆς περιηγήσεως.", "st": "2.5.18"}, {"sp": "N", "t": "εἴρηται δὲ ὅτι ἀρχὴ τοῦδε τοῦ κόλπου ἐστὶν ὁ κατὰ τὰς στήλας πορθμός· τὸ δὲ στενώτατον τούτου περὶ ἑβδομήκοντα σταδίους λέγεται· παραπλεύσαντι δὲ τὸν στενωπὸν ἑκατὸν καὶ εἴκοσι σταδίων ὄντα διάστασιν λαμβάνουσιν αἱ ᾐόνες ἀθρόαν, ἡ δ’ ἐν ἀριστερᾷ μᾶλλον· εἶτ’ ὄψις μεγάλου φαίνεται πελάγους. ὁρίζεται δ’ ἐκ μὲν τοῦ δεξιοῦ πλευροῦ τῇ Λιβυκῇ παραλίᾳ μέχρι Καρχηδόνος, ἐκ δὲ θατέρου τῇ τε Ἰβηρικῇ καὶ τῇ Κελτικῇ κατὰ Νάρβωνα καὶ Μασσαλίαν, καὶ μετὰ ταῦτα τῇ Λιγυστικῇ, τελευταίᾳ δὲ τῇ Ἰταλικῇ μέχρι τοῦ Σικελικοῦ πορθμοῦ. τὸ δ’ ἑῷον τοῦ πελάγους πλευρὸν ἡ Σικελία ἐστὶ καὶ οἱ ἑκατέρωθεν αὐτῆς πορθμοί, ὁ μὲν πρὸς τῇ Ἰταλίᾳ ἑπταστάδιος, ὁ δὲ πρὸς τῇ Καρχηδόνι χιλίων καὶ πεντακοσίων σταδίων. ἡ δ’ ἀπὸ τῶν στηλῶν ἐπὶ τὸ ἑπταστάδιον γραμμὴ μέρος μέν ἐστι τῆς ἐπὶ Ῥόδον καὶ τὸν Ταῦρον, μέσον δέ πως τέμνει τὸ λεχθὲν πέλαγος· λέγεται δὲ σταδίων μυρίων καὶ δισχιλίων· τοῦτο μὲν δὴ τὸ μῆκος τοῦ πελάγους, πλάτος δὲ τὸ μέγιστον ὅσον πεντακισχιλίων σταδίων τὸ ἀπὸ τοῦ Γαλατικοῦ κόλπου μεταξὺ Μασσαλίας καὶ Νάρβωνος ἐπὶ τὴν κατ’ ἀντικρὺ Λιβύην. καλοῦσι δὲ τὸ πρὸς τῇ Λιβύῃ πᾶν μέρος τῆς θαλάττης ταύτης Λιβυκὸν πέλαγος, τὸ δὲ πρὸς τῇ κατ’ ἀντικρὺ γῇ τὸ μὲν Ἰβηρικὸν τὸ δὲ Λιγυστικὸν τὸ δὲ Σαρδόνιον, τελευταῖον δὲ μέχρι τῆς Σικελίας τὸ Τυρρηνικόν. νῆσοι δ’ εἰσὶν ἐν μὲν τῇ παραλίᾳ τῇ κατὰ τὸ Τυρρηνικὸν πέλαγος μέχρι τῆς Λιγυστικῆς συχναί, μέγισται δὲ Σαρδὼ καὶ Κύρνος, μετά γε τὴν Σικελίαν· αὕτη δὲ καὶ τῶν ἄλλων ἐστὶ μεγίστη τῶν καθ’ ἡμᾶς καὶ ἀρίστη. πολὺ δὲ τούτων λειπόμεναι πελάγιαι μὲν Πανδατερία τε καὶ Ποντία, πρόσγειοι δὲ Αἰθαλία τε καὶ Πλανασία καὶ Πιθηκοῦσσα καὶ Προχύτη καὶ Καπρίαι καὶ Λευκωσία καὶ ἄλλαι τοιαῦται. ἐπὶ θάτερα δὲ τῆς Λιγυστικῆς αἱ πρὸ τῆς λοιπῆς ᾐόνος μέχρι στηλῶν οὐ πολλαί, ὧν εἰσιν ἥ τε Γυμνησία καὶ Ἔβυσος· οὐ πολλαὶ δ’ οὐδ’ αἱ πρὸ τῆς Λιβύης καὶ τῆς Σικελίας, ὧν εἰσι Κόσσουρά τε καὶ Αἰγίμουρος καὶ αἱ Λιπαραίων νῆσοι, ἃς Αἰόλου τινὲς προσαγορεύουσι.", "st": "2.5.19"}, {"sp": "N", "t": "μετὰ δὲ τὴν Σικελίαν καὶ τοὺς ἑκατέρωθεν πορθμοὺς ἄλλα πελάγη συνάπτει, τό τε πρὸ τῶν Σύρτεων καὶ τῆς Κυρηναίας καὶ αὐταὶ αἱ Σύρτεις καὶ τὸ Αὐσόνιον μὲν πάλαι νῦν δὲ καλούμενον Σικελικόν, σύρρουν ἐκείνῳ καὶ συνεχές. τὸ μὲν οὖν πρὸ τῶν Σύρτεων καὶ τῆς Κυρηναίας καλεῖται Λιβυκόν, τελευτᾷ δ’ εἰς τὸ Αἰγύπτιον πέλαγος. τῶν δὲ Σύρτεων ἡ μὲν ἐλάττων ἐστὶν ὅσον χιλίων καὶ ἑξακοσίων σταδίων τὴν περίμετρον· πρόκεινται δ’ ἐφ’ ἑκάτερα τοῦ στόματος νῆσοι Μῆνίγξ τε καὶ Κέρκινα· τῆς δὲ μεγάλης Σύρτεώς φησιν Ἐρατοσθένης τὸν κύκλον εἶναι πεντακισχιλίων, τὸ δὲ βάθος χιλίων ὀκτακοσίων ἀφ’ Ἑσπερίδων εἰς Αὐτόμαλα καὶ τὸ τῆς Κυρηναίας μεθόριον πρὸς τὴν ἄλλην τὴν ταύτῃ Λιβύην· ἄλλοι δὲ τὸν περίπλουν τετρακισχιλίων σταδίων εἶπον, τὸ δὲ βάθος χιλίων πεντακοσίων, ὅσον καὶ τὸ πλάτος τοῦ στόματος. τὸ δὲ Σικελικὸν πέλαγος πρὸ τῆς Σικελίας ἐστὶ καὶ τῆς Ἰταλίας ἐπὶ τὸ πρὸς ἕω μέρος καὶ ἔτι τοῦ μεταξὺ πόρου τῆς τε Ῥηγίνης μέχρι Λοκρῶν, καὶ τῆς Μεσσηνίας μέχρι Συρακουσσῶν καὶ Παχύνου. αὔξεται δ’ ἐπὶ μὲν τὸ πρὸς ἕω μέρος μέχρι τῶν ἄκρων τῆς Κρήτης, καὶ τὴν Πελοπόννησον δὲ περικλύζει τὴν πλείστην, καὶ πληροῖ τὸν Κορινθιακὸν καλούμενον κόλπον· πρὸς ἄρκτους δὲ ἐπί τε ἄκραν Ἰαπυγίαν καὶ τὸ στόμα τοῦ Ἰονίου κόλπου καὶ τῆς Ἠπείρου τὰ νότια μέρη μέχρι τοῦ Ἀμβρακικοῦ κόλπου καὶ τῆς συνεχοῦς παραλίας τῆς ποιούσης τὸν Κορινθιακὸν κόλπον πρὸς τὴν Πελοπόννησον. ὁ δ’ Ἰόνιος κόλπος μέρος ἐστὶ τοῦ νῦν Ἀδρίου λεγομένου· τούτου δὲ τὴν μὲν ἐν δεξιᾷ πλευρὰν ἡ Ἰλλυρὶς ποιεῖ, τὴν δ’ εὐώνυμον ἡ Ἰταλία μέχρι τοῦ μυχοῦ τοῦ κατὰ Ἀκυληίαν. ἔστι δὲ πρὸς ἄρκτον ἅμα καὶ πρὸς τὴν ἑσπέραν ἀνέχων στενὸς καὶ μακρός, μῆκος μὲν ὅσον ἑξακισχιλίων σταδίων, πλάτος δὲ τὸ μέγιστον διακοσίων ἐπὶ τοῖς χιλίοις. νῆσοι δέ εἰσιν ἐνταῦθα συχναὶ μὲν αἱ πρὸ τῆς Ἰλλυρίδος, αἵ τε Ἀψυρτίδες καὶ Κυρικτικὴ καὶ Λιβυρνίδες, ἔτι δ’ Ἴσσα καὶ Τραγούριον καὶ ἡ Μέλαινα Κόρκυρα καὶ Φάρος, πρὸ τῆς Ἰταλίας δὲ αἱ Διομήδειοι. τοῦ Σικελικοῦ δὲ τὸ ἐπὶ Κρήτην ἀπὸ Παχύνου τετρακισχιλίων καὶ πεντακοσίων σταδίων φασί· τοσοῦτον δὲ καὶ τὸ ἐπὶ Ταίναρον τῆς Λακωνικῆς· τὸ δὲ ἀπὸ ἄκρας Ἰαπυγίας ἐπὶ τὸν μυχὸν τοῦ Κορινθιακοῦ κόλπου τῶν μὲν τρισχιλίων ἐστὶν ἔλαττον, τὸ δ’ ἀπὸ Ἰαπυγίας εἰς τὴν Λιβύην πλέον τῶν τετρακισχιλίων ἐστί. νῆσοι δ’ εἰσὶν ἐνταῦθα ἥ τε Κόρκυρα καὶ Σύβοτα πρὸ τῆς Ἠπειρώτιδος, καὶ ἐφεξῆς πρὸ τοῦ Κορινθιακοῦ κόλπου Κεφαλληνία καὶ Ἰθάκη καὶ Ζάκυνθος καὶ Ἐχινάδες.", "st": "2.5.20"}, {"sp": "N", "t": "τῷ δὲ Σικελικῷ συνάπτει τὸ Κρητικὸν πέλαγος καὶ τὸ Σαρωνικὸν καὶ τὸ Μυρτῷον, ὃ μεταξὺ τῆς Κρήτης ἐστὶ καὶ τῆς Ἀργείας καὶ τῆς Ἀττικῆς, πλάτος ἔχον τὸ μέγιστον τὸ ἀπὸ τῆς Ἀττικῆς ὅσον χιλίων καὶ διακοσίων σταδίων, μῆκος δ’ ἔλαττον ἢ διπλάσιον. ἐν τούτῳ δὲ νῆσοι Κύθηρά τε καὶ Καλαυρία καὶ αἱ περὶ Αἴγιναν καὶ Σαλαμῖνα καὶ τῶν Κυκλάδων τινές. τὸ δὲ συνεχὲς τὸ Αἰγαῖόν ἐστιν ἤδη σὺν τῷ Μέλανι κόλπῳ καὶ τῷ Ἑλλησπόντῳ, καὶ τὸ Ἰκάριον καὶ Καρπάθιον μέχρι τῆς Ῥόδου καὶ Κρήτης καὶ τῶν πρώτων μερῶν τῆς Ἀσίας … αἵ τε Κυκλάδες νῆσοι εἰσὶ καὶ αἱ Σποράδες καὶ αἱ προκείμεναι τῆς Καρίας καὶ Ἰωνίας καὶ Αἰολίδος μέχρι τῆς Τρῳάδος, λέγω δὲ Κῶ καὶ Σάμον καὶ Χίον καὶ Λέσβον καὶ Τένεδον· ὡς δ’ αὕτως αἱ προκείμεναι τῆς Ἑλλάδος μέχρι τῆς Μακεδονίας καὶ τῆς ὁμόρου Θρᾴκης Εὔβοιά τε καὶ Σκῦρος καὶ Πεπάρηθος καὶ Λῆμνος καὶ Θάσος καὶ Ἴμβρος καὶ Σαμοθρᾴκη καὶ ἄλλαι πλείους, περὶ ὧν ἐν τοῖς καθ’ ἕκαστα δηλώσομεν. ἔστι δὲ τὸ μῆκος τῆς θαλάττης ταύτης περὶ τετρακισχιλίους ἢ μικρῷ πλείους, τὸ δὲ πλάτος περὶ δισχιλίους. περιέχεται δὲ ὑπὸ τῶν λεχθέντων μερῶν τῆς Ἀσίας καὶ τῆς ἀπὸ Σουνίου μέχρι Θερμαίου κόλπου πρὸς ἄρκτον ἐχούσης τὸν πλοῦν παραλίας καὶ τῶν Μακεδονικῶν κόλπων μέχρι τῆς Θρᾳκίας χερρονήσου.", "st": "2.5.21"}, {"sp": "N", "t": "κατὰ δὲ ταύτην ἐστὶ τὸ ἑπταστάδιον τὸ κατὰ Σηστὸν καὶ Ἄβυδον, δι’ οὗ τὸ Αἰγαῖον καὶ ὁ Ἑλλήσποντος ἐκδίδωσι πρὸς ἄρκτον εἰς ἄλλο πέλαγος, ὃ καλοῦσι Προποντίδα, κἀκεῖνο εἰς ἄλλο τὸν Εὔξεινον προσαγορευόμενον πόντον. ἔστι δὲ διθάλαττος τρόπον τινὰ οὗτος· κατὰ μέσον γάρ πως ἄκραι δύο προπίπτουσιν, ἡ μὲν ἐκ τῆς Εὐρώπης καὶ τῶν βορείων μερῶν ἡ δ’ ἐκ τῆς Ἀσίας ἐναντία ταύτῃ, συνάγουσαι τὸν μεταξὺ πόρον καὶ ποιοῦσαι δύο πελάγη μεγάλα· τὸ μὲν οὖν τῆς Εὐρώπης ἀκρωτήριον καλεῖται Κριοῦ μέτωπον τὸ δὲ τῆς Ἀσίας Κάραμβις, διέχοντα ἀλλήλων περὶ χιλίους σταδίους καὶ πεντακοσίους. τὸ μὲν οὖν πρὸς ἑσπέραν πέλαγος μῆκός ἐστιν ἀπὸ Βυζαντίου μέχρι τῶν ἐκβολῶν τοῦ Βορυσθένους σταδίων τρισχιλίων ὀκτακοσίων, πλάτος δὲ δισχιλίων· ἐν τούτῳ δ’ ἡ Λευκὴ νῆσός ἐστι· τὸ δ’ ἑῷόν ἐστι παράμηκες εἰς στενὸν τελευτῶν μυχὸν τὸν κατὰ Διοσκουριάδα ἐπὶ πεντακισχιλίους ἢ μικρῷ πλείους σταδίους, τὸ δὲ πλάτος περὶ τρισχιλίους· ἡ δὲ περίμετρος τοῦ σύμπαντος πελάγους ἐστὶ δισμυρίων που καὶ πεντακισχιλίων σταδίων. εἰκάζουσι δέ τινες τὸ σχῆμα τῆς περιμέτρου ταύτης ἐντεταμένῳ Σκυθικῷ τόξῳ, τὴν μὲν νευρὰν ἐξομοιοῦντες τοῖς δεξιοῖς καλουμένοις μέρεσι τοῦ Πόντου (ταῦτα δ’ ἐστὶν ὁ παράπλους ὁ ἀπὸ τοῦ στόματος μέχρι τοῦ μυχοῦ τοῦ κατὰ Διοσκουριάδα· πλὴν γὰρ τῆς Καράμβιος ἥ γε ἄλλη πᾶσα ᾐὼν μικρὰς ἔχει εἰσοχάς τε καὶ ἐξοχὰς ὥστ’ εὐθείᾳ ἐοικέναι), τὴν δὲ λοιπὴν τῷ κέρατι τοῦ τόξου διττὴν ἔχοντι τὴν ἐπιστροφήν, τὴν μὲν ἄνω περιφερεστέραν τὴν δὲ κάτω εὐθυτέραν· οὕτω δὲ κἀκείνην ἀπεργάζεσθαι δύο κόλπους, ὧν ὁ ἑσπέριος πολὺ θατέρου περιφερέστερός ἐστιν.", "st": "2.5.22"}, {"sp": "N", "t": "̔υπέρκειται δὲ τοῦ ἑωθινοῦ κόλπου πρὸς ἄρκτον ἡ Μαιῶτος λίμην τὴν περίμετρον ἔχουσα ἐνακισχιλίων σταδίων ἢ καὶ μικρῷ πλεόνων· ἐκδίδωσι δ’ αὕτη μὲν εἰς Πόντον κατὰ τὸν Κιμμερικὸν καλούμενον Βόσπορον, οὗτος δὲ κατὰ τὸν Θρᾴκιον εἰς τὴν Προποντίδα· τὸ γὰρ Βυζαντιακὸν στόμα οὕτω καλοῦσι Θρᾴκιον Βόσπορον, ὃ τετραστάδιόν ἐστιν. ἡ δὲ Προποντὶς χιλίων καὶ πεντακοσίων λέγεται τὸ μῆκος σταδίων τὸ ἀπὸ τῆς Τρῳάδος ἐπὶ τὸ Βυζάντιον· πάρισον δέ πώς ἐστι καὶ τὸ πλάτος. ἐνταῦθα δ’ ἡ τῶν Κυζικηνῶν ἵδρυται νῆσος καὶ τὰ περὶ αὐτὴν νησία.", "st": "2.5.23"}, {"sp": "N", "t": "τοιαύτη μὲν ἡ πρὸς ἄρκτον τοῦ Αἰγαίου πελάγους ἀνάχυσις καὶ τοσαύτη, πάλιν δ’ ἀπὸ τῆς Ῥοδίας ἡ τὸ Αἰγύπτιον πέλαγος ποιοῦσα καὶ τὸ Παμφύλιον καὶ τὸ Ἰσσικὸν ἐπὶ μὲν τὴν ἕω καὶ τῆς Κιλικίας κατὰ Ἰσσὸν ἐκτείνεται μέχρι καὶ πεντακισχιλίων σταδίων παρά τε Λυκίαν καὶ Παμφυλίαν καὶ τὴν Κιλίκων παραλίαν πᾶσαν. ἐντεῦθεν δὲ Συρία τε καὶ Φοινίκη καὶ Αἴγυπτος ἐγκυκλοῖ πρὸς νότον τὴν θάλατταν καὶ πρὸς δύσιν ἕως Ἀλεξανδρείας. ἐν δὲ τῷ Ἰσσικῷ κόλπῳ καὶ τῷ Παμφυλίῳ κεῖσθαι συμβαίνει τὴν Κύπρον, συνάπτουσαν τῷ Αἰγυπτίῳ πελάγει. ἔστι δ’ ἀπὸ Ῥόδου δίαρμα εἰς Ἀλεξάνδρειαν βορέᾳ τετρακισχιλίων που σταδίων, ὁ δὲ περίπλους διπλάσιος. ὁ δ’ Ἐρατοσθένης ταύτην μὲν τῶν ναυτικῶν εἶναί φησι τὴν ὑπόληψιν περὶ τοῦ διάρματος τοῦ πελάγους, τῶν μὲν οὕτω λεγόντων, τῶν δὲ καὶ πεντακισχιλίους οὐκ ὀκνούντων εἰπεῖν, αὐτὸς δὲ διὰ τῶν σκιοθηρικῶν γνωμόνων ἀνευρεῖν τρισχιλίους ἑπτακοσίους πεντήκοντα. τούτου δὴ τοῦ πελάγους τὸ πρὸς τῇ Κιλικίᾳ καὶ Παμφυλίᾳ καὶ τοῦ Ποντικοῦ τὰ καλούμενα δεξιὰ μέρη καὶ ἡ Προποντὶς καὶ ἡ ἐφεξῆς παραλία μέχρι Παμφυλίας ποιεῖ τινα χερρόνησον μεγάλην καὶ μέγαν ταύτης ἰσθμόν, τὸν ἀπὸ τῆς πρὸς Ταρσῷ θαλάττης ἐπὶ πόλιν Ἀμισὸν καὶ τὸ τῶν Ἀμαζόνων πεδίον τὴν Θεμίσκυραν. ἡ γὰρ ἐντὸς τῆς γραμμῆς ταύτης χώρα μέχρι Καρίας καὶ Ἰωνίας καὶ τῶν ἐντὸς Ἅλυος νεμομένων ἐθνῶν περίκλυστος ἅπασά ἐστιν ὑπὸ τοῦ Αἰγαίου καὶ τῶν ἑκατέρωθεν λεχθέντων τῆς θαλάττης μερῶν· καὶ δὴ καὶ καλοῦμεν Ἀσίαν ταύτην ἰδίως καὶ ὁμωνύμως τῇ ὅλῃ.", "st": "2.5.24"}, {"sp": "N", "t": "συλλήβδην δ’ εἰπεῖν, τῆς καθ’ ἡμᾶς θαλάττης νοτιώτατον μέν ἐστι σημεῖον ὁ τῆς μεγάλης Σύρτεως μυχός, καὶ μετὰ τοῦτον ἡ κατ’ Αἴγυπτον Ἀλεξάνδρεια καὶ τοῦ Νείλου προχοαί, βορειότατον δὲ τὸ τοῦ Βορυσθένους [στόμα]· εἰ δὲ καὶ τὴν Μαιῶτιν προστιθείη τῷ πελάγει τις (καὶ γάρ ἐστιν ὡς ἂν μέρος), τὸ τοῦ Τανάιδος· δυσμικώτατον δὲ ὁ κατὰ τὰς στήλας πορθμός, ἑωθινώτατον δ’ ὁ λεχθεὶς μυχὸς κατὰ Διοσκουριάδα· Ἐρατοσθένης δ’ οὐκ εὖ τὸν Ἰσσικὸν κόλπον φησίν. ὁ μὲν γὰρ ἐπὶ τοῦ αὐτοῦ μεσημβρινοῦ ἵδρυται ἐφ’ οὗπερ ἥ τε Ἀμισὸς καὶ Θεμίσκυρα· εἰ δὲ βούλει, πρόσλαβε καὶ τὴν Σιδήνην μέχρι Φαρνακείας. ἀπὸ δὲ τούτων τῶν μερῶν πρὸς ἕω πλοῦς ἐστι πλειόνων ἢ τρισχιλίων σταδίων εἰς Διοσκουριάδα, ὡς ἔσται μᾶλλον ἐκ τῆς ἐν μέρει περιοδείας φανερόν. ἡ μὲν δὴ καθ’ ἡμᾶς θάλαττα τοιαύτη τις.", "st": "2.5.25"}, {"sp": "N", "t": "̔υπογραπτέον δὲ καὶ τὰς περιεχούσας αὐτὴν γᾶς, ἀρχὴν λαβοῦσιν ἀπὸ τῶν αὐτῶν μερῶν ἀφ’ ὧνπερ καὶ τὴν θάλατταν ὑπεγράψαμεν. εἰσπλέουσι τοίνυν τὸν κατὰ στήλας πορθμὸν ἐν δεξιᾷ μέν ἐστιν ἡ Λιβύη μέχρι τῆς τοῦ Νείλου ῥύσεως, ἐν ἀριστερᾷ δὲ ἀντίπορθμος ἡ Εὐρώπη μέχρι τοῦ Τανάιδος· τελευτῶσι δ’ ἀμφότεραι περὶ τὴν Ἀσίαν. ἀρκτέον δ’ ἀπὸ τῆς Εὐρώπης, ὅτι πολυσχήμων τε καὶ πρὸς ἀρετὴν ἀνδρῶν εὐφυεστάτη καὶ πολιτειῶν καὶ ταῖς ἄλλαις πλεῖστον μεταδεδωκυῖα τῶν οἰκείων ἀγαθῶν, ἐπειδὴ σύμπασα οἰκήσιμός ἐστι πλὴν ὀλίγης τῆς διὰ ψῦχος ἀοικήτου. αὕτη δ’ ὁμορεῖ τοῖς Ἁμαξοίκοις τοῖς περὶ τὸν Τάναϊν καὶ τὴν Μαιῶτιν καὶ τὸν Βορυσθένη. τῆς δ’ οἰκησίμου τὸ μὲν δυσχείμερον καὶ τὸ ὀρεινὸν μοχθηρῶς οἰκεῖται τῇ φύσει, ἐπιμελητὰς δὲ λαβόντα ἀγαθοὺς καὶ τὰ φαύλως οἰκούμενα καὶ λῃστρικῶς ἡμεροῦται, καθάπερ οἱ Ἕλληνες ὄρη καὶ πέτρας κατέχοντες ᾤκουν καλῶς διὰ πρόνοιαν τὴν περὶ τὰ πολιτικὰ καὶ τὰς τέχνας καὶ τὴν ἄλλην σύνεσιν τὴν περὶ βίον, Ῥωμαῖοί τε πολλὰ ἔθνη παραλαβόντες καὶ τὴν φύσιν ἀνήμερα διὰ τοὺς τόπους ἢ τραχεῖς ὄντας ἢ ἀλιμένους ἢ ψυχροὺς ἢ ἀπ’ ἄλλης αἰτίας δυσοικήτους πολλοῖς τούς τε ἀνεπιπλέκτους ἀλλήλοις ἐπέπλεξαν καὶ τοὺς ἀγριωτέρους πολιτικῶς ζῆν ἐδίδαξαν. ὅσον δ’ ἐστὶν αὐτῆς ἐν ὁμαλῷ καὶ εὐκράτῳ τὴν φύσιν ἔχει συνεργὸν πρὸς ταῦτα, ἐπειδὴ τὸ μὲν ἐν τῇ εὐδαίμονι χώρᾳ πᾶν ἐστιν εἰρηνικόν, τὸ δ’ ἐν τῇ λυπρᾷ μάχιμον καὶ ἀνδρικόν, καὶ δέχεταί τινας παρ’ ἀλλήλων εὐεργεσίας τὰ γένη ταῦτα· τὰ μὲν γὰρ ἐπικουρεῖ τοῖς ὅπλοις, τὰ δὲ καρποῖς καὶ τέχναις καὶ ἠθοποιίαις. φανεραὶ δὲ καὶ αἱ ἐξ ἀλλήλων βλάβαι μὴ ἐπικουρούντων· ἔχει δέ τι πλεονέκτημα ἡ βία τῶν τὰ ὅπλα ἐχόντων, πλὴν εἰ τῷ πλήθει κρατοῖτο. ὑπάρχει δή τι καὶ πρὸς τοῦτο εὐφυὲς τῇ ἠπείρῳ ταύτῃ· ὅλη γὰρ διαπεποίκιλται πεδίοις τε καὶ ὄρεσιν, ὥστε πανταχοῦ καὶ τὸ γεωργικὸν καὶ τὸ πολιτικὸν καὶ τὸ μάχιμον παρακεῖσθαι· πλέον δ’ εἶναι θάτερον, τὸ τῆς εἰρήνης οἰκεῖον, ὥσθ’ ὅλων ἐπικρατεῖ τοῦτο, προσλαμβανόντων καὶ τῶν ἡγεμόνων Ἑλλήνων μὲν πρότερον Μακεδόνων δὲ καὶ Ῥωμαίων ὕστερον. διὰ τοῦτο δὲ καὶ πρὸς πόλεμον αὐταρκεστάτη ἐστί· καὶ γὰρ τὸ μάχιμον πλῆθος ἄφθονον ἔχει καὶ τὸ ἐργαζόμενον τὴν γῆν καὶ τὸ τὰς πόλεις συνέχον. διαφέρει δὲ καὶ ταύτῃ, διότι τοὺς καρποὺς ἐκφέρει τοὺς ἀρίστους καὶ τοὺς ἀναγκαίους τῷ βίῳ καὶ μέταλλα ὅσα χρήσιμα· θυώματα δὲ καὶ λίθους πολυτελεῖς ἔξωθεν μέτεισιν, ὧν τοῖς σπανιζομένοις οὐδὲν χείρων ὁ βίος ἐστὶν ἢ τοῖς εὐπορουμένοις. ὡς δ’ αὕτως βοσκημάτων μὲν πολλῶν ἀφθονίαν παρέχει, θηρίων δὲ σπάνιν. τοιαύτη μὲν ἡ ἤπειρος αὕτη καθόλου τὴν φύσιν ἐστί.", "st": "2.5.26"}, {"sp": "N", "t": "κατὰ μέρος δ’ ἐστὶ πρώτη πασῶν ἀπὸ τῆς ἑσπέρας ἡ Ἰβηρία, βύρσῃ βοείᾳ παραπλησία, τῶν ὡς ἂν τραχηλιμαίων μερῶν ὑπερπιπτόντων εἰς τὴν συνεχῆ Κελτικήν· ταῦτα δ’ ἐστὶ τὰ πρὸς ἕω, καὶ τούτοις ἐναποτέμνεται τὸ πλευρὸν * ὄρος ἡ καλουμένη Πυρήνη. * αὕτη δ’ ἐστὶ περίρρυτος τῇ θαλάττῃ τὸ μὲν νότιον τῇ καθ’ ἡμᾶς μέχρι στηλῶν, τὰ δὲ λοιπὰ τῇ Ἀτλαντικῇ μέχρι τῶν βορείων ἄκρων τῆς Πυρήνης. μῆκος δὲ τῆς χώρας ταύτης ἐστὶ περὶ ἑξακισχιλίους σταδίους τὸ μέγιστον, πλάτος δὲ πεντακισχιλίους.", "st": "2.5.27"}, {"sp": "N", "t": "μετὰ δὲ ταύτην ἐστὶν ἡ Κελτικὴ πρὸς ἕω μέχρι ποταμοῦ Ῥήνου, τὸ μὲν βόρειον πλευρὸν τῷ Βρεττανικῷ κλυζομένη πορθμῷ παντί· ἀντιπαρήκει γὰρ αὐτῇ παράλληλος ἡ νῆσος αὕτη πᾶσα πάσῃ, μῆκος ὅσον πεντακισχιλίους ἐπέχουσα· τὸ δ’ ἑωθινὸν τῷ Ῥήνῳ ποταμῷ περιγραφομένη παράλληλον ἔχοντι τὸ ῥεῦμα τῇ Πυρήνῃ· τὸ δὲ νότιον τὸ μὲν ταῖς Ἄλπεσι τὸ ἀπὸ τοῦ Ῥήνου, τὸ δ’ αὐτῇ τῇ καθ’ ἡμᾶς θαλάττῃ, καθ’ ὃ χωρίον ὁ καλούμενος Γαλατικὸς κόλπος ἀναχεῖται, καὶ ἐν αὐτῷ Μασσαλία τε καὶ Νάρβων ἵδρυνται πόλεις ἐπιφανέσταται. ἀντίκειται δὲ τῷ κόλπῳ τούτῳ κατ’ ἀποστροφὴν ἕτερος κόλπος ὁμωνύμως αὐτῷ καλούμενος Γαλατικός, βλέπων πρὸς τὰς ἄρκτους καὶ τὴν Βρεττανικήν· ἐνταῦθα δὲ καὶ στενώτατον λαμβάνει τὸ πλάτος ἡ Κελτική· συνάγεται γὰρ εἰς ἰσθμὸν ἐλαττόνων μὲν ἢ τρισχιλίων σταδίων, πλειόνων δ’ ἢ δισχιλίων. μεταξὺ δέ ἐστι ῥάχις ὀρεινὴ πρὸς ὀρθὰς τῇ Πυρήνῃ, τὸ καλούμενον Κέμμενον ὄρος· τελευτᾷ δὲ τοῦτο εἰς μεσαίτατα τὰ Κελτῶν πεδία. τῶν δὲ Ἄλπεων, ἅ ἐστιν ὄρη σφόδρα ὑψηλὰ ποιοῦντα περιφερῆ γραμμήν, τὸ μὲν κυρτὸν ἔστραπται πρὸς τὰ λεχθέντα τῶν Κελτῶν πεδία καὶ τὸ Κέμμενον ὄρος, τὸ δὲ κοῖλον πρὸς τὴν Λιγυστικὴν καὶ τὴν Ἰταλίαν. ἔθνη δὲ κατέχει πολλὰ τὸ ὄρος τοῦτο Κελτικὰ πλὴν τῶν Λιγύων· οὗτοι δ’ ἑτεροεθνεῖς μέν εἰσι, παραπλήσιοι δὲ τοῖς βίοις· νέμονται δὲ μέρος τῶν Ἄλπεων τὸ συνάπτον τοῖς Ἀπεννίνοις ὄρεσι, μέρος δὲ καὶ τῶν Ἀπεννίνων ὀρῶν κατέχουσι. ταῦτα δ’ ἐστὶν ὀρεινὴ ῥάχις διὰ τοῦ μήκους ὅλου τῆς Ἰταλίας διαπεφυκυῖα ἀπὸ τῶν ἄρκτων ἐπὶ μεσημβρίαν, τελευτῶσα δ’ ἐπὶ τὸν Σικελικὸν πορθμόν.", "st": "2.5.28"}, {"sp": "N", "t": "τῆς δ’ Ἰταλίας ἐστὶ τὰ μὲν πρῶτα μέρη τὰ ὑποπίπτοντα ταῖς Ἄλπεσι πεδία μέχρι τοῦ μυχοῦ τοῦ Ἀδρίου καὶ τῶν πλησίον τόπων, τὰ δ’ ἑξῆς ἄκρα στενὴ καὶ μακρὰ χερρονησιάζουσα, δι’ ἧς, ὡς εἶπον, ἐπὶ μῆκος τέταται τὸ Ἀπέννινον ὄρος ὅσον ἑπτακισχιλίων, πλάτος δ’ ἀνώμαλον. ποιεῖ δὲ τὴν Ἰταλίαν χερρόνησον τό τε Τυρρηνικὸν πέλαγος ἀρξάμενον ἀπὸ τοῦ Λιγυστικοῦ καὶ τὸ Αὐσόνιον καὶ ὁ Ἀδρίας.", "st": "2.5.29"}, {"sp": "N", "t": "μετὰ δὲ τὴν Ἰταλίαν καὶ τὴν Κελτικὴν τὰ πρὸς ἕω λοιπά ἐστι τῆς Εὐρώπης, ἃ δίχα τέμνεται τῷ Ἴστρῳ ποταμῷ. φέρεται δ’ οὗτος ἀπὸ τῆς ἑσπέρας ἐπὶ τὴν ἕω καὶ τὸν Εὔξεινον πόντον ἐν ἀριστερᾷ λιπὼν τήν τε Γερμανίαν ὅλην ἀρξαμένην ἀπὸ τοῦ Ῥήνου καὶ τὸ Γετικὸν πᾶν καὶ τὸ τῶν Τυρεγετῶν καὶ Βασταρνῶν καὶ Σαυροματῶν μέχρι Τανάιδος ποταμοῦ καὶ τῆς Μαιώτιδος λίμνης, ἐν δεξιᾷ δὲ τήν τε Θρᾴκην ἅπασαν καὶ τὴν Ἰλλυρίδα, λοιπὴν δὲ καὶ τελευταίαν τὴν Ἑλλάδα. πρόκεινται δὲ νῆσοι τῆς Εὐρώπης ἃς ἔφαμεν, ἔξω μὲν στηλῶν Γάδειρά τε καὶ Καττιτερίδες καὶ Βρεττανικαί, ἐντὸς δὲ στηλῶν αἵ τε Γυμνήσιαι καὶ ἄλλα νησίδια Φοινίκων καὶ τὰ τῶν Μασσαλιωτῶν καὶ Λιγύων καὶ αἱ πρὸ τῆς Ἰταλίας μέχρι τῶν Αἰόλου νήσων καὶ τῆς Σικελίας, ὅσαι τε περὶ τὴν Ἠπειρῶτιν καὶ Ἑλλάδα καὶ μέχρι Μακεδονίας καὶ τῆς Θρᾳκίας χερρονήσου.", "st": "2.5.30"}, {"sp": "N", "t": "Ἀπὸ δὲ τοῦ Τανάιδος καὶ τῆς Μαιώτιδός ἐστι τὰ ἐντὸς τοῦ Ταύρου συνεχῆ, τούτοις δ’ ἑξῆς τὰ ἐκτός. διαιρουμένης γὰρ αὐτῆς ὑπὸ ὄρους τοῦ Ταύρου δίχα διατείνοντος ἀπὸ τῶν ἄκρων τῆς Παμφυλίας ἐπὶ τὴν ἑῴαν θάλατταν κατ’ Ἰνδοὺς καὶ τοὺς ταύτῃ Σκύθας, τὸ μὲν πρὸς τὰς ἄρκτους νενευκὸς τῆς ἠπείρου μέρος καλοῦσιν οἱ Ἕλληνες ἐντὸς τοῦ Ταύρου, τὸ δὲ πρὸς μεσημβρίαν ἐκτός· τὰ δὴ συνεχῆ τῇ Μαιώτιδι καὶ τῷ Τανάιδι μέρη τὰ ἐντὸς τοῦ Ταύρου ἐστί. τούτων δὲ τὰ πρῶτα μέρη τὰ μεταξὺ τῆς Κασπίας θαλάττης ἐστὶ καὶ τοῦ Εὐξείνου πόντου, τῇ μὲν ἐπὶ τὸν Τάναϊν καὶ τὸν ὠκεανὸν τελευτῶντα τόν τε ἔξω καὶ τὸν τῆς Ὑρκανίας θαλάττης, τῇ δ’ ἐπὶ τὸν ἰσθμόν, καθ’ ὃ ἐγγυτάτω ἐστὶν ἀπὸ τοῦ μυχοῦ τοῦ Πόντου ἐπὶ τὴν Κασπίαν. ἔπειτα ἐντὸς τοῦ Ταύρου τὰ ὑπὲρ τῆς Ὑρκανίας μέχρι πρὸς τὴν κατὰ Ἰνδοὺς καὶ Σκύθας τοὺς πρὸς τὴν αὐτὴν θάλατταν καὶ τὸ Ἰμάιον ὄρος. ταῦτα δ’ ἔχουσι τὰ μὲν οἱ Μαιῶται καὶ οἱ μεταξὺ τῆς Ὑρκανίας καὶ τοῦ Πόντου μέχρι τοῦ Καυκάσου καὶ Ἰβήρων καὶ Ἀλβανῶν, Σαυρομάται καὶ Σκύθαι καὶ Ἀχαιοὶ καὶ Ζυγοὶ καὶ Ἡνίοχοι, τὰ δ’ ὑπὲρ τῆς Ὑρκανίας θαλάττης Σκύθαι καὶ Ὑρκανοὶ καὶ Παρθυαῖοι καὶ Βάκτριοι καὶ Σογδιανοὶ καὶ τἆλλα τὰ ὑπερκείμενα μέρη τῶν Ἰνδῶν πρὸς ἄρκτον. πρὸς νότον δὲ τῆς Ὑρκανίας θαλάττης ἐκ μέρους καὶ τοῦ ἰσθμοῦ παντὸς μεταξὺ ταύτης καὶ τοῦ Πόντου τῆς τε Ἀρμενίας ἡ πλείστη κεῖται καὶ Κολχὶς καὶ Καππαδοκία σύμπασα μέχρι τοῦ Εὐξείνου πόντου καὶ τῶν Τιβαρανικῶν ἐθνῶν, ἔτι δὲ ἡ ἐντὸς Ἅλυος χώρα λεγομένη, περιέχουσα πρὸς μὲν τῷ Πόντῳ καὶ τῇ Προποντίδι Παφλαγόνας τε καὶ Βιθυνοὺς καὶ Μυσοὺς καὶ τὴν ἐφ’ Ἑλλησπόντῳ λεγομένην Φρυγίαν, ἧς ἐστι καὶ ἡ Τρῳάς, πρὸς δὲ τῷ Αἰγαίῳ καὶ τῇ ἐφεξῆς θαλάττῃ τήν τε Αἰολίδα καὶ τὴν Ἰωνίαν καὶ Καρίαν καὶ Λυκίαν, ἐν δὲ τῇ μεσογαίᾳ τήν τε Φρυγίαν, ἧς ἐστι μέρος ἥ τε τῶν Γαλλογραικῶν λεγομένη Γαλατία καὶ ἡ Ἐπίκτητος, καὶ Λυκάονας καὶ Λυδούς.", "st": "2.5.31"}, {"sp": "N", "t": "Ἐφεξῆς δὲ τοῖς ἐντὸς τοῦ Ταύρου οἵ τε τὰ ὄρη κατέχοντες Παροπαμισάδαι καὶ τὰ Παρθυαίων τε καὶ Μήδων καὶ Ἀρμενίων καὶ Κιλίκων ἔθνη καὶ Κατάονες καὶ Πισίδαι. μετὰ δὲ τοὺς ὀρείους ἐστὶ τὰ ἐκτὸς τοῦ Ταύρου. πρώτη δ’ ἐστὶ τούτων ἡ Ἰνδική, ἔθνος μέγιστον τῶν πάντων καὶ εὐδαιμονέστατον, τελευτῶν πρός τε τὴν ἑῴαν θάλατταν καὶ τὴν νοτίαν τῆς Ἀτλαντικῆς. ἐν δὲ τῇ νοτίᾳ ταύτῃ θαλάττῃ πρόκειται τῆς Ἰνδικῆς νῆσος οὐκ ἐλάττων τῆς Βρεττανικῆς ἡ Ταπροβάνη· μετὰ δὲ τὴν Ἰνδικὴν ἐπὶ τὰ ἑσπέρια νεύουσιν, ἐν δεξιᾷ δ’ ἔχουσι τὰ ὄρη χώρα ἐστὶ συχνή, φαύλως οἰκουμένη διὰ λυπρότητα ὑπ’ ἀνθρώπων τελέως βαρβάρων οὐχ ὁμοεθνῶν· καλοῦσι δ’ Ἀριανούς, ἀπὸ τῶν ὀρῶν διατείνοντας μέχρι Γεδρωσίας καὶ Καρμανίας. ἑξῆς δέ εἰσι πρὸς μὲν τῇ θαλάττῃ Πέρσαι καὶ Σούσιοι καὶ Βαβυλώνιοι καθήκοντες ἐπὶ τὴν κατὰ Πέρσας θάλατταν καὶ τὰ περιοικοῦντα τούτους ἔθνη μικρά, πρὸς δὲ τοῖς ὄρεσιν ἢ ἐν αὐτοῖς τοῖς ὄρεσι Παρθυαῖοι καὶ Μῆδοι καὶ Ἀρμένιοι καὶ τὰ τούτοις πρόσχωρα ἔθνη καὶ ἡ Μεσοποταμία. μετὰ δὲ τὴν Μεσοποταμίαν τὰ ἐντὸς Εὐφράτου· ταῦτα δ’ ἐστὶν ἥ τε εὐδαίμων Ἀραβία πᾶσα, ἀφοριζομένη τῷ τε Ἀραβίῳ κόλπῳ παντὶ καὶ τῷ Περσικῷ, καὶ ὅσην οἱ Σκηνῖται καὶ οἱ Φύλαρχοι κατέχουσιν οἱ ἐπὶ τὸν Εὐφράτην καθήκοντες καὶ τὴν Συρίαν· εἶθ’ οἱ πέραν τοῦ Ἀραβίου κόλπου μέχρι Νείλου, Αἰθίοπές τε καὶ Ἄραβες, καὶ οἱ μετ’ αὐτοὺς Αἰγύπτιοι καὶ Σύροι καὶ Κίλικες οἵ τε ἄλλοι καὶ οἱ Τραχειῶται λεγόμενοι, τελευταῖοι δὲ Πάμφυλοι.", "st": "2.5.32"}, {"sp": "N", "t": "μετὰ δὲ τὴν Ἀσίαν ἐστὶν ἡ Λιβύη συνεχὴς οὖσα τῇ τε Αἰγύπτῳ καὶ τῇ Αἰθιοπίᾳ, τὴν μὲν καθ’ ἡμᾶς ᾐόνα ἐπ’ εὐθείας ἔχουσα, σχεδόν τι μέχρι στηλῶν ἀπὸ Ἀλεξανδρείας ἀρξαμένην, πλὴν τῶν Σύρτεων καὶ εἴ πού τις ἄλλη κόλπων ἐπιστροφὴ μετρία καὶ τῶν ταύτην ποιούντων ἀκρωτηρίων ἐξοχή· τὴν δὲ παρωκεανῖτιν ἀπὸ τῆς Αἰθιοπίας μέχρι τινός, ὡς ἂν παράλληλον οὖσαν τῇ προτέρᾳ, μετὰ δὲ ταῦτα συναγομένην ἀπὸ τῶν νοτίων μερῶν εἰς ὀξεῖαν ἄκραν, μικρὸν ἔξω στηλῶν προπεπτωκυῖαν καὶ ποιοῦσαν τραπέζιόν πως τὸ σχῆμα. ἔστι δ’, ὥσπερ οἵ τε ἄλλοι δηλοῦσι καὶ δὴ καὶ Γναῖος Πείσων ἡγεμὼν γενόμενος τῆς χώρας διηγεῖτο ἡμῖν, ἐοικυῖα παρδαλῇ· κατάστικτος γάρ ἐστιν οἰκήσεσι περιεχομέναις ἀνύδρῳ καὶ ἐρήμῳ γῇ· καλοῦσι δὲ τὰς τοιαύτας οἰκήσεις αὐάσεις οἱ Αἰγύπτιοι. τοιαύτη δὲ οὖσα ἔχει τινὰς ἄλλας διαφορὰς τριχῆ διαιρουμένας· τῆς μὲν γὰρ καθ’ ἡμᾶς παραλίας εὐδαίμων ἐστὶν ἡ πλείστη σφόδρα, καὶ μάλιστα ἡ Κυρηναία καὶ ἡ περὶ Καρχηδόνα [μέχρι] Μαυρουσίων καὶ τῶν Ἡρακλείων στηλῶν· οἰκεῖται δὲ μετρίως καὶ ἡ παρωκεανῖτις, ἡ δὲ μέση φαύλως ἡ τὸ σίλφιον φέρουσα, ἔρημος ἡ πλείστη καὶ τραχεῖα καὶ ἀμμώδης. τὸ δ’ αὐτὸ πέπονθε καὶ ἡ ἐπ’ εὐθείας ταύτῃ διά τε τῆς Αἰθιοπίας διήκουσα τῆς τε Τρωγλοδυτικῆς καὶ τῆς Ἀραβίας καὶ τῆς Γεδρωσίας τῆς τῶν Ἰχθυοφάγων. νέμεται δ’ ἔθνη τὴν Λιβύην τὰ πλεῖστα ἄγνωστα· οὐ πολλὴν γὰρ ἐφοδεύεσθαι συμβαίνει στρατοπέδοις οὐδ’ ἀλλοφύλοις ἀνδράσιν, οἱ δ’ ἐπιχώριοι καὶ ὀλίγοι παρ’ ἡμᾶς ἀφικνοῦνται πόρρωθεν, καὶ οὐ πιστὰ οὐδὲ πάντα λέγουσιν· ὅμως δ’ οὖν τὰ λεγόμενα τοιαῦτά ἐστι. τοὺς μὲν μεσημβρινωτάτους Αἰθίοπας προσαγορεύουσι, τοὺς δ’ ὑπὸ τούτοις τοὺς πλείστους Γαράμαντας καὶ Φαρουσίους καὶ Νιγρίτας, τοὺς δ’ ἔτι ὑπὸ τούτοις Γαιτούλους, τοὺς δὲ τῆς θαλάττης ἐγγὺς ἢ καὶ ἁπτομένους αὐτῆς πρὸς Αἰγύπτῳ μὲν Μαρμαρίδας μέχρι τῆς Κυρηναίας, ὑπὲρ δὲ ταύτης καὶ τῶν Σύρτεων Ψύλλους καὶ Νασαμῶνας καὶ τῶν Γαιτούλων τινάς, εἶτ’ Ἀσβύστας καὶ Βυζακίους μέχρι τῆς Καρχηδονίας. πολλὴ δ’ ἐστὶν ἡ Καρχηδονία· συνάπτουσι δ’ οἱ νομάδες αὐτῇ· τούτων δὲ τοὺς γνωριμωτάτους τοὺς μὲν Μασυλιεῖς τοὺς δὲ Μασαισυλίους προσαγορεύουσιν· ὕστατοι δ’ εἰσὶ Μαυρούσιοι. πᾶσα δ’ ἡ ἀπὸ Καρχηδόνος μέχρι στηλῶν ἐστιν εὐδαίμων, θηριοτρόφος δέ, ὥσπερ καὶ ἡ μεσόγαια πᾶσα. οὐκ ἀπεικὸς δὲ καὶ νομάδας λεχθῆναί τινας αὐτῶν, οὐ δυναμένους γεωργεῖν διὰ τὸ πλῆθος τῶν θηρίων τὸ παλαιόν· οἱ δὲ νῦν ἅμα τῇ ἐμπειρίᾳ τῆς θήρας διαφέροντες, καὶ τῶν Ῥωμαίων προσλαμβανόντων πρὸς τοῦτο διὰ τὴν σπουδὴν τὴν περὶ τὰς θηριομαχίας, ἀμφοτέρων περιγίνονται καὶ τῶν θηρίων καὶ τῆς γεωργίας. τοσαῦτα καὶ περὶ τῶν ἠπείρων λέγομεν.", "st": "2.5.33"}, {"sp": "N", "t": "λοιπὸν εἰπεῖν περὶ τῶν κλιμάτων, ὅπερ καὶ αὐτὸ ἔχει καθολικὴν ὑποτύπωσιν, ὁρμηθεῖσιν ἐκ τῶν γραμμῶν ἐκείνων, ἃ στοιχεῖα ἐκαλέσαμεν, λέγω δὲ τῆς τε τὸ μῆκος ἀφοριζούσης τὸ μέγιστον καὶ τῆς τὸ πλάτος, μάλιστα δὲ τῆς τὸ πλάτος. τοῖς μὲν οὖν ἀστρονομικοῖς ἐπὶ πλέον τοῦτο ποιητέον, καθάπερ Ἵππαρχος ἐποίησεν. ἀνέγραψε γάρ, ὡς αὐτός φησι, τὰς γινομένας ἐν τοῖς οὐρανίοις διαφορὰς καθ’ ἕκαστον τῆς γῆς τόπον τῶν ἐν τῷ καθ’ ἡμᾶς τεταρτημορίῳ τεταγμένων, λέγω δὲ τῶν ἀπὸ τοῦ ἰσημερινοῦ μέχρι τοῦ βορείου πόλου. τοῖς δὲ γεωγραφοῦσιν οὔτε τῶν ἔξω τῆς καθ’ ἡμᾶς οἰκουμένης φροντιστέον, οὔτ’ ἐν αὐτοῖς [τοῖς] τῆς οἰκουμένης μέρεσι τὰς τοιαύτας καὶ τοσαύτας διαφορὰς παραδεκτέον τῷ πολιτικῷ· περισκελεῖς γάρ εἰσιν. ἀλλ’ ἀρκεῖ τὰς σημειώδεις καὶ ἁπλουστέρας ἐκθέσθαι τῶν ὑπ’ αὐτοῦ λεχθεισῶν, ὑποθεμένοις, ὥσπερ ἐκεῖνος, εἶναι τὸ μέγεθος τῆς γῆς σταδίων εἴκοσι πέντε μυριάδων καὶ δισχιλίων, ὡς καὶ Ἐρατοσθένης ἀποδίδωσιν· οὐ μεγάλη γὰρ παρὰ τοῦτ’ ἔσται διαφορὰ πρὸς τὰ φαινόμενα ἐν τοῖς μεταξὺ τῶν οἰκήσεων διαστήμασιν. εἰ δή τις εἰς τριακόσια ἑξήκοντα τμήματα τέμοι τὸν μέγιστον τῆς γῆς κύκλον, ἔσται ἑπτακοσίων σταδίων ἕκαστον τῶν τμημάτων· τούτῳ δὴ χρῆται μέτρῳ πρὸς τὰ διαστήματα [τὰ] ἐν τῷ λεχθέντι διὰ Μερόης μεσημβρινῷ λαμβάνεσθαι μέλλοντα. ἐκεῖνος μὲν δὴ ἄρχεται ἀπὸ τῶν ἐν τῷ ἰσημερινῷ οἰκούντων, καὶ λοιπὸν ἀεὶ δι’ ἑπτακοσίων σταδίων τὰς ἐφεξῆς οἰκήσεις ἐπιὼν κατὰ τὸν λεχθέντα μεσημβρινὸν πειρᾶται λέγειν τὰ παρ’ ἑκάστοις φαινόμενα· ἡμῖν δ’ οὐκ ἐντεῦθεν ἀρκτέον. καὶ γὰρ εἰ οἰκήσιμα ταῦτά ἐστιν, ὥσπερ οἴονταί τινες, ἰδία γέ τις οἰκουμένη αὕτη ἐστί, διὰ μέσης τῆς ἀοικήτου διὰ καῦμα στενὴ τεταμένη, οὐκ οὖσα μέρος τῆς καθ’ ἡμᾶς οἰκουμένης· ὁ δὲ γεωγράφος ἐπισκοπεῖ ταύτην μόνην τὴν καθ’ ἡμᾶς οἰκουμένην. αὕτη δ’ ἀφορίζεται πέρασι νοτίῳ μὲν τῷ διὰ τῆς Κινναμωμοφόρου παραλλήλῳ, βορείῳ δὲ τῷ διὰ Ἰέρνης· οὔτε δὲ τὰς τοσαύτας οἰκήσεις ἐπιτέον ὅσας ὑπαγορεύει τὸ λεχθὲν μεταξὺ διάστημα, οὔτε πάντα τὰ φαινόμενα θετέον, μεμνημένοις τοῦ γεωγραφικοῦ σχήματος. ἀρκτέον δ’, ὥσπερ Ἵππαρχος, ἀπὸ τῶν νοτίων μερῶν.", "st": "2.5.34"}, {"sp": "N", "t": "φησὶ δὴ τοῖς οἰκοῦσιν ἐπὶ τῷ διὰ τῆς Κινναμωμοφόρου παραλλήλῳ, ὃς ἀπέχει τῆς Μερόης τρισχιλίους σταδίους πρὸς νότον, τούτου δ’ ὁ ἰσημερινὸς ὀκτακισχιλίους καὶ ὀκτακοσίους, εἶναι τὴν οἴκησιν ἐγγυτάτω μέσην τοῦ τε ἰσημερινοῦ καὶ τοῦ θερινοῦ τροπικοῦ τοῦ κατὰ Συήνην· ἀπέχειν γὰρ τὴν Συήνην πεντακισχιλίους τῆς Μερόης· παρὰ δὲ τούτοις πρώτοις τὴν μικρὰν ἄρκτον ὅλην ἐν τῷ ἀρκτικῷ περιέχεσθαι καὶ ἀεὶ φαίνεσθαι· τὸν γὰρ ἐπ’ ἄκρας τῆς οὐρᾶς λαμπρὸν ἀστέρα, νοτιώτατον ὄντα, ἐπ’ αὐτοῦ ἱδρῦσθαι τοῦ ἀρκτικοῦ κύκλου ὥστ’ ἐφάπτεσθαι τοῦ ὁρίζοντος. τῷ δὲ λεχθέντι μεσημβρινῷ παράλληλός πως παράκειται ἕωθεν ὁ Ἀράβιος κόλπος· τούτου δ’ ἔκβασις εἰς τὸ ἔξω πέλαγος ἡ Κινναμωμοφόρος ἐστίν, ἐφ’ ἧς ἡ τῶν ἐλεφάντων γέγονε θήρα τὸ παλαιόν. ἐκπίπτει δ’ ὁ παράλληλος οὗτος τῇ μὲν ἐπὶ τοὺς νοτιωτέρους μικρὸν τῆς Ταπροβάνης ἢ ἐπὶ τοὺς ἐσχάτους οἰκοῦντας, τῇ δ’ ἐπὶ τὰ νοτιώτατα τῆς Λιβύης.", "st": "2.5.35"}, {"sp": "N", "t": "τοῖς δὲ κατὰ Μερόην καὶ Πτολεμαΐδα τὴν ἐν τῇ Τρωγλοδυτικῇ ἡ μεγίστη ἡμέρα ὡρῶν ἰσημερινῶν ἐστι τρισκαίδεκα· ἔστι δ’ αὕτη ἡ οἴκησις μέση πως τοῦ τε ἰσημερινοῦ καὶ τοῦ δι’ Ἀλεξανδρείας παρὰ χιλίους καὶ ὀκτακοσίους τοὺς πλεονάζοντας πρὸς τῷ ἰσημερινῷ· διήκει δ’ ὁ διὰ Μερόης παράλληλος τῇ μὲν δι’ ἀγνωρίστων μερῶν, τῇ δὲ διὰ τῶν ἄκρων τῆς Ἰνδικῆς. ἐν δὲ Συήνῃ καὶ Βερενίκῃ τῇ ἐν τῷ Ἀραβίῳ κόλπῳ καὶ τῇ Τρωγλοδυτικῇ κατὰ θερινὰς τροπὰς ὁ ἥλιος κατὰ κορυφῆς γίνεται, ἡ δὲ μακροτάτη ἡμέρα ὡρῶν ἰσημερινῶν ἐστι τρισκαίδεκα καὶ ἡμιωρίου, ἐν δὲ τῷ ἀρκτικῷ φαίνεται καὶ ἡ μεγάλη ἄρκτος ὅλη σχεδόν τι πλὴν τῶν σκελῶν καὶ τοῦ ἄκρου τῆς οὐρᾶς καὶ ἑνὸς τῶν ἐν τῷ πλινθίῳ ἀστέρων. ὁ δὲ διὰ Συήνης παράλληλος τῇ μὲν διὰ τῆς τῶν Ἰχθυοφάγων τῶν κατὰ τὴν Γεδρωσίαν καὶ τῆς Ἰνδικῆς διήκει, τῇ δὲ διὰ τῶν νοτιωτέρων Κυρήνης πεντακισχιλίοις σταδίοις παρὰ μικρόν.", "st": "2.5.36"}, {"sp": "N", "t": "̔́απασι δὲ τοῖς μεταξὺ κειμένοις τοῦ τε τροπικοῦ καὶ τοῦ ἰσημερινοῦ κύκλου μεταπίπτουσιν αἱ σκιαὶ ἐφ’ ἑκάτερα, πρός τε ἄρκτους καὶ μεσημβρίαν, τοῖς δ’ ἀπὸ Συήνης ἐκ τοῦ θερινοῦ τροπικοῦ πρὸς ἄρκτους πίπτουσιν αἱ σκιαὶ κατὰ μεσημβρίαν· καλοῦνται δ’ οἱ μὲν ἀμφίσκιοι οἱ δ’ ἑτερόσκιοι. ἔστι δέ τις καὶ ἄλλη διαφορὰ τοῖς ὑπὸ τῷ τροπικῷ, ἣν προείπομεν ἐν τῷ περὶ τῶν ζωνῶν λόγῳ. αὐτή τε γάρ ἐστιν δίαμμος καὶ σιλφιοφόρος καὶ ξηρά, τῶν νοτιωτέρων μερῶν εὐύδρων τε καὶ εὐκάρπων ὄντων.", "st": "2.5.37"}, {"sp": "N", "t": "Ἐν δὲ τοῖς [τοῦ] δι’ Ἀλεξανδρείας καὶ Κυρήνης νοτιωτέροις ὅσον τετρακοσίοις σταδίοις, ὅπου ἡ μεγίστη ἡμέρα ὡρῶν ἐστιν ἰσημερινῶν δεκατεττάρων, κατὰ κορυφὴν γίνεται ὁ ἀρκτοῦρος μικρὸν ἐκκλίνων πρὸς νότον. ἐν δὲ τῇ Ἀλεξανδρείᾳ ὁ γνώμων λόγον ἔχει πρὸς τὴν ἰσημερινὴν σκιάν, ὃν ἔχει τὰ πέντε πρὸς τρία. Καρχηδόνος δὲ νοτιώτεροί εἰσι χιλίοις καὶ τριακοσίοις σταδίοις, εἴπερ ἐν Καρχηδόνι ὁ γνώμων λόγον ἔχει πρὸς τὴν ἰσημερινὴν σκιάν, ὃν ἔχει τὰ ἕνδεκα πρὸς τὰ ἑπτά. διήκει δ’ ὁ παράλληλος οὗτος τῇ μὲν διὰ Κυρήνης καὶ τῶν νοτιωτέρων Καρχηδόνος ἐνακοσίοις σταδίοις μέχρι Μαυρουσίας μέσης, τῇ δὲ δι’ Αἰγύπτου καὶ Κοίλης Συρίας καὶ τῆς ἄνω Συρίας καὶ Βαβυλωνίας καὶ Σουσιάδος Περσίδος Καρμανίας Γεδρωσίας τῆς ἄνω μέχρι τῆς Ἰνδικῆς.", "st": "2.5.38"}, {"sp": "N", "t": "Ἐν δὲ τοῖς περὶ Πτολεμαΐδα τὴν ἐν τῇ Φοινίκῃ καὶ Σιδῶνα καὶ Τύρον ἡ μεγίστη ἡμέρα ἐστὶν ὡρῶν ἰσημερινῶν δεκατεττάρων καὶ τετάρτου· βορειότεροι δ’ εἰσὶν οὗτοι Ἀλεξανδρείας μὲν ὡς χιλίοις ἑξακοσίοις σταδίοις, Καρχηδόνος δὲ ὡς ἑπτακοσίοις. ἐν δὲ τῇ Πελοποννήσῳ καὶ περὶ τὰ μέσα τῆς Ῥοδίας καὶ περὶ Ξάνθον τῆς Λυκίας ἢ τὰ μικρῷ νοτιώτερα καὶ ἔτι τὰ Συρακοσίων νοτιώτερα τετρακοσίοις σταδίοις, ἐνταῦθα ἡ μεγίστη ἡμέρα ἐστὶν ὡρῶν ἰσημερινῶν δεκατεττάρων καὶ ἡμίσους· ἀπέχουσι δ’ οἱ τόποι οὗτοι Ἀλεξανδρείας μὲν τρισχιλίους ἑξακοσίους τετταράκοντα …· διήκει δ’ ὁ παράλληλος οὗτος κατ’ Ἐρατοσθένη διὰ Καρίας Λυκαονίας Καταονίας Μηδίας Κασπίων πυλῶν Ἰνδῶν τῶν κατὰ Καύκασον.", "st": "2.5.39"}, {"sp": "N", "t": "Ἐν δὲ τοῖς περὶ Ἀλεξάνδρειαν μέρεσι τῆς Τρῳάδος, κατ’ Ἀμφίπολιν καὶ Ἀπολλωνίαν τὴν ἐν Ἠπείρῳ, καὶ τοὺς Ῥώμης μὲν νοτιωτέρους βορειοτέρους δὲ Νεαπόλεως, ἡ μεγίστη ἡμέρα ἐστὶν ὡρῶν ἰσημερινῶν δεκαπέντε ἀπέχει δὲ ὁ παράλληλος οὗτος τοῦ μὲν δι’ Ἀλεξανδρείας τῆς πρὸς Αἰγύπτῳ ὡς ἑπτακισχιλίους σταδίους πρὸς ἄρκτον, τοῦ δ’ ἰσημερινοῦ ὑπὲρ δισμυρίους ὀκτακισχιλίους ὀκτακοσίους, τοῦ δὲ διὰ Ῥόδου τρισχιλίους τετρακοσίους, πρὸς νότον δὲ Βυζαντίου καὶ Νικαίας καὶ τῶν περὶ Μασσαλίαν χιλίους πεντακοσίους, μικρὸν δ’ ἀρκτικώτερός ἐστιν ὁ διὰ Λυσιμαχείας, ὅν φησιν Ἐρατοσθένης διὰ Μυσίας εἶναι καὶ Παφλαγονίας καὶ τῶν περὶ Σινώπην καὶ Ὑρκανίαν καὶ Βάκτρα.", "st": "2.5.40"}, {"sp": "N", "t": "Ἐν δὲ τοῖς περὶ τὸ Βυζάντιον ἡ μεγίστη ἡμέρα ὡρῶν ἐστιν ἰσημερινῶν δεκαπέντε καὶ τετάρτου, ὁ δὲ γνώμων πρὸς τὴν σκιὰν λόγον ἔχει ἐν τῇ θερινῇ τροπῇ ὃν τὰ ἑκατὸν εἴκοσι πρὸς τετταράκοντα δύο λείποντα πέμπτῳ. ἀπέχουσι δ’ οἱ τόποι οὗτοι τοῦ διὰ μέσης τῆς Ῥοδίας περὶ τετρακισχιλίους καὶ ἐνακοσίους, τοῦ δ’ ἰσημερινοῦ ὡς τρισμυρίους τριακοσίους. εἰσπλεύσασι δ’ εἰς τὸν Πόντον καὶ προελθοῦσιν ἐπὶ τὰς ἄρκτους ὅσον χιλίους καὶ τετρακοσίους ἡ μεγίστη ἡμέρα γίνεται ὡρῶν ἰσημερινῶν δεκαπέντε καὶ ἡμίσους ἀπέχουσι δ’ οἱ τόποι οὗτοι ἴσον ἀπό τε τοῦ πόλου καὶ τοῦ ἰσημερινοῦ κύκλου, καὶ ὁ ἀρκτικὸς κύκλος κατὰ κορυφὴν αὐτοῖς ἐστιν, ἐφ’ οὗ κεῖται ὅ τ’ ἐν τῷ τραχήλῳ τῆς Κασσιεπείας καὶ ὁ ἐν τῷ δεξιῷ ἀγκῶνι τοῦ Περσέως μικρῷ βορειότερος ὤν.", "st": "2.5.41"}, {"sp": "N", "t": "ἔν τε τοῖς ἀπέχουσι Βυζαντίου πρὸς ἄρκτον ὅσον τρισχιλίους ὀκτακοσίους ἡ μεγίστη ἡμέρα ἐστὶν ὡρῶν ἰσημερινῶν δεκαέξ· ἡ οὖν δὴ Κασσιέπεια ἐν τῷ ἀρκτικῷ φέρεται. εἰσὶ δ’ οἱ τόποι οὗτοι περὶ Βορυσθένη καὶ τῆς Μαιώτιδος τὰ νότια· ἀπέχουσι δὲ τοῦ ἰσημερινοῦ περὶ τρισμυρίους τετρακισχιλίους ἑκατόν. ὁ δὲ κατὰ τὰς ἄρκτους τόπος τοῦ ὁρίζοντος ἐν ὅλαις σχεδόν τι ταῖς θεριναῖς νυξὶ παραυγάζεται ὑπὸ τοῦ ἡλίου ἀπὸ δύσεως ἕως καὶ ἀνατολῆς ἀντιπεριισταμένου τοῦ φωτός. ὁ γὰρ θερινὸς τροπικὸς ἀπέχει ἀπὸ τοῦ ὁρίζοντος ἑνὸς ζωδίου ἥμισυ καὶ δωδέκατον· τοσοῦτον οὖν καὶ ὁ ἥλιος ἀφίσταται τοῦ ὁρίζοντος κατὰ τὸ μεσονύκτιον. καὶ παρ’ ἡμῖν δὲ τοσοῦτον τοῦ ὁρίζοντος ἀποσχὼν πρὸ τοῦ ὄρθρου καὶ μετὰ τὴν ἑσπέραν ἤδη καταυγάζει τὸν περὶ τὴν ἀνατολὴν ἢ τὴν δύσιν ἀέρα. ἐν δὲ ταῖς χειμεριναῖς ὁ ἥλιος τὸ πλεῖστον μετεωρίζεται πήχεις ἐννέα. φησὶ δ’ Ἐρατοσθένης τούτους τῆς Μερόης διέχειν μικρῷ πλείους ἢ δισμυρίους τρισχιλίους. διὰ γὰρ Ἑλλησπόντου εἶναι μυρίους ὀκτακισχιλίους, εἶτα πεντακισχιλίους εἰς Βυρυσθένη. ἐν δὲ τοῖς ἀπέχουσι τοῦ Βυζαντίου σταδίους περὶ ἑξακισχιλίους τριακοσίους, βορειοτέροις οὖσι τῆς Μαιώτιδος, κατὰ τὰς χειμερινὰς ἡμέρας μετεωρίζεται τὸ πλεῖστον ὁ ἥλιος ἐπὶ πήχεις ἕξ, ἡ δὲ μεγίστη ἡμέρα ἐστὶν ὡρῶν ἰσημερινῶν δεκαεπτά.", "st": "2.5.42"}, {"sp": "N", "t": "τὰ δ’ ἐπέκεινα ἤδη πλησιάζοντα τῇ ἀοικήτῳ διὰ ψῦχος οὐκέτι χρήσιμα τῷ γεωγράφῳ ἐστίν. ὁ δὲ βουλόμενος καὶ ταῦτα μαθεῖν καὶ ὅσα ἄλλα τῶν οὐρανίων Ἵππαρχος μὲν εἴρηκεν ἡμεῖς δὲ παραλείπομεν διὰ τὸ τρανότερα εἶναι τῆς νῦν προκειμένης πραγματείας, παρ’ ἐκείνου λαμβανέτω. τρανότερα δ’ ἐστὶ καὶ τὰ περὶ τῶν περισκίων καὶ ἀμφισκίων καὶ ἑτεροσκίων, ἅ φησι Ποσειδώνιος. ὅμως γε καὶ τούτων τό γε τοσοῦτον ἐπιμνηστέον ὥστε τὴν ἐπίνοιαν διασαφῆσαι καὶ πῆ χρήσιμον πρὸς τὴν γεωγραφίαν καὶ πῆ ἄχρηστον. ἐπεὶ δὲ περὶ τῶν ἀφ’ ἡλίου σκιῶν ὁ λόγος ἐστίν, ὁ δ’ ἥλιος πρὸς αἴσθησιν κατὰ παραλλήλου φέρεται καθ’ οὗ καὶ ὁ κόσμος, παρ’ οἷς καθ’ ἑκάστην κόσμου περιστροφὴν ἡμέρα γίνεται καὶ νύξ, ὅτε μὲν ὑπὲρ γῆς τοῦ ἡλίου φερομένου ὅτε δ’ ὑπὸ γῆν, παρὰ τούτοις οἵ τε ἀμφίσκιοι ἐπινοοῦνται καὶ οἱ ἑτερόσκιοι. ἀμφίσκιοι μὲν ὅσοι κατὰ μέσον ἡμέρας τοτὲ μὲν ἐπὶ τάδε πιπτούσας ἔχουσι τὰς σκιάς, ὅταν ὁ ἥλιος ἀπὸ μεσημβρίας τῷ γνώμονι προσπίπτῃ τῷ ὀρθῷ πρὸς τὸ ὑποκείμενον ἐπίπεδον, τοτὲ δ’ εἰς τοὐναντίον, ὅταν ὁ ἥλιος εἰς τοὐναντίον περιστῇ (τοῦτο δὲ συμβέβηκε μόνοις τοῖς μεταξὺ τῶν τροπικῶν οἰκοῦσιν), ἑτερόσκιοι δ’ ὅσοις ἢ ἐπὶ τὴν ἄρκτον ἀεὶ πίπτουσιν ὥσπερ ἡμῖν, ἢ ἐπὶ τὰ νότια ὥσπερ τοῖς ἐν τῇ ἑτέρᾳ εὐκράτῳ ζώνῃ οἰκοῦσι· τοῦτο δὲ συμβαίνει πᾶσι τοῖς ἐλάττονα ἔχουσι τοῦ τροπικοῦ τὸν ἀρκτικόν. ὅταν δὲ τὸν αὐτὸν ἢ μείζονα, ἀρχὴ τῶν περισκίων ἐστὶ μέχρι τῶν οἰκούντων ὑπὸ τῷ πόλῳ. τοῦ γὰρ ἡλίου καθ’ ὅλην τὴν τοῦ κόσμου περιστροφὴν ὑπὲρ γῆς φερομένου, δῆλον ὅτι καὶ ἡ σκιὰ κύκλῳ περιενεχθήσεται περὶ τὸν γνώμονα· καθ’ ὃ δὴ καὶ περισκίους αὐτοὺς ἐκάλεσεν, οὐδὲν ὄντας πρὸς τὴν γεωγραφίαν· οὐ γάρ ἐστιν οἰκήσιμα ταῦτα τὰ μέρη διὰ ψῦχος, ὥσπερ ἐν τοῖς πρὸς Πυθέαν λόγοις εἰρήκαμεν. ὥστ’ οὐδὲ τοῦ μεγέθους τῆς ἀοικήτου ταύτης φροντιστέον ἐκ τοῦ λαβεῖν, ὅτι οἱ ἔχοντες ἀρκτικὸν τὸν τροπικὸν ὑποπεπτώκασι τῷ γραφομένῳ κύκλῳ ὑπὸ τοῦ πόλου τοῦ ζωδιακοῦ κατὰ τὴν τοῦ κόσμου περιστροφήν, ὑποκειμένου τοῦ μεταξὺ διαστήματος τοῦ τε ἰσημερινοῦ καὶ τοῦ τροπικοῦ τεττάρων ἑξηκοστῶν τοῦ μεγίστου κύκλου.", "st": "2.5.43"}, {"sp": "HDR", "t": "Βιβλίον Γʹ", "st": "3"}, {"sp": "N", "t": "Ἀποδεδωκόσι δ’ ἡμῖν τὸν πρῶτον τύπον τῆς γεωγραφίας οἰκεῖός ἐστιν ὁ ἐφεξῆς λόγος περὶ τῶν καθ’ ἕκαστα· καὶ γὰρ ὑπεσχόμεθα οὕτως καὶ δοκεῖ μέχρι νῦν ὀρθῶς ἡ πραγματεία μεμερίσθαι. ἀρκτέον δὲ πάλιν ἀπὸ τῆς Εὐρώπης καὶ τῶν μερῶν αὐτῆς τούτων ἀφ’ ὧνπερ καὶ πρότερον κατὰ τὰς αὐτὰς αἰτίας.", "st": "3.1.1"}, {"sp": "N", "t": "πρῶτον δὲ μέρος αὐτῆς ἐστι τὸ ἑσπέριον, ὡς ἔφαμεν, ἡ Ἰβηρία. ταύτης δὴ τὸ μὲν πλέον οἰκεῖται φαύλως· ὄρη γὰρ καὶ δρυμοὺς καὶ πεδία λεπτὴν ἔχοντα γῆν οὐδὲ ταύτην ὁμαλῶς εὔυδρον οἰκοῦσι τὴν πολλήν· ἡ δὲ πρόσβορρος ψυχρά τέ ἐστι τελέως πρὸς τῇ τραχύτητι καὶ παρωκεανῖτις, προσειληφυῖα τὸ ἄμικτον κἀνεπίπλεκτον τοῖς ἄλλοις, ὥσθ’ ὑπερβάλλει τῇ μοχθηρίᾳ τῆς οἰκήσεως. ταῦτα μὲν δὴ τὰ μέρη τοιαῦτα, ἡ δὲ νότιος πᾶσα εὐδαίμων σχεδόν τι καὶ διαφερόντως ἡ ἔξω στηλῶν· ἔσται δὲ δῆλον ἐν τοῖς καθ’ ἕκαστα ὑπογράψασιν ἡμῖν πρότερον τό τε σχῆμα καὶ τὸ μέγεθος.", "st": "3.1.2"}, {"sp": "N", "t": "ἔοικε γὰρ βύρσῃ τεταμένῃ κατὰ μῆκος μὲν ἀπὸ τῆς ἑσπέρας ἐπὶ τὴν ἕω τὰ πρόσθια ἐχούσῃ μέρη πρὸς τῇ ἕῳ, κατὰ πλάτος δ’ ἀπὸ τῶν ἄρκτων πρὸς νότον. ἔχει δὲ σταδίων ἑξακισχιλίων ὁμοῦ τὸ μῆκος, πλάτος δὲ πεντακισχιλίων τὸ μέγιστον, ἔστι δ’ ὅπου πολὺ ἔλαττον τῶν τρισχιλίων καὶ μάλιστα πρὸς τῇ Πυρήνῃ τῇ ποιούσῃ τὴν ἑῴαν πλευράν· ὄρος γὰρ διηνεκὲς ἀπὸ νότου πρὸς βορρᾶν τεταμένον ὁρίζει τὴν Κελτικὴν ἀπὸ τῆς Ἰβηρίας. οὔσης δὲ καὶ τῆς Κελτικῆς ἀνωμάλου τὸ πλάτος καὶ τῆς Ἰβηρίας, τὸ στενώτατον τοῦ πλάτους ἑκατέρας ἀπὸ τῆς ἡμετέρας θαλάττης ἐπὶ τὸν ὠκεανόν ἐστι τὸ τῇ Πυρήνῃ πλησιάζον μάλιστα ἐφ’ ἑκάτερον αὐτῆς τὸ μέρος καὶ ποιοῦν κόλπους τοὺς μὲν ἐπὶ τῷ ὠκεανῷ τοὺς δὲ ἐπὶ τῇ καθ’ ἡμᾶς θαλάττῃ· μείζους δὲ τοὺς Κελτικούς, οὓς δὴ καὶ Γαλατικοὺς καλοῦσι, στενώτερον τὸν ἰσθμὸν ποιοῦντας παρὰ τὸν Ἰβηρικόν. καὶ δὴ τὸ μὲν ἑῷον πλευρὸν τῆς Ἰβηρίας ἡ Πυρήνη ποιεῖ, τὸ δὲ νότιον ἥ τε καθ’ ἡμᾶς θάλαττα ἀπὸ τῆς Πυρήνης μέχρι στηλῶν καὶ ἡ ἐκτὸς τὸ ἑξῆς μέχρι τοῦ ἱεροῦ καλουμένου ἀκρωτηρίου· τρίτον ἐστὶ τὸ ἑσπέριον πλευρὸν παράλληλόν πως τῇ Πυρήνῃ, τὸ ἀπὸ τοῦ ἱεροῦ ἀκρωτηρίου μέχρι τῆς πρὸς Ἀρτάβροις ἄκρας ἣν καλοῦσι Νέριον· τέταρτον δὲ τὸ ἐνθένδε μέχρι τῶν βορείων ἄκρων τῆς Πυρήνης.", "st": "3.1.3"}, {"sp": "N", "t": "Ἀναλαβόντες δὲ λέγωμεν τὰ καθ’ ἕκαστα ἀπὸ τοῦ ἱεροῦ ἀκρωτηρίου ἀρξάμενοι. τοῦτο δέ ἐστι τὸ δυτικώτατον οὐ τῆς Εὐρώπης μόνον ἀλλὰ καὶ τῆς οἰκουμένης ἁπάσης σημεῖον. περατοῦται μὲν γὰρ ὑπὸ τῶν δυεῖν ἠπείρων ἡ οἰκουμένη πρὸς δύσιν, τοῖς τε τῆς Εὐρώπης ἄκροις καὶ τοῖς πρώτοις τῆς Λιβύης, ὧν τὰ μὲν Ἴβηρες ἔχουσι τὰ δὲ Μαυρούσιοι. προὔχει δὲ τὰ Ἰβηρικὰ ὅσον χιλίοις καὶ πεντακοσίοις σταδίοις κατὰ τὸ λεχθὲν ἀκρωτήριον. καὶ δὴ καὶ τὴν προσεχῆ τούτῳ χώραν τῇ Λατίνῃ φωνῇ καλοῦσι Κούνεον, σφῆνα σημαίνειν βουλόμενοι. αὐτὸ δὲ τὸ ἄκρον καὶ προπεπτωκὸς εἰς τὴν θάλατταν Ἀρτεμίδωρος εἰκάζει πλοίῳ, γενόμενος, φησίν, ἐν τῷ τόπῳ, προσλαμβάνειν δὲ τῷ σχήματι νησίδια τρία, τὸ μὲν ἐμβόλου τάξιν ἔχον τὰ δὲ ἐπωτίδων, ὑφόρμους ἔχοντα μετρίους. Ἡρακλέους δ’ οὔθ’ ἱερὸν ἐνταῦθα δείκνυσθαι (ψεύσασθαι δὲ τοῦτο Ἔφορον) οὔτε βωμόν, οὐδ’ ἄλλου τῶν θεῶν, ἀλλὰ λίθους συγκεῖσθαι τρεῖς ἢ τέτταρας κατὰ πολλοὺς τόπους, οὓς ὑπὸ τῶν ἀφικνουμένων στρέφεσθαι κατά τι πάτριον καὶ μεταφέρεσθαι σπονδοποιησαμένων· θύειν δ’ οὐκ εἶναι νόμιμον, οὐδὲ νύκτωρ ἐπιβαίνειν τοῦ τόπου, θεοὺς φασκόντων κατέχειν αὐτὸν ἐν τῷ τότε χρόνῳ, ἀλλὰ τοὺς ἐπὶ θέαν ἥκοντας ἐν κώμῃ πλησίον νυκτερεύειν, εἶτ’ ἐπιβάλλειν ἡμέρας ὕδωρ ἐπιφερομένους διὰ τὴν ἀνυδρίαν.", "st": "3.1.4"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οὕτως ἔχειν ἐγχωρεῖ καὶ δεῖ πιστεύειν· ἃ δὲ τοῖς πολλοῖς καὶ χυδαίοις ὁμοίως εἴρηκεν, οὐ πάνυ. λέγειν γὰρ δή φησι Ποσειδώνιος τοὺς πολλοὺς μείζω δύνειν τὸν ἥλιον ἐν τῇ παρωκεανίτιδι [καὶ] μετὰ ψόφου παραπλησίως ὡσανεὶ σίζοντος τοῦ πελάγους κατὰ σβέσιν αὐτοῦ διὰ τὸ ἐμπίπτειν εἰς τὸν βυθόν. ψεῦδος δ’ εἶναι καὶ τοῦτο καὶ τὸ παραχρῆμα νύκτα ἀκολουθεῖν μετὰ τὴν δύσιν· οὐ γὰρ παραχρῆμα, μικρὸν δ’ ὕστερον, καθάπερ καὶ ἐν τοῖς ἄλλοις πελάγεσι τοῖς μεγάλοις. ὅπου μὲν γὰρ εἰς ὄρη δύεται, πλείω τὸν μετὰ δύσιν χρόνον τῆς ἡμέρας συμβαίνειν ἐκ τοῦ παραφωτισμοῦ, ἐκεῖ δὲ πλείω μὲν οὐκ ἐπακολουθεῖν, μὴ μέντοι μηδὲ παραχρῆμα συνάπτειν τὸ σκότος, καθάπερ καὶ ἐν τοῖς μεγάλοις πεδίοις. τὴν δὲ τοῦ μεγέθους φαντασίαν αὔξεσθαι μὲν ὁμοίως κατά τε τὰς δύσεις καὶ τὰς ἀνατολὰς ἐν τοῖς πελάγεσι διὰ τὸ τὰς ἀναθυμιάσεις πλείους ἐκ τῶν ὑγρῶν ἀναφέρεσθαι· διὰ δὲ τούτων ὡς δι’ ὑάλων κλωμένην τὴν ὄψιν πλατυτέρας δέχεσθαι τὰς φαντασίας, καθάπερ καὶ διὰ νέφους ξηροῦ καὶ λεπτοῦ βλέπουσαν δυόμενον ἢ ἀνατέλλοντα τὸν ἥλιον ἢ τὴν σελήνην, ἡνίκα καὶ ἐνερευθὲς φαίνεσθαι τὸ ἄστρον. τὸ δὲ ψεῦδος ἐλέγξαι φησὶ τριάκονθ’ ἡμέρας διατρίψας ἐν Γαδείροις καὶ τηρήσας τὰς δύσεις. ὁ δέ γε Ἀρτεμίδωρος ἑκατονταπλασίονά φησι δύεσθαι τὸν ἥλιον καὶ αὐτίκα νύκτα καταλαμβάνειν. ὡς μὲν οὖν αὐτὸς εἶδε τοῦτο ἐν τῷ ἱερῷ ἀκρωτηρίῳ, οὐχ ὑποληπτέον προσέχοντας τῇ ἀποφάσει αὐτοῦ· ἔφη γὰρ νύκτωρ μηδένα ἐπιβαίνειν, ὥστ’ οὐδὲ δυομένου ἡλίου οὐδεὶς ἂν ἐπιβαίνοι, εἴπερ εὐθὺς ἡ νὺξ καταλαμβάνει. ἀλλ’ οὐδ’ ἐν ἄλλῳ τόπῳ τῆς παρωκεανίτιδος· καὶ γὰρ τὰ Γάδειρα ἐπὶ τῷ ὠκεανῷ, καὶ ὁ Ποσειδώνιος ἀντιμαρτυρεῖ καὶ ἄλλοι πλείους.", "st": "3.1.5"}, {"sp": "N", "t": "τῆς δὲ συνεχοῦς τῷ ἱερῷ ἀκρωτηρίῳ παραλίας ἡ μὲν ἐστὶν ἀρχὴ τοῦ ἑσπερίου πλευροῦ τῆς Ἰβηρίας μέχρι τῆς ἐκβολῆς τοῦ Τάγου ποταμοῦ, ἡ δὲ τοῦ νοτίου μέχρι ἄλλου ποταμοῦ τοῦ Ἄνα καὶ τῆς ἐκβολῆς αὐτοῦ. φέρεται δ’ ἀπὸ τῶν ἑῴων μερῶν ἑκάτερος, ἀλλ’ ὁ μὲν ἐπ’ εὐθείας εἰς τὴν ἑσπέραν ἐκδίδωσι πολὺ μείζων ὢν θατέρου, ὁ δ’ Ἄνας πρὸς νότον ἐπιστρέφει τὴν μεσοποταμίαν ἀφορίζων, ἣν Κελτικοὶ νέμονται τὸ πλέον καὶ τῶν Λυσιτανῶν τινὲς ἐκ τῆς περαίας τοῦ Τάγου μετοικισθέντες ὑπὸ Ῥωμαίων· ἐν δὲ τοῖς ἄνω μέρεσι καὶ Καρπητανοὶ καὶ Ὠρητανοὶ καὶ Ὀυεττώνων συχνοὶ νέμονται. αὕτη μὲν οὖν ἡ χώρα μετρίως ἐστὶν εὐδαίμων, ἡ δ’ ἐφεξῆς πρὸς ἕω κειμένη καὶ νότον ὑπερβολὴν οὐκ ἀπολείπει πρὸς ἅπασαν κρινομένη τὴν οἰκουμένην ἀρετῆς χάριν καὶ τῶν ἐκ γῆς καὶ θαλάττης ἀγαθῶν. αὕτη δ’ ἐστὶν ἣν ὁ Βαῖτις διαρρεῖ ποταμός, ἀπὸ τῶν αὐτῶν μερῶν τὴν ἀρχὴν ἔχων ἀφ’ ὧνπερ καὶ ὁ Ἄνας καὶ ὁ Τάγος, μέσος πως ἀμφοῖν τούτων ὑπάρχων κατὰ μέγεθος· παραπλησίως μέντοι τῷ Ἄνᾳ κατ’ ἀρχὰς ἐπὶ τὴν ἑσπέραν ῥυεὶς εἶτ’ ἐπιστρέφει πρὸς νότον καὶ κατὰ τὴν αὐτὴν ἐκδίδωσι τούτῳ παραλίαν. καλοῦσι δ’ ἀπὸ μὲν τοῦ ποταμοῦ Βαιτικήν, ἀπὸ δὲ τῶν ἐνοικούντων Τουρδητανίαν· τοὺς δ’ ἐνοικοῦντας Τουρδητανούς τε καὶ Τουρδούλους προσαγορεύουσιν, οἱ μὲν τοὺς αὐτοὺς νομίζοντες οἱ δ’ ἑτέρους· ὧν ἐστι καὶ Πολύβιος συνοίκους φήσας τοῖς Τουρδητανοῖς πρὸς ἄρκτον τοὺς Τουρδούλους· νυνὶ δ’ ἐν αὐτοῖς οὐδεὶς φαίνεται διορισμός. σοφώτατοι δ’ ἐξετάζονται τῶν Ἰβήρων οὗτοι καὶ γραμματικῇ χρῶνται καὶ τῆς παλαιᾶς μνήμης ἔχουσι συγγράμματα καὶ ποιήματα καὶ νόμους ἐμμέτρους ἑξακισχιλίων ἐπῶν, ὥς φασι· καὶ οἱ ἄλλοι δ’ Ἴβηρες χρῶνται γραμματικῇ, οὐ μιᾷ δ’ ἰδέᾳ· οὐδὲ γὰρ γλώττῃ μιᾷ. τείνει δὲ ἡ χώρα αὕτη ἡ ἐντὸς τοῦ Ἄνα πρὸς ἕω μὲν μέχρι τῆς Ὠρητανίας, πρὸς νότον δὲ μέχρι τῆς παραλίας τῆς ἀπὸ τῶν ἐκβολῶν τοῦ Ἄνα μέχρι στηλῶν. ἀνάγκη δὲ διὰ πλειόνων περὶ αὐτῆς εἰπεῖν καὶ τῶν σύνεγγυς τόπων, ὅσα συντείνει πρὸς τὸ μαθεῖν τὴν εὐφυΐαν τῶν τόπων καὶ τὴν εὐδαιμονίαν.", "st": "3.1.6"}, {"sp": "N", "t": "τῆς δὲ παραλίας ταύτης, εἰς ἣν ὅ τε Βαῖτις καὶ ὁ Ἄνας ἐκδίδωσι, καὶ τῶν ἐσχάτων τῆς Μαυρουσίας εἰς τὸ μεταξὺ ἐμπῖπτον τὸ Ἀτλαντικὸν πέλαγος ποιεῖ τὸν κατὰ στήλας πορθμόν, καθ’ ὃν ἡ ἐντὸς θάλαττα συνάπτει τῇ ἐκτός. ἐνταῦθα δὴ ὄρος ἐστὶ τῶν Ἰβήρων τῶν καλουμένων Βαστητανῶν, οὓς καὶ Βαστούλους καλοῦσιν, ἡ Κάλπη, τῇ περιοχῇ μὲν οὐ μέγα τῷ δ’ ὕψει μέγα καὶ ὄρθιον ὥστε πόρρωθεν νησοειδὲς φαίνεσθαι. ἐκπλέουσιν οὖν ἐκ τῆς ἡμετέρας θαλάττης εἰς τὴν ἔξω δεξιόν ἐστι τοῦτο, καὶ πρὸς αὐτὸ Καρτηία πόλις ἐν τετταράκοντα σταδίοις ἀξιόλογος καὶ παλαιά, ναύσταθμόν ποτε γενομένη τῶν Ἰβήρων. ἔνιοι δὲ καὶ Ἡρακλέους κτίσμα λέγουσιν αὐτήν, ὧν ἐστι καὶ Τιμοσθένης, ὅς φησι καὶ Ἡράκλειαν ὀνομάζεσθαι τὸ παλαιόν, δείκνυσθαί τε μέγαν περίβολον καὶ νεωσοίκους.", "st": "3.1.7"}, {"sp": "N", "t": "εἶτα Μελλαρία ταριχείας ἔχουσα καὶ μετὰ ταῦτα Βελὼν πόλις καὶ ποταμός. ἐντεῦθεν οἱ διάπλοι μάλιστά εἰσιν εἰς Τίγγιν τῆς Μαυρουσίας καὶ ἐμπόρια καὶ ταριχεῖαι. ἦν δὲ καὶ Ζῆλις τῆς Τίγγιος ἀστυγείτων, ἀλλὰ μετῴκισαν ταύτην εἰς τὴν περαίαν Ῥωμαῖοι καὶ ἐκ τῆς Τίγγιος προσλαβόντες τινάς· ἔπεμψαν δὲ καὶ παρ’ ἑαυτῶν ἐποίκους καὶ ὠνόμασαν Ἰουλίαν Ἴοζαν τὴν πόλιν. εἶτα Γάδειρα, πορθμῷ στενῷ διειργομένη νῆσος ἀπὸ τῆς Τουρδητανίας, διέχουσα τῆς Κάλπης περὶ ἑπτακοσίους καὶ πεντήκοντα σταδίους· οἱ δὲ ὀκτακοσίους φασίν. ἔστι δ’ ἡ νῆσος αὕτη τἆλλα μὲν οὐδὲν διαφέρουσα τῶν ἄλλων, ἀνδρείᾳ δὲ τῶν ἐνοικούντων τῇ περὶ τὰς ναυτιλίας καὶ φιλίᾳ πρὸς Ῥωμαίους τοσαύτην ἐπίδοσιν εἰς πᾶσαν εὐτυχίαν ἔσχεν ὥστε καίπερ ἐσχάτη ἱδρυμένη τῆς γῆς ὀνομαστοτάτη τῶν ἁπασῶν ἐστιν. ἀλλὰ περὶ μὲν ταύτης ἐροῦμεν, ὅταν καὶ περὶ τῶν ἄλλων νήσων λέγωμεν.", "st": "3.1.8"}, {"sp": "N", "t": "Ἐφεξῆς δ’ ἐστὶν ὁ Μενεσθέως καλούμενος λιμὴν καὶ ἡ κατὰ Ἄσταν ἀνάχυσις καὶ Νάβρισσαν. λέγονται δὲ ἀναχύσεις αἱ πληρούμεναι τῇ θαλάττῃ κοιλάδες ἐν ταῖς πλημμυρίσι καὶ ποταμῶν δίκην ἀνάπλους εἰς τὴν μεσόγαιαν ἔχουσαι καὶ τὰς ἐπ’ αὐταῖς πόλεις. εἶτ’ εὐθὺς αἱ ἐκβολαὶ τοῦ Βαίτιος διχῆ σχιζόμεναι· ἡ δὲ ἀπολαμβανομένη νῆσος ὑπὸ τῶν στομάτων ἑκατόν, ὡς δ’ ἔνιοι καὶ πλειόνων σταδίων, ἀφορίζει παραλίαν. ἐνταῦθα δέ που καὶ τὸ μαντεῖον τοῦ Μενεσθέως ἐστί, καὶ ὁ τοῦ Καιπίωνος ἵδρυται πύργος ἐπὶ πέτρας ἀμφικλύστου, θαυμασίως κατεσκευασμένος, ὥσπερ ὁ Φάρος, τῆς τῶν πλοϊζομένων σωτηρίας χάριν. ἥ τε γὰρ ἐκβαλλομένη χοῦς ὑπὸ τοῦ ποταμοῦ βραχέα ποιεῖ καὶ χοιραδώδης ἐστὶν ὁ πρὸ αὐτοῦ τόπος, ὥστε δεῖ σημείου τινὸς ἐπιφανοῦς. ἐντεῦθεν δ’ ὁ τοῦ Βαίτιος ἀνάπλους ἐστὶ καὶ πόλις Ἐβοῦρα καὶ τὸ τῆς Φωσφόρου ἱερόν, ἣν καλοῦσι Λοῦκεμ δουβίαν· εἶθ’ οἱ τῶν ἀναχύσεων τῶν ἄλλων ἀνάπλοι, καὶ μετὰ ταῦτα ὁ Ἄνας ποταμός, δίστομος καὶ οὗτος, καὶ ὁ ἐξ αὐτῶν ἀνάπλους· εἶθ’ ὕστατον τὸ ἱερὸν ἀκρωτήριον, διέχον τῶν Γαδείρων ἐλάττους ἢ δισχιλίους σταδίους· τινὲς δ’ ἀπὸ μὲν τοῦ ἱεροῦ ἀκρωτηρίου ἐπὶ τὸ τοῦ Ἄνα στόμα ἑξήκοντα μίλιά φασιν, ἐντεῦθεν δ’ ἐπὶ τὸ τοῦ Βαίτιος στόμα ἑκατόν, εἶτα εἰς Γάδειρα ἑβδομήκοντα.", "st": "3.1.9"}, {"sp": "N", "t": "τῆς δ’ οὖν ἐντὸς τοῦ Ἄνα παραλίας ὑπερκεῖσθαι συμβαίνει τὴν Τουρδητανίαν, ἣν ὁ Βαῖτις διαρρεῖ ποταμός. ἀφορίζει δὲ αὐτὴν πρὸς μὲν τὴν ἑσπέραν καὶ ἄρκτον ὁ Ἄνας ποταμός, πρὸς δὲ τὴν ἕω Καρπητανῶν τέ τινες καὶ Ὠρητανοί, πρὸς νότον δὲ Βαστητανῶν οἱ μεταξὺ τῆς Κάλπης καὶ τῶν Γαδείρων στενὴν νεμόμενοι παραλίαν, καὶ ἡ ἑξῆς θάλαττα μέχρι Ἄνα. καὶ οἱ Βαστητανοὶ δὲ οὓς εἶπον τῇ Τουρδητανίᾳ πρόσκεινται καὶ οἱ ἔξω τοῦ Ἄνα καὶ οἱ πολλοὶ τῶν προσχώρων. μέγεθος δ’ οὐ πλεῖόν ἐστι τῆς χώρας ταύτης ἐπὶ μῆκος καὶ πλάτος ἢ δισχίλιοι στάδιοι. πόλεις δ’ ὑπερβάλλουσαι τὸ πλῆθος· καὶ γὰρ διακοσίας φασί· γνωριμώταται δὲ αἱ ἐπὶ τοῖς ποταμοῖς ἱδρυμέναι καὶ ταῖς ἀναχύσεσι καὶ τῇ θαλάττῃ διὰ τὰς χρείας. πλεῖστον δ’ ἥ τε Κόρδυβα ηὔξηται, Μαρκέλλου κτίσμα, καὶ δόξῃ καὶ δυνάμει καὶ ἡ τῶν Γαδιτανῶν πόλις, ἡ μὲν διὰ τὰς ναυτιλίας καὶ διὰ τὸ προσθέσθαι Ῥωμαίοις κατὰ συμμαχίας, ἡ δὲ χώρας ἀρετῇ καὶ μεγέθει, προσλαμβάνοντος καὶ τοῦ ποταμοῦ Βαίτιος μέγα μέρος· ᾤκησάν τε ἐξ ἀρχῆς Ῥωμαίων τε καὶ τῶν ἐπιχωρίων ἄνδρες ἐπίλεκτοι· καὶ δὴ καὶ πρώτην ἀποικίαν ταύτην εἰς τούσδε τοὺς τόπους ἔστειλαν Ῥωμαῖοι. μετὰ δὲ ταύτην καὶ τὴν τῶν Γαδιτανῶν ἡ μὲν Ἵσπαλις ἐπιφανής, καὶ αὐτὴ ἄποικος Ῥωμαίων· νυνὶ δὲ τὸ μὲν ἐμπόριον συμμένει, τῇ τιμῇ δὲ καὶ τῷ ἐποικῆσαι νεωστὶ τοὺς Καίσαρος στρατιώτας ἡ Βαῖτις ὑπερέχει καίπερ οὐ συνοικουμένη λαμπρῶς.", "st": "3.2.1"}, {"sp": "N", "t": "μετὰ δὲ ταύτας Ἰτάλικα καὶ Ἴλιπα ἐπὶ τῷ Βαίτι, Ἄστιγις δ’ ἀπωτέρω καὶ Κάρμων καὶ Ὀβούλκων, ἔτι δὲ ἐν αἷς οἱ Πομπηίου παῖδες κατεπολεμήθησαν, Μοῦνδα καὶ Ἀτέγουα καὶ Οὔρσων καὶ Τοῦκκις καὶ Οὐλία καὶ Αἴγουα· ἅπασαι δ’ αὗται Κορδύβης οὐκ ἄπωθεν. τρόπον δέ τινα μητρόπολις κατέστη τοῦ τόπου τούτου Μοῦνδα· διέχει δὲ Καρτηίας ἡ Μοῦνδα σταδίους * χιλίους καὶ τετρακοσίους, εἰς ἣν ἔφυγεν ἡττηθεὶς ὁ Γναῖος, εἶτ’ ἐκπλεύσας ἔνθεν καὶ ἐκβὰς εἴς τινα ὑπερκειμένην θαλάττης ὀρεινὴν διεφθάρη. ὁ δ’ ἀδελφὸς αὐτοῦ Σέξτος ἐκ Κορδύβης σωθεὶς καὶ μικρὸν ἐν τοῖς Ἴβηρσι πολεμήσας χρόνον ὕστερον Σικελίαν ἀπέστησεν, εἶτ’ ἐκπεσὼν ἐνθένδε εἰς τὴν Ἀσίαν ἁλοὺς ὑπὸ τῶν Ἀντωνίου στρατηγῶν ἐν Μιδαείῳ κατέστρεψε τὸν βίον. ἐν δὲ τοῖς Κελτικοῖς Κονίστοργίς ἐστι γνωριμωτάτη· ἐπὶ δὲ ταῖς ἀναχύσεσιν ἡ Ἄστα, εἰς ἣν οἱ Γαδιτανοὶ συνίασι μάλιστα, ὑπερκειμένην τοῦ ἐπινείου τῆς νήσου σταδίους οὐ πολὺ πλείους τῶν ἑκατόν.", "st": "3.2.2"}, {"sp": "N", "t": "παροικεῖται δὲ ὑπὸ πλείστων ὁ Βαῖτις καὶ ἀναπλεῖται σχεδόν τι ἐπὶ χιλίους καὶ διακοσίους σταδίους ἐκ θαλάττης μέχρι Κορδύβης καὶ τῶν μικρὸν ἐπάνω τόπων. καὶ δὴ καὶ ἐξείργασται περιττῶς ἥ τε παραποταμία καὶ τὰ ἐν τῷ ποταμῷ νησίδια. πρόσεστι δὲ καὶ τὸ τῆς ὄψεως τερπνόν, ἄλσεσι καὶ ταῖς ἄλλαις φυτουργίαις ἐκπεπονημένων τῶν χωρίων. μέχρι μὲν οὖν Ἱσπάλιος ὁλκάσιν ἀξιολόγοις ὁ ἀνάπλους ἐστὶν ἐπὶ σταδίους οὐ πολὺ λείποντας τῶν πεντακοσίων, ἐπὶ δὲ τὰς ἄνω πόλεις μέχρι Ἰλίπας ταῖς ἐλάττοσι, μέχρι δὲ Κορδύβης τοῖς ποταμίοις σκάφεσι, πηκτοῖς μὲν τὰ νῦν τὸ παλαιὸν δὲ καὶ μονοξύλοις· τὸ δ’ ἄνω τὸ ἐπὶ Καστλῶνος οὐκ ἔστι πλόιμον· παράλληλοι δέ τινες ῥάχεις ὀρῶν παρατείνουσι τῷ ποταμῷ μᾶλλόν τε καὶ ἧττον αὐτῷ συνάπτουσαι πρὸς βορρᾶν, μετάλλων πλήρεις. πλεῖστος δ’ ἐστὶν ἄργυρος ἐν τοῖς κατὰ Ἴλιπαν τόποις καὶ τοῖς κατὰ Σισάπωνα τόν τε παλαιὸν λεγόμενον καὶ τὸν νέον· κατὰ δὲ τὰς Κωτίνας λεγομένας χαλκός τε ἅμα γεννᾶται καὶ χρυσός. ἐν ἀριστερᾷ μὲν οὖν ἐστι τοῖς ἀναπλέουσι τὰ ὄρη ταῦτα, ἐν δεξιᾷ δὲ πεδίον μέγα καὶ ὑψηλὸν καὶ εὔκαρπον καὶ μεγαλόδενδρον καὶ εὔβοτον. ἔχει δὲ καὶ ὁ Ἄνας ἀνάπλουν, οὔτε δὲ τηλικούτοις σκάφεσιν οὔτ’ ἐπὶ τοσοῦτον. ὑπέρκειται δὲ καὶ αὐτοῦ μεταλλείας ἔχοντα ὄρη, καθήκει δὲ ταῦτα πρὸς τὸν Τάγον. τὰ μὲν οὖν τὰς μεταλλείας ἔχοντα χωρία ἀνάγκη τραχέα τε εἶναι καὶ παράλυπρα, οἷάπερ καὶ τὰ τῇ Καρπητανίᾳ συνάπτοντα καὶ ἔτι μᾶλλον τοῖς Κελτίβηρσι. τοιαύτη δὲ καὶ ἡ Βαιτουρία ξηρὰ ἔχουσα πεδία τὰ παρήκοντα τῷ Ἄνᾳ.", "st": "3.2.3"}, {"sp": "N", "t": "αὐτὴ δ’ ἡ Τουρδητανία θαυμαστῶς εὐτυχεῖ· παμφόρου δ’ οὔσης αὐτῆς, ὡσαύτως δὲ καὶ πολυφόρου, διπλασιάζεται τὰ εὐτυχήματα ταῦτα τῷ ἐκκομισμῷ· τὸ γὰρ περιττεῦον τῶν καρπῶν ἀπεμπολεῖται ῥᾳδίως τῷ πλήθει τῶν ναυκληρίων. ποιοῦσι δὲ τοῦτο οἵ τε ποταμοὶ καὶ αἱ ἀναχύσεις, ὡς εἶπον, ἐμφερεῖς τοῖς ποταμοῖς οὖσαι καὶ ἀναπλεόμεναι παραπλησίως ἐκ θαλάττης οὐ μικροῖς μόνον ἀλλὰ καὶ μεγάλοις σκάφεσιν εἰς τὰς ἐν τῇ μεσογαίᾳ πόλεις. ἅπασα γάρ ἐστι πεδιὰς ἡ ὑπὲρ τῆς παραλίας ἐπὶ πολὺ τῆς μεταξὺ τοῦ τε ἱεροῦ ἀκρωτηρίου καὶ στηλῶν. ἐνταῦθα δὲ πολλαχοῦ κοιλάδες εἰς τὴν μεσόγαιαν ἐκ τῆς θαλάττης ἀνέχουσι φάραγξι μετρίαις ἢ καὶ ῥείθροις ἐοικυῖαι ποταμίοις, ἐκτεταμέναι ἐπὶ πολλοὺς σταδίους· ταύτας δὲ πληροῦσιν αἱ τῆς θαλάττης ἐπιβάσεις κατὰ τὰς πλημμυρίδας, ὥστ’ ἀναπλεῖσθαι μηδὲν ἧττον ἢ τοὺς ποταμούς, ἀλλὰ καὶ βέλτιον· τοῖς γὰρ κατάπλοις ἔοικε τοῖς ποταμίοις, ἀντικόπτοντος μὲν οὐδενός, ἐπουρίζοντος δὲ τοῦ πελάγους καθάπερ τοῦ ποταμίου ῥεύματος διὰ τὴν πλημμυρίδα. αἱ δ’ ἐπιβάσεις μείζους εἰσὶν ἐνταῦθα ἢ ἐν τοῖς ἄλλοις τόποις, ὅτι εἰς πόρον συνωθουμένη στενὸν ἡ θάλαττα ἐκ μεγάλου πελάγους, ὃν ἡ Μαυρουσία ποιεῖ πρὸς τὴν Ἰβηρίαν, ἀνακοπὰς λαμβάνει καὶ φέρεται πρὸς τὰ εἴκοντα μέρη τῆς γῆς εὐπετῶς. ἔνιαι μὲν οὖν τῶν τοιούτων κοιλάδων κενοῦνται κατὰ τὰς ἀμπώτεις, τινὰς δ’ οὐ παντάπασιν ἐπιλείπει τὸ ὕδωρ, ἔνιαι δὲ καὶ νήσους ἀπολαμβάνουσιν ἐν ἑαυταῖς. τοιαῦται μὲν οὖν εἰσιν αἱ ἀναχύσεις αἱ μεταξὺ τοῦ τε ἱεροῦ ἀκρωτηρίου καὶ τῶν στηλῶν, ἐπίδοσιν ἔχουσαι σφοδροτέραν παρὰ τὰς ἐν τοῖς ἄλλοις τόποις· ἡ τοιαύτη δ’ ἐπίδοσις ἔχει μέν τι καὶ πλεονέκτημα πρὸς τὰς χρείας τῶν πλοϊζομένων· πλείους γὰρ καὶ μείζους ποιεῖ τὰς ἀναχύσεις, πολλάκις καὶ ἐπὶ * ὀκτὼ σταδίους ἀναπλεομένας, ὥστε τρόπον τινὰ πᾶσαν πλωτὴν παρέχεται τὴν γῆν καὶ εὐπετῆ πρός τε τὰς ἐξαγωγὰς τῶν φορτίων καὶ τὰς εἰσαγωγάς. ἔχει δέ τι καὶ ὀχληρόν· αἱ γὰρ ἐν τοῖς ποταμοῖς ναυτιλίαι διὰ τὴν σφοδρότητα τῆς πλημμυρίδος ἰσχυρότερον τῇ ῥύσει τῶν ποταμῶν ἀντιπνέουσαν κίνδυνον οὐ μικρὸν τοῖς ναυκληρίοις ἐπιφέρουσι κατακομιζομένοις τε ὁμοίως καὶ ἀνακομιζομένοις. αἱ δὲ ἀμπώτεις ἐν ταῖς ἀναχύσεσίν εἰσι βλαβεραί· ταῖς γὰρ πλημμυρίσιν ἀνὰ λόγον καὶ αὐταὶ παροξύνονται, διά τε τὸ τάχος καὶ ἐπὶ ξηρᾶς πολλάκις ἐγκατέλιπον τὴν ναῦν. τά τε βοσκήματα εἰς τὰς νήσους διαβαίνοντα τὰς πρὸ τῶν ἀναχύσεων τοτὲ μὲν οὖν καὶ ἐπεκλύσθη τοτὲ δὲ ἀπελήφθη, βιαζόμενα δ’ ἐπανελθεῖν οὐκ ἴσχυσεν ἀλλὰ διεφθάρη· τὰς δὲ βοῦς φασι καὶ τετηρηκυίας τὸ συμβαῖνον περιμένειν τὴν ἀναχώρησιν τῆς θαλάττης καὶ τότε ἀπαίρειν εἰς τὴν ἤπειρον.", "st": "3.2.4"}, {"sp": "N", "t": "καταμαθόντες δ’ οὖν τὴν φύσιν τῶν τόπων οἱ ἄνθρωποι καὶ τὰς ἀναχύσεις ὁμοίως ὑπουργεῖν τοῖς ποταμοῖς δυναμένας πόλεις ἔκτισαν ἐπ’ αὐτῶν καὶ ἄλλας κατοικίας, καθάπερ ἐπὶ τῶν ποταμῶν· τούτων δ’ ἐστὶν ἥ τε Ἄστα καὶ Νάβρισσα καὶ Ὄνοβα καὶ Ὀσσόνοβα καὶ Μαίνοβα καὶ ἄλλαι πλείους. προσλαμβάνουσι δὲ καὶ διώρυγες ἔσθ’ ὅπου γεγονυῖαι τῷ πολλαχόθεν εἶναι καὶ πολλαχόσε τὴν κομιδὴν καὶ πρὸς ἀλλήλους καὶ πρὸς τοὺς ἔξω. καὶ αἱ σύρροιαι δὲ ὡσαύτως ὠφελοῦσι κατὰ τὰς ἐπὶ πολὺ πλήμας διαχεομένας ἐπὶ τῶν διειργόντων ἰσθμῶν τοὺς πόρους καὶ πλωτοὺς ἀπεργαζομένας, ὥστε πορθμεύεσθαι καὶ ἐκ τῶν ποταμῶν εἰς τὰς ἀναχύσεις κἀκεῖθεν δεῦρο. ἅπασα δ’ ἡ ἐμπορία πρὸς τὴν Ἰταλίαν ἐστὶ καὶ τὴν Ῥώμην, ἔχουσα τὸν πλοῦν [τόν τε] μέχρι τῶν στηλῶν ἀγαθὸν (πλὴν εἴ τίς ἐστι περὶ τὸν πορθμὸν δυσκολία) καὶ τὸν πελάγιον τὸν ἐν τῇ καθ’ ἡμᾶς θαλάττῃ. διὰ γὰρ εὐδίου κλίματος οἱ δρόμοι συντελοῦνται καὶ μάλιστα τῷ πελαγίζοντι· τοῦτο δὲ πρόσφορόν ἐστι ταῖς ἐμπορικαῖς ὁλκάσιν. ἔχουσι δὲ καὶ οἱ ἄνεμοι τάξιν οἱ πελάγιοι· πρόσεστι δὲ καὶ ἡ νῦν εἰρήνη, τῶν λῃστηρίων καταλυθέντων, ὥσθ’ ἡ σύμπασα ὑπάρχει ῥᾳστώνη τοῖς πλοϊζομένοις. ἴδιον δέ τί φησι Ποσειδώνιος τηρῆσαι κατὰ τὸν ἀνάπλουν τὸν ἐκ τῆς Ἰβηρίας, ὅτι οἱ εὖροι κατ’ ἐκεῖνο τὸ πέλαγος ἕως τοῦ Σαρδῴου κόλπου πνέοιεν ἐτησίαι· διὸ καὶ τρισὶ μησὶν εἰς Ἰταλίαν κατᾶραι μόλις παραδιενεχθεὶς περί τε τὰς Γυμνησίας νήσους καὶ περὶ Σαρδόνα καὶ τὰ ἄλλα ἀπαντικρὺ τούτων μέρη τῆς Λιβύης.", "st": "3.2.5"}, {"sp": "N", "t": "Ἐξάγεται δ’ ἐκ τῆς Τουρδητανίας σῖτός τε καὶ οἶνος πολὺς καὶ ἔλαιον οὐ πολὺ μόνον ἀλλὰ καὶ κάλλιστον· καὶ κηρὸς δὲ καὶ μέλι καὶ πίττα ἐξάγεται καὶ κόκκος πολλὴ καὶ μίλτος οὐ χείρων τῆς Σινωπικῆς γῆς. τά τε ναυπήγια συνιστᾶσιν αὐτόθι ἐξ ἐπιχωρίας ὕλης, ἅλες τε ὀρυκτοὶ παρ’ αὐτοῖς εἰσι καὶ ποταμῶν ἁλμυρῶν ῥεύματα οὐκ ὀλίγα· οὐκ ὀλίγη δὲ οὐδὲ ἐκ τῶν ὄψων ταριχεία οὐκ ἔνθεν μόνον ἀλλὰ καὶ ἐκ τῆς ἄλλης τῆς ἐκτὸς στηλῶν παραλίας, οὐ χείρων τῆς Ποντικῆς. πολλὴ δὲ καὶ ἐσθὴς πρότερον ἤρχετο, νῦν δὲ ἔρια μᾶλλον τῶν κοραξῶν. καὶ ὑπερβολή τίς ἐστι τοῦ κάλλους· ταλαντιαίους γοῦν ὠνοῦνται τοὺς κριοὺς εἰς τὰς ὀχείας. ὑπερβολὴ δὲ καὶ τῶν λεπτῶν ὑφασμάτων, ἅπερ οἱ Σαλτιγῖται κατασκευάζουσιν. ἄφθονος δὲ καὶ βοσκημάτων εὐπορία παντοίων καὶ κυνηγεσίων. τῶν δ’ ὀλεθρίων θηρίων σπάνις πλὴν τῶν γεωρύχων λαγιδέων, οὓς ἔνιοι λεβηρίδας προσαγορεύουσι· λυμαίνονται γὰρ καὶ φυτὰ καὶ σπέρματα ῥιζοφαγοῦντες· καὶ τοῦτο συμβαίνει καθ’ ὅλην τὴν Ἰβηρίαν σχεδόν τι, διατείνει δὲ καὶ μέχρι Μασσαλίας, ὀχλεῖ δὲ καὶ τὰς νήσους. οἱ δὲ τὰς Γυμνησίας οἰκοῦντες λέγονται πρεσβεύσασθαί ποτε πρὸς Ῥωμαίους κατὰ χώρας αἴτησιν· ἐκβάλλεσθαι γὰρ ὑπὸ τῶν ζῴων τούτων, ἀντέχειν μὴ δυνάμενοι διὰ τὸ πλῆθος. πρὸς μὲν οὖν τὸν τοσοῦτον ἴσως πόλεμον, ὃς οὐκ ἀεὶ συμβαίνει, φορᾷ δέ τινι λοιμικῇ καθάπερ ὄφεων καὶ μυῶν τῶν ἀρουραίων, χρεία τῆς τοσαύτης ἐπικουρίας, πρὸς δὲ τὸ μέτριον ἐξεύρηνται πλείους θῆραι· καὶ δὴ καὶ γαλᾶς ἀγρίας ἃς ἡ Λιβύη φέρει τρέφουσιν ἐπίτηδες, ἃς φιμώσαντες παριᾶσιν εἰς τὰς ὀπάς· αἱ δ’ ἐξέλκουσιν ἔξω τοῖς ὄνυξιν οὓς ἂν καταλάβωσιν, ἢ φεύγειν ἀναγκάζουσιν εἰς τὴν ἐπιφάνειαν, ἐκπεσόντας δὲ θηρεύουσιν οἱ ἐφεστῶτες. τὴν δὲ ἀφθονίαν τῶν ἐκκομιζομένων ἐκ τῆς Τουρδητανίας ἐμφανίζει τὸ μέγεθος καὶ τὸ πλῆθος τῶν ναυκληρίων· ὁλκάδες γὰρ μέγισται παρὰ τούτων πλέουσιν εἰς Δικαιάρχειαν καὶ τὰ Ὤστια τῆς Ῥώμης ἐπίνειον· τὸ δὲ πλῆθος μικροῦ δεῖν ἐνάμιλλον τοῖς Λιβυκοῖς.", "st": "3.2.6"}, {"sp": "N", "t": "τοιαύτης δὲ τῆς μεσογαίας οὔσης τῆς ἐν τῇ Τουρδητανίᾳ, καὶ τὴν παράλιον ἐνάμιλλον εὕροι τις ἂν τοῖς ἐκ θαλάττης ἀγαθοῖς· τά τε γὰρ ὀστρεώδη πάντα καὶ κογχοειδῆ καὶ τοῖς πλήθεσιν ὑπερβάλλει καὶ τοῖς μεγέθεσι καθόλου κατὰ τὴν ἔξω θάλατταν πᾶσαν, ἐνταῦθα δὲ διαφερόντως, ἅτε καὶ τῶν πλημμυρίδων καὶ τῶν ἀμπώτεων ἐνταῦθα αὐξομένων, ἃς εἰκὸς αἰτίας εἶναι καὶ τοῦ πλήθους καὶ τοῦ μεγέθους διὰ τὴν γυμνασίαν. ὡς δ’ αὕτως ἔχει καὶ περὶ τῶν κητέων ἁπάντων, ὀρύγων τε καὶ φαλαινῶν καὶ φυσητήρων, ὧν ἀναφυσησάντων φαίνεταί τις νεφώδους ὄψις κίονος τοῖς πόρρωθεν ἀφορῶσι· καὶ οἱ γόγγροι δὲ ἀποθηριοῦνται πολὺ τῶν παρ’ ἡμῖν ὑπερβεβλημένοι κατὰ τὸ μέγεθος, καὶ αἱ σμύραιναι καὶ ἄλλα πλείω τῶν τοιούτων ὄψων. ἐν δὲ Καρτηίᾳ κήρυκας δεκακοτύλους καὶ πορφύρας φασίν· ἐν δὲ τοῖς ἐξωτέροις τόποις καὶ μείζους ὀγδοήκοντα μνῶν τὴν σμύραιναν καὶ τὸν γόγγρον, ταλαντιαῖον δὲ τὸν πολύποδα, διπήχεις δὲ τὰς τευθίδας καὶ τὰ παραπλήσια. πολὺς δὲ καὶ ὁ θύννος συνελαύνεται δεῦρο ἀπὸ τῆς ἄλλης τῆς ἔξωθεν παραλίας πίων καὶ παχύς. τρέφεται δὲ βαλάνῳ δρυΐνῃ φυομένῃ κατὰ τῆς θαλάττης χαμαιζήλῳ τινὶ παντάπασιν, ἁδρότατον δ’ ἐκφερούσῃ καρπόν· ἥπερ καὶ ἐν τῇ γῇ φύεται πολλὴ κατὰ τὴν Ἰβηρίαν, ῥίζας μὲν ἔχουσα μεγάλας ὡς ἂν τελείας δρυός, ἐξαιρομένη δὲ θάμνου ταπεινῆς ἧττον· τοσοῦτον δ’ ἐκφέρει καρπὸν ὥστε μετὰ τὴν ἀκμὴν πλήρη τὴν παραλίαν [βαλάνου] εἶναι τήν τε ἐντὸς καὶ τὴν ἐκτὸς στηλῶν, ἣν ἐκβάλλουσιν αἱ πλῆμαι· ἡ δ’ ἐντὸς στηλῶν ἐλάττων ἀεὶ καὶ μᾶλλον εὑρίσκεται. λέγει δ’ ὁ Πολύβιος καὶ μέχρι τῆς Λατίνης ἐκπίπτειν τὴν βάλανον ταύτην, εἰ μὴ ἄρα (φησί) καὶ ἡ Σαρδὼ φέρει καὶ ἡ πλησιόχωρος ταύτῃ. καὶ οἱ θύννοι δ’ ὅσῳ πλέον συνεγγίζουσι ταῖς στήλαις ἔξωθεν φερόμενοι, τοσῷδ’ ἰσχναίνονται πλέον τῆς τροφῆς ἐπιλειπούσης· εἶναί τε παρὰ θαλάττιον ὗν τὸ ζῷον τοῦτο· ἥδεσθαι γὰρ τῇ βαλάνῳ καὶ πιαίνεσθαι διαφερόντως ὑπ’ αὐτῆς, φορᾶς τε τῆς βαλάνου γενομένης φορὰν καὶ τῶν θύννων εἶναι.", "st": "3.2.7"}, {"sp": "N", "t": "τοσούτοις δὲ τῆς προειρημένης χώρας ἀγαθοῖς κεχορηγημένης, οὐχ ἥκιστα, ἀλλὰ καὶ μάλιστα ἀποδέξαιτ’ ἄν τις καὶ θαυμάσειε τὸ περὶ τὰς μεταλλείας εὐφυές· ἅπασα μὲν γὰρ μεστὴ τῶν τοιούτων ἐστὶν ἡ τῶν Ἰβήρων χώρα, οὐ πᾶσα δ’ εὔκαρπος οὐδ’ εὐδαίμων οὕτως καὶ μάλιστα ἡ τῶν μετάλλων εὐποροῦσα. σπάνιον δ’ ἐν ἀμφοτέροις εὐτυχεῖν, σπάνιον δὲ καὶ τὸ τὴν αὐτὴν ἐν ὀλίγῳ χωρίῳ παντοίοις πληθύνειν μετάλλοις. ἡ δὲ Τουρδητανία καὶ ἡ προσεχὴς αὐτῇ λόγον οὐδένα ἄξιον καταλείπει περὶ τήνδε τὴν ἀρετὴν τοῖς ἐπαινεῖν βουλομένοις. οὔτε γὰρ χρυσός, οὐκ ἄργυρος, οὐδὲ δὴ χαλκός, οὐδὲ σίδηρος οὐδαμοῦ τῆς γῆς οὔτε τοσοῦτος οὔθ’ οὕτως ἀγαθὸς ἐξήτασται γεννώμενος μέχρι νῦν. ὁ δὲ χρυσὸς οὐ μεταλλεύεται μόνον ἀλλὰ καὶ σύρεται· καταφέρουσι δ’ οἱ ποταμοὶ καὶ οἱ χείμαρροι τὴν χρυσῖτιν ἄμμον, πολλαχοῦ καὶ ἐν τοῖς ἀνύδροις τόποις οὖσαν, ἀλλ’ ἐκεῖ μὲν ἀφανής ἐστιν, ἐν δὲ τοῖς ἐπικλύστοις ἀπολάμπει τὸ τοῦ χρυσοῦ ψῆγμα· καὶ τοὺς ἀνύδρους δὲ φορητῷ ἐπικλύζοντες ὕδατι στιλπνὸν ποιοῦσι τὸ ψῆγμα, καὶ φρέατα δ’ ὀρύσσοντες καὶ ἄλλας τέχνας ἐπινοοῦντες πλύσει τῆς ἄμμου τὸν χρυσὸν ἐκλαμβάνουσι, καὶ πλείω τῶν χρυσωρυχείων ἐστὶ νῦν τὰ χρυσοπλύσια προσαγορευόμενα. ἀξιοῦσι δὲ Γαλάται [κράτις]τα παρ’ ἑαυτοῖς εἶναι τὰ μέταλλα τά τε ἐν τῷ Κεμμένῳ ὄρει καὶ τὰ ὑπ’ αὐτῇ κείμενα τῇ Πυρήνῃ· τὸ μέντοι πλέον τἀντεῦθεν εὐδοκιμεῖ. ἐν δὲ τοῖς ψήγμασι τοῦ χρυσίου φασὶν εὑρίσκεσθαί ποτε καὶ ἡμιλιτριαίας βώλους ἃς καλοῦσι πάλας, μικρᾶς καθάρσεως δεομένας. φασὶ δὲ καὶ λίθων σχιζομένων εὑρίσκειν βωλάρια θηλαῖς ὅμοια· ἐκ δὲ τοῦ χρυσοῦ ἑψομένου καὶ καθαιρομένου στυπτηριώδει τινὶ γῇ τὸ κάθαρμα ἤλεκτρον εἶναι· πάλιν δὲ τούτου καθεψομένου, μῖγμα ἔχοντος ἀργύρου καὶ χρυσοῦ, τὸν μὲν ἄργυρον ἀποκαίεσθαι τὸν δὲ χρυσὸν ὑπομένειν· εὐδιάχυτος γὰρ * ὁ τύπος καὶ λιπώδης· διὰ τοῦτο καὶ τῷ ἀχύρῳ τήκεται μᾶλλον ὁ χρυσός, ὅτι ἡ φλὸξ μαλακὴ οὖσα συμμέτρως ἔχει πρὸς τὸ εἶκον καὶ διαχεόμενον ῥᾳδίως, ὁ δὲ ἄνθραξ ἐπαναλίσκει πολὺ ὑπερτήκων τῇ σφοδρότητι καὶ ἐξαίρων. ἐν δὲ τοῖς ῥείθροις σύρεται καὶ πλύνεται πλησίον ἐν σκάφαις, ἢ ὀρύττεται φρέαρ, ἡ δὲ ἀνενεχθεῖσα γῆ πλύνεται. τὰς δὲ τοῦ ἀργύρου καμίνους ποιοῦσιν ὑψηλάς, ὥστε τὴν ἐκ τῶν βώλων λιγνὺν μετέωρον ἐξαίρεσθαι· βαρεῖα γάρ ἐστι καὶ ὀλέθριος. τῶν δὲ χαλκουργείων τινὰ καλεῖται χρυσεῖα, ἐξ ὧν τεκμαίρονται χρυσὸν ἐξ αὐτῶν ὀρύττεσθαι πρότερον.", "st": "3.2.8"}, {"sp": "N", "t": "ποσειδώνιος δὲ τὸ πλῆθος τῶν μετάλλων ἐπαινῶν καὶ τὴν ἀρετὴν οὐκ ἀπέχεται τῆς συνήθους ῥητορείας, ἀλλὰ συνενθουσιᾷ ταῖς ὑπερβολαῖς· οὐ γὰρ ἀπιστεῖν τῷ μύθῳ φησὶν ὅτι τῶν δρυμῶν ποτε ἐμπρησθέντων ἡ γῆ τακεῖσα, ἅτε ἀργυρῖτις καὶ χρυσῖτις, εἰς τὴν ἐπιφάνειαν ἐξέζεσε διὰ τὸ πᾶν ὄρος καὶ πάντα βουνὸν ὕλην εἶναι νομίσματος ὑπό τινος ἀφθόνου τύχης σεσωρευμένην. καθόλου δ’ ἂν εἶπε (φησίν) ἰδών τις τοὺς τόπους θησαυροὺς εἶναι φύσεως ἀενάους ἢ ταμιεῖον ἡγεμονίας ἀνέκλειπτον· οὐ γὰρ πλουσία μόνον ἀλλὰ καὶ ὑπόπλουτος ἦν (φησίν) ἡ χώρα, καὶ παρ’ ἐκείνοις ὡς ἀληθῶς τὸν ὑποχθόνιον τόπον οὐχ ὁ Ἅιδης ἀλλ’ ὁ Πλούτων κατοικεῖ. τοιαῦτα μὲν οὖν ἐν ὡραίῳ σχήματι εἴρηκε περὶ τούτων, ὡς ἂν ἐκ μετάλλου καὶ αὐτὸς πολλῷ χρώμενος τῷ λόγῳ. τὴν δ’ ἐπιμέλειαν φράζων τὴν τῶν μεταλλευόντων παρατίθησι τὸ τοῦ Φαληρέως, ὅτι φησὶν ἐκεῖνος ἐπὶ τῶν Ἀττικῶν ἀργυρείων, οὕτω συντόνως ὀρύττειν τοὺς ἀνθρώπους ὡς ἂν προσδοκώντων αὐτὸν ἀνάξειν τὸν Πλούτωνα· καὶ τούτων οὖν ἐμφανίζει παραπλησίαν τὴν σπουδὴν καὶ τὴν φιλεργίαν, σκολιὰς τεμνόντων καὶ βαθείας τὰς σύριγγας καὶ πρὸς τοὺς ἐν αὐταῖς ἀπαντῶντας ποταμοὺς πολλάκις τοῖς Αἰγυπτίοις ἀναντλούντων κοχλίαις. * τὸν δόλον οὐ ταὐτὸν εἶναι τούτοις τε καὶ τοῖς Ἀττικοῖς, ἀλλ’ ἐκείνοις μὲν αἰνίγματι ἐοικέναι τὴν μεταλλείαν· ὅσα μὲν γὰρ ἀνέλαβον (φησίν) οὐκ ἔλαβον, ὅσα δὲ εἶχον, ἀπέβαλον· τούτοις δ’ ὑπεράγαν λυσιτελεῖν, τοῖς μὲν χαλκουργοῖς τέταρτον μέρος ἐξάγουσι τῆς γῆς τὸν χαλκόν, τῶν δὲ ἀργυρευόντων τισὶν ἰδιωτῶν ἐν τρισὶν ἡμέραις Εὐβοϊκὸν τάλαντον ἐξαίρουσι. τὸν δὲ καττίτερον οὐκ ἐπιπολῆς εὑρίσκεσθαί φησιν, ὡς τοὺς ἱστορικοὺς θρυλεῖν, ἀλλ’ ὀρύττεσθαι· γεννᾶσθαι δ’ ἔν τε τοῖς ὑπὲρ τοὺς Λυσιτανοὺς βαρβάροις καὶ ἐν ταῖς Καττιτερίσι νήσοις, καὶ ἐκ τῶν Βρεττανικῶν δὲ εἰς τὴν Μασσαλίαν κομίζεσθαι. ἐν δὲ τοῖς Ἀρτάβροις, οἳ τῆς Λυσιτανίας ὕστατοι πρὸς ἄρκτον καὶ δύσιν εἰσίν, ἐξανθεῖν φησιν τὴν γῆν ἀργύρῳ, καττιτέρῳ, χρυσῷ λευκῷ (ἀργυρομιγὴς γάρ ἐστι), τὴν δὲ γῆν ταύτην φέρειν τοὺς ποταμούς· τὴν δὲ σκαλίσι τὰς γυναῖκας διαμώσας πλύνειν ἐν ἠθητηρίοις πλεκτοῖς εἰς κίστην. οὗτος μὲν περὶ τῶν μετάλλων τοιαῦτ’ εἴρηκε.", "st": "3.2.9"}, {"sp": "N", "t": "πολύβιος δὲ τῶν περὶ Καρχηδόνα νέαν ἀργυρείων μνησθεὶς μέγιστα μὲν εἶναί φησι, διέχειν δὲ τῆς πόλεως ὅσον εἴκοσι σταδίους, περιειληφότα κύκλον τετρακοσίων σταδίων, ὅπου τέτταρας μυριάδας ἀνθρώπων μένειν τῶν ἐργαζομένων, ἀναφέροντας τότε τῷ δήμῳ τῶν Ῥωμαίων καθ’ ἑκάστην ἡμέραν δισμυρίας καὶ πεντακισχιλίας δραχμάς. τὴν δὲ κατεργασίαν τὴν μὲν ἄλλην ἐῶ (μακρὰ γάρ ἐστι), τὴν δὲ συρτὴν βῶλον τὴν ἀργυρῖτίν φησι κόπτεσθαι καὶ κοσκίνοις εἰς ὕδωρ διαττᾶσθαι· κόπτεσθαι δὲ πάλιν τὰς ὑποστάσεις, καὶ πάλιν διηθουμένας ἀποχεομένων τῶν ὑδάτων κόπτεσθαι· τὴν δὲ πέμπτην ὑπόστασιν χωνευθεῖσαν, ἀποχυθέντος τοῦ μολίβδου, καθαρὸν τὸν ἄργυρον ἐξάγειν. ἔστι δὲ καὶ νῦν τὰ ἀργυρεῖα, οὐ μέντοι δημόσια οὔτε ἐνταῦθα οὔτε ἐν τοῖς ἄλλοις τόποις, ἀλλ’ εἰς ἰδιωτικὰς μεθέστηκε κτήσεις· τὰ δὲ χρυσεῖα δημοσιεύεται τὰ πλείω. ἐν δὲ καὶ Καστλῶνι καὶ ἄλλοις τόποις ἴδιόν ἐστι μέταλλον ὀρυκτοῦ μολίβδου· παραμέμικται δέ τι καὶ τούτῳ τοῦ ἀργύρου μικρόν, οὐχ ὥστε λυσιτελεῖν ἀποκαθαίρειν αὐτόν.", "st": "3.2.10"}, {"sp": "N", "t": "οὐ πολὺ δ’ ἄπωθεν τοῦ Καστλῶνος ἔστι καὶ τὸ ὄρος ἐξ οὗ ῥεῖν φασι τὸν Βαῖτιν, ὃ καλοῦσιν Ἀργυροῦν διὰ τὰ ἀργυρεῖα τὰ ἐν αὐτῷ. Πολύβιος δὲ καὶ τὸν Ἄναν καὶ τοῦτον ἐκ τῆς Κελτιβηρίας ῥεῖν φησι, διέχοντας ἀλλήλων ὅσον ἐνακοσίους σταδίους· αὐξηθέντες γὰρ οἱ Κελτίβηρες ἐποίησαν καὶ τὴν πλησιόχωρον πᾶσαν ὁμώνυμον ἑαυτοῖς. ἐοίκασι δ’ οἱ παλαιοὶ καλεῖν τὸν Βαῖτιν Ταρτησσόν, τὰ δὲ Γάδειρα καὶ τὰς πρὸς αὐτὴν νήσους Ἐρύθειαν· διόπερ οὕτως εἰπεῖν ὑπολαμβάνουσι Στησίχορον περὶ τοῦ Γηρυόνος βουκόλου διότι γεννηθείη “σχεδὸν ἀντιπέρας κλεινᾶς Ἐρυθείας Ταρτησσοῦ ποταμοῦ παρὰ παγὰς ἀπείρονας ἀργυρορίζους, ἐν κευθμῶνι πέτρας.” δυεῖν δὲ οὐσῶν ἐκβολῶν τοῦ ποταμοῦ πόλιν ἐν τῷ μεταξὺ χώρῳ κατοικεῖσθαι πρότερον φασίν, ἣν καλεῖσθαι Ταρτησσὸν ὁμώνυμον τῷ ποταμῷ, καὶ τὴν χώραν Ταρτησσίδα, ἣν νῦν Τουρδοῦλοι νέμονται. καὶ Ἐρατοσθένης δὲ τὴν συνεχῆ τῇ Κάλπῃ Ταρτησσίδα καλεῖσθαί φησι καὶ Ἐρύθειαν νῆσον εὐδαίμονα. πρὸς ὃν Ἀρτεμίδωρος ἀντιλέγων καὶ ταῦτα ψευδῶς λέγεσθαί φησιν ὑπ’ αὐτοῦ καθάπερ καὶ τὸ ἀπὸ Γαδείρων ἐπὶ τὸ ἱερὸν ἀκρωτήριον διάστημα ἀπέχειν ἡμερῶν πέντε πλοῦν, οὐ πλειόνων ὄντων ἢ χιλίων καὶ ἑπτακοσίων σταδίων, καὶ τὸ τὰς ἀμπώτεις μέχρι δεῦρο περατοῦσθαι ἀντὶ τοῦ κύκλῳ περὶ πᾶσαν τὴν οἰκουμένην συμβαίνειν, καὶ τὸ τὰ προσαρκτικὰ μέρη τῆς Ἰβηρίας εὐπαροδώτερα εἶναι πρὸς τὴν Κελτικὴν ἢ κατὰ τὸν ὠκεανὸν πλέουσι, καὶ ὅσα δὴ ἄλλα εἴρηκε Πυθέᾳ πιστεύσας.", "st": "3.2.11"}, {"sp": "N", "t": "̔ο δὲ ποιητὴς πολύφωνός τις ὢν καὶ πολυίστωρ δίδωσιν ἀφορμὰς ὡς οὐδὲ τούτων ἀνήκοός ἐστι τῶν τόπων, εἴ τις ὀρθῶς συλλογίζεσθαι βούλοιτο ἀπ’ ἀμφοῖν, τῶν τε χεῖρον λεγομένων περὶ αὐτῶν καὶ τῶν ἄμεινον καὶ ἀληθέστερον. χεῖρον μέν, ὅτι πρὸς δύσιν ἐσχάτη ἤκουεν αὕτη, ὅπου, καθάπερ αὐτός φησιν, εἰς τὸν ὠκεανὸν ἐμπίπτει “λαμπρὸν φάος ἠελίοιο, ἕλκον νύκτα μέλαιναν ἐπὶ ζείδωρον ἄρουραν.” ἡ δὲ νὺξ ὅτι δύσφημον καὶ τῷ Ἅιδῃ πλησιάζον, ὁ δὲ Ἅιδης τῷ Ταρτάρῳ, εἰκάζοι ἄν τις ἀκούοντα περὶ Ταρτησσοῦ τὸν Τάρταρον ἐκεῖθεν παρονομάσαι τὸν ἔσχατον τῶν ὑποχθονίων τόπων, προσθεῖναι δὲ καὶ μῦθον τὸ ποιητικὸν σώζοντα. καθάπερ καὶ τοὺς Κιμμερίους εἰδὼς ἐν βορείοις καὶ ζοφεροῖς οἰκήσαντας τόποις τοῖς κατὰ τὸν Βόσπορον ἵδρυσεν αὐτοὺς πρὸς τῷ Ἅιδῃ, τάχα καὶ κατά τι κοινὸν τῶν Ἰώνων ἔχθος πρὸς τὸ φῦλον τοῦτο· καὶ γὰρ καθ’ Ὅμηρον ἢ μικρὸν πρὸ αὐτοῦ λέγουσι τὴν τῶν Κιμμερίων ἔφοδον γενέσθαι τὴν μέχρι τῆς Αἰολίδος καὶ τῆς Ἰωνίας. ταῖς δὲ Κυανέαις ἐποίησε παραπλησίως τὰς Πλαγκτάς, ἀεὶ τοὺς μύθους ἀπό τινων ἱστοριῶν ἐνάγων. χαλεπὰς γάρ τινας μυθεύει πέτρας, καθάπερ τὰς Κυανέας φασίν, ἐξ οὗ καὶ Συμπληγάδες καλοῦνται· διόπερ καὶ τὸν Ἰάσονος παρέθηκε δι’ αὐτῶν πλοῦν· καὶ ὁ κατὰ τὰς στήλας δὲ πορθμὸς καὶ ὁ κατὰ Σικελίαν ὑπηγόρευον αὐτῷ τὸν περὶ τῶν Πλαγκτῶν μῦθον. πρὸς μὲν δὴ τὸ χεῖρον ἀπὸ τῆς τοῦ Ταρτάρου μυθοποιίας αἰνίττοιτό τις ἂν τὴν τῶν τόπων μνήμην τῶν περὶ Ταρτησσόν.", "st": "3.2.12"}, {"sp": "N", "t": "πρὸς δὲ τὸ βέλτιον ἐκ τούτων· ἥ τε γὰρ Ἡρακλέους στρατεία μέχρι δεῦρο προελθοῦσα καὶ τῶν Φοινίκων ὑπέγραφεν αὐτῷ πλοῦτόν τινα καὶ ῥᾳθυμίαν τῶν ἀνθρώπων· οὗτοι γὰρ Φοίνιξιν οὕτως ἐγένοντο σφόδρα ὑποχείριοι ὥστε τὰς πλείους τῶν ἐν τῇ Τουρδητανίᾳ πόλεων καὶ τῶν πλησίον τόπων ὑπ’ ἐκείνων νῦν οἰκεῖσθαι. καὶ ἡ τοῦ Ὀδυσσέως δὲ στρατεία δοκεῖ μοι δεῦρο γενηθεῖσα καὶ ἱστορηθεῖσα ὑπ’ αὐτοῦ παραδοῦναι πρόφασιν, ὥστε τὴν Ὀδύσσειαν καθάπερ καὶ τὴν Ἰλιάδα ἀπὸ τῶν συμβάντων μεταγαγεῖν εἰς ποίησιν καὶ τὴν συνήθη τοῖς ποιηταῖς μυθοποιίαν. οὐ γὰρ μόνον οἱ κατὰ τὴν Ἰταλίαν καὶ Σικελίαν τόποι καὶ ἄλλοι τινὲς τῶν τοιούτων σημεῖα ὑπογράφουσιν, ἀλλὰ καὶ ἐν τῇ Ἰβηρίᾳ Ὀδύσσεια πόλις δείκνυται καὶ Ἀθηνᾶς ἱερὸν καὶ ἄλλα μυρία ἴχνη τῆς τε ἐκείνου πλάνης καὶ ἄλλων τῶν ἐκ τοῦ Τρωικοῦ πολέμου [περι]γενομένων ἐπ’ ἴσης κακώσαντος τούς τε πολεμηθέντας καὶ τοὺς ἑλόντας τὴν Τροίαν· καὶ γὰρ οὗτοι Καδμείαν νίκην ἐτύγχανον ἠρμένοι, τῶν τε οἴκων αὐτοῖς κατεφθαρμένων καὶ τῶν λαφύρων ὀλίγων εἰς ἕκαστον ἐληλυθότων· συνέβη [δὴ] τοῖς περιλειφθεῖσιν ἀπελθοῦσιν ἐκ τῶν κινδύνων κατὰ λῃστείας τρέπεσθαι, τοῖς μὲν διὰ τὸ ἐκπεπορθῆσθαι τοῖς δὲ διὰ τὴν αἰσχύνην, ἑκάστου προλαβόντος “αἰσχρόν τοι δηρόν τε μένειν” ἄνευ τῶν οἰκείων “κενεόν τε νέεσθαι” παρ’ αὐτοὺς πάλιν. ἥ τε τοῦ Αἰνείου παραδέδοται πλάνη καὶ Ἀντήνορος καὶ ἡ τῶν Ἑνετῶν· ὡσαύτως καὶ ἡ Διομήδους τε καὶ Μενελάου καὶ ἄλλων πλειόνων. ὁ τοίνυν ποιητὴς τὰς τοσαύτας στρατείας ἐπὶ τὰ ἔσχατα τῆς Ἰβηρίας ἱστορηκώς, πυνθανόμενος δὲ καὶ πλοῦτον καὶ τὰς ἄλλας ἀρετὰς (οἱ γὰρ Φοίνικες ἐδήλουν τοῦτο) ἐνταῦθα τὸν τῶν εὐσεβῶν ἔπλασε χῶρον καὶ τὸ Ἠλύσιον πεδίον, οὗ φησιν ὁ Πρωτεὺς ἀποικήσειν τὸν Μενέλαον “ἀλλά σ’ ἐς Ἠλύσιον πεδίον καὶ πείρατα γαίης ἀθάνατοι πέμψουσιν, ὅθι ξανθὸς Ῥαδάμανθυς· τῇ περ ῥηίστη βιοτὴ πέλει ἀνθρώποισιν· οὐ νιφετὸς οὔτ’ ἂρ χειμὼν πολὺς οὐδέ ποτ’ ὄμβρος, ἀλλ’ αἰεὶ ζεφύροιο λιγὺ πνείοντας ἀήτας ὠκεανὸς ἀνίησιν ἀναψύχειν ἀνθρώπους.” τό τε γὰρ εὐάερον καὶ τὸ εὔπνουν τοῦ ζεφύρου ταύτης ἐστὶ τῆς χώρας οἰκεῖον ἑσπερίου τε καὶ ἀλεεινῆς οὔσης, τό τε ἐπὶ τοῖς πέρασι τῆς γῆς ἐφ’ οἷς καὶ τὸν Ἅιδην μεμυθεῦσθαι ἔφαμεν, ὅ τε Ῥαδάμανθυς παρατεθεὶς ὑπογράφει τὸν πλησίον τῷ Μίνῳ τόπον, περὶ οὗ φησίν “ἔνθ’ ἤτοι Μίνωα ἴδον Διὸς ἀγλαὸν υἱόν, χρύσεον σκῆπτρον ἔχοντα, θεμιστεύοντα νέκυσσι.” καὶ οἱ μετὰ ταῦτα δὲ ποιηταὶ παραπλήσια θρυλοῦσι, τήν τε ἐπὶ τὰς Γηρυόνου βόας στρατείαν καὶ τὴν ἐπὶ τὰ μῆλα τῶν Ἑσπερίδων τὰ χρύσεα ὡσαύτως, καὶ μακάρων τινὰς νήσους κατονομάζοντες, ἃς καὶ νῦν δεικνυμένας ἴσμεν οὐ πολὺ ἄπωθεν τῶν ἄκρων τῆς Μαυρουσίας τῶν ἀντικειμένων τοῖς Γαδείροις.", "st": "3.2.13"}, {"sp": "N", "t": "τοὺς δὲ Φοίνικας λέγω μηνυτάς· καὶ τῆς Ἰβηρίας καὶ τῆς Λιβύης τὴν ἀρίστην οὗτοι κατέσχον πρὸ τῆς ἡλικίας τῆς Ὁμήρου καὶ διετέλεσαν κύριοι τῶν τόπων ὄντες, μέχρι οὗ Ῥωμαῖοι κατέλυσαν αὐτῶν τὴν ἡγεμονίαν. τοῦ δ’ Ἰβηρικοῦ πλούτου καὶ ταῦτα μαρτύρια· Καρχηδόνιοι μετὰ τοῦ Βάρκα στρατεύσαντες κατέλαβον, ὥς φασιν οἱ συγγραφεῖς, φάτναις ἀργυραῖς καὶ πίθοις χρωμένους τοὺς ἐν τῇ Τουρδητανίᾳ. ὑπολάβοι δ’ ἄν τις ἐκ τῆς πολλῆς εὐδαιμονίας καὶ μακραίωνας ὀνομασθῆναι τοὺς ἐνθάδε ἀνθρώπους, καὶ μάλιστα τοὺς ἡγεμόνας, καὶ διὰ τοῦτο Ἀνακρέοντα μὲν οὕτως εἰπεῖν “ἔγωγ’ οὔτ’ ἂν Ἀμαλθίης βουλοίμην κέρας οὔτ’ ἔτεα πεντήκοντά τε καὶ ἑκατὸν Ταρτησσοῦ βασιλεῦσαι,” Ἡρόδοτον δὲ καὶ τὸ ὄνομα τοῦ βασιλέως καταγράψαι καλέσαντα Ἀργανθώνιον.", "st": "3.2.14"}, {"sp": "N", "t": "τῇ δὲ τῆς χώρας εὐδαιμονίᾳ καὶ τὸ ἥμερον καὶ τὸ πολιτικὸν συνηκολούθησε τοῖς Τουρδητανοῖς, καὶ τοῖς Κελτικοῖς δὲ διὰ τὴν γειτνίασιν, ὡς δ’ εἴρηκε Πολύβιος διὰ τὴν συγγένειαν· ἀλλ’ ἐκείνοις μὲν ἧττον· τὰ πολλὰ γὰρ κωμηδὸν ζῶσιν. οἱ μέντοι Τουρδητανοὶ καὶ μάλιστα οἱ περὶ τὸν Βαῖτιν τελέως εἰς τὸν Ῥωμαίων μεταβέβληνται τρόπον οὐδὲ τῆς διαλέκτου τῆς σφετέρας ἔτι μεμνημένοι. Λατῖνοί τε οἱ πλεῖστοι γεγόνασι καὶ ἐποίκους εἰλήφασι Ῥωμαίους, ὥστε μικρὸν ἀπέχουσι τοῦ πάντες εἶναι Ῥωμαῖοι. αἵ τε νῦν συνῳκισμέναι πόλεις, ἥ τε ἐν τοῖς Κελτικοῖς Παξαυγοῦστα καὶ ἡ ἐν τοῖς Τουρδούλοις Αὐγοῦστα Ἠμέριτα καὶ ἡ περὶ τοὺς Κελτίβηρας Καισαραυγοῦστα καὶ ἄλλαι ἔνιαι κατοικίαι, τὴν μεταβολὴν τῶν λεχθεισῶν πολιτειῶν ἐμφανίζουσι. καὶ δὴ τῶν Ἰβήρων ὅσοι ταύτης εἰσὶ τῆς ἰδέας τογᾶτοι λέγονται· ἐν δὲ τούτοις εἰσὶ καὶ οἱ Κελτίβηρες οἱ πάντων νομισθέντες ποτὲ θηριωδέστατοι. ταῦτα μὲν περὶ τούτων.", "st": "3.2.15"}, {"sp": "N", "t": "Ἀπὸ δὲ τοῦ ἱεροῦ πάλιν ἀκρωτηρίου τὴν ἀρχὴν λαμβάνουσιν ἐπὶ θάτερον μέρος τῆς παραλίας τὸ πρὸς τὸν Τάγον κόλπος ἐστίν· ἔπειτα ἄκρα τὸ Βαρβάριον καὶ αἱ τοῦ Τάγου ἐκβολαὶ πλησίον, ἐφ’ ἃς εὐθυπλοίᾳ … στάδιοι δ’ εἰσὶ δέκα· ἐνταῦθα δὲ καὶ ἀναχύσεις, ὧν μία ἐπὶ πλείους ἢ τετρακοσίους σταδίους ἀπὸ τοῦ λεχθέντος πύργου, καθ’ ἣν ὑδρεύονται εἴ που λακκαῖα. ὁ δὲ Τάγος καὶ τὸ πλάτος ἔχει τοῦ στόματος εἴκοσί που σταδίων καὶ τὸ βάθος μέγα, ὥστε μυριαγωγοῖς ἀναπλεῖσθαι. δύο δ’ ἀναχύσεις ἐν τοῖς ὑπερκειμένοις ποιεῖται πεδίοις, ὅταν αἱ πλῆμαι γίνωνται, ὥστε πελαγίζειν μὲν ἐπὶ ἑκατὸν καὶ πεντήκοντα σταδίους καὶ ποιεῖν πλωτὸν τὸ πεδίον, ἐν δὲ τῇ ἐπάνω ἀναχύσει καὶ νησίον ἀπολαμβάνειν ὅσον τριάκοντα σταδίων τὸ μῆκος, πλάτος δὲ μικρὸν ἀπολεῖπον τοῦ μήκους, εὐαλσὲς καὶ εὐάμπελον. κεῖται δ’ ἡ νῆσος κατὰ Μόρωνα πόλιν εὖ κειμένην ἐν ὄρει τοῦ ποταμοῦ πλησίον, ἀφεστῶσαν τῆς θαλάττης ὅσον πεντακοσίους σταδίους, ἔχουσαν δὲ καὶ χώραν ἀγαθὴν τὴν πέριξ καὶ τοὺς ἀνάπλους εὐπετεῖς μέχρι μὲν πολλοῦ καὶ μεγάλοις σκάφεσι, τὸ δὲ λοιπὸν τοῖς ποταμίοις· καὶ ὑπὲρ τὸν Μόρωνα δ’ ἔτι μακρότερος ἀνάπλους ἐστί. ταύτῃ δὲ τῇ πόλει Βροῦτος ὁ Καλλαϊκὸς προσαγορευθεὶς ὁρμητηρίῳ χρώμενος ἐπολέμησε πρὸς τοὺς Λυσιτανοὺς καὶ κατέστρεψε τούτους. τοῖς δὲ τοῦ ποταμοῦ πλίθροις ἐπετείχισε τὴν Ὀλυσιπῶνα, ἵν’ ἔχοι τοὺς ἀνάπλους ἐλευθέρους καὶ τὰς ἀνακομιδὰς τῶν ἐπιτηδείων, ὥστε καὶ τῶν περὶ τὸν Τάγον πόλεων αὗται κράτισται. πολύιχθυς δ’ ὁ ποταμὸς καὶ ὀστρέων πλήρης. ῥεῖ δ’ ἔχων τὰς ἀρχὰς ἐκ Κελτιβήρων διὰ Ὀυεττώνων καὶ Καρπητανῶν καὶ Λυσιτανῶν ἐπὶ δύσιν ἰσημερινήν, μέχρι ποσοῦ παράλληλος ὢν τῷ τε Ἄνᾳ καὶ τῷ Βαίτι, μετὰ δὲ ταῦτα ἀφιστάμενος ἐκείνων ἀποκλινόντων πρὸς τὴν νότιον παραλίαν.", "st": "3.3.1"}, {"sp": "N", "t": "οἱ δὲ ὑπερκείμενοι τῶν λεχθέντων μερῶν Ὠρητανοὶ μέν εἰσι νοτιώτατοι καὶ μέχρι τῆς παραλίας διήκοντες ἐκ μέρους τῆς ἐντὸς στηλῶν, Καρπητανοὶ δὲ μετὰ τούτους πρὸς ἄρκτους, εἶτα Ὀυέττωνες καὶ Ὀυακκαῖοι, δι’ ὧν ὁ Δούριος ῥεῖ κατ’ Ἀκούτειαν πόλιν τῶν Ὀυακκαίων ἔχων διάβασιν, Καλλαϊκοὶ δ’ ὕστατοι, τῆς ὀρεινῆς ἐπέχοντες πολλήν· διὸ καὶ δυσμαχώτατοι ὄντες τῷ τε καταπολεμήσαντι τοὺς Λυσιτανοὺς αὐτοὶ παρέσχον τὴν ἐπωνυμίαν, καὶ νῦν ἤδη τοὺς πλείστους τῶν Λυσιτανῶν Καλλαϊκοὺς καλεῖσθαι παρεσκεύασαν. τῆς μὲν οὖν Ὠρητανίας κρατιστεύουσά ἐστι πόλις Καστουλὼν καὶ Ὠρία.", "st": "3.3.2"}, {"sp": "N", "t": "τοῦ δὲ Τάγου τὰ πρὸς ἄρκτον ἡ Λυσιτανία ἐστὶ μέγιστον τῶν Ἰβηρικῶν ἐθνῶν καὶ πλείστοις χρόνοις ὑπὸ Ῥωμαίων πολεμηθέν. περιέχει δὲ τῆς χώρας ταύτης τὸ μὲν νότιον πλευρὸν ὁ Τάγος, τὸ δ’ ἑσπέριον καὶ τὸ ἀρκτικὸν ὁ ὠκεανός, τὸ δ’ ἑωθινὸν οἵ τε Καρπητανοὶ καὶ οἱ Ὀυέττωνες καὶ Ὀυακκαῖοι καὶ Καλλαϊκοί, τὰ γνώριμα ἔθνη· τἆλλα δὲ οὐκ ἄξιον ὀνομάζειν διὰ τὴν μικρότητα καὶ τὴν ἀδοξίαν· ὑπεναντίως δὲ τὰ νῦν ἔνιοι καὶ τούτους Λυσιτανοὺς ὀνομάζουσιν. ὅμοροι δ’ εἰσὶν ἐκ τοῦ πρὸς ἕω μέρους οἱ μὲν Καλλαϊκοὶ τῷ τῶν Ἀστούρων ἔθνει καὶ τοῖς [Κελτ]ίβηρσιν, οἱ δ’ ἄλλοι τοῖς Κελτίβηρσι. τὸ μὲν οὖν μῆκος τρισχιλίων σταδίων, τὸ δὲ πλάτος πολὺ ἔλαττον, ὃ ποιεῖ τὸ ἑωθινὸν πλευρὸν εἰς τὴν ἀντικειμένην παραλίαν· ὑψηλὸν δ’ ἐστὶ τὸ ἑωθινὸν καὶ τραχύ, ἡ δὲ ὑποκειμένη χώρα πεδιὰς πᾶσα καὶ μέχρι θαλάττης πλὴν ὀλίγων ὀρῶν οὐ μεγάλων· ᾗ δὴ καὶ τὸν Ἀριστοτέλη φησὶν ὁ Ποσειδώνιος οὐκ ὀρθῶς αἰτιᾶσθαι τὴν παραλίαν τῶν πλημμυρίδων καὶ τῶν ἀμπώτεων· παλιρροεῖν γὰρ φάναι τὴν θάλατταν διὰ τὸ τὰς ἀκτὰς ὑψηλάς τε καὶ τραχείας εἶναι δεχομένας τε τὸ κῦμα σκληρῶς καὶ ἀνταποδιδούσας. τἀναντία γὰρ τῇ Ἰβηρίᾳ θινώδεις εἶναι καὶ ταπεινὰς τὰς πλείστας, ὀρθῶς λέγων.", "st": "3.3.3"}, {"sp": "N", "t": "̔η δ’ οὖν χώρα περὶ ἧς λέγομεν εὐδαίμων τέ ἐστι καὶ διαρρεῖται ποταμοῖς μεγάλοις τε καὶ μικροῖς, ἅπασιν ἐκ τῶν ἑωθινῶν μερῶν, παραλλήλοις τῷ Τάγῳ· ἔχουσι δὲ καὶ ἀνάπλους οἱ πλείους καὶ ψῆγμα τοῦ χρυσοῦ πλεῖστον. γνωριμώτατοι δὲ τῶν ποταμῶν ἐφεξῆς τῷ Τάγῳ Μούνδας ἀνάπλους ἔχων μικροὺς καὶ Ὀυακούα ὡσαύτως· μετὰ δὲ τούτους Δούριος μακρόθεν τε ῥέων παρὰ Νομαντίαν καὶ πολλὰς ἄλλας τῶν Κελτιβήρων καὶ Ὀυακκαίων κατοικίας, μεγάλοις τ’ ἀναπλεόμενος σκάφεσιν ἐπὶ ὀκτακοσίους σχεδόν τι σταδίους. εἶτ’ ἄλλοι ποταμοὶ καὶ μετὰ τούτους ὁ τῆς Λήθης, ὃν τινὲς Λιμαίαν οἱ δὲ Βελιῶνα καλοῦσι· καὶ οὗτος δ’ ἐκ Κελτιβήρων καὶ Ὀυακκαίων ῥεῖ καὶ ὁ μετ’ αὐτὸν Βαῖνις (οἱ δὲ Μίνιον φασὶ) πολὺ μέγιστος τῶν ἐν Λυσιτανίᾳ ποταμῶν ἐπὶ ὀκτακοσίους καὶ αὐτὸς ἀναπλεόμενος σταδίους. Ποσειδώνιος δὲ ἐκ Καντάβρων αὐτὸν ῥεῖν φησί· πρόκειται δὲ τῆς ἐκβολῆς αὐτοῦ νῆσος καὶ χηλαὶ δύο ὅρμους ἔχουσαι. ἐπαινεῖν δ’ ἄξιον τὴν φύσιν, ὅτι τὰς ὄχθας ὑψηλὰς ἔχουσιν οἱ ποταμοὶ καὶ ἱκανὰς δέχεσθαι τοῖς ῥείθροις τὴν θάλατταν πλημμυροῦσαν, ὥστε μὴ ὑπερχεῖσθαι μηδ’ ἐπιπολάζειν ἐν τοῖς πεδίοις. τῆς μὲν οὖν Βρούτου στρατείας ὅρος οὗτος, περαιτέρω δ’ εἰσὶν ἄλλοι πλείους ποταμοὶ παράλληλοι τοῖς λεχθεῖσιν.", "st": "3.3.4"}, {"sp": "N", "t": "̔́υστατοι δ’ οἰκοῦσιν Ἄρταβροι περὶ τὴν ἄκραν ἣ καλεῖται Νέριον, ἣ καὶ τῆς ἑσπερίου πλευρᾶς καὶ τῆς βορείου πέρας ἐστί. περιοικοῦσι δ’ αὐτὴν [καὶ] Κελτικοί, συγγενεῖς τῶν ἐπὶ τῷ Ἄνᾳ. καὶ γὰρ τούτους καὶ Τουρδούλους στρατεύσαντας ἐκεῖσε στασιάσαι φασὶ μετὰ τὴν διάβασιν τοῦ Λιμαία ποταμοῦ· πρὸς δὲ τῇ στάσει καὶ ἀποβολῆς τοῦ ἡγεμόνος γενομένης, καταμεῖναι σκεδασθέντας αὐτόθι· ἐκ τούτου δὲ καὶ τὸν ποταμὸν Λήθης προσαγορευθῆναι. ἔχουσι δὲ οἱ Ἄρταβροι πόλεις συχνὰς ἐν κόλπῳ συνοικουμένας, ὃν οἱ πλέοντες καὶ χρώμενοι τοῖς τόποις Ἀρτάβρων λιμένα προσαγορεύουσιν· οἱ δὲ νῦν τοὺς Ἀρτάβρους Ἀροτρέβας καλοῦσιν. ἔθνη μὲν οὖν περὶ τριάκοντα τὴν χώραν νέμεται τὴν μεταξὺ Τάγου καὶ τῶν Ἀρτάβρων· εὐδαίμονος δὲ τῆς χώρας ὑπαρχούσης κατά τε καρποὺς καὶ βοσκήματα καὶ τὸ τοῦ χρυσοῦ καὶ ἀργύρου καὶ τῶν παραπλησίων πλῆθος, ὅμως οἱ πλείους αὐτῶν τὸν ἀπὸ τῆς γῆς ἀφέντες βίον ἐν λῃστηρίοις διετέλουν καὶ συνεχεῖ πολέμῳ πρός τε ἀλλήλους καὶ τοὺς ὁμόρους αὐτοῖς διαβαίνοντες τὸν Τάγον, ἕως ἔπαυσαν αὐτοὺς Ῥωμαῖοι ταπεινώσαντες καὶ κώμας ποιήσαντες τὰς πόλεις αὐτῶν τὰς πλείστας, ἐνίας δὲ καὶ συνοικίζοντες βέλτιον. ἦρχον δὲ τῆς ἀνομίας ταύτης οἱ ὀρεινοί, καθάπερ εἰκός· λυπρὰν γὰρ νεμόμενοι καὶ μικρὰ κεκτημένοι τῶν ἀλλοτρίων ἐπεθύμουν, οἱ δὲ ἀμυνόμενοι τούτους ἄκυροι τῶν ἰδίων ἔργων καθίσταντο ἐξ ἀνάγκης, ὥστ’ ἀντὶ τοῦ γεωργεῖν ἐπολέμουν καὶ οὗτοι, καὶ συνέβαινε τὴν χώραν ἀμελουμένην στεῖραν οὖσαν τῶν ἐμφύτων ἀγαθῶν οἰκεῖσθαι ὑπὸ λῃστῶν.", "st": "3.3.5"}, {"sp": "N", "t": "τοὺς δ’ οὖν Λυσιτανούς φασιν ἐνεδρευτικοὺς ἐξερευνητικοὺς ὀξεῖς κούφους εὐεξελίκτους· ἀσπίδιον δ’ αὐτοὺς δίπουν ἔχειν τὴν διάμετρον, κοῖλον εἰς τὸ πρόσθεν, τελαμῶσιν ἐξηρτημένον· οὔτε γὰρ πόρπακας οὔτ’ ἀντιλαβὰς ἔχει … παραξιφὶς πρὸς τούτοις ἢ κοπίς. λινοθώρακες οἱ πλείους· σπάνιοι δὲ ἁλυσιδωτοῖς χρῶνται καὶ τριλοφίαις, οἱ δ’ ἄλλοι νευρίνοις κράνεσιν· οἱ πεζοὶ δὲ καὶ κνημῖδας ἔχουσιν, ἀκόντια δ’ ἕκαστος πλείω· τινὲς δὲ καὶ δόρατι χρῶνται· ἐπιδορατίδες δὲ χάλκεαι. ἐνίους δὲ τῶν προσοικούντων τῷ Δουρίῳ ποταμῷ λακωνικῶς διάγειν φασίν, ἀλειπτηρίοις χρωμένους δὶς καὶ πυρίαις ἐκ λίθων διαπύρων, ψυχρολουτροῦντας καὶ μονοτροφοῦντας καθαρείως καὶ λιτῶς. θυτικοὶ δ’ εἰσὶ Λυσιτανοὶ τά τε σπλάγχνα ἐπιβλέπουσιν οὐκ ἐκτέμνοντες· προσεπιβλέπουσι δὲ καὶ τὰς ἐν τῇ πλευρᾷ φλέβας, καὶ ψηλαφῶντες δὲ τεκμαίρονται. σπλαγχνεύονται δὲ καὶ δι’ ἀνθρώπων αἰχμαλώτων καλύπτοντες σάγοις· εἶθ’ ὅταν πληγῇ τὰ σπλάγχνα ὑπὸ τοῦ ἱεροσκόπου, μαντεύονται πρῶτον ἐκ τοῦ πτώματος. τῶν δ’ ἁλόντων τὰς χεῖρας ἀποκόπτοντες τὰς δεξιὰς ἀνατιθέασιν.", "st": "3.3.6"}, {"sp": "N", "t": "̔́απαντες δ’ οἱ ὄρειοι λιτοὶ ὑδροπόται χαμαιεῦναι βαθεῖαν κατακεχυμένοι τὴν κόμην γυναικῶν δίκην· μιτρωσάμενοι δὲ τὰ μέτωπα μάχονται. τραγοφαγοῦσι δὲ μάλιστα, καὶ τῷ Ἄρει τράγον θύουσι καὶ τοὺς αἰχμαλώτους καὶ ἵππους· ποιοῦσι δὲ καὶ ἑκατόμβας ἑκάστου γένους ἑλληνικῶς. τελοῦσι δὲ καὶ ἀγῶνας γυμνικοὺς καὶ ὁπλιτικοὺς καὶ ἱππικούς, πυγμῇ καὶ δρόμῳ καὶ ἀκροβολισμῷ καὶ τῇ σπειρηδὸν μάχῃ. οἱ δ’ ὄρειοι τὰ δύο μέρη τοῦ ἔτους δρυοβαλάνῳ χρῶνται ξηράναντες καὶ κόψαντες, εἶτα ἀλέσαντες καὶ ἀρτοποιησάμενοι ὥστ’ ἀποτίθεσθαι εἰς χρόνον. χρῶνται δὲ καὶ ζύθει· οἴνῳ δὲ σπανίζονται, τὸν δὲ γινόμενον ταχὺ ἀναλίσκουσι κατευωχούμενοι μετὰ τῶν συγγενῶν· ἀντ’ ἐλαίου δὲ βουτύρῳ χρῶνται. καθήμενοί τε δειπνοῦσι περὶ τοὺς τοίχους καθέδρας οἰκοδομητὰς ἔχοντες, προκάθηνται δὲ καθ’ ἡλικίαν καὶ τιμήν· περιφορητὸν δὲ τὸ δεῖπνον. ξυλίνοις δὲ ἀγγείοις χρῶνται, καθάπερ καὶ οἱ Κελτοί. καὶ παρὰ πότον ὀρχοῦνται πρὸς αὐλὸν καὶ σάλπιγγα χορεύοντες, ἀλλὰ καὶ ἀναλλόμενοι καὶ ὀκλάζοντες· ἐν Βαστητανίᾳ δὲ καὶ γυναῖκες ἀναμὶξ ἀνδράσιν ἀντιλαμβανόμεναι τῶν χειρῶν. μελανείμονες ἅπαντες τὸ πλέον ἐν σάγοις, ἐν οἷσπερ καὶ στιβαδοκοιτοῦσι, αἱ γυναῖκες δ’ ἐν ἐνδύμασι καὶ ἀνθίναις ἐσθήσεσι διάγουσιν. ἀντὶ δὲ νομίσματος οἱ λίαν ἐν βάθει φορτίων ἀμοιβῇ χρῶνται ἢ τοῦ ἀργυροῦ ἐλάσματος ἀποτέμνοντες διδόασι. τοὺς δὲ θανατουμένους καταπετροῦσι, τοὺς δὲ πατραλοίας ἔξω τῶν ὅρων καταλεύουσι. γαμοῦσι δ’ ὥσπερ οἱ Ἕλληνες. τοὺς δὲ ἀρρώστους, ὥσπερ οἱ Ἀσσύριοι τὸ παλαιόν, προτιθέασιν εἰς τὰς ὁδοὺς τοῖς πεπειραμένοις τοῦ πάθους ὑποθήκης χάριν. διφθερίνοις τε πλοίοις ἐχρῶντο ἕως ἐπὶ Βρούτου διὰ τὰς πλημμυρίδας καὶ τὰ τενάγη, νυνὶ δὲ καὶ τὰ μονόξυλα ἤδη σπάνια. ἅλες πορφυροῖ, τριφθέντες δὲ λευκοί. ἔστι δὲ τῶν ὀρείων ὁ βίος οὗτος, ὧνπερ ἔφην, λέγω δὲ τοὺς τὴν βόρειον πλευρὰν ἀφορίζοντας τῆς Ἰβηρίας, Καλλαϊκοὺς καὶ Ἄστουρας καὶ Καντάβρους μέχρι Ὀυασκώνων καὶ τῆς Πυρήνης· ὁμοειδεῖς γὰρ ἁπάντων οἱ βίοι. ὀκνῶ δὲ τοῖς ὀνόμασι πλεονάζειν φεύγων τὸ ἀηδὲς τῆς γραφῆς, εἰ μή τινι πρὸς ἡδονῆς ἐστιν ἀκούειν Πλευταύρους καὶ Βαρδυήτας καὶ Ἀλλότριγας καὶ ἄλλα χείρω καὶ ἀσημότερα τούτων ὀνόματα.", "st": "3.3.7"}, {"sp": "N", "t": "τὸ δὲ δυσήμερον καὶ ἀγριῶδες οὐκ ἐκ τοῦ πολεμεῖν συμβέβηκε μόνον ἀλλὰ καὶ διὰ τὸν ἐκτοπισμόν· καὶ γὰρ ὁ πλοῦς ἐπ’ αὐτοὺς μακρὸς καὶ αἱ ὁδοί, δυσεπίμικτοι δ’ ὄντες ἀποβεβλήκασι τὸ κοινωνικὸν καὶ τὸ φιλάνθρωπον. ἧττον δὲ νῦν τοῦτο πάσχουσι διὰ τὴν εἰρήνην καὶ τὴν τῶν Ῥωμαίων ἐπιδημίαν· ὅσοις δ’ ἧττον τοῦτο συμβαίνει, χαλεπώτεροί εἰσι καὶ θηριωδέστεροι. τοιαύτης δ’ οὔσης καὶ ἀπὸ τῶν τόπων λυπρότητος ἐνίοις καὶ τῶν ὀρῶν, εἰκὸς ἐπιτείνεσθαι τὴν τοιαύτην ἀτοπίαν. ἀλλὰ νῦν, ὡς εἶπον, πέπαυται πολεμοῦντα πάντα· τούς τε γὰρ συνέχοντας ἔτι νῦν μάλιστα τὰ λῃστήρια Καντάβρους καὶ τοὺς γειτονεύοντας αὐτοῖς κατέλυσεν ὁ Σεβαστὸς Καῖσαρ, καὶ ἀντὶ τοῦ πορθεῖν τοὺς τῶν Ῥωμαίων συμμάχους στρατεύουσι νῦν ὑπὲρ τῶν Ῥωμαίων οἵ τε Κωνιακοὶ καὶ οἱ πρὸς ταῖς πηγαῖς τοῦ Ἴβηρος οἰκοῦντες Πληντουίσοι. ὅ τ’ ἐκεῖνον διαδεξάμενος Τιβέριος τριῶν ταγμάτων στρατιωτικὸν ἐπιστήσας τοῖς τόποις, τὸ ἀποδειχθὲν ὑπὸ τοῦ Σεβαστοῦ Καίσαρος, οὐ μόνον εἰρηνικοὺς ἀλλὰ καὶ πολιτικοὺς ἤδη τινὰς αὐτῶν ἀπεργασάμενος τυγχάνει.", "st": "3.3.8"}, {"sp": "N", "t": "λοιπὴ δ’ ἐστὶ τῆς Ἰβηρίας ἥ τε ἀπὸ τῶν στηλῶν μέχρι τῆς Πυρήνης καθ’ ἡμᾶς παραλία καὶ ἡ ταύτης ὑπερκειμένη μεσόγαια πᾶσα, τὸ μὲν πλάτος ἀνώμαλος τὸ δὲ μῆκος μικρῷ πλειόνων ἢ τετρακισχιλίων σταδίων· τὸ δὲ τῆς παραλίας ἔτι πλεῖον καὶ δισχιλίοις σταδίοις εἴρηται. φασὶ δὲ ἀπὸ μὲν Κάλπης τοῦ κατὰ στήλας ὄρους ἐπὶ Καρχηδόνα νέαν δισχιλίους καὶ διακοσίους σταδίους· οἰκεῖσθαι δὲ τὴν ᾐόνα ταύτην ὑπὸ Βαστητανῶν οὓς καὶ Βαστούλους καλοῦσιν, ἐκ μέρους δὲ καὶ ὑπὸ Ὠρητανῶν. ἐντεῦθεν δ’ ἐπὶ τὸν Ἴβηρα ἄλλους τοσούτους σχεδόν τι (ταύτην δ’ ἔχειν Ἐδητανούς), ἐντὸς δὲ τοῦ Ἴβηρος μέχρι Πυρήνης καὶ τῶν Πομπηίου ἀναθημάτων χιλίους καὶ ἑξακοσίους· οἰκεῖν δὲ Ἐδητανῶν τε ὀλίγους καὶ λοιπὸν τοὺς προσαγορευομένους Ἰνδικήτας μεμερισμένους τέτραχα.", "st": "3.4.1"}, {"sp": "N", "t": "κατὰ μέρος δὲ ἀπὸ Κάλπης ἀρξαμένοις ῥάχις ἐστὶν ὀρεινὴ τῆς Βαστητανίας καὶ τῶν Ὠρητανῶν δασεῖαν ὕλην ἔχουσα καὶ μεγαλόδενδρον, διορίζουσα τὴν παραλίαν ἀπὸ τῆς μεσογαίας. πολλαχοῦ δὲ κἀνταῦθά ἐστι χρυσεῖα καὶ ἄλλα μέταλλα. πόλις δ’ ἐστὶν ἐν τῇ παραλίᾳ ταύτῃ πρώτη Μάλακα, ἴσον διέχουσα τῆς Κάλπης ὅσον καὶ τὰ Γάδειρα· ἐμπόριον δ’ ἐστὶν τοῖς ἐν τῇ περαίᾳ νομάσι, καὶ ταριχείας δὲ ἔχει μεγάλας. ταύτην τινὲς τῇ Μαινάκῃ τὴν αὐτὴν νομίζουσιν, ἣν ὑστάτην τῶν Φωκαϊκῶν πόλεων πρὸς δύσει κειμένην παρειλήφαμεν, οὐκ ἔστι δέ· ἀλλ’ ἐκείνη μὲν ἀπωτέρω τῆς Κάλπης ἐστί, κατεσκαμμένη, τὰ δ’ ἴχνη σώζουσα Ἑλληνικῆς πόλεως, ἡ δὲ Μάλακα πλησίον μᾶλλον, Φοινικικὴ τῷ σχήματι. ἐφεξῆς δ’ ἐστὶν ἡ τῶν Ἐξιτανῶν πόλις, ἐξ ἧς καὶ τὰ ταρίχη ἐπωνύμως λέγεται.", "st": "3.4.2"}, {"sp": "N", "t": "μετὰ ταύτην Ἄβδηρα Φοινίκων κτίσμα καὶ αὐτή. ὑπὲρ δὲ τῶν τόπων ἐν τῇ ὀρεινῇ δείκνυται Ὀδύσσεια καὶ τὸ ἱερὸν τῆς Ἀθηνᾶς ἐν αὐτῇ, ὡς Ποσειδώνιός τε εἴρηκε καὶ Ἀρτεμίδωρος καὶ Ἀσκληπιάδης ὁ Μυρλεανός, ἀνὴρ ἐν τῇ Τουρδητανίᾳ παιδεύσας τὰ γραμματικὰ καὶ περιήγησίν τινα τῶν ἐθνῶν ἐκδεδωκὼς τῶν ταύτῃ. οὗτος δέ φησιν ὑπομνήματα τῆς πλάνης τῆς Ὀδυσσέως ἐν τῷ ἱερῷ τῆς Ἀθηνᾶς ἀσπίδας προσπεπατταλεῦσθαι καὶ ἀκροστόλια. ἐν Καλλαϊκοῖς δὲ τῶν μετὰ Τεύκρου στρατευσάντων τινὰς οἰκῆσαι, καὶ ὑπάρξαι πόλεις αὐτόθι, τὴν μὲν καλουμένην Ἕλληνες τὴν δὲ Ἀμφίλοχοι, ὡς καὶ τοῦ Ἀμφιλόχου τελευτήσαντος δεῦρο καὶ τῶν συνόντων πλανηθέντων μέχρι τῆς μεσογαίας. καὶ τῶν μεθ’ Ἡρακλέους δέ τινας καὶ τῶν ἀπὸ Μεσσήνης ἱστορῆσθαί φησιν ἐποικῆσαι τὴν Ἰβηρίαν, τῆς δὲ Κανταβρίας μέρος τι κατασχεῖν Λάκωνας καὶ οὗτός φησι καὶ ἄλλοι. ἐνταῦθα δὲ καὶ Ὠκέλλαν πόλιν Ὠκέλλα κτίσμα λέγουσι τοῦ μετὰ Ἀντήνορος καὶ τῶν παίδων αὐτοῦ διαβάντος εἰς τὴν Ἰταλίαν. καὶ ἐν τῇ Λιβύῃ δὲ πεπιστεύκασί τινες τοῖς τῶν Γαδειριτῶν ἐμπόροις προσέχοντες, ὡς καὶ Ἀρτεμίδωρος εἴρηκεν, ὅτι οἱ ὑπὲρ τῆς Μαυρουσίας οἰκοῦντες πρὸς τοῖς ἑσπερίοις Αἰθίοψι Λωτοφάγοι καλοῦνται, σιτούμενοι λωτόν, πόαν τινὰ καὶ ῥίζαν, οὐ δεόμενοι δὲ ποτοῦ, οὐδὲ ἔχοντες διὰ τὴν ἀνυδρίαν, διατείνοντες καὶ μέχρι τῶν ὑπὲρ τῆς Κυρήνης τόπων. ἄλλοι τε πάλιν καλοῦνται Λωτοφάγοι τὴν ἑτέραν οἰκοῦντες τῶν πρὸ τῆς μικρᾶς Σύρτεως νήσων, τὴν Μήνιγγα.", "st": "3.4.3"}, {"sp": "N", "t": "οὐ δὴ θαυμάζοι τις ἂν οὔτε τοῦ ποιητοῦ τὰ περὶ τὴν Ὀδυσσέως πλάνην μυθογραφήσαντος τοῦτον τὸν τρόπον, ὥστ’ ἔξω στηλῶν ἐν τῷ Ἀτλαντικῷ πελάγει τὰ πολλὰ διαθέσθαι τῶν λεγομένων περὶ αὐτοῦ (τὰ γὰρ ἱστορούμενα ἐγγὺς ἦν καὶ [τοῖς] τόποις καὶ τοῖς ἄλλοις τῶν ὑπ’ ἐκείνου πεπλασμένων, ὥστε οὐκ ἀπίθανον ἐποίει τὸ πλάσμα), οὔτ’ εἴ τινες αὐταῖς τε ταύταις ταῖς ἱστορίαις πιστεύσαντες καὶ τῇ πολυμαθείᾳ τοῦ ποιητοῦ καὶ πρὸς ἐπιστημονικὰς ὑποθέσεις ἔτρεψαν τὴν Ὁμήρου ποίησιν, καθάπερ Κράτης τε ὁ Μαλλώτης ἐποίησε καὶ ἄλλοι τινές. οἱ δ’ οὕτως ἀγροίκως ἐδέξαντο τὴν ἐπιχείρησιν τὴν τοιαύτην ὥστε οὐ μόνον τὸν ποιητὴν σκαπανέως ἢ θεριστοῦ δίκην ἐκ πάσης τῆς τοιαύτης ἐπιστήμης ἐξέβαλον, ἀλλὰ καὶ τοὺς ἁψαμένους τῆς τοιαύτης πραγματείας μαινομένους ὑπέλαβον· συνηγορίαν δὲ ἢ ἐπανόρθωσιν ἤ τι τοιοῦτον ἕτερον εἰς τὰ λεχθέντα ὑπ’ ἐκείνων εἰσενεγκεῖν οὐκ ἐθάρρησεν οὔτε τῶν γραμματικῶν οὔτε τῶν περὶ τὰ μαθήματα δεινῶν οὐδείς. καίτοι ἔμοιγε δοκεῖ δυνατὸν εἶναι καὶ συνηγορῆσαι πολλοῖς τῶν λεχθέντων καὶ εἰς ἐπανόρθωσιν ἄγειν καὶ μάλιστα ταῦτα ὅσα Πυθέας παρεκρούσατο τοὺς πιστεύσαντας αὐτῷ κατὰ ἄγνοιαν τῶν τε ἑσπερίων τόπων καὶ τῶν προσβόρρων τῶν παρὰ τὸν ὠκεανόν. ἀλλὰ ταῦτα μὲν ἐάσθω λόγον ἔχοντα ἴδιον καὶ μακρόν.", "st": "3.4.4"}, {"sp": "N", "t": "τῆς δὲ τῶν Ἑλλήνων πλάνης τῆς εἰς τὰ βάρβαρα ἔθνη νομίζοι τις ἂν αἴτιον τὸ διεσπάσθαι κατὰ μέρη μικρὰ καὶ δυναστείας ἐπιπλοκὴν οὐκ ἐχούσας πρὸς ἀλλήλους κατ’ αὐθάδειαν, ὥστε ἐκ τούτου πρὸς τοὺς ἐπιόντας ἔξωθεν ἀσθενεῖς εἶναι. τοῦτο δὲ τὸ αὔθαδες ἐν δὴ τοῖς Ἴβηρσι μάλιστα ἐπέτεινε προσλαβοῦσι καὶ τὸ πανοῦργον φύσει καὶ τὸ μὴ ἁπλοῦν· ἐπιθετικοὶ γὰρ καὶ λῃστρικοὶ τοῖς βίοις ἐγένοντο τὰ μικρὰ τολμῶντες, μεγάλοις δ’ οὐκ ἐπιβαλλόμενοι διὰ τὸ μεγάλας μὴ κατασκευάζεσθαι δυνάμεις καὶ κοινωνίας. εἰ γὰρ δὴ συνασπίζειν ἐβούλοντο ἀλλήλοις, οὔτε Καρχηδονίοις ὑπῆρξεν ἂν καταστρέψασθαι ἐπελθοῦσι τὴν πλείστην αὐτῶν ἐκ περιουσίας, καὶ ἔτι πρότερον Τυρίοις, εἶτα Κελτοῖς οἳ νῦν Κελτίβηρες καὶ Βήρωνες καλοῦνται, οὔτε τῷ λῃστῇ Οὐριάθῳ καὶ Σερτωρίῳ μετὰ ταῦτα καὶ εἴ τινες ἕτεροι δυναστείας ἐπεθύμησαν μείζονος. Ῥωμαῖοί τε τῷ κατὰ μέρη πρὸς τοὺς Ἴβηρας πολεμεῖν καθ’ ἑκάστην διὰ ταύτην τὴν δυναστείαν πολύν τινα διετέλεσαν χρόνον, ἄλλοτ’ ἄλλους καταστρεφόμενοι τέως ἕως ἅπαντας ὑποχειρίους ἔλαβον διακοσιοστῷ σχεδόν τι ἔτει ἢ μακρότερον. ἐπάνειμι δὲ ἐπὶ τὴν περιήγησιν.", "st": "3.4.5"}, {"sp": "N", "t": "μετὰ τοίνυν Ἄβδηρα ἔστι Καρχηδὼν ἡ νέα, κτίσμα Ἀσδρούβα τοῦ διαδεξαμένου Βάρκαν τὸν Ἀννίβα πατέρα, κρατίστη πολὺ τῶν ταύτῃ πόλεων· καὶ γὰρ ἐρυμνή τ’ ἐστὶ καὶ τείχει κατεσκευασμένῳ καλῶς καὶ λιμέσι καὶ λίμνῃ κεκόσμηται καὶ τοῖς τῶν ἀργυρίων μετάλλοις, περὶ ὧν εἰρήκαμεν· κἀνταῦθα δὲ καὶ ἐν τοῖς πλησίον τόποις πολλὴ ἡ ταριχεία· καὶ ἔστι τοῦτο μέγιστον ἐμπόριον τῶν μὲν ἐκ θαλάττης τοῖς ἐν τῇ μεσογαίᾳ, τῶν δ’ ἐκεῖθεν τοῖς ἔξω πᾶσιν. ἡ δ’ ἐνθένδε μέχρι τοῦ Ἴβηρος παραλία κατὰ μέσον πως τὸ διάστημα ἔχει τὸν Σούκρωνα ποταμὸν καὶ τὴν ἐκβολὴν αὐτοῦ καὶ πόλιν ὁμώνυμον· ῥεῖ δὲ ἐκ τοῦ συνεχοῦς ὄρους τῇ ὑπερκειμένῃ ῥάχει τῆς τε Μαλάκας καὶ τῶν περὶ Καρχηδόνα τόπων, περατὸς πεζῇ, παράλληλος δέ πως τῷ Ἴβηρι, μικρὸν δὲ [ἔλαττον] διέχει τῆς Καρχηδόνος ἢ τοῦ Ἴβηρος. μεταξὺ μὲν οὖν τοῦ Σούκρωνος καὶ τῆς Καρχηδόνος τρία πολίχνια Μασσαλιωτῶν ἔστιν οὐ πολὺ ἄπωθεν τοῦ ποταμοῦ· τούτων δ’ ἐστὶ γνωριμώτατον τὸ Ἡμεροσκοπεῖον ἔχον ἐπὶ τῇ ἄκρᾳ τῆς Ἐφεσίας Ἀρτέμιδος ἱερὸν σφόδρα τιμώμενον, ᾧ ἐχρήσατο Σερτώριος ὁρμητηρίῳ κατὰ θάλατταν· ἐρυμνὸν γάρ ἐστι καὶ λῃστρικόν, κάτοπτον δὲ ἐκ πολλοῦ τοῖς προσπλέουσι, καλεῖται δὲ [καὶ] Διάνιον, οἷον Ἀρτεμίσιον, ἔχον σιδηρεῖα εὐφυῆ πλησίον καὶ νησίδια Πλανησίαν καὶ Πλουμβαρίαν καὶ λιμνοθάλατταν ὑπερκειμένην, ἔχουσαν ἐν κύκλῳ σταδίους τετρακοσίους. εἶθ’ ἡ τοῦ Ἡρακλέους νῆσος ἤδη πρὸς Καρχηδόνι, ἣν καλοῦσι Σκομβραρίαν ἀπὸ τῶν ἁλισκομένων σκόμβρων, ἐξ ὧν τὸ ἄριστον σκευάζεται γάρον· εἴκοσι δὲ διέχει σταδίους καὶ τέτταρας τῆς Καρχηδόνος. πάλιν δ’ ἐπὶ θάτερα τοῦ Σούκρωνος ἰόντι ἐπὶ τὴν ἐκβολὴν τοῦ Ἴβηρος Σάγουντον κτίσμα Ζακυνθίων, ἣν Ἀννίβας κατασκάψας παρὰ τὰ συγκείμενα πρὸς Ῥωμαίους τὸν δεύτερον αὐτοῖς ἐξῆψε πόλεμον πρὸς Καρχηδονίους. πλησίον δὲ πόλεις εἰσὶ Χερρόνησός τε καὶ Ὀλέαστρον καὶ Καρταλίας· ἐπ’ αὐτῇ δὲ τῇ διαβάσει τοῦ Ἴβηρος Δέρτωσσα κατοικία. ῥεῖ δὲ ὁ Ἴβηρ ἀπὸ Καντάβρων ἔχων τὰς ἀρχὰς ἐπὶ μεσημβρίαν διὰ πολλοῦ πεδίου παράλληλος τοῖς Πυρηναίοις ὄρεσι.", "st": "3.4.6"}, {"sp": "N", "t": "μεταξὺ δὲ τῶν τοῦ Ἴβηρος ἐκτροπῶν καὶ τῶν ἄκρων τῆς Πυρήνης, ἐφ’ ὧν ἵδρυται τὰ ἀναθήματα τοῦ Πομπηίου, πρώτη Ταρράκων ἐστὶ πόλις, ἀλίμενος μὲν ἐν κόλπῳ δὲ ἱδρυμένη καὶ κατεσκευασμένη τοῖς ἄλλοις ἱκανῶς καὶ οὐχ ἧττον εὐανδροῦσα νυνὶ τῆς Καρχηδόνος. πρὸς γὰρ τὰς τῶν ἡγεμόνων ἐπιδημίας εὐφυῶς ἔχει, καὶ ἔστιν ὥσπερ μητρόπολις οὐ τῆς ἐντὸς Ἴβηρος μόνον ἀλλὰ καὶ τῆς ἐκτὸς τῆς πολλῆς. αἵ τε Γυμνήσιαι νῆσοι προκείμεναι πλησίον καὶ ἡ Ἔβυσος, ἀξιόλογοι νῆσοι, τὴν θέσιν εὔκαιρον τῆς πόλεως ὑπαγορεύουσιν. Ἐρατοσθένης δὲ καὶ ναύσταθμον ἔχειν φησὶν αὐτήν, οὐδὲ ἀγκυροβολίοις σφόδρα εὐτυχοῦσαν, ὡς ἀντιλέγων εἴρηκεν Ἀρτεμίδωρος.", "st": "3.4.7"}, {"sp": "N", "t": "καὶ ἡ σύμπασα δ’ ἀπὸ στηλῶν σπανίζεται λιμέσι μέχρι δεῦρο, ἐντεῦθεν δ’ ἤδη τὰ ἑξῆς εὐλίμενα καὶ χώρα ἀγαθὴ τῶν τε Λεητανῶν καὶ Λαρτολαιητῶν καὶ ἄλλων τοιούτων μέχρι Ἐμπορίου. αὐτὸ δ’ ἐστὶ Μασσαλιωτῶν κτίσμα, ὅσον τετταράκοντα διέχον τῆς Πυρήνης σταδίους καὶ τῶν μεθορίων τῆς Ἰβηρίας πρὸς τὴν Κελτικήν· καὶ αὕτη δ’ ἐστὶ πᾶσα ἀγαθὴ καὶ εὐλίμενος. ἐνταῦθα δ’ ἔστι καὶ ἡ Ῥόδη πολίχνιον, Ἐμποριτῶν κτίσμα, τινὲς δὲ Ῥοδίων φασί· κἀνταῦθα δὲ καὶ ἐν τῷ Ἐμπορίῳ τὴν Ἄρτεμιν τὴν Ἐφεσίαν τιμῶσιν· ἐροῦμεν δὲ τὴν αἰτίαν ἐν τοῖς περὶ Μασσαλίαν. ᾤκουν δ’ οἱ Ἐμπορῖται πρότερον νησίον τι προκείμενον, ὃ νῦν καλεῖται παλαιὰ πόλις, νῦν δ’ οἰκοῦσιν ἐν τῇ ἠπείρῳ. δίπολις δ’ ἐστὶ τείχει διωρισμένη, πρότερον τῶν Ἰνδικητῶν τινας προσοίκους ἔχουσα, οἳ καίπερ ἰδίᾳ πολιτευόμενοι κοινὸν ὅμως περίβολον ἔχειν ἐβούλοντο πρὸς τοὺς Ἕλληνας ἀσφαλείας χάριν, τῷ χρόνῳ δ’ εἰς ταὐτὸ πολίτευμα συνῆλθον μικτόν τι ἔκ τε βαρβάρων καὶ Ἑλληνικῶν νομίμων, ὅπερ καὶ ἐπ’ ἄλλων πολλῶν συνέβη.", "st": "3.4.8"}, {"sp": "N", "t": "̔ρεῖ δὲ καὶ ποταμὸς πλησίον, ἐκ τῆς Πυρήνης ἔχων τὰς ἀρχάς, ἡ δὲ ἐκβολὴ λιμήν ἐστι τοῖς Ἐμπορίταις. λινουργοὶ δὲ ἱκανῶς οἱ Ἐμπορῖται· χώραν δὲ τὴν μεσόγαιαν ἔχουσι τὴν μὲν ἀγαθὴν τὴν δὲ σπαρτοφόρον τῆς ἀχρηστοτέρας καὶ ἑλείας σχοίνου, καλοῦσι δὲ Ἰουγκάριον πεδίον· τινὲς δὲ καὶ τῶν τῆς Πυρήνης ἄκρων νέμονται [τὰ] μέχρι τῶν ἀναθημάτων τοῦ Πομπηίου, δι’ ὧν βαδίζουσιν εἰς τὴν ἔξω καλουμένην Ἰβηρίαν ἐκ τῆς Ἰταλίας καὶ μάλιστα τὴν Βαιτικήν. αὕτη δ’ ἡ ὁδὸς ποτὲ μὲν πλησιάζει τῇ θαλάττῃ ποτὲ δ’ ἀφέστηκε, καὶ μάλιστα ἐν τοῖς πρὸς ἑσπέραν μέρεσι. φέρεται δὲ ἐπὶ Ταρράκωνα, ἀπὸ τῶν ἀναθημάτων τοῦ Πομπηίου διὰ τοῦ Ἰουγκαρίου πεδίου καὶ Βετέρων καὶ τοῦ Μαραθῶνος καλουμένου πεδίου τῇ Λατίνῃ γλώττῃ, φύοντος πολὺ τὸ μάραθον· ἐκ δὲ τοῦ Ταρράκωνος ἐπὶ τὸν πόρον τοῦ Ἴβηρος κατὰ Δέρτωσσαν πόλιν· ἐντεῦθεν διὰ Σαγούντου καὶ Σαιτάβιος πόλεως ἐνεχθεῖσα κατὰ μικρὸν ἀφίσταται τῆς θαλάττης καὶ συνάπτει τῷ Σπαρταρίῳ ὡς ἂν Σχοινοῦντι καλουμένῳ πεδίῳ· τοῦτο δ’ ἐστὶ μέγα καὶ ἄνυδρον, τὴν σχοινοπλοκικὴν φύον σπάρτον ἐξαγωγὴν ἔχουσαν εἰς πάντα τόπον καὶ μάλιστα εἰς τὴν Ἰταλίαν. πρότερον μὲν οὖν διὰ μέσου τοῦ πεδίου καὶ Ἐγελάστας συνέβαινεν εἶναι τὴν ὁδὸν χαλεπὴν καὶ πολλήν, νυνὶ δὲ ἐπὶ τὰ πρὸς θαλάττῃ μέρη πεποιήκασιν αὐτήν, ἐπιψαύουσαν μόνον τοῦ Σχοινοῦντος, εἰς ταὐτὸ δὲ τείνουσαν τῇ προτέρᾳ, τὰ περὶ Καστλῶνα καὶ Ὀβούλκωνα, δι’ ὧν εἴς τε Κορδύβην καὶ εἰς Γάδειρα ἡ ὁδός, τὰ μέγιστα τῶν ἐμπορίων. διέχει δὲ τῆς Κορδύβης ἡ Ὀβούλκων περὶ τριακοσίους σταδίους. φασὶ δ’ οἱ συγγραφεῖς ἐλθεῖν Καίσαρα ἐκ Ῥώμης ἑπτὰ καὶ εἴκοσιν ἡμέραις εἰς τὴν Ὀβούλκωνα καὶ τὸ στρατόπεδον τὸ ἐνταῦθα, ἡνίκα ἔμελλε συνάπτειν τὸν περὶ τὴν Μοῦνδαν πόλεμον.", "st": "3.4.9"}, {"sp": "N", "t": "̔η μὲν δὴ παραλία πᾶσα ἡ ἀπὸ στηλῶν μέχρι τῆς μεθορίας τῆς Ἰβήρων καὶ Κελτῶν τοιαύτη. ἡ δ’ ὑπερκειμένη μεσόγαια (λέγω δὲ τὴν ἐντὸς τῶν τε Πυρηναίων ὀρῶν καὶ τῆς προσαρκτίου πλευρᾶς μέχρι Ἀστύρων) δυεῖν μάλιστα ὄρεσι διορίζεται. τούτων δὲ τὸ μὲν παράλληλόν ἐστι τῇ Πυρήνῃ, τὴν ἀρχὴν ἀπὸ τῶν Καντάβρων ἔχον, τελευτὴν δ’ ἐπὶ τὴν καθ’ ἡμᾶς θάλατταν· καλοῦσι δὲ τοῦτο Ἰδουβέδαν· ἕτερον δ’ ἀπὸ τοῦ μέσου διῆκον ἐπὶ τὴν δύσιν, ἐκκλῖνον δὲ πρὸς νότον καὶ τὴν ἀπὸ στηλῶν παραλίαν· ὃ κατ’ ἀρχὰς μὲν γεώλοφόν ἐστι καὶ ψιλόν, διέξεισι δὲ τὸ καλούμενον Σπαρτάριον πεδίον, εἶτα συνάπτει τῷ δρυμῷ τῷ ὑπερκειμένῳ τῆς τε Καρχηδονίας καὶ τῶν περὶ τὴν Μάλακαν τόπων· καλεῖται δὲ Ὀροσπέδα. μεταξὺ μὲν δὴ τῆς Πυρήνης καὶ τῆς Ἰδουβέδας ὁ Ἴβηρ ῥεῖ ποταμός, παράλληλος τοῖς ὄρεσιν ἀμφοτέροις, πληρούμενος ἐκ τῶν ἐντεῦθεν καταφερομένων ποταμῶν καὶ τῶν ἄλλων ὑδάτων. ἐπὶ δὲ τῷ Ἴβηρι πόλις ἐστὶ Καισαραυγοῦστα καλουμένη καὶ Κέλσα κατοικία τις ἔχουσα γεφύρας λιθίνης διάβασιν. συνοικεῖται δὲ ὑπὸ πλειόνων ἐθνῶν ἡ χώρα, γνωριμωτάτου δὲ τοῦ τῶν Ἰακκητανῶν λεγομένου. τοῦτο δ’ ἀρξάμενον ἀπὸ τῆς παρωρείας τῆς κατὰ τὴν Πυρήνην εἰς τὰ πεδία πλατύνεται καὶ συνάπτει τοῖς περὶ Ἰλέρδαν καὶ Ὄσκαν χωρίοις, τοῖς τῶν Ἰλεργετῶν οὐ πολὺ ἄπωθεν τοῦ Ἴβηρος. ἐν δὲ ταῖς πόλεσι ταύταις ἐπολέμει τὸ τελευταῖον Σερτώριος καὶ ἐν Καλαγούρι Ὀυασκώνων πόλει καὶ τῆς παραλίας ἐν Ταρράκωνι καὶ ἐν τῷ Ἡμεροσκοπείῳ μετὰ τὴν ἐκ Κελτιβήρων ἔκπτωσιν, ἐτελεύτα δ’ ἐν Ὄσκᾳ. κἀν Ἰλέρδᾳ ὕστερον Ἀφράνιος καὶ Πετρήιος οἱ τοῦ Πομπηίου στρατηγοὶ κατεπολεμήθησαν ὑπὸ Καίσαρος τοῦ θεοῦ. διέχει δὲ ἡ Ἰλέρδα τοῦ μὲν Ἴβηρος ὡς ἐπὶ δύσιν ἰόντι σταδίους ἑκατὸν ἑξήκοντα, Ταρράκωνος δὲ πρὸς νότον περὶ τετρακοσίους ἑξήκοντα, πρὸς ἄρκτον δὲ Ὄσκας πεντακοσίους τετταράκοντα. διὰ τούτων δὲ τῶν μερῶν ἡ ἐκ Ταρράκωνος ἐπὶ τοὺς ἐσχάτους ἐπὶ τῷ ὠκεανῷ Ὀυάσκωνας τοὺς κατὰ Πομπέλωνα καὶ τὴν ἐπ’ αὐτῷ τῷ ὠκεανῷ Οἰασῶνα πόλιν ὁδός ἐστι σταδίων δισχιλίων τετρακοσίων πρὸς αὐτὰ τὰ τῆς Ἀκυιτανίας ὅρια καὶ τῆς Ἰβηρίας. Ἰακκητανοὶ δ’ εἰσὶν ἐν οἷς τότε μὲν Σερτώριος ἐπολέμει πρὸς Πομπήιον, ὕστερον δ’ ὁ τοῦ Πομπηίου υἱὸς Σέξτος πρὸς τοὺς Καίσαρος στρατηγούς. ὑπέρκειται δὲ τῆς Ἰακκητανίας πρὸς ἄρκτον τὸ τῶν Ὀυασκώνων ἔθνος, ἐν ᾧ πόλις Πομπέλων ὡς ἂν Πομπηιόπολις.", "st": "3.4.10"}, {"sp": "N", "t": "αὐτῆς δὲ τῆς Πυρήνης τὸ μὲν Ἰβηρικὸν πλευρὸν εὔδενδρόν ἐστι παντοδαπῆς ὕλης καὶ τῆς ἀειθαλοῦς, τὸ δὲ Κελτικὸν ψιλόν, τὰ δὲ μέσα περιέχει καλῶς οἰκεῖσθαι δυναμένους αὐλῶνας. ἔχουσι δ’ αὐτοὺς Κερρητανοὶ τὸ πλέον τοῦ Ἰβηρικοῦ φύλου, παρ’ οἷς πέρναι διάφοροι συντίθενται ταῖς Κανταβρικαῖς ἐνάμιλλοι, πρόσοδον οὐ μικρὰν τοῖς ἀνθρώποις παρέχουσαι.", "st": "3.4.11"}, {"sp": "N", "t": "̔υπερβαλόντι δὲ τὴν Ἰδουβέδαν ἡ Κελτιβηρία παραχρῆμα πολλὴ καὶ ἀνώμαλος, τὸ μέν [τοι] πλέον αὐτῆς ἐστὶ τραχὺ καὶ ποταμόκλυστον· διὰ γὰρ τούτων ὅ τε Ἄνας φέρεται καὶ ὁ Τάγος καὶ οἱ ἐφεξῆς ποταμοὶ οἱ πλείους οἱ ἐπὶ τὴν ἑσπερίαν θάλατταν καταφερόμενοι, τὴν ἀρχὴν ἔχοντες ἐκ τῆς [Κελτ]ιβηρίας· ὧν ὁ Δούριος φέρεται παρὰ τὴν Νομαντίαν καὶ τὴν Σεργουντίαν, ὁ δὲ Βαῖτις ἐκ τῆς Ὀροσπέδας τὰς ἀρχὰς ἔχων διὰ τῆς Ὠρητανίας εἰς τὴν Βαιτικὴν ῥεῖ. οἰκοῦσι δ’ ἐκ μὲν τῶν πρὸς ἄρκτον μερῶν τοῖς Κελτίβηρσι Βήρωνες Καντάβροις ὅμοροι τοῖς Κονίσκοις, καὶ αὐτοὶ τοῦ Κελτικοῦ στόλου γεγονότες, ὧν ἐστι πόλις Ὀυαρία κατὰ τὴν τοῦ Ἴβηρος διάβασιν κειμένη· συνεχεῖς δ’ εἰσὶ καὶ Βαρδυήταις, οὓς οἱ νῦν Βαρδούλους καλοῦσιν· ἐκ δὲ τοῦ ἑσπερίου τῶν τε Ἀστύρων τινὲς καὶ τῶν Καλλαϊκῶν καὶ Ὀυακκαίων, ἔτι δὲ Ὀυεττώνων καὶ Καρπητανῶν· ἐκ δὲ τῶν νοτίων Ὠρητανοί τε καὶ ὅσοι ἄλλοι τὴν Ὀροσπέδαν οἰκοῦσι Βαστητανῶν τε καὶ Ἐδητανῶν· πρὸς ἕω δὲ Ἰδουβέδα.", "st": "3.4.12"}, {"sp": "N", "t": "αὐτῶν τε τῶν Κελτιβήρων εἰς τέτταρα μέρη διῃρημένων οἱ κράτιστοι μάλιστα πρὸς ἕω εἰσὶ καὶ πρὸς νότον οἱ Ἀρουάκοι, συνάπτοντες Καρπητανοῖς καὶ ταῖς τοῦ Τάγου πηγαῖς· πόλις δ’ αὐτῶν ὀνομαστοτάτη Νομαντία. ἔδειξαν δὲ τὴν ἀρετὴν τῷ Κελτιβηρικῷ πολέμῳ τῷ πρὸς Ῥωμαίους εἰκοσαετεῖ γενομένῳ· πολλὰ γὰρ στρατεύματα σὺν ἡγεμόσιν ἐφθάρη, τὸ δὲ τελευταῖον οἱ Νομαντῖνοι πολιορκούμενοι ἀπεκαρτέρησαν πλὴν ὀλίγων τῶν ἐνδόντων τὸ τεῖχος. καὶ οἱ Λούσωνες δὲ ἑῷοί εἰσι, συνάπτοντες καὶ αὐτοὶ ταῖς τοῦ Τάγου πηγαῖς. τῶν δ’ Ἀρουάκων ἐστὶ καὶ Σεγήδα πόλις καὶ Παλλαντία. διέχει δὲ Νομαντία τῆς Καισαραυγούστας, ἣν ἔφαμεν ἐπὶ τῷ Ἴβηρι ἱδρῦσθαι, σταδίους ἐπὶ ὀκτακοσίους. καὶ Σεγοβρίγα δ’ ἐστὶ τῶν Κελτιβήρων πόλις καὶ Βίλβιλις, περὶ ἃς Μέτελλος καὶ Σερτώριος ἐπολέμησαν. Πολύβιος δὲ τὰ τῶν Ὀυακκαίων καὶ τῶν Κελτιβήρων ἔθνη καὶ χωρία διεξιὼν συλλέγει ταῖς ἄλλαις πόλεσι καὶ Σεγεσάμαν καὶ Ἰντερκατίαν. φησὶ δὲ Ποσειδώνιος Μάρκον Μάρκελλον πράξασθαι φόρον ἐκ τῆς Κελτιβηρίας τάλαντα ἑξακόσια, ἐξ οὗ τεκμαίρεσθαι πάρεστιν ὅτι καὶ πολλοὶ ἦσαν οἱ Κελτίβηρες καὶ χρημάτων εὐποροῦντες, καίπερ οἰκοῦντες χώραν παράλυπρον. Πολυβίου δ’ εἰπόντος τριακοσίας αὐτῶν καταλῦσαι πόλεις Τιβέριον Γράκχον, κωμῳδῶν φησι τοῦτο τῷ Γράκχῳ χαρίσασθαι τὸν ἄνδρα, τοὺς πύργους καλοῦντα πόλεις, ὥσπερ ἐν ταῖς θριαμβικαῖς πομπαῖς. καὶ ἴσως οὐκ ἄπιστον τοῦτο λέγει· καὶ γὰρ οἱ στρατηγοὶ καὶ οἱ συγγραφεῖς ῥᾳδίως ἐπὶ τοῦτο φέρονται τὸ ψεῦσμα καλλωπίζοντες τὰς πράξεις, ἐπεὶ καὶ οἱ φάσκοντες πλείους ἢ χιλίας τὰς τῶν Ἰβήρων ὑπάρξαι πόλεις ἐπὶ τοῦτο φέρεσθαί μοι δοκοῦσι, τὰς μεγάλας κώμας πόλεις ὀνομάζοντες. οὔτε γὰρ ἡ τῆς χώρας φύσις πόλεων ἐπιδεκτικὴ πολλῶν ἐστι διὰ τὴν λυπρότητα ἢ διὰ τὸν ἐκτοπισμὸν καὶ τὸ ἀνήμερον, οὔθ’ οἱ βίοι καὶ πράξεις αὐτῶν (ἔξω τῶν κατὰ τὴν παραλίαν τὴν καθ’ ἡμᾶς) ὑπαγορεύουσι τοιοῦτον οὐδέν· ἄγριοι γὰρ οἱ κατὰ κώμας οἰκοῦντες· τοιοῦτοι δ’ οἱ πολλοὶ τῶν Ἰβήρων· αἱ δὲ πόλεις ἡμεροῦσιν οὐδ’ αὗται ῥᾳδίως, ὅταν πλεονάζῃ τὸ τὰς ὕλας ἐπὶ κακῷ τῶν πλησίον οἰκοῦν.", "st": "3.4.13"}, {"sp": "N", "t": "μετὰ δὲ τοὺς Κελτίβηρας πρὸς νότον εἰσὶν οἱ τὸ ὄρος οἰκοῦντες τὴν Ὀροσπέδαν καὶ τὴν περὶ τὸν Σούκρωνα χώραν Ἐδητανοί, μέχρι Καρχηδόνος, καὶ Βαστητανοὶ καὶ Ὠρητανοί, σχεδὸν δέ τι καὶ μέχρι Μαλάκας.", "st": "3.4.14"}, {"sp": "N", "t": "πελτασταὶ δ’ ἅπαντες, ὡς εἰπεῖν, ὑπῆρξαν οἱ Ἴβηρες καὶ κοῦφοι κατὰ τὸν ὁπλισμὸν διὰ τὰς λῃστείας, οἵους ἔφαμεν τοὺς Λυσιτανούς, ἀκοντίῳ καὶ σφενδόνῃ καὶ μαχαίρα χρώμενοι· ταῖς δὲ πεζαῖς δυνάμεσι παρεμέμικτο καὶ ἱππεία, δεδιδαγμένων ἵππων ὀρειβατεῖν καὶ κατοκλάζεσθαι ῥᾳδίως ἀπὸ προστάγματος, ὅτε τούτου δέοι. φέρει δ’ ἡ Ἰβηρία δορκάδας πολλὰς καὶ ἵππους ἀγρίους. ἔστι δ’ ὅπου καὶ αἱ λίμναι πληθύουσιν ὀρνέοις. εἰσὶ δὲ κύκνοι καὶ τὰ παραπλήσια, πολλαὶ δὲ καὶ ὠτίδες· κάστορας φέρουσι μὲν οἱ ποταμοί, τὸ δὲ καστόριον οὐκ ἔχει τὴν αὐτὴν δύναμιν τῷ Ποντικῷ· ἴδιον γὰρ τῷ Ποντικῷ πάρεστι τὸ φαρμακῶδες, καθάπερ ἄλλοις πολλοῖς. ἐπεί, φησὶν ὁ Ποσειδώνιος, καὶ ὁ Κύπριος χαλκὸς μόνος φέρει τὴν καδμείαν λίθον καὶ τὸ χαλκανθὲς καὶ τὸ σπόδιον. ἴδιον δ’ εἴρηκεν Ἰβηρίᾳ ὁ Ποσειδώνιος καὶ τὸ τὰς κορώνας μελαίνας εἶναι καὶ τὸ τοὺς ἵππους τῶν Κελτιβήρων ὑποψάρους ὄντας, ἐπειδὰν εἰς τὴν ἔξω μεταχθῶσιν Ἰβηρίαν, μεταβάλλειν τὴν χρόαν. ἐοικέναι δὲ τοῖς Παρθικοῖς· καὶ γὰρ ταχεῖς εἶναι καὶ εὐδρόμους μᾶλλον τῶν ἄλλων.", "st": "3.4.15"}, {"sp": "N", "t": "καὶ τῶν ῥιζῶν τῶν εἰς βαφὴν χρησίμων πλῆθος. ἐλαίας δὲ πέρι καὶ ἀμπέλου καὶ συκῆς καὶ τῶν παραπλησίων φυτῶν ἡ καθ’ ἡμᾶς Ἰβηρικὴ παραλία πάντων εὐπορεῖ, συχνὴ δὲ καὶ … τῶν ἐκτὸς ἡ μὲν παρωκεανῖτις ἡ πρόσβορρος ἀμοιρεῖ διὰ τὰ ψύχη, ἡ δ’ ἄλλη τὸ πλέον διὰ τὴν ὀλιγωρίαν τῶν ἀνθρώπων καὶ τὸ μὴ πρὸς διαγωγὴν ἀλλὰ μᾶλλον πρὸς ἀνάγκην καὶ ὁρμὴν θηριώδη μετὰ ἔθους φαύλου ζῆν· εἰ μή τις οἴεται πρὸς διαγωγὴν ζῆν τοὺς οὔρῳ λουομένους ἐν δεξαμεναῖς παλαιουμένῳ, καὶ τοὺς ὀδόντας σμηχομένους καὶ αὐτοὺς καὶ τὰς γυναῖκας αὐτῶν, καθάπερ τοὺς Καντάβρους φασὶ καὶ τοὺς ὁμόρους αὐτοῖς. καὶ τοῦτό τε καὶ τὸ χαμευνεῖν κοινόν ἐστι τοῖς Ἴβηρσι πρὸς τοὺς Κελτούς. ἔνιοι δὲ τοὺς Καλλαϊκοὺς ἀθέους φασί, τοὺς δὲ Κελτίβηρας καὶ τοὺς προσβόρρους τῶν ὁμόρων αὐτοῖς ἀνωνύμῳ τινὶ θεῷ [θύειν] ταῖς πανσελήνοις νύκτωρ πρὸ τῶν πυλῶν, πανοικίους τε χορεύειν καὶ παννυχίζειν. τοὺς δὲ Ὀυέττωνας, ὅτε πρῶτον εἰς τὸ τῶν Ῥωμαίων παρῆλθον στρατόπεδον, ἰδόντας τῶν ταξιαρχῶν τινας ἀνακάμπτοντας ἐν ταῖς ὁδοῖς περιπάτου χάριν, μανίαν ὑπολαβόντας ἡγεῖσθαι τὴν ὁδὸν αὐτοῖς ἐπὶ τὰς σκηνάς, ὡς δέον ἢ μένειν καθ’ ἡσυχίαν ἱδρυθέντας ἢ μάχεσθαι.", "st": "3.4.16"}, {"sp": "N", "t": "τῆς δὲ βαρβαρικῆς ἰδέας καὶ τὸν τῶν γυναικῶν ἐνίων κόσμον θείη τις ἄν, ὃν εἴρηκεν Ἀρτεμίδωρος· ὅπου μὲν γὰρ περιτραχήλια σιδηρᾶ φορεῖν αὐτάς φησιν ἔχοντα κόρακας καμπτομένους ὑπὲρ κορυφῆς καὶ προπίπτοντας πρὸ τοῦ μετώπου πολύ, κατὰ τούτων δὲ τῶν κοράκων, ὅτε βούλονται, κατασπᾶν τὸ κάλυμμα ὥστε ἐμπετασθὲν σκιάδιον τῷ προσώπῳ παρέχειν, καὶ νομίζειν κόσμον· ὅπου δὲ τυμπάνιον περικεῖσθαι πρὸς μὲν τῷ ἰνίῳ περιφερὲς καὶ σφίγγον τὴν κεφαλὴν μέχρι τῶν παρωτίδων, εἰς ὕψος δὲ καὶ πλάτος ἐξυπτιασμένον κατ’ ὀλίγον· ἄλλας δὲ τὰ προκόμια ψιλοῦν ἐπὶ τοσοῦτον ὥστ’ ἀποστίλβειν τοῦ μετώπου μᾶλλον· τὰς δ’ ὅσον ποδιαῖον τὸ ὕψος ἐπιθεμένας στυλίσκον περιπλέκειν αὐτῷ τὴν χαίτην, εἶτα καλύπτρᾳ μελαίνῃ περιστέλλειν. πρὸς δὲ τῇ ἀηθείᾳ τῇ τοιαύτῃ πολλὰ καὶ ἑώραται καὶ μεμύθευται περὶ πάντων κοινῇ τῶν Ἰβηρικῶν ἐθνῶν, διαφερόντως δὲ τῶν προσβόρρων, οὐ μόνον τὰ πρὸς ἀνδρείαν ἀλλὰ καὶ τὰ πρὸς ὠμότητα καὶ ἀπόνοιαν θηριώδη. καὶ γὰρ τέκνα μητέρες ἔκτειναν πρὶν ἁλῶναι κατὰ τὸν πόλεμον τὸν ἐν Καντάβροις, καὶ παιδίον δὲ δεδεμένων αἰχμαλώτων τῶν γονέων καὶ ἀδελφῶν ἔκτεινε πάντας κελεύσαντος τοῦ πατρὸς σιδήρου κυριεῦσαν, γυνὴ δὲ τοὺς συναλόντας. κληθεὶς δέ τις εἰς μεθυσκομένους ἔβαλεν αὑτὸν εἰς πυράν. κοινὰ δὲ καὶ ταῦτα πρὸς τὰ Κελτικὰ ἔθνη καὶ τὰ Θρᾴκια καὶ Σκυθικά, κοινὰ δὲ καὶ [τὰ] πρὸς ἀνδρείαν τήν τε τῶν ἀνδρῶν καὶ τὴν τῶν γυναικῶν. γεωργοῦσιν αὗται τεκοῦσαί τε διακονοῦσι τοῖς ἀνδράσιν ἐκείνους ἀνθ’ ἑαυτῶν κατακλίνασαι· ἔν τε τοῖς ἔργοις πολλάκις αὐταὶ καὶ λούουσι καὶ σπαργανοῦσιν ἀποκλίνασαι πρός τι ῥεῖθρον. ἐν δὲ τῇ Λιγυστικῇ φησὶν ὁ Ποσειδώνιος διηγήσασθαι τὸν ξένον ἑαυτῷ Χαρμόλεων Μασσαλιώτην ἄνδρα, ὅτι μισθώσαιτο ἄνδρας ὁμοῦ καὶ γυναῖκας ἐπὶ σκαφητόν, ὠδίνασα δὲ μία τῶν γυναικῶν ἀπέλθοι ἀπὸ τοῦ ἔργου πλησίον, τεκοῦσα δ’ ἐπανέλθοι ἐπὶ τοὖργον αὐτίκα, ὅπως μὴ ἀπολέσειε τὸν μισθόν· αὐτὸς δὲ ἐπιπόνως ἰδὼν ἐργαζομένην, οὐκ εἰδὼς τὴν αἰτίαν πρότερον ὀψὲ μάθοι καὶ ἀφείη δοὺς τὸν μισθόν· ἡ δ’ ἐκκομίσασα τὸ νήπιον πρός τι κρηνίον, λούσασα καὶ σπαργανώσασα οἷς εἶχε διασώσειεν οἴκαδε.", "st": "3.4.17"}, {"sp": "N", "t": "οὐκ ἴδιον δὲ τῶν Ἰβήρων οὐδὲ τοῦτο σύνδυο ἐφ’ ἵππων κομίζεσθαι, κατὰ δὲ τὰς μάχας τὸν ἕτερον πεζὸν ἀγωνίζεσθαι. οὐδὲ τὸ τῶν μυῶν πλῆθος ἴδιον, ἀφ’ οὗ καὶ λοιμικαὶ νόσοι πολλάκις ἠκολούθησαν. συνέβη δ’ ἐν τῇ Κανταβρίᾳ τοῦτο τοῖς Ῥωμαίοις, ὥστε καὶ μισθοὺς ἄρνυσθαι μυοθηροῦντας πρὸς μέτρον ἀποδειχθέν, [καὶ] διεσώζοντο μόλις· προσελάμβανε δὲ καὶ ἄλλων σπάνις καὶ σίτου· ἐπεσιτίζοντο δὲ ἐκ τῆς Ἀκυιτανίας χαλεπῶς διὰ τὰς δυσχωρίας. τῆς δ’ ἀπονοίας καὶ τοῦτο λέγεται τῆς Καντάβρων, ὅτι ἁλόντες τινὲς ἀναπεπηγότες ἐπὶ τῶν σταυρῶν ἐπαιάνιζον. τὰ μὲν οὖν τοιαῦτα τῶν ἠθῶν ἀγριότητός τινος παραδείγματ’ ἂν εἴη· τὰ δὲ τοιαῦτα ἧττον μὲν ἴσως πολιτικά, οὐ θηριώδη δέ, οἷον τὸ παρὰ τοῖς Καντάβροις τοὺς ἄνδρας διδόναι ταῖς γυναιξὶ προῖκα [καὶ] τὸ τὰς θυγατέρας κληρονόμους ἀπολείπεσθαι τούς τε ἀδελφοὺς ὑπὸ τούτων ἐκδίδοσθαι γυναιξίν· ἔχει γάρ τινα γυναικοκρατίαν· τοῦτο δ’ οὐ πάνυ πολιτικόν. Ἰβηρικὸν δὲ καὶ τὸ ἐν ἔθει [εἶναι] παρατίθεσθαι τοξικὸν ὃ συντιθέασιν ἐκ βοτάνης σελίνῳ προσομοίας ἄπονον, ὥστ’ ἔχειν ἐν ἑτοίμῳ πρὸς τὰ ἀβούλητα, καὶ τὸ κατασπένδειν αὑτοὺς οἷς ἂν προσθῶνται, ὥστε ἀποθνήσκειν αὐτοὺς ὑπὲρ αὐτῶν.", "st": "3.4.18"}, {"sp": "N", "t": "τινὲς μὲν οὖν εἰς τέτταρα μέρη διῃρῆσθαί φασι τὴν χώραν ταύτην, καθάπερ εἴπομεν, ἄλλοι δὲ πενταμερῆ λέγουσιν. οὐκ ἔστι δὲ τἀκριβὲς ἐν τούτοις ἀποδιδόναι διὰ τὰς μεταβολὰς καὶ τὴν ἀδοξίαν τῶν τόπων. ἐν γὰρ τοῖς γνωρίμοις καὶ ἐνδόξοις αἵ τε μεταναστάσεις γνώριμοι καὶ οἱ μερισμοὶ τῆς χώρας καὶ αἱ μεταβολαὶ τῶν ὀνομάτων καὶ εἴ τι ἄλλο παραπλήσιον· θρυλεῖται γὰρ ὑπὸ πολλῶν καὶ μάλιστα τῶν Ἑλλήνων. ὅσα δὲ καὶ βάρβαρα καὶ ἐκτετοπισμένα καὶ μικρόχωρα καὶ διεσπασμένα, τούτων ὑπομνήματα οὔτ’ ἀσφαλῆ ἐστιν οὔτε πολλά· ὅσα δὲ δὴ πόρρω τῶν Ἑλλήνων ἐπιτείνει τὴν ἄγνοιαν. οἱ δὲ τῶν Ῥωμαίων συγγραφεῖς μιμοῦνται μὲν τοὺς Ἕλληνας, ἀλλ’ οὐκ ἐπὶ πολύ· καὶ γὰρ ἃ λέγουσι παρὰ τῶν Ἑλλήνων μεταφέρουσιν, ἐξ ἑαυτῶν δ’ οὐ πολὺ μὲν προσφέρονται τὸ φιλείδημον ὥσθ’, ὁπόταν ἔλλειψις γένηται παρ’ ἐκείνων, οὐκ ἔστι πολὺ τὸ ἀναπληρούμενον ὑπὸ τῶν ἑτέρων, ἄλλως τε καὶ τῶν ὀνομάτων, ὅσα ἐνδοξότατα, τῶν πλείστων ὄντων Ἑλληνικῶν· ἐπεὶ καὶ Ἰβηρίαν ὑπὸ μὲν τῶν προτέρων καλεῖσθαι πᾶσαν τὴν ἔξω τοῦ Ῥοδανοῦ καὶ τοῦ ἰσθμοῦ τοῦ ὑπὸ τῶν Γαλατικῶν κόλπων σφιγγομένου, οἱ δὲ νῦν ὅριον αὐτῆς τίθενται τὴν Πυρήνην, συνωνύμως τε τὴν αὐτὴν Ἰβηρίαν λέγουσι καὶ Ἱσπανίαν· [ἄλλοι δ’ Ἰβηρίαν] μόνην ἐκάλουν τὴν ἐντὸς τοῦ Ἴβηρος· οἱ δ’ ἔτι πρότερον αὐτοὺς τούτους Ἰγλῆτας, οὐ πολλὴν χώραν νεμομένους, ὥς φησιν Ἀσκληπιάδης ὁ Μυρλεανός. Ῥωμαῖοι δὲ τὴν σύμπασαν καλέσαντες συνωνύμως Ἰβηρίαν τε καὶ Ἱσπανίαν τὸ μὲν αὐτῆς μέρος εἶπον τὴν ἐκτὸς τὸ δὲ ἕτερον τὴν ἐντός· ἄλλοτε δ’ ἄλλως διαιροῦσι πρὸς τοὺς καιροὺς πολιτευόμενοι.", "st": "3.4.19"}, {"sp": "N", "t": "νυνὶ δὲ τῶν ἐπαρχιῶν τῶν μὲν ἀποδειχθεισῶν τῷ δήμῳ τε καὶ τῇ συγκλήτῳ τῶν δὲ τῷ ἡγεμόνι τῶν Ῥωμαίων, ἡ μὲν Βαιτικὴ πρόσκειται τῷ δήμῳ, καὶ πέμπεται στρατηγὸς ἐπ’ αὐτὴν ἔχων ταμίαν τε καὶ πρεσβευτήν· ὅριον δ’ αὐτῆς τεθείκασι πρὸς ἠῶ πλησίον Καστλῶνος. ἡ δὲ λοιπὴ Καίσαρός ἐστι· πέμπονται δ’ ὑπ’ αὐτοῦ δύο πρεσβευταί, στρατηγικός τε καὶ ὑπατικός, ὁ μὲν στρατηγικὸς ἔχων σὺν αὑτῷ πρεσβευτήν, δικαιοδοτήσων Λυσιτανοῖς τοῖς παρακειμένοις τῇ Βαιτικῇ καὶ διατείνουσι μέχρι τοῦ Δουρίου ποταμοῦ καὶ τῶν ἐκβολῶν αὐτοῦ· καλοῦσι γὰρ οὕτω τὴν χώραν ταύτην ἰδίως ἐν τῷ παρόντι. ἐνταῦθα δ’ ἔστι καὶ ἡ Αὐγοῦστα Ἠμερίτα. ἡ [δὲ] λοιπὴ (αὕτη δ’ ἐστὶν ἡ πλείστη τῆς Ἰβηρίας) ὑπὸ τῷ ὑπατικῷ ἡγεμόνι στρατιάν τε ἔχοντι ἀξιόλογον τριῶν που ταγμάτων καὶ πρεσβευτὰς τρεῖς, ὧν ὁ μὲν δύο ἔχων τάγματα παραφρουρεῖ τὴν πέραν τοῦ Δουρίου πᾶσαν ἐπὶ τὰς ἄρκτους, ἣν οἱ μὲν πρότερον Λυσιτανοὺς ἔλεγον οἱ δὲ νῦν Καλλαϊκοὺς καλοῦσι· συνάπτει δὲ τούτοις τὰ προσάρκτια μέρη μετὰ τῶν Ἀστύρων καὶ τῶν Καντάβρων. ῥεῖ δὲ διὰ τῶν Ἀστύρων Μέλσος ποταμός, καὶ μικρὸν ἀπωτέρω πόλις Νοῖγα, καὶ πλησίον ἐκ τοῦ ὠκεανοῦ ἀνάχυσις ὁρίζουσα τοὺς Ἄστυρας ἀπὸ τῶν Καντάβρων· τὴν δ’ ἑξῆς παρόρειον μέχρι Πυρήνης ὁ δεύτερος τῶν πρεσβευτῶν μετὰ τοῦ ἑτέρου τάγματος ἐπισκοπεῖ. ὁ δὲ τρίτος τὴν μεσόγαιαν, συνέχει δὲ τὰ τῶν [τογάτων] ἤδη λεγομένων ὡς ἂν εἰρηνικῶν καὶ εἰς τὸ ἥμερον καὶ τὸν Ἰταλικὸν τύπον μετακειμένων ἐν τῇ τηβεννικῇ ἐσθῆτι. οὗτοι δ’ εἰσὶν οἱ Κελτίβηρες καὶ οἱ τοῦ Ἴβηρος πλησίον ἑκατέρωθεν οἰκοῦντες μέχρι τῶν πρὸς θαλάττῃ μερῶν. αὐτὸς δὲ ὁ ἡγεμὼν διαχειμάζει μὲν ἐν τοῖς ἐπιθαλαττιαίοις μέρεσι καὶ μάλιστα τῇ Καρχηδόνι καὶ τῇ Ταρράκωνι δικαιοδοτῶν, θέρους δὲ περίεισιν ἐφορῶν ἀεί τινα τῶν δεομένων ἐπανορθώσεως. εἰσὶ δὲ καὶ ἐπίτροποι τοῦ Καίσαρος, ἱππικοὶ ἄνδρες, οἱ διανέμοντες τὰ χρήματα τοῖς στρατιώταις εἰς τὴν διοίκησιν τοῦ βίου.", "st": "3.4.20"}, {"sp": "N", "t": "τῶν δὲ προκειμένων νήσων τῆς Ἰβηρίας τὰς μὲν Πιτυούσσας δύο καὶ τὰς Γυμνησίας δύο (καλοῦσι καὶ Βαλιαρίδας) προκεῖσθαι συμβαίνει τῆς μεταξὺ Ταρράκωνος καὶ Σούκρωνος παραλίας, ἐφ’ ἧς ἵδρυται τὸ Σάγουντον· εἰσὶ δὲ καὶ πελάγιαι, * μᾶλλον αἱ Πιτυοῦσσαι καὶ πρὸς ἑσπέραν κεκλιμέναι τῶν Γυμνησίων. καλεῖται δ’ αὐτῶν ἡ μὲν Ἔβουσος πόλιν ἔχουσα ὁμώνυμον· κύκλος δὲ τῆς νήσου τετρακόσιοι στάδιοι, παρώμαλος τὸ πλάτος καὶ τὸ μῆκος· ἡ δὲ Ὀφιοῦσσα ἔρημος καὶ πολὺ ἐλάττων ταύτης πλησίον κειμένη. τῶν δὲ Γυμνησίων ἡ μὲν μείζων ἔχει δύο πόλεις, Πάλμαν καὶ Πολεντίαν, τὴν μὲν πρὸς ἕω κειμένην τὴν Πολεντίαν, τὴν δ’ ἑτέραν πρὸς δύσιν. μῆκος δὲ τῆς νήσου μικρὸν ἀπολεῖπον τῶν ἑξακοσίων σταδίων, πλάτος δὲ διακοσίων· Ἀρτεμίδωρος δὲ διπλάσιον εἴρηκε καὶ τὸ πλάτος καὶ τὸ μῆκος. ἡ δ’ ἐλάττων ὡς [διακοσίους] ἑβδομήκοντα τῆς Πολεντίας διέχει σταδίους· κατὰ μέγεθος μὲν οὖν πολὺ τῆς μείζονος ἀπολείπεται, κατὰ δὲ τὴν ἀρετὴν οὐδὲν αὐτῆς χείρων ἐστίν· ἄμφω γὰρ εὐδαίμονες καὶ εὐλίμενοι, χοιραδώδεις δὲ κατὰ τὰ στόματα, ὥστε δεῖν προσοχῆς τοῖς εἰσπλέουσι. διὰ δὲ τὴν ἀρετὴν τῶν τόπων καὶ οἱ κατοικοῦντες εἰρηναῖοι, καθάπερ καὶ οἱ κατὰ τὴν Ἔβουσον. κακούργων δέ τινων ὀλίγων κοινωνίας συστησαμένων πρὸς τοὺς ἐν τοῖς πελάγεσι λῃστάς, διεβλήθησαν ἅπαντες, καὶ διέβη Μέτελλος ἐπ’ αὐτοὺς ὁ Βαλιαρικὸς προσαγορευθείς, ὅστις καὶ τὰς πόλεις ἔκτισε. διὰ δὲ τὴν αὐτὴν ἀρετὴν ἐπιβουλευόμενοι, καίπερ εἰρηναῖοι ὄντες, ὅμως σφενδονῆται ἄριστοι λέγονται· καὶ τοῦτ’ ἤσκησαν, ὥς φασι, διαφερόντως ἐξ ὅτου Φοίνικες κατέσχον τὰς νήσους. οὗτοι δὲ καὶ ἐνδῦσαι λέγονται πρῶτοι τοὺς ἀνθρώπους χιτῶνας πλατυσήμους … ἄζωστοι δ’ ἐπὶ τοὺς ἀγῶνας ἐξῄεσαν, αἰγίδα περὶ τῇ χειρὶ ἔχοντες * ἢ πεπυρακτωμένον ἀκόντιον, σπάνιον δὲ καὶ λελογχωμένον σιδήρῳ μικρῷ. σφενδόνας δὲ περὶ τῇ κεφαλῇ τρεῖς μελαγκρανίνας ἢ τριχίνας ἢ νευρίνας, τὴν μὲν μακρόκωλον πρὸς τὰς μακροβολίας, τὴν δὲ βραχύκωλον πρὸς τὰς ἐν βραχεῖ βολάς, τὴν δὲ μέσην πρὸς τὰς μέσας. ἠσκοῦντο δ’ ἐκ παίδων οὕτως ταῖς σφενδόναις ὥστ’ οὐδ’ ἄλλως τοῖς παισὶν ἄρτον ἐδίδοσαν ἄνευ τοῦ τῇ σφενδόνῃ τυχεῖν. διόπερ ὁ Μέτελλος προσπλέων πρὸς τὰς νήσους δέρρεις ἔτεινεν ὑπὲρ τῶν καταστρωμάτων σκέπην πρὸς τὰς σφενδόνας. εἰσήγαγε δὲ ἐποίκους τρισχιλίους τῶν ἐκ τῆς Ἰβηρίας Ῥωμαίων.", "st": "3.5.1"}, {"sp": "N", "t": "πρὸς δὲ τῇ εὐκαρπίᾳ τῆς γῆς καὶ τὸ μηδὲν τῶν σινομένων θηρίων εὑρίσκεσθαι ῥᾳδίως ἐνταῦθα πρόσεστιν· οὐδὲ γὰρ τοὺς λαγιδεῖς ἐπιχωρίους εἶναί φασιν, ἀλλὰ κομισθέντων ἐκ τῆς περαίας ὑπό τινος ἄρρενος καὶ θηλείας γενέσθαι τὴν ἐπιγονήν, ἣ τοσαύτη κατ’ ἀρχὰς ὑπῆρχεν ὥστε καὶ οἴκους ἀνατρέπειν ἐκ τῆς ὑπονομῆς καὶ δένδρα, καὶ ἐπὶ τοὺς Ῥωμαίους, ὥσπερ εἶπον, ἀναγκασθῆναι καταφυγεῖν τοὺς ἀνθρώπους. νῦν μέντοι τὸ εὐμεταχείριστον τῆς θήρας ἐπικρατεῖν οὐκ ἐᾷ τὴν βλάβην, ἀλλὰ λυσιτελῶς οἱ ἔχοντες καρποῦνται τὴν γῆν.", "st": "3.5.2"}, {"sp": "N", "t": "αὗται μὲν οὖν ἐντὸς στηλῶν τῶν Ἡρακλείων καλουμένων. πρὸς αὐταῖς δὲ δύο νησίδια, ὧν θάτερον Ἥρας νῆσον ὀνομάζουσι· καὶ δή τινες καὶ ταύτας στήλας καλοῦσιν. ἔξω δὲ στηλῶν τὰ Γάδειρα, περὶ ὧν τοσοῦτον μόνον εἰρήκαμεν ὅτι τῆς Κάλπης διέχει περὶ ἑπτακοσίους καὶ πεντήκοντα σταδίους, τῆς δὲ ἐκβολῆς τοῦ Βαίτιδος πλησίον ἵδρυται· πλείους δ’ εἰσὶ λόγοι περὶ αὐτῆς. οὗτοι γάρ εἰσιν οἱ ἄνδρες οἱ τὰ πλεῖστα καὶ μέγιστα ναυκλήρια στέλλοντες εἴς τε τὴν καθ’ ἡμᾶς θάλατταν καὶ τὴν ἐκτός, οὔτε μεγάλην οἰκοῦντες νῆσον οὔτε τῆς περαίας νεμόμενοι πολλὴν οὔτ’ ἄλλων εὐποροῦντες νήσων, ἀλλὰ πλέον οἰκοῦντες τὴν θάλατταν, ὀλίγοι δ’ οἰκουροῦντες ἢ ἐν Ῥώμῃ διατρίβοντες. ἐπεὶ πλήθει γε οὐδεμιᾶς ἂν ἀπολείπεσθαι δόξειε τῶν ἔξω Ῥώμης πόλεων· ἤκουσα γοῦν ἐν μιᾷ τῶν καθ’ ἡμᾶς τιμήσεων πεντακοσίους ἄνδρας τιμηθέντας ἱππικοὺς Γαδιτανούς, ὅσους οὐδένας οὐδὲ τῶν Ἰταλιωτῶν πλὴν τῶν Παταουίνων. τοσοῦτοι δ’ ὄντες νῆσον ἔχουσιν οὐ πολὺ μείζονα τῶν ἑκατὸν σταδίων τὸ μῆκος, πλάτος δ’ ἔσθ’ ὅπου καὶ σταδιαῖον. πόλιν δὲ κατ’ ἀρχὰς μὲν ᾤκουν παντάπασι μικράν, προσέκτισε δ’ αὐτοῖς Βάλβος Γαδιτανὸς ὁ θριαμβεύσας ἄλλην ἣν νέαν καλοῦσι, τὴν δ’ ἐξ ἀμφοῖν Διδύμην, οὐ πλειόνων εἴκοσι σταδίων οὖσαν τὴν περίμετρον, οὐδὲ ταύτην στενοχωρουμένην· ὀλίγοι γὰρ οἰκουροῦσιν ἐν αὐτῇ διὰ τὸ πάντας θαλαττεύειν τὸ πλέον, τοὺς δὲ καὶ τὴν περαίαν οἰκεῖν, καὶ μάλιστα τὴν ἐπὶ τῆς προκειμένης νησῖδος διὰ τὴν εὐφυΐαν, ἣν ὥσπερ ἀντίπολιν πεποιήκασι τῇ Διδύμῃ χαίροντες τῷ τόπῳ. ὀλίγοι δὲ κατὰ σύγκρισιν καὶ ταύτην οἰκοῦσι καὶ τὸ ἐπίνειον, ὃ κατεσκεύασεν αὐτοῖς Βάλβος ἐν τῇ περαίᾳ τῆς ἠπείρου. κεῖται δ’ ἐπὶ τῶν ἑσπερίων τῆς νήσου μερῶν ἡ πόλις, προσεχὲς δ’ αὐτῇ τελευταῖόν ἐστι τὸ Κρόνιον πρὸς τῇ νησῖδι· τὸ δ’ Ἡράκλειον ἐπὶ θάτερα τέτραπται τὰ πρὸς ἕω, καθ’ ὃ δὴ μάλιστα τῇ ἠπείρῳ τυγχάνει συνάπτουσα ἡ νῆσος ὅσον σταδιαῖον πορθμὸν ἀπολείπουσα. καὶ λέγουσι μὲν διέχειν τῆς πόλεως δώδεκα μίλια τὸ ἱερόν, ἴσον ποιοῦντες τὸν τῶν ἄθλων καὶ τὸν τῶν μιλίων ἀριθμόν· ἔστι δὲ μεῖζον καὶ σχεδόν τι τοσοῦτον ὅσον ἐστὶ τὸ τοῦ μήκους τῆς νήσου· μῆκος δ’ ἐστὶ τῆς νήσου τὸ ἀπὸ τῆς δύσεως ἐπὶ τὴν ἀνατολήν.", "st": "3.5.3"}, {"sp": "N", "t": "Ἐρύθειαν δὲ τὰ Γάδειρα ἔοικε λέγειν ὁ Φερεκύδης, ἐν ᾗ τὰ περὶ τὸν Γηρυόνην μυθεύουσιν, ἄλλοι δὲ τὴν παραβεβλημένην ταύτῃ τῇ πόλει νῆσον πορθμῷ σταδιαίῳ διειργομένην, τὸ εὔβοτον ὁρῶντες, ὅτι τῶν νεμομένων αὐτόθι προβάτων τὸ γάλα ὀρὸν οὐ ποιεῖ. τυροποιοῦσί τε πολλῷ ὕδατι μίξαντες διὰ τὴν πιότητα, ἐν πεντήκοντά τε ἡμέραις πνίγεται τὸ ζῷον, εἰ μή τις ἀποσχάζοι τι τοῦ αἵματος. ξηρὰ δέ ἐστιν ἣν νέμονται βοτάνην, ἀλλὰ πιαίνει σφόδρα· τεκμαίρονται δ’ ἐκ τού[του] πεπλάσθαι τὸν μῦθον τὸν περὶ τὰ βουκόλια τοῦ Γηρυόνου· … κοινῇ μέντοι συνῴκισται πᾶς ὁ αἰγιαλός.", "st": "3.5.4"}, {"sp": "N", "t": "περὶ δὲ τῆς κτίσεως τῶν Γαδείρων τοιαῦτα λέγοντες μέμνηνται Γαδιτανοὶ χρησμοῦ τινος, ὃν γενέσθαι φασὶ Τυρίοις κελεύοντα ἐπὶ τὰς Ἡρακλέους στήλας ἀποικίαν πέμψαι· τοὺς δὲ πεμφθέντας κατασκοπῆς χάριν, ἐπειδὴ κατὰ τὸν πορθμὸν ἐγένοντο τὸν κατὰ τὴν Κάλπην, νομίσαντας τέρμονας εἶναι τῆς οἰκουμένης καὶ τῆς Ἡρακλέους στρατείας τὰ ἄκρα ποιοῦντα τὸν πορθμόν, ταῦτα δ’ αὐτὰ καὶ στήλας ὀνομάζειν τὸ λόγιον, κατασχεῖν εἴς τι χωρίον ἐντὸς τῶν στενῶν, ἐν ᾧ νῦν ἔστιν ἡ τῶν Ἐξιτανῶν πόλις· ἐνταῦθα δὲ θύσαντας μὴ γενομένων καλῶν τῶν ἱερείων ἀνακάμψαι πάλιν. χρόνῳ δ’ ὕστερον τοὺς πεμφθέντας προελθεῖν ἔξω τοῦ πορθμοῦ περὶ χιλίους καὶ πεντακοσίους σταδίους εἰς νῆσον Ἡρακλέους ἱερὰν κειμένην κατὰ πόλιν Ὀνόβαν τῆς Ἰβηρίας, καὶ νομίσαντας ἐνταῦθα εἶναι τὰς στήλας θῦσαι τῷ θεῷ, μὴ γενομένων δὲ πάλιν καλῶν τῶν ἱερείων ἐπανελθεῖν οἴκαδε. τῷ δὲ τρίτῳ στόλῳ τοὺς ἀφικομένους Γάδειρα κτίσαι καὶ ἱδρύσασθαι τὸ ἱερὸν ἐπὶ τοῖς ἑῴοις τῆς νήσου, τὴν δὲ πόλιν ἐπὶ τοῖς ἑσπερίοις. διὰ δὲ τοῦτο τοὺς μὲν δοκεῖν τὰ ἄκρα τοῦ πορθμοῦ τὰς στήλας εἶναι, τοὺς δὲ τὰ Γάδειρα, τοὺς δ’ ἔτι πορρώτερον τῶν Γαδείρων ἔξω προκεῖσθαι. ἔνιοι δὲ στήλας ὑπέλαβον τὴν Κάλπην καὶ τὴν Ἀβίλυκα, τὸ ἀντικείμενον ὄρος ἐκ τῆς Λιβύης, ὅ φησιν Ἐρατοσθένης ἐν τῷ Μεταγωνίῳ νομαδικῷ ἔθνει ἱδρῦσθαι· οἱ δὲ τὰς πλησίον ἑκατέρου νησῖδας, ὧν τὴν ἑτέραν Ἥρας νῆσον ὀνομάζουσιν. Ἀρτεμίδωρος δὲ τὴν μὲν τῆς Ἥρας νῆσον καὶ ἱερὸν λέγει αὐτῆς, ἄλλην δέ φησιν εἶναί τινα, οὐδ’ Ἀβίλυκα ὄρος οὐδὲ Μεταγώνιον ἔθνος. καὶ τὰς Πλαγκτὰς [δὲ] καὶ τὰς Συμπληγάδας ἐνθάδε μεταφέρουσί τινες, ταύτας εἶναι νομίζοντες στήλας, ἃς Πίνδαρος καλεῖ πύλας Γαδειρίδας, εἰς ταύτας ὑστάτας ἀφῖχθαι φάσκων τὸν Ἡρακλέα. καὶ Δικαίαρχος δὲ καὶ Ἐρατοσθένης καὶ Πολύβιος καὶ οἱ πλεῖστοι τῶν Ἑλλήνων περὶ τὸν πορθμὸν ἀποφαίνουσι τὰς στήλας. οἱ δὲ Ἴβηρες καὶ Λίβυες ἐν Γαδείροις εἶναι φασίν· οὐδὲν γὰρ ἐοικέναι στήλαις τὰ περὶ τὸν πορθμόν. οἱ δὲ τὰς ἐν τῷ Ἡρακλείῳ τῷ ἐν Γαδείροις χαλκᾶς ὀκταπήχεις, ἐν αἷς ἀναγέγραπται τὸ ἀνάλωμα τῆς κατασκευῆς τοῦ ἱεροῦ, ταύτας λέγεσθαί φασιν· ἐφ’ ἃς ἐρχόμενοι οἱ τελέσαντες τὸν πλοῦν καὶ θύοντες τῷ Ἡρακλεῖ διαβοηθῆναι παρεσκεύασαν, ὡς τοῦτ’ εἶναι καὶ γῆς καὶ θαλάττης τὸ πέρας. τοῦτον δ’ εἶναι πιθανώτατον καὶ Ποσειδώνιος ἡγεῖται τὸν λόγον, τὸν δὲ χρησμὸν καὶ τοὺς πολλοὺς ἀποστόλους ψεῦσμα Φοινικικόν. περὶ μὲν οὖν τῶν ἀποστόλων τί ἄν τις διισχυρίσαιτο πρὸς ἔλεγχον ἢ πίστιν, οὐδετέρως παράλογον [ὄν]; τὸ δὲ τὰς νησῖδας ἢ τὰ ὄρη μὴ φάσκειν ἐοικέναι στήλαις, ἀλλὰ ζητεῖν ἐπὶ τῶν κυρίως λεγομένων στηλῶν τοὺς τῆς οἰκουμένης ὅρους ἢ τῆς στρατείας τῆς Ἡρακλέους ἔχει μέν τινα νοῦν· ἔθος γὰρ παλαιὸν ὑπῆρχε τὸ τίθεσθαι τοιούτους ὅρους, καθάπερ οἱ Ῥηγῖνοι τὴν στυλίδα ἔθεσαν τὴν ἐπὶ τῷ πορθμῷ κειμένην, πυργίον τι, καὶ ὁ τοῦ Πελώρου λεγόμενος πύργος ἀντίκειται ταύτῃ τῇ στυλίδι· καὶ οἱ Φιλαίνων λεγόμενοι βωμοὶ κατὰ μέσην που τὴν μεταξὺ τῶν σύρτεων γῆν· καὶ ἐπὶ τῷ ἰσθμῷ τῷ Κορινθιακῷ μνημονεύεται στήλη τις ἱδρυμένη πρότερον, ἣν ἔστησαν κοινῇ οἱ τὴν Ἀττικὴν σὺν τῇ Μεγαρίδι κατασχόντες Ἴωνες ἐξελαθέντες ἐκ τῆς Πελοποννήσου καὶ οἱ κατασχόντες τὴν Πελοπόννησον, ἐπιγράψαντες ἐπὶ μὲν τοῦ πρὸς τῇ Μεγαρίδι μέρους “τάδ’ οὐχὶ Πελοπόννησος ἀλλ’ Ἰωνία,” ἐκ δὲ θατέρου “τάδ’ ἐστὶ Πελοπόννησος οὐκ Ἰωνία.” Ἀλέξανδρος δὲ τῆς Ἰνδικῆς στρατείας ὅρια βωμοὺς ἔθετο ἐν τοῖς τόποις εἰς οὓς ὑστάτους ἀφίκετο τῶν πρὸς ταῖς ἀνατολαῖς Ἰνδῶν, μιμούμενος τὸν Ἡρακλέα καὶ τὸν Διόνυσον. ἦν μὲν δὴ τὸ ἔθος τοῦτο.", "st": "3.5.5"}, {"sp": "N", "t": "Ἀλλὰ καὶ τοὺς τόπους εἰκός ἐστι μεταλαμβάνειν τὴν αὐτὴν προσηγορίαν, καὶ μάλιστα ἐπειδὰν ὁ χρόνος διαφθείρῃ τοὺς τεθέντας ὅρους. οὐ γὰρ νῦν οἱ Φιλαίνων βωμοὶ μένουσιν, ἀλλ’ ὁ τόπος μετείληφε τὴν προσηγορίαν. οὐδὲ ἐν τῇ Ἰνδικῇ στήλας φασὶν ὁραθῆναι κειμένας οὔθ’ Ἡρακλέους οὔτε Διονύσου· καὶ λεγομένων μέντοι καὶ δεικνυμένων τόπων τινῶν οἱ Μακεδόνες ἐπίστευον τούτους εἶναι στήλας, ἐν οἷς τι σημεῖον εὕρισκον ἢ τῶν περὶ τὸν Διόνυσον ἱστορουμένων ἢ τῶν περὶ τὸν Ἡρακλέα. κἀνταῦθα δὴ τοὺς μὲν πρώτους οὐκ ἂν ἀπιστήσαι τις ὅροις χρήσασθαι χειροκμήτοις τισὶ βωμοῖς ἢ πύργοις ἢ στυλίσιν ἐπὶ τῶν τόπων, εἰς οὓς ὑστάτους ἧκον τοὺς ἐπιφανεστάτους (ἐπιφανέστατοι δὲ οἱ πορθμοὶ καὶ τὰ ἐπικείμενα ὄρη καὶ αἱ νησῖδες πρὸς τὸ ἀποδηλοῦν ἐσχατιάς τε καὶ ἀρχὰς τόπων), ἐκλιπόντων δὲ τῶν χειροκμήτων ὑπομνημάτων μετενεχθῆναι τοὔνομα εἰς τοὺς τόπους, εἴτε τὰς νησῖδας τις βούλεται λέγειν εἴτε τὰς ἄκρας τὰς ποιούσας τὸν πορθμόν. τοῦτο γὰρ ἤδη διορίσασθαι χαλεπὸν ποτέροις χρὴ προσάψαι τὴν ἐπίκλησιν, διὰ τὸ ἀμφοτέροις ἐοικέναι τὰς στήλας. λέγω δὲ ἐοικέναι, διότι ἐν τοῖς τοιούτοις ἵδρυνται τόποις, οἳ σαφῶς τὰς ἐσχατιὰς ὑπαγορεύουσι, καθ’ ὃ καὶ στόμα εἴρηται ὁ πορθμὸς καὶ οὗτος καὶ ἄλλοι πλείους· τὸ δὲ στόμα πρὸς μὲν εἴσπλουν ἀρχή ἐστι, πρὸς δὲ ἔκπλουν ἔσχατον. τὰ οὖν ἐπὶ τῷ στόματι νησίδια ἔχοντα τὸ εὐπερίγραφόν τε καὶ σημειῶδες οὐ φαύλως στήλαις ἀπεικάζοι τις ἄν· ὡς δ’ αὕτως καὶ τὰ ὄρη τὰ ἐπικείμενα τῷ πορθμῷ καὶ ἐξοχήν τινα τοιαύτην ἐμφαίνοντα οἵαν αἱ στυλίδες ἢ αἱ στῆλαι. καὶ ὁ Πίνδαρος οὕτως ἂν ὀρθῶς λέγοι πύλας Γαδειρίδας, εἰ ἐπὶ τοῦ στόματος νοοῖντο αἱ στῆλαι· πύλαις γὰρ ἔοικε τὰ στόματα. τὰ δὲ Γάδειρα οὐκ ἐν τοιούτοις ἵδρυται τόποις ὥστε ἀποδηλοῦν ἐσχατιάν, ἀλλ’ ἐν μέσῃ πως κεῖται μεγάλῃ παραλίᾳ κολπώδει. τὸ δὲ ἐπ’ αὐτὰς ἀναφέρειν τὰς ἐν τῷ Ἡρακλείῳ στήλας τῷ ἐνθάδε ἧττον εὔλογον, ὡς ἐμοὶ φαίνεται· οὐ γὰρ ἐμπόρων ἀλλ’ ἡγεμόνων μᾶλλον ἀρξάντων τοῦ ὀνόματος τούτου, κρατῆσαι πιθανὸν τὴν δόξαν, καθάπερ καὶ ἐπὶ τῶν Ἰνδικῶν στηλῶν. ἄλλως τε καὶ ἡ ἐπιγραφὴ ἥν φασιν, οὐκ ἀφίδρυμα ἱερὸν δηλοῦσα ἀλλὰ ἀναλώματος κεφάλαιον, ἀντιμαρτυρεῖ τῷ λόγῳ· τὰς γὰρ Ἡρακλείους στήλας μνημεῖα εἶναι δεῖ τῆς ἐκείνου μεγαλουργίας, οὐ τῆς Φοινίκων δαπάνης.", "st": "3.5.6"}, {"sp": "N", "t": "φησὶ δὲ ὁ Πολύβιος κρήνην ἐν τῷ Ἡρακλείῳ τῷ ἐν Γαδείροις εἶναι πότιμον, βαθμῶν ὀλίγων κατάβασιν ἔχουσαν εἰς τὸ ὕδωρ, ἣν ταῖς παλιρροίαις τῆς θαλάττης ἀντιπαθεῖν, κατὰ μὲν τὰς πλήμας ἐκλείπουσαν κατὰ δὲ τὰς ἀμπώτεις πληρουμένην. αἰτιᾶται δ’ ὅτι τὸ πνεῦμα τὸ ἐκ τοῦ βάθους εἰς τὴν ἐπιφάνειαν τῆς γῆς ἐκπῖπτον, καλυφθείσης μὲν αὐτῆς ὑπὸ τοῦ κύματος κατὰ τὰς ἐπιβάσεις τῆς θαλάττης, εἴργεται τῶν οἰκείων τοιούτων ἐξόδων· ἀναστρέψαν δὲ εἰς τὸ ἐντὸς ἐμφράττει τοὺς τῆς πηγῆς πόρους καὶ ποιεῖ λειψυδρίαν· γυμνωθείσης δὲ πάλιν, εὐθυπορῆσαν ἐλευθεροῖ τὰς φλέβας τῆς πηγῆς ὥστ’ ἀναβλύειν εὐπόρως. Ἀρτεμίδωρος δὲ ἀντειπὼν τούτῳ καὶ ἅμα παρ’ αὑτοῦ τινα θεὶς αἰτίαν, μνησθεὶς δὲ καὶ τῆς Σιλανοῦ δόξης τοῦ συγγραφέως, οὔ μοι δοκεῖ μνήμης ἄξια εἰπεῖν, ὡς ἂν ἰδιώτης περὶ ταῦτα καὶ αὐτὸς καὶ Σιλανός. Ποσειδώνιος δὲ ψευδῆ λέγων τὴν ἱστορίαν εἶναι ταύτην δύο φησὶν εἶναι φρέατα ἐν τῷ Ἡρακλείῳ καὶ τρίτον ἐν τῇ πόλει· τῶν δ’ ἐν τῷ Ἡρακλείῳ τὸ μὲν μικρότερον ὑδρευομένων συνεχῶς αὐθωρὸν καὶ ἐκλείπειν καὶ διαλειπόντων τῆς ὑδρείας πληροῦσθαι πάλιν, τὸ δὲ μεῖζον δι’ ὅλης τῆς ἡμέρας τὴν ὑδρείαν ἔχον, μειούμενον μέντοι, καθάπερ καὶ τἆλλα φρέατα πάντα, νύκτωρ πληροῦσθαι μηκέτι ὑδρευομένων· ἐπειδὴ δὲ συμπίπτει κατὰ τὸν τῆς συμπληρώσεως καιρὸν ἡ ἄμπωτις πολλάκις, πεπιστεῦσθαι κενῶς ὑπὸ τῶν ἐγχωρίων τὴν ἀντιπάθειαν. ὅτι μὲν οὖν ἡ ἱστορία πεπίστευται, καὶ οὗτος εἴρηκε καὶ ἡμεῖς ἐν τοῖς παραδόξοις θρυλουμένην παρειλήφαμεν. ἠκούομεν δὲ καὶ φρέατα εἶναι, τὰ μὲν πρὸ τῆς πόλεως ἐν τοῖς κήποις τὰ δὲ ἐντός, διὰ δὲ τὴν μοχθηρίαν τοῦ ὕδατος κατὰ τὴν πόλιν δεξαμενὰς ἐπιπολάζειν τοῦ λακκαίου ὕδατος· εἰ μέντοι καὶ τούτων τι τῶν φρεάτων ἐπιδείκνυται τὴν τῆς ἀντιπαθείας ὑπόνοιαν, οὐκ ἴσμεν. τὰς δ’ αἰτίας, εἴπερ συμβαίνει ταῦτα οὕτως, ὡς ἐν χαλεποῖς ἀποδέχεσθαι δεῖ. εἰκὸς μὲν γὰρ οὕτως ἔχειν ὡς ὁ Πολύβιός φησιν, εἰκὸς δὲ καὶ τῶν φλεβῶν τινας τῶν πηγαίων νοτισθείσας ἔξωθεν χαυνοῦσθαι καὶ παρέκχυσιν εἰς τὰ πλάγια μᾶλλον διδόναι τοῖς ὕδασιν ἢ ἀναθλίβειν κατὰ τὸ ἀρχαῖον ῥεῖθρον εἰς τὴν κρήνην· νοτίζεσθαι δ’ ἀναγκαῖον ἐπικλύσαντος τοῦ κύματος. εἰ δ’, ὥσπερ Ἀθηνόδωρός φησιν, εἰσπνοῇ τε καὶ ἐκπνοῇ τὸ συμβαῖνον περὶ τὰς πλημμυρίδας καὶ περὶ τὰς ἀμπώτεις ἔοικεν, εἶναι ἄν τινα τῶν ῥεόντων ὑδάτων, ἃ κατ’ ἄλλους μὲν πόρους ἔχει τὴν ἔκρυσιν κατὰ φύσιν εἰς τὴν ἐπιφάνειαν, ὧν δὴ τὰ στόματα πηγὰς καὶ κρήνας καλοῦμεν, κατ’ ἄλλους δὲ πόρους συνέλκεται πρὸς τὸ τῆς θαλάττης βάθος· καὶ συνεξαίροντα μὲν ἐκείνην ὥστε πλημμυρεῖν, ὅταν οἷον ἡ ἐκπνοὴ γίνηται, τὸ οἰκεῖον ἀπολείπει ῥεῖθρον, πάλιν δ’ ἀναχωρεῖ πρὸς τὸ οἰκεῖον ῥεῖθρον, ὅταν κἀκείνη λάβῃ τὴν ἀναχώρησιν.", "st": "3.5.7"}, {"sp": "N", "t": "οὐκ οἶδα δὲ πῶς κατ’ ἄλλα δεινοὺς ἀποφαίνων ὁ Ποσειδώνιος τοὺς Φοίνικας ἐνταῦθα μωρίαν μᾶλλον ἢ δριμύτητα αὐτῶν κατέγνωκεν. ἡμέρα μὲν γὰρ καὶ νὺξ τῇ τοῦ ἡλίου περιφορᾷ μετρεῖται τοτὲ μὲν ὑπὸ γῆς ὄντος τοτὲ δὲ ὑπὲρ γῆς φαινομένου· φησὶ δὲ τὴν τοῦ ὠκεανοῦ κίνησιν ὑπέχειν ἀστροειδῆ περίοδον, τὴν μὲν ἡμερήσιον ἀποδιδοῦσαν, τὴν δὲ μηνιαίαν, τὴν δ’ ἐνιαυσιαίαν συμπαθῶς τῇ σελήνῃ· ὅταν γὰρ αὕτη ζῳδίου μέγεθος ὑπερέχῃ τοῦ ὁρίζοντος, ἄρχεσθαι διοιδεῖν τὴν θάλατταν καὶ ἐπιβαίνειν τῆς γῆς αἰσθητῶς μέχρι μεσουρανήσεως· ἐκκλίναντος δὲ τοῦ ἄστρου, πάλιν ἀναχωρεῖν τὸ πέλαγος κατ’ ὀλίγον ἕως ἂν ζῴδιον ὑπερέχῃ τῆς δύσεως ἡ σελήνη, εἶτα μένειν τοσοῦτον ἐν τῇ αὐτῇ καταστάσει χρόνον ὅσον ἡ σελήνη συνάπτει πρὸς αὐτὴν τὴν δύσιν, καὶ ἔτι μᾶλλον τοσοῦτον ὅσον κινηθεῖσα ὑπὸ γῆς ζῴδιον ἀπόσχοι ἂν τοῦ ὁρίζοντος· εἶτ’ ἐπιβαίνειν πάλιν ἕως τοῦ ὑπὸ γῆν μεσουρανήματος· εἶτ’ ἀναχωρεῖν ἕως ἂν πρὸς τὰς ἀνατολὰς περιχωρήσασα ἡ σελήνη ζῴδιον τοῦ ὁρίζοντος ἀπόσχῃ, μένειν δὲ μέχρι ἂν ζῴδιον ὑπὲρ γῆς μετεωρισθῇ, καὶ πάλιν ἐπιβαίνειν· ταύτην μὲν εἶναι λέγει τὴν ἡμερήσιον περίοδον. τὴν δὲ μηνιαίαν, ὅτι μέγισται μὲν αἱ παλίρροιαι γίνονται περὶ τὰς συνόδους, εἶτα μειοῦνται μέχρι διχοτόμου· πάλιν δ’ αὔξονται μέχρι πανσελήνου, καὶ μειοῦνται πάλιν ἕως διχοτόμου φθινάδος· εἶθ’ ἕως τῶν συνόδων αἱ αὐξήσεις· πλεονάζειν δὲ καὶ χρόνῳ καὶ τάχει τὰς αὐξήσεις. τὰς δ’ ἐνιαυσιαίας παρὰ τῶν ἐν Γαδείροις πυθέσθαι φησί, λεγόντων ὡς κατὰ θερινὰς τροπὰς μάλιστα αὔξοιντο καὶ αἱ ἀναχωρήσεις καὶ αἱ ἐπιβάσεις. εἰκάζει δ’ αὐτὸς ἀπὸ τῶν τροπῶν μειοῦσθαι μὲν ἕως ἰσημερίας, αὔξεσθαι δὲ ἕως χειμερινῶν τροπῶν· εἶτα μειοῦσθαι μέχρι ἐαρινῆς ἰσημερίας· εἶτ’ αὔξεσθαι μέχρι θερινῶν τροπῶν. τῶν δὲ περιόδων τούτων οὐσῶν καθ’ ἑκάστην ἡμέραν καὶ νύκτα, τὸν συνάμφω χρόνον δὶς μὲν ἐπιβαινούσης τῆς θαλάττης δὶς δὲ ἀναχωρούσης, τεταγμένως δὲ καὶ τῶν ἡμερησίων χρόνων καὶ τῶν νυκτερινῶν, πῶς οἷόν τε πολλάκις μὲν συμβαίνειν κατὰ τὰς ἀμπώτεις τὴν πλήρωσιν τοῦ φρέατος, μὴ πολλάκις δὲ τὴν λειψυδρίαν; ἢ πολλάκις μέν, μὴ ἰσάκις δέ; ἢ καὶ ἰσάκις μέν, τοὺς δὲ Γαδειρίτας ταῦτα μὲν μὴ ἱκανοὺς γενέσθαι τηρῆσαι τὰ καθ’ ἡμέραν γινόμενα, τὰς δ’ ἐνιαυσίους περιόδους ἐκ τῶν ἅπαξ συμβαινόντων κατ’ ἔτος τηρῆσαι; ἀλλὰ μὴν ὅτι γε πιστεύει αὐτοῖς, δῆλον ἐξ ὧν καὶ προσεικάζει γίνεσθαι τὰς μειώσεις καὶ πάλιν αὐξήσεις ἀπὸ τροπῶν ἐπὶ τροπάς τε ἑτέρας κἀκεῖθεν πάλιν ἐπανόδους. καὶ μὴν οὐδὲ ἐκεῖνο εἰκός, ὅτι τηρητικοὶ ὄντες τὰ μὲν συμβαίνοντα οὐκ εἶδον, τοῖς δὲ μὴ συμβαίνουσιν ἐπίστευσαν.", "st": "3.5.8"}, {"sp": "N", "t": "φησὶ δ’ οὖν Σέλευκον τὸν ἀπὸ τῆς Ἐρυθρᾶς θαλάττης καὶ ἀνωμαλίαν τινὰ ἐν τούτοις καὶ ὁμαλότητα λέγειν κατὰ τὰς τῶν ζῳδίων διαφοράς· ἐν μὲν γὰρ τοῖς ἰσημερινοῖς ζῳδίοις τῆς σελήνης οὔσης ὁμαλίζειν τὰ πάθη, ἐν δὲ τοῖς τροπικοῖς ἀνωμαλίαν εἶναι καὶ πλήθει καὶ τάχει, τῶν δ’ ἄλλων ἑκάστου κατὰ τοὺς συνεγγισμοὺς εἶναι τὴν ἀναλογίαν. αὐτὸς δὲ κατὰ τὰς θερινὰς τροπὰς περὶ τὴν πανσέληνόν φησιν ἐν τῷ Ἡρακλείῳ γενόμενος τῷ ἐν Γαδείροις πλείους ἡμέρας μὴ δύνασθαι συνεῖναι τὰς ἐνιαυσίους διαφοράς. περὶ μέντοι τὴν σύνοδον ἐκείνου τοῦ μηνὸς τηρῆσαι μεγάλην παραλλαγὴν ἐν Ἰλίπᾳ τῆς τοῦ Βαίτιος ἀνακοπῆς παρὰ τὰς ἔμπροσθεν, ἐν αἷς οὐδὲ ἕως ἡμίσους τὰς ὄχθας ἔβρεχε· τότε δ’ ὑπερχεῖσθαι τὸ ὕδωρ ὥσθ’ ὑδρεύεσθαι τοὺς στρατιώτας αὐτόθι (διέχει δ’ Ἰλίπα τῆς θαλάττης περὶ ἑπτακοσίους σταδίους)· τῶν δ’ ἐπὶ θαλάττῃ πεδίων καὶ ἐπὶ τριάκοντα σταδίους εἰς βάθος καλυπτομένων ὑπὸ τῆς πλημμυρίδος, ὥστε καὶ νήσους ἀπολαμβάνεσθαι, τὸ τῆς κρηπῖδος ὕψος τῆς τε τοῦ νεὼ τοῦ ἐν τῷ Ἡρακλείῳ καὶ τῆς τοῦ χώματος, ὃ τοῦ λιμένος πρόκειται τοῦ ἐν Γαδείροις, οὐδ’ ἐπὶ δέκα πήχεις καλυπτόμενον ἀναμετρῆσαί φησι· κἂν προσθῇ δέ τις τὸ διπλάσιον τούτου κατὰ τὰς γενομένας ποτὲ παραυξήσεις, [οὐδ’] οὕτω παρασχεῖν ἂν τὴν ἔμφασιν, ἣν ἐν τοῖς πεδίοις παρέχεται τὸ μέγεθος τῆς πλημμυρίδος. τοῦτο μὲν δὴ τὸ πάθος κοινὸν ἱστορεῖται κατὰ πᾶσαν τὴν κύκλῳ παρωκεανῖτιν, τὸ δὲ τοῦ Ἴβηρος ποταμοῦ καινὸν καὶ ἴδιόν φησιν οὗτος· πλημμυρεῖν γὰρ ἔσθ’ ὅπου καὶ χωρὶς ὄμβρων καὶ χιόνων, ἐπειδὰν τὰ βόρεια πνεύματα πλεονάσῃ, αἰτίαν δ’ εἶναι τὴν λίμνην δι’ ἧς ῥεῖ· συνεκβάλλεσθαι γὰρ τὸ λιμναῖον ὑπὸ τῶν ἀνέμων.", "st": "3.5.9"}, {"sp": "N", "t": "̔ιστορεῖ δὲ καὶ δένδρον ἐν Γαδείροις ὄζους ἔχον καμπτομένους εἰς ἔδαφος, πολλάκις δὲ φύλλα ξιφοειδῆ πηχυαῖα τὸ μῆκος, πλάτος δὲ τετραδάκτυλα. περὶ δὲ νέαν Καρχηδόνα δένδρον ἐξ ἀκάνθης φλοιὸν ἀφιέναι ἐξ οὗ ὑφάσματα γίνεται κάλλιστα. τῷ μὲν οὖν ἐν Γαδείροις καὶ ἡμεῖς οἴδαμεν ὅμοιον ἐν Αἰγύπτῳ κατὰ τὴν τῶν κλάδων κατάκαμψιν, τοῖς δὲ φύλλοις ἀνόμοιον οὐδὲ καρπὸν ἔχον· τοῦτο δ’ ἔχειν φησί. τὰ δ’ ἀκάνθινα ὑφαίνεται καὶ ἐν Καππαδοκίᾳ, φέρει δ’ οὐ δένδρον τὴν ἄκανθαν ἐξ ἧς ὁ φλοιός, ἀλλὰ χαμαίζηλος ἡ βοτάνη. τῷ δὲ δένδρῳ τῷ ἐν Γαδείροις καὶ τοῦτο προσιστόρηται ὅτι κλάδου μὲν ἀποκλωμένου γάλα ῥεῖ, ῥίζης δὲ τεμνομένης μιλτῶδες ὑγρὸν ἀναφέρεται. τοσαῦτα καὶ περὶ Γαδείρων.", "st": "3.5.10"}, {"sp": "N", "t": "αἱ δὲ Καττιτερίδες δέκα μέν εἰσι, κεῖνται δ’ ἐγγὺς ἀλλήλων πρὸς ἄρκτον ἀπὸ τοῦ τῶν Ἀρτάβρων λιμένος πελάγιαι· μία δ’ αὐτῶν ἔρημός ἐστι, τὰς δ’ ἄλλας οἰκοῦσιν ἄνθρωποι μελάγχλαινοι, ποδήρεις ἐνδεδυκότες τοὺς χιτῶνας, ἐζωσμένοι περὶ τὰ στέρνα, μετὰ ῥάβδων περιπατοῦντες, ὅμοιοι ταῖς τραγικαῖς Ποιναῖς· ζῶσι δ’ ἀπὸ βοσκημάτων νομαδικῶς τὸ πλέον. μέταλλα δὲ ἔχοντες καττιτέρου καὶ μολίβδου κέραμον ἀντὶ τούτων καὶ τῶν δερμάτων διαλλάττονται καὶ ἅλας καὶ χαλκώματα πρὸς τοὺς ἐμπόρους. πρότερον μὲν οὖν Φοίνικες μόνοι τὴν ἐμπορίαν ἔστελλον ταύτην ἐκ τῶν Γαδείρων κρύπτοντες ἅπασι τὸν πλοῦν· τῶν δὲ Ῥωμαίων ἐπακολουθούντων ναυκλήρῳ τινί, ὅπως καὶ αὐτοὶ γνοῖεν τὰ ἐμπόρια, φθόνῳ ὁ ναύκληρος ἑκὼν εἰς τέναγος ἐξέβαλε τὴν ναῦν, ἐπαγαγὼν δ’ εἰς τὸν αὐτὸν ὄλεθρον καὶ τοὺς ἑπομένους αὐτὸς ἐσώθη διὰ ναυαγίου, καὶ ἀπέλαβε δημοσίᾳ τὴν τιμὴν ὧν ἀπέβαλε φορτίων. οἱ Ῥωμαῖοι δὲ ὅμως πειρώμενοι πολλάκις ἐξέμαθον τὸν πλοῦν· ἐπειδὴ δὲ καὶ Πόπλιος Κράσσος διαβὰς ἐπ’ αὐτοὺς ἔγνω τὰ μέταλλα ἐκ μικροῦ βάθους ὀρυττόμενα καὶ τοὺς ἄνδρας εἰρηναίους, ἐκ περιουσίας ἤδη τὴν θάλατταν ἐργάζεσθαι ταύτην τοῖς ἐθέλουσιν ἐπέδειξε καίπερ οὖσαν πλείω τῆς διειργούσης τὴν Βρεττανικήν. καὶ περὶ μὲν Ἰβηρίας καὶ τῶν προκειμένων νήσων ταῦτα.", "st": "3.5.11"}], []);})();
